		\section{Preliminaries}\label{S.Preliminary}
        Our notation regarding first-order logic is standard.
	This section contains preliminaries concerning reduced products, recognizing coordinates, $h$-formulas, ultraproducts of reduced products, and the Feferman--Vaught theorem. We fix a language $\calL$ throughout.   
%	\subsection{Recognizing coordinates}

   \subsection{Reduced products}
	A class of $\mathcal{L}$-structures will often be denoted by~$\fC$. We use the symbols $\Index{I}, \Index{J}$ to denote index sets and the symbols $\Ideal{I},\Ideal{J}$ to denote ideals on those particular indices. We recall that an ideal $\Ideal{I}$ on $\Index{I}$ is a collection of subsets of $\mathbb{I}$ which is downward closed, closed under finite unions, and does not contain $\mathbb{I}$. Given an ideal $\Ideal{I}$ on $\Index{I}$, one constructs the quotient Boolean algebra $\mathcal{P}(\Index{I})/\Ideal{I}$  via the following identification: 
    \[ A\simeq B \ \Leftrightarrow \ A \vartriangle B \in \Ideal{I}. \]
If $\Index{I}$ is an index set, then we let $\Fin(\Index{I})$ denote the ideal of all finite subsets of $\Index{I}$. When there is no possibility of confusion, we simply write $\Fin$ in place of $\Fin(\Index{I})$. We begin by recalling the definition of the reduced product. 
\begin{definition}[Reduced product]
Let $(\mathcal{M}_i)_{i\in \Index{I}}$ be a collection of $\mathcal{L}$-struc\-tu\-res. We let $\prod_{i \in \Index{I}} \mathcal{M}_i/\Ideal{I}$, or more frequently,  $\prod_\Ideal{I}\mathcal{M}_i$, denote the quotient of the product $\prod_{ i \in \Index{I}} \mathcal{M}_i$ by the following equivalence relation: if $(a_i)_i$ and $(b_i)_i$ are in $ \prod_{i \in \Index{I}}\mathcal{M}_i$, then  
	\[ (a_i)_i\simeq (b_i)_i \ \Leftrightarrow \{i\in \Index{I} \mid a_i \neq b_i\} \in \Ideal{I}.\]
        Formally, we let $[(a_i)]_{\Ideal{I}}$ denote the equivalence class of $(a_i)_{i}$. This quotient is naturally equipped with an $\mathcal{L}$-structure. For any $n$-ary relation symbol $R\in \mathcal{L}$ and $[(a^{1}_i)]_{\Ideal{I}},...,[(a^{n}_i)]_{\Ideal{I}}$ in $\prod_\mathcal{I}\mathcal{M}_i$, 
	\[\models R([(a^{1}_i)]_{\Ideal{I}},...,[(a^{n}_i)]_{\Ideal{I}}) ~\Leftrightarrow ~ \{i\in \Index{I} \mid \mathcal{M}_i\models \neg R(a^{1}_i,...,a^{n}_i)\}\in \Ideal{I}, \]
	and for any $n$-ary function symbol $f \in \mathcal{L}$ and  $[(a^{1}_i)]_{\Ideal{I}},...,[(a^{n}_i)]_{\Ideal{I}}$ in $\prod_{\Ideal{I}}\mathcal{M}_{i}$,
	\[f([(a^{1}_i)]_\Ideal{I},...,[(a^{n}_i)]_\Ideal{I})= [f(a^{1}_i,...,a^{n}_i)]_\Ideal{I} .\]
    The structure $\prod_{\mathcal{I}} \mathcal{M}_i$ is called the \emph{reduced product}.
    We often abuse notation and identify elements in $\prod_{\Ideal{I}} \mathcal{M}_i$ with the elements in $\prod_{i \in \Index{I}} \mathcal{M}_i$ when there is no possibility of confusion or error.     
	If all $\cM_i$ are isomorphic to a fixed structure $\cN$, then the reduced product $\prod_\cI \cM_i$ is called a \emph{reduced power} of~$\cN$. 

    We remark that in the case where $\cI=\{\emptyset\}$, the reduced product reduces (!) to the product. 
\end{definition}



%The following conjecture would be, if true, a variant of Theorem 9.4.3 in Hodges:
\begin{definition}
	An ideal $\Ideal{I}$ on an index set $\Index{I}$ is \emph{atomless} if the quotient Boolean algebra $\cP(\Index I)/\Ideal I$ is atomless. By metonymy, we also call a reduced product $\prod_\Ideal{I}\mathcal{M}_i$ \emph{atomless} if $\Ideal{I}$ is atomless.
	% \emph{contains an atom-free ideal} if there is $\Index{J} \subseteq \Index{I}$ such that $\Bool{J}{J}$ is atom-free, where $\Ideal{J}:=\Ideal{I}\cap \mathcal{P}(\Index{J})$.    
\end{definition}

The following example illustrates a situation that we would like to avoid; where information is lost. Settings like the one below can lead to pathological behavior and annoying/unrewarding case work.   
\begin{example}\label{Ex.NotFull}
    Let $\mathcal{L}:=\{ \leq, R\}$ be a language with two binary relation symbols. Notice that both graphs $(G,R)$ and a linear orders $(L,\leq) $ can be viewed as $\mathcal{L}$-structure by interpreting remaining symbol as empty. Fix a non-trivial linear order and a non-trivial graph relation on a set $A$, denoted by $\leq^{A}$ and $R^{A}$ respectively. Now consider the product $\mathcal{M}=\prod_{n \in \mathbb{N}} \mathcal{M}_n$ where each $\mathcal{M}_n$ has universe $A$ and 
    \[\mathcal{M}_n =\begin{cases}
        R^{\mathcal{M}_n} = \emptyset; \hspace{.2cm} \leq^{\mathcal{M}_n} = \leq^{A},  & \text{ if $n$ is even, }\\
        R^{\mathcal{M}_n} = R^{A}; \hspace{.2cm} \leq^{\mathcal{M}_n} = \emptyset,  & \text{ if $n$ is odd. }
    \end{cases}\]
    By the definition of the reduced product (with respect to the empty ideal), both relations in the structure $\mathcal{M}$ are empty, i.e., $R^\mathcal{M}=\leq^\mathcal{M} =\emptyset$.
\end{example}
In order to avoid the pathological situation described in Example~\ref{Ex.NotFull}, we will consider only classes $\fC$ of structures satisfying the following. 

\begin{definition}\label{Def.Full}
    A class $\fC$ of $\mathcal{L}$-structures is called \emph{full} if 
    \begin{enumerate}
        \item For every predicate $P$ in $\mathcal{L}$ and all $\mathcal{M}$ in $\fC$, $P^{\mathcal{M}} \neq \emptyset$. 
        \item Every $\mathcal{M}$ in $\fC$ has at least three elements. 
    \end{enumerate}

%\begin{equation}
%        \tag{$\ddagger$}\label{eq.full}\text{For every predicate $P$ in $\mathcal{L}$ and all $\mathcal{M}\in \fC$,}\ P^\mathcal{M} \neq \emptyset.
%           \end{equation}     and every $\cM\in \fC$ has at least three elements. 
\end{definition}
We remark that there is no issue in assuming that there exist some structure $\mathcal{M}$ in $\fC$ and some $n$-ary predicate $P$ such that $P^{\mathcal{M}}$ is $\mathcal{M}^{n}$.  
Notice that if $\mathcal{L}$ is a functional language, then all classes of $\mathcal{L}$-structures automatically satisfy condition $(1)$ above. 

    \subsection{Recognizing coordinates} Here we recall the definition of recognizing coordinates. Definition~\ref{D.recognizes-coordinates} below is \cite[Definition 2.5 and Definition 2.6]{de2023trivial} (see \S\ref{S.Products} for the variant of this notion for direct products). In order to state the definition, we introduce some notation which will be used throughout the text. 

Assume that $\Ideal{I}$ is an ideal on a set $\Index I$ and $(\mathcal{M}_i)_{i \in \Index{I}}$ is an indexed family of $\mathcal{L}$-structures. Consider the reduced product $\mathcal{M} := \prod_{\Ideal{I}} \mathcal{M}_i$. For 
$S\subseteq \Index I$ we write $\cM\rs S$ for the quotient $(\prod_{i\in S} \mathcal{M}_i)/(\Ideal I\rs S)$ of $\cM$. The quotient map is denoted~$\pi_S$. If $S\in \Bool II$ then  we write $\cM\rs S$ for $(\prod_{i\in \tilde S} \mathcal{M}_i)/(\Ideal I\rs \tilde S)$ and $\pi_S$ for $\pi_{\tilde S}$,  where $\tilde S\subseteq \Index I$ is any set that satisfies  $[\tilde S]_{\Ideal I}=S$. Clearly $\cM\rs S$ does not depend on the choice of representative $\tilde S$ for $S$.  

%This notation will also be used in case $\cI=\{\emptyset\}$, when the reduced product reduces (!) to the product. 





	\begin{definition}\label{D.recognizes-coordinates}
		 An isomorphism $\Phi$ between reduced products $\cM:=\prod_\Ideal{I} \cM_i$ and $\cN:=\prod_\Ideal{J} \cN_j$ is \emph{isomorphically coordinate respecting} if  there is an isomorphism $\alpha\colon \Bool II\to \Bool JJ$ such that for all $S\in \Bool II$ we have a function 
		\[
		\Phi_S\colon \cM\rs S\to \cN \rs \alpha(S),
		\]
		defined by 
		\[
		\Phi_S(\pi_S(a))=\pi_{\alpha(S)}(\Phi(a)), 
		\]
		making the following diagram commute:
		\begin{center}
			\begin{tikzpicture}
				\matrix[row sep=1cm,column sep=1cm]
				{
					& & \node (M1) {$\cM$}; && &\node (M2) {$\cN$};&
					\\
					& & \node (Q1) {$\cM\rs S$}; &&& \node (Q2) {$\cN\rs \alpha(S)$} ;
					\\
				};
				\draw (M1) edge [->] node [above] {$\Phi$} (M2);
				\draw (Q1) edge [->] node [above] {$\Phi_S$} (Q2);
				\draw (M1) edge [->] node [left] {$\pi_S$} (Q1);
				\draw (M2) edge [->] node [right] {$\pi_{\alpha(S)}$} (Q2);
			\end{tikzpicture}
		\end{center}
			A first-order theory $T$ is said to \emph{recognize coordinates} if every isomorphism between reduced products of models of $T$ is isomorphically coordinate respecting. 

		More generally, if $\fC$ is a class of structures of the same language (not necessarily axiomatizable), then $\fC$ is said to \emph{recognize coordinates} if every isomorphism  between arbitrary reduced products of structures from $\fC$ (possibly with repeated structures) is isomorphically coordinate respecting. 

		Moreover, a class $\fC$ is said to \emph{recognize coordinates in $\bbN$} \footnote{ In \cite{de2023trivial}, the notion of ``recognizing coordinates in $\mathbb{N}$" was simply called ``recognizing coordinates". We choose to change the terminology to clarify our presentation.} if every isomorphism  between arbitrary reduced products of the form $\prod_{n\in \bbN} \cM_n/\Ideal I$ of structures from $\fC$ (again, possibly with repeated structures) is isomorphically coordinate respecting. 
        In \Cref{T.eq}, we will show in particular that this distinction is superfluous and that a class recognizes coordinates in $\bbN$ if and only if it recognizing coordinates.  
	\end{definition}


	    \subsection{h-formulas}\label{S.h-formulas}

	In this section we first recall the definition of an $h$-formula. We then recall some analysis of $h$-formulas in reduced products by Palmgren and Omarov. Finally, we conclude with some analysis of our own concerning $h$-formulas and \emph{definable support functions}. We prove that a full class of structures admits such functions if and only if a certain formula (involving only logical symbols and equality) is equivalent to an $h$-formula. The following definition is taken from \cite{palmgren}, \cite{palyutin1}, \cite{palyutin2} (see \cite[\S 2]{de2024saturation}). 

	\begin{definition}[The class of $h$-formulas] \label{Def.h-formulas} 
		The class of \emph{$h$-formulas} is the smallest class of formulas $\mathcal C$ containing all atomic formulas and if $\varphi$ and~$\psi$ belong to $\mathcal C$, then so do
		\[
		\varphi\wedge\psi,\,\,(\exists x)\varphi,\,\,(\forall x)\varphi,\text{ and }(\exists x)\varphi\wedge (\forall x)(\varphi\rightarrow\psi).
		\]
        \end{definition}

It is not difficult to see that  the class of formulas that contains all atomic formulas and is closed under the construct $(\exists x)\varphi\wedge(\forall x)(\varphi\rightarrow\psi)$ coincides with the class of $h$-formulas. 
The following fact will be used tacitly and frequently without being explicitly mentioned. 

\begin{fact} If a theory $T$ implies  $(\exists x)\varphi$ then $T$ implies that  $(\forall x)(\varphi\to \psi)$ is equivalent to an $h$-formula. \qed
\end{fact}

In the situation described by the fact above, we will slightly abuse terminology and say that the formula $(\forall x)(\varphi\to \psi)$ is an $h$-formula. The following is an analog of \L o\' s's theorem for reduced products (see \cite{palyutin2} for details). 

	\begin{theorem}\label{T.Palyutin}
		If $\cI$ is an ideal on an index set $\mathbb{I}$, $(\mathcal{M}_i)_{i \in \mathbb{I}}$ is an indexed family of $\mathcal{L}$-structures, $\mathcal{M}=\prod_i \mathcal{M}_i/\cI$, $\bar{a}$ is an element of  $\mathcal{M}^{\bar{x}}$ with representative $(\bar{a}_i)$, and $\varphi(\bar x)$ is an $h$-formula, then
		\begin{align*}
			\mathcal{M}&\models \varphi(\bar a)\text{ if and only if } \{i\in \mathbb{I} \mid \mathcal{M}_i\models \neg \varphi(\bar a_i)\}\in \cI.
		\end{align*}
%		where $\pi\colon\prod_i\mathcal{M}_{i \in \mathbb{I}} \to \mathcal{M}$ denotes the quotient map.
	\end{theorem}

    Proposition~\ref{lemma:Palmgren} below is a uniform version of \cite[Lemma 3]{palmgren}. There it was credited to Palyutin. It is a consequence of \cite[Lemma 2]{palmgren} which implies that every atomless reduced product satisfies the so-called simple cover property (a relative to the conclusion of  McKinsey's Lemma, \cite[Lemma 9.1.7]{Hodg:Model}). 

			\begin{proposition}\label{lemma:Palmgren}
				For every $\mathcal{L}$-formula $\phi(\bar{x})$, there is a Boolean combination of $h$-formulas $\psi(\bar{x})$ such that 
				\[(\forall \bar{x})~ (\phi(\bar{x}) \leftrightarrow \psi(\bar{x})),\]
				holds in all atomless reduced products.\qed 
			\end{proposition}

			The following proposition is a direct consequence of \cite[Lemma 4]{Oma91}. 
			\begin{proposition}[Omarov]\label{Prop:Omarov}
				Let $\fC$ a class of $\mathcal{L}$-structure and let $\phi(\bar{x})$ be a satisfiable $\mathcal{L}$-formula with the following property: there is an $\mathcal{L}$-formula $\psi(\bar{x})$ such that for all atomless reduced products $\mathcal{M}=\prod_\Ideal{I}\mathcal{M}_i$ of structures from $\fC$ and for all $\bar{a} \in \prod_\Ideal{I}\mathcal{M}_i$, \begin{equation}\label{eq.Omarov}
					\prod_\Ideal{I}\mathcal{M}_i\models \phi(\bar{a}) \Leftrightarrow \{i \in \Index{I} \mid \mathcal{M}_i\models\neg \psi(\bar{a}_i)\} \in \Ideal{I}.
					\end{equation}
					\begin{enumerate}
						\item \label{1.Omarov} Then $\phi(\bar{x})$ is equivalent to an $h$-formula $\Phi(\bar{x})$ in the common theory of all atomless reduced product from $\fC$.
						\item \label{2.Omarov} Also, $\Phi(\bar{x})$ and $\psi(\bar{x})$ are equivalent in $\mathcal{M}_i$ for all but $\Ideal{I}$-many $i$. 
					\end{enumerate}
            \end{proposition}

