            We now connect the syntax of $h$-formulas with the semantics of reduced products. The \emph{comparison formulas} from the previous proposition corresponds to certain kinds of support functions. The \emph{relative support function of} $\prod_\Ideal{I}\mathcal{M}_i$, denoted $\supp_=$,  is the map which associates to two elements $a$ and $b$ with representations $(a_i)_i$ and $(b_i)_i$, the element of $\Bool{I}{I}$ where these two elements coincide: 
    \[
    ((a_i)_i,(b_i)_i) \buildrel{\supp_=}\over\longmapsto [\{ i \mid a_i=b_i\}]_\Ideal{I}.  
    \]
    Intuitively, by the variant of \strokeL o\'s's theorem for reduced products, the definability of the \emph{relative support function} in all reduced products should be an intrinsic property of the class of structures. This is what we show in \Cref{lemma:RecognizingCoordinateEquivalence} and \Cref{T.InterpretingSupport} below. 


			\begin{lemma} \label{lemma:RecognizingCoordinateEquivalence}
				Let $\Index{I}$ be an indexed set, $\Ideal{I}$ be an ideal on $\Index{I}$, and $(\mathcal{M}_i)_{i \in \Index{I}}$ be an indexed family of $\mathcal{L}$-structures. Then the following Condition (\ref{item:RCE1}) implies Condition (\ref{item:RCE2}). 

				%    For all atomless ideals, the Conditions \ref{item:RCE1} and \ref{item:RCE2} are equivalent.
				\begin{enumerate}
					\item\label{item:RCE1} The formula,     \[ x=x' \rightarrow y=y',\]
					is equivalent to an $h$-formula $\Phi(x,x',y,y')$ in $\Th_\Ideal{I}(\mathcal{M}_i, i\in \mathbb{I})$.
					\item\label{item:RCE2} The Boolean algebra $\Bool{I}{I}$ and the relative support function,
                    \[\supp_=: \prod_\Ideal{I} \mathcal{M}_i \rightarrow \Bool{I}{I} \text{ via } 
                     ((g_i)_i, (g_i')_i) \rightarrow [\{ i \in \Index{I} \mid  g_i \neq g_i'\}]_\Ideal{I},\] 
                    are interpretable in $\prod_\Ideal{I} \mathcal{M}_i$. 
				\end{enumerate}
			\end{lemma}
			\begin{proof}
            Assume Condition \eqref{item:RCE1}. Fix $a,a',b$, and $b'$ in  $\prod_\Ideal{I} \mathcal{M}_i$ with representatives $(a_i)_{i},(b_i)_{i},(a'_i)_{i},$ and $(b'_i)_{i}$ respectively. Then,
				\begin{align*}
					\supp_=(a,a') \subseteq \supp_=(b,b') & \Leftrightarrow  \{i \in \Index{I} \mid a_i \neq a_i' \wedge b_i = b_i'\} \in \Ideal{I}\\
					& \Leftrightarrow  \{i \in \Index{I}  \mid \neg (a_i = a_i' \rightarrow b_i = b_i')\} \in \Ideal{I}\\
					&  \Leftrightarrow  \{i \in \Index{I}  \mid \mathcal{M}_i \models \neg \Phi(a_i,a_i',b_i,b_i')\} \in \Ideal{I} \\
					& \Leftrightarrow   \prod_\Ideal{I} \mathcal{M}_i \models \Phi(a,a',b,b').
				\end{align*}
				It follows that $\Bool{I}{I}$ is interpretable as a poset, and therefore it is interpretable as a Boolean algebra.  The natural projection is the relative support function, therefore Condition (\ref{item:RCE2}) holds.
			\end{proof}
			\begin{theorem}\label{T.InterpretingSupport}
				Let $\fC$ be a full class of $\mathcal{L}$-structures. 
				The following conditions are equivalent: 
				\begin{enumerate}
					\item The relative support function $\supp_=$ is interpretable in all reduced products of structures from $\fC$.
					\item The relative support function $\supp_=$ is interpretable in all atomless reduced products of structures from $\fC$. 
					\item The formula $x=x' \rightarrow y=y'$ is equivalent to an $h$-formula in the common theory $\Th(\fC)$ of $\fC$.  
				\end{enumerate} 
			\end{theorem}

		The proof of the above theorem uses the following lemma. We recall that $\Fin(\Index I)$ is the atomless ideal of all finite subsets of $\Index I$. 
			\begin{lemma}\label{lemma:TheoryClass}
				For every class $\fC$ of $\mathcal{L}$-structures, there is an index set $\Index I$ and a family of $\mathcal{L}$-structures from $\fC$, $(\mathcal{M}_i)_{i \in \Index{I}}$, such that $\Th_{\Fin(\Index I)}(\cM_i)=\Th(\fC)$. 
			\end{lemma}

			\begin{proof}
				Let $\Index I_0$ be the set of all $\calL$-sentences  that do not belong to $\Th(\fC)$.  Let $\Index I=\Index I_0\times \bbN$ and  for each $i\in \bbN$ choose $\cM_{\varphi,i}\in \fC$ that does not satisfy $\varphi$. Then for every finite $S\subseteq \Index I$ and every $\varphi\notin \Th(\fC)$ we have that $(\varphi,i)\notin S$ for all large enough $i$, therefore $\Th_{\Fin(\Index I)}(\cM_{(\varphi,i)})\subseteq \Th(\fC)$. Since every $\cM_{(\varphi,i)}$ belongs to $\fC$, the reverse inclusion is automatic.   \end{proof}

			\begin{proof}[Proof of Theorem~\ref{T.InterpretingSupport}]
				The implication $(1)\Rightarrow (2)$ is obvious and $(3)\Rightarrow (1)$ follows from ~\Cref{lemma:RecognizingCoordinateEquivalence}.
				It remains to show that $(2)$ implies $(3)$. Assume that $(2)$ holds and consider $\prod_{\Ideal{I}}\mathcal{M}_i$ where the index set $\Index I$ and the ideal $\Ideal{I}=\Fin(\Index I)$ are as in \Cref{lemma:TheoryClass}. Let $\phi(x,x',y,y')$ be the $\mathcal{L}$-formula defining the relation $\supp_=(a,a') \subseteq \supp_=(b,b')$ in $\prod_\Ideal{I} \mathcal{M}_i$. It follows that for all $a,a',b,b' \in \prod_\Ideal{I} \mathcal{M}_i$, with respective representatives $(a_i)_i,(a'_i)_i,(b_i)_i,(b'_i)_i$:

				\[\prod_\Ideal{I} \mathcal{M}_i \models \phi(a,a',b,b') \Leftrightarrow \{i \in \Index{I} \mid \neg (a_i = a_i' \rightarrow b_i = b_i')\} \in \Ideal{I}.\]
				By \Cref{Prop:Omarov}(1), $\phi(x,x',y,y')$ is equivalent to an $h$-formula $\Phi(x,x',y,y')$ in $\prod_\Ideal{I} \mathcal{M}_i$, and by Theorem~\ref{T.Palyutin} we have, 
                \[ \prod_\Ideal{I} \mathcal{M}_i \models \Phi(a,a',b,b') \Leftrightarrow \{i \in \Index{I} \mid \neg \Phi(a_i,a_i',b_i,b_i')\} \in \Ideal{I}.\]
                By \Cref{Prop:Omarov}(2), we have for all but  $\Ideal{I}$-many $i\in \Index{I}:$ 
                \[\mathcal{M}_i \models \forall x,x',y,y'~\left(\Phi(x,x',y,y') \leftrightarrow (x=x'\rightarrow y=y')\right).\]
                Since $\Th_{\Fin(\Index I)}(\cM_i)=\Th(\fC)$, we have the equivalence in $\Th(\fC)$, as required, and this concludes the proof.
                \end{proof} 

