	\begin{proof}
		We first observe that the sort,
        \[
        B:= (\Bool{I}{I};\cap ,\cup, 0, 1, \{c_\theta : \theta \text{ an } \mathcal{L}\text{- sentence} \} ),
        \]
        is \emph{closed} in the following sense: in the language, there are neither functions from $B$ to the main sort $\mathcal{M}$, nor predicates in $B^n\times \mathcal{M}^m$ for strictly positive integers $n,m$. Any (parameter-free) $\mathcal{L}^{+}$-formula is equivalent, in the theory of the reduced product, to a Boolean combination of formulas of the form:
		\begin{itemize}
			\item $\psi_B(\supp_{\phi}(\Bar{x}))$
			\item $\phi(\Bar{x})$
		\end{itemize}
		where $\phi$ is an $\mathcal{L}$-formula, and $\psi_B$ is a formula  in the language $\mathcal{L}_{\textrm{Bool}} \cup \{c_\theta: \theta \text{ an } \mathcal{L}\text{-sentence} \}$.
		By \cite[Theorem 6.3.2]{CK90}, a formula of the second kind can be expressed as a formula of the first kind. Therefore, we have eliminated all quantifiers in the main sort $\prod_\Ideal{I} \mathcal{M}_i$. Since the sort is closed, relative quantifier elimination follows by \cite[Remark A.8]{Rid17}. %The `furthermore´ statement follows from Tarski's classical result of quantifier eliminations in Boolean algebras \cite{Tar49}. 
	\end{proof}


	This language for quantifier elimination can sometimes be optimized by using the notion of a \emph{fundamental} set of formula. 

	\begin{definition}\label{D.Fundamehtal}
	We call a set $\Phi$ of $\mathcal{L}$-formulas  \emph{fundamental} for the pair $(\mathcal{M}_i)_{i \in \Index{I}}$ and $\Ideal{I}$ if every $\mathcal{L}$-formula is equivalent, in $\Th_{\cI}(\mathcal{M}_i)$, to a Boolean combination of formulas in $\Phi$.
	\end{definition}

 The following (easy) proposition implies that we may obtain quantifier elimination in a fragment of $\mathcal{L}^{+}$ which contains the support functions $\supp_\phi$ where $\phi$ ranges over a fundamental set $\Phi$. 

	\begin{proposition}\label{P.boolfund}
		Let $\phi(\bar{x})$ and $\psi(\bar{x})$ be two $\mathcal{L}$-formula. Then every $\bar{a}$ in $ \left(\prod_\Ideal{I}\mathcal{M}_i\right)^{|\bar{x}|}$ satisfies the following: 
\begin{align*}
		\supp_{\neg\phi}(\bar{a})& = \supp_{\phi}(\bar{a})^\complement,\\
\supp_{\phi\wedge\psi}(\bar{a})&=\supp_\phi(\bar{a})\cap\supp_\psi(\bar{a}),\\
\supp_{\phi\vee\psi}(\bar{a})&=\supp_\phi(\bar{a})\cup\supp_\psi(\bar{a}). 
\end{align*}
	\end{proposition}



\begin{corollary}\label{C.FV.reduced} If $\Phi$ is a fundamental set of $\mathcal{L}$-formulas for the pair $(\mathcal{M}_i)_{i \in \Index{I}}$ and $\Ideal{I}$ then 
	the reduced product $\mathcal{M}\coloneqq \prod_\Ideal{I} \mathcal{M}_i$ eliminates quantifiers relative to  $\Bool{I}{I}$ in the following two-sorted language $\mathcal{L}^+_\Phi$: 
	\[
	\mathcal{L}\cup \left\{\supp_{\phi(\bar{x})} : \phi(\bar{x})\in \Phi \right\} \cup \mathcal{L}_{\textrm{Bool}}\cup \{c_\theta : \theta\in \Phi \text{ is a sentence} \}.
	\]
\end{corollary}
\begin{proof}
It is enough to show that every function of the form $\supp_{\psi(\bar x)}$, where $\psi(\bar x)$ is any $\mathcal{L}$-formula, is equivalent to a quantifier-free $\mathcal{L}^+_\Phi$-formula.
    Fix an $\mathcal{L}$-formula $\psi(\bar x)$. By assumption, $\psi(\bar x)$ is equivalent to a Boolean combination of formulas from $\Phi$, say $\phi_1(\bar x),\dots,\phi_k(\bar x)$. By \Cref{P.boolfund}, $\supp_{\psi(\bar x)}$ is the same Boolean combination of $\supp_{\phi_i(\bar x)}$, $i\leq k$. Therefore, it is expressed without quantifiers in the language $\mathcal{L}^+_\Phi$, as desired.    
\end{proof}

A priori, the language $\mathcal{L}^{+}$ in the Feferman--Vaught theorem can be much larger than the language needed for quantifier elimination. However, it can also be already definable in our original language. Thus the following question naturally arises:

    \begin{question}
        For which indexed families of $\mathcal{L}$-structures $(\mathcal{M}_i)_{i \in \mathbb{I}}$ and ideals $\mathcal{I}$ on $\mathbb{I}$ does the reduced product $\prod_\Ideal{I} \mathcal{M}_i$ interprets the Boolean algebra $\Bool{I}{I}$ and the support functions $\supp_{\phi(\bar{x})}$ in the language $\mathcal{L}$? In other word, in which reduced products is the language $\mathcal{L}^+$ a definable expansion of the language $\mathcal{L}$?
    \end{question}
    We provide a positive answer to the question above if our reduced product satisfies two conditions: (1) the relative support function is interpretable and (2) there exists a fundamental set of $h$-formulas. We recall that if $\mathcal{M}$ is an atomless reduced product, then it admits a fundamental set of $h$-formulas (i.e., \Cref{lemma:Palmgren}). \Cref{lemma:PhiSupport} and \Cref{C.QuestionDecomp.1} provide the details. 

\begin{lemma}\label{lemma:PhiSupport}
	Fix an index set $\Index{I}$, and ideal $\Ideal{I}$ on $\Index{I}$ and a family of $\mathcal{L}$-structures $(\mathcal{M}_i)_{i \in \Index{I}}$. Assume that the reduced product $\prod_\Ideal{I} \mathcal{M}_i$ interprets the Boolean algebra $\Bool{I}{I}$ and the relative support function:
	\[\supp_= \colon (a_i)_i,(b_i)_i \mapsto [\{ i \mid a_i=b_i\}]_\Ideal{I}.\]
	Then, for every satisfiable $h$-formula $\phi(\bar x)$, the $\phi$-support function $\supp_{\phi(\bar{x})}$ is interpretable in $\prod_\Ideal{I} \mathcal{M}_i$. 
\end{lemma}
\begin{proof} We may assume that $\bar x$ is a single variable, as the proof changes only notationally. 
	Fix $b\in \prod_\Ideal{I} \mathcal{M}_i$ satisfying $\phi(x)$. For every element $a \in \prod_\Ideal{I} \mathcal{M}_i$ and $S\in \Bool{I}{I}$, there is a unique element $a_S$ which coincides with $a$ on $S$ and with $b$ on $S^\complement$. Formally, $a_S$ is the unique element such that:
	\begin{itemize}
		\item $\supp_=(a_S,a) \supseteq S$,
		\item $\supp_=(a_S,b) \supseteq S^\complement$.
	\end{itemize}
	This is because $\phi(a_S)$ holds if and only if $\cM_i\models \phi(a_S(i))$ for all but $\cI$-many $i$, and this is equivalent to $S\setminus [\![ a]\!]_{\phi(x)}\in \cI$. 
	Therefore $[\![ a]\!]_{\phi(x)}$ is the largest $S \in \Bool{I}{I} $ with respect to the inclusion such that $\phi(a_S)$ holds. Since $S$ does not depend on the choice of $b$, we get that the $\phi$-support function $\supp_{\phi(x)}$ is interpretable without parameters.
\end{proof}

We can now prove Theorem~\ref{C.QuestionDecomp}.


	\begin{theorem}\label{C.QuestionDecomp.1}		    Assume that a reduced product $\mathcal{M}:=\prod_\Ideal{I} \mathcal{M}_i$ interprets the relative support function $\supp_=$. Assume that there exists $\Phi$ a fundamental set of $h$-formulas for  the pair $(\mathcal{M}_i)_{i \in \Index{I}}$ and $\Ideal{I}$. Then $\mathcal{M}$, as an $\mathcal{L}$-structure, already interprets all functions of the language $\calL^+$ and $\mathcal{M}$ eliminates quantifiers relative to $\Bool{I}{I}$ in the language $\calL_\Phi^+$.
	\end{theorem}
    \begin{proof} We fix an interpretation of the Boolean algebra $\Bool{I}{I}$ and of the map $\supp_=$.
    By \Cref{lemma:PhiSupport}, for any $h$-formula $\phi(x)$ the function $\supp_{\phi(\bar{x})}$ is definable in the language,  \[
	\mathcal{L} \cup \mathcal{L}_{\textrm{Bool}}\cup \left\{\supp_{=}\right\}.
	\]
    Relative quantifier elimination follows directly from \Cref{C.FV.reduced}.
    \end{proof}



    \section{Proof of Theorem \ref{T.A}}




        %In \cite[\S 2.2]{de2023trivial} it was conjectured that the `right' proof of recognition of coordinates should follow from model-theoretical considerations. It turns out that indeed one may formulate a simple characterization, using the relative support function.
  %  In particular, we see that any coordinate respecting isomorphism respects the relative support function. 
    %This confirms the conjecture from \cite[\S 2.2]{de2023trivial}. This characterization is proven in these section. The result are then gathered in   \Cref{T.eq}. 


As mentioned in the introduction, in \cite[\S 2.2]{de2023trivial} it was pointed out that 
    from the model-theoretic point of view, a \emph{morally} satisfactory proof that a theory recognizes coordinates would proceed by exhibiting a copy of $\cP(\bbN)/\cI$ as well as the projections $\pi_S$, for $S\in \Bool {\bbN} \cI$ inside every reduced product $\prod_{\Fin} \cM_n$ of models of $T$. In this section, we prove that a theory recognizes coordinates if and only if every reduced product interprets both the appropriate Boolean algebra along with the appropriate coordinate projections. Moreover, we prove that recognizing coordinates is equivalent to a simple characterization using the relative support function. This section provides much of substance of the proof of \Cref{T.A}. We gather the results together at the end of the section (see \Cref{T.eq}).

    \subsection{Interpreting supports implies recognizing coordinates}
    We show in this subsection that if all reduced products from a class of structures interpret the relative support function, then said class recognizes coordinates. The proof breaks nicely into two steps: (1) if a reduced product $\prod_\cI \mathcal{M}_i$ interprets the relative support function, then it also (uniformly) interprets the quotient structures $\prod_\cI \mathcal{M}_i\restriction S$ for any $S \in \Bool{I}{I}$ and (2) if all reduced products from a class of structures interpret the appropriate Boolean algebra and quotients (coherently), then the class recognizes coordinates. We prove Step (1) and then Step (2). 

    Consider  a reduced product $\mathcal{M}:=\prod_\cI \mathcal{M}_i$ and nonzero $S \in \Bool{I}{I}$, with a representative $\Index{S}\subseteq \Index{I}$. Then  $\Ideal{I}$ induces the ideal $\Ideal{I}_S:=\{\Index{S} \cap J \mid J \in \Ideal{I}\}$ on~$\Index{S}$ and $\mathcal{M} \restriction S$ denotes the reduced product $\prod_{\Ideal{I}_S} \mathcal{M}_i$. We let $a\rs S$ denote the natural projection of an element $a$ of $\mathcal{M}$ to $\mathcal{M} \restriction S$. 

    We first show Step (1), i.e., interpreting the relative support function implies that the relevant family of substructures is also interpretable. 
	\begin{lemma}\label{Claim.RestrictionInterpretable}
		Fix a full (Definition~\ref{Def.Full} class $\fC$, an indexing set $\Index{I}$, an ideal $\Ideal{I}$ on $\Index{I}$, and a sequence of $\mathcal{L}$ structures $(\cM_i)_{i \in \Index{I}}$ from $\fC$. Consider the reduced product $\mathcal{M}:=\prod_\Ideal{I} \mathcal{M}_i$, and assume that   
	$\mathcal{M}$ interprets the Boolean algebra $\Bool{I}{I}$ and the relative support function:
	\[\supp_= \colon (a_i)_i,(b_i)_i \mapsto [\{ i \mid a_i=b_i\}]_\Ideal{I}.\]
        Then both the restriction $\mathcal{M} \restriction S$, with its natural $\mathcal{L}$-structure, and the natural projection $\pi_S: \mathcal{M} \rightarrow \mathcal{M} \restriction S$ via  $a\mapsto a\restriction S$ are (uniformly) interpretable with parameter $S$. 
	\end{lemma}

	\begin{proof}
		We first recover the base set of $\mathcal{M} \restriction S$ as the quotient of $\mathcal{M}$ by the equivalence relation $\simeq$ given by: for all $a,b \in \mathcal{M}$, 
		\[a\simeq b  \Leftrightarrow \supp_=(a,b) \supseteq S.\]
		It remains to interpret the $\mathcal{L}$-structure of $\mathcal{M} \restriction S$. Let $R$ be a predicate in~$\mathcal{L}$. Since $\fC$ is full, $R$ is a satisfiable $h$-formula. By \Cref{lemma:PhiSupport}, the support function $\supp_{R(\bar{x})}$ is interpretable in $\mathcal{M}$. Then, for any $\bar{a}\restriction S$ in  $\left(\mathcal{M}\restriction S\right)^{|\bar{x}|}$, we have that $\mathcal{M}\restriction S \models R( \bar{a}\restriction S )$  if and only if $\supp_{R(\bar{x})} (\bar{a}) \supseteq S$.
		The interpretations of function symbols $f$ from $\mathcal{L}$ in $\mathcal{M}\restriction S$ are also straightforward. For any $\bar{a}\restriction{S}\in \left(\mathcal{M}\restriction S\right)^{|\bar{x}|}$, set 
        \begin{equation*}f(\bar{a}\restriction{S})=f(\bar{a})\restriction{S}. \qedhere
        \end{equation*}
	\end{proof}

    \begin{lemma}\label{lemma:equiv} Let $\Index{I}$ be an indexing set, $(\mathcal{M}_{i})_{i \in \mathcal{I}}$ be an indexed family of $\mathcal{L}$-structures, and $\mathcal{I}$ an ideal on $\Index{I}$. Then the following are equivalent: 
\begin{enumerate}
    \item The formula $\phi(x,x',y,y') := \supp_{=}(x,x') \subseteq \supp_{=}(y,y')$ is a $\emptyset$-definable subset of $\mathcal{M}^{4}$. 
    \item The Boolean algebra $(\mathcal{P}(\Index{I})/\mathcal{I},\subseteq)$ and the relative support function $\supp_{=}: \mathcal{M}^{2} \to \mathcal{P}(\Index{I})/\mathcal{I}$ is interpretable in $\mathcal{M}$. 
\end{enumerate}
\end{lemma}

\begin{proof} $(1) \to (2)$. Suppose that $\phi(x,x',y,y')$ is a definable set. Consider the equivalence relation given by $E := \phi(x,x',y,y') \cap \phi(y,y',x,x')$. Then $\mathcal{M}^{2}/E$ is naturally isomorphic to $\Bool{I}{I}$. Let $\pi_{E}:\mathcal{M}^{2} \to \mathcal{M}^{2}/E$ be the quotient map. Notice that if $S, T \in \Bool{I}{I}$ then $S \subseteq T$ if and only if $\exists a,b,c,d$ in $\mathcal{M}$ such that $\pi_{E}(a,b) = S$, $\pi_{E}(c,d) = T$ and $\phi(a,b,c,d)$. Hence the relation $\subseteq$ is interpretable. Notice that $\pi_{E} = \supp_{=}$ which concludes this direction.   

$(2) \to (1)$. By construction, the set $\phi(x,x',y,y')$ is a definable subset of $\mathcal{M}^{4}$ in $\mathcal{M}^{\eq}$. Since there are no new definable subsets of $\mathcal{M}^{n}$ in $\mathcal{M}^{\eq}$, we see that $\phi(x,x',y,y')$ is already definable in $M$. 
\end{proof}



\begin{lemma}\label{L.RecognizingCoordinates} Let $\fC$ be a full class (see Definition~\ref{Def.Full}) of $\mathcal{L}$-structures. Suppose there exists an $\mathcal{L}$-formula $\phi(x,x',y,y')$ such that for any reduced product $\mathcal{M} := \prod_{i \in \Index{I}} \mathcal{M}_i/\mathcal{I}$ from the class $\fC$, 
\begin{equation*}
\mathcal{M} \models \phi(a,b,c,d) \Longleftrightarrow \supp_{=}(a,b) \subseteq \supp_{=}(c,d).
\end{equation*}
Then the class $\fC$ recognizes coordinates. 
\end{lemma}
\begin{proof}
Assume that  $\mathcal{M}= \prod_\Ideal{I}\mathcal{M}_i$ and $\mathcal{N}=\prod_\Ideal{J}\mathcal{N}_j$ are reduced products of structures from $\fC$ and let $\Phi\colon \mathcal{M}\to \mathcal{N}$ be an isomorphism. Then $\Phi$ extends to an isomorphism $\mathcal{M}^{\eq}\rightarrow \mathcal{N}^{\eq}$ and by \Cref{lemma:equiv}, it induces an isomorphism $\alpha: \Bool{I}{I} \rightarrow \Bool{J}{J}$. Then, we can name the parameter $S$, and $\Phi$ gives rise to an isomorphism between $\cM\rs S$ and $\cN \rs{\alpha(S)}$ by \Cref{Claim.RestrictionInterpretable}. %It extends to an isomorphism $\mathcal{M}_S^{\eq} \rightarrow \mathcal{N}_{\alpha(S)}^{\eq}$
    Hence the following diagram commutes

	\begin{center}
		\begin{tikzpicture}
			\matrix[row sep=1cm,column sep=1cm]
			{
				& & \node (M1) {$\cM$}; && &\node (M2) {$\cN$};&
				\\
				& & \node (Q1) {$\cM\rs S$}; &&& \node (Q2) {$\cN \rs {\alpha(S)}$} ;
				\\
			};
			\draw (M1) edge [->] node [above] {$\Phi$} (M2);
			\draw (Q1) edge [->] node [above] {$\Phi_S$} (Q2);
			\draw (M1) edge [->] node [left] {$\pi_S$} (Q1);
			\draw (M2) edge [->] node [right] {$\pi_{\alpha(S)}$} (Q2);
		\end{tikzpicture}
	\end{center}
	This shows that $\fC$ recognizes coordinates.
\end{proof}

\begin{remark}
Uniformity comes for free: assume otherwise, that for all formulas $\varphi(x, x', y, y')$, there is a reduced product $\prod_{I_\varphi} \mathcal{M}_i$ where $\supp_=(x, x') \subseteq \supp_=(y, y')$ is not equivalent to $\varphi(x, x', y, y')$. Then $\supp_=(x, x') \subseteq \supp_=(y, y')$ is not $\emptyset$-definable in the reduced product $\prod_{I} M_i$, where $\Ideal{I} \coloneq\bigoplus_\varphi I_\varphi$.
\end{remark}


