\begin{proposition}\label{P.2}
	Suppose that $T$ is a theory of (nontrivial) groups and that for $m\geq 1$ and  $n\geq 1$, $T$ includes an axiom asserting the following: 
	\begin{enumerate}
		\item \label{1.P.1}For all $a,b$ in $G\setminus\{e\}$ of order dividing $m$ there is some $c$ in $a^G$ such that $bc\neq cb$. 
		\item\label{2.P.1} Every $c$ in $G$ is the product of at most $n$ elements, each one of which has order dividing $m$.   
	\end{enumerate}
	Then $T$ recognizes coordinates
\end{proposition}

\begin{proof}
We proceed as in the proof of Theorem~\ref{T.RecognizingCoordinates}.
We will show that modulo the theory $T$, the formula  $ x=e \rightarrow y=e $ is equivalent to the following (let $G_{[m]}$ denote the set of elements  of $G$ whose order divides $m$). 
\begin{align*}
    \tag{*} \label{Eq.1.P.2}	(\exists a_1,\dots,a_n \in G_{[m]})& \  [y =a_1 \cdot ... \cdot a_n   \\ \ \wedge  ( & \forall a \in G_{[m]}) ~ ( x\in C(a^G)\cap G_{[m]} \rightarrow \bigwedge_{i\leq n}a_i\in C(a^G) )].  
\end{align*}
Assume that (\ref{Eq.1.P.2}) holds, witnessed by $y =a_1 \cdot ... \cdot a_n$ with $a_i\in G_{[m]}$, $i\leq n$. Moreover assume $x=e$. Then for every $a\in G_{[m]} \setminus\{e\}$ we have $x\in C(a^G)\cap G_{[m]}$. By \eqref{Eq.1.P.2}, we have for $i\leq n$ that $a_i\in C(a^G)\cap G_{[m]}$.  Since \eqref{1.P.1} implies that this set is equal to $\{e\}$, it follows that $a_i=e$ for all $i$ and therefore $y=a_1\cdot ... \cdot a_n=e$.

Conversely, assume that $x=e \rightarrow y=e $ holds. If $x=y=e$, then (\ref{Eq.1.P.2}) trivially holds, witnessed by $a_1= \cdots= a_n=e$. Assume $x\neq e$. By \eqref{2.P.1} there are $a_1,\dots, a_n\in G_{[m]}$ such that $y=a_1\cdot \dots \cdot a_n$.  We check that the consequent of \eqref{Eq.1.P.2} holds for every $a\in G_{[m]}$.  First,~\eqref{1.P.1} implies that $x\notin C(a^G)\cap G_{[m]}$ for every $a\neq e$.  If  $a=e$, then $a_i\in C(a^G)$ for all $i\leq n$, and  therefore, (\ref{Eq.1.P.2}) also holds.
\end{proof}

