\subsection{Free products of groups}
In this subsection we prove \ref{5.C} and \ref{6.C} of Theorem~\ref{T.RecognizingCoordinates}.
\begin{definition}
	Suppose that $G=H_0*H_1$ and both $H_0$ and $H_1$ are nontrivial groups. Then every element of $G\setminus \{e\}$ has the form $x_1 x_2 \dots x_{n}$ for some $n\geq 1$ where $x_i\in (H_0\setminus \{e\})\cup (H_1\setminus\{e\})$ for all $i\leq n$  and $x_i \in H_0$ if and only if $x_{i+1}\in H_1$ for all $i\leq n-1$. With these conventions we define the following ($\lambda$ stands for `length' while $L$' and `$R$' are for `left' and `right') 
	\begin{align*}
		\lambda(x_0x_1 \dots x_{n-1})&=n,\\
		\lambda(e)&=0\\
		L(x_1x_2\dots x_n)&=j\qquad \text{ if } x_1\in H_j\\
		R(x_1x_2\dots x_n)&=j\qquad \text{ if } x_n\in H_j. 
	\end{align*}
\end{definition}
The following lemma is well-known (e.g. \cite{magnus2004combinatorial}) but we include a proof for the reader's convenience. 

\begin{lemma}\label{L.FreeProduct}
	Suppose that $G=H_0*H_1$ is a free product of nontrivial groups and $a,b$ are in $G\setminus \{e\}$. Then we have the following. 
	\begin{enumerate}
		\item $\lambda(a)=\lambda(a^{-1})$. 
		\item $|\lambda(a)-\lambda(b)|\leq \lambda(ab)\leq \lambda(a)+\lambda(b)$. 
		\item $\lambda(a)>\lambda(b)$ implies $L(ab)=L(a)$ and $R(ba)=R(a)$. 
		\item If $R(a)\neq L(b)$ then $L(ab)=L(a)$ and $R(ab)=R(b)$. 
		\item \label{4.FreeProduct} If $|H_0|\geq 3$ then for every $a\in G\setminus \{e\}$ there are $b$ and $c$ in $a^G$ such that $L(b)=R(b)=0$ and $L(c)=R(c)=1$. 
	\end{enumerate}
\end{lemma}

\begin{proof}
	The first four items are immediate consequences of the definition of the free product. To prove the fifth, fix $a$ in $G\setminus \{e\}$. We will first find $b\in a^G$ such that $L(b)=R(b)=0$. If $L(a)=R(a)=0$ then let $b=a$, and if $L(a)=R(a)=1$ then let $b=xax^{-1}$ for some $x\in H_0\setminus \{e\}$. We may therefore assume $a=yd$ or $a=dy$ for some $y\in H_0\setminus \{e\}$ and $d$ such that $L(d)=R(d)=1$ or $d=e$. Since $|H_0|\geq 3$, we can choose  choose $z \in H_0 \backslash\{e,y^{-1}\}$. Then if $a = yd$, let $b=zy dz^{-1}$ and if $a = dy$, let $b=z^{-1} d y z$. Then $b$ is as required. 
	We can now set $c= xbx^{-1}$ for any $x\in H_1\setminus \{e\}$. 
\end{proof}	


\begin{proposition}
	\label{P.FreeProduct} The class of all groups that are free products of two nontrivial groups at least one of which has cardinality at least 3 recognizes coordinates.  
\end{proposition}

\begin{proof} By Theorem~\ref{T.RecognizingCoordinates} \eqref{2.RecognizingCoordinates}  it suffices to prove that  for every $a\neq e$, $C_G(a^G)=\{e\}$. This is equivalent to asserting that for all $a$ and $b$ in $G\setminus \{e\}$ there are $a'\in a^G$ and $b'\in b^G$ such that $a'b'\neq b'a'$. Fix $a$ and $b$ in $G\setminus \{e\}$. By Lemma~\ref{L.FreeProduct} \eqref{4.FreeProduct}  there are $a'\in a^G$ with $L(a')=R(a')=0$ and $b'\in b^G$ with $L(b')=R(b')=1$. Then $L(a'b')=L(a')=0$ and $L(b'a')=L(b')=1$, therefore $a'b'\neq b'a'$, as required. 
\end{proof}

\begin{proposition}\label{P.Z/2Z*Z/2Z} The group $(\bbZ/2\bbZ)*(\bbZ/2\bbZ)$ recognizes coordinates. 
\end{proposition}

\begin{proof} By Proposition~\ref{P.2}, with $m=n=2$, it suffices to prove that (i) for any two elements $a$ and $b$ of order 2 there is $a'\in a^G$ such that $a'b\neq ba'$ and (ii) every element of $G\setminus \{e\}$ is a product of at most two elements of order 2. 

	Let $G=(\bbZ/2\bbZ)*(\bbZ/2\bbZ)$ and let  $x$ and $y$ denote the generators of the two copies of $\bbZ/2\bbZ$. Then every nontrivial word in $G$ is an alternating sequence of $x$'s and $y$'s. We need two straightforward properties of such words $w$.  First, the inverse of $w$ is obtained by taking $w$ in  the reverse order. Second, the first and the last symbols of $w$  are equal (in the terminology of Lemma~\ref{L.FreeProduct}, $L(w)=R(w)$) if and only if its length is odd. These facts together imply that $w^2=e$ if and only if its length is odd. Assume $a$ and $b$ are of an odd length.  If $L(a)\neq R(b)$ then since $R(a)=L(a)$ and $R(b)=L(b)$, we have $ab\neq ba$. Otherwise, we can take $a'=xax
	$ or $a'=yay$ to obtain $a'\in a^G$ that does not commute with $b$. 


	Finally, every nontrivial word of even length is clearly a product of two nontrivial words each one of which has an odd length and Proposition~\ref{P.2}, with $m=n=2$, applies to show that $G$ recognizes coordinates.
\end{proof}	


\subsection{Graph products of groups}\label{S.GraphProducts}
Assume $\Gamma=(V(\Gamma),E(\Gamma))$ is a graph (we will write $(V,E)$ when $\Gamma$ is clear from the context) and $\cG=\{G_v\vert v\in V\}$ is a family of groups indexed by its vertices. Then the \emph{graph product} (\cite{green1990graph}) is the group $\Gamma \cG$  defined as the quotient of the free product $\ast_{v\in V} G_v$ modulo the normal subgroup generated by the commutators 
\[
\{aba^{-1} b^{-1}\vert a\in G_v, b\in G_w, \{v,w\}\in E\}. 
\]
Thus in the case when $\Gamma$ is a complete graph, $\Gamma \cG$ is the direct product $\prod_{v\in V} G_v$ while in the case when $\Gamma$ is the null graph $\Gamma\cG$ is the free product $\ast_{v\in V} G_v$.
Two prominent cases of this construction are the right-angled Coxeter groups (when $G_v\cong \bbZ/2\bbZ$ for all $v$) and the right-angled Artin groups (when $G_v\cong \bbZ$ for all $v$).  Although in some of the literature the graph $\Gamma$ is required to be finite, we do not impose any restriction on the cardinality of $\Gamma$ or groups $G_v$.  
We say that a graph product $\Gamma\cG$ is \emph{nontrivial} if  $|V(\Gamma)|\geq 2$ and  $|G_v|\geq 2$ for all $v\in V$.  
This is not a loss of generality  since $\Gamma\cG$ is isomorphic to $\Gamma'\cG'$ where $\Gamma'$ is the induced subgraph on $V'=\{v\in V\mid |G_v|\geq 2\}$ and $\cG'=\{G_v\vert v\in V'\}$. 


Theorem~\ref{T.GraphProduct} below is stated more naturally in terms of the complement of $\Gamma$, denoted $\bar \Gamma$ (to be specific, if $\Gamma=(V,E)$ then $\bar\Gamma=(V,\bar E)$ where $\bar E$ is the complement of $E$).  Since free products are a special case of graph products associated with the null graph, the following is a generalization of Proposition~\ref{P.FreeProduct}. 

\begin{theorem}\label{T.GraphProduct} 
	A nontrivial graph product $\Gamma\cG$ such that $|G_{\tilde v}|\geq 3$ for some $\tilde v\in V$   recognizes coordinates if and only if the complement $\bar\Gamma$ of $\Gamma$ is connected.
	Moreover, the class $\cC$ of all nontrivial graph products $\Gamma\cG$ such that~$\bar{\Gamma}$  is connected and $|G_v|\geq 3$ for some $v\in V(\Gamma)$  recognizes coordinates. 
\end{theorem}
The proof of this theorem will take up this entire subsection. 

The assertion that $|G_v|\geq 3$ for some $v$ is equivalent to the assertion that $\Gamma\cG$ is not a right-angled Coxeter group. We conjecture that the conclusion of Theorem~\ref{T.GraphProduct} is true without this assumption, and that the analogous conjecture is true for all Coxeter groups and all Artin groups. Proposition~\ref{P.Z/2Z*Z/2Z} gives this conjecture in case  of $(\bbZ/2\bbZ)*(\bbZ/2\bbZ)$, the right-angled Coxeter group   associated with the null graph with two vertices, 	\begin{tikzpicture}		\draw (0,0) node (A1) {$\bullet$}; 
		\draw (0.4,0) node (A2) {$\bullet$};\\
\end{tikzpicture}, and its proof shows that the proof of our conjecture may be somewhat involved. 




\begin{lemma}
	\label{L.graph.disconnected} If $\bar \Gamma$ is not connected then $\Gamma\cG$ is decomposable.   
\end{lemma}

\begin{proof}
	Let $V(\Gamma)=X\sqcup Y$ be a partition of into nonempty sets such that no vertex in $X$ is $\bar\Gamma$-adjacent to a vertex in $Y$. In other words, the complete bipartite graph with bipartition $X,Y$ is a subgraph of $\Gamma$.  Let $\Gamma_X$ and $\Gamma_Y$ be the induced subgraphs of $\Gamma$ on $X$ and $Y$. Then, with $\cG_X=\{G_v\vert v\in X\}$ and $\cG_Y=\{G_v\vert v\in Y\}$  the definition of $\Gamma\cG$ implies that $\Gamma\cG\cong \Gamma_X \cG_X\times \Gamma_Y\cG_Y$. Since each $G_v$ is nontrivial, $\Gamma\cG$ is decomposable as a product of nontrivial groups. 
\end{proof}

Our positive result will require considerably more work and references to the literature.
The \emph{normal form} for words in graph products appears in \cite[Theorem ~3.9, also see Definition~3.5]{green1990graph}. It asserts that for every $g\in \Gamma\cG\setminus \{e\}$ there are $n\geq 1$, $v(i)\in V$, $g(i)\in G_{v(i)}\setminus \{e\}$, for $1\leq i\leq n$ such that $g=g_1\cdot\ldots \cdot g_n$, and for all $1\leq i\leq k<j\leq n$ such that 
$[g_i,g_l]=e=[g_m,g_j]$ for all $i+1\leq l \leq k$ and all $k+1\leq m \leq j$, we have $v(i)\neq v(j)$. A moment taken to parse the latter condition on commutators reveals that it implies $g=g_1\cdot\ldots\cdot g_{i-1} g_{i+1}\cdot\ldots \cdot g_k g_i g_j g_{k+1}\cdot\ldots \cdot g_{j-1} g_{j+1}\cdot\ldots \cdot g_n$, in which case $v(i)=v(j)$ would imply that $g_i g_j\in G_{v(i)}$ and that $g$ could be presented as a word of length $n-1$.  	The elements $g_i$ in a normal form of $g$ are called \emph{syllables} of $g$.  
Note that the normal form of $g$ is not unique, since if $\{v(i),v(i+1)\}\in E$ then $g_i$ and $g_{i+1}$ can be swapped without changing the value of $g$. However, the set of syllables of $g$ is uniquely determined. 

Following \cite{genevois2019automorphisms}, for $g\in \Gamma\cG$  the \emph{head} of $g$, denoted $\head(g)$, is the set of all first syllables appearing in the reduced words representing $g$. The \emph{tail} of $g$, denoted $\tail(g)$, is the set of all last syllables appearing in the reduced words representing $g$. Clearly these sets depend on $g$ and not on the normal form used to represent it. For $g\in \Gamma\cG$ with the normal form $g=g_1\cdot \ldots \cdot g_n$ we write 
\begin{align*}
	L(g)&=\{v\in V\vert ((\exists a\in \head(g)) a\in G_{v}\},\\
	R(g)&=\{v\in V\vert ((\exists a\in \tail(g)) a\in G_{v}\},\\
	V(g)&=\{v\in V\vert (\exists i) g_i\in G_{v}\}. 
\end{align*}
(A reasonable notation for $V(g)$ would be $\supp(g)$ but in other sections of the present paper $\supp$ has a different meaning.)

Lemma~\ref{L.GraphGeneralities} below collects straightforward facts that will be used in the proof of lemmas leading towards the nontrivial part of Theorem~\ref{T.GraphProduct}. 
\begin{lemma}
	\label{L.GraphGeneralities}
	Suppose that $\Gamma\cG$ is a nontrivial graph product and let  $g=g_1\cdot\ldots \cdot g_m$ and $h=h_1\cdot\ldots \cdot h_n$ be  elements of $\Gamma\cG\setminus \{e\}$ in normal form. 
	\begin{enumerate}
		\item \label{1.GraphGeneralities} If $g_i\in G_{v(i)}\setminus \{e\}$ for $1\leq i\leq n$, then $v\in L(g)$ if and only if there is $i$ such that $v=v(i)$ and  all $1\leq j<i$ satisfy $\{v(j),v(i)\}\in E$. 
		\item \label{2.GraphGeneralities} If $V(g)\cap V(h)=\emptyset$ then $\head(g)\subseteq \head(gh)\subseteq \head(g)\cup \head(h)$. 
		\item \label{3.GraphGeneralities} If $V(g)\cap V(h)=\emptyset$ and for every $v\in L(h)$ there is $w\in V(g)$ such that $\{v,w\}\notin E$ then $L(g)=L(gh)$.
		%		 \item \label{4.GraphGeneralities} If $v\in L(g)$ then there is exactly one  $c\in G_v$ such that $v\notin L(cg)$. 
	\end{enumerate}
	Since $\tail(g)=\head(g^{-1})$ assertions analogous to the above  hold for $\tail(g)$ and $\tail(h)$. \qed
\end{lemma}







\begin{lemma}\label{L.GraphConjugacy} In a nontrivial graph product $\Gamma\cG$ such that $\bar\Gamma$ is connected  and $|G_{\tilde v}|\geq 3$ for some $\tilde v\in V$  and $\bar \Gamma$ is connected the following holds. For  every  $v\in V$, every $g\in \Gamma\cG\setminus \{e\}$ is conjugate to some $\tilde g$ such that $L(\tilde g)=R(\tilde g)=\{v\}$. 
\end{lemma}


\begin{proof} 
	Fix $g\in \Gamma\cG\setminus\{e\}$ and let $L(g)=\{v(1), \dots, v(m)\}$. Since the syllables in $\head(g)$ commute, $\{v(i),v(j)\}$ is not an edge of $\bar \Gamma$ for all $i,j\leq m$.
	Since $\bar\Gamma$ is connected, there is $v(*)\in V\setminus L(g)$. 
	Choose a spanning tree $T$ for $\bar \Gamma$. (That is, $T$ is an acyclic connected subgraph of $\bar\Gamma$ with the same vertex set.) For every $i\leq m$ there is a unique path $P(i)$ in $T$ connecting $v(*)$ and $v(i)$. Consider $T(0)=\bigcup_{i\leq m} P(i)$ as a subgraph of $T$ and let $d$ denote the graph distance on $T(0)$.  Let $\sqsubseteq$ be a linear ordering of the vertices of $T(0)$  such that $x\sqsubseteq y$ implies $d(v(*),x)\leq d(v(*),y)$, and let $x(1), \dots, x(k)$ be the $\sqsubseteq$-increasing list of all vertices of $T(0)$. Then $x(1)=v(*)$. For each $1\leq j\leq k$ pick $h_j\in G_{x(j)}\setminus \{e\}$. 



	Let $a=h_1 h_2\dots h_k$.  		If $v(*)=\tilde v$ let $g'=a g a^{-1}$. 
	If $v(*)\neq \tilde v$, then let $x(1),\dots, x(p)$ be a $\bar{\Gamma}$-path from $\tilde v$ to $v(*)$. Choose $h'_i\in G_{x(i)}$  for $1\leq i< p$, let $b=h'_1 h'_2\cdot\ldots \cdot h'_{p-1} $. Then Lemma~\ref{L.GraphGeneralities} \eqref{1.GraphGeneralities} implies $L(ba)=\{\tilde v\}$.  With  $g'=b a g a^{-1} b^{-1}$, Lemma~\ref{L.GraphGeneralities} \eqref{3.GraphGeneralities} implies   $L(g')=\{\tilde v\}$.  


	At this point in the construction we don't know what is the relation of $\tilde v$ to the vertices in $R(g')$ but we would like to be able to assume that $\tilde v\in R(g')$. 
	Assume this is not the case. Since $\tilde v\in L(g')$ and $|G_{\tilde v}|\geq 3$, if $a\in \head(g')\cap G_{\tilde v}$ then we can choose $c\in G_{\tilde v}\setminus\{e,a^{-1}\}$.  In this case we have  $L(cg')=L(g')$ and   
	$g''=cg'c^{-1}$ satisfies $L(g'')=\{\tilde v\}$ and $\tilde v\in R(g'')$. 


	Let $R(g')=\{w(1),\dots, w(n)\}$ (with $w(1)=\tilde v$). The next portion of the proof, we look for a conjugate $\tilde{g}$ of $g'$ so that  such that  $R(\tilde{g})=L(\tilde{g})=\{\tilde v\} $. This is analogous to previous part of the proof where we were obtained $g'$. Since  $\{w(i),w(j)\}$ is not an edge of $\bar \Gamma$ for all $i,j\leq n$ and $\bar \Gamma$ is connected, there is $w(*)\in V\setminus R(g')$. Find a tree $U(0)$ with root $w(*)$ and leaves  $\{w(1),\dots, w(n)\}$, let $d(\cdot,\cdot)$ denote the graph distance in $U(0)$, fix a linear ordering of its vertices such that  $x\sqsubseteq' y$ implies $d(w(*),x)\leq d(w(*),y)$, and let $y(1), \dots, y(k')$ be the  $\sqsubseteq'$-increasing list of all vertices of $U(0)$. For each $1\leq j<k'$ pick $h'_j\in G_{y(j)}\setminus \{e\}$. 
	Let $a'=h_{k'-1}\cdot\ldots \cdot h'_1$. Then, using Lemma~\ref{L.GraphGeneralities} as before,  $g'''=(a')^{-1} g'' a'$ satisfies $R(g''')=L(g''')=\{w(*)\}$. 

	It remains to show that we can assure that $w(*)$ is equal to the distinguished vertex $v$ fixed in the statement of this lemma. If $w(*)\neq v$, choose a path in $\bar\Gamma$ from $w(*)$ to $v$, $w(*)=x(0),x(1), \dots , x(m)=v$, fix $f_i\in G_{x(i)}\setminus \{e\}$, let $d= f_m \cdot f_{m-1}\cdot\ldots \cdot f_1$ and let $\tilde g=d g''' d^{-1}$. Once again,  Lemma~\ref{L.GraphGeneralities} implies  that $L(\tilde g)=R(\tilde g)=\{v\}$. 
\end{proof}

 The reader may be under the impression that the fact that every $g\in \Gamma\cG$ is conjugate to a word $g'$ such that $L(g')\cap R(g')=\emptyset$ (this is \cite[Lemma~3.16]{green1990graph}, where such words $g'$ are called \emph{cyclically reduced}) may be used to remove the assumption that $|G_{\tilde v}|\geq 3$ in Lemma~\ref{L.GraphConjugacy} and  Theorem~\ref{T.GraphProduct}. The proof of  that $(\bbZ/2\bbZ)*(\bbZ/2\bbZ)$ recognizes coordinates (Proposition~\ref{P.Z/2Z*Z/2Z})  is very different from the above proof, suggesting that a common generalization requires additional nontrivial ideas. 
   In particular, using the notation from Proposition~\ref{P.Z/2Z*Z/2Z}, one should note that the element $ab$ of $(\bbZ/2\bbZ)*(\bbZ/2\bbZ)$ (and any other reduced word of even length in this group) does not satisfy the conclusion of Lemma~\ref{L.GraphConjugacy}. 

\begin{lemma}
	\label{L.GraphRecognizing} If $\cC$ is the class of all nontrivial graph products $\Gamma\cG$ such that~$\bar \Gamma$ is connected and   $|G_{\tilde v}|\geq 3$ for some $\tilde v\in V$,   then $\cC$ recognizes coordinates. 
\end{lemma}


\begin{proof} By Theorem~\ref{T.RecognizingCoordinates} \eqref{2.RecognizingCoordinates}, it suffices to show that for every $\Gamma\cG\in \cC$, for all $a$ and $b$ in $\Gamma\cG\setminus \{e\}$, some $\tilde a$ conjugate to $a$ does not commute to some~$\tilde b$ conjugate to $b$. Since $\bar \Gamma$ is connected and it has at least two vertices, we can fix vertices $v$ and $w$ adjacent in $\bar\Gamma$. 
	By Lemma~\ref{L.GraphConjugacy}, there are $\tilde a$ and $\tilde b$ conjugate to $a$  and $b$, respectively, such that $L(\tilde a)=R(\tilde a)=\{v\}$ and $L(\tilde b)=R(\tilde b)=\{w\}$. Since $\{v,w\}$ is not an edge in $\Gamma$,  $L(ab)=R(a)\neq L(b)=L(ba)$, hence $ab\neq ba$.  
\end{proof}


\begin{proof}[Proof of Theorem~\ref{T.GraphProduct}] By Lemma~\ref{L.graph.disconnected} below, if $\bar\Gamma$ is not connected then $\Gamma\cG$ is decomposable and it therefore does not recognize coordinates by Theorem~\ref{Fact:construction}. By Lemma~\ref{L.GraphRecognizing}, the class $\cC$ recognizes coordinates. 
\end{proof}


\subsection{Symmetric groups}

For an integer $n\geq 2$, by $\Sym_n$ we denote the symmetric group on $n$ elements. By $\Sym$ we denote an arbitrary  finite symmetric group. As mentioned in the proof of Theorem~\ref{T.RC} \ref{2.Cplus}, the 
class of finite symmetric groups containing four or more elements recognizes coordinates. In this section we slightly modify this argument to be able to include the symmetric group on $3$ elements. Then, we pursue the model-theoretic motivation described in the introduction and prove a quantifier elimination result. Here, we will however have to exclude $\Sym_6$, because of the existence of a non-trivial outer automorphism.  



\begin{lemma}\label{L.Defining2Cycles}
	\begin{enumerate}
		\item   \label{1.Defining2Cycles}      There is an $h$-formula  $\psi(x)$ which uniformly defines the set $C_2\cup \{e\}$ where $C_2$ is the set of transpositions, in all symmetric groups of the form  $\Sym_n$ for $n \neq 2$ and $n \neq 6$. 
		\item \label{2.Defining2Cycles}        For every $k\geq 3$,  there is a formula $\phi_k(x)$ which uniformly defines the set $C_k$ of $k$-cycles in all symmetric group $\Sym_n$ with $n \neq 6$.% and $n \neq 6$.
	\end{enumerate}
	\end{lemma}

\begin{proof} \eqref{1.Defining2Cycles}
	We claim that the following $h$-formula defines, uniformly in $\Sym_{n}$ for all $n>2$ and $n\neq 6$, the set $C_2 \cup \{e\}$: 
	\[
	\psi(x):=x^2=e \wedge (\forall g)~ (x gxg^{-1})^6=e\wedge (\exists g)~(x gxg^{-1})^3=e. 
	 \]
	 We remark that the last conjunct is required only in $\Sym_4$. 

     Since the conjugate of a 2-cycle is a 2-cycle and the product of two distinct 2-cycles is either a 3-cycle or a 2-2-cycle, every 2-cycle satisfies each of the above conjuncts. 

	We now prove the converse. Every element of order 2 is a product of transpositions with disjoint supports (for convenience we will call such permutations $2$-$2$-\dots -$2$-cycles). 

	 The case of $n = 3$ is trivial. Suppose that $\sigma$ is an element of order 2 in $\Sym_n$ for $n\geq 4$ and $n\neq 6$ that is not in $C_2$.

	    If $n=4$ then $\sigma$ is a $2$-$2$-cycle. Any two $2$-$2$-cycles are conjugate, and  in $\Sym_4$, the product of two distinct $2$-$2$-cycles is a $2$-$2$-cycle (e.g.
	 		$(12)(34) \circ (14)(23)=(13)(24)$). Thus in this case $\sigma$  does not satisfy the last conjunct of the formula.

	 Now consider the case when $\sigma$ has a fixed point. Let $\sigma$ be the product of $k\geq 2$ disjoint transpositions, $\sigma=\prod_{j=1}^k (m_{2j-1},m_{2j})$ and let $m_{2k+1}$ be a fixed point of $\sigma$. Then $\sigma':=\prod_{j=1}^k (m_{2j},m_{2j+1})$ is conjugate to $\sigma$, and $\sigma'\circ \sigma$ is the $2k+1$-cycle is the $2k+1$ cycle $(m_1 m_3\dots m_{2k+1} m_{2k} m_{2k-2}\dots m_2)$. Since $2k+1\geq 5$, we have that  $\sigma$ does not satisfy the middle conjunct of the formula. 

	 This proves the claim in the case when $n$ is odd, and when $k \leq 3$, and $n \geq  8$.  We may therefore assume $k\geq 4$; let us assume $k=4$ and $n=8$ for a moment. In the following special case,  we obtain a conjugate $\sigma'$ of sigma such that $\sigma\circ \sigma'$ has order 4 and therefore fails the middle conjunct of the formula: 
	         \[
	         (16)(47)(52)(38)\circ (15)(64)(73)(28)= (1234)(5678).
	         \]   
	      In general, if $k\geq 4$, then by restricting $\sigma$ to an 8-element $\sigma$-invariant subset of its support we can find $\sigma'$ such that $\sigma\circ \sigma'$ has order 4. This concludes the proof of \eqref{1.Defining2Cycles}.    
%	This is due to the following facts:
%	\begin{itemize}
%		\item     in $\Sym_4$, the product of $2$-$2$-cycle with a conjugate (other than itself) is always a $2$-$2$-cycle. (e.g.
%		$(12)(34) \circ (14)(23)=(13)(24)$). Thus, a $2$-$2$-cycle does not satisfy the last part of the formula and only $2$-cycles and the identity satisfy it.
%		\item in $\Sym_5$, the product of a $2$-$2$-cycle with a conjugate can have order $5$: 
%        \[ (12)(35) \circ (13)(45)=(12345). \] Thus $2$-$2$-cycles don't satisfy the middle part of the formula and only $2$-cycles and the identity satisfy it. 
%		\item in $\Sym_n$ for $n>6$, $n$ odd, we see as in the previous case that only $2$-cycles and the identity satisfy the formula.
%		
%		\item in $\Sym_n$ for $n>6$, $n$ even, we can observe that  $2$-torsion elements composed of 4 cycles or more don't satisfy the middle part of the formula: 
%        \[(16)(47)(52)(38)\circ (15)(64)(73)(28)= (1234)(5678).\]   We argue as before to that the formula excludes $2$-$2$-cycles and $2$-$2$-$2$-cycles.  
%	\end{itemize}
	Prior to embarking on the proof of \eqref{2.Defining2Cycles}, 
	we note that in $\Sym_n$ for all $n\geq 3$, $n\neq 6$,  the set of transpositions $C_2$ is given by the formula
	\[
	\psi(x)\wedge x\neq e.
	\]
      This is however not an $h$-formula. 

\eqref{2.Defining2Cycles}
      We need a formula that defines $C_2$ in $\Sym_n$ for all $n\neq 6$. To include the case $n= 2$, we can consider the formula:
    \[
    [\psi(x)\vee (\exists y)(\forall z)~ (z=y\vee z=e) ]\wedge x\neq e .
    \]
The set $C_k$ of $k$-cycles can now be defined as the set of products of $(k-1)$ pairwise distinct $2$-cycles $c_1,\dots, c_{k-1}$ such that $c_ic_j \neq c_jc_i$ if and only if $\vert i-j\vert=1$ for $i,j<k$.  
\end{proof}

Since there is an automorphism of $\Sym_6$ sending $2$-cycles to $2$-$2$-$2$-cycles,  there is no parameter-free definition of the set of $2$-cycles in $\Sym_6$ and Lem\-ma~\ref{L.Defining2Cycles} cannot be improved by including $\Sym_6$ in the set of groups to which it applies. 

Even though we cannot separate $2$-cycles from $2-2-2$-cycles in $\Sym_{6}$, we can still prove the following:


\begin{corollary}\label{C.SymAllExceptSix}
	The class of symmetric groups $\Sym_n$, $n\geq 3$ recognizes coordinates.
\end{corollary}

\begin{proof} Let $\Sym$ denote an arbitrary $\Sym_n$ for $n\geq 3$ and $n\neq 6$. Let $\psi(x)$ be the $h$-formula defining $\mathcal{C}_2\cup \{e\}$ as in the proof of \Cref{L.Defining2Cycles}\eqref{1.Defining2Cycles}. For $x,y\in \Sym$, let $xRy$ denote the relation ``$x$ commutes with all conjugates of $y$'' used in the proof of Theorem~\ref{T.RecognizingCoordinates} \eqref{2.RecognizingCoordinates}.  Then $xRy$ is an $h$-formula and for all $x,x' \in \Sym$, we have 
\[ 
x'=e \rightarrow x=e \  \Leftrightarrow \ (\forall y\in \mathcal{C}_2\cup \{e\}) ~ \ \left( x'Ry \rightarrow xRy \right). 
\]


The right-hand side formula is an $h$-formula, as it is equivalent to
\begin{align*}
	(\exists y)  ~(\psi(y) ~\wedge \ x'Ry) 
	\wedge (\forall y) ~ \left((\psi(y) ~\wedge \ x'Ry) \rightarrow xRy \right). 
\end{align*}
%By the equivalence of \eqref{3.T.eq} and \eqref{1.T.eq}  in \Cref{T.eq}, 
Notice furthermore that the same equivalence holds in $\Sym_6$. Indeed, the formula $\psi(y)$ defines there the set containing $C_2\cup \{e\}$ and the $2$-$2$-$2$-cycles, and the centralizer of the conjugacy class of a $2$-$2$-$2$-cycles is also $\{e\}$.

The conclusion follows by \Cref{T.eq.groups}.  
\end{proof}


Since $\Sym_2$ is abelian, any class containing it cannot recognize coordinates by \Cref{T.example:DNR} \ref{DNR.decomposable}.

\begin{lemma}\label{L.Sym.xneqe}
In  the common theory of $\Sym_n$, for all $n\geq 3$, the formula $x\neq e$ is equivalent to an $h$-formula. 
\end{lemma}

\begin{proof}
Since both the formulas $\psi(\tau)$ (asserting that $\tau\in C_2\cup \{e\}$ if $n\neq 6$) and $xRy$ used in the proof of \Cref{C.SymAllExceptSix} are equivalent to $h$-formulas and since $eRx$ holds for all $x$, the right-hand side of  
\[
x\neq e \ \Leftrightarrow \ (\forall y) (\forall \tau ) \ ((\psi(\tau)\wedge \tau R y) \rightarrow \tau R x )
\]
 is an explicit $h$-formula. We remark that this Lemma also follows from \Cref{Prop:Omarov}.
\end{proof}


As discussed in \Cref{section:FV}, we can now proceed to define a language interpretable in  $\mathcal{L}_{\textrm{groups}}$ in which reduced products of $\Sym_n$ for $n \geq 4, n\neq 6$ eliminate quantifiers.
The following definition and fact are heavily inspired by a post on Math Stack Exchange (\cite{kruckman2021stack}), from which we borrow the terminology and some of the proofs, included for reader's convenience. 
 %https://math.stackexchange.com/questions/4098806/identifying-the-finite-symmetric-groups}

\begin{definition}\label{D.identifying}
	A pair  of distinct transpositions in some symmetric group which have at least one common element $k$, is said to \emph{identify} $k$, or  that it is \emph{identifying}. The set of all identifying pairs is denoted by $P$.
On $P$ consider the equivalence relation $E$ given by 
\[
(\sigma,\tau) E (\sigma',\tau') \quad   \Leftrightarrow \quad \text{pairs $(\sigma,\tau)$ and $(\sigma',\tau')$ identify the same element $k$.}
\] 
Let $\mathcal{L}_X$ denote  the group language expanded by a sort for the base set $\{1,\dots, n\}$ and the natural projection $\pi_X: P \rightarrow X$.
\end{definition}

Clearly, $E$ is an equivalence relation on the set $P$ and every $\Sym_n$ has a natural expansion to an $\calL_X$-structure. Also, in $\Sym_n$ the quotient $X:=P/E$ is naturally identified with the base set $\{1,\dots,n\}$. It will be convenient to write $\Sym_X$ for the symmetric group on the base set $X$. 


\begin{fact}\label{Fact:symmetricgroups}  The following facts hold (uniformly) in the theory of all $\Sym_n$, for $n\geq 4$ and $n\neq 6$.

    \begin{enumerate}
        \item\label{f.sym1} The set $P$ of identifying pairs is (uniformly) $h$-definable, namely there exists an $h$-formula defining $P$ in all $\Sym_n$, for $n \geq 4$ and $n \neq 6$.
        \item\label{f.sym2} The relation $E$ on $P$ is (uniformly) $h$-definable.
          \item\label{f.sym4}       For $k$ and $h$ in the base set  $X$ and $\nu \in \Sym_X$, the relation 
        \[\nu=\begin{cases}
            ~(kh) & \text{ if }k\neq h\\
            ~e & \text{ otherwise}
        \end{cases}\]
        is defined by an $h$-formula $\psi(\nu,k,h)$ in the language $\mathcal{L}_X$. 

        \item\label{f.sym5} For $s\geq 2$ and distinct $k_1, \dots, k_s$ 
        in $X$, and $x\in \Sym_X$, the relation:
        \[x=
\begin{pmatrix}
1 & \dots & s \\
k_1 & \dots & k_s
\end{pmatrix},
\]        
is defined by an $h$-formula in the language $\mathcal{L}_X$.

    \item\label{f.sym6} For every $n\geq 4$, $n\neq 6$, $k\geq 1$ and a $k$-tuple $(\sigma_1,\dots,\sigma_k)$ of elements of $\Sym_n$,  the type $p=\tp(\sigma_1,\cdots,\sigma_k/\emptyset)$ is isolated by an $h$-formula $\phi_p(x_1,\dots,x_k)$. 
    \end{enumerate}
\end{fact}

We briefly justify  these facts:
\begin{proof}
    (\ref{f.sym1}) As two distinct transpositions move a common element if and only if their product has  order three, we may use the following formula:
       \[\sigma,\tau\in C_2\wedge \sigma\tau^{-1} \neq e  \wedge  \ (\sigma\tau)^3=1.\] 
    This is equivalent to an $h$-formula by Lemma~\ref{L.Sym.xneqe} 

    (\ref{f.sym2}) We will prove that the relation $E$ is defined by the following formula:
        \begin{equation}\label{eq.E}
        \begin{aligned}
           (\forall \nu\in C_2\cup\{e\})\quad  
            & [\nu\sigma \nu=\sigma \wedge \sigma \neq \nu ] \rightarrow \\ & [(\tau  \nu \tau'\nu)^3= (\tau  \nu \sigma'\nu)^3=(\sigma  \nu \tau'\nu)^3=(\sigma  \nu \sigma'\nu)^3=1 ]   \\
            \wedge &  [\nu\tau \nu=\tau \wedge \tau \neq \nu ] \rightarrow \\
            &[(\tau  \nu \tau'\nu)^3= (\tau  \nu \sigma'\nu)^3=(\sigma  \nu \tau'\nu)^3=(\sigma  \nu \sigma'\nu)^3=1 ].
        \end{aligned}
        \end{equation}
    Indeed, if both $(\sigma,\tau)$ and $(\sigma',\tau')$ identify an element $k$, then any transposition $\nu$ disjoint from $\sigma$ or $\tau$ does not move $k$. Then, as $\tau'$ and $\sigma'$  move $k$, so do $\nu\tau'\nu$ and $\nu\sigma'\nu$. Therefore each one of $\tau  \nu \tau'\nu,\tau  \nu \sigma'\nu,\sigma  \nu \tau'\nu$ and $\sigma  \nu \sigma'\nu$ has order $1$ or $3$, and formula \eqref{eq.E} holds.

    Conversely, assume that  $(\sigma,\tau)$ identifies $k$ and $(\sigma',\tau')$ identifies some $k'\neq k$. We prove that \eqref{eq.E} doesn't hold by considering cases. 
    \begin{itemize}
        \item If at least one of the pairs of transpositions among $(\sigma,\sigma'),(\sigma,\tau'),(\tau,\sigma')$, and $(\tau,\tau')$ is disjoint, then the formula \eqref{eq.E} above fails by taking $\nu=e$.
        \item Now assume that none of these pairs are disjoint. Since $k\neq k'$, there is $k''$ such that  $\tau,\sigma,\tau'$, and $\sigma'$ are transpositions of $k,k'$, and $k''$. By swapping $\sigma$ with $\tau$ and $\sigma'$ with $\tau'$ if needed, we may assume that $\sigma=(kk'),\tau=(kk''),\sigma'=(k'k)$, and $\tau'=(k'k'')$.
        As the base set has at least four  elements, we may take $l\notin \{k,k',k''\}$ and let $\nu:=(lk'')$.  Then $\tau \nu \tau' \nu =(kk'')(k'l)$ has order $2$ and \eqref{eq.E} fails.
    \end{itemize}    
    As $\sigma \neq \nu$ is equivalent to an $h$-formula by Lemma~\ref{L.Sym.xneqe}, one sees that~\eqref{eq.E} is also equivalent to an $h$-formula.

    (\ref{f.sym4}) Let $\psi(\nu,k,h)$ be the following formula (using the $h$-formulas for $P$ and $E$ provided by the above)
    \[(\forall \sigma, \tau \in C_2) ~ \left( [(\sigma,\tau) \in P \wedge \pi_X(\sigma, \tau)=k ] \rightarrow \pi_X(\nu\sigma\nu, \nu\tau\nu)=h \right).\]
    In words, if  $\psi(\nu,k,h)$ holds, then for all $\sigma,\tau\in C_2$,  if $(\sigma,\tau)$ identifies $k$, then $(\nu \sigma \nu ,\nu \tau\nu)$ identifies $h$.
    Clearly, if $k,h$ are distinct elements of $X$, then $\nu=(k,h)$, and if $k=h$, then $\nu=e$ as required.

    (\ref{f.sym5}) The permutation $\rho:=\begin{pmatrix}
1 & \dots & s \\
k_1 & \dots & k_s
\end{pmatrix}$ can be written as a product of transposition. Therefore, this relation is expressible as a conjunction of $h$-formulas of the form $\psi(\nu,k,h)$ as in (\ref{f.sym4}).


(\ref{f.sym6}) 
For $i\leq k$, consider the following permutation
    \[\sigma_i:=
\begin{pmatrix}
1 & \cdots & n \\
\sigma_i(1) & \cdots & \sigma_i(n)
\end{pmatrix}. 
\]
Then, the type $p$ is isolated by the following $\mathcal{L}_X$-formula:
    \[\label{formula.Ip}\tag{$I_p$}(\exists ~k_1,\dots,k_n \in X) ~ \bigwedge_{\substack{i,j\leq k\\ i\neq j}} k_i\neq k_j   ~\wedge x_i= \begin{pmatrix}
1 & \cdots & n \\
k_{\sigma_i(1)} & \cdots & k_{\sigma_i(n)}
\end{pmatrix}.\]
    We claim that the formula above is equivalent to an $h$-formula in the language of groups. 
    We use the following facts: 
    \begin{itemize}
        \item Every existential quantifier over $X$ can be replaced by an existential quantifier over the group: 
        \[(\exists k\in X) ~ \phi(X)  \Leftrightarrow \exists \sigma_k,\tau_K  ~ (\sigma_k,\tau_k)\in P \wedge \phi(\pi_X(\sigma_k,\tau_k))\]
        \item We have the equivalence 
        \[\psi( \nu , \pi_X((\sigma_k,\tau_k)), \pi_X((\sigma_h,\tau_h)) ) \Leftrightarrow \nu \in C_2\cup\{e\} \wedge (\nu\sigma_k\nu,\nu\sigma_h\nu)E(\sigma_h,\tau_h). \]
        \item for pairs $(\sigma_h,\tau_h)$ and $(\sigma_k,\tau_k)$ in $P$, the relation   $\pi_X((\sigma_k,\tau_k)) \neq  \pi_X((\sigma_h,\tau_h)) $
        can be expressed in the language of group as follows:
        \[ (\forall \nu)~ [(\nu\sigma_k\nu,\nu\sigma_h\nu)E(\sigma_h,\tau_h)\rightarrow \nu\neq e]. \]
    \end{itemize}
    Using these facts, as well as the facts that the set $P$ and  the relations $E$ and $x\neq e$ are $h$-definable, we can deduce that (\ref{formula.Ip}) can be expressed by an $h$-formula $\phi_p$ in the language of groups. 
\end{proof}


With $\phi_p$ as provided by  \Cref{Fact:symmetricgroups} (\ref{f.sym6}), we obtain the following amusing corollary which is certainly folklore but we could not find it in the literature. 

\begin{corollary}
    Let $n> 6$. The parameter-free type of a permutation $a\in \Sym_n$ is uniformly isolated by the $h$-formula $\phi_p$ in the theory of all $\Sym_N$ for $N\geq n$. \qed 
\end{corollary}

We may finally give, for all $n\geq4$ and $n\neq 6$, an interpretable language where reduced power of the symmetric group $\Sym_n$ eliminates quantifiers.
We denote by $\mathcal{L}_{n}^+$ the $2$-sorted language consisting of the following:
	\begin{itemize}
		\item The language of groups, $(G, \cdot)$. 
		\item The language of Boolean algebras $(\Bool{I}{I}, \subseteq)$ %where $c_n:= \{i \in \Index{I} \mid G_i=\Sym_n\} \mod I$,
		\item $\{\supp_{\phi_{p}}: G^{\vert k \vert}  \rightarrow \Bool{I}{I}: p(x_1,...,x_k)$ is an $\Sym_{n}$-type$\}$,      where $\phi_{p}(x_1,\dots, x_k)$ is as in \Cref{Fact:symmetricgroups} \eqref{f.sym6}.
	\end{itemize}

\begin{corollary}\label{lem:cyclesformula}
    Fix an $n\geq 4$, $n \neq 6$, an index set $\mathbb{I}$, and an ideal on $\mathcal{I}$ on $\mathbb{I}$. Let $G:=\prod_{\bbI}\Sym_n/\cI$. 
	Then $(G,\mathcal{L}_{n}^+)$ is an interpretable expansion of the group $(G,\cdot)$, which eliminates quantifiers relative to $(\Bool{I}{I}, \subseteq)$.
\end{corollary}


\begin{proof}
    %We deal with the case $n=3$ in \Cref{P.prodSym3} below. 
    %Fix $n\geq 4$, $n \neq 6$.
    In $\Sym_n$, every formula $\phi(\bar{x})$ is equivalent to a Boolean combination of $h$-formulas of the form $\phi_{p}(\bar{x})$ for some types $p$,  i.e., $\{\phi_{p}(\bar{x}) \ : \ p\in \mathcal{S}(\Sym_{n})\}$ is a fundamental set of satisfiable $h$-formulas in $\Sym_n$. Since $G$ recognizes coordinates, it interprets the support function by \Cref{T.eq.groups}. It follows from \Cref{C.QuestionDecomp} that the language $\mathcal{L}_{n}^+$ is interpretable in the language of groups and that  $G$ eliminates quantifiers relative to $\Bool{I}{I}$ in this language.
\end{proof}
\begin{remark}
    \begin{itemize}
        \item One could slightly improve the above corollary and, for a fixed $N$, eliminate quantifiers in a reduced product $G \coloneq \prod_\Ideal{I} G_i$, where $G_i \in \{\Sym_4,\Sym_5,\Sym_7,\Sym_8,\dots, \Sym_N\}$. 
        \item We don't know a language where an arbitrary reduced products of symmetric groups among $\Sym_n$, for $n\geq 4$, $n\neq 6$,  eliminate quantifiers relative to the corresponding Boolean algebra. This would require a uniform description of definable sets in all symmetric groups, which our analysis  does not provide. For example, we don't know whether the formula $x^2=e$ can be described uniformly as a Boolean combination of $\phi_p$.
         \end{itemize}
\end{remark}



We proceed to analyze quantifier elimination in reduced powers of  $\Sym_3$. For $p\in \{2,3\}$, let $\supp_p$ denote the function $\supp_{x^p=e}: \mathcal{G}\rightarrow \Bool{I}{I}$. Consider the language $\mathcal{L}^{\star} := \{\cdot,  (\Bool{I}{I},\subseteq), \supp_{2},\supp_{3} \}$.




\begin{proposition}\label{P.prodSym3}
Let $\mathbb{I}$ be an index set, and $\mathcal{I}$ be an ideal on $\mathbb{I}$. Let Let $G:=\prod_{\bbI}\Sym_3/\cI$. . Then $(G,\mathcal{L}^{\star})$ is an interpretable expansion of the group $(G,\cdot)$, which eliminates quantifiers relative to $(\Bool{I}{I}, \subseteq)$.

\end{proposition}

The proof will be given below. 
Observe that, since every nontrivial element of $\Sym_3$ is either a $2$- or a $3$-cycle, we have $\supp(x)= \supp_2(x)\sqcup \supp_3(x)$.


\begin{lemma}[Patching]
	The following can be expressed by a first-order sentence in $\mathcal{L}^{\star}$-theory of $\mathcal{G}$:
	For all $A,B \in \Bool{I}{I}$ such that $A\cap B = \emptyset$ and $a,b \in G$, there exists $c$ such that $c\restriction{A}=a\restriction{A}$ and $c\restriction{B}=b\restriction{B}$.
\end{lemma}
\begin{proof}
	This condition can be written as follows: 
	\[
	(\exists c\in \mathcal{G}) A^\complement \supseteq \supp(c\cdot a^{-1}) \wedge  B^\complement \supseteq \supp(c\cdot b^{-1}).\qedhere
	\]
\end{proof}

\begin{proof}[Proof of \Cref{P.prodSym3}]

	We prove the statement via the standard semantic quantifier elimination argument (see e.g. \cite[Paragraph 2.27]{Cha11}). For convenience, we denote by $\mathcal{P}$ the sort $\Bool{I}{I}$. 
    To prove quantifier elimination relative to $\mathcal{P}$, consider:
    \begin{itemize}
        \item $\mathcal{M}=(\mathcal{G}_\mathcal{M},\mathcal{P}_\mathcal{M})$ and $\mathcal{N}=(\mathcal{G}_\mathcal{N},\mathcal{P}_\mathcal{N})$, two models of $\Th(\mathcal{G})$, such that $\mathcal{N}$ is $\aleph_0$-saturated,
        \item two finitely generated (and therefore finite) substructures $\mathcal{A}=(\mathcal{G}_A,\mathcal{P}_A) \subseteq \mathcal{M}$ and $\mathcal{B}=(\mathcal{G}_B,\mathcal{P}_B) \subseteq \mathcal{N}$,
        \item a partial isomorphism 
    \[
    f=(f_{\mathcal{G}},f_\mathcal{P}):\mathcal{A}\rightarrow \mathcal{B},
    \] 
    such that  $f_\mathcal{P}$ is elementary. 
    \end{itemize}
    We need to show that, for all $a\in \mathcal{M}$, we can extend $f$ to a partial isomorphism $\tilde{f}=(\tilde{f}_{\mathcal{G}},\tilde{f}_\mathcal{P})$ with $\tilde{f}_\mathcal{P}$ elementary, and with domain containing $a$.

	We can extend $f_{\mathcal{P}}$ to a full embedding $g: \mathcal{P}_\mathcal{M} \rightarrow \mathcal{P}_{\mathcal{N}}$.
	Notice that the sort $\mathcal{P}$ is closed: there are no function symbol in the language from $\mathcal{P}$ to $\mathcal{M}$. It follows therefore automatically that $f \cup  g: (\mathcal{G}_A,\mathcal{P}_\mathcal{M}) \rightarrow (\mathcal{G}_B,\mathcal{P}_\mathcal{N})$ is a partial isomorphism.

	Consider $a\in \mathcal{G}_{\mathcal{M}} \setminus \mathcal{G}_A$. We will give a concrete partition $I_1\sqcup \cdots \sqcup I_7$ of the top element of $\mathcal{P}_\mathcal{M}$, $I_i\in \mathcal{P}_\mathcal{M}$. For $i\leq 7$, we will denote by $a_i$ the element in of $\mathcal{G}_{\mathcal{M}}$ such that:
    \begin{itemize}
        \item $\supp(a_i) \subseteq I_i$,
        \item $\supp(a^{-1}\cdot a_i) \subseteq I_i^\complement$.
    \end{itemize}
    (we can identify $a_i$ with $a\restriction I_i$).
    Then, for each $i\leq 7$, we will find a correct answer ${b}_i$ for $a_i$: for all formulas $\phi(x,a',I) \in \qftp(a_i/\mathcal{A})$, we have $\mathcal{N}\models \phi({b}_i,f(a'),g(I)) $. Then we can conclude by patching that there is a good answer $b$ for $a$ i.e. such that $f(\qftp(a/\mathcal{A})) = \qftp(b/\mathcal{B})$. 


	\subsubsection*{Case 1:} Consider $I_1=\supp(\mathcal{G}_A)^\complement \cap \supp_2(a)$ where $\supp(\mathcal{G}_A) = \bigcup_{a'\in \mathcal{G}_A} \supp(a')$. Set $f({a}_1)$ to be any $2$-torsion element $b_1$ of $\mathcal{N}$ such that $\supp(b) = g(I_1)$.


	\subsubsection*{Case 2:} 
	Consider $I_2=\supp(\mathcal{G}_A)^\complement \cap \supp_3(a)$. Set $f({a}_2)$ any $3$-torsion element $b_2$ of $\mathcal{N}$ such that $\supp(b_2)=g(I_2)$.


	\subsubsection*{Case 3:}
	For $a'\in \mathcal{G}_A$, $I_{3,a'}= \supp(a'a^{-1})^c$. This is the part of $\mathcal{P}_\mathcal{M}$ where $a'$ and $a$ coincide. Set ${b}_{3,a'}$ of support $g(I_{3,a'})$ such that $\supp(f(a')^{-1}\cdot {b}_{3,a'}) \subseteq g(I_{3,a'})^\complement$ ( 
    i.e. ${b}_{3,a'}$ can be identified with ${f(a')}\restriction{g(I_{3,a'})}$). Set $I_3= \bigcup_{a'\in \mathcal{G}_A} I_{3,a'}$. 
	 By saturation, compactness and the patching property, we find ${b}_3$ in $\mathcal{N}$ such that for all $a'\in \mathcal{G}_A$, ${b}_3\restriction g(I_{3,a'})={a'}\restriction{g(I_{3,a'})}$.


	\subsubsection*{Case 4:} 
	Let $a' \in \mathcal{G}_A$. Set $I_{4,a'}=\supp_3(a) \cap I_3^\complement \cap \supp_3(a')$. This is a part of $\mathcal{P}$ where $a'$ and $a$ are both $3$-cycle, but do not coincide. In particular, we have ${a}\restriction{I_{4,a'}}= ({a'}\restriction{I_{4,a'}})^2$ and we need to have ${b}\restriction{g(I_{4,a'})}= {f(a')^2}\restriction{g(I_{4,a'})}$ for all such $a'$.
    Set $I_4= \bigcup_{a'\in \mathcal{G}_A} I_{4,a'}$. By saturation, compactness and the patching property, we find ${b}_4$ in $\mathcal{N}$ such that for all $a'\in \mathcal{G}_A$, ${b}_4\restriction {g(I_{4,a'})}={f(a')^2}\restriction{g(I_{4,a'})}$.

	\subsubsection*{Case 5:} 
	Let $a',a'' \in \mathcal{G}_A$. Set $I_{5,a',a''}=\supp_2{a} \cap I_3^\complement \cap \supp_2(a') \cap \supp_3(a'') \cap (\supp({a''}a'a))^\complement$.
	This is the part of $\mathcal{P}$ where $a$ is a $2$-cycle, $a'$ is another $2$-cycle, $a''$ is a $3$-cycle  and  $a$ is equal to $a''a'$ . 
    We need that ${b}\restriction{g(I_{5,a',a''})}= {f(a'')}\restriction{g(I_{5,a',a''})}\cdot {f(a')}\restriction{g(I_{5,a',a''})}.$

	Set $I_5= \bigcup_{a',a''\in \mathcal{G}_A} I_{5,a',a''}$. By saturation, compactness and patching, we find ${b}_5$ in $\mathcal{N}$ with support included in $g(I_5)$ such that for all $a',a''\in \mathcal{G}_A$, \[ {b}_5\restriction{g(I_{5,a',a''})}={f(a'')}\restriction{g(I_{5,a',a''})}\cdot {f(a')}\restriction{g(I_{5,a',a''})}.\]

	\subsubsection*{Case 6:} 
	Let $a',a'' \in \mathcal{G}_A$. Set $I_{6,a',a''}=\supp_2(a) \cap I_3^\complement \cap \supp_2(a') \cap \supp_2(a'') \cap \supp(aa'a''a')^\complement$.
	This is the part of $\mathcal{P}$ where $a$ is a  $2$-cycle, and $a',a''\in \mathcal{G}_A$ are the other two $2$-cycles and $a$ coincides with $a'a''a'^{-1}=a'a''a'$.
	We need to have: 
    \[{b}\restriction{g(I_{6,a',a''})}= f(a')f(a'')f(a')\restriction{g(I_{6,a',a''})}. \]
    for all such $a',a''$.
	Set $I_6= \bigcup_{a',a''\in \mathcal{G}_A} I_{6,a',a''}$. By saturation, compactness and the patching property, we find ${b}_6$ in $\mathcal{N}$ with support included in $g(I_6)$ such that for all $a',a''\in \mathcal{G}_A$, 
    \[ {b}_6\restriction{g(I_{6,a',a''})}=f(a')f(a'')f(a') \restriction {g(I_{6,a',a''})}.\]

	\subsubsection*{Case 7:}
	Let $a' \in \mathcal{G}_A$. Set $I_{7,a'}=\supp_2{a} \cap I_3^\complement \cap \supp_2(a') \cap (I_6)^\complement$. This is the part of the support where $a$ is a $2$-cycle, $a'\in \mathcal{G}_A$ is another $2$-cycle but $a'aa'$ is not in $\mathcal{G}_A$.
	Then ${b}\restriction{g(I_{7,a'})}$ needs (and only needs) to be a two torsion element $\alpha_{a'}$ with support $g(I_{7,a'})$ which is nowhere equal element to $f(a')$ on $g(I_{7,a'})$.  
	Set $I_7= \bigcup_{a'\in \mathcal{G}_A} I_{7,a'}$. By saturation, compactness and patching, we find ${b}_7$ in $\mathcal{N}$ such that for all $a'\in \mathcal{G}_A$, ${b}_7 \restriction {g(I_{7,a'})}=\alpha_{a'} \restriction{g(I_{7,a'})}$.

\vspace{.1in}

    Set $b$ to be the unique element such that $b\restriction{g(I_i)}=b_i\restriction{g(I_i)}$ for $i\leq 7$. 
    One can observe easily that $\bigcup I_i$ is a partition of $\mathcal{P}_\mathcal{M}$ definable over $a$ and $\mathcal{G}_{A}$. Since we have for all $i\leq 7$, $f(\qftp(a_i/\mathcal{A})) = \qftp(b_i/\mathcal{B})$, we also have $f(\qftp(a/\mathcal{A})) = \qftp(b/\mathcal{B})$. Therefore $f\cup \{(a,b)\}$ extends the partial isomorphism and this concludes the proof.  
\end{proof}


\section{Groups not recognizing coordinates}
\label{S.GroupsNotRecognizing}
\subsection{General criteria for not recognizing coordinates}
\label{S.NotRecognizing}


\begin{theorem}\label{Fact:construction}
	Suppose that $\fC$ is a class of groups that satisfies one of the following two conditions. 
	\begin{enumerate}
		\item \label{1.construction} It contains groups $G$ and $H$ and a nontrivial homomorphism $f\colon G\to Z(H)$.
		\item \label{2.construction} It contains a group that  is decomposable as a direct product of nontrivial groups. 
	\end{enumerate}  
	Then $\fC$ does not recognize coordinates
\end{theorem}

The converse of this theorem does not hold. Namely, there is a family $\fD$ of groups that  fails both \eqref{1.construction} and \eqref{2.construction} of Theorem~\ref{Fact:construction} but it does not recognize coordinates (see  Theorem~\ref{T.Limiting}). 
The sufficiency of the second condition is obvious, and the 
proof  of the sufficiency of the first uses the following obvious lemma. 

\begin{lemma} Suppose that $T$ recognizes coordinates. Consider $\theta: \prod \mathcal{M}_i \to \prod \mathcal{N}_i$ an isomorphism between (non-reduced) products. If $\vert \supp(a) \vert$ is finite, then $|\supp(\theta(a))| = |\supp(a)|$. 
\end{lemma}
\begin{proof}
    By \Cref{T.InterpretingSupport}, the support map is interpretable. In particular, the set $\{a \mid |\supp(a)| =n\}$ is definable and thus preserved by isomorphisms.
\end{proof}


\begin{proof}[Proof of Theorem~\ref{Fact:construction}] Here, we simply quotient out by the trivial ideal. Consider the map $\tau_{f}: G \times H \to G \times H$ defined via $\tau_{f}((a,b)) = (a,f(a)b)$. Then $\tau_{f}$ is an automorphism of $G \times H$. 
	\begin{enumerate}
		\item Homomorphism: Notice that 
		\begin{align*}
			\tau_{f}((a,b)(c,d)) &= \tau_{f}((ac,bd)) = (ac,f(ac)bd)\\ &= (ac,f(a)bf(c)d) = (a,f(a)b)(c,f(c)d) \\ 
			&= \tau_{f}((a,b)) \tau_{f}((c,d)). 
		\end{align*}
		\item Injective: Suppose that $\tau_{f}((a,b)) = \bar{e}$. Then $(a,af(b)) = (e,e)$. Hence $a = e$ and so $e = f(a)b = f(e)b = b$. It follows that $\tau_{f}$ is injective.
		\item Surjective: Fix $(a,b) \in G \times G$. Then 
		\begin{equation*}
			\tau_{f}(a,f(a)^{-1}b) = (a,b). 
		\end{equation*}
	\end{enumerate} 
	In particular, this allows us to build an automorphism $\Sigma_{f}: \prod_{i\in \bbN} (G\times H)$ via $\Sigma_{f}((a_i,b_i)_{i \in \mathbb{N}}) = (a_i,f(a_i)b_i)_{i\in \bbN}$. Since $f$ is non-trivial, we can find some $a_* \in G$ such that $f(a_*) \neq e$. Then with $a_i=a_*$ for all $i$ and arbitrary $b\in G$ we have 
	\begin{equation*}
		\Sigma_{f}((a_i,b_i)_i)) \neq (a_i,b_i)_{i\in \bbN}. 
	\end{equation*}
	Moreover,  		$\Sigma_f$ is an automorphism of $\prod_{i\in \bbN} (G\times H)$ and its restriction to  $\bigoplus_{i\in \bbN} (G\times H)$ is an automorphism of $\bigoplus_{i\in \bbN} (G\times H)$. It therefore lifts an automorphism of the quotient $\prod_{\Fin} (G\times H)$. 
\end{proof}


\subsection{Classes of groups that do not recognize coordinates}

\begin{theorem}\label{T.eDNR} 
 Any class of groups that contains some of the following does not recognize coordinates. 
\begin{enumerate}[label=(\alph*)]
	\item  Any product of nontrivial groups. 
	\item   Groups $G$ and $H$ such that $G$ admits a non-trivial homomorphism into the center of $H$. 
	\item  Group $\GL(n,F)$ for $n\geq 2$ and any field $F$.
	\item   Group $Q_{8} = \langle -1,i,j,k: (-1)^{2} = e, i^{2} = j^{2} = k^{2} =ijk = -1  \rangle$. 
	\item  The dihedral group $D_{2n}$  of the $2n$-gon for $n\geq 1$. 
	\item  Any nilpotent group. 
	\item  Any nontrivial graph product $\Gamma\cG$ such that the complement graph $\bar\Gamma$ is not connected (see \S\ref{S.GraphProducts}). 
	\item  Any class of groups that contains $\Sym_3$ and $\SL(2,5)$.
\end{enumerate} 
\end{theorem}


\begin{proof}
\ref{DNR.abelian} follows by Theorem~\ref{Fact:construction}. 

%By Theorem~\ref{Fact:construction}, it suffices to find a nontrivial homomorphism into the centre of the given group. 

\ref{DNR.decomposable} This is Theorem~\ref{Fact:construction} \eqref{2.construction}. 

\ref{DNR.GLn} Compose the determinant map with the map that sends scalars to scalar matrices. 

\ref{DNR.Q8}
Recall that $Z(Q_{8}) = \{\pm 1\} \cong \mathbb{Z}/2\mathbb{Z}$. 
For any $l\in \{i,j,k\}$, we have a homomorphism $\alpha_{l}: Q_{8} \to Z(Q_8) $ via
\begin{equation*}
	\alpha_{l}(d)=\begin{cases}
		\begin{array}{cc}
			1 & d=l, -l, 1,-1\\
