It is relatively easy to define various copies of Boolean algebra $\Bool{I}{I}$. With a small trick, we can interprets the support function. %It looks however harder to identify them in the structure. %After identification, we can properly interprets the relative support function.
\begin{proof}
	%To show that $\Sh$ interprets the support function $\supp_=$, it is enough to show that the formula $x=t \rightarrow y=t$ is equivalent to an $h$-formula in $\mathfrak{M}$. 
	To show that $\Sh$ interprets the support function $\supp_=$, it is enough to show by \Cref{T.eq} that the formula $x=t \rightarrow y=t$ is equivalent to an $h$-formula in $\mathfrak{M}$. 
	Fix $t\in \mathfrak{M}$. We denote by $L(t)$ the element $s$ losing against $t$, i.e. such that $s\neq t$ and $s\cdot t = t$. The following shows that $t\mapsto L(t)$ is defined by the $h$-formula:
	\[L(t)=t' \quad  \Leftrightarrow \quad t'\cdot t = t \wedge \forall s' ~s'\cdot t = t \rightarrow t'\cdot s' = s'.\]

	We see that $x=t \rightarrow y=t$ is equivalent to 
	\[\tag{*}\label{eq.RPS}(x\cdot L(t))\cdot (y\cdot L(t))=(y\cdot L(t))\]
	Indeed, if  (\ref{eq.RPS}) holds and $x=t$, then we have \begin{align*}
		&\quad (x\cdot L(t))\cdot (y\cdot L(t))=(y\cdot L(t))\\
		\Leftrightarrow &\quad (t\cdot L(t))\cdot (y\cdot L(t))=(y\cdot L(t))\\
		\Leftrightarrow& \quad t\cdot (y\cdot L(t))=(y\cdot L(t)).\\
		%   \Leftrightarrow& \quad t=(y\cdot L(t))
		%   \\
		%   \Leftrightarrow& \quad t=y
	\end{align*}
	Then, since  $y\cdot L(t)$ is either $t$ or $L(t)$, we have:
	\[ \quad t\cdot (y\cdot L(t))=(y\cdot L(t))\Leftrightarrow t=(y\cdot L(t)) \Leftrightarrow t=y.\]
	Conversely, assume $x=t \rightarrow y=t$, and we need to show that (\ref{eq.RPS}) holds. If $y=t$, then $(y\cdot L(t))=t$, and since $(x\cdot L(t))$ is either $t$ or $L(t)$, we have
	\[(x\cdot L(t))\cdot (y\cdot L(t))= t = (y\cdot L(t))\]
	and (\ref{eq.RPS}) holds. If $x\neq t$, then $(x\cdot L(t))=L(t)$ and (\ref{eq.RPS}) also clearly holds. 

	At the end, we get that the formula $x=t \rightarrow y=t$ is equivalent to the formula:
	\[(\exists s) ~\left[s\cdot t = t \wedge (\forall s') ~(s'\cdot t = t \rightarrow s\cdot s' = s') \wedge (x\cdot s)\cdot (y\cdot s)=(y\cdot s) \right].\]

	This is clearly (equivalent to) an $h$-formula since $(\exists s') ~s'\cdot t = t $ always holds.
\end{proof}

By \Cref{T.A}, we have:

\begin{corollary}
	The magma $\mathfrak{M}$ recognizes coordinates.
\end{corollary}

Finally, we notice that every (parameter-free) formulas in $\mathfrak{M}$ are equivalent to a Boolean combination of (quantifier-free) atomic formulas in the language $(\mathfrak{M},\cdot,L)$. It follows that any reduced power $\Sh$ of $\mathfrak{M}$, $\{(\Sh,\cdot),(\Bool{I}{I},\subseteq), \supp_= \}$ is a definable expansion of the magma $
(\Sh,\cdot)$ and by \Cref{C.QuestionDecomp}:

\begin{corollary}
	Any reduced power $\Sh= \prod_\Ideal{I} \mathfrak{M}$ of the magma $\mathfrak{M}$ eliminates quantifiers relative to $\Bool{I}{I}$ in the following interpretable language:
    \[\{(\Sh,\cdot,L),(\Bool{I}{I},\subseteq), \supp_= \}.\]
\end{corollary}


