\section{Proof of Theorem \ref{mainthm}}\label{sec:pf_mainthm} 
%\setcounter{lemma}{0}
\begin{proof}
    Fix $a \in [p]$. We have $n$ i.i.d copies of matrix-valued data $\bX^{(1)}, \ldots, \bX^{(n)} \sim \mathcal{MN}_{p, q}(\bzero, \bU,\bV)$, and write
    $(\bX^{(i)})^\top = \left(X^{(i)}_{a}, \bX^{(i)}_{(a)}\right)$.
    Let $\bbX=(\bX^{(1)}, \ldots, \bX^{(n)})^\top = (\bbX_a, \bbX_{(a)}) \in \mathbb{R}^{nq \times p}$ be the vectorized data matrix, where $\bbX_a$ is the $nq \times 1$ vector obtained by stacking the $a$-th rows of each matrix data, and $\bbX_{(a)}$ is the $nq \times (p-1)$ matrix obtained by removing those rows and stack. For notational convenience, set $S=\mathcal{N}(a)$, $\bGamma=\text{tr}(\bV)/q \cdot \bU_{(a),(a)}$, and $\hat{\bGamma}=\bbX_{(a)}^{\top}\bbX_{(a)}/nq$ so that $\mathbb{E}[\hat{\bGamma}]=\bGamma$. As we noted in Section \ref{subsection:method}, we consider the standard lasso estimator: $$\hat{\theta} \in \argmin_{\theta \in \mathbb{R}^{p-1}} \left\{  \frac{1}{2n} \Vert \bbX_a - \bbX_{(a)}\theta \Vert_2^2 +\lambda \Vert \theta \Vert_1\right\}.$$

\subsection{Proof of Assertion (i) of Theorem \ref{mainthm}}
To prove (i), we employ the primal-dual witness argument of \citet{wainwright2019high}. Specifically, we seek an optimal primal-dual pair $(\hat{\theta}, \hat{z})$ that satisfies $\bbX_{(a)}^\top (\bbX_{(a)} \hat{\theta}-\bbX_a)/n+\lambda\hat{z} = 0$. 
A straightforward calculation shows 
\begin{align*}
\hat{z}_{S^c} = \underbrace{\bbX^\top_{S^c}\bbX_S(\bbX^\top_S \bbX_S)^{-1}\hat{z}_S}_{=:\ \mu} + \underbrace{\bbX^\top_{S^c}(\text{I}-\bPi_S) \frac{\epsilon}{nq \lambda}}_{=:\ T_{S^c}}
\end{align*}
where $\hat{z}^\top = (\hat{z}_S^\top, \hat{z}_{S^c}^\top)$ and $\bPi_S=\bbX_S(\bbX_S ^\top \bbX_S)^{-1}\bbX_S^\top$.

We first claim that $\Vert \hat{z}_{S^c} \Vert _{\infty} < 1$ holds with high probability. Lemma 7.23 in \citet{wainwright2019high} states that if the minimum eigenvalue of $\hat{\bGamma}_{SS}=\bbX_S^\top \bbX_S/nq$ is bounded away from zero, then $\Vert \hat{z}_{S^c} \Vert _{\infty} < 1$ implies $\hat{\theta}_{S^c}=0$, which in turn gives $\widehat{\mathcal{N}}(a) \subseteq \mathcal{N}(a)$. Then we complete the proof of (i) by applying a union bound over all $a \in [p]$, as will be discussed later.

\subsubsection*{Probabilistic Bound of $\mu$}
Since $(\bX_{S,j}^\top, \bX_{S^c,j}^\top)^\top \sim \mathcal{N}(0,v_{jj}\bU_{(a),(a)})$ for every $j \in [q]$, we can write 
$$
\bX^{(i)}_{S^c,j}=\bGamma_{S^cS}(\bGamma_{SS})^{-1}\bX^{(i)}_{S,j} + \Tilde{W}^{(i)}_{S^c,j} \in \mathbb{R}^{p-1-s}.
$$
By stacking these vectors appropriately, we obtain $\bX^{(i)}_{S^c}=\bGamma_{S^cS}(\bGamma_{SS})^{-1}\bX^{(i)}_{S} + \Tilde{\bW}^{(i)}_{S^c}$,
and hence
\begin{align}\label{decomposition}
	\bbX^\top_{S^c}=\bGamma_{S^cS}(\bGamma_{SS})^{-1}\bbX^\top_S + \Tilde{\bW}^\top_{S^c},
\end{align}
where $\Tilde{\bW}_{S^c} \in \mathbb{R}^{nq \times (p-1-s)}$ is a zero-mean Gaussian random matrix independent of $\bbX_S$. Substituting \eqref{decomposition} gives
\begin{align*}      
    \Vert \mu \Vert _{\infty}&\leq  \Vert \bGamma_{S^cS}(\bGamma_{SS})^{-1}\hat{z}_S \Vert _{\infty}+ \left\lVert \frac{\Tilde{\bW}^\top_{S^c}\bbX_S}{nq}(\hat{\bGamma}_{SS})^{-1}\hat{z}_S \right\rVert _{\infty}\\
	&\leq (1-\alpha) + \Biggl\lVert  \underbrace{\frac{\Tilde{\bW}^\top_{S^c}\bbX_S}{nq}(\hat{\bGamma}_{SS})^{-1}\hat{z}_S}_{=:R} \Biggr\rVert_{\infty}
 \end{align*}
by Assumption \ref{assum:alpha} (recall the definition of $\bGamma$).

Since $\Tilde{\bW}^\top_{S^c} \indep \bbX_S$, the conditioned $R | \bbX_S$ follows the mean zero Gaussian distribution.
Let $r_k=e_k^\top R$ denote the $k$-th entry of $R$ for each $k \in S^c$, and define $b_S:=\bbX_S(\hat{\bGamma}_{SS})^{-1} \hat{z}_S / \sqrt{nq}$. 
Then since $r_k=e_k^\top R= \Tilde{W}_k^\top b_S/\sqrt{nq}$, we have
\begin{align*}
	\text{Var}(r_k | \bbX_S)=\frac{1}{nq}\text{Var}(b_S^{\top} \Tilde{W}_k)=\frac{1}{nq}b_S^{\top} \text{Var}(\Tilde{W}_k) b_S
	\leq \frac{1}{nq} \Vert b_S \Vert _2^2  \Vert \text{Var}(\Tilde{W}_k) \Vert _2.
\end{align*}
Now observe that $\Tilde{W}_k = (\Tilde{W}_{k,1}^{(1)}, \ldots, \Tilde{W}_{k,q}^{(1)}, \ldots, \Tilde{W}_{k,1}^{(n)}, \ldots, \Tilde{W}_{k,q}^{(n)})^\top$. Also, one can verify that 
$$
\text{Cov}(\Tilde{W}_{k,l}^{(i)}, \Tilde{W}_{k,m}^{(j)})=\delta_{ij}(u_{kk}-\bU_{kS}\bU_{SS}^{-1}\bU_{Sk})v_{lm}
$$ 
where $\delta_{ij}$ denotes Kronecker delta. Combining these facts, we obtain 
$$
\text{Var}(\Tilde{W}_k)=(u_{kk}-\bU_{kS}\bU_{SS}^{-1}\bU_{Sk})\cdot \diag_{n}(\bV).
$$
Since $\bU_{SS}^{-1}$ is positive definite, it follows $u_{kk}-\bU_{kS}\bU_{SS}^{-1}\bU_{Sk} \leq u_{kk}$. Moreover, $\bV$ and $\diag_n(\bV)$ share the same eigenvalues. Taken together, we conclude that $ \Vert \text{Var}(\Tilde{W}_k) \Vert _2 \leq  u_{kk} \Vert \bV \Vert _2$.

Now the uniform upper bound for the conditional variances holds for all $k \in [p]$:
\begin{align}
	\sqrt{\text{Var}(r_k|\bbX_S)} &= \sqrt{\frac{ u_{kk} \Vert \bV \Vert _2}{nq}} \left\lVert \frac{\bbX_S}{\sqrt{nq}}\hat{\bGamma}_{SS}^{-1}\hat{z}_S \right\rVert _2 \nonumber\\
	&\leq \sqrt{\frac{ u_{kk} \Vert \bV \Vert _2}{nq}} \left\lVert \frac{\bbX_S}{\sqrt{nq}}\hat{\bGamma}_{SS}^{-1} \right\rVert _2\cdot  \Vert \hat{z}_S \Vert _2 \nonumber\\
	&\leq \sqrt{\frac{ u_{kk} \Vert \bV \Vert _2}{nq}}\sqrt{ \Vert \hat{\bGamma}_{SS}^{-1} \Vert _2}\cdot \sqrt{d_{\max}} \label{vb3}\\
	&\leq \sqrt{\frac{2d_{\max}}{nq \lambda_{\min}^U v_{\text{avg}}}\cdot u_{\max} \Vert \bV \Vert _2}. \label{vb4}
\end{align}
Inequality \eqref{vb3} follows from Assumption \ref{assum:sparse}, while \eqref{vb4} holds with high probability by the following fact:
\begin{fact}\label{fact:minimumeigenvalue}
    Let $E_{1a} : = \{ \Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2 \le \lambda_{\min}^Uv_{\text{avg}}/2\}$. On $E_{1a}$, we have
    \begin{align}\label{eq:minimumeigenvalue}
        \Vert \hat{\bGamma}_{SS}^{-1} \Vert _2 \leq \frac{2}{\lambda_{\min}^Uv_{\text{avg}}}.
    \end{align}
    Moreover, $E_{1a}$ holds with probability at least $1-3d_{\max}/p^\beta$ for any $beta>0$, under either condition \eqref{eq:dim_cond1} or \eqref{eq:dim_cond2}.
\end{fact}
\noindent
The proof of Fact~\ref{fact:minimumeigenvalue} is deferred to Section \ref{sec:pf_minimumeigenvalue}. As a consequence, by applying the Gaussian tail property and a union bound, we have
\begin{align*}
    &\mathbb{P}( \Vert R \Vert _{\infty} \geq t) 
    \leq \mathbb{P}(\max_{k \in S^c} \vert r_k \vert  \geq t |\ E_{1a}) + \mathbb{P}(E_{1a}^c)\\
    &\leq 2|S^c|\exp \left( -\frac{nq \lambda_{\min}^U v_{\text{avg}} t^2}{4d_{\max} \cdot u_{\max} \Vert \bV \Vert _2} \right) +\mathbb{P}(E_{1a}^c)\\
    &\leq 2p \exp \left(-\frac{nq\lambda_{\min}^U v_{\text{avg}} t^2}{4d_{\max}\cdot u_{\max} \Vert \bV \Vert _2}\right)+\mathbb{P}(E_{1a}^c).
\end{align*}
For any fixed $\beta > 1$, by taking $t=\alpha/4$, we have
\begin{align*} 
    \mathbb{P}\left( \Vert R \Vert _{\infty} \geq \frac{\alpha}{4} \ |\ E_{1a}\right) \leq 2p \exp \left( -\frac{\lambda_{\min}^Uv_{\text{avg}} nq \alpha^2}{64d_{\max}\cdot u_{\max} \Vert \bV \Vert _2 }\right)  \leq \frac{2}{p^{\beta}},
\end{align*}
provided that 
\begin{align} \label{eq:dim1}
    \frac{nq}{\log p} \geq (1+\beta)\frac{64d_{\max} \cdot u_{\max} \Vert \bV \Vert _2}{\lambda_{\min}^Uv_{\text{avg}} \alpha^2}.
\end{align}
Combining everything, we conclude
\begin{align}\nonumber
	\mathbb{P}\left( \Vert \mu \Vert _{\infty} \geq 1-\frac{3}{4}\alpha \right) \leq\  \mathbb{P}\left( \Vert R \Vert _{\infty} \geq \frac{\alpha}{4}\right) 
    \leq \frac{3d_{\max}+2}{p^{\beta}},
\end{align}
as long as either (i) \eqref{eq:dim1} and \eqref{eq:dim_cond1}, or (ii) \eqref{eq:dim1} and \eqref{eq:dim_cond2} are satisfied.

