\subsubsection*{Probabilistic Bound of $T_{S^c}$}

Recall that $T_{S^c}=\bbX^\top_{S^c}(\text{I}-\bPi_S)\epsilon/(nq \lambda)$. Using the decomposition \eqref{decomposition} and the fact $\bbX_S^\top(\text{I}-\bPi_S)=0$, we have $T_{S^c}=\Tilde{\bW}_{S^c}^\top(\text{I}-\bPi_S)\epsilon/(nq \lambda)$.
To apply the same arguments leading to \eqref{vb4}, we need a probabilistic bound on $ \Vert (\text{I}-\bPi_S)\epsilon \Vert _2$. Since $\text{I}-\bPi_S$ is a projection, we get $\Vert (\text{I}-\bPi_S)\epsilon \Vert _2 \leq  \Vert \epsilon \Vert _2$. Therefore, it remains to bound $\mathbb{P}( \Vert \epsilon \Vert _2 \geq t)$.

By the model assumption, for each $i \in [n], j \in [q]$, we have $X^{(i)}_{a,j}=X^{(i)}_{(a),j}\theta^*+\epsilon^{(i)}_j$. Since $X^{(i)}_j \sim \mathcal{N}_q(0,v_{jj}\bU)$, one can check $\text{Var}(\epsilon^{(i)}_j)=v_{jj}(u_{aa}-\bU_{a,(a)}(\bU_{(a),(a)})^{-1}\bU_{(a),a})$, or equivalently
$$
\text{Var}(\epsilon^{(i)})=(u_{aa}-\bU_{a,(a)}(\bU_{(a),(a)})^{-1}\bU_{(a),a})\bV =: \bV^{*}.
$$
Thus we can write $\epsilon^{(i)}\overset{d}{=}{\bV^*}^{1/2}Z^{(i)}$  with 
$Z^{(i)} \overset {\mathrm{i.i.d.}}{\sim} \mathcal{N}_q(0,I_q)$. Let
$\Tilde{Z}=(Z^{(1)},\dots,Z^{(n)})^\top$ and
$\Tilde{\bV}^*=\diag_n(\bV^*)$, then the squared norm becomes
\begin{align*}
	\Vert \epsilon \Vert _2^2 = \sum_{i=1}^n ({\epsilon^{(i)}})^\top \epsilon^{(i)}
	{\buildrel d \over =} \sum_{i=1}^n ({Z^{(i)}})^\top \bV^{*} Z^{(i)} 
	= \Tilde{Z}^\top \Tilde{\bV}^* \Tilde{Z}.
\end{align*}
By the Hanson–Wright inequality \citep{rudelson2013hanson}, for any $s>0$,
\begin{align}\label{eq:HWineq}
	\mathbb{P}( \Vert \epsilon \Vert _2^2 \geq \text{tr}(\Tilde{\bV}^*)+s) \leq&\ 2 \exp\Bigl( -c \min\bigl(\frac{s}{ \Vert \Tilde{\bV^*} \Vert _2}, \frac{s^2}{ \Vert \Tilde{\bV^*} \Vert _F^2}\bigr)\Bigr)  \\
    \leq &\ 2 \exp\Bigl( -c \min\bigl(\frac{s}{ u_{aa} \Vert \bV \Vert _2}, \frac{s^2}{n q u_{aa}^2  \Vert \bV \Vert_2^2}\bigr)\Bigr), \nonumber
\end{align}
where we used $u_{aa}-\bU_{a,(a)}(\bU_{(a),(a)})^{-1}\bU_{(a),a} \leq u_{aa}$ and $\Vert \bV \Vert _F^2 \leq q \Vert \bV \Vert_2^2$.
Setting $s=nq u_{aa} v_{\text{avg}}$ and since $\text{tr}(\Tilde{\bV^*}) \leq nu_{aa}\text{tr}(\bV) = nq u_{aa} v_{\text{avg}}$ and 
$v_{\text{avg}} \leq \Vert \bV \Vert_2$, we get 
$$
\mathbb{P}\bigl(\|\epsilon\|_2 \ge \sqrt{2nq\,u_{aa}\,v_{\text{avg}}} \bigr)
 \leq\ 2 \exp\Bigl( -c \cdot nq \min\left(\frac{v_{\text{avg}}}{ \Vert \bV \Vert _2}, \frac{v_{\text{avg}}^2}{ \Vert \bV \Vert _2^2}\right)\Bigr)\\
\le 2 \exp\Bigl( -c \cdot nq \frac{v_{\text{avg}}^2}{ \Vert \bV \Vert _2^2} \Bigr).
$$
Therefore, the event $E_{2a}:=\{ \Vert \epsilon \Vert _2 \leq \sqrt{2nq\, u_{aa}\, v_{\text{avg}}}\}$ satisfies $\mathbb{P}(E_{2a}^c) \leq 2/p^{\beta}$ whenever
\begin{align} \label{eq:dim2}
    \frac{nq}{\log p} \geq \frac{\beta\, \Vert \bV \Vert _2^2}{c\, v_{\text{avg}}^2}.
\end{align}

Since $\Tilde{\bW}_{S^c}^\top$ and $\epsilon$ are independent, $T_{S^c}|\epsilon$ follows the centered normal distribution. Denote its $k$\-th component by $t_k := e_k^\top T_{S^c}=\Tilde{W}_k^\top(\text{I}-\bPi_S)\epsilon/(nq\lambda)$ . On $E_{2a}$, its conditional variance satisfies
\begin{align*}
	\text{Var}(t_k|\epsilon)=&\ \frac{1}{(nq\lambda)^2}((\text{I}-\bPi_S)\epsilon)^\top \text{Var}(\Tilde{W}_k) (\text{I}-\bPi_S) \epsilon
	\leq\ \frac{1}{(nq\lambda)^2} \Vert (\text{I}-\bPi_S)\epsilon \Vert _2^2  \Vert \text{Var}(\Tilde{W}_k) \Vert _2\\
	\leq&\ \frac{1}{(nq\lambda)^2} \Vert \epsilon \Vert _2^2 u_{kk} \Vert \bV \Vert _2
	\leq\ \frac{2}{nq\lambda^2} u_{aa}u_{kk} v_{\text{avg}} \Vert \bV \Vert _2.
\end{align*}
By the Gaussian tail bound and a union bound, we obtain
$$
\mathbb{P}( \Vert T_{S^c} \Vert _{\infty} \geq t) \leq \mathbb{P} \bigl(\max_{k \in S^c} \vert t_k \vert  \geq t \ |\ E_{2a} \bigr) + \mathbb{P}(E_{2a}^c) \leq 2|S^c|\exp \left(-\frac{nq\lambda^2 t^2}{4 u_{\max}^2 v_{\text{avg}} \Vert \bV \Vert _2} \right)+\mathbb{P}(E_{2a}^c).
$$
Setting $t=\alpha/4$ , we get
\begin{align*}
    \mathbb{P}\left( \Vert T_{S^c} \Vert _{\infty} \geq \frac{\alpha}{4} \right) \leq 2p \exp \left(-\frac{nq\lambda^2 \alpha^2}{64 u_{\max}^2 v_{\text{avg}} \Vert \bV \Vert _2} \right) +\mathbb{P}(E_{2a}^c).
\end{align*}
Finally, if \eqref{eq:dim2} and 
\begin{align} \label{lambdacond1}
        \lambda \geq \frac{1}{\alpha}\sqrt{\frac{\log p}{nq}(1+\beta)\cdot 64u_{\max}^2 v_{\text{avg}} \Vert \bV \Vert _2},
\end{align}
holds, we get $\mathbb{P}( \Vert T_{S^c} \Vert _{\infty} \geq \alpha/4) \le 4/p^\beta$.


\subsubsection*{Combining Pieces Together}
Putting everything together, we deduce that for any $\beta>1$,
\begin{align}\label{eq:zbound}
        \mathbb{P}\left( \Vert \hat{z}_{S^c} \Vert_\infty \geq 1-\frac{\alpha}{2}\right) \leq \frac{3d_{\max}+6}{p^\beta}
\end{align}
provided that either (i) \eqref{eq:dim1} and \eqref{eq:dim_cond1} or (ii) \eqref{eq:dim1} and \eqref{eq:dim_cond2} hold together with \eqref{lambdacond1}.
As we have already proved that the minimum eigenvalue of $\hat{\bGamma}_{SS}$ is bounded away from zero on $E_{1a}$ in \eqref{eq:minimumeigenvalue}, it follows that
\begin{align*}
        \mathbb{P}\left( \widehat{\mathcal{N}}(a) \subseteq \mathcal{N}(a) \right) \geq 1-\frac{3d_{\max}+6}{p^\beta},
\end{align*}
under the same assumptions. 
Finally, taking a union bound over $a=1, \ldots, p$, we have $\hat{E} \subseteq E$ with probability larger than $1-(3d_{\max}+6)/p^{\beta-1}$, which completes the proof.



\subsubsection{Proof of Fact \ref{fact:minimumeigenvalue}}\label{sec:pf_minimumeigenvalue}
First, observe that
\begin{align} \label{b_bound}
    \Vert {\bGamma}_{SS}^{-1} \Vert _2 =\ \lambda_{\min}({\bGamma}_{SS})^{-1}
    =\ \frac{q}{\text{tr}(\bV)}\cdot\lambda_{\min}(\bU_{SS})^{-1}
    \leq \frac{1}{v_{\text{avg}} \lambda_{\min}^U}
\end{align}
Next, by using Weyl's inequality, we get
$$
\left| \frac{1}{ \Vert \hat{\bGamma}_{SS}^{-1} \Vert _2} - \frac{1}{ \Vert {\bGamma}_{SS}^{-1} \Vert _2} \right| =|\lambda_{\min}(\hat{\bGamma}_{SS}) - \lambda_{\min}({\bGamma}_{SS})| \le  \Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2.
$$
Thus, on the event $E_{1a} = \{ \Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2 \le \lambda_{\min}^Uv_{\text{avg}}/2\}$, we get
$$
\frac{1}{ \Vert \hat{\bGamma}_{SS}^{-1} \Vert _2} \ge \frac{1}{ \Vert {\bGamma}_{SS}^{-1} \Vert _2}  - \Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2 \ge \frac{\lambda_{\min}^Uv_{\text{avg}}}{2},
$$
which proves \eqref{eq:minimumeigenvalue}. 


% \subsubsection*{Probability of $E_{1a}^c$}
We now show $E_{1a}^c$ holds with high probability. By Lemma \ref{lem:Gamma_SS_dev} with $t_0 = \lambda_{\min}^U v_{\text{avg}}/(2C ||\bU||_2)$, one obtains
$$
{\rm P} \left[
\Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2 
\geq \lambda_{\min}^Uv_{\text{avg}} / 2 \right] \le 3d_{\max} \exp \bigg[
- \min \Big\{
(t_0 / a_1)^2, t_0 / a_2, (t_0 / a_3)^{2/3}
\Big\}
\bigg].
$$
where $a_1, a_2, a_3$ are as in Lemma \ref{lem:Gamma_SS_dev}. The right hand side is at most $3d_{\max}/p^\beta$ if one of the following holds:
\begin{enumerate}[label=(\roman*)]
	\item[(i)] $1/a_1 \ge (\beta \log p)^{1/2}/t_0$ and $t_0 \le \min\{ a_1^2/a_2, a_1^{3/2} / a_3^{1/2}\}$,
	\item[(ii)] $1/a_2 \ge \beta \log p/t_0$ and $ a_1^2/a_2 \le t_0 \le a_2^3/a_3^2$,
	\item[(iii)] $1/a_3 \ge (\beta \log p)^{3/2}/t_0$ and $t_0 \ge \max\{a_1^{3/2} / a_3^{1/2},  a_2^3/a_3^2\}$.
\end{enumerate}
Under the mild assumption $n (2d_{\max}/q + 1) > ||\bV||_2^2$, then all the three terms 
$$ \frac{a_1^{3/2} / a_3^{1/2}}{a_2^3/a_3^2} =  \left(\dfrac{n (2d_{\max}/q + 1)}{||\bV||_2^2} \right)^{3/4}, \ 
	\frac{a_1^2/a_2}{a_1^{3/2} / a_3^{1/2}} = \left(\dfrac{n (2d_{\max}/q + 1)}{||\bV||_2^2} \right)^{1/4}, 
	\ \frac{a_1^2/a_2}{a_2^3/a_3^2} = \dfrac{n (2d_{\max}/q + 1)}{||\bV||_2^2}
$$
are greater than $1$. Consequently, the conditions (i)-(iii) reduce to:
\begin{enumerate}[label=(\alph*)]
	\item[(a)] 
	$1/a_1 \ge (\beta \log p)^{1/2}/t_0$ and $t_0 \le a_1^{3/2} / a_3^{1/2}$,
	\item[(b)] $1/a_3 \ge (\beta \log p)^{3/2}/t_0$ and $t_0 \ge a_1^{3/2} / a_3^{1/2}$.
\end{enumerate}
The sufficient condition of (a) is that 
\begin{equation}\label{eq:dim_cond1}
	n\! \left( \frac{2d_{\max}}{q}\! + 1 \right)\! >\! ||\bV||_2^2, \ \ \frac{n}{\log p} \ge  \beta \!\left(\frac{2d_{\max}}{q}  + 1 \right)\!  \frac{||\bV||_2^2}{t_0^2}, \ \ \frac{q^2}{n} \ge \left( \frac{2d_{\max}}{q}\! +1 \right)^{-3}\! \frac{t_0^4}{||\bV||_2^2}.
\end{equation}
Similarly for the condition (b), we need
\begin{equation}\label{eq:dim_cond2}
	n \left(\frac{2d_{\max}}{q}\! + 1 \right)\! > \!||\bV||_2^2, \ \ \frac{nq}{(\log p)^{3/2}} \ge \beta^{3/2} \frac{||\bV||_2^2}{t_0}, \ \ 
	\frac{n}{q^2} \ge  \left( \frac{2d_{\max}}{q}\! + 1 \right)^3\! \frac{||\bV||_2^2}{t_0^4}.
\end{equation}
In summary, for given $\beta >0$, if either \eqref{eq:dim_cond1} or \eqref{eq:dim_cond2} holds, then we have
$$
{\rm P} \left(
\Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2 
\geq \frac{\lambda_{\min}^Uv_{\text{avg}}}{2} \right) \le \frac{3d_{\max}}{p^\beta}.
$$



\subsection{Proof of (ii) of Theorem \ref{mainthm}}
One can easily check that it suffices to show 
$\Vert \hat{\theta}_S-\theta_S^* \Vert _{\infty} \leq 3\lambda \sqrt{d_{\max}}/(\lambda_{\min}^Uv_{\text{avg}})$ 
holds with high probability.
Indeed, we observe
\begin{align}
	\Vert \hat{\theta}_S-\theta_S^* \Vert _{\infty} \leq&\  \left\lVert \bigl(\frac{\bbX_S^\top \bbX_S}{nq}\bigr)^{-1}\bbX_S^\top \frac{\epsilon}{nq} \right\rVert _{\infty}+ \lambda \left\lVert \bigl(\frac{\bbX_S^\top\bbX}{nq}\bigr)^{-1} \right\rVert _{\infty} \nonumber\\
	=&\ \Big\Vert \underbrace{\hat{\bGamma}_{SS}^{-1}\bbX_S^\top \frac{\epsilon}{nq}}_{=:L_S} \Big\Vert _{\infty} + \lambda \Vert \hat{\bGamma}_{SS}^{-1} \Vert _{\infty}. \nonumber
\end{align}
Moreover, under the event $E_{1a} = \{ \Vert \hat{\bGamma}_{SS}-{\bGamma}_{SS} \Vert _2 \leq \lambda_{\min}^Uv_{\text{avg}}/2\}$,  we have
\begin{align}
	\Vert \hat{\bGamma}_{SS}^{-1} \Vert _{\infty} \leq&\ \Vert \bGamma_{SS}^{-1} \Vert _{\infty} + \Vert \hat{\bGamma}_{SS}^{-1}-\bGamma_{SS}^{-1} \Vert _{\infty} \nonumber \\
	\leq&\ \frac{\sqrt{d_{\max}}}{\lambda_{\min}^Uv_{\text{avg}}} + \sqrt{d_{\max}} \Vert \hat{\bGamma}_{SS}^{-1}-\bGamma_{SS}^{-1} \Vert _2 \label{eqn:infnorm2}\\
	\leq&\ \frac{\sqrt{d_{\max}}}{\lambda_{\min}^Uv_{\text{avg}}} +\sqrt{d_{\max}}\cdot\frac{ \Vert \hat{\bGamma}_{SS}-{\bGamma}_{SS} \Vert _2 /(\lambda_{\min}^Uv_{\text{avg}})^2}{1-\Vert \hat{\bGamma}_{SS}-{\bGamma}_{SS} \Vert _2 /\lambda_{\min}^Uv_{\text{avg}}} \label{eqn:infnorm3}  \\
	\leq&\ \frac{2\sqrt{d_{\max}}}{\lambda_{\min}^Uv_{\text{avg}}}. \nonumber
\end{align}
For \eqref{eqn:infnorm2}, we use the fact 
$$
\Vert \bGamma_{SS}^{-1} \Vert _{\infty} \leq \sqrt{d_{\max}} \Vert \bGamma_{SS}^{-1} \Vert _2 \leq \sqrt{d_{\max}}/(\lambda_{\min}^Uv_{\text{avg}})
$$ 
which is verified by \eqref{b_bound}, and \eqref{eqn:infnorm3} follows from Lemma \ref{lem:invcov_dev}. 

Next, we focus on the term $L_S = \hat{\bGamma}_{SS}^{-1}\bbX_S^\top \epsilon/(nq)$. Since $\hat{\bGamma}_{SS}^{-1}\bbX_S^\top \indep \epsilon$, $L_S | \bbX_S$ follows the centered normal distribution. Let $\bA= \bbX_S \hat{\bGamma}_{SS}^{-1}/nq$, and denote its $j$-th column by $a_j$. Then, the maximum conditional variances of  the components of $L_S | \bbX_S$ is bounded as
$$
\max_{j \in S} \text{Var}((L_S)_j| \bbX_S) = \max_{j \in S}a_j^\top \text{Var}(\epsilon) a_j \le  \Vert \bV \Vert _2 \max_{j} a_j^\top a_j \le  \Vert \bV \Vert _2  \Vert  \diag(\bA^\top \bA)  \Vert 
$$
since $\text{Var}(\epsilon) = \text{diag}_n(\bV) \preceq  \Vert \bV \Vert _2 \text{I}_{nq}$.
In the last inequality, any matrix norm can be used, such as $ \Vert \cdot \Vert _{\max}$, $ \Vert \cdot \Vert _{2}$, and $ \Vert \cdot \Vert _{\infty}$. Finally, as $\bA^\top \bA = \widehat{\bGamma}_{SS}^{-1} / nq$, we can conclude under $E_{1a}$ that
\begin{equation}
	\max_{j \in S} \text{Var}((L_S)_j| \bbX_S) \le \dfrac{ \Vert \bV \Vert _2}{nq}  \Vert  \diag(\widehat{\bGamma}_{SS}^{-1})  \Vert_{\infty}  \leq \frac{ \Vert \bV \Vert _2}{nq} \Vert \widehat{\bGamma}_{SS}^{-1}  \Vert _{\infty} \leq \frac{2 \sqrt{d_{\max}} \Vert \bV \Vert _2}{nq\cdot \lambda_{\min}^Uv_{\text{avg}}} \nonumber
\end{equation}
where the last inequality uses $\Vert \hat\bGamma_{SS}^{-1} \Vert _{\infty} \leq \sqrt{d_{\max}} \Vert \hat\bGamma_{SS}^{-1} \Vert _2 \leq 2\sqrt{d_{\max}}/ (\lambda_{\min}^Uv_{\text{avg}})$. Applying the Gaussian tail bound,we get
\begin{align}\label{lambda_tailprob}
	\mathbb{P}\left( \Vert L_S \Vert _{\infty} \geq \frac{\sqrt{d_{\max}}}{\lambda_{\min}^Uv_{\text{avg}}} \lambda \right) \leq &\ 2|S| \exp \left(-nq\frac{\sqrt{d_{\max}} \lambda^2}{4 \lambda_{\min}^Uv_{\text{avg}} \Vert \bV \Vert _2} \right).
\end{align}
Hence, this probability is at most $2d_{\max} / p^\beta$ if $\lambda$ satisfies
\begin{align}\label{lambdacond2}
    \lambda \geq 2\sqrt{\frac{\log p}{nq} \cdot\beta \frac{\lambda_{\min}^Uv_{\text{avg}} \Vert \bV \Vert_2}{\sqrt{d_{\max}}} }.
\end{align}
In conclusion,under conditions \eqref{eq:dim_cond1} or \eqref{eq:dim_cond2} and \eqref{lambdacond2}, we obtain
\begin{align}\nonumber
    \mathbb{P}\left(\Vert \hat{\theta}_S-\theta_S^* \Vert _{\infty} \leq \frac{3\sqrt{d_{\max}}}{\lambda_{\min}^Uv_{\text{avg}}} \lambda \right) \leq \frac{2d_{\max}}{p^{\beta}}+\mathbb{P}(E_{1a}^c) \leq \frac{5d_{\max}}{p^\beta}
\end{align}
and the proof is completed by applying a union bound over the $p$ rows.

\end{proof}


\section{Supporting lemmas}

\subsection{Lemma \ref{lem:Gamma_SS_dev}}
\begin{lemma}\label{lem:Gamma_SS_dev}
Let $\bX^{(i)}$, $i=1,\dots,n$, be i.i.d. samples from the matrix normal distribution $\mathcal{MN}_{p,q}(\mathbf{0},\bU,\bV)$, and fix any index set $S \subseteq [p]$ with $|S| \leq m$ for some constant $m$. Let $\bGamma_{SS} = \text{tr}(\bV)/q \cdot \bU_{SS}$, $\hat{\bGamma}_{SS} = \sum_{i=1}^{n} \bX_S^{(i)} \bX_S^{(i) \top} /nq$.
Under Assumptions \ref{assum:sparse} and \ref{assum:eigen}, there exists a numerical constant $C>0$ such that for any $t>0$, 
$$
{\rm P} \left[
\Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2 
\geq C \cdot  \Vert \bU \Vert _2 \cdot t\right]
\le 
3m \exp \bigg[
- \min \Big\{
(t / a_1)^2, t / a_2, (t / a_3)^{2/3}
\Big\}
\bigg],
$$
where
\begin{align*}
	a_1 & = \sqrt{(2 m / q + 1) \Vert \bV \Vert^2_2 / n},\\
	a_2 & = \Vert \bV \Vert_2^2 / (n\sqrt{q}),\\
	a_3 & = \Vert \bV \Vert_2^2 / (nq).	
\end{align*}
%Under assumption \ref{assum:sparse} and \ref{assum:eigen}, for any $t>0$, $$\mathbb{P} \left( \Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2 \leq t \right)
%    \geq 1- 3m \exp \left( -c \cdot \min \left((nq)^{\frac{2}{3}}t^{\frac{2}{3}}, n \sqrt{q} t, n t^2 \right)\right)$$
\end{lemma}


\begin{proof}

Since $\bX_S^{(i)} \sim \mathcal{MN}_{s, q}(\bzero,  \bU_{SS}, \bV)$, write $\bX_S^{(i)}=\bU_{SS}^{1/2}\bZ_{S}^{(i)}\bV^{1/2}$ where each $\bZ_{S}^{(i)}$ has i.i.d standard normal entries. Then
$$
\hat{\bGamma}_{SS}
=\frac{1}{nq}\sum_{i=1}^n \bX_{S}^{(i)} \bigl( \bX_{S}^{(i)} \bigr)^\top 
=\frac{1}{nq}\bU_{SS}^{\frac{1}{2}}\sum_{i=1}^n \bZ_{S}^{(i)} \bV \big( \bZ_{S}^{(i)} \big)^\top \bU_{SS}^{\frac{1}{2}},
$$
thus
\begin{align*}
     \left\Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \right\Vert _2 =&  \left\Vert \frac{1}{q} \bU_{SS}^{\frac{1}{2}} \left( \frac{1}{n} \sum_{i=1}^n \bZ_{S}^{(i)} \bV (\bZ_{S}^{(i)})^\top - \text{tr}(\bV)\text{I}_s \right) \bU_{SS}^{\frac{1}{2}} \right\Vert _2\\
    \leq&\ \frac{1}{q} \left\Vert \bU_{SS} \right\Vert _2 \cdot  \left\Vert \frac{1}{n} \sum_{i=1}^n \bZ_{S}^{(i)} \bV (\bZ_{S}^{(i)})^\top - \text{tr}(\bV)\text{I}_s \right\Vert _2\\
    \leq&\ \frac{1}{q} \left\Vert \bU \right\Vert _2 \cdot  \left\Vert \frac{1}{n} \sum_{i=1}^n \bZ_{S}^{(i)} \bV (\bZ_{S}^{(i)})^\top - \text{tr}(\bV)\text{I}_s \right\Vert _2.
\end{align*}

We apply the Bernstein inequality for bounded random matrices (Theorem 6.1.1 of \citet{tropp2015introduction}) to control the rate of $ \Vert \frac{1}{n} \sum_{i=1}^n \bZ_{S}^{(i)} \bV (\bZ_{S}^{(i)})^\top - \text{tr}(\bV)\text{I}_s \Vert _2$.
To this end, define the event $A = \cap_{i=1}^n A_i \equiv \cap_{i=1}^n \{ \Vert \bZ_S^{(i)} \Vert _2^2 \le K \}$ for some constant $K>0$ to be specified later. On the event $A$, it holds
\begin{align*}
\frac{1}{n} \sum_{i=1}^n \big\{\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \big\}
=&\ \frac{1}{n}\sum_{i=1}^n \big\{\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i} - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i} \big\} \\
-&\ \mathbb{E}\bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \text{I}_{A_1^c}, 
\end{align*}
which implies
\begin{align*}
    \bigg\|\frac{1}{n}\sum_{i=1}^n \bigl\{\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \bigr\}\bigg\|_2
    &\le 
    \underbrace{\frac{1}{n}\bigg\|\sum_{i=1}^n \bigl\{\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i}
       - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i}\bigr\}\bigg\|_2}_{=:B_1}\\
    &\quad+
    \underbrace{\bigg\|\mathbb{E}\bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \text{I}_{A_1^c}\bigg\|_2}_{=:B_2}\,.
\end{align*}

\subsubsection*{(1) Concentration of $B_1$}
We apply the matrix Bernstein inequality to $\bS_i \equiv \bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i} - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i}$.

\subsubsection*{Boundedness of $\bS_i$}
Assume the event $A$ holds. Then
\begin{align*}
    \Vert  \bS_i  \Vert _2 & \le  \Vert  \bZ^{(i)}_{S} \bV      (\bZ^{(i)}_{S})^\top  \Vert _2 +  \Vert  \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i}  \Vert _2 \\
    & \le  \Vert  \bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top  \Vert _2 + \mathbb{E}  \Vert  \bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i}  \Vert _2
    \le 2  \Vert \bV \Vert _2 K,   
\end{align*}
where the last inequality holds since
$\Vert  \bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top  \Vert _2 \le  \Vert  \bZ^{(i)}_{S} \Vert _2^2  \Vert  \bV  \Vert _2 \le  \Vert  \bV  \Vert _2 K.$

\subsubsection*{Calculation of $ \Vert \mathbb{E} \bS_1 \bS_1^\top \Vert _2$}
Observe that
\begin{align*}
    \mathbb{E} \bS_1 \bS_1^\top & =  
    \mathbb{E} \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top  \text{I}_{A_1} - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(1)}_{S})^\top \text{I}_{A_1}\mathbb{E}\bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \text{I}_{A_1} \\
    & \preceq \mathbb{E} \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top.
\end{align*}
Thus, we have
$ \Vert \mathbb{E} \bS_1 \bS_1^\top \Vert _2 \le  \Vert \mathbb{E} \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \Vert _2$.
Writing the $k$-th row of $\bZ^{(1)}$ as $Z^{(1)}_{k}$, the $(k,\ell)$-th entry of the above expectation is
$$
\mathbb{E} (Z^{(1)}_k)^\top \bV \sum_{i \in S} Z^{(1)}_i (Z^{(1)}_i)^\top \bV Z^{(1)}_\ell = \sum_{i \in S} \sum_{j_1, j_2, j_3, j_4} \bV_{j_1 j_2} \bV_{j_3 j_4} \mathbb{E} Z^{(1)}_{kj_1} Z^{(1)}_{ij_2} Z^{(1)}_{\ell j_3} Z^{(1)}_{ij_4}.
$$

When $k=\ell$, the only nonzero fourth moments in right-hand side arise from appropriate pairings of the $Z^{(1)}_{ab}$ terms.
\begin{align*}
   \mathbb{E} Z^{(1)}_{kj_1} Z^{(1)}_{ij_2} Z^{(1)}_{k j_3} Z^{(1)}_{ij_4} =
   \begin{cases}
       3 & i=k, j_1=j_2=j_3=j_4 \\
       1 & i=k, j_1=j_2 \neq j_3=j_4\\
       1 & i=k, j_1=j_3 \neq j_2=j_4\\
       1 & i=k, j_1=j_4 \neq j_2=j_3\\
       1 & i \neq k, j_1=j_3, j_2=j_4\\
       0 & otherwise.
   \end{cases}
\end{align*}
Hence,
$$
\mathbb{E} (Z^{(1)}_k)^\top \bV \Bigl(\sum_{i \in S} Z^{(1)}_i (Z^{(1)}_i)^\top \Bigr)\bV Z^{(1)}_k
= (|S|+1) \sum_{j_1, j_2} V_{j_1 j_2}^2 + (\sum_{j} V_{jj})^2 \leq(m+1)  \Vert \bV \Vert _F^2 + \text{tr}(\bV)^2.
$$
since $|S| \leq m$.

When $k \neq \ell$, all fourth moments $\mathbb{E} Z^{(1)}_{kj_1} Z^{(1)}_{ij_2} Z^{(1)}_{\ell j_3} Z^{(1)}_{ij_4}=0$. Therefore, $\Vert \mathbb{E} \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \Vert _2$ equals to the maximum diagonal entry, which is bounded above by $(m+1) \Vert \bV \Vert _F^2 + \text{tr}(\bV)^2$.


\subsubsection*{Bernstein inequality of $\bS_i$}
Assume that event $A$ holds. Then, for any $\delta>0$,
\begin{align*}
\mathbb{P}\left(	\bigg|\bigg|\sum_{i=1}^n \big\{\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i} - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i} \big\}\bigg|\bigg|_2 \ge n \delta  \right)
\le 2m \exp\left\{
-\dfrac{1}{4} \min\bigg\{
\dfrac{n\delta^2}{(m+1)  \Vert \bV \Vert _F^2 + \text{tr}(\bV)^2},\dfrac{3n\delta}{2 \Vert \bV \Vert _2^2 K}
\bigg\} 
\right\}.
\end{align*}
Equivalently, for any $u>0$,
\begin{align*}
  \frac{1}{n}\bigg|\bigg|\sum_{i=1}^n \big\{\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i} - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i} \big\}\bigg|\bigg|_2 
  \ge 4 \max\bigg\{\sqrt{\dfrac{\Big((m+1)  \Vert \bV \Vert _F^2 + \text{tr}(\bV)^2 \Big)u}{n}},\dfrac{2 \Vert \bV \Vert _2^2 K u}{3n}
\bigg\} 
\end{align*}
holds with probability at most $2m \exp(-u)$.


\subsubsection*{(2) Upper bound for $B_2$}
First, observe that
\begin{align*}
\bigg|\bigg|\mathbb{E}\bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \text{I}_{A_1^c}\bigg|\bigg|_2 & = 
\max\limits_{x:  \Vert x \Vert _2=1} \mathbb{E} (x^\top \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top x ) \cdot \text{I}_{A_1^c}\\
& \le 
\max\limits_{x:  \Vert x \Vert _2=1} \sqrt{\mathbb{E} (x^\top \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top x )^2 \cdot \mathbb{E} \text{I}_{A_1^c}}
\end{align*}
holds by the Cauchy-Schwartz inequality.

\subsubsection*{Calculation of $\mathbb{E} (x^\top \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top x )^2$}
For any unit vector $x \in \mathbb{R}^s$, note that
\begin{align*}
\mathbb{E} (x^\top \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top x )^2 & = \ \mathbb{E}\Bigl(
\sum\limits_{i_1, i_2 \in S}
\sum\limits_{j_1, j_2 \in [q]} x_{i_1} Z_{i_1 j_1}^{(1)} V_{j_1 j_2}Z_{i_2 j_2}^{(1)} x_{i_2}
\Bigr)^2
\\
& =
\sum_{\substack{i_1,i_2,i_3,i_4\in S\\j_1,\dots,j_4\in[q]}} x_{i_1} x_{i_2} x_{i_3} x_{i_4} V_{j_1 j_2} V_{j_3 j_4} \mathbb{E} Z_{i_1 j_1}^{(1)} Z_{i_2 j_2}^{(1)} Z_{i_3 j_3}^{(1)} Z_{i_4 j_4}^{(1)}.    
\end{align*}
The only nonzero fourth moments occur in the following four cases:
\begin{enumerate}
	\item $(i_1, j_1) = (i_2, j_2)$, $(i_3, j_3) = (i_4, j_4)$, and
	$(i_1, j_1) \neq (i_3, j_3)$
	$$
	\mathbb{E} Z_{i_1 j_1}^{(1)} Z_{i_2 j_2}^{(1)} Z_{i_3 j_3}^{(1)} Z_{i_4 j_4}^{(1)} = \mathbb{E}(Z_{i_1 j_1}^{(1)})^2 \mathbb{E}(Z_{i_3 j_3}^{(1)})^2 = 1
	$$
	\item $(i_1, j_1) = (i_3, j_3)$, $(i_2, j_2) = (i_4, j_4)$, and
	$(i_1, j_1) \neq (i_2, j_2)$ 
	$$
	\mathbb{E} Z_{i_1 j_1}^{(1)} Z_{i_2 j_2}^{(1)} Z_{i_3 j_3}^{(1)} Z_{i_4 j_4}^{(1)} = \mathbb{E}(Z_{i_1 j_1}^{(1)})^2 \mathbb{E}(Z_{i_2 j_2}^{(1)})^2 = 1
	$$
	\item $(i_1, j_1) = (i_4, j_4)$, $(i_3, j_3) = (i_2, j_2)$, and
	$(i_1, j_1) \neq (i_3, j_3)$ 
	$$
	\mathbb{E} Z_{i_1 j_1}^{(1)} Z_{i_2 j_2}^{(1)} Z_{i_3 j_3}^{(1)} Z_{i_4 j_4}^{(1)} = \mathbb{E}(Z_{i_1 j_1}^{(1)})^2 \mathbb{E}(Z_{i_3 j_3}^{(1)})^2 = 1
	$$	
	\item $(i_1, j_1) = (i_2, j_2)=(i_3, j_3) = (i_4, j_4)$
	$$
	\mathbb{E} Z_{i_1 j_1}^{(1)} Z_{i_2 j_2}^{(1)} Z_{i_3 j_3}^{(1)} Z_{i_4 j_4}^{(1)} = \mathbb{E}(Z_{i_1 j_1}^{(1)})^4 = 3
	$$
\end{enumerate}
Therefore, we have
\begin{align*}
    \mathbb{E} (x^\top \bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top x )^2
    =&\ \sum\limits_{i_1, i_2 \in S}
    \sum\limits_{j_1, j_2 \in [q]} x_{i_1}^2 x_{i_2}^2(V_{j_1 j_1} V_{j_2 j_2} + 2V_{j_1 j_2}^2)
    + 3\sum\limits_{i_1 \in S}
    \sum\limits_{j_1 \in [q]} x_{i_1}^4 V_{j_1 j_1}^2\\
    \leq&\ \sum\limits_{j_1, j_2 \in [q]} (V_{j_1 j_1} V_{j_2 j_2} + 2V_{j_1 j_2}^2)
    + 3\sum\limits_{j_1 \in [q]} V_{j_1 j_1}^2
    =\ \text{tr}(\bV)^2 + 2 \Vert \bV \Vert _F^2.
\end{align*}


\subsubsection*{Calculation of $\text{\rm P}(A_1^c)$}

Note that $ \Vert \bZ_S^{(1)} \Vert _2= \Vert (\bZ_S^{(1)})^\top \Vert _2 = \sigma_{\max}((\bZ_S^{(1)})^\top)$. 
By Theorem 6.1 of \citet{wainwright2019high}, 
$$
\mathbb{P}\bigl(
\sigma_{\max}((\bZ_S^{(1)})^\top) \ge \sqrt{q} (1 + \delta) + \sqrt{m} \bigr) 
\le \exp(-q\delta^2 / 2), \quad \forall\,\delta>0.
$$
Here $S$ is treated as fixed, so the $q$–dimension plays the role of sample size.
Setting $\delta = \sqrt{2(u + \log n) /q}$ for $u>0$ gives
$$
\mathbb{P}\bigl(
\sigma_{\max}((\bZ_S^{(1)})^\top) \ge \sqrt{q} + \sqrt{m} + \sqrt{2(u + \log n)}
\bigr) \le \frac{1}{n}\exp(-u), \quad u>0.
$$
By a union bound over $i=1,\dots,n$, it follows that
$$
\mathbb{P}\left(\cup_{i=1}^n \Big\{ \Vert \bZ_S^{(i)} \Vert _2^2 \ge K_u \Big\} \right) \le 
n\, \mathbb{P}\left( \Vert \bZ_S^{(1)} \Vert _2^2 \ge K_u \right) \le \exp(-u),
$$
where $K_u = \sqrt{q} + \sqrt{m} + \sqrt{2(u + \log n)}$.	
%This implies $\mathbb{P}(A_1^c) \le  1 - \big(1 - e^{-q\delta^2 / 2}\big)^n \equiv f(q,\delta, n)$.
%{\color{red} ()
%Assume $q > s$. For the choice $K=9q$ (we use $\delta = 1$), we have
%$\mathbb{P}( \Vert Z_S^{(1)} \Vert _2^2 > K)\le \exp(-q / 2)$.
%%If $n > \log q$, $\mathbb{P}( \Vert Z_S^{(1)} \Vert _2^2 > K)\le x	$
%}
Hence, by choosing $u \ge \log n$, we get
$$
\bigg|\bigg|\mathbb{E}\bZ^{(1)}_{S} \bV (\bZ^{(1)}_{S})^\top \text{I}_{A_1^c}\bigg|\bigg|_2
\le
\sqrt{
	\text{tr}(\bV)^2 + 2 \Vert \bV \Vert _F^2}\ e^{-u / 2} \le 
\sqrt{\dfrac{\text{tr}(\bV)^2 + 2 \Vert \bV \Vert _F^2}{n}}.
$$


\subsubsection*{(3) Combined results}
Now, define
$$
t_1 = 4 \max\bigg\{
\sqrt{\dfrac{\Big((m+1)  \Vert \bV \Vert _F^2 + \text{tr}(\bV)^2 \Big)u}{n}},\dfrac{2 \Vert \bV \Vert _2^2 K_u \cdot u}{3n}
\bigg\}, \quad t_2 = \sqrt{\dfrac{\text{tr}(\bV)^2 + 2 \Vert \bV \Vert _F^2}{n}},
$$
where $K_u=\sqrt{q} + \sqrt{m} + \sqrt{2(u+\log n)}$
and set $A \equiv \cap_{i=1}^n \{ \Vert \bZ_S^{(i)} \Vert _2^2 \le K_u\}$. Then
\begin{align*}
&\mathbb{P}\left[
\bigg|\bigg|\frac{1}{n}\sum_{i=1}^n \big\{\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \big\}\bigg|\bigg|_2 \ge t_1 + t_2
\right] \\
\le\, &\mathbb{P}\left[
\bigg|\bigg|\frac{1}{n}\sum_{i=1}^n \big\{\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \big\}\bigg|\bigg|_2 \ge t_1 + t_2 \bigg| A \right] + \mathbb{P}(A^c)\\
\le\, &\mathbb{P}\left[
\frac{1}{n}\bigg|\bigg|\sum_{i=1}^n \big\{\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i} - \mathbb{E}\bZ^{(i)}_{S} \bV (\bZ^{(i)}_{S})^\top \text{I}_{A_i} \big\}\bigg|\bigg|_2\ge t_1 \bigg| A \right] + \exp(-u)\\
\le\, &3m \exp(-u)    
\end{align*}
Therefore, for $u > 1 \vee \log n$, we have
\begin{equation}
  \begin{aligned} \label{Gamma concentration inequality}
    \Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2
    \geq&\, C \cdot  \Vert \bU \Vert _2 \cdot \max\bigg\{
\sqrt{\dfrac{\Big((m+1)  \Vert \bV \Vert _F^2 + \text{tr}(\bV)^2\Big)u }{nq^2}},
\dfrac{2 \Vert \bV \Vert _2^2 K_u \cdot u}{3nq} \bigg\} \\
\geq&\, C \cdot  \Vert \bU \Vert _2 \cdot \max\bigg\{
\sqrt{\dfrac{\Big((m+1)  \Vert \bV \Vert _F^2 + \text{tr}(\bV)^2\Big)u }{nq^2}},
\dfrac{4 \Vert \bV \Vert _2^2 (u^{\frac{3}{2}}+u\sqrt{q})}{3nq} \bigg\}
 \end{aligned}  
\end{equation}
with probability at most $3m \exp(-u)$.
Since $K_u \leq 2\sqrt{q}+2\sqrt{u}$, it follows that
$$
\Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2 
\geq 2 C \cdot  \Vert \bU \Vert _2 \cdot 
\max\big\{
a_1 \sqrt{u},\
a_2 u,\
a_3 u\sqrt{u}
\big\}
$$
holds with the same probability, where 
\begin{align*}
    a_1 = \sqrt{(m+1) \Vert \bV \Vert _F^2 + \text{tr}(\bV)^2}/(\sqrt{n}q),\quad
    a_2 = \Vert \bV \Vert_2^2 / (n\sqrt{q}), \quad
    a_3 = \Vert \bV \Vert_2^2 / (nq).	    
\end{align*}
This leads to 
$$
\mathbb{P} \left[
\Vert \hat{\bGamma}_{SS} - {\bGamma}_{SS} \Vert _2 
\geq 2 C \cdot  \Vert \bU \Vert _2 \cdot t\right]
\le 
3m \exp \bigg[
- \min \Big\{
(t / a_1)^2, t / a_2, (t / a_3)^{2/3}
\Big\}
\bigg].
$$
Finally, using $\|\bV\|_F^2\le q\|\bV\|_2^2$ and $\text{tr}(\bV)/q\le\|\bV\|_2$ shows $a_1 \le \sqrt{(2m/q+1) \,\|\bV\|_2^2/n}$, which completes the proof.
\end{proof}


\subsection{Lemma \ref{lem:invcov_dev}}
\begin{lemma}\label{lem:invcov_dev}
    Let $\bSigma$ and $\hat{\bSigma}$ be nonsingular matrices, and suppose $\|\bSigma^{-1}\| \cdot \|\widehat{\bSigma} - \bSigma\| < 1$. Then for any sub-multiplicative matrix norm,
\begin{equation}\nonumber
    \|\widehat{\bSigma}^{-1} - \bSigma^{-1} \| \le \frac{\|\bSigma^{-1}\|^2 \cdot \|\widehat{\bSigma} - \bSigma\|}{1-\|\bSigma^{-1}\| \cdot \|\widehat{\bSigma} - \bSigma\| }.
\end{equation}
\end{lemma}

\begin{proof}
Observe that
\begin{align*}
	\|\widehat{\bSigma}^{-1} - \bSigma^{-1} \|
	&= \|\bSigma^{-1}(\widehat{\bSigma} - \bSigma)\widehat{\bSigma}^{-1}\| \\
	&\le \|\bSigma^{-1}\| \cdot \|\widehat{\bSigma} - \bSigma\| \cdot \|\widehat{\bSigma}^{-1}\| \\
	&\le \|\bSigma^{-1}\| \cdot \|\widehat{\bSigma} - \bSigma\| \cdot \big(\|\widehat{\bSigma}^{-1} - \bSigma^{-1}\| + \|\bSigma^{-1}\| \big)
\end{align*}
By rearranging and using the assumption $\|\bSigma^{-1}\| \cdot \|\widehat{\bSigma} - \bSigma\| < 1$, we yield the result.
\end{proof}



\section{Additional results for simulation study} \label{appendix:numerical}

\subsection{Results - homongenous variances} \label{appendix:homogeneous}
We first present simulation results under homogeneous variances, which correspond to the setting of the main experiment in Section 4, except that the diagonal entries $\omega_{ii}$ are not scaled by uniform random numbers. All other settings follow analogously to Section 4.

\begin{figure}[htbp]
