\section{Separably determined properties of C*-algebras and Cu-semigroups}
\label{sec:SepDet}

%==========================================================================================
In this section we introduce the concept of being `separably determined' for properties of \ca{s} and \CuSgp{s}.
This notion is very useful for reducing arguments to the separable case, and this will be crucial in \cref{sec:CompDivExt}.
Many everyday properties of \ca{s} --- for example, stable rank one --- are separably determined. 
Moreover, if $\calP$ is a separably determined property of \CuSgp{s}, then the property of having a Cuntz semigroup with $\calP$ is separably determined for \ca{s};
see \cref{prp:RelateSepDet}.

%==========================================================================================
\begin{pgr}
Let $A$ be a \ca.
We denote by $\Sep(A)$ the collection of separable sub-\ca{s} of $A$, equipped with the partial order given by inclusion.
Every countable, directed subset $\calC \subseteq \Sep(A)$ admits a supremum, namely $\overline{\bigcup_{B \in \calC}B}$.
Restricting the model-theoretic definition to our case of interest, a family $\calC \subseteq \Sep(A)$ is called a \emph{club} if it is \emph{cofinal} (that is, for every $B_0\in\Sep(A)$ there exists $B\in\calC$ such that $B_0 \subseteq B$) and \emph{$\sigma$-complete} (that is, for every countable, directed subset $\calC' \subseteq \calC$ we have $\sup\calC' \in \calC$).

Let $\calP$ be a property of \ca{s} (for example, `has stable rank one').
One says that $\calP$ satisfies the \emph{L{\"o}wenheim-Skolem condition}, or that $\calP$ \emph{reflects to separable sub-\ca{s}} (\cite[Definition~7.3.1]{Far19BookSetThyCAlg}), if every \ca{} with $\calP$ contains a club of separable sub-\ca{s} that also have $\calP$.
\end{pgr}

%==========================================================================================
In the following definition, an inductive limit refers to the limit of an inductive system with not necessarily injective connecting maps and indexed by a directed set, which is not necessarily countable.

%==========================================================================================
\begin{dfn}
\label{dfn:SepDet}
We say that a property $\calP$ of \ca{s} is \emph{separably determined} if it satisfies the L{\"o}wenheim-Skolem condition and is preserved by inductive limits.
\end{dfn}

%==========================================================================================
\begin{rmk}
\label{rmk:SepDet}
Let $\calP$ be a property of \ca{s} that passes to inductive limits.
Given a \ca{} $A$, let $\Sep_{\calP}(A)$ denote the family of separable sub-\ca{s} that have $\calP$.
We note that $\Sep_{\calP}(A)$ is automatically $\sigma$-complete:
Indeed, if $\calC' \subseteq \Sep_{\calP}(A)$ is a countable, directed subset, then $\calC'$ is an inductive system indexed over itself whose inductive limit is $\sup\calC'$, and since $\calP$ passes to inductive limits, we get $\sup\calC' \in \Sep_{\calP}(A)$.

Thus, to ensure that~$\calP$ satisfies the L{\"o}wenheim-Skolem condition (and thus is separably determined), it suffices to assume that $\Sep_{\calP}(A)$ is cofinal whenever $A$ has $\calP$.
This shows that \cref{dfn:SepDetIntro} agrees with \cref{dfn:SepDet}.
\end{rmk}

%==========================================================================================
\begin{prp}
\label{prp:ClubWithProperty}
Let $\calP$ be a separably determined property of \ca{s}.
Then the following are equivalent for every \ca{} $A$:
\begin{enumerate}
\item[{\rm (1)}]
The \ca{} $A$ has $\calP$.
\item[{\rm (2)}]
The family of separable sub-\ca{s} of $A$ that have $\calP$ is a club.
\item[{\rm (3)}]
The \ca{} $A$ contains a club of separable sub-\ca{s} that have $\calP$. 
\end{enumerate}
\end{prp}
\begin{proof}
To show that~(1) implies~(2), assume that $A$ has $\calP$ and let $\Sep_{\calP}(A)$  be the family of separable sub-\ca{s} of $A$ that have $\calP$.
Since $\calP$ satisfies the L{\"o}wenheim-Skolem condition, $\calC$ contains a club and consequently is cofinal.
Further, $\Sep_{\calP}(A)$ is automatically $\sigma$-complete, as noted in \cref{rmk:SepDet}.

Clearly, (2) implies~(3).
To see that~(3) implies~(1), let $\calC \subseteq \Sep(A)$ be a club of separable sub-\ca{s} that have $\calP$.
Viewing $\calC$ as an inductive system indexed over itself, its limit is (isomorphic to) $A$, and since $\calP$ passes to inductive limits it follows that $A$ has $\calP$.
\end{proof}

%==========================================================================================
\begin{rmk}
The Downwards L{\"o}wenheim-Skolem theorem (\cite[Theorem~7.1.9, Lemma~7.3.3]{Far19BookSetThyCAlg}) shows that every axiomatizable property satisfies the L{\"o}wenheim-Skolem condition.
Further, every $\forall\exists$-axiomatizable property passes to inductive limits;
see \cite[Proposition~2.4.4(3)]{FarHarLupRobTikVigWin21ModelThy}.
It follows that every $\forall\exists$-axiomatizable property is separably determined, and \cite[Theorem 2.5.1]{FarHarLupRobTikVigWin21ModelThy} lists many such properties.

On the other hand, there are some natural properties of \ca{s} that are separably determined but that are not axiomatizable (or at least not known to be axiomatizable).
For example, the property of having real rank $\leq 1$ is separably determined (see the discussion after \cite[Definition~4.5]{Thi24RRExt}), but it remains open of this property is axiomatizable \cite[Question~3.9.3]{FarHarLupRobTikVigWin21ModelThy}.
\end{rmk}

%==========================================================================================
\begin{rmk}
Following Blackadar \cite[Definition~II.8.5]{Bla06OpAlgs}, one says that a property~$\calP$ of \ca{s} is \emph{separably inheritable} if for every \ca{} $A$ with $\calP$ the separable sub-\ca{s} with $\calP$ are cofinal in $\Sep(A)$ and $\calP$ passes to sequential inductive limits with injective connecting maps.
It thus follows from the definitions that every separably determined property is separably inheritable.
It is also known that every separably inheritable property satisfies the L{\"o}wenheim-Skolem condition.
The implications are shown in the following diagram:
\begin{center}
\begin{tikzcd}[column sep=10pt,row sep=12pt,arrows=Rightarrow]
\text{$\forall\exists$-axiomatizable} \ar[r] & \text{separably determined} \ar[d] \\
& \text{separably inheritable} \ar[r] & \text{L{\"o}wenheim-Skolem condition}
\end{tikzcd}
\end{center}
\end{rmk}

%==========================================================================================
\begin{pgr}
Let us recall the basic theory of Cuntz semigroups and their abstract counterparts.
A \emph{\CuSgp{}} is a positively ordered monoid such that
\begin{itemize}
\item[\axiomO{1}] 
increasing sequences have suprema;
\item[\axiomO{2}]
every element is the supremum of a $\ll$-increasing sequence;
\item[\axiomO{3}] 
addition is compatible with the relation $\ll$;
\item[\axiomO{4}] 
addition is compatible with taking suprema of increasing sequences;
\end{itemize}
where $\ll$ denotes the \emph{way-below relation} defined by setting $x\ll y$ if for every increasing sequence $(y_n)_n$ with $y \leq \sup_n y_n$ there exists $n\in\mathbb{N}$ such that $x\leq y_n$.

A \emph{generalized \CuMor} is an order-preserving monoid morphism that preserves suprema of increasing sequences.
If it also preserves the way-below relation then it is called a \emph{\CuMor}.

The category of \CuSgp{s} was introduced in \cite{CowEllIva08CuInv} to provide an abstract framework for the study of the \emph{Cuntz semigroup} of a \ca{} $A$. 
This invariant, denoted by $\Cu(A)$, is defined as the Cuntz equivalence classes of positive elements in the stabilization~$A\otimes\Cpct$.
Here, the Cuntz subsequivalence relation $\precsim$ and the Cuntz equivalence relation $\sim$ among positive elements $a$ and $b$ in a \ca{} are defined by setting $a\precsim b$ if there exists a sequence $(r_n)_n$ such that $a=\lim_n r_n br_n^*$, and by setting $a \sim b$ if $a\precsim b$ and $b \precsim a$.

When equipped with the partial order induced by $\precsim$ and the addition induced by addition of orthogonal positive elements in $A\otimes\Cpct$, the Cuntz semigroup becomes a \CuSgp{}; 
see \cite[Theorem 1]{CowEllIva08CuInv}.
Further, every $\ast$-homomorphism $A \to B$ between \ca{s} induces a natural \CuMor{} $\Cu(A)\to\Cu(B)$, and the Cuntz semigroup functor preserves inductive limits (\cite[Corollary 3.2.9]{AntPerThi18TensorProdCu}) and taking scales into account it also preserves (ultra)products (\cite[Theorem~7.5]{AntPerThi20CuntzUltraproducts}).~See also \cite{AraPerTom11Cu, GarPer23arX:ModernCu} for general expositions. 

A basis of a \CuSgp{} $S$ is a subset $B \subseteq S$ such that every element in $S$ can be written as the supremum of an increasing sequence of elements in $B$.
One says that $S$ is \emph{separable} or \emph{countably based} if it contains a countable basis.
The Cuntz semigroup of a separable \ca{} is separable;
see \cite[Lemma~1.3]{AntPerSan11PullbacksCu}.
\end{pgr}

%==========================================================================================
\begin{pgr}
Let $S$ be a \CuSgp.
As defined in \cite[Definition~4.1]{ThiVil21DimCu2}, a submonoid~$H$ of~$S$ is called a sub-\CuSgp{} if $H$ is a \CuSgp{} with the induced order and the inclusion map $H\to S$ is a \CuMor{}. 
We denote by $\Sep(S)$ the family of all separable (=countably based) sub-\CuSgp{s} of $S$.

Given a countable, directed subset $\calD \subseteq \Sep(S)$, the union $M:=\bigcup\calD=\bigcup_{T\in\calD} T$ is a submonoid of~$S$ such that every element in $M$ is the supremum (in $S$) of a $\ll$-increasing sequence of elements in $M$.
Therefore, the set
\[
\overline{M} := \left\{ \sup_n x_n \in S : (x_n)_n \text{ is an increasing sequence of elements in } M \right\}
\]
is a sub-\CuSgp{} by \cite[Corollary~4.12]{ThiVil21DimCu2}.
Using that $\calD$ is countable and that each $T \in \calD$ is separable, it follows that $\overline{M}$ is separable.
Then $\overline{M}$ is the supremum of $\calD$ in $\Sep(S)$.

As in the setting of \ca{s}, we define a family $\calD \subseteq \Sep(S)$ to be a \emph{club} if
\begin{enumerate}
\item[{\rm (i)}]  
$\calD$ is cofinal, that is, for every $T_0 \in \Sep(S)$ there exists $T \in \calD$ such that $T_0 \subseteq T$; and
\item[{\rm (ii)}] 
$\calD$ is $\sigma$-complete, that is, for every countable, directed subset $\calD'\subseteq\calD$ we have $\sup\calD'\in\calD$.
\end{enumerate}

Let $\calP$ be a property for \CuSgp{s} (for example, `has $0$-comparison').
We say that $\calP$ satisfies the \emph{L{\"o}wenheim-Skolem condition}, or that $\calP$ \emph{reflects to separable sub-\CuSgp{s}}, if every \CuSgp{} with $\calP$ contains a club of separable sub-\CuSgp{s} with $\calP$;
see \cite[Paragraph~5.2]{ThiVil21DimCu2}.
\end{pgr}

%==========================================================================================
Analogous to \cref{dfn:SepDet}, we define:

%==========================================================================================
\begin{dfn}
\label{dfn:SepDetCu}
We say that a property $\calP$ of \CuSgp{s} is \emph{separably determined} if it satisfies the L{\"o}wenheim-Skolem condition and passes to inductive limits.
\end{dfn}

%==========================================================================================
The following result follows a similar proof as in \cref{prp:ClubWithProperty}:

%==========================================================================================
\begin{prp}
\label{prp:ClubWithPropertyCu}
Let $\calP$ be a separably determined property of \CuSgp{s}. Then, for every \CuSgp{} $S$, we have that $S$ has $\calP$ if, and only if, the family of separable sub-\CuSgp{s} of $S$ that have $\calP$ is a club.
\end{prp}	

%==========================================================================================
The next result closely relates clubs of separable sub-\ca{s} of a \ca{} with clubs of separable sub-\CuSgp{s} of its Cuntz semigroup.

%==========================================================================================
\begin{lma}
\label{prp:RelateClubs}
Let $A$ be a \ca.
Then the collection $\calC_0$ of separable sub-\ca{s} $B \subseteq A$ such that the inclusion $B \to A$ induces an order-embedding $\Cu(B) \to \Cu(A)$ is a club in $\Sep(A)$.

Further, the family $\calD_0$ formed by the induced monoids $\Cu (B)$ ---when viewed as sub-\CuSgp{s} of $\Cu (A)$--- is a club in $\Sep(\Cu(A))$, and the induced map $\alpha\colon\calC_0\to\calD_0$ preserves the order and suprema of countable, directed sets.

If $\calD \subseteq \Sep(\Cu(A))$ is a club, then so is $\alpha^{-1}(\calD_0 \cap \calD) \subseteq \Sep(A)$.
\end{lma}
\begin{proof}
It was shown in \cite[Proposition~6.1]{ThiVil21DimCu2} that $\calC_0$ and $\calD_0$ are clubs and that $\alpha\colon\calC_0\to\calD_0$ preserves the order and suprema of countable, directed sets.
We will repeatedly use that the intersection of finitely many (even at most countably many) clubs is again a club;
see \cite[Proposition~6.2.9]{Far19BookSetThyCAlg}.

Let $\calD \subseteq \Sep(\Cu(A))$ be a club, and set $\calC := \alpha^{-1}(\calD_0 \cap \calD)$.
We need to show that $\calC$ is a club.
Using that $\alpha$ preserves suprema of countable, directed sets, we deduce that $\calC$ is $\sigma$-complete.

To show that~$\calC$ is cofinal, let $B_0\in \Sep(A)$.
Since $\calC_0$ is a club (and thus cofinal), we may assume that $B_0 \in \calC_0$.
Since $\calD\cap\calD_0$ is a club (and thus cofinal), there exists $H_1 \in \calD\cap\calD_0$ with $\Cu(B_0)\subseteq H_1$.
Pick $C_1 \in \calC$ with $\Cu(C_1)=H_1$.
Using that~$\calC_0$ is cofinal find $B_1 \in \calC_0$ containing $B_0$ and $C_1$.
Then $B_0 \subseteq B_1$ and $\Cu(B_0) \subseteq H_1 \subseteq \Cu(B_1)$.

Proceeding inductively, we find $H_1,H_2,\ldots \in \calD$ and $B_1,B_2,\ldots \in \calC_0$ such that
\[
\Cu(B_0) 
\subseteq H_1
\subseteq \Cu(B_1)
\subseteq H_2
\subseteq \Cu(B_2)
\subseteq \ldots, \andSep
B_0 \subseteq B_1 \subseteq B_2 \subseteq \ldots.
\]

Set $B := \overline{\bigcup_n B_n}$, which is the supremum of the increasing sequence $(B_n)_n$ in~$\Sep(A)$.
By construction, we have $B_0 \subseteq B$.
Since $\alpha$ preserves suprema of countable, directed sets (in particular, of increasing sequences), we have
\[
\alpha(B)=\sup_n \alpha(B_n) = \sup_n H_n.
\]
Since $\calD$ is a club, we have $\sup_n H_n \in \calD$, and thus $B \in \calC$, as desired.
\end{proof}

%==========================================================================================
\begin{prp}
\label{prp:RelateLS}
If $\calP$ is a property of \CuSgp{s} satisfying the L{\"o}wenheim-Skolem condition, then the property of having a Cuntz semigroup with $\calP$ satisfies the L{\"o}wenheim-Skolem condition.
\end{prp}
\begin{proof}
To show that the property of having a Cuntz semigroup with $\calP$ satisfies the L{\"o}wenheim-Skolem condition, let $A$ be a \ca{} such that $\Cu(A)$ has $\calP$.
Let the clubs $\calC_0\subseteq\Sep(A)$ and $\calD_0\subseteq\Sep(\Cu(A))$ and the map $\alpha\colon\calC_0\to\calD_0$ be as in \cref{prp:RelateClubs}.
Since $\calP$ satisfies the L{\"o}wenheim-Skolem condition, there exists a club $\calD\subseteq\Sep(\Cu(A))$ of separable sub-\CuSgp{s} with $\calP$.

By \cref{prp:RelateClubs}, $\alpha^{-1}(\calD_0 \cap \calD)$ is a club in $\Sep(A)$.
Note that $\alpha^{-1}(\calD_0 \cap \calD)$ consists of separable sub-\ca{s} of $A$ whose Cuntz semigroup has $\calP$, as desired.
\end{proof}

%==========================================================================================
\begin{thm}
\label{prp:RelateSepDet}
If $\calP$ is a separably determined property of \CuSgp{s}, then the property of having a Cuntz semigroup with $\calP$ is separably determined.
\end{thm}
\begin{proof}
By \cref{prp:RelateLS}, the property $\calQ$ of having a Cuntz semigroup with $\calP$ satisfies the L{\"o}wenheim-Skolem condition.
By \cite[Corollary~3.2.9]{AntPerThi18TensorProdCu}, the Cuntz semigroup functor preserves inductive limits (over not necessarily countable index sets). 
It follows that $\calQ$ passes to inductive limits.
\end{proof}


