\section{Comparison and divisibility are separably determined}
\label{sec:CompDivSepDet}

%==========================================================================================
In this section we show that pureness is separably determined for \ca{s}
see \cref{prp:PureSepDet}.
More specifically, for each $m\in\NN$ we show that $m$-comparison is separably determined (\cref{prp:CompSepDet}), and for each $n\in\NN$ we show that $n$-almost divisibility is separably determined (\cref{prp:DivSepDet}).

\medskip

We first recall the definition of pureness, introduced by Winter for simple \ca{s} in \cite[Definitions~3.1~and~3.5]{Win12NuclDimZstable} and later adapted to the non-simple setting by Robert-Tikuisis \cite[Paragraph~2.3]{RobTik17NucDimNonSimple};
see also \cite{AntPerThiVil24arX:PureCAlgs}.
We will use the relation $<_s$ on a \CuSgp, which is defined by setting $x<_s y$ if there exists $n\in\NN$ such that $(n+1)x\leq ny$.

%==========================================================================================
\begin{dfn}
\label{dfn:pure}
Let $S$ be a \CuSgp, and let $m,n \in \NN$.
One says that $S$ has \emph{$m$-comparison} if for any $x,y_0,\ldots ,y_m \in S$ such that $x<_s y_j$ for each $j=0,\ldots ,m$, then $x\leq y_0+\ldots +y_m$.
Further, one says that $S$ is \emph{$n$-almost divisible} if for any $k\in\NN$ and any $x',x \in S$ such that $x'\ll x$ there exists an element $y$ such that $ky\leq x$ and $x'\leq (k+1)(n+1)y$.

We say that $S$ is \emph{$(m,n)$-pure} if it has $m$-comparison and is $n$-almost divisible. Further, $S$ is said to be \emph{pure} if it is $(0,0)$-pure.

A \ca{} $A$ is termed \emph{$(m,n)$-pure} if its Cuntz semigroup $\Cu(A)$ is $(m,n)$-pure; and $A$ is \emph{pure} if $\Cu(A)$ is pure (See \cref{rmk:MnPureImpPure} below.)
\end{dfn}

%==========================================================================================
\begin{rmk}
\label{rmk:MnPureImpPure}
The property of $0$-comparison is often referred to as \emph{almost unperforation}, and the Cuntz semigroup of a \ca{} $A$ is almost unperforated if and only if $A$ has \emph{strict comparison of positive elements by quasitraces}; 
see \cite[Proposition~6.2]{EllRobSan11Cone} and the discussions in \cite[Paragraph~3.4]{AntPerThiVil24arX:PureCAlgs}.
The property of $0$-almost divisibility is usually referred to as \emph{almost divisibility}.
Thus, a \ca{} is pure if (by definition) its Cuntz semigroup is almost unperforated and almost divisible.

It is easy to see that $(m,n)$-pureness implies $(m',n')$-pureness for all $m' \geq m$ and $n' \geq n$, both for \ca{s} and at the level of \CuSgp{s}.
In the converse direction, \ca{s} exhibit a reduction phenomenon:
a \ca{} is automatically pure whenever it is $(m,n)$-pure for some $m,n \in \NN$. 
This was established in \cite[Theorem~5.7]{AntPerThiVil24arX:PureCAlgs}, building on earlier results in the simple case \cite[Theorem~10.5]{AntPerRobThi24TracesUltra}. 
For simple, unital \ca{s} with locally finite nuclear dimension, the phenomenon also follows from Winter’s $\calZ$-stability theorem \cite{Win12NuclDimZstable} in combination with R{\o}rdam's theorem that $\calZ$-stable \ca{s} are pure \cite{Ror04StableRealRankZ}.
\end{rmk}

%==========================================================================================
Let $S$ be a \CuSgp{}, and let $\varphi_\lambda\colon S_\lambda \to S$ be \CuMor{s} from some \CuSgp{s} $S_\lambda$, for $\lambda\in\Lambda$.
Following \cite[Definition~3.1]{ThiVil21DimCu2}, we say that $S$ is \emph{approximated} by the family $(S_\lambda,\varphi_\lambda)_{\lambda\in\Lambda}$ if the following holds:
For any finite index sets $J$ and $K$, any $x_j',x_j \in S$ for $j \in J$ (thought of as variables), and any functions $m_k,n_k \colon J \to \NN$ for $k \in K$ (thought of as relations) such that
\[
x_j' \ll x_j \text{ for $j \in J$}, \andSep
\sum_{j \in J} m_k(j)x_j \ll \sum_{j \in J} n_k(j)x_j'  \text{ for $k \in K$}
\]
there exists an index $\lambda\in\Lambda$ and $y_j \in S_\lambda$ for $j \in J$ such that
\[
x_j' \ll \varphi_\lambda(y_j) \ll x_j \text{ for $j \in J$}, \andSep
\sum_{j \in J} m_k(j)y_j \ll \sum_{j \in J} n_k(j)y_j \text{ for $k \in K$}.
\]

%==========================================================================================
\begin{lma}
\label{prp:CompApprox}
For each $m\in\NN$, the property of $m$-comparison passes to approximated \CuSgp{s}.
\end{lma}
\begin{proof}
Let $m\in\NN$, and let $S$ be a \CuSgp{} that is approximated by the family $(S_\lambda,\varphi_\lambda)_{\lambda\in\Lambda}$.
Assume that each $S_\lambda$ has $m$-comparison.
To show that $S$ has $m$-comparison, let $x,y_0,\ldots ,y_m \in S$ satisfy $x<_s y_j$ for each $j=0,\ldots,m$.
We need to show that $x\leq y_0+\ldots +y_m$.

Let $x' \in S$ satisfy $x' \ll x$, and pick $z \in S$ such that $x' \ll z \ll x$.
Set $z' := x'$.
For each $j$, first pick $n_j\in\NN$ such that $(n_j+1)x \leq n_j y_j$, and then choose $y_j' \in S$ such that
\[
y_j' \ll y_j, \andSep
(n_j+1)z \ll n_j y_j'.
\]
Since $(S_\lambda,\varphi_\lambda)_{\lambda\in\Lambda}$ approximates $S$, there exists $\lambda$ and $u,w_0,\ldots,w_m \in S_\lambda$ such that
\[
z' \ll \varphi_\lambda(u) \ll z, \andSep
y_j' \ll \varphi_\lambda(w_j) \ll y_j \text{ for $j=0,\ldots,m$}
\]
and
\[
(n_j+1)u \ll n_j w_j \text{ for $j=0,\ldots,m$}.
\]
Then $u <_s w_0,\ldots,w_m$.
Since $S_\lambda$ has $m$-comparison, we get $u \leq w_0+\ldots+w_m$, and then
\[
x' = z' 
\leq \varphi_\lambda(u) 
\leq \sum_{j=0}^m \varphi_\lambda(w_j) 
\leq \sum_{j=0}^m y_j.
\]
Since this holds for every $x'$ way-below $x$, we get $x \leq y_0+\ldots+y_m$, as desired.
\end{proof}

%==========================================================================================
\begin{prp}
\label{prp:CompSepDet}
For each $m\in\NN$, the property of $m$-comparison is separably determined for \CuSgp{s}.
\end{prp}
\begin{proof}
Let $m\in\NN$.
It follows directly from the definitions that $m$-comparison passes to sub-\CuSgp{s}.
Therefore, $m$-comparison satisfies the L{\"o}wenheim-Skolem condition.
Further, by \cref{prp:CompApprox}, $m$-comparison passes to approximated \CuSgp{s}, and therefore passes to inductive limits by \cite[Proposition~3.5]{ThiVil21DimCu2}.
\end{proof}

%==========================================================================================
\begin{lma}
\label{prp:DivApprox}
For each $n\in\NN$, the property of $n$-almost divisibility passes to approximated \CuSgp{s}.
\end{lma}
\begin{proof}
Let $n\in\NN$, and let $S$ be a \CuSgp{} that is approximated by the family $(S_\lambda,\varphi_\lambda)_{\lambda\in\Lambda}$.
Assume that each $S_\lambda$ is $n$-almost divisible.
To show that $S$ is $n$-almost divisible, let $x',x \in S$ satisfy $x' \ll x$.
We need to find $y \in S$ such that $ky \leq x$ and $x' \leq (k+1)(n+1)y$.

We directly obtain $\lambda$ and $u \in S_\lambda$ such that
\[
x' \ll \varphi_\lambda(u) \ll x.
\]
Choose $u' \in S_\lambda$ such that
\[
u' \ll u, \andSep
x' \ll \varphi_\lambda(u').
\]
Using that $S_\lambda$ is $n$-almost divisible, we obtain $w \in S_\lambda$ such that $kw \leq u$ and $u' \leq (k+1)(n+1)w$.
Then $y:=\varphi_\lambda(w)$ has the desired properties.
\end{proof}

%==========================================================================================
\begin{prp}
\label{prp:DivSepDet}
For each $n\in\NN$, the property of $n$-almost divisibility is separably determined for \CuSgp{s}.
\end{prp}
\begin{proof}
Let $n\in\NN$.
By \cref{prp:DivApprox}, $n$-almost divisibility passes to approximated \CuSgp{s}, and therefore passes to inductive limits by \cite[Proposition~3.5]{ThiVil21DimCu2}.
It remains to show that it satisfies the L{\"o}wenheim-Skolem condition.

Let $S$ be an $n$-almost divisible \CuSgp{}, and let $\calC$ denote the family of separable sub-\CuSgp{s} that are $n$-almost divisible.
Using that $n$-almost divisibility passes to inductive limits, it follows that $\calC$ is $\sigma$-complete.
To show that~$\calC$ is cofinal, let $T_0 \in \Sep(S)$.
We need to find $T \in \Sep(S)$ with $T_0 \subseteq T$ and such that~$T$ is $n$-almost divisible.
Choose a countable basis $B_0 \subseteq T_0$.
The proof follows a standard technique, as for example the one used in \cite[Proposition~5.3]{ThiVil21DimCu2}.

We inductively choose an increasing sequence $(T_j)_j$ in $\Sep(S)$ and a countable basis $B_j \subseteq T_j$ such that for each $j \in \NN$ the following holds:
\begin{equation}
\tag{$\ast$}
\parbox{11cm}{\emph{For every $x',x \in B_j$ satisfying $x' \ll x$ and every $k\in\NN$, there exists $y_k \in B_{j+1}$ such that $ky_k \leq x$ and $x' \leq (k+1)(n+1)y_k$.}}
\end{equation}

We already chose $T_0$ and $B_0$.
Let $j\in\NN$ and assume we chose $T_j$ and $B_j$.
Set
\[
I_j := \big\{ (x',x) \in B_j \times B_j : x' \ll x \big\},
\]
which is countable since $B_j$ is. 

For each $i=(x',x) \in I_j$ and $k\in\NN$, since $S$ is $n$-almost divisible, we can pick $y_{i,k} \in S$ with $ky_{i,k} \leq x$ and $x' \leq (k+1)(n+1)y_{i,k}$. 
Now $B_j \cup \{ y_{i,k} : i \in I_j, k\in\NN \}$ is a countable subset of $S$, which by \cite[Lemma~5.1]{ThiVil21DimCu2} is contained in some separable sub-\CuSgp{} $T_{j+1} \subseteq S$.
Since $B_j$ is a basis for $T_j$, we have $T_j \subseteq T_{j+1}$.
Pick a countable basis $B_{j+1} \subseteq T_{j+1}$ that contains $B_j$.

Set $T:=\sup_j T_j \in \Sep(S)$.
Clearly $T_0 \subseteq T$, and we claim that $T$ is $n$-almost divisible.
To verify this, let $x' \ll x$ in $T$, and let $k\in\NN$.
Since every element in $T$ is the supremum of an increasing sequence in $\bigcup_j T_j$, we see $\bigcup_j B_j$ is a basis for $T$, which allows us to find $j$ and $u',u \in B_j$ such that $x' \leq u' \ll u \leq x$.
Applying $(\ast)$, we obtain the desired element in $T_{j+1} \subseteq T$.
\end{proof}

%==========================================================================================
\begin{prp}
\label{prp:PureSepDetCu}
For each $m,n\in\NN$, the property of $(m,n)$-pureness is separably determined for \CuSgp{s}.
\end{prp}
\begin{proof}
In general, the conjunction of finitely (or even countably) many separably determined properties is itself separably determined.
Therefore, the result follows by combining \cref{prp:CompSepDet,prp:DivSepDet}.
\end{proof}

%==========================================================================================
\begin{thm}
\label{prp:PureSepDet}
Pureness of \ca{s} is separably determined.
\end{thm}
\begin{proof}
This follows from \cref{prp:RelateSepDet} with \cref{prp:PureSepDetCu} for $m=n=0$.
\end{proof}

%==========================================================================================
\begin{rmk}
The result that a \ca{} is pure whenever it is approximated by pure sub-\ca{s} can also be deduced from \cite[Corollary~4.8]{BosVil25PureHom}.
\end{rmk}

%==========================================================================================
\begin{cor}
\label{prp:CharPureness}
A \ca{} is pure if and only if every separable sub-\ca{} is contained in a separable, pure sub-\ca{}.

A \ca{} has strict comparison (of positive elements by quasitraces) if and only if every separable sub-\ca{} is contained in a separable sub-\ca{} with strict comparison.
\end{cor}

%==========================================================================================
\begin{rmk}
In \cite[Sections~3,4]{AntPerThiVil24arX:PureCAlgs} the study of the unquantized notion of \emph{controlled comparison} (resp. \emph{functional divisibility}) was crucial to obtain the dimension reduction phenomenon \cite[Theorem~C]{AntPerThiVil24arX:PureCAlgs}. Controlled comparison (resp. functional divisibility) is weaker than $m$-comparison for any $m$ (resp. $n$-almost divisibility for any $n$); see \cite[Proposition~4.9]{AntPerThiVil24arX:PureCAlgs} and \cite[Proposition~10.3]{AntPerRobThi24TracesUltra}.

We have shown in this section that the notions of $m$-comparison and $n$-almost divisibility are separably determined. However, this is not true for controlled comparison. 
Indeed, some Villadsen algebras of first type (e.g. the one in \cite{Tom08ClassificationNuclear}) fail to have controlled comparison \cite[Example~5.16]{AntPerThiVil24arX:PureCAlgs}, although they are built as inductive limits whose blocks have controlled comparison (since each block has $m$-comparison for some $m$). 

In contrast, functional divisibility passes to limits. In fact, one can use techniques similar to those in this section to show that it is separably determined.
\end{rmk}

%==========================================================================================
%==========================================================================================
\section{Comparison and divisibility of extensions} 
\label{sec:CompDivExt}

%==========================================================================================
In this section we prove the main result of the paper (\cref{prp:PureExt}): pureness passes to extensions of \ca{s}.
At the level of \CuSgp{s}, we show that the property of being $(m,n)$-pure for some $m,n\in\NN$ passes to extensions;
see \cref{prp:PureExtCu}.
However, the `degree of pureness' may potentially decrease.
In particular, we establish that an extension of pure (that is, $(0,0$)-pure) \CuSgp{s} is $(1,1)$-pure.
In the \ca{} setting, this is sufficient because, as already mentioned, every $(1,1)$-pure \ca{} is pure (\cite[Theorem~5.7]{AntPerThiVil24arX:PureCAlgs}).

\medskip

%==========================================================================================
In the results below, we use additional order-theoretic properties for \CuSgp{s} that are labelled \axiomO{5}-\axiomO{8}. Except for \axiomO{5}, the other properties are needed as assumptions in other results in the literature that will be quoted. Therefore, we will only recall the formulation of \axiomO{5} when needed (namely, in the proof of \cref{prp:DivExtSep}). Let us remark that the Cuntz semigroup of every \ca{} satisfies \axiomO{5}-\axiomO{8}: specifically, we refer to \cite[Proposition~4.6]{AntPerThi18TensorProdCu} for \axiomO{5}, to \cite[Proposition~5.1.1]{Rob13Cone} for \axiomO{6}, to \cite[Proposition~2.2]{AntPerRobThi21Edwards} for \axiomO{7}, and to \cite[Theorem~7.4]{ThiVil24NowhereScattered} for \axiomO{8}.

Given a \CuSgp{} $S$, an \emph{ideal} is a submonoid $I \subseteq S$ that is closed under suprema of increasing sequences and that is downward hereditary (that is, if $x,y \in S$ satisfy $x \leq y$ and $y \in I$, then $x \in I$).
Given an ideal $I$, the relations $\leq_I$ and $\sim_I$ on~$S$ are defined by setting $x \leq_I y$ if there exists $w \in I$ such that $x \leq y+w$, and by setting $x \sim_I y$ if $x \leq_I y$ and $y \leq_I x$.
Then $\sim_I$ is an equivalence relation, and the set of equivalence classes is denoted by $S/I$.
The addition on $S$ induces an addition on $S/I$, and the relation $\leq_I$ induces a partial order on $S/I$.
This gives $S/I$ the structure of a \CuSgp{}; see \cite[Section~5.1]{AntPerThi18TensorProdCu} for details. Note that, upon replacing $w$ by $\infty w:=\sup_n nw$ in the definition of $\leq_I$, we may assume that $w\in I$ is an idempotent, i.e. $2w=w$.

%==========================================================================================
\begin{lma}
\label{prp:CompExtSep}
Let $S$ be a separable \CuSgp{} satisfying \axiomO{5}-\axiomO{7}, and let~$I$ be an ideal in~$S$.
Assume that $S/I$ has $m_1$-comparison, and that $I$ has $m_2$-comparison.
Then $S$ has $(m_1+m_2+1)$-comparison.
\end{lma}
\begin{proof}
To verify that the \CuSgp{} $S$ has $(m_1+m_2+1)$-comparison, let $x,y_0,\ldots,y_{m_1},z_0,\ldots,z_{m_2} \in S$ be such that $x<_s y_j$ for $j=0,\ldots,m_1$ and $x <_s z_j$ for $j=0,\ldots,m_2$.
We need to show that $x \leq y_0+\ldots+y_{m_1}+z_0+\ldots+z_{m_2}$.

The relations $x<_s y_j$ still hold when passing to the quotient $S/I$. 
Using that~$S/I$ has $m_1$-comparison, we get that
\begin{equation}
\label{eq:CompExt-1}
x \leq y_0+\ldots+y_{m_1}+w
\end{equation}
for some idempotent $w \in I$. 
%By replacing~$w$ with $\infty w$ (which is defined as $\infty w := \sup_n nw$), we may assume that~$w$ is idempotent, that is, that $w=2w$. 

As shown in \cite[Theorem~2.4]{AntPerRobThi21Edwards}, in separable \CuSgp{s} satisfying \axiomO{7}, the infimum between an arbitrary element and an idempotent element exists.
In our setting, it follows that $x \wedge w$ exists in $S$.
Moreover, by applying \cite[Theorem~2.5~(ii)]{AntPerRobThi21Edwards} to \eqref{eq:CompExt-1}, it follows that
\begin{equation}
\label{eq:CompExt-2}
x \leq y_0+\ldots+y_{m_1}+(x\wedge w).
\end{equation}

By \cite[Theorem~2.5~(i)]{AntPerRobThi21Edwards}, the map $S \to I$, $z \mapsto (z\wedge w)$, is a generalized \CuMor.
It follows that $(x\wedge w)<_s(z_j\wedge w)$ for $j=0,\ldots,m_2$.
Using that $I$ has $m_2$-comparison, we get that
\[
(x\wedge w) 
\leq (z_0\wedge w)+\ldots+(z_{m_2}\wedge w)
\leq z_0+\ldots+z_{m_2}.
\]
Combining this estimate with \eqref{eq:CompExt-2}, we get 
\[
x 
\leq y_0+\ldots+y_{m_1}+(x\wedge w)
\leq y_0+\ldots+y_{m_1}+z_0+\ldots+z_{m_2},
\]
as desired.
\end{proof}

%==========================================================================================
\begin{prp}
\label{prp:OSepDet}
Each of the properties \axiomO{5}-\axiomO{8} is separably determined.
\end{prp}
\begin{proof}
Each of the properties \axiomO{5}-\axiomO{7} satisfies the L{\"o}wenheim-Skolem condition by \cite[Proposition~5.3]{ThiVil21DimCu2}, and passes to inductive limits by \cite[Corollary~3.6]{ThiVil21DimCu2}.
With similar methods, one shows that also \axiomO{8} is separably determined.
\end{proof}

%==========================================================================================
Let $I$ be an ideal in a \CuSgp{} $S$, and let $\pi_I \colon S \to S/I$ be the quotient map.
If $T \subseteq S$ is a sub-\CuSgp{}, then it is not clear that $\pi_I(T)$ is a sub-\CuSgp{} of $S/I$.
However, the next result shows that there are many separable sub-\CuSgp{s} of $S$ with this property.
The result is proved with similar methods as \cref{prp:RelateClubs} and \cite[Proposition~6.1]{ThiVil21DimCu2}.
We omit the details.

%==========================================================================================
\begin{lma}
\label{prp:RelateClubsQuot}
Let $S$ be a \CuSgp{}, let~$I$ be an ideal in~$S$, and let $\pi_I \colon S \to S/I$ be the quotient map.
Then the collection $\calC_0$ of separable sub-\CuSgp{s} $T \subseteq S$ such that $\pi_I(T)$ is a sub-\CuSgp{} of $S/I$ is a club in $\Sep(S)$.

Further, if $\calD\subseteq\Sep(S/I)$ is a club, then so is
\[
\calC := \big\{ T \in \calC_0 : \pi_I(T) \in \calD \big\}.
\]
\end{lma}

%==========================================================================================
\begin{lma}
\label{prp:RelateClubsIdl}
Let~$I$ be an ideal in a \CuSgp{}~$S$, and let $\calD \subseteq \Sep(I)$ be a club.
Then $\{T \in \Sep(S) : I \cap T \in \calD\}$ is a club in $\Sep(S)$.
\end{lma}
\begin{proof}
This is the \CuSgp{} analog of \cite[Lemma~3.2(1)]{Thi23grSubhom} and can be proved with similar methods.
We omit the details.
\end{proof}

%==========================================================================================
\begin{prp}
\label{prp:CompExt}
Let $S$ be a \CuSgp{} satisfying \axiomO{5}-\axiomO{7}, and let~$I$ be an ideal in~$S$.
Assume that $S/I$ has $m_1$-comparison, and that $I$ has $m_2$-comparison.
Then $S$ has $(m_1+m_2+1)$-comparison.
\end{prp}
\begin{proof}
Let $\pi_I \colon S \to S/I$ denote the quotient map.
Let $\calC$ be the family of separable sub-\CuSgp{s} of $S/I$ that have $m_1$-comparison.
Since $m_1$-comparison is separably determined (\cref{prp:CompSepDet}), it follows from \cref{prp:ClubWithPropertyCu} that $\calC$ is a club.
Similarly, the family $\calD$ of separable sub-\CuSgp{s} of $I$ that have $m_2$-comparison is a club.
By \cref{prp:RelateClubsQuot,prp:RelateClubsIdl}, the collections
\begin{align*}
\calC' 
&:= \big\{T \in \Sep(S) : \pi_I(T) \text{ is a sub-\CuSgp{}}, \pi_I(T)  \in \calC \big\}, \andSep \\
\calD' 
&:= \big\{T \in \Sep(S) : T \cap I \in \calD \big\}
\end{align*}
are clubs in $\Sep(S)$.

By \cref{prp:OSepDet}, the families $\calE_{\axiomO{5}}$, $\calE_{\axiomO{6}}$ and $\calE_{\axiomO{7}}$ of separable sub-\CuSgp{s} of $S$ that satisfy \axiomO{5}, \axiomO{6} and \axiomO{7}, respectively, are clubs.
Set
\[
\calF := \calC' \cap \calD' \cap \calE_{\axiomO{5}} \cap \calE_{\axiomO{6}} \cap \calE_{\axiomO{7}}.
\]
Since the intersection of at most countably many clubs is again a club, it follows that $\calF$ is a club in $\Sep(S)$.

Let $T \in \calF$.
Then $T$ is a separable \CuSgp{} satisfying \axiomO{5}-\axiomO{7}, and $T \cap I$ is an ideal in $T$ such that $T/(I \cap T)$ has $m_1$-comparison (since it is isomorphic to $\pi_I(T)$ and $T \in \calC'$) and such that $I \cap T$ has $m_2$-comparsion (since $T \in \calD'$).
By \cref{prp:CompExtSep}, $T$ has $(m_1+m_2+1)$-comparison.
Since $\calF$ is a club in $S$, and since $(m_1+m_2+1)$-comparison is separably determined, it follows that $S$ has $(m_1+m_2+1)$-comparison.
\end{proof}

%==========================================================================================
We now turn to divisibility properties of extensions.

%==========================================================================================
\begin{lma}
\label{prp:LiftDiv}
Let $S$ be a separable \CuSgp{} satisfying \axiomO{5}-\axiomO{8}, and let~$I$ be an ideal in~$S$, and assume that $S/I$ is $n$-almost divisible.
Let $x' \ll x$ in $S$, and let $k\in\NN$.
Then there exist $u \in S$ and an idempotent $w \in I$ such that
\[
ku \ll x, \andSep
x' \ll (k+1)(n+1)u + w.
\]
\end{lma}
\begin{proof}
Find $x'' \in S$ such that $x' \ll x'' \ll x$.
Since the quotient map $S \to S/I$ is a \CuMor{}, the image of $x''$ is way-below the image of $x$ in $S/I$.
Using that $S/I$ is $n$-almost divisible, we find $y \in S$ such that
\[
ky \leq_I x, \andSep
x'' \leq_I (k+1)(n+1)y.
\]
This gives idempotent elements $w_1,w_2 \in I$ such that
\[
ky \leq x + w_1, \andSep
x'' \leq (k+1)(n+1)y + w_2.
\]
%Set $w:=\infty(w_1+w_2)$, which is an idempotent in $I$.
Set $w:=w_1+w_2$. Using that $x' \ll x''$, we then have
\[
ky \leq x + w, \andSep
x' \ll (k+1)(n+1)y + w.
\]
Choose $y'',y' \in S$ such that
\[
y'' \ll y' \ll y, \andSep 
x' \ll (k+1)(n+1)y'' + w.
\]
Then $ky' \ll x + w$ and $y'' \ll y'$, which allows us to apply \cite[Proposition~7.8]{ThiVil24NowhereScattered} to obtain $u \in S$ such that
\[
ku \ll x, \quad
y'' \ll u + w, \andSep
u \ll y' + w.
\]
Using that $w$ is idempotent, we get
\[
x' \ll (k+1)(n+1)y'' + w
\leq (k+1)(n+1)u + w,
\]
as desired.
\end{proof}

%==========================================================================================
\begin{lma}
\label{prp:DivExtSep}
Let $S$ be a separable \CuSgp{} satisfying \axiomO{5}-\axiomO{8}, and let~$I$ be an ideal in~$S$.
Assume that $S/I$ is $n_1$-almost divisible, and that $I$ is $n_2$-almost divisible.
Then $S$ is $n$-almost divisible for $n=\max\{2n_1+1,2n_2+1\}$.
\end{lma}
\begin{proof}
Let $x'',x \in S$ with $x'' \ll x$, and let $k \in \NN$. 
We need to find $d \in S$ such that $kd \leq x$ and $x'' \leq (k+1)(n+1)d$.
Pick $x' \in S$ such that $x'' \ll x' \ll x$.
Applying \cref{prp:LiftDiv} for $2k$ and $x' \ll x$, we obtain $z \in S$ and an idempotent $w \in I$ such that
\begin{equation}
\label{eq:DivExt-1}
2kz \ll x, \andSep
x' \ll (2k+1)(n_1+1)z + w.
\end{equation}
Find $z'',z' \in S$ such that
\[
z'' \ll z' \ll z, \andSep
x' \ll (2k+1)(n_1+1)z'' + w.
\]

The `almost algebraic order' property \axiomO{5} means that for $r',r,s',s,t \in S$ with $r+s \leq t$ and $r' \ll r$, $s' \ll s$, there exists $u \in S$ such that $r' + u \leq t \leq r+u$ and $s' \ll u$.
In our setting, we have
\[
kz' + kz \leq x, \quad
kz'' \ll kz', \andSep
kz' \ll kz.
\]
Applying \axiomO{5}, we obtain $u \in S$ such that
\[
kz'' + u \leq x \leq kz' + u, \andSep
kz' \ll u.
\]
Then
\[
x \leq 2u.
\]

As in the proof of \cref{prp:CompExtSep}, we use that infima between $w$ and arbitrary elements in $S$ exist.
By applying \cite[Theorem~2.5~(ii)]{AntPerRobThi21Edwards} to \eqref{eq:DivExt-1} at the first step, and by using that $s \mapsto (s\wedge w)$, is a generalized \CuMor{} (\cite[Theorem~2.5~(i)]{AntPerRobThi21Edwards}) at the second step, we get
\[
x' 
\leq (2k+1)(n+1)z'' + (x' \wedge w)
\leq (2k+1)(n+1)z'' + 2(u \wedge w).
\]
Choose $u' \in S$ such that
\[
u' \ll (u \wedge w), \andSep
x'' \leq (2k+1)(n+1)z'' + 2u'.
\]

Using that $I$ is $n_2$-almost divisible for $k$ and $u' \ll (u \wedge w)$, we obtain $v \in I$ such that
\[
kv \leq u \wedge w, \andSep
u' \leq (k+1)(n_2+1)v.
\]
Set $d:=z''+v$.
Then
\[
kd 
= kz'' + kv
\leq kz'' + (u \wedge w)
\leq kz'' + u
\leq x.
\]
Further,
\begin{align*}
x''
&\leq (2k+1)(n_1+1)z'' + 2u' \\
&\leq 2(k+1)(n_1+1)z'' + 2(k+1)(n_2+1)v \\
&\leq (k+1)(n+1)z''+(k+1)(n+1)v \\
&= (k+1)(n+1)d.
\end{align*}
This shows that $d$ has the desired properties.
\end{proof}

%==========================================================================================
\begin{prp}
\label{prp:DivExt}
Let $S$ be a \CuSgp{} satisfying \axiomO{5}-\axiomO{8}, and let~$I$ be an ideal in~$S$.
Assume that $S/I$ is $n_1$-almost divisible, and that $I$ is $n_2$-almost divisible.
Then $S$ is $n$-almost divisible for $n=\max\{2n_1+1,2n_2+1\}$.
\end{prp}
\begin{proof}
This is proved analogous to \cref{prp:CompExt}.
We omit the details.
\end{proof}

%==========================================================================================
\begin{lma}
\label{prp:PureIdlQuot}
Let $I$ be an ideal in a \CuSgp{} $S$.
If $S$ has $m$-comparison, then so do $I$ and $S/I$.
If $S$ is $n$-almost divisible, then so are $I$ and $S/I$.
%Then $I$ and $S/I$ are $(m,n)$-pure.
\end{lma}
\begin{proof}
It follows directly from the definitions that $m$-comparison and $n$-almost divisibility pass to ideals.
Assuming that $S$ has $m$-comparison, let us verify that~$S/I$ has $m$-comparison as well.
Let $x,y_0,\ldots,y_m \in S$ be elements such that the image of $x$ in $S/I$ is $<_s$-below the image of $y_j$ in $S/I$ for each $j$.
For each $j$, we obtain $n_j \in \NN$ and $w_j \in I$ such that
\[
(n_j+1)x \leq n_j y_j + w_j.
\]
Then $(n_j+1)x \leq n_j(y_j+w_j)$ and so $x<_s(y_j+w_j)$.
Using that $S$ has $m$-comparison, it follows that 
\[
x \leq (y_0+w_0)+\ldots+(y_m+w_m) = (y_0+\ldots+y_m)+(w_0+\ldots+w_m).
\]
Since $w_0+\ldots+w_m$ belongs to $I$, we get $x \leq_I y_0+\ldots+y_m$, as desired.

Assuming that $S$ is $n$-almost divisible, let us verify that~$S/I$ is $n$-almost divisible.
Let $\pi_I \colon S \to S/I$ denote the quotient map, and let $u',u \in S/I$ with $u' \ll u$, and let $k\in\NN$.
Pick a lift $x \in S$ of $u$.
Using that $\pi_I$ preserves suprema of increasing sequences, we find $x' \in S$ with $x' \ll x$ and $u' \leq \pi_I(x')$.
Using that $S$ is $n$-almost divisible, we obtain $y \in S$ such that $ky \leq x$ and $x' \leq (k+1)(n+1)y$.
Then $\pi_I(y)$ has the desired properties.
\end{proof}

%==========================================================================================
\begin{thm}
\label{prp:PureExtCu}
Let $S$ be a \CuSgp{} satisfying \axiomO{5}-\axiomO{8}, and let~$I$ be an ideal in~$S$.
Then $S$ is $(m,n)$-pure for some $m,n\in\NN$ if and only if $I$ is $(m',n')$-pure for some $m',n'\in\NN$ and $S/I$ is $(m'',n'')$-pure for some $m'',n''\in\NN$.
%Assume that $S/I$ is $(m_1,n_1)$-pure and that $I$ is $(m_2,n_2)$-pure.
%Then $S$ is $(m,n)$-pure for $m=m_1+m_2+1$ and $n=\max\{2n_1+1,2n_2+1\}$.
\end{thm}
\begin{proof}
The forward implication follows from \cref{prp:PureIdlQuot}, and the backward implication follows from \cref{prp:CompExt,prp:DivExt}.
\end{proof}

%==========================================================================================
\begin{thm}
\label{prp:PureExt}
Let $I$ be a closed ideal in a \ca{} $A$.
Then $A$ is pure if and only if~$I$ and~$A/I$ are pure.
\end{thm}
\begin{proof}
By \cite{CiuRobSan10CuIdealsQuot}, we can identify $\Cu(I)$ with an ideal in $\Cu(A)$ such that $\Cu(A/I)$ is naturally isomorphic to $\Cu(A)/\Cu(I)$;
see also \cite[Section~5.1]{AntPerThi18TensorProdCu}.
Therefore, the forward implication follows from \cref{prp:PureIdlQuot}.

For the backward implications, assume that $I$ and $A/I$ are pure. Since, as mentioned before, Cuntz semigroups of \ca{s} always satisfy \axiomO{5}-\axiomO{8}, we may apply \cref{prp:CompExt,prp:DivExt} to deduce that $\Cu(A)$ is $(1,1)$-pure. By \cite[Theorem~5.7]{AntPerThiVil24arX:PureCAlgs}, it follows that $A$ is pure.
\end{proof}

%==========================================================================================
\begin{rmk}
%\label{prp:CompExtCa}
Let $I$ be a closed ideal in a \ca{} $A$.
By \cref{prp:PureIdlQuot}, if $A$ has $0$-comparison (that is, strict comparison of positive elements by quasitraces), then so do $I$ and $A/I$.
Similarly, if $A$ is $0$-almost divisible, then so are $I$ and $A/I$.

In the converse direction, applying \cref{prp:CompExt} and \cref{prp:DivExt}, and arguing as in the proof of \cref{prp:PureExt}, we get:
\begin{enumerate}
\item
If $I$ and $A/I$ have $0$-comparison, then $A$ has $1$-comparison.
\item
If $I$ and $A/I$ are $0$-almost divisible, then $A$ is $1$-almost divisible.
\end{enumerate}
\end{rmk}

%==========================================================================================
Since the reduction phenomenon \cite[Theorem~5.7]{AntPerThiVil24arX:PureCAlgs} does not hold for comparison or divisibility individually, the following questions remain open:

%==========================================================================================
\begin{qst}
\label{qst:CompExt}
Does strict comparison (of positive elements by quasitraces) pass to extensions of \ca{s}?
\end{qst}

%==========================================================================================
\begin{qst}
\label{qst:DivExt}
Does almost divisibility pass to extensions of \ca{s}?
\end{qst}

%==========================================================================================
We end with an application of the main result to the structure of stable multiplier algebras.
A \ca{} is said to be \emph{separably $\calZ$-stable} if it contains a club of separable, $\calZ$-stable sub-\ca{s}.
Since every $\calZ$-stable \ca{} is pure (\cite{Ror04StableRealRankZ}), it follows from \cref{prp:PureSepDet} that every separably $\calZ$-stable \ca{} is pure.
In \cite[Theorem~B]{FarSza24arX:CoronaSSA}, Farah and Szab\'{o} show that a $\sigma$-unital \ca{} $A$ is separably $\calZ$-stable if and only if its multiplier algebra is.
In particular, if $A$ is a unital $\calZ$-stable \ca{}, then its \emph{stable multiplier algebra} $M(A\otimes\Cpct)$ is pure.
In \cref{exa:GroupCa} we give examples of pure, non-$\calZ$-stable \ca{s} whose stable multiplier algebra is pure.

In \cite{KucNgPer10PICorona} and \cite{KafNgZha19PICorona}, the authors study when the corona algebra of a simple \ca{} is purely infinite. Building on these results, we obtain:

