\begin{prp}
	\label{prp:PureStableMult}
	Let $A$ be a simple, separable, unital \ca.
	\begin{enumerate}
		\item[{\rm (1)}] If $A$ is exact and has finitely many extremal traces and strict comparison of positive elements, then $M(A\otimes\Cpct)$ is pure if and only if $A$ is pure.
		\item[{\rm (2)}] If $A$ has stable rank one and strict comparison of positive elements by a unique tracial state, then $M(A\otimes\Cpct)$ is pure.
	\end{enumerate}
\end{prp}
\begin{proof}
	We consider the extension
	\[
	0 \to A\otimes\Cpct \to M(A\otimes\Cpct) \to M(A\otimes\Cpct)/(A\otimes\Cpct) \to 0.
	\]
	(1): It was proved in \cite[Theorem~4.5]{KucNgPer10PICorona} that, under these assumptions, the corona $M(A\otimes\Cpct)/(A\otimes\Cpct)$ is purely infinite, hence pure. The result then follows from \cref{prp:PureExt}.

\noindent (2):	By \cite[Corollary~8.12]{Thi20RksOps}, $A\otimes\Cpct$ is pure. 
	Further, it follows from \cite[Corollary~4.11]{KafNgZha19PICorona} that $A\otimes\Cpct$ has projection surjectivity and injectivity, which allows us to apply \cite[Corollary~6.12]{KafNgZha19PICorona}.
	Since $A$ has a unique tracial state, it follows that its stable corona algebra is purely infinite, and therefore pure. Again the result follows from \cref{prp:PureExt}.
\end{proof}

%==========================================================================================
\begin{exa}
\label{exa:GroupCa}
Let $G$ be a countable, discrete group that is acylindrically hyperbolic with trivial finite radical, and that has the rapid decay property.
Then the reduced group \ca{} $C^*_{\mathrm{red}}(G)$ is simple, separable, unital and has stable rank one (\cite[Theorem~1.1]{GerOsi20InvGpCAlgAcylHyperbolic}, see also \cite{Rau24arX:TwAcylHypGps}), and has strict comparison with respect to its unique tracial state (\cite[Theorem~B]{AmrGaoElaPat24arX:StrCompRedGpCAlgs}).
Therefore, \cref{prp:PureStableMult} applies and shows that $M(C^*_{\mathrm{red}}(G)\otimes\Cpct)$ is pure.

This applies in particular to free groups $\mathbb{F}_n$ for $n=2,3,\ldots,\infty$.
Thus, the stable multiplier algebras of the reduced free group \ca{s} $C^*_{\mathrm{red}}(\mathbb{F}_n)$ are pure.
\end{exa}



