\title{Sequence-to-Sequence Models with Attention Mechanistically Map to the Architecture of Human Memory Search}

\author[1]{Nikolaus Salvatore}
\author[1,2,3,*]{Qiong Zhang}
\affil[1]{Rutgers University-New Brunswick, Department of Computer Science, Piscataway, 08854, USA}
