\section{Model Outline and Large Deviations Principle}

%In this section we outline a general Large Deviation Principle for a Markovian switching process with fast and slow components. In the next section we determine specific Euler-Lagrange equations, and the section after this we apply it to the stochastic opening and closing of calcium channels in cells.

A chemical reaction network \cite{Anderson2015} consists of the following triple:
\begin{itemize}
\item \textit{species} $\mathscr{S}$, which are the chemical components whose counts we wish to model dynamically. There are $d$ of these.
\item \textit{complexes} $\mathscr{C}$ which are nonnegative linear combinations of the species that describe how the species can interact and
\item \textit{reactions} $\mathscr{R}$ which describe how to convert one complex to another.
\end{itemize}
Let $X(t) \in \mathbb{Z}_+^d$ be a vector that counts the number of particles of each species. For a reaction $\alpha\in\mathscr{R}$, let $Z_{\alpha}(t) \in \mathbb{Z}_+$ count the number of times the reaction has occured. We thus have that
\begin{equation}
X(t)  =X(0) + \sum_{\alpha \in \mathscr{R}}Z_{\alpha}(t) \xi_{\alpha} 
\end{equation}
where $\xi_\alpha \in \mathbb{Z}^d$ is the reaction vector corresponding to the $\alpha^{th}$ reaction. We define the concentration vector to be the scaled number of particles, i.e.
\begin{align}
x(t) &=  N^{-1} X(t) = N^{-1}X(0)+  \sum_{\alpha \in \mathscr{R}}z_{\alpha}(t) \xi_{\alpha} , \label{eq: x definition}
\end{align}
where $N \gg 1$ is a scaling parameter that indicates the system size (for instance, the total number of particles at time $0$).

The intensity of the $\alpha^{th}$ reaction is defined to be
\begin{equation}
N\lambda_\alpha\big( x(t) ,  u(t) \big), \label{eq: intensity of N system}
\end{equation}
where $\lambda_\alpha: \mathbb{R}^d \times \mathbb{R}^m \to \mathbb{R}^+$ is continuous and bounded. It is assumed that reactions cannot produce a negative concentration: that is, it is assumed that if $x\in \mathbb{R}_+^d$ and $u \in \mathbb{R}^m$, and $\alpha\in \mathscr{R}$ are such that $x + N^{-1}\xi_{\alpha} \notin \mathbb{R}_+^d$, then necessarily $\lambda_{\alpha}(x,u) =0$.


%We assume that $\lambda^N_n$ can only have zeros on the boundary (if it is to have any zeros at all), i.e. we assume that for any $\delta > 0$, there exists $\epsilon > 0$ such that
%\begin{equation}
%\big\lbrace (x,u): \lambda^N_n(x,u) =0 \big\rbrace \subseteq \big\lbrace (x,u): \inf_{1\leq i \leq d} |x_i | = 0 \big\rbrace .
%\end{equation}
%We also assume that if $\xi_{\alpha}^{i} < 0$ and $x^i \leq 1$, then necessarily 
%\begin{equation}\label{eq: assumption lower bound reaction rates}
%\lambda_{\alpha}(x,u) \leq x^i p_{\alpha}(x),
%\end{equation}
%for some $p_{\alpha}$ which is polynomial in the variables $(x^1,\ldots,x^{i-1},x^{i+1},\ldots,x^d)$. This assumption essentially bounds the rate at which molecules are destroyed in reactions: it is consistent with mass-action kinetics \cite{Feinberg2019}, however it rules out (for example) the annihilation of species at rates that are independent of their concentrations.


%We also assume that there is a uniform large $N$ limit of the reaction intensity, i.e. for any $C > 0$,
%\begin{align}
%\lim_{N\to\infty} \sup_{\norm{x},\norm{u} \leq C}\big| \lambda^N_n( x ,  u) - \lambda_n( x ,  u) \big| = 0.
%\end{align}
The ordinary differential equation takes values in a state space $\mathbb{R}^m$, and is such that
\begin{align}\label{eq: u ODE}
\frac{du}{dt} = A\big( u(t), x(t) \big),
\end{align}
where $A: \mathbb{R}^m \times \mathbb{R}^d \to \mathbb{R}^d$ is continuous. The initial conditions are taken to be non-random constants i.e. 
\begin{align}
u(0) &:=  \hat{u}^N_0 \text{ and }
x(0) :=  \hat{x}^N_0.
\end{align}
and it is assumed that the following limits exist
\begin{align}
\lim_{N\to\infty} \hat{u}^N_0 &= \hat{u}_0 \\
\lim_{N\to\infty} \hat{x}^N_0 &= \hat{x}_0.
\end{align}
%Finally it is assumed that the initial jump rates are always non-zero in the large $N$ limit, i.e. it is assumed that
%\begin{align}
%\inf_{\alpha\in\mathscr{R}}\lambda_{\alpha}\big( \hat{x}_0 , \hat{u}_0 \big) > 0.
%\end{align}
We assume the following uniform growth bounds: for some constant $K > 0$, for all $t\geq 0$, and $u\in \mathbb{R}^m$, and all $\alpha \in \mathscr{R}$,
\begin{align}
\norm{ A( u , X  ) } &\leq K \big(1 + \norm{u} + \norm{X}\big) \label{eq: bound the u intensity} \\
\big| \lambda_\alpha\big( X , u \big) \big| &\leq K.% \big(1 + \norm{u} + \norm{X}\big). \label{eq: bound the lambda intensity}% \big(1 + \norm{u} + \norm{X(t)}\big). 
\end{align}
Second, we assume that $A$ and $\lambda_n$ are both uniformly Lipschitz in their arguments: that is,% for any compact subset $\mathcal{K}$ of $\mathbb{R}^m \times \mathbb{R}^d$, there exists a constant $C(\mathcal{K})$ such that
\begin{align}
\norm{ A\big( u, X \big) -A\big( \tilde{u}, \tilde{X} \big)   } &\leq C \big\lbrace \norm{u - \tilde{u}} + \norm{X - \tilde{X}} \big\rbrace \\
\sup_{\alpha \in \mathscr{R}}\| \lambda_\alpha\big( u, X \big) -\lambda_\alpha\big( \tilde{u}, \tilde{X} \big)   \| &\leq C\big\lbrace \norm{u - \tilde{u}} + \norm{X - \tilde{X}} \big\rbrace .
\end{align}
Standard ODE theory dictates that for any piecewise-continuous $x$, there is a unique solution to the ODE in \eqref{eq: u ODE}.

 The linearity of Poisson Processes ensures that $Z_{\alpha}(t)$ can be represented as, writing $\lbrace Y_{\alpha}(t) \rbrace_{\alpha \in \mathscr{R}}$ to be independent unit-intensity Poisson Processes \cite{Anderson2015},
\begin{align}
Z_{\alpha}(t) %=& %Y_{\alpha}\bigg(\sum_{j=1}^N \int_0^t \chi\lbrace \sigma^j_s = \alpha\rbrace \mathcal{V}_{\alpha\beta}( u(s) , \bar{\sigma}_s)ds \bigg)\nonumber \\
=&  Y_{\alpha}\bigg(N \int_0^t  \lambda_{\alpha}\big( x(s) , u(s) \big) ds \bigg)\label{eq: Z definition} \\
z_{\alpha}(t) =& N^{-1}Z_{\alpha}(t) \text{ with initial condition} \\
z_{\alpha}(0) =& 0.
\end{align}
Writing $y_{\alpha}(t) = N^{-1}Y_{\alpha}(Nt)$, it may be observed that
\begin{equation}
z_{\alpha}(t) = y_{\alpha}\bigg(  \int_0^t  \lambda_{\alpha}\big( x(s) , u(s) \big) ds \bigg).\label{eq: Z definition next} 
\end{equation}

The main result of this paper is the following theorem. Further below in \eqref{Upsilon Definition} we specify $\Upsilon$ to be the state space that the triple $(z,x,u)$ lives in (and we define a topology too). The sequence of probability laws of $\big( z,x,u \big)$ satisfies the following asymptotic estimate on the space $\Upsilon$ as $N\to\infty$.
\begin{theorem}\label{Theorem Main LDP}
%Define $\Upsilon^1 \subset \Upsilon$ to consist of all $(z,x,u)$ such that for each $\alpha \in \mathscr{R}$, $z_{\alpha}$ is differentiable Lebesgue-almost-everywhere, and the derivative $\dot{z}_{\alpha}$ has only a finite number of points of discontinuity over any finite time interval.  
Supponse that $\mathcal{O},\mathcal{A} \subset \Upsilon$, with $\mathcal{O}$ open and $\mathcal{A}$ closed, are such that for any $T > 0$,
\begin{align}
\inf_{ (z,x,u) \in \mathcal{A} \cup \mathcal{O}} \inf_{\alpha\in\mathscr{R}} \inf_{s\in [0,T]} \lambda_\alpha(x(s),u(s)) > 0. \label{eq: set infimum lambda first statement}
\end{align}
Then there exists a function $\mathcal{J}: \Upsilon \to \mathbb{R}$ (specified in Section \ref{Section Topological Definitions}) that is (i) lower-semi-continuous and (ii) has compact level sets, such that
\begin{align}
\lsup{N}N^{-1}\log \mathbb{P}\big( (z,x,u) \in \mathcal{A} \big) &\leq - \inf_{(z,x,u) \in \mathcal{A}}\mathcal{J}(z,x,u) \\
\linf{N}N^{-1}\log \mathbb{P}\big( (z,x,u) \in \mathcal{O} \big) &\geq - \inf_{(z,x,u)\in \mathcal{O}}\mathcal{J}(z,x,u).
\end{align}
 \end{theorem}

\subsection{Topological Definitions} \label{Section Topological Definitions}
Before we state our main result we must briefly note the topological space that our variables belong to. Write the state space for $\big( z,x, u \big)$ as $\Upsilon$, i.e.
\begin{multline}\label{Upsilon Definition}
\Upsilon :=  \big\lbrace (z,x,u) \in \tilde{\mathcal{D}}([0,\infty),\mathbb{R}^+)^{M} \times \mathcal{D}([0,\infty),\mathbb{R}^+)^{d} \times \mathcal{C}^1([0,\infty),\mathbb{R})^m \\  \text{ where (i)}\sum_{\alpha\in\mathscr{R}}  z_{\alpha}(t) \zeta_{\alpha} = x(t) ,\; \text{(ii) for all }t\geq 0, \; \; \frac{du}{dt} = A\big( u(t), x(t) \big) \text{ and }u(0) = \hat{u} %\text{(iii) and }z_{\alpha} \in \hat{\mathcal{H}}
% \text{(iii) If }z_{\alpha}(t-) \neq z_{\alpha}(t) \text{ then necessarily }z_{\alpha}(t) = z_{\alpha}(t-) + jN^{-1} \text{ where }j,N \in \mathbb{Z}^+ 
 \big\rbrace
\end{multline}
and endow $\Upsilon$ with the product topology. Since the values of $x$ and $u$ are effectively determined by $z$, we only need to metrize the convergence of $z$. This is captured by the following lemma.

\begin{lemma}\label{Lemma Topology on Upsilon}
$\Upsilon$ is a closed subset of  $\tilde{\mathcal{D}}([0,\infty),\mathbb{R}^+)^{M} \times \mathcal{D}([0,\infty),\mathbb{R}^+)^{d} \times \mathcal{C}^1([0,\infty),\mathbb{R})^m$. Also, $\Upsilon$ is separable and metrizable. Furthermore for any $t > 0$, there exists $c_t > 0$ such that for all $\delta > 0$,
\begin{multline}
\big\lbrace (z,x,u), (\tilde{z},\tilde{x},\tilde{u}) \in \Upsilon \times \Upsilon : \sup_{\alpha\in\mathscr{R}}d^{\circ}_t(z_{\alpha},\tilde{z}_{\alpha}) \leq \delta \big\rbrace \subseteq  
\big\lbrace (z,x,u), (\tilde{z},\tilde{x},\tilde{u}) \in \Upsilon \times \Upsilon : d^{\circ}_t(z,\tilde{z}) \leq \delta \text{ and }\\ \sup_{0\leq s \leq t}\norm{x(s) - \tilde{x}(s)} \leq c_t \delta \text{ and }\sup_{0\leq s \leq t}\norm{u(s) - \tilde{u}(s)} \leq c_t \delta \big\rbrace 
\end{multline}
\end{lemma}
