\section{Euler-Lagrange Equations}

In this section we determine the structure of the Euler-Lagrange equations that determine the most likely trajectory followed by the system in attaining a specified state. Computing estimates for first-hitting-times is one of the most important applications of Large Deviations Theory. For the application of Large Deviations Theory to first-hitting-time estimates, see for example \cite{E2010,Grafke2017,Newby2024}.   The `fast processes' (i.e. the ODE in $u(t)$) are implemented as a constraint (with Lagrange multipliers). We start by framing the problem in terms of the reaction fluxes; that is, we we wish to determine the most likely trajectory followed by the system in attaining a target reaction flux  $z^* \in (\mathbb{R}^+)^{|\mathscr{R}|}$ at time $T$. We must determine the trajectory 
\[
(z,x,u) \in  \mathcal{C}^1(\mathbb{R})^M \times   \mathcal{C}^1(\mathbb{R})^d \times   \mathcal{C}^1(\mathbb{R})^m
\]
such that $\mathcal{J}_T$ is minimized, where
\begin{align}\label{eq: restated rate function}
\mathcal{J}_T = \sum_{\alpha\in\mathscr{R}} \int_0^T L\big( \dot{z}(s), x(s) , u(s) \big) ds,
\end{align}
where $L: \mathbb{R}^M \times \mathbb{R}^d\times  \mathbb{R}^m  \ \to \mathbb{R}^+$ is the integrand of the rate function in \eqref{eq: J rate function}, i.e.
  \begin{align}
  L\big(q,x , u \big)&=  \sum_{\alpha\in \mathscr{R}} \ell\big( q_{\alpha} / \lambda_{\alpha}(x,u) \big)\lambda_{\alpha}(x,u)  \\
  \ell(a) &= a\log a -a +1.\label{eq: ell definition restated}
  \end{align}
subject to the following constraints and boundary conditions
\begin{align}
\frac{du}{dt} =& A(u,x) \\
x(t) =&  x(0) +  \sum_{\alpha \in \mathscr{R}}z_{\alpha}(t) \xi_{\alpha} . \label{eq: x definition restated}\\
u(0) =& \hat{u}\\
z_{\alpha}(0) =& 0 \\
z_{\alpha}(T) =& z_{\alpha}^*.
\end{align}
We introduce Lagrange Multipliers $\lbrace \eta^i(t) \rbrace_{1\leq i \leq m}$ corresponding to the $m$ constraints
  \begin{align}
  \frac{du^i_t}{dt} = A^i(u_t, x_t).
  \end{align}
  Our task is now to find the critical points of the functional
  \begin{align}
\tilde{\mathcal{J}}_T( z,u,\eta) =& \int_0^T \tilde{L}\big( \dot{z}(s), x(s) , u(s) \big) ds \text{ where } \label{eq: Functional with constraint}\\
\tilde{L}\big( \dot{z}(s), x(s) , u(s) \big) =&  L\big( \dot{z}(s), x(s) , u(s) \big) -\sum_{i=1}^m  \eta^i(s) \big\lbrace \dot{u}^i(s)- A^i(u(s),x(s)) \big\rbrace  \text{ such that }\\
x(t) =&  \hat{x}(0) +  \sum_{\alpha \in \mathscr{R}}z_{\alpha}(t) \xi_{\alpha} . \label{eq: x definition restated 2}
  \end{align}
 We now take the Frechet Derivative of \eqref{eq: Functional with constraint}, i.e. for $w \in \mathcal{C}^1([0,T],\mathbb{R})^M$ and $v \in \mathcal{C}^1([0,T],\mathbb{R})^m$, and $\kappa \in \mathcal{C}^1([0,T],\mathbb{R})^m$, with boundary conditions $w(0) = 0, w(T) = 0, v(0) = 0$, and the boundary conditions for $\kappa$ are not yet clear. Thanks to the constraint in \eqref{eq: x definition restated 2}, we have that
 \begin{align}
 \frac{d}{dz_{\alpha}} = \sum_{i=1}^d \frac{\partial }{\partial x^i} \xi^i_{\alpha}.
 \end{align}
 We therefore find that
 \begin{multline}
D \tilde{\mathcal{J}}_T( z,u,\eta) \cdot (w,v,\kappa) :=  \lim_{\epsilon \to 0^+}\epsilon^{-1} \big\lbrace \tilde{\mathcal{J}}_T( z + \epsilon w,u + \epsilon v,\eta + \epsilon \kappa) -  \tilde{\mathcal{J}}_T( z  ,u  ,\eta  ) \big\rbrace \\
=\sum_{\alpha\in\mathscr{R}} \int_0^T w_{\alpha}(t) \bigg\lbrace \sum_{i=1}^d \bigg(  \frac{\partial L}{\partial x^i}\xi^i_{\alpha}  +  \sum_{k=1}^m \eta^k \frac{\partial A^k}{\partial x^i} \xi^i_{\alpha} \bigg)  - \frac{d}{dt} \frac{\partial L}{\partial \dot{z}_{\alpha}} \bigg\rbrace dt \nonumber \\
+ \sum_{i=1}^m\int_0^T v^i(t) \bigg\lbrace \frac{\partial L}{\partial u^i} + \frac{d\eta^i}{dt} + \sum_{k=1}^m \eta^k \frac{\partial A^k}{\partial u^i}  \bigg\rbrace  
-\kappa^i \bigg\lbrace \frac{du^i}{dt} - A^i(u(t),x(t)) \bigg\rbrace dt  \\
+ \sum_{\alpha\in\mathscr{R}}\bigg\lbrace w_{\alpha}(T)\frac{\partial }{\partial\dot{z}_{\alpha}}L(\dot{z}(T),x(T), u(T)) - w_{\alpha}(0)\frac{\partial }{\partial\dot{z}_{\alpha}}L(\dot{z}(0),x(0), u(0))\bigg\rbrace \\
-  \sum_{i=1}^m \big\lbrace \eta^i(T) v^i(T) - \eta^i(0) v^i(0) \big\rbrace , 
 \end{multline}
 and to obtain the above expression, we have used integration by parts to write
 \begin{multline}
 \sum_{\alpha\in\mathscr{R}} \int_0^T \dot{w}_{\alpha}(t) \frac{\partial L}{\partial\dot{z}_{\alpha}} dt =  \sum_{\alpha\in\mathscr{R}}\bigg\lbrace w_{\alpha}(T)\frac{\partial }{\partial\dot{z}_{\alpha}}L(\dot{z}(T),x(T), u(T)) - w_{\alpha}(0)\frac{\partial }{\partial\dot{z}_{\alpha}}L(\dot{z}(0),x(0), u(0)) \\ -  \int_0^T  w_{\alpha}(t)\frac{d}{dt} \frac{\partial L}{\partial \dot{z}_{\alpha}} dt  \bigg\rbrace
 \end{multline}
 and
 \begin{equation}
   \sum_{i=1}^m \int_0^t \eta^i(t) \dot{v}^i(t) dt =   \sum_{i=1}^m \big\lbrace \eta^i(T) v^i(T) - \eta^i(0) v^i(0)  -\int_0^t \dot{\eta}^i(t) v^i(t) dt  \big\rbrace .
 \end{equation}
 Setting the coefficients of $w_{\alpha}$, $v$ and $\kappa^i$ to zero, we obtain the equations
 \begin{align}
\sum_{i=1}^d  \bigg(\frac{\partial L}{\partial x^i}\xi^i_{\alpha}  +  \sum_{k=1}^m \eta^k \frac{\partial A^k}{\partial x^i} \xi^i_{\alpha} \bigg)  - \frac{d}{dt} \frac{\partial L}{\partial \dot{z}_{\alpha}} &= 0 \\
  \frac{\partial L}{\partial u^i}+ \frac{d\eta^i}{dt}  + \sum_{k=1}^m \eta^k \frac{\partial A^k}{\partial u^i} &= 0 \\
   \frac{du^i}{dt} - A^i(u(s),x(s) )&= 0 \\
  \eta^i(T) &= 0.
 \end{align}
 Noting that $\dot{\ell}(a) = \log a$, we compute that $\frac{\partial L}{\partial \dot{z}_{\alpha}} = \log \frac{\dot{z}_{\alpha}}{\lambda_{\alpha}(x(t),u(t))}$, and therefore
 \begin{align}
 \frac{d}{dt} \frac{\partial L}{\partial \dot{z}_{\alpha}} =& \frac{d}{dt}\left( \log \frac{\dot{z}_{\alpha}}{\lambda_{\alpha}(x(t),u(t))}  \right) \\
 =& \frac{\ddot{z}_{\alpha}}{\dot{z}_{\alpha}} - \frac{1}{\lambda_{\alpha}(x(t),u(t))} \frac{d}{dt}\lambda_{\alpha}(x(t),u(t)).
  \end{align}
  Thus in the case that $\lambda_{\alpha}(x,u) > 0$, the Euler Lagrange equations are such that for $1\leq j \leq m$, $\alpha \in \mathscr{R}$ and $1\leq i \leq d$,
    \begin{align}
 \frac{\ddot{z}_{\alpha}}{\dot{z}_{\alpha}} =& \frac{1}{\lambda_{\alpha}} \frac{d\lambda_{\alpha}}{dt}+\sum_{i=1}^d \xi^i_{\alpha} \frac{\partial L}{\partial x_i} - \sum_{k=1}^d \sum_{j=1}^m \eta^j(t) \frac{\partial A^j}{\partial x^k_t} \xi^k_{\alpha} \label{eq: EL summary 1}\\
  \frac{d\eta^j}{dt} =& - \frac{\partial L}{\partial u^j} - \sum_{k=1}^m \eta^k \frac{\partial A^k}{\partial u^j} \\
  x^i(t) =&  x^i(0) +  \sum_{\alpha \in \mathscr{R}}z_{\alpha}(t) \xi^i_{\alpha} \text{ for all }t\geq 0 . \label{eq: x definition restated again}\\
  \eta^j (T) =& 0 \\
  z_{\alpha}(0) =& 0 \\
  z(T) =& z_*. \label{eq: EL summary 2}
    \end{align}
    For the sake of completeness, we note that
    \begin{align}
    \frac{d\lambda_{\alpha}}{dt} =& \sum_{\beta \in \mathscr{R}} \sum_{i=1}^d \frac{\partial\lambda_{\alpha}}{\partial x^i}\xi^i_{\beta} \dot{z}_{\beta}+\sum_{i=1}^m \frac{\partial\lambda_{\alpha}}{\partial u^i}A^i(u(t),x(t)) \\
     \frac{\partial L}{\partial u^i} =& \sum_{\alpha\in\mathscr{R}}\frac{\partial \lambda_{\alpha}}{\partial u^i} \bigg(1 - \frac{\dot{z}_{\alpha}}{\lambda_{\alpha}} \bigg)
    \end{align}
 It can be seen that this system amounts to an ODE boundary value problem. One way that one may attempt to solve this problem is via the shooting method \cite{E2010}. At time $0$, the unknowns are $\lbrace \dot{z}_{\alpha}(0) \rbrace_{\alpha \in \mathscr{R}}$ and $\lbrace \eta^j(0) \rbrace_{1\leq j \leq m}$. The shooting method requires one to guess values for the unknowns at time $0$, (ii) integrate forward the equations to time $T$, and then (iii) implement the constraints $\lbrace \dot{z}_{\alpha}(T) = \dot{z}_{*,\alpha} \rbrace_{\alpha \in \mathscr{R}}$  and $\lbrace \eta^j(T) = 0 \rbrace_{1\leq j \leq m}$.

   %So it will have to be solved with the shooting method or some other ODE package. We integrate forwards in time, from $0$ to $T$. The following initial conditions are free: $\eta(0), \dot{z}(0)$. We have to solve for these initial conditions, by implementing constraints corresponding to the boundary conditions at time $T$: $\eta(T) = 0$, and $x(T) = x_*$ (some stipulated constants).


 \subsection{Simplified Euler-Lagrange Equations}
Usually, one desires to know the first-hitting-time for the concentrations $\lbrace x^i(T) \rbrace_{1\leq i \leq d}$, rather than the first hitting time for the reaction fluxes. That is, for a fixed $x_* \in \mathbb{R}^d$, one wishes to estimate the probability that $x_T \simeq x_*$, and also determine the optimal (most likely) path followed by the system in attaining this point. For this reason, it can be simpler to eliminate the reaction fluxes and reduce the problem to one purely in terms of the concentrations and the ODE variables $\lbrace u^i(T) \rbrace_{1\leq i \leq m}$. To this end, for any $\dot{x} \in \mathbb{R}^d$, $x \in (\mathbb{R}^+)^d$, and $u \in \mathbb{R}^m$, define the set%  to determine the Large Deviations of a reduced system, which does not contain the reaction intensities $\lbrace \dot{z}_{\alpha} \rbrace$. To this end, define the set
 \begin{align}
 \Xi(\dot{x},x,u) = \big\lbrace \dot{z} \; : \; \dot{x}^p =\sum_{\alpha\in\mathscr{R}} \xi^p_{\alpha} \dot{z}_{\alpha} \big\rbrace  \subset (\mathbb{R}^+)^M
 \end{align}
 Then define the function
 \begin{equation}
\hat{L}\big( \dot{x}(s), x(s) , u(s) \big) = \inf \big\lbrace L( \dot{z}, x(s) , u(s) ) \; : \; \dot{z}  \in  \Xi(\dot{x},x,u) \big\rbrace \label{eq: contracted rate function}
 \end{equation}
 In the case that $ \Xi(\dot{x},x,u)  = \emptyset$, define $\hat{L}\big( \dot{x}(s), x(s) , u(s) \big) = \infty$. One can thus define the contracted rate function
\begin{align}
\tilde{\mathcal{J}}_T:& \mathcal{C}_{ac}([0,T],(\mathbb{R}^+)^d \big) \times \mathcal{C}_{ac}([0,T],\mathbb{R}^m \big) \to \mathbb{R} \\
\tilde{\mathcal{J}}_T(x,u) &=  \int_0^T \tilde{L}\big( \dot{x}(s), x(s) , u(s) \big) ds,
\end{align}
and it is immediate from the Contraction Principle \cite{Dembo1998} that $\tilde{\mathcal{J}}_T$ governs the Large Deviations of $(x,u)$. The following convexity property makes it easier to compute optimal trajectories.
 \begin{lemma}
 $\tilde{L}$ is convex in its first argument.
 \end{lemma}
 \begin{proof}
This is because $\Xi$ is linear in $\dot{x}$,  and $L$ is convex in its first argument.
 \end{proof}
Next, we outline the Euler-Lagrange equations for $\tilde{\mathcal{J}}_T$. The derivation parallels that of the previous section. Our task is to find the critical points of the functional
  \begin{align}
\grave{\mathcal{J}}_T( x,u,\eta) =& \int_0^T \grave{L}\big( \dot{x}(s), x(s) , u(s) \big) ds \text{ where } \label{eq: Functional with constraint 2}\\
\grave{L}\big( \dot{x}(s), x(s) , u(s) , \eta(s) \big) =&  \tilde{L}\big( \dot{x}(s), x(s) , u(s) \big) -\sum_{i=1}^m  \eta^i(s) \big\lbrace \dot{u}^i(s)- A^i(u(s),x(s)) \big\rbrace ,
  \end{align}
  and $\eta^i \in \mathcal{C}^1([0,T],\mathbb{R})$ is the Lagrange Multiplier.

 We now take the Frechet Derivative of \eqref{eq: Functional with constraint 2}, i.e. for $w \in \mathcal{C}^1([0,T],\mathbb{R})^M$ and $v \in \mathcal{C}^1([0,T],\mathbb{R})^m$, and $\kappa \in \mathcal{C}^1([0,T],\mathbb{R})^m$, with boundary conditions $w(0) = 0, w(T) = 0, v(0) = 0$, and the boundary conditions for $\kappa$ are not yet clear,
 \begin{multline}
D \grave{\mathcal{J}}_T( x,u,\eta) \cdot (w,v,\kappa) :=  \lim_{\epsilon \to 0^+}\epsilon^{-1} \big\lbrace \grave{\mathcal{J}}_T( x + \epsilon w,u + \epsilon v,\eta + \epsilon \kappa) -  \tilde{\mathcal{J}}_T( x  ,u  ,\eta  ) \big\rbrace \\
= \int_0^T \sum_{i=1}^d  w_{i}(t) \bigg\lbrace \bigg(  \frac{\partial \hat{L}}{\partial x^i} +\sum_{k=1}^m  \eta^k  \frac{\partial A^k}{\partial x^i} \bigg)  - \frac{d}{dt} \frac{\partial L}{\partial \dot{x}^i} \bigg\rbrace dt \nonumber \\
+ \sum_{i=1}^m\int_0^T v^i(t) \bigg\lbrace \frac{\partial \hat{L}}{\partial u^i} + \frac{d\eta^i}{dt} + \sum_{k=1}^m \eta^k \frac{\partial A^k}{\partial u^i}  \bigg\rbrace  
-\kappa^i \bigg\lbrace \frac{du^i}{dt} - A^i(u(t),x(t)) \bigg\rbrace dt  \\
-  \sum_{i=1}^m \big\lbrace \eta^i(T) v^i(T) - \eta^i(0) v^i(0) \big\rbrace
 \end{multline}
The Euler-Lagrange equations are thus, for $1\leq i \leq d$ and $1\leq j \leq m$,
 \begin{align}
\frac{\partial \hat{L}}{\partial x^i} + \sum_{k=1}^m \eta^k  \frac{\partial A^k}{\partial x^i}  - \frac{d}{dt} \frac{\partial \hat{L}}{\partial \dot{x}^i} &= 0 \label{eq: reduced EL 1} \\
  \frac{\partial \hat{L}}{\partial u^j}+ \frac{d\eta^j}{dt}  + \sum_{k=1}^m \eta^k \frac{\partial A^k}{\partial u^j} &= 0 \\
   \frac{du^i}{dt} - A^i(u(s),x(s) )&= 0 \\
  \eta^i(T) &= 0 .\label{eq: reduced EL 4}
 \end{align}
For the sake of completeness, we note that the derivative assumes the form
\begin{align}
\frac{d}{dt} \frac{\partial \hat{L}}{\partial \dot{x}^i} =\sum_{j=1}^d \bigg\lbrace \frac{\partial^2 \tilde{L}}{\partial \dot{x}^i \partial \dot{x}^j} \ddot{x}^j +  \frac{\partial^2 \hat{L}}{\partial \dot{x}^i \partial x^j} \dot{x}^j \bigg\rbrace+\sum_{j=1}^m  \frac{\partial^2 \hat{L}}{\partial \dot{x}^i \partial u^j}  \frac{du^j}{dt}
\end{align}




\section{Application to Calcium Signalling}

We apply this theory to determine estimates for the typical time it takes for cells with stochastically opening and closing calcium channels to change from most of the channels being closed to most being open \cite{Dupont2016}. There are thus two components to the model: the opening and closing channels, and the calcium concentration (that evolves deterministically between the opening and closing of the channels). The model is simplified to be such that the calcium concentration throughout the cell is spatially homogeneous. 

To begin with, we must outline a simple microscopic model of stochastic calcium effects. Following for instance \cite{Coombes2003,Keener2006,Ramlow2023,Falcke2023b}, we employ a hybrid model: with the calcium diffusion modeled deterministically, the IP3 concentration constant throughout the cell, and the channel opening and closing modeled stochastically. 

%The IP3 channels occur in clusters. It is assumed that there is no spatial resolution between channels in the same cluster: in our model channel clusters occupy nodes on a lattice \cite{Falcke2000,Coombes2003,Keener2006}. The number of channels per cluster is specified to be $M$: this is typically between $10-100$ \cite{Sun1998,Meinhold2002}. It has been argued by Rudiger \cite{Rudiger2010} that it is inaccurate to not distinguish the locations of calcium channels in a cluster: he argues that if the calcium channels within a cluster are too tightly grouped, then the opening of one calcium channel would have too great an inhibiting effect on other channels. In future work we will determine the probability of a puff in this situation.

Our basic aim is to determine the probability of calcium puffs and waves by studying a similar stochastic model to  \cite{Coombes2003,Keener2006,Ramlow2023,Falcke2023b}. These papers performed detailed numerical simulations, and analytically estimated the probabilities. To calculate the probability of a calcium puff in a cluster, the calcium and IP3 concentration throughout the cluster is assumed to be homogeneous. However there is a feedback effect of the opening / closing of the channels: when these bind or unbind the calcium / IP3, they alter the local concentration. Thus the opening and closing of channels within a cluster is not independent because the channels communicate with each other via the calcium / IP3 concentrations.


\subsection{Piecewise-Deterministic-Markov-Process Model of Calcium Dynamics}

We suppose that there are $N$ channels distributed on the cell membrane. It is assumed that spatial effects are negligible, so that the calcium concentrations can be modelled as approximately spatially homogeneous using ODEs. Let $u_1$ be the calcium concentration in the cellular cytosol, and $u_2$ be the calcium concentration in the endoplasmic reticulum.

We take the number of stochastic variables corresponding to each channel to be $1$. That is, $Z^i_t = 1$ if the channel is open, and $Z^i_t = 0$ if the channel is closed.  Employing a standard model \cite{Dupont2016} for the calcium dynamics, we obtain that
%In this case, the ODE dynamics in \eqref{eq: ODE 1}-\eqref{eq: ODE 4} is virtually the same, except that now we have
\begin{align}
\frac{du_1}{dt} =& k_f x(t) (u_2 - u_1) - J_{serca}(u) +  J_{leak} := A^1(u,x) \label{eq: ODE 1 restated}\\
\frac{du_2}{dt} =& \gamma J_{serca}(u_1) - \gamma  k_f x(t) (u_2 - u_1) - \gamma J_{leak} := A^2(u,x), \label{eq: ODE 1 restated} \\
J_{serca}(u_1) =& \frac{V_s (u_1)^2}{K_s^2 + (u_1)^2} \\
J_{leak}(u) =& k_{leak}(u_2 - u_1)\label{eq: ODE 4}
\end{align}
One may observe that 
\begin{align}
\frac{d}{dt}\big( \gamma u_1 + u_2 \big) = 0,
\end{align}
which means that we can eliminate $u_2$ from the dynamics, and write $u := u_1(t)$, and $A(t) := A^1(u,x)$.
Now 
\begin{align}
x(t) = \frac{1}{N}\sum_{j=1}^N Z^j_t.
\end{align}
The Markovian switching of the channel is given by
\begin{itemize}
\item Reaction 1: $1$ to $0$ with intensity $\lambda_1(u,x) = \alpha_{-1}x$ (a constant). The stoichiometric constant is $\zeta_1 = -1$.
\item Reaction 2: $0$ to $1$ with intensity $\lambda_2(u,x) = \alpha_1 u_1 (1-x)$. The stoichiometric constant is $\zeta_2 = 1$.
\end{itemize}
Let $z_1(t)$ count the number of times reaction $1$ happens, and $z_2(t)$ count the number of times that reaction $2$ happens. Then it must be that
\begin{align}
x(t) = x(0) + z_2(t) - z_1(t).
\end{align}

\subsubsection{Large $N$ Limiting Dynamics.}

As $N\to\infty$ it is classical that the concentration of open channels converges to the following ODE \cite{Kurtz1971}.
\begin{align}
\frac{dz}{dt} =& \lambda_2(u,x) - \lambda_1(u,x). \label{eq: large N channel proportion} \\
\frac{du_1}{dt} =& k_f x(t) (u_2 - u_1) - J_{serca}(u) +  J_{leak} := A^1(u,x) \label{eq: ODE 1 restated again}\\
\frac{du_2}{dt} =& \gamma J_{serca}(u_1) - \gamma  k_f x(t) (u_2 - u_1) - \gamma J_{leak} := A^2(u,x), \label{eq: ODE 1 restated again} 
\end{align}
It turns out that there exists a unique fixed point of \eqref{eq: large N channel proportion} - \eqref{eq: ODE 1 restated again}. This point is written as $(z^* , u_1^* , u_2^*)$.
