\subsubsection{Euler-Lagrange Equations}

It seems easiest to work with the contracted rate function in \eqref{eq: contracted rate function}. We first find a much simpler form for the contracted rate function.

\begin{lemma}
\begin{align} \label{eq: tilde L first}
 \hat{L}\big( \dot{x}, x , u \big) = \ell\bigg( \frac{\dot{z}_1}{\lambda_1(x,u)} \bigg)\lambda_1(x,u) +  \ell\bigg( \frac{\dot{x} + \dot{z}_1}{\lambda_2(x,u)} \bigg)\lambda_2(x,u) 
\end{align}
where $\dot{z}_1$ is such that
\begin{align} \label{eq: quadratic for dot z 1}
\dot{z}_1 \big( \dot{x} + \dot{z}_1 \big) = \lambda_1(x,u) \lambda_2(x,u).
\end{align}
One must make sure to choose the root of the above quadratic that is such that $\dot{z}_1 \geq 0$. %$\dot{z}_1$ such that

\end{lemma}
\begin{proof}
It must be that 
\[
\dot{x} = \dot{z}_2 - \dot{z}_1.
\]
Thus, upon substitution, the Lagrangian assumes the form in \eqref{eq: tilde L first}. We must choose $\dot{z}_1$ to minimize \eqref{eq: tilde L first}, subject to the constraint $0\leq \dot{z}_1 \leq \dot{x}$. Differentiating \eqref{eq: tilde L first} with respect to $\dot{z}_1$, and setting the derivative to zero, we obtain that
\begin{align}
 \log\bigg( \frac{\dot{z}_1}{\lambda_1(x,u)} \bigg)  +  \log\bigg( \frac{  \dot{z}_1 + \dot{x}}{\lambda_2(x,u)} \bigg) = 0.
\end{align}
Exponentiating both sides, we obtain \eqref{eq: quadratic for dot z 1}.
\end{proof}
