\subsection{Discussion}
We have demonstrated that Large Deviation Theory can be used to compute the most likely trajectory followed by $N$ stochastic channels / diffusing calcium in making the spark to wave transition \cite{Dupont2016}. This model is relatively simple, particularly insofar as the calcium concentration is spatially homogeneous. In a subsequent work, we will employ a spatially-distributed model of the calcium to compute the optimal trajectories.

\section{Proofs}
To prove Theorem \ref{Theorem Main LDP}, we apply the Contraction Principle \cite{Dembo1998} to the Large Deviation Principle for the independent system.
In other words, we are going to perform a change of variable, which will transfer known results for the Large Deviations of independent Poisson Processes \cite[Chapter 6]{Weiss1995}. We first recount the Large Deviations for independent Poisson Processes (recalling the definition of $\lbrace y_{\alpha}(t) \rbrace_{\alpha\in\mathscr{R}}$ in \eqref{eq: Z definition next}).

%We assume throughout this section that there exists a constant $\mathfrak{C} > 0$ such that
%\begin{align}
%\sup_{\alpha}\lambda_{\alpha}(x,u) \leq \mathfrak{C}. \label{eq: lambda upperbound}
%\end{align}

\begin{theorem}\label{Theorem Sanov}
The sequence of probability laws of $ (y_{\alpha})_{\alpha\in \mathscr{R}} \in \tilde{\mathcal{D}}([0,\infty),\mathbb{R}^+)^M$ satisfy a Large Deviation Principle with good rate function.
 %Write $y_{\alpha\beta}(t) := N^{-1}Y_{\alpha\beta}(Nt)$, and $y = (y_{\alpha\beta})_{\alpha,\beta\in\Gamma} \in \mathcal{D}([0,\infty),\mathbb{R})^{\Gamma\times\Gamma}$. The sequence of probability laws of $\tilde{\mu}^N$ satisfy a Large Deviation Principle on $\mathcal{P}\big( \mathcal{D}([0,\infty),\mathbb{R})^{\Gamma \times \Gamma} \big)$.
 That is, for $\mathcal{O},\mathcal{A} \subset  \tilde{\mathcal{D}}([0,\infty),\mathbb{R}^+)^M$, with $\mathcal{O}$ open and $\mathcal{A}$ closed,
\begin{align}
\lsup{N}N^{-1}\log \mathbb{P}\big(  y \in \mathcal{A} \big) &\leq - \inf_{\alpha \in \mathcal{A}}\mathcal{I}(\alpha) \\
\linf{N}N^{-1}\log \mathbb{P}\big( y \in \mathcal{O} \big) &\geq - \inf_{\alpha \in \mathcal{O}}\mathcal{I}(\alpha) ,
\end{align}
and the rate function is
\begin{align}
\mathcal{I}(y) &= \left\lbrace \begin{array}{c}
\infty \text{ in the case that }y_{\alpha} \text{ is not absolutely continuous for some }\alpha \in \mathscr{R} \\
\sum_{\alpha \in \mathscr{R}} \int_0^\infty \ell\big( \dot{y}_{\alpha}(r) \big)dr \text{ otherwise,  }
\end{array}\right.   \\
\ell(r) &= r\log r -r +1.
\end{align}
 Furthermore the level sets of $\mathcal{I}$ are compact.
\end{theorem}
\begin{proof}

The Large Deviations Principle for arbitrarily long finite time intervals is proved in \cite[Chapter 5]{Weiss1995}, with corresponding rate function
\begin{equation}
\mathcal{I}(y) = \sum_{\alpha \in \mathscr{R}} \int_0^{\infty} \ell\big( \dot{y}_{\alpha}(r) \big)dr.
\end{equation}
%This Large Deviations Principle extends to infinite time thanks to the Dawson-Gartner projective limits theorem \cite{Dembo1998}, and using the fact that the infinite-time topology is generated by the topologies over finite time intervals.
\end{proof}


The first result that we must prove is that the Large Deviations Principle must hold for sets with reaction rates bounded away from zero.
\begin{lemma}\label{Lemma Main LDP}
Suppose that $\mathcal{O},\mathcal{A} \subseteq \Upsilon$, with $\mathcal{O}$ open and $\mathcal{A}$ closed, are such that for any $T > 0$,
\begin{align}
\inf_{ (z,x,u) \in \mathcal{A} \cup \mathcal{O}} \inf_{\alpha\in\mathscr{R}} \inf_{s\in [0,T]} \lambda_\alpha(x(s),u(s)) > 0. \label{eq: set infimum lambda}
\end{align}
Then the sequence of probability laws of $\big( z,x,u \big)$ satisfy a Large Deviation Principle on the space $\Upsilon$, i.e.
\begin{align}
\lsup{N}N^{-1}\log \mathbb{P}\big( (z,x,u) \in \mathcal{A} \big) &\leq - \inf_{\beta \in \mathcal{A}}\mathcal{J}(\beta) \\
\linf{N}N^{-1}\log \mathbb{P}\big( (z,x,u) \in \mathcal{O} \big) &\geq - \inf_{\beta\in \mathcal{O}}\mathcal{J}(\beta).
\end{align}
$\mathcal{J}$ is lower-semi-continuous and the level sets of $\mathcal{J}$ are compact.
\end{lemma}
\begin{proof}
We are going to prove the Large Deviation Principle using a contraction principle. To this end, define a mapping $\Psi: \Upsilon \to \tilde{\mathcal{D}}([0,\infty),\mathbb{R}^+)^M$ as follows. For any $(z,x,u) \in \Upsilon$, define 
\begin{align}
\Lambda_{\alpha}(t) = \int_0^t \lambda_{\alpha}(x(s),u(s)) ds.
\end{align}
Let $\Lambda^{-1}_{\alpha} \in  \tilde{\mathcal{D}}([0,\infty),\mathbb{R}^+$ be such that
\begin{align}
\Lambda^{-1}_{\alpha}(t) = \inf\big\lbrace s\geq 0 \; : \Lambda_{\alpha}(s) = t \big\rbrace . 
\end{align}
Note that, since $\inf_{s\in [0,t]}\lambda_{\alpha}(x(s),u(s)) > 0$, it must be that $\Lambda^{-1}_{\alpha}$ is the function inverse of $\Lambda_{\alpha}$. Write
\begin{align}
\tau_{\alpha} = \lim_{t\to\infty} \Lambda_{\alpha}(t) ,
\end{align}
and note that $\tau_{\alpha}$ could be $\infty$.
%Because $\Lambda_{\apha}$ is non-decreasing and continuous, $\Lambda^{-1}_{\alpha}$ is well-defined upto some time $\tau_{\alpha}$ (which could be infinite). 
We define $\Psi(z,x,u) = \big( w_{\alpha} \big)_{\alpha\in \mathscr{R}}$, where for any $t < \tau_{\alpha}$,
\begin{align}
w_{\alpha}(t) = z_{\alpha}\big( \Lambda^{-1}_{\alpha}(t) \big).
\end{align}
In the case that $\tau_{\alpha} < \infty$, for all $t\geq \tau_{\alpha}$, we define $w_{\alpha}(t) = \lim_{s\to \tau_{\alpha}^-}w_{\alpha}(s)$.
One observes that over sets of the form \eqref{eq: set infimum lambda}, $\Psi$ is continuous.  Furthermore, $w_{\alpha}(t) = y_{\alpha}(t)$. 
We wish to apply the Inverse Contraction Principle \cite{Dembo1998}, (noting also Lemmas \ref{Theorem Sanov} and \ref{Lemma Exponential Tightness}). In order that this theorem applies, we must also prove that $\Psi$ is one-to-one. This is proved in Lemma \ref{One to One Lemma}.

%Let $\Gamma_{\alpha}: [0,\infty) \to [0,\infty)$ be such that
%\begin{align}
%2d^{\circ}_t(y,\tilde{y}) \leq \sup_{s\in [0,t]} \big| y_{\alpha}(s) - \tilde{y}_{\alpha}(\Gamma_{\alpha}(s)) \big|
%\end{align}

\end{proof}
\begin{lemma} \label{One to One Lemma}
Over any set $\mathcal{A}_{\epsilon}$ of the form, for $\epsilon > 0$,
\begin{align}
\mathcal{A}_\epsilon = \inf_{ (z,x,u) \in \Upsilon} \inf_{\alpha\in\mathscr{R}} \inf_{s\in [0,T]} \lambda_\alpha(x(s),u(s)) \geq \epsilon. \label{eq: set infimum lambda restated}
\end{align}
 $\Psi$ is one-to-one.
\end{lemma}
\begin{proof}
Let $(z,x,u) , (\hat{z},\hat{x},\hat{u}) \in \Upsilon$. Write
\begin{align}
\Lambda_{\alpha}(t) &= \int_0^t \lambda_{\alpha}(x(s),u(s)) ds \\
\hat{\Lambda}_{\alpha}(t) &= \int_0^t \lambda_{\alpha}( \hat{x}(s), \hat{u}(s)) ds \\
w_{\alpha}(t) &= z_{\alpha}\big( \Lambda^{-1}_{\alpha}(t) \big) \\
\hat{w}_{\alpha}(t) &= \hat{z}_{\alpha}\big( \hat{\Lambda}^{-1}_{\alpha}(t) \big).
\end{align}
It is noted in Lemma that there is a constant $C_t > 0$ such that
\begin{align}
\sup_{\alpha\in\mathscr{R}} \Lambda_{\alpha}(t)\leq C_t
\end{align}
We are going to demonstrate that for any $t \geq 0$, there exists a constant $c_{\epsilon,t}$ such that for all $s\leq t$,
\begin{align}
\tilde{d}^{\circ}_s( z_{\alpha}, \hat{z}_{\alpha}) \leq  \tilde{d}^{\circ}_{C_s}( w_{\alpha}, \hat{w}_{\alpha}) + c_{\epsilon,t} \tilde{d}^{\circ}_s( z_{\alpha}, \hat{z}_{\alpha}). \label{eq: to show gronwall one to one}
\end{align}
An application of Gronwall's Inequality to \eqref{eq: to show gronwall one to one} implies that if $w_{\alpha} = \hat{w}_{\alpha}$ for all $\alpha \in \mathscr{R}$, then necessarily  $z_{\alpha} = \hat{z}_{\alpha}$. This implies the Lemma.

With an aim of proving \eqref{eq: to show gronwall one to one}, it follows from Calculus that
\begin{align}
\Lambda^{-1}_{\alpha}(t) &= \int_0^t \lambda^{-1}_{\alpha}(x(s),u(s)) ds \\
\hat{\Lambda}^{-1}_{\alpha}(t) &= \int_0^t \lambda^{-1}_{\alpha}( \hat{x}(s), \hat{u}(s)) ds .
\end{align}
Our assumptions on the set $\mathcal{A}_{\epsilon}$ imply that
\begin{align}
\Lambda^{-1}_{\alpha}(t) &\leq t \epsilon^{-1} \label{eq: reaction rate bound 1} \\
\hat{\Lambda}^{-1}_{\alpha}(t) &\leq t \epsilon^{-1} .\label{eq: reaction rate bound 2}
\end{align}
Define
\begin{align}
\tilde{z}_{\alpha}(t) = w_{\alpha} \big( \hat{\Lambda}(t)  \big) .
\end{align}
The triangle inequality implies that
\begin{align}
\tilde{d}^{\circ}_{t}(z_\alpha , \hat{z}_{\alpha}) \leq \tilde{d}^{\circ}_{t}(z_\alpha , \tilde{z}_{\alpha}) + \tilde{d}^{\circ}_{t}(\tilde{z}_\alpha , \hat{z}_{\alpha}).
\end{align}
The definition of the Skorohod metric implies that
\begin{align}
 \tilde{d}^{\circ}_{t}(z_\alpha , \tilde{z}_{\alpha}) \leq \sup_{s\leq t} \bigg| \int_0^s  \lambda_{\alpha}(x(r),u(r)) /  \lambda_{\alpha}(\hat{x}(r),\hat{u}(r)) dr - s \bigg|. \label{eq: skorohod 0}
 \end{align}
 Our assumption that the reaction rates and functions are Lipschitz, together with Lemma \ref{Lemma Topology on Upsilon} implies that there is a constant $\bar{C}_{\epsilon,t} > 0$ such that 
\begin{align}
\sup_{s\in [0,t]} \sup_{\alpha\in \mathscr{R}} \big| \lambda_{\alpha}(x(s),u(s))- \lambda_{\alpha}(\hat{x}(s),\hat{u}(s)) \big| \leq &\bar{C}_{\epsilon,t} \sup_{s\in [0,t]} \sup_{\alpha\in \mathscr{R}} \big| z_{\alpha}(s) -\hat{z}_{\alpha}(s) \big| \\ 
\leq &  \bar{C}_{\epsilon,t}  \sup_{\alpha\in \mathscr{R}}  \tilde{d}^{\circ}_t(z_{\alpha} , \hat{z}_{\alpha}). \label{eq: lips 1}
\end{align}
Since the reaction rates are (by assumption in the statement of the Lemma), bounded from below, we thus obtain that there is a constant $\grave{C}_{\epsilon,t}$ such that for all $s \leq \bar{t}$,
\begin{align}
\sup_{\alpha\in \mathscr{R}} \tilde{d}^{\circ}_{s}(z_\alpha , \tilde{z}_{\alpha}) \leq \grave{C}_{\epsilon,\bar{t}}  \sup_{\alpha\in \mathscr{R}}  \tilde{d}^{\circ}_s(z_{\alpha} , \hat{z}_{\alpha}).
 \end{align}
 The definition of the Skorohod Metric, together with the bounds in \eqref{eq: reaction rate bound 1} also implies that 
 \begin{align}
  \tilde{d}^{\circ}_{t}(\tilde{z}_\alpha , \hat{z}_{\alpha}) \leq  \tilde{d}^{\circ}_{C_t}(w_\alpha , \hat{w}_{\alpha}).
 \end{align}
 We have thus proved \eqref{eq: to show gronwall one to one}.
\end{proof}

The following exponential tightness result is a standard requirement for Large Deviation Principles.
\begin{lemma} \label{Lemma Exponential Tightness}
For any $L > 0$, there exists a compact set $\mathcal{K}_{L} \subset \Upsilon$ such that
\begin{align}
\lsup{N} N^{-1}\log \mathbb{P}\big( (z,x,u) \notin \mathcal{K}_L \big) \leq - L.
\end{align}
\end{lemma}
\begin{proof}
We can equivalently formulate the system in terms of an empirical measure, and the exponential tightness is an immediate consequence. In more detail, write 
\begin{align}
\hat{\mu}^N = N^{-1}\sum_{j\in I_N} \delta_{w^j} \in \mathcal{P}\big( \mathcal{D}\big( [0,T], \mathbb{Z}^+ \big)^{|\mathscr{R}|} \big). 
\end{align}
Here $w^j := \big(w^{j}_{\alpha} \big)_{ \alpha \in \mathscr{R}} \subset \mathcal{D}\big( [0,T], \mathbb{Z}^+ \big)^{|\mathscr{R}|}$ are inhomogeneous counting processes, i.e. they are such that
\begin{align}
\mathbb{P}\big( w^{j}_{\alpha}(t+\Delta) =w^{j}_{\alpha}(t) +1 \; | \; \mathcal{F}_t \big) &\simeq \Delta \lambda_{\alpha}(x(t),u(t) )+ O(\Delta^2) \\
\mathbb{P}\big( w^{j}_{\alpha}(t+\Delta) = w^{j}_{\alpha}(t)   \; | \; \mathcal{F}_t \big) &\simeq 1 - \Delta \lambda_{\alpha}(x(t),u(t) )+ O(\Delta^2) .
\end{align}
Here
\begin{align}
x(t) =& x(0) + N^{-1} \sum_{j\in I_N} \sum_{\alpha\in\mathscr{R}}\xi_{\alpha}  w^j_{\alpha}(t) \\
\frac{du}{dt} =& A(u(t),x(t))
\end{align}
We then find that, substituting $z_{\alpha}(t) = N^{-1}\sum_{j=1}^N w^j_{\alpha}(t)$, the above system has the same probability law as the original system. Write $\mathcal{D}_*\big( [0,T], \mathbb{Z}^+ \big)^{|\mathscr{R}|} \big) \subseteq \mathcal{D}\big( [0,T], \mathbb{Z}^+ \big)^{|\mathscr{R}|}$ to consist of all processes that are (i) equal to $0$ at time $0$, (ii) non-decreasing.

More precisely, we see that there exists a continuous mapping $\Psi: \mathcal{P}\big( \mathcal{D}_*\big( [0,T], \mathbb{Z}^+ \big)^{|\mathscr{R}|} \big)$ such that $(z,x,u) = \Psi\big(\hat{\mu}^N\big)$, with unit probability. For a positive number $L>0$, we are going to define a compact set $\mathcal{K}_L \subseteq  \mathcal{P}\big( \mathcal{D}_*\big( [0,T], \mathbb{Z}^+ \big)^{|\mathscr{R}|} \big)$ such that
\begin{align}
\lsup{N} N^{-1}\log \mathbb{P}\big( \hat{\mu}^N \notin \mathcal{K}_L \big) \leq - L.
\end{align}
This suffices for the lemma because the continuity of $\Psi$ then implies that $\Psi(\mathcal{K}_L)$ is compact.

For a positive integer $p\geq 1$, write $\mathcal{U}_{p,T} \subseteq \mathcal{D}_*\big( [0,T], \mathbb{Z}^+ \big)^{|\mathscr{R}|}$ to consist of all paths that are less than or equal to $p$ at time $T$. Its easy to check that $\mathcal{U}_p$ is compact with respect to the Skorohod Topology (there are at most $p$ `spike times', and these spike times must be in the compact time interval $[0,T]$). Write $Y^{p,j}_\alpha$ to be independent counting processes of unit intensity. Thus the time-rescaled representation of Poisson Processes \cite{Anderson2015} means that we can write
\begin{align}
w^j_{\alpha}(t) = Y^j_\alpha\bigg( \int_0^t \lambda_{\alpha}(x(s),u(s)) ds \bigg)
\end{align}
For another number $b_p > 0$, we find that
\begin{align}
\mathbb{P}\big( \hat{\mu}^N(\mathbf{w})(\mathcal{U}_{p,T}) < 1 - b_p \big) \leq \mathbb{P}\big( \hat{\mu}^N(\mathbf{Y}) \big(\mathcal{U}_{p,KT}\big) < 1 - b_p \big) .
\end{align}
since $\lambda \leq K$ uniformly. Thanks to Chernoff's Inequality, for a constant $c > 0$, 
\begin{align}
 \mathbb{P}\big( \hat{\mu}^N(\mathbf{Y}) \big(\mathcal{U}_{p,KT}\big) < 1 - b_p \big) \leq & \mathbb{P}\bigg( \sup_{\alpha \in \mathscr{R}} N^{-1}\sum_{j=1}^N \chi\big\lbrace w^j_{\alpha}(KT) > p \big\rbrace \geq b_p \bigg) \\
\leq & \big| \mathscr{R} \big| \mathbb{E}\bigg[ \exp\bigg( c \sum_{j=1}^N\chi\big\lbrace w^j_{\alpha}(KT) > p \big\rbrace  - Nc b_p \bigg) \bigg] \\
=& \big|\mathscr{R}\big| \bigg\lbrace1 + \mathbb{P}\big(w^j_{\alpha}(KT) > p \big)  \big(\exp(c) - 1 \big) \bigg\rbrace^N \exp\big( - Nc b_p \big)  
\end{align}
Through taking $p$ large enough, and $1\ll c \ll  -\log\mathbb{P}\big(w^j_{\alpha}(KT) > p \big) $, we find that
\begin{align}
  \mathbb{P}\big( \hat{\mu}^N(\mathbf{w})(\mathcal{U}_{p,T}) < 1 - b_p \big) \leq \exp\big( -p N \big).
\end{align}
Now define $\mathcal{K}_L$ to consist of all measures $\mu$ such that for all $p \geq p_L$ (for an integer $p_L$ to be specified below),
\begin{align}
\mu( \mathcal{U}_{p,KT}) \geq b_p.
\end{align}
We thus find through a union of events bound that
\begin{align}
\mathbb{P}\bigg( \hat{\mu}^N \notin \mathcal{K}_L \bigg) \leq  &\sum_{p=p_L}^{\infty}\mathbb{P}\bigg(  \hat{\mu}^N(\mathbf{Y}) \big(\mathcal{U}_{p,KT}\big) < 1 - b_p  \bigg)  \\
\leq & \sum_{p=p_L}^{\infty}\exp\big(-pN \big).
\end{align}
Thus for large enough $p_L$, it must be that for all $N\geq 1$,
\begin{align}
N^{-1} \log \mathbb{P}\bigg( \hat{\mu}^N \notin \mathcal{K}_L \bigg) \leq - L.
\end{align}

\end{proof}
We finally note the proof of Lemma \ref{Lemma Topology on Upsilon}.
\begin{proof}
It is clear from the definition of $x$ that there is a universal constant such that
\begin{equation}
\norm{x(s) - \tilde{x}(s)} \leq C\sup_{\alpha\in\mathscr{R}}| z_{\alpha}(s) - \tilde{z}_{\alpha}(s) |.
\end{equation}
It is demonstrated in Billingsley \cite{Billingsley1999} that convergence in the Skorohod metric implies convergence in the supremum norm, i.e as $d^{\circ}_\infty(z,\tilde{z}) \to 0$, it must be that
\begin{equation}
\sup_{\alpha\in\mathscr{R}}\sup_{0\leq s \leq t}\big| z_{\alpha}(s) - \tilde{z}_{\alpha}(s) \big| \to 0.
\end{equation} 
The Lemma now follows from a standard application of Gronwall's Inequality.
\end{proof}

