\section{Proof of Lemma \ref{lem:bae}}
\label{sec:proof of main}


For any policy $\pi$, we have the following bounds on its utilitarian regret $\mathfrak{R}^{\pi}_{\thetabf, T}$, defined in \eqref{eq:regret}:
\[
\Delta_{\min}(\thetabf)\cdot \Prob^{\pi}_{\thetabf,T}\left(\hat{I}_T \neq I^*\right)
\leq \mathfrak{R}^{\pi}_{\thetabf, T} \leq 
\Delta_{\max}(\thetabf)\cdot \Prob^{\pi}_{\thetabf,T}\left(\hat{I}_T \neq I^*\right),
\]
where $\Delta_{\min} = \theta_{I^*} - \max_{i\neq I^*}\theta_i$ and $\Delta_{\max} = \theta_{I^*} - \min_{i\neq I^*}\theta_i$.
We note that $\Delta_{\min}(\thetabf) > 0$ by uniqueness of the best arm (Assumption \ref{assu:gauss}), and that the optimality gaps become irrelevant in the asymptotic regime. Hence, to prove Lemma \ref{lem:bae}, it suffices to establish the following result.

\begin{lemma}
\label{lem:bae prob of error}
Under Assumption \ref{assu:gauss} and
for batched arm elimination with batch weights $(\beta_K, \beta_{K-1}, \ldots, \beta_2)\in\Sigma_{K-1}$ (Algorithm \ref{alg:bae}), 
\[
\lim_{T\rightarrow \infty }  \,\, -\frac{1}{T} \ln\left(\Prob^{\tt{BAE}}_{\thetabf,T}\left(\hat{I}_T \neq I^*\right)\right)  \geq \min_{n \in  \{K,K-1,\ldots,2\}}\,\, w_n\Gamma_{\thetabf,n},
%\textnormal{SR+}
\]
where $w_n$ and $\Gamma_{\thetabf,n}$ are defined in \eqref{eq:proportion} and \eqref{eq:gamma}, respectively.
\end{lemma}





By the construction of BAE designs (Algorithm \ref{alg:bae}), we have
\begin{align*}
\Prob^{\tt{BAE}}_{\thetabf,T}\left(\hat{I}_T\neq I^*\right) 
=  \sum_{n\in\{K,\ldots,2\}}\Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*\right),
\end{align*}
where $\ell_n$ is the arm eliminated at the end of the batch starting with $n$ arms.
Hence,
\[
\Prob^{\tt{BAE}}_{\thetabf,T}\left(\hat{I}_T\neq I^*\right) 
\leq (K-1)\max_{n\in\{K,\ldots,2\}}\Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*\right),
\]
and thus
\begin{align}
\liminf_{T\rightarrow \infty }  \,\, -\frac{1}{T} \ln\left(\Prob^{\tt{BAE}}_{\thetabf,T}\left(\hat{I}_T \neq I^*\right)\right) 
&\geq \lim_{T\rightarrow \infty }  \,\, -\frac{1}{T}\ln\left(\max_{n\in\{K,\ldots,2\}}\Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*\right)\right) \nonumber\\
&= \liminf_{T\rightarrow \infty }  \,\, \min_{n\in\{K,\ldots,2\}}-\frac{1}{T}\ln\left(\Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*\right)\right) \nonumber\\
&= \min_{n\in\{K,\ldots,2\}}\liminf_{T\rightarrow \infty }  \,\, -\frac{1}{T}\ln\left(\Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*\right)\right),
\label{eq:prob of error lower bound}
\end{align}
where the last equality holds since the set of potential values of $n$ is finite. 


By \eqref{eq:prob of error lower bound}, establishing the lower bound in Lemma \ref{lem:bae prob of error} reduces to prove the following result.

\begin{lemma}
\label{lem:eliminate best}
For $n\in\{K,\ldots,2\}$,
\[
\liminf_{T\rightarrow \infty }  \,\, -\frac{1}{T} \ln\left(\Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*\right)\right) \geq w_n\Gamma_{\thetabf,n}.
\]
\end{lemma}


\begin{proof}
We have
\begin{equation}
\label{eq:eliminate best}
\Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*\right)
= \sum_{J \in \mathcal{J}_{\thetabf,n}} \Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*, C_n = J\right)
\leq |\mathcal{J}_{\thetabf,n}| \cdot \max_{J \in \mathcal{J}_{\thetabf,n}} \Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*, C_n = J\right).
\end{equation}
Fix $J \in \mathcal{J}_{\thetabf,n}$. Since the arm $\ell_n$ is eliminated at the end of $T_n \triangleq (\beta_K+\cdots + \beta_n)\cdot T$ timesteps, the event $\{\ell_n = I^*, C_n = J\}$ implies that
$\{\bm{m}_{T_n}\in M, \bm{p}_{T_n}\in P\}$, where
\[
M = \left\{\lambdabf\in\mathbb{R}^K: \lambda_{I^*}\leq \lambda_i,\forall i \in J\right\}
\quad\text{and}\quad
P = \left\{\bm{p}\in\Sigma_K: p_i = \tilde{p},\forall i\in J\right\}.
\]
where $\tilde{p} = \frac{\left(\frac{\beta_K}{K} + \cdots + \frac{\beta_n}{n}\right)T}{T_n} = \frac{\frac{\beta_K}{K} + \cdots + \frac{\beta_n}{n}}{\beta_K + \cdots + \beta_n}$.
That is, 
\[
\Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*, C_n = J\right) \leq 
\Prob^{\tt{BAE}}_{\thetabf,T}\left(\bm{m}_{T_n} \in M, \bm{p}_{T_n}\in P\right),
\]
and thus
\begin{align*}
\liminf_{T\rightarrow \infty }  \,\, -\frac{1}{T} 
\ln\left( \Prob^{\tt{BAE}}_{\thetabf,T}\left(\ell_n = I^*, C_n = J\right) \right)
&\geq 
\liminf_{T\rightarrow \infty }  \,\, -\frac{1}{T} 
\ln\left( \Prob^{\tt{BAE}}_{\thetabf,T}\left(\bm{m}_{T_n}\in M, \bm{p}_{T_n} \in P\right) \right) \\
&= \left(\beta_K + \cdots + \beta_n \right)\liminf_{T\rightarrow \infty }  \,\, -\frac{1}{T_n} 
\ln\left( \Prob^{\tt{BAE}}_{\thetabf,T}\left(\bm{m}_{T_n}\in M, \bm{p}_{T_n} \in P\right) \right) \\
&\geq  \left(\beta_K + \cdots + \beta_n \right)\inf_{\bm{p}\in \cl(P)}F_{\thetabf,M}(\bm{p})\\
&\geq \left(\beta_K + \cdots + \beta_n \right) \tilde{p}
\inf_{\lambdabf \in \cl (M) } \sum_{i \in J}d(\lambda_i,\theta_i)\\
&= \left(\frac{\beta_K}{K} + \cdots + \frac{\beta_n}{n}\right)
\inf_{\lambdabf \in \cl (M) } \sum_{i \in J}d(\lambda_i,\theta_i) \\
&=w_n\Gamma_{\thetabf,n},
\end{align*}
where the second inequality uses Theorem \ref{thm:LD}.
Applying the inequality in \eqref{eq:eliminate best} completes the proof.
\end{proof}










\subsection{Large-deviation results}
The proof of Lemma \ref{lem:eliminate best} above relies on the following large-deviation results, which extend \citet[Theorem 1]{wang2023best} for Gaussian distributions.
\begin{Theorem}%[Theorem 1 in \citet{wang2023best}]
\label{thm:LD}
Fix $\thetabf\in\Theta$. For a non-anticipating algorithm, if the empirical allocation sequence $\{\bm{p}_t\}_{t\geq 1}$ satisfies the large deviation principle (LDP) upper bound with rate function $I$, then 
\begin{enumerate}
    \item $\{\bm{m}_t\}_{t\geq 1}$ satisfies the LDP lower bound with rate function 
    \[
    \lambdabf \mapsto \min_{\bm{p}\in \Sigma_K}\max\{ \Psi_{\thetabf}(\lambdabf,\bm{p}),I(\bm{p})\},
    \]
    where $\Psi_{\thetabf}(\lambdabf,\bm{p}) \triangleq \sum_{i=1}^K p_i \cdot d(\lambda_i ,\theta_i)$;
    \item 
    Given $n\in\{2,\ldots, K\}$, consider a set $J\subseteq \mathbb{R}^K$ such that $|J| = n$ and $I^*\in J$. Then for the set 
    \[
    M \triangleq \left\{\lambdabf\in\mathbb{R}^K:\,\,  \lambda_{I^*}\leq \lambda_i, \,\, \forall i \in J\right\}
    \]
    and any Borel subset $P\subseteq \Sigma_K$,
    \[
    \liminf_{t\rightarrow \infty }  \,\,  - \frac{1}{t} \ln 
    \left(\Prob_{\thetabf}\left(  \bm{m}_t\in  M, \,\, \bm{p}_t\in P\right)\right) \geq  \inf_{\bm{p}\in \cl(P)} \max\left\{ F_{\thetabf,M}(\bm{p}),I(\bm{p})\right\},
    \]
    where $F_{\thetabf,M}(\bm{p})\triangleq\inf_{\lambdabf \in \cl (M) }\Psi_{\thetabf}(\lambdabf,\bm{p})$,
    and $\cl (A)$ denotes the closure of the set $A$.
\end{enumerate}
\end{Theorem}









\section{Proof of Lemma \ref{lem:lower bound}}
\label{sec:lower bound}





Fix $n \in \{K,\ldots, 2\}$. For $\mu_1 > \mu_2\geq \cdots \geq \mu_n$, we define
 \begin{align}\label{opt:1}
	\Psi(\mu_1,\mu_2,\ldots,\mu_n) \triangleq 
\inf_{\substack{(\lambda_1,\ldots,\lambda_n)\in \mathbb{R}^n: \\ \lambda_{1}\le \min_{i \in [n]} \lambda_i}} 
    \sum_{i=1}^n (\lambda_i-\mu_i)^2.
\end{align}
Given this, we can write
\[
\Gamma_{\thetabf,n} = \min_{J\in \mathcal{J}_{\thetabf, n}} \inf_{\lambdabf\in \Lambda_{\thetabf, J}}
\sum_{i \in J}d(\lambda_i,\theta_i) = \frac{1}{2\sigma^2}\min_{J\in \mathcal{J}_{\thetabf, n}} \Psi\left(\theta_{I^*}, \theta_{(2)_J},\ldots, \theta_{(n)_J}\right),
\]
where $(i)_J$ denotes the index of the $i$-th largest element in the set $J$ for $i=2,\ldots,n$; note that the largest element in $J$ is $I^*$.

To prove Lemma \ref{lem:lower bound}, it suffices to prove the following result: 
\begin{lemma}[Bounds on $\Psi(\mu_1,\mu_2,\ldots,\mu_n)$]
\label{lem:xi lower bound}
The value $\Psi(\mu_1,\mu_2,\ldots,\mu_n)$ can be lower bounded as follows,
\[
\Psi(\mu_1,\mu_2,\ldots,\mu_n) \geq \frac{n-1}{n}(\mu_1 - \mu_2)^2,
\]
where the inequality becomes equality when $\mu_2 = \cdots = \mu_n$.
On the other hand, $\Psi(\mu_1,\mu_2,\ldots,\mu_n)$ can be upper bounded:
\[
\Psi(\mu_1,\mu_2,\ldots,\mu_n)  < \sum_{i=2}^n (\mu_1 - \mu_i)^2.
\]
\end{lemma}

%%%
The proof starts with the calculation of $\Psi(\mu_1,\mu_2,\ldots,\mu_n)$, which uses the following result in \citet{wang2023best}:
\begin{proposition}[Proposition 1 in \citet{wang2023best}]
\label{prop:xi}
	The value $\Psi(\mu_1,\mu_2,\ldots,\mu_n)$ can be calculated as follows,
	$$
	\Psi(\mu_1,\mu_2,\ldots,\mu_n)=\left\{
	\begin{array}{ll}
	\sum_{i=1,n} \left(\mu_i-\frac{\mu_1+\mu_n}{2}\right)^2,&\hbox{ if }\mu_{n-1}\ge \frac{\mu_1+\mu_n}{2},\\
	\sum_{i=1,n-1,n} \left(\mu_i-  \frac{\mu_1+\mu_{n-1}+\mu_n}{3} \right)^2,&\hbox{ if }\mu_{n-1}< \frac{\mu_1+\mu_n}{2},\,\,\mu_{n-2}\ge \frac{\mu_1+\mu_{n-1}+\mu_n}{3}, \\
	\vdots&\vdots\\
	\sum_{i=1}^n \left(\mu_i -  \frac{\sum_{j=1}^n\mu_j}{n} \right)^2,&\hbox{ if }\mu_{n-1}< \frac{\mu_1+\mu_n}{2},\,\,\ldots,\,\, \mu_2< \frac{\mu_1+\mu_3+\cdots+\mu_n}{n-1}.
	\end{array}
	\right.
	$$
\end{proposition}

We can simplify the above formulas by introducing $\Delta_i = \mu_1 - \mu_i$ for $i=1, 2,\ldots, n$.

\begin{corollary}\label{cor:xi}
	The value $\Psi(\mu_1,\mu_2,\ldots,\mu_n)$ can be rewritten as follows,
	$$
	\Psi(\mu_1,\mu_2,\ldots,\mu_n)=\left\{
	\begin{array}{ll}
	\frac{\Delta_n^2}{2},&\hbox{ if }\Delta_{n-1}\le \frac{\Delta_n}{2},\\
	\left(\sum_{i=n-1}^n\Delta_{i}^2\right) - \frac{\left(\sum_{i=n-1}^n\Delta_{i}\right)^2}{3},&\hbox{ if }\Delta_{n-1}> \frac{\Delta_n}{2},\,\,\Delta_{n-2}\le \frac{\sum_{i=n-1}^n\Delta_{i}}{3}, \\
	\vdots&\vdots\\
	 \left(\sum_{i=2}^n\Delta_{i}^2\right) - \frac{\left(\sum_{i=2}^n\Delta_{i}\right)^2}{n},&\hbox{ if }\Delta_{n-1} > \frac{\Delta_n}{2},\,\,\ldots,\,\,
  \Delta_2 > \frac{\sum_{i=3}^n\Delta_i}{n-1}.
	\end{array}
	\right.
	$$
\end{corollary}

\begin{proof}[Proof of Corollary \ref{cor:xi}]
If the $m$-th condition holds where $m \in [n-1]$, we have
\begin{align*}
\Psi(\mu_1,\mu_2,\ldots,\mu_n) &= \sum_{i=1,n-m+1,\ldots,n} \left(\mu_i-  \frac{\mu_1 + \sum_{j = n-m+1}^n\mu_j}{m+1} \right)^2 \\
&= \sum_{i=1,n-m+1,\ldots,n} \left(\Delta_i - \frac{\sum_{j = n-m+1}^n\Delta_j}{m+1}\right)^2.
\end{align*}
For notational convenience, write $a = \frac{\sum_{j = n-m+1}^n\Delta_i}{m+1}$. Then
\begin{align*}
\Psi(\mu_1,\mu_2,\ldots,\mu_n) &= a^2 + \sum_{i = n-m+1}^n \left(\Delta_i - a\right)^2 \\
&= a^2 + m a^2  +  \sum_{i = n-m+1}^n\Delta_i^2 - 2a\sum_{i = n-m+1}^n\Delta_i\\
&= \sum_{i = n-m+1}^n\Delta_i^2 - (m+1)a^2 \\
&= \sum_{i = n-m+1}^n\Delta_i^2 - \frac{\left(\sum_{i = n-m+1}^n\Delta_i\right)^2}{m+1}.
\end{align*}
\end{proof}


Now we are ready to complete the proof of Lemma \ref{lem:xi lower bound}.
\begin{proof}[Proof of Lemma \ref{lem:xi lower bound}]
The upper bound follows directly from the formulas in Corollary \ref{cor:xi}.

Now we are going to prove the lower bound. If the $m$-th condition in Corollary~\ref{cor:xi} holds where $m\in[n-2]$, we have
\begin{align*}
\left(\sum_{i=n-m+1}^n\Delta_{i}^2\right) - \frac{\left(\sum_{i=n-m+1}^n\Delta_{i}\right)^2}{m+1}
&\geq \frac{\left(\sum_{i=n-m+1}^n\Delta_{i}\right)^2}{m} - \frac{\left(\sum_{i=n-m+1}^n\Delta_{i}\right)^2}{m+1} \\
&= \frac{\left(\sum_{i=n-m+1}^n\Delta_{i}\right)^2}{m(m+1)}\\
&\geq \frac{(m+1)\Delta_{n-m}^2}{m}
> \Delta_2^2,
\end{align*}
where the second-to-last inequality applied the $m$-th condition: $\Delta_{n-m} \leq \frac{\sum_{i=n-m+1}^n\Delta_{i}}{m+1}$.

On the other hand, if the last condition in Corollary~\ref{cor:xi} holds, applying the Cauchy–Schwarz inequality gives
\begin{align*}
\left(\sum_{i=2}^n\Delta_{i}^2\right) - \frac{\left(\sum_{i=2}^n\Delta_{i}\right)^2}{n}
&\geq \frac{\left(\sum_{i=2}^n\Delta_{i}\right)^2}{n-1} - \frac{\left(\sum_{i=2}^n\Delta_{i}\right)^2}{n} \\
&= \frac{\left(\sum_{i=2}^n\Delta_{i}\right)^2}{(n-1)n}\\
&\geq \frac{n-1}{n}\Delta_2^2,
\end{align*}
where the last inequality simply uses $\Delta_{i}\geq \Delta_2$ for any $i\in\{2,\ldots,n\}$.

Combining the two cases completes the inequality in Lemma \ref{lem:xi lower bound}. The equality holds if and only if $\Delta_2 = \cdots = \Delta_n$.
\end{proof}






