\section{Failure of invertibility and validity of OP/LP/ACF moment condition\label{app:validity}}

\paragraph{Omitted proofs.}

\begin{proof}[Proof of Theorem \ref{thm:bias_reduction}]
	Using $\zeta_{it-1}=q^*_{it-1} - \expt[q_{it-1}|x_{it-1}]$, we have
	\begin{eqnarray}
&& \expt\left[ g^\prime\left(q^*_{it-1} - \zeta_{it-1} -f(k_{it-1},v_{it-1}) \right)\zeta_{it-1} \big| z_{it}\right]\nonumber\\
&=& \expt\left[ g^\prime\left(\expt[q_{it-1}|x_{it-1}] -f(k_{it-1},v_{it-1}) \right)\zeta_{it-1} \big| z_{it}\right]\nonumber\\
&=& \expt\left[  \expt [g^\prime\left(\expt[q_{it-1}|x_{it-1}] -f(k_{it-1},v_{it-1}) \right)\zeta_{it-1} | x_{it-1}] \big| z_{it}\right]\nonumber\\
&=& \expt\left[ g^\prime\left(\expt[q_{it-1}|x_{it-1}] -f(k_{it-1},v_{it-1}) \right) \expt[\zeta_{it-1} | x_{it-1}] \big| z_{it}\right]\nonumber\\
& = & 0, \label{eq:bias_correction_theorem_part_2}
	\end{eqnarray}
where the second equality uses $x_{it-1}\supseteq z_{it}$ and the law of iterated expectations, the third equality uses that $g^\prime\left(\expt[q_{it-1}|x_{it-1}] -f(k_{it-1},v_{it-1}) \right)$ is a function of $x_{it-1}$ because $x_{it-1}=\left(k_{it-1},v_{it-1},\ldots\right)$, and the last equality uses $\expt[\zeta_{it-1} | x_{it-1}] =0$. Finally, using equation \eqref{eq:bias_correction_theorem_part_2} and $\zeta_{it-1}=q^*_{it-1} - \expt[q_{it-1}|x_{it-1}]$ establishes equation \eqref{eq:first_order_correction}.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:bound}]
Because $g^0\in \mathcal{G}$, we have
\begin{eqnarray*}
	&&\inf_{\tilde g\in \mathcal{G}}\norm{\expt\left[g^0(\omega_{it-1})|z_{it}\right]-\expt\left[\tilde g\left(\expt\left[\omega_{it-1}|x_{it-1}\right]\right)|z_{it}\right]}_{L, 1} \\
	&=&\inf_{\tilde g\in \mathcal{G}}\expt\left[\Big|\expt\left[g^0(\omega_{it-1})|z_{it}\right]-\expt\left[\tilde g\left(\expt\left[\omega_{it-1}|x_{it-1}\right]\right)|z_{it}\right]\Big|\right] \\
	&\le& \expt\left[\Big\vert \expt[g^0(\omega_{it-1})|z_{it}] - \expt[g^0(\expt[\omega_{it-1}|x_{it-1}])|z_{it}] \Big \vert\right].
\end{eqnarray*}
Using a second-order Taylor expansion of $g^0$ around $\expt[\omega_{it-1}|x_{it-1}]$, we have
\begin{eqnarray*}
&&\Big\vert \expt[g^0(\omega_{it-1})|z_{it}] - \expt[g^0(\expt[\omega_{it-1}|x_{it-1}])|z_{it}] \Big \vert \\
&=& \Big\vert\expt \left[ g^{0\prime}(\expt[\omega_{it-1}|x_{it-1}])\zeta_{it-1}  \Big\vert z_{it} \right] + \expt \left[ g^{0\prime\prime}(\tilde{\omega}_{it-1}) \zeta_{it-1}^2 \Big\vert z_{it} \right] \Big\vert \\
&\le &\Big\vert\expt \left[ g^{0\prime}(\expt[\omega_{it-1}|x_{it-1}])\zeta_{it-1}  \Big\vert z_{it} \right] \Big\vert +
\Big\vert \expt \left[ g^{0\prime\prime}(\tilde{\omega}_{it-1}) \zeta_{it-1}^2 \Big\vert z_{it} \right] \Big\vert
\\
&\le &\Big\vert\expt \left[ g^{0\prime}(\expt[\omega_{it-1}|x_{it-1}])\zeta_{it-1}  \Big\vert z_{it} \right] \Big\vert + \tau \expt \left[ \zeta_{it-1}^2 \Big\vert z_{it} \right],
\end{eqnarray*}
where $\tilde{\omega}_{it-1}$ is some value between $\omega_{it-1}$ and $\expt[\omega_{it-1}|x_{it-1}]$, and the last inequality follows from the definition of $\tau$. As in the proof of Theorem \ref{thm:bias_reduction}, using $x_{it-1}\supseteq z_{it}$ and the law of iterated expectations yields $\expt \left[ g^{0\prime}(\expt[\omega_{it-1}|x_{it-1}]) \zeta_{it-1} \Big\vert z_{it} \right] = 0 $. Thus, we have
\begin{equation*}
	\inf_{\tilde g\in \mathcal{G}}\norm{\expt\left[g^0(\omega_{it-1})|z_{it}\right]-\expt\left[\tilde g\left(\expt\left[\omega_{it-1}|x_{it-1}\right]\right)|z_{it}\right]}_{L, 1} \le\expt\left[ \tau \expt \left[ \zeta_{it-1}^2 | z_{it} \right]\right] = \tau \var(\zeta_{it-1}).
\end{equation*}
\end{proof}

\section{Monte Carlo exercise\label{app:montecarlo}}

\paragraph{Data generating process.}

Marginal revenue is
\begin{equation*}
mr_{it}=-\ln\left(1+\exp(\delta_{2i})\right)+p_{it}
\end{equation*}
and marginal cost is
\begin{equation*}
mc_{it}=p^V_{i}+v_{it}-f(k_{it},v_{it})-\ln\frac{\partial f(k_{it},v_{it})}{\partial v_{it}}-\omega_{it}.
\end{equation*}
We rewrite $mr_{it}=mc_{it}$ as
$$
\frac{\delta_{1i}+\exp(-\delta_{2i})(f(k_{it},v_{it})+\omega_{it})}{1+\exp(-\delta_{2i})}-\ln\left(1+\exp(\delta_{2i})\right)+\ln\frac{\partial f(k_{it},v_{it})}{\partial v_{it}}-p^V_{i}-v_{it}=0
$$
and solve numerically for $v_{it}$. With $v_{it}$ in hand, we determine $q^*_{it}=f(k_{it},v_{it})+\omega_{it}$, $q_{it}=q^*_{it}+\varepsilon_{it}$, and $p_{it}=\frac{\delta_{1i}-q^*_{it}}{1+\exp(-\delta_{2i})}$.

As capital fully depreciates between periods and the firm has static expectations, it chooses $k_{it+1}$ in period $t$ given $\omega_{it}$, $\delta_{i}$, $p^K_{i}$, and $p^V_{i}$ whilst anticipating that it optimally chooses $\tilde v_{it+1}$ in period $t+1$. To maximize its expected profit in period $t+1$, in period $t$ the firm solves
\begin{gather*}
\max_{k_{it+1}}\left(\max_{\tilde v_{it+1}}\exp(\tilde p_{it+1}+\tilde q^*_{it+1})-\exp(p^K_{i}+k_{it+1})-\exp(p^V_{i}+\tilde v_{it+1})\right) \\
=\max_{k_{it+1},\tilde v_{it+1}}\exp(\tilde p_{it+1}+\tilde q^*_{it+1})-\exp(p^K_{i}+k_{it+1})-\exp(p^V_{i}+\tilde v_{it+1})
\end{gather*}
subject to
\begin{gather*}
\tilde q^*_{it+1}=f(k_{it+1},\tilde v_{it+1})+\omega_{it}, \\
\tilde q^*_{it+1}=\delta_{1i}-(1+\exp(-\delta_{2i}))\tilde p_{it+1}.
\end{gather*}
The solution is
\begin{gather*}
k_{it+1}=\frac{1}{1-\rho}\left(\ln\alpha-p^K_{i}\right)
	+\frac{\exp(\delta_{2i})+1}{\exp(\delta_{2i})+1-\nu}\Bigg(
	\ln\nu \notag\\
	+\left(\frac{\nu}{(\exp(\delta_{2i})+1)\rho}-1\right)\ln\left(\alpha\left(\frac{\alpha}{\exp(p^K_{i})}\right)^\frac{\rho}{1-\rho}
	+(1-\alpha)\left(\frac{1-\alpha}{\exp(p^V_{i})}\right)^\frac{\rho}{1-\rho}\right) \notag\\
	-\ln\left(\exp(\delta_{2i})+1\right)+\frac{1}{\exp(\delta_{2i})+1}\omega_{it}+\frac{\delta_{1i}}{1+\exp(-\delta_{2i})}
	\Bigg).
\end{gather*}

\paragraph{Neural network estimator.}

The neural network uses two hidden layers of 128 neurons and ReLU activation. We standardize the input data. We train the network using the stochastic gradient decent (SDG) method on 80\% of firms, setting aside 20\% of firms for validation, to minimize the mean squared error. We stop the SDG iterations if the mean squared error for the validation sample does not improve after 10 epoch iterations. We use the trainnet command in Matlab and set the learning rate to 0.01 and the mini-batch size to 500 observations.

\paragraph{GMM estimator.}

Corresponding to moment condition \eqref{eq:step2} in step 2, define the moment function
\begin{equation}\label{eq:moment_791}
m_{it}(\theta)=q_{it}-f(k_{it},v_{it};\theta_f)-g\left(e(x_{it-1}) - f(k_{it-1},v_{it-1};\theta_f);\theta_g\right),
\end{equation}
where we replace $e(x_{it-1})$ by the estimate from step 1. In step 2, we solve the GMM problem
\begin{equation}\label{eq:GMM_795}
\min_\theta \left(\frac{1}{NT}\sum_{i,t}h(z_{it})m_{it}(\theta)\right)^\top W \left(\frac{1}{NT}\sum_{i,t}h(z_{it})m_{it}(\theta)\right),
\end{equation}
where the superscript $\top$ denotes the transpose, $h(z_{it})$ is the complete set of Hermite polynomials of total degree 4 in the variables in $z_{it}$, and 
\begin{equation*}
	W=\left(\frac{1}{NT-1}\sum_{i,t}\left(h(z_{it})m_{it}\left(\theta^0\right) - \hat{\mu}\right)^\top\left(h(z_{it})m_{it}\left(\theta^0\right) - \hat{\mu}\right)\right)^{-1} \text{ with } \hat{\mu} = \frac{1}{NT}\sum_{i,t}h(z_{it})m_{it}\left(\theta^0\right),
\end{equation*}
is a weighting matrix evaluated at the true parameters values $\theta^0$.

Corresponding to moment condition \eqref{eq:modified_step2}, our modification of the OP/LP/ACF procedure redefines the moment function as
\begin{multline}\label{eq:modified_moment_791}
m_{it}(\theta)=
q_{it}-f(k_{it},v_{it};\theta_f) - g\left(e(x_{it-1}) -f(k_{it-1},v_{it-1};\theta_f);\theta_g \right) \\
	 - g^\prime\left(e(x_{it-1}) -f(k_{it-1},v_{it-1};\theta_f);\theta_g \right) (q_{it-1} - e(x_{it-1})),
\end{multline}
where we replace $e(x_{it-1})$ by the estimate from step 1. We hold fixed $W$ to facilitate the comparison between our modification and the original procedure. 

\paragraph{Lagrange multiplier (LM) test.}

We first derive the LM test for the original moment function \eqref{eq:moment_791}. To account for the plug-in nature of the GMM estimator in step 2, we have to explicitly specify how $e(x_{it-1})$ is modelled and estimated in step 1. In our Monte Carlo exercise, we model $e(x_{it-1}) = r^\top(x_{it-1}) \tau$, where the superscript $\top$ denotes the transpose, $r(x_{it-1})$ is the complete set of Hermite polynomials of total degree 4 in the variables in $x_{it-1}$, and $\tau$ is a parameter vector. Consequently, we define
\begin{equation}\label{eq:moment_816}
m_{it}(\theta, \tau)=q_{it}-f(k_{it},v_{it};\theta_f)-g\left(r^\top(x_{it-1}) \tau - f(k_{it-1},v_{it-1};\theta_f);\theta_g\right),
\end{equation}
where we make explicit the dependence of the moment function on $\tau$. We estimate $\tau$ in step 1 by OLS as $\hat{\tau} = [\frac{1}{NT} \sum_{i,t} r(x_{it-1}) r^\top (x_{it-1})]^{-1} \frac{1}{NT}\sum_{i,t} q_{it-1} r(x_{it-1})$.\footnote{We can alternatively estimate $\tau$ as $\hat{\tau} = [\frac{1}{NT} \sum_{i,t} r(x_{it}) r^\top (x_{it})]^{-1} \frac{1}{NT}\sum_{i,t} q_{it} r(x_{it})$. In our simulated datasets, both current and lagged values are available for all $T$ periods and $N$ firms.}

Following standard asymptotic arguments, we can show that
\begin{equation*}
\widehat{\Sigma}^{-\frac{1}{2}}\frac{1}{\sqrt{NT}} \sum_{i, t} h(z_{it}) m_{it}(\theta^0, \hat{\tau}) \convd N(0, I),
\end{equation*}
where $\widehat{\Sigma} = \widehat{\Lambda} \widehat{\Omega} \widehat{\Lambda}^{\top}$,
\begin{equation*}
	\widehat{\Lambda} = \begin{pmatrix}
		I & \sum_{i,t} h(z_{it})\left[ \frac{\partial m_{it}(\theta^0, \hat{\tau})}{\partial \tau^\top} \right] \left[ \sum_{i,t} r(x_{it-1}) r^\top(x_{it-1})  \right]^{-1}
\end{pmatrix},
\end{equation*}
with $I$ being the $\dim(h(z_{it}))\times \dim(h(z_{it}))$ identity matrix, and
\begin{eqnarray*}
	\widehat{\Omega} &=&
\begin{pmatrix}
	\widehat{\Omega}_{11} & \widehat{\Omega}_{12}\\
	\widehat{\Omega}^\top_{12} & \widehat{\Omega}_{22}
\end{pmatrix}, \\
	\widehat{\Omega}_{11} &=& \frac{1}{NT}\sum_{t=1}^T\sum_{t'=1}^T\sum_{i=1}^N\left[ m_{it}(\theta^0, \hat{\tau}) m_{it'}(\theta^0, \hat{\tau}) h(z_{it}) h^\top(z_{it'}) \right], \\
	\widehat{\Omega}_{12} &=& \frac{1}{NT}\sum_{t=1}^T\sum_{t'=1}^T\sum_{i=1}^N\left[ m_{it}(\theta^0, \hat{\tau}) (q_{it'-1} - r^\top(x_{it'-1}) \hat{\tau}) h(z_{it}) r^\top(x_{it'-1}) \right], \\
	\widehat{\Omega}_{22} &=& \frac{1}{NT}\sum_{t=1}^T\sum_{t'=1}^T\sum_{i=1}^N\left[ (q_{it-1} - r^\top(x_{it-1}) \hat{\tau}) (q_{it'-1} - r^\top(x_{it'-1}) \hat{\tau}) r(x_{it-1}) r^\top(x_{it'-1}) \right].
\end{eqnarray*}
Note that $\widehat{\Sigma}$ incorporates firm-level clustering and thus allows for arbitrary correlation within firm across time in the data.
As $N\to\infty$, the LM statistic
\begin{equation*}
S_{N} = \frac{1}{NT} \left( \sum_{i, t} h(z_{it}) m_{it}(\theta^0, \hat{\tau}) \right)^\top \widehat{\Sigma}^{-1} \left( \sum_{i, t} h(z_{it}) m_{it}(\theta^0, \hat{\tau}) \right)
\end{equation*}
converges to a $\chi^2$ distribution with $\dim(h(z_{it}))$ degrees of freedom. Let $c_{1-\alpha}$ be the $1-\alpha$ quantile of this distribution. Then rejecting $H_0: \expt[h(z_{it})m_{it}(\theta^0, \tau^0)] = 0$ if $S_N > c_{1-\alpha}$ is a valid LM inference procedure with asymptotic size $\alpha$.

Turning to the modified moment function \eqref{eq:modified_moment_791}, Neyman orthogonality renders correcting for the plug-in nature of the GMM estimator in step 2 superfluous. Consequently, we use a standard LM test with firm-level clustering. As $N\to\infty$, the LM statistic
\begin{equation*}
S_{N} = \frac{1}{NT} \left( \sum_{i, t} h(z_{it}) m_{it}(\theta^0, \hat{\tau}) \right)^\top \widehat{\Omega}_{11}^{-1} \left( \sum_{i, t} h(z_{it}) m_{it}(\theta^0, \hat{\tau}) \right)
\end{equation*}
converges to a $\chi^2$ distribution with $\dim(h(z_{it}))$ degrees of freedom. Rejecting $H_0: \expt[h(z_{it})m_{it}(\theta^0, \tau^0)] = 0$ if $S_N > c_{1-\alpha}$ is a valid LM inference procedure with asymptotic size $\alpha$.

\section{Modification of OP/LP/ACF moment condition\label{app:modification_orthogonalization}}

\paragraph{Omitted proofs.}

\begin{proof}[Proof of Theorem \ref{thm:neyman_orth}]
	By the definition of the derivative, it suffices to show that for any non-zero sequence $\lambda_n$ with $\lim_{n\to\infty}\lambda_n = 0$, we have
	\begin{multline}
		\lim_{n\to\infty} \frac{1}{\lambda_n} \Bigg[ \Bigg(\expt\left[q_{it}-f(k_{it},v_{it}) - g\left( \expt[q_{it-1}|x_{it-1}] + \lambda_n \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right) \right.\\
		- \left. g^\prime\left(\expt[q_{it-1}|x_{it-1}] + \lambda_n \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right)(q_{it-1} - \expt[q_{it-1}|x_{it-1}] - \lambda_n \delta(x_{it-1}) \big| z_{it}\right] \Bigg)\\
- \Bigg(\expt\big[q_{it}-f(k_{it},v_{it}) - g\left( \expt[q_{it-1}|x_{it-1}]  -f(k_{it-1},v_{it-1}) \right) \\
-  g^\prime\left(\expt[q_{it-1}|x_{it-1}]  -f(k_{it-1},v_{it-1}) \right)(q_{it-1} - \expt[q_{it-1}|x_{it-1}]) \big| z_{it}\big] \Bigg) \Bigg] = 0. \label{eq:722}
	\end{multline}

Similar to the idea used in the proof of Theorem \ref{thm:bias_reduction}, the law of iterated expectations implies
    \begin{gather}
	\expt\left[  g^\prime\left(\expt[q_{it-1}|x_{it-1}] + \lambda_n \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right)(q_{it-1} - \expt[q_{it-1}|x_{it-1}]) | z_{it} \right] = 0, \label{eq:727} \\
	\expt\left[  g^\prime\left(\expt[q_{it-1}|x_{it-1}] -f(k_{it-1},v_{it-1}) \right)(q_{it-1} - \expt[q_{it-1}|x_{it-1}]) | z_{it} \right] = 0. \label{eq:730}
	\end{gather}
Using equations \eqref{eq:727} and \eqref{eq:730}, equation \eqref{eq:722} is equivalent to
\begin{align}
	  & \lim_{n\to\infty}\frac{1}{\lambda_n}\expt\left[g\left( \expt[q_{it-1}|x_{it-1}] + \lambda_n \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right)  - g\left( \expt[q_{it-1}|x_{it-1}]  -f(k_{it-1},v_{it-1}) \right) \Big\vert z_{it} \right] \nonumber\\
	=& \lim_{n\to\infty }\expt \left[ g^\prime\left(\expt[q_{it-1}|x_{it-1}] + \lambda_n \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right)\delta(x_{it-1}) \Big\vert z_{it}\right].  \label{eq:749}
\end{align}
It therefore remains to establish equation \eqref{eq:749}. We do this by showing that both sides of equation \eqref{eq:749} are equal to $\expt\left[  g^\prime\left( \expt[q_{it-1}|x_{it-1}]  -f(k_{it-1},v_{it-1}) \right) \delta(x_{it-1}) \bigg\vert z_{it} \right]$.

Because $g^\prime$ is bounded and $\delta$ is integrable,  there exists some $\eta > 0$ such that
\begin{equation}\label{eq:753}
	\expt\left[ \sup_{\lambda: |\lambda| < \eta } \left| g^\prime\left(\expt[q_{it-1}|x_{it-1}] + \lambda \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right)\delta(x_{it-1}) \right|   \Bigg\vert z_{it} \right] < \infty
\end{equation}
almost surely.\footnote{Theorem \ref{thm:neyman_orth} continues to hold if the assumption that $g^\prime$ is bounded is relaxed to this condition.}
Because $g^\prime $ is continuous, the dominated convergence theorem therefore implies that
\begin{eqnarray}
&&\lim_{n\to\infty }\expt \left[ g^\prime\left(\expt[q_{it-1}|x_{it-1}] + \lambda_n \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right)\delta(x_{it-1}) \Big\vert z_{it}\right] \nonumber \\
&=&\expt \left[ g^\prime\left(\expt[q_{it-1}|x_{it-1}] -f(k_{it-1},v_{it-1}) \right)\delta(x_{it-1}) \Big\vert z_{it}\right]. \label{eq:758}
\end{eqnarray}

Turning to the other side of equation \eqref{eq:749}, the mean value theorem implies that
\begin{align}
&\frac{1}{\lambda_n}\left( g\left( \expt[q_{it-1}|x_{it-1}] + \lambda_n \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right)  - g\left( \expt[q_{it-1}|x_{it-1}]  -f(k_{it-1},v_{it-1}) \right)  \right) \nonumber \\
	=& g'\left( \expt[q_{it-1}|x_{it-1}] + \tilde{\lambda}_n \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right) \delta(x_{it-1}),
\end{align}
where $\tilde{\lambda}_n$ is some value between $0$ and $\lambda_n$ that implicitly depends on $x_{it-1}$. Because $|\tilde{\lambda}_n| \le |\lambda_n|$ and $g^\prime$ is continuous, we have
\begin{align}
&\lim_{n\to\infty} g'\left( \expt[q_{it-1}|x_{it-1}] + \tilde{\lambda}_n \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right) \delta(x_{it-1}) \nonumber \\
	= &\  g'\left( \expt[q_{it-1}|x_{it-1}]  -f(k_{it-1},v_{it-1}) \right) \delta(x_{it-1}) \label{eq:768}
\end{align}
for all $x_{it-1}$. Given inequality \eqref{eq:753} and equation \eqref{eq:768}, the dominated convergence theorem implies that
\begin{align*}
&\lim_{n\to\infty}\frac{1}{\lambda_n}\expt\left[g\left( \expt[q_{it-1}|x_{it-1}] + \lambda_n \delta(x_{it-1}) -f(k_{it-1},v_{it-1}) \right)  - g\left( \expt[q_{it-1}|x_{it-1}]  -f(k_{it-1},v_{it-1}) \right) \Big\vert z_{it} \right] \\
	=&\  \expt\left[  g^\prime\left( \expt[q_{it-1}|x_{it-1}]  -f(k_{it-1},v_{it-1}) \right) \delta(x_{it-1}) \bigg\vert z_{it} \right].
\end{align*}
This establishes equation \eqref{eq:749}.
\end{proof}

