\section{Sensitivity analysis\label{app:sensitivity}}

Assume $f(k_{it}, v_{it}; \theta_f)$ is twice continuously differentiable in $\theta_f$ and $g(\omega_{it-1}; \theta_g)$ is twice continuously differentiable in $(\theta_g, \omega_{it-1})$, so that  $m_{it}(\theta, \lambda)$ is twice continuously differentiable in $(\theta, \lambda)$. Assume the product of $h$ and the first-order derivatives of $m_{it}(\theta, \lambda)$ is always integrable. Then the dominated convergence theorem implies
\begin{equation*}
	\pd{\expt[h(z_{it}) m_{it}(\theta, \lambda)]}{\theta^\top} = \expt\left[h(z_{it}) \pd{m_{it}(\theta, \lambda)}{\theta^\top} \right],\quad \pd{\expt[h(z_{it}) m_{it}(\theta, \lambda)]}{\lambda} = \expt\left[h(z_{it}) \pd{m_{it}(\theta, \lambda)}{\lambda} \right].
\end{equation*}
Similarly, assume the product of $h$ and the second-order derivatives of $m_{it}(\theta, \lambda)$ is always integrable. Then the dominated convergence theorem implies
\begin{equation*}
	\pd{^2\expt[h(z_{it}) m_{it}(\theta, \lambda)]}{\theta \partial\theta^\top} = \expt\left[h(z_{it}) \pd{^2m_{it}(\theta, \lambda)}{\theta \partial\theta^\top} \right],\quad	\pd{^2\expt[h(z_{it}) m_{it}(\theta, \lambda)]}{\theta \partial\lambda} = \expt\left[h(z_{it}) \pd{^2m_{it}(\theta, \lambda)}{\theta \partial\lambda} \right].
\end{equation*}
Under these regularity conditions, the pseudo-true value $\theta(\lambda)$ satisfies the first-order condition \eqref{eq:theta_FOC}.

Assume the first-order condition \eqref{eq:theta_FOC} identifies $\theta(\lambda)$ for $\lambda$ in a neighborhood of $1$. Then the implicit function theorem implies
\begin{multline}\label{eq:828}
	\expt\left[ \left( \pd{^2 m_{it}}{\theta\partial \theta^\top} \dd{\theta(\lambda)}{\lambda}\Big|_{\lambda = 1} + \pd{^2 m_{it}}{\theta\partial \lambda} \right)h^\top(z_{it})  \right] W \expt\left[ h(z_{it})m_{it}(\theta(\lambda), \lambda)  \right]\\
	+ \expt\left[ \pd{m_{it}}{\theta} h^\top(z_{it}) \right] W \expt\left[ h(z_{it})  \left( \pd{m_{it}}{\theta^\top} \dd{\theta(\lambda)}{\lambda}\Big|_{\lambda = 1} + \pd{m_{it}}{\lambda} \right) \right] = 0,
\end{multline}
where we use $\pd{m_{it}}{\theta}$, $\pd{m_{it}}{\lambda}$,  $\pd{^2 m_{it}}{\theta\partial \theta^\top}$, and $\pd{^2 m_{it}}{\theta\partial \lambda}$ to abbreviate $\pd{m_{it}(\theta(\lambda), \lambda)}{\theta}|_{\lambda = 1}$, $\pd{m_{it}(\theta(\lambda), \lambda)}{\lambda}|_{\lambda = 1}$, $\pd{^2 m_{it}(\theta(\lambda), \lambda)}{\theta\partial \theta^\top} |_{\lambda = 1}$, and $\pd{^2 m_{it}(\theta(\lambda), \lambda)}{\theta\partial \lambda} |_{\lambda = 1}$, respectively.
Equation \eqref{eq:828} can be rewritten as
\begin{equation*}
\Gamma  \dd{\theta(\lambda)}{\lambda}\Big|_{\lambda = 1} + \gamma = 0,
\end{equation*}
where $\Gamma$ and $\gamma$ are defined in equations \eqref{eq:Gamma_definition} and \eqref{eq:gamma_definition}, respectively. Assume $\Gamma$ is invertible. Then equation \eqref{eq:change_theta} follows.

Consistently estimating $\Gamma$ is straightforward because
\begin{equation*}
\pd{m_{it}}{\theta} =
\begin{pmatrix}
	\frac{\partial m_{it}}{\partial \theta_f} \\[7pt]
\frac{\partial m_{it}}{\partial \theta_g}
\end{pmatrix}
=
\begin{pmatrix}
	- \frac{\partial f(k_{it}, v_{it}; \theta_f)}{\partial \theta_f} + \frac{\partial g(\expt[q_{it-1}|x_{it-1}] - f(k_{it-1}, v_{it-1}; \theta_f); \theta_g)}{\partial \omega_{it-1} } \frac{\partial f(k_{it-1}, v_{it-1}; \theta_f)}{\partial \theta_f} \\[7pt]
 - \frac{\partial g(\expt[q_{it-1}|x_{it-1}] - f(k_{it-1}, v_{it-1}; \theta_f); \theta_g)}{\partial \theta_g}
\end{pmatrix}
\end{equation*}
and
\begin{equation*}
\pd{^2m_{it}}{\theta\partial \theta^{\top}} =
\begin{pmatrix}
	\pd{^2m_{it}}{\theta_f\partial \theta_f^{\top}}  & \pd{^2m_{it}}{\theta_f\partial \theta_g^{\top}} \\
\left(  \pd{^2m_{it}}{\theta_f\partial \theta_g^{\top}}  \right)^{\top} 	 & \pd{^2m_{it}}{\theta_g\partial \theta_g^{\top}}
\end{pmatrix},
\end{equation*}
where
\begin{eqnarray*}
	\pd{^2m_{it}}{\theta_f\partial \theta_f^{\top}} &=&
	- \frac{\partial^2 f(k_{it}, v_{it}; \theta_f)}{\partial \theta_f\partial \theta^\top_f} + \frac{\partial g(\expt[q_{it-1}|x_{it-1}] - f(k_{it-1}, v_{it-1}; \theta_f); \theta_g)}{\partial \omega_{it-1} } \frac{\partial^2 f(k_{it-1}, v_{it-1}; \theta_f)}{\partial \theta_f\partial \theta_f^\top} \\
							&& - \frac{\partial^2 g(\expt[q_{it-1}|x_{it-1}] - f(k_{it-1}, v_{it-1}; \theta_f); \theta_g)}{\partial \omega^2_{it-1} } \left( \frac{\partial f(k_{it-1}, v_{it-1}; \theta_f)}{\partial \theta_f}  \right)  \left( \frac{\partial f(k_{it-1}, v_{it-1}; \theta_f)}{\partial \theta_f}  \right)^\top,\\[7pt]
	\pd{^2m_{it}}{\theta_f\partial \theta_g^{\top}} &=&  \frac{\partial f(k_{it-1}, v_{it-1}; \theta_f)}{\partial \theta_f}  \frac{\partial^2 g(\expt[q_{it-1}|x_{it-1}] - f(k_{it-1}, v_{it-1}; \theta_f); \theta_g)}{\partial \omega_{it-1}\partial \theta_g^\top}, \\[7pt]
	\pd{^2m_{it}}{\theta_g\partial \theta_g^{\top}} &=&   \frac{\partial^2 g(\expt[q_{it-1}|x_{it-1}] - f(k_{it-1}, v_{it-1}; \theta_f); \theta_g)}{\partial \theta_g \partial \theta_g^\top},
\end{eqnarray*}
do not depend on the lagged prediction error $\zeta_{it-1}$. Following standard asymptotic arguments, $\Gamma$ can be consistently estimated by the finite-sample analog to equation \eqref{eq:Gamma_definition} using the estimate of $\expt[q_{it-1}|x_{it-1}]$ from step 1 and the estimate of $\theta$ from step 2.



