\section{Preliminaries}\label{sec-prelim}
In this section we fix notations, recall basics from metric measure geometry, \LLSn s and in particular, recall the different notions of Ricci curvature bounds in Subsection \ref{subsec-curv}. Then in Subsection \ref{subsec-loc} we recall the localization method on metric measure spaces.

\subsection{Optimal transport  and curvature-dimension conditions}\label{subsec-curv}
We start by recalling some basics of optimal transportation theory, both on metric measure spaces and on Lorentzian pre-length spaces, referring to \cite{Vil:09, Stu:06a, Stu:06b} for the metric case and to \cite{CM:24a, Bra:23b} for the Lorentzian case for more details.

\subsubsection{Curvature-dimension conditions for metric measure spaces}


Let $(X,\met)$ be a Polish space and let $\m$ be a Radon measure on $X$.  We assume that $\met$ is a proper metric, i.e., closed and bounded subsets are compact. The triple $(X, \met, \m)$ will be called a metric measure space.  

We denote with $L_\met$ the canonical length structure associated to $\met$, and with $\Geo(X)$ the set of constant speed geodesics $\gamma:[0,1]\rightarrow X$, i.e., $\gamma\in \Geo(X)$ if and only if $$\met(\gamma(s), \gamma(t))= (t-s)\, \met(\gamma(0), \gamma(1))$$ for $0\leq s\leq t\leq 1$. We call $(X,\met)$ a geodesic (metric) space if for all $x, y\in X$ there exists a geodesic $\gamma\in \Geo(X)$ such that $\gamma(0)=x$ and $\gamma(1)=y$. A geodesic is also a minimizer of  $L_\met$ subject to its  endpoints. We note that this notion of geodesic differs from the  one in the context of smooth Riemannian manifolds where geodesics are solutions of the geodesic equation $\nabla_{\dot\gamma} \dot\gamma=0$.

We denote by $\mathscr{P}(X)$ the set of Borel probability measures on $X$ and by $\mathscr{P}_\mathrm{c}(X)$ the subset of compactly supported ones. Given a metric measure space $(X,\met,\m)$, we also define the subset $\mathscr{P}^\ac(X)$  of $\m$-absolutely continuous probability measures and its subset $\mathscr{P}^\ac_\mathrm{c}(X)$  of measures with compact support. For $p\geq1$, we  define the set $\mathscr{P}_p(X)$ of probability measures $\mu\in \mathscr{P}(X)$ with $\int_X\met(x,x_0)^p\,\dint\mu(x)<\infty$ for some $x_0\in X$. Similarly we define $\mathscr P^\ac_p(X)$  and $\mathscr P^\ac_{p,\textnormal c}(X)$.

Given $\mu,\nu\in\mathscr{P}(X)$, let $\Pi(\mu,\nu)$ be the set of all their \emph{couplings}, i.e., measures $\pi\in\mathscr{P}(X^2)$ such that $\pi(\cdot\times X)=\mu$ and $\pi(X\times\cdot)=\nu$. Alternatively, given a Borel map $T:X\rightarrow Y$ from a polish space $X$ to a polish space $Y$, define the \emph{pushforward} $T_\sharp \mu$ of $\mu\in\mathscr{P}(X)$ by $T$ as a probability measure on $Y$ by the formula
$$T_\sharp \mu(E):=\mu(T^{-1}(E)), \ \ E\subseteq X \mbox{ Borel measurable}.$$
Then $\pi\in\Pi(\mu,\nu)$ if and only if $(P_1)_\sharp \pi=\mu$ and $(P_2)_\sharp \pi=\nu$, where $P_1$ and $P_2$ are the projections onto the first and second factors. 

For $\mu,\nu\in\mathscr{P}_p(X)$ the \emph{$p$-Wasserstein distance} $W_p:\mathscr{P}_p(X)\times\mathscr{P}_p(X)\rightarrow[0,\infty)$ is defined as
\begin{align}\label{id:pwasserstein}W_p(\mu,\nu):=\left(\inf_{\pi\in\Pi(\mu,\nu)}\int_{X^2}\met(x,y)^p\,\dint\pi(x,y)\right)^\frac{1}{p}.\end{align}
If $\pi\in\Pi(\mu,\nu)$ is a minimizer in  \eqref{id:pwasserstein}, we say that $\pi$ is $p$-optimal and write $\pi\in\Pi^\opt_p(\mu,\nu)$. The function $W_p$ is a (finite) distance on $\mathscr{P}_p(X)$ and turns the latter into a complete metric space \cite[Thm.\ 6.18]{Vil:09}. Moreover, if $(X,\met)$ is geodesic, then also $(\mathscr{P}_p(X),W_p)$ is geodesic \cite[Cor.\ 7.22]{Vil:09}. 

When $W_p(\mu,\nu)$ is finite it is known that $\pi\in\Pi(\mu,\nu)$ is optimal if and only if it is concentrated on a $\met^p$-cyclically monotone set: Let $c\colon X^2\rightarrow \R$, then  a set $\Lambda\subseteq X^2$ is \emph{$c$-cyclically monotone} if for every finite set of points $(x_i,y_i)_{i=1,\dots,N}$ in $\Lambda$ it holds that
\begin{align*}
    \sum_{i=1}^N c(x_i,y_i)\leq\sum_{i=1}^Nc(x_i,y_{i+1})\,,
\end{align*}
with the convention that $y_{N+1}:=y_1$.

The evaluation map $\e_t:\Geo(X)\rightarrow X$ for a fixed $t\in[0,1]$ is defined as
\begin{align*}
    \e_t(\gamma):=\gamma_t.
\end{align*}
A measure $\bdpi\in\mathscr{P}(\Geo(X))$ is called a \emph{$p$-optimal geodesic plan} if $(\e_0,\e_1)_\sharp \bdpi$ is a $p$-optimal coupling between $(\e_0)_\sharp \bdpi$ and $(\e_1)_\sharp \bdpi$. It follows that  the map $[0,1]\ni t\mapsto(\e_t)_\sharp \bdpi$ is a geodesic in $(\mathscr{P}_p(X),W_p)$. Vice-versa, it is known that any geodesic $(\mu_t)_{t\in[0,1]}$ can be lifted to an $p$-optimal geodesic plan $\bdpi$ so that $(\e_t)_\sharp \bdpi=\mu_t$, see for example \cite[Thm.\ 2.10]{AG:13}. We denote by $\OptGeo_p(\mu,\nu)$ the space of such optimal geodesic plans $\bdpi$ with $(\e_0)_\sharp \bdpi=\mu$ and $(\e_1)_\sharp \bdpi=\nu$.

\begin{defi}[(Essential) nonbranching]\label{De: ess non-branch}
   A subset $G\subseteq\Geo(X)$ of geodesics is called \emph{nonbranching} if for any $\gamma^1,\gamma^2\in G$ the following holds:
   \begin{align*}
       \exists t\in(0,1)\colon\gamma^1_s=\gamma^2_s\quad\forall s\in[0,t]\quad\Longrightarrow\quad\gamma_s^1=\gamma^2_s\quad\forall s\in[0,1].
   \end{align*}
   The metric measure space $(X,\met,\m)$ is said to be nonbranching if $\Geo(X)$ is nonbranching. We say that $(X,\met,\m)$ is \emph{$p$-essentially nonbranching} if for all $\mu,\nu\in\mathscr{P}_p^\ac(X)$ any $\bdpi\in\OptGeo_p(\mu,\nu)$ is concentrated on a Borel nonbranching set $G\subseteq\Geo(X)$. We call $2$-essentially nonbranching just essentially nonbranching. 
\end{defi}

We define the \emph{(Boltzmann-Shannon) relative entropy functional} ${\Ent_\m(\mu):\mathscr{P}(X)\rightarrow\R\cup\{+\infty\}}$ as
\begin{align}\label{Eq: boltzmann}
   \Ent_\m(\mu):=\begin{cases}\int_X\rho\log\rho\,\dint\m\quad&\mathrm{if}\quad\mu=\rho\m\quad\mbox{and}\quad(\rho\log\rho)^+\in L^1(X,\m),\\
   +\infty&\mbox{otherwise.}\end{cases}
\end{align}
The two following facts are well known \cite{Stu:06a}:
\begin{itemize}
   \item by Jensen's inequality, it holds that $\Ent_\m(\mu)\geq-\log\m(\supp\,\mu)>-\infty$ for every ${\mu\in\mathscr{P}_\mathrm{c}^\ac(X)}$;
   \item $\Ent_\m$ is weakly lower semicontinuous: if $\{\mu_n\}_{n\in\N}\subseteq\mathscr{P}(X)$ converges weakly  to $\mu\in\mathscr{P}(X)$ and there is a Borel subset $C\subseteq X$ with $\m(C)<\infty$ and $\supp\,\mu_n\subseteq C$ for all $n\in\N$, then
\begin{align*}
   \Ent_\m(\mu)\leq\liminf_{n\rightarrow\infty}\Ent_\m(\mu_n).
\end{align*}
\end{itemize} 

\begin{defi}[$\CD(K,\infty)$]\label{De: CD for inf K}
   Given $K\in\R$, we say that $(X,\met,\m)$ satisfies the  $\CD(K,\infty)$ condition if and only if for every $\mu_0,\mu_1\in\mathscr{P}^\ac_{2,\mathrm{c}}(X)$ such that $\Ent_\m(\mu_0), \Ent_\m(\mu_1)<\infty$ there exists $\bdpi\in\OptGeo_2(\mu_0,\mu_1)$ such that, denoting $\mu_t:=(\e_t)_\sharp \bdpi$, we have
   \begin{align}\label{Eq: CD for inf K}
       \Ent_\m(\mu_t)\leq(1-t)\Ent_\m(\mu_0)+t\Ent_\m(\mu_1)-\frac{K}{2}t(1-t) W_2(\mu_0, \mu_1)^2\,.
   \end{align}
\end{defi}

For $\kappa\in\R$ and $\theta\geq0$ let the \emph{generalized sine functions} be
\begin{equation*}
    \mathfrak{s}_\kappa(\theta):=\begin{cases}
        \frac{1}{\sqrt{\kappa}}\sin(\sqrt{\kappa}\theta)\quad&\mathrm{if}\,\kappa>0,\\
        0&\mathrm{if}\,\kappa=0,\\
        \frac{1}{\sqrt{-\kappa}}\sinh(\sqrt{-\kappa}\theta)&\mathrm{if}\,\kappa<0.
    \end{cases}
\end{equation*}
Then, for $t\in[0,1]$, we define the \emph{volume distortion coefficients} for $\kappa=\tfrac{K}{N}$ with $K\in\R$ and $N\geq1$ as
\begin{equation*}
    \sigma_{\kappa}^{(t)}(\theta):=\begin{cases}
        \tfrac{\mathfrak{s}_\kappa(t\theta)}{\mathfrak{s}_\kappa(\theta)}\quad&\mathrm{if}\,\kappa\theta^2\neq0\,\mathrm{and}\,\kappa\theta^2<\pi^2,\\
        t&\mathrm{if}\,\kappa\theta^2=0,\\
        +\infty&\mathrm{if}\,\kappa\theta^2>+\infty,
    \end{cases}
\end{equation*}
and set $\sigma_{K,N}^{(t)}(0)=t$. Define then
\begin{align*}
    \sigma_{K,N}^{(t)}(\theta):=\sigma_{\frac{K}{N}}^{(t)}(\theta), \ \ \ \ \ \ \ 
    \tau_{K,N}^{(t)}(\theta):=(t\cdot\sigma_{K,N-1}^{(t)}(\theta)^{N-1})^{\frac{1}{N}}.
\end{align*}
When $N=1$ we set $\smash{\tau_{K,1}^{(t)}(\theta)=t}$ if $K\leq0$ and $\smash{\tau_{K,1}^{(t)}(\theta)=+\infty}$ if $K>0$. Note that for every $t\in(0,1)$ and every $\theta>0$, $\smash{\sigma^{(t)}_{K,N}}$ is continuous in $(K,N)\in\R\times[1,\infty)$, nondecreasing in $K$ and nonincreasing in $N$ \cite[Rem.\ 2.2]{BS:10}. Analogous
claims apply to the quantity $\smash{\tau_{K,N}^{(t)}(\theta)}$. Furthermore, for every $t\in[0,1]$,
every $\theta\geq0$, and every $\kappa\in(-\infty,\pi^2/\theta^2)$,
$$\sigma_\kappa^{(t)}(\theta)=\sigma_{\kappa\theta^2}^{(t)}(1).$$

The \emph{Rényi relative $N$-entropy} $S_N: \mathscr{P}(X)\rightarrow (-\infty, 0]$ on a metric measure space $(X, \met, \m)$ is defined as
$$ S_N(\mu|\m)= - \int_X \rho^{-\frac{1}{N}} \dint \mu  \mbox{ where } \mu= \rho \dint \m + \mu^\perp,$$
where $\mu^\perp \perp \m$. 
The two following facts are well known \cite{Stu:06b, gsm15}:
\begin{itemize}
   \item By Jensen's inequality, it holds that $S_N(\mu|\m)\geq-\m(\supp\,\mu)^{\frac{1}{N}}$ for every $\mu\in\mathscr{P}_\mathrm{c}(X,\m)$.  
    \item $S_N$ is  weakly lower semicontinuous: if $\{\mu_n\}_{n\in\N}\subseteq\mathscr{P}(X)$ converges weakly  to $\mu\in\mathscr{P}(X)$ and there is a Borel subset $C\subseteq X$ with $\m(C)<\infty$ and $\supp\,\mu_n\subseteq C$ for all $n\in\N$, then
\begin{align*}
S_N(\mu|\m)\leq\liminf_{n\rightarrow\infty}S_N(\mu_n|\m).
\end{align*}
\end{itemize}

We can now recall the definition of synthetic Ricci curvature-dimension bounds, introduced by Sturm \cite{Stu:06a, Stu:06b} and Lott--Villani \cite{LV:09} for $p=2$. The case for general $p$ is studied in \cite{Kel:17}. The reduced curvature dimension condition for $p=2$ was introduced later in \cite{BS:10}.

\begin{defi}[$\CD_p(K,N)$ and $\CD^*_p(K,N)$]\label{De:CD and CDstar}
    Given real numbers $K\in\R$ and $N\geq1$, we say that a metric measure space $(X,\met,\m)$ satisfies the \emph{curvature-dimension condition} $\CD_p(K,N)$ if for every $\mu_0,\mu_1\in\mathscr{P}_{p,\mathrm{c}}(X,\m)$ there exists $\bdpi\in\OptGeo_p(\mu_0,\mu_1)$ so that for all $t\in[0,1]$, $\mu_t:=(\e_t)_\sharp \bdpi\ll\m$ and for all $N'\geq N$ it holds that
    \begin{equation}
        \begin{aligned}\label{Eq:CD}
            %\int_X\rho_t^{1-\frac{1}{N'}}\,\dint\m
            S_{N'}(\mu_t|\m)\leq-\int_{X^2}\Big[\tau_{K,N'}^{(1-t)}(&\met(x_0,x_1))\rho_0(x_0)^{-\frac{1}{N'}}+\tau_{K,N'}^{(t)}(\met(x_0,x_1))\rho_1(x_1)^{-\frac{1}{N'}}\Big]\,\dint\pi(x_0,x_1),
        \end{aligned}
    \end{equation}
    where $\pi=(\e_0,\e_1)_\sharp \bdpi$ and $\mu_i=\rho_i\m$, $i=0,1$. 

    If \eqref{Eq:CD} holds with the coefficients $\sigma^{(t)}_{K,N'}(\theta)$ in place of \smash{$\tau^{(t)}_{K,N'}(\theta)$}, we say that $(X,\met,\m)$ satisfies the \emph{reduced curvature-dimension condition} $\CD_p^*(K,N)$.
\end{defi}

\begin{notation}[Suppressing $p$]\label{Not: CDp}
    The condition $\CD_p(K,N)$ is independent of $p\in[1,\infty)$ thanks to \cite{ACMcCCF:21}, so we will notationally suppress the subscript $p$ everywhere in this case, and work with  $p=2$.
\end{notation}
The measure contraction property was introduced independently by Ohta \cite{Oht:07} and Sturm \cite{Stu:06a, Stu:06b} (see also \cite{kush01}).
We will make use of the version from \cite{Oht:07}.

\begin{defi}[$\mcp^O(K,N)$]\label{De: MCP}
    A metric measure space is said to satisfy the \emph{measure contraction property (in the sense of Ohta)} $\mcp^O(K,N)$ for $K\in\R$ and $N\geq1$ if for every $o\in\supp\,\m$ and $\mu_0\in\mathscr{P}(X)$ of the form $\mu_0=\frac{1}{\m(A)}\m\llcorner A$ for some Borel set $A\subseteq X$ with $0<\m(A)<+\infty$ there exists $\bdpi\in\OptGeo_p(\mu_0,\delta_o)$ such that
    \begin{align}\label{Eq: MCPO}
        \frac{1}{\m(A)}\m\geq(\e_t)_\sharp\left(\tau_{K,N}^{(1-t)}(\met(\gamma_0,\gamma_1))^N\bdpi(\dint\gamma)\right)\qquad\forall t\in[0,1].
    \end{align}
\end{defi}

\begin{rem}[Relations among the curvature-dimension conditions]\label{Rem: Cd rel}
Here we collect some useful properties of the curvature-dimension conditions that we will need later on.
\begin{itemize}
    \item[(i)]\label{Rem: Cd rel 1}\textbf{(Globalization)} Since in general $\tau_{K,N}^{(t)}(\theta)\geq\sigma_{K,N}^{(t)}(\theta)$, the condition $\CD(K,N)$ always implies $\CD^*(K,N)$. The latter is equivalent to its local version $\CD^*_\loc(K',N)$ for all $K'<K$ thanks to \cite[Thm.\ 5.1]{BS:10}. But then due to \cite{CM:21} $\CD(K,N)$ for $N>1$ can be globalized so there is no necessity to define any local curvature-dimension condition. The result for the case $K=\infty$ was previously already known \cite{Stu:06a}. The case $N=1$ was excluded to avoid pathological behaviours,
    %. For example, $\CD^*(K,1)$ does not imply $\CD_\loc(K,1)$ for $K<0$: the metric measure space $(X,\met,\m)=([0,1],\vert\cdot\vert,\sinh(\cdot)\,\mathcal{L}^1)$ satisfies $\CD^*(-1,1)$ but not $\CD_\loc(-1,1)$,
    cf. \cite[Rem.\ 2.4]{CM:17a}.


    \item[(ii)]\label{Rem: Cd rel 2}\textbf{($\CD(K,N)$ and $\CD(K,\infty)$)} If $(X,\met,\m)$ satisfies $\CD(K,N)$ then it satisfies also $\CD(K,\infty)$ by taking the limit as $N\rightarrow\infty$, cf. \cite[Prop.\ 1.6 (ii)]{Stu:06b}.% for the case $p=2$.

    \item[(iii)]\label{Rem: Cd rel 3}\textbf{($\CD$ and $\mcp^O$)} It is known thanks to \cite{Raj:12} that 
    \begin{align*}
        \CD(K,N)\quad\Rightarrow\quad\mcp^O(K,N)
    \end{align*}
    but the converse is in general false \cite{Stu:06b}.
    %as it is the case in sub-Riemannian geometry \cite{} or even weighted Riemannian manifolds.

    \item[(iv)]\label{Rem: Cd rel 5}\textbf{(Equivalent pointwise inequality)} If $(X,\met,\m)$ is also essentially nonbranching, thanks to \cite[Prop. 9.1]{CM:21} $\CD(K,N)$ is equivalent to the following pointwise inequality, which holds for $\bdpi$-a.e.\ $\gamma$ (retaining the notation of \eqref{Eq:CD}):
    \begin{align}\label{Eq: CD pointwise}
        \rho_t(\gamma_t)^{-\frac{1}{N}}\geq\tau_{K,N}^{(1-t)}(\met(\gamma_0,\gamma_1))\rho_0(\gamma_0)^{-\frac{1}{N}}+\tau_{K,N}^{(t)}(\met(\gamma_0,\gamma_1))\rho_1(\gamma_1)^{-\frac{1}{N}}.
    \end{align}
    \item[(v)]\label{Rem: Cd rel 4}\textbf{($\mcp^O$ and the smooth case)} Notice that if $X$ is a smooth Riemannian manifold with smooth metric tensor $g$, it is not true that $\mcp^O(K,N)$ implies $\Ric_g\geq K$ unless $N=\dim X$, cf. \cite[Cor.\ 5.5 (ii) and Rem.\ 5.6]{Stu:06b}.

\end{itemize}
\end{rem}
\subsubsection{Lorentzian (pre-)length spaces}
{\LpLSn s are  Lorentzian analogues of metric spaces, while \LLSn s are analogues of metric length spaces. They have been introduced in \cite{KS:18} (after earlier works of Busemann \cite{Bus:67} and Kronheimer--Penrose \cite{KP:67}). There are different variants of the basic axiomatization of these spaces, cf.\ \cite{McC:24, BMcC:23, BBCGMORS:24, MS:25} (and approaches \cite{SV:16, SS:24} based on the null distance and the bounded Lorentzian metric spaces \cite{MS:24, BMS:24}). We opted for sticking to the original setting of \cite{KS:18} as, for example, the topological and metric structure of the underlying space is always given by the cone or product structure.}
\smallskip

Given a set $Y$ we call the triple $(Y,\ll, \leq)$ a \emph{causal space} where $\leq$ is a pre-order, i.e., a reflexive and transitive relation, and $\ll$ is a transitive relation contained in $\leq$ \cite[Def.\ 2.1]{KS:18}. We write $x<y$ when $x\leq y$ and $x\neq y$. We say $x$ and $y$ are \emph{timelike} (resp.\ \emph{causally}) \emph{related} if $x\ll y$ (resp.\ $x\leq y$). 

For $A\subseteq Y$ we define the \emph{chronological} and \emph{causal future} of $A$ as
\begin{align}
&I^+(A):=\{y'\in Y\colon\exists y\in A, y\ll y'\}\,,\qquad  J^+(A):=\{y'\in Y\colon\exists y\in A, y\leq y'\}\,,
\end{align}
respectively. Analogously we define the chronological $I^-(A)$ and the causal past $J^-(A)$ of $A$. In the case $A=\{y\}$ for $y\in Y$ we will write $I^+(x):= I^+(\{x\})$ and $J^+(x)=J^+(\{x\})$. 
%We define the chronological and causal future and past of a point as
%\begin{align}
%&I^+(y):=\{y'\in Y: y\ll y'\}\,,\qquad  I^-(y):=\{y'\in Y: y'\ll y\}\,,\\
%&J^+(y):=\{y'\in Y: y\leq y'\}\,,\qquad  J^-(y):=\{y'\in Y: y'\leq y\}\,,
%\end{align}
%and similar for subsets $A\subseteq Y$ as
%\begin{align}
%&I^\pm(A):=\bigcup_{a\in A} I^\pm(a)\,,\qquad  J^\pm(A):=\bigcup_{a\in A}J^\pm(a)\,,
%\end{align}
The \emph{chronological} and \emph{causal emeralds}  of $A,B\subseteq Y$ are defined as
\begin{align}
&I(A,B):=I^+(A)\cap I^-(B)\,,\qquad J(A,B):=J^+(A)\cap J^-(B)\,.
\end{align}
Moreover, for notational clarity, we define the subsets of timelike (resp.\ causal) pairs as
$$Y^2_{\ll} =\{(x,y)\in Y^2: x\ll y\}\,,\qquad Y^2_{\leq}= \{(x,y)\in Y^2 : x\leq y\}.$$

\begin{defi}[Lorentzian pre-length space {\cite[Def.\ 2.8]{KS:18}}]\label{Def: LpLS}
A \emph{Lorentzian pre-length space} $(Y, \met, \ll, \leq, \uptau)$ is a causal space $(Y, \ll, \leq)$  equipped  with a (proper) metric $\met$ and a lower semi-continuous function $\uptau: Y^2 \rightarrow [0,\infty]$ called \emph{time separation function} that satisfies for all ${x,y, z\in Y}$ 
\begin{itemize}
    \item $\uptau(x,y)=0$ if $x\nleq y$, 
    \item $\uptau(x,y)>0$ if and only if $x\ll y$, 
    \item $\uptau(x,z)\geq \uptau(x,y)+ \uptau(y,z)$ if $x\leq y\leq z$.
\end{itemize}
The set $Y$ is endowed with the metric topology induced by $\met$. The lower semi-continuity of $\uptau$ implies that $I^{\pm}(x)$ is open for all $x\in Y$. We also refer to the function $\uptau(x,\cdot)$ \textnormal{(}and $\uptau(\cdot,y)$\textnormal{)} as
\emph{Lorentzian distance} from a fixed point $x\in Y$ \textnormal{(}to a fixed point $y\in Y$\textnormal{)}.
\end{defi}
If $I\subseteq\R$ is an interval, a curve $\gamma:I\rightarrow Y$ is called (future-directed) timelike (resp.\ causal) if $\gamma$ is locally Lipschitz continuous (w.r.t.\ $\met$) and if for all $s\leq t\in I$, it holds $\gamma(s)\ll \gamma(t)$ (resp.\ $\gamma(s)\leq \gamma(t)$). We say that $\gamma$ is a null
curve if, in addition to being causal, no two points on $\gamma(I)$ are timelike related.

The ($\uptau$-)length $L_\uptau(\gamma)$ of a (future directed) causal curve $\gamma\colon[a,b]\rightarrow Y$ is defined via the time separation function, in analogy to the theory of length metric spaces \cite{KS:18}, i.e.,
\begin{equation*}
    L_\uptau(\gamma):=\inf \left\{\sum_{i=0}^{N-1} \uptau(\gamma(t_i),\gamma(t_{i+1})): N\in\N,\, a=t_0 < t_1 < \ldots < t_N=b\right\}\,.
\end{equation*}
Under natural assumptions, these definitions coincide with the classical ones in the smooth setting \cite{KS:18}.

A future-directed causal curve $\gamma:[a,b]\rightarrow Y$ is called \emph{maximal} (or a \emph{maximizer}) if its length realizes the time separation function between $\gamma(a)$ and $\gamma(b)$, i.e., $L_\uptau(\gamma)= \uptau(\gamma(a), \gamma(b))$. 
A curve $\gamma:[0,1]\rightarrow Y$ will be called
a (causal) \emph{geodesic} if it is maximal and continuous when parametrized proportional by $\uptau$-arc-length. In other words, the set of (causal) geodesics is
$$\Geo(Y)= \{\gamma\in {C}([0,1], Y): \uptau(\gamma(s), \gamma(t))= (t-s)\uptau(\gamma(0), \gamma(1)), \forall s< t\}.$$
Its subset of timelike geodesics is defined as 
$$\TGeo(Y)= \{\gamma\in \Geo(Y): \uptau(\gamma(0), \gamma(1))>0\}.$$

   A subset $G\subseteq\TGeo(X)$  is called \emph{forward timelike nonbranching} if for any $\gamma^1,\gamma^2\in G$ the following holds:
   \begin{align*}
       \exists t\in(0,1)\colon\gamma^1_s=\gamma^2_s\quad\forall s\in[0,t]\quad\Longrightarrow\quad\gamma_s^1=\gamma^2_s\quad\forall s\in[0,1].
   \end{align*}
If $G=\TGeo(Y)$ is forward timelike nonbranching, then we say the Lorentzian pre-length space $(Y,\met, \ll, \leq, \uptau)$ is forward timelike nonbranching. Similarly, one defines \emph{backward timelike nonbranching}, and we just call the Lorentzian pre-length space \emph{timelike nonbranching} if it is forward and backward timelike nonbranching.

Our main results will only deal with \emph{Lorentzian geodesic spaces}. We will use the streamlined definition of \cite[Subsec.\ 1.1]{CM:24a}.
\begin{defi}[Lorentzian geodesic space] A Lorentzian pre-length space $(Y,\met, \ll, \leq, \uptau)$ is termed \emph{Lorentzian geodesic space} if additionally it is: 
\begin{itemize}
\item \emph{$\met$-compatible:} every $x\in Y$ admits a neighbourhood $U$ and a constant $C$ such that $L_{\met}(\gamma)\leq C$ for every future or past directed causal curve $\gamma$ contained in $U$;
\item  \emph{geodesic:} for all $x,y\in Y$ with $x<y$ there is a {\it maximal} future-directed causal curve $\gamma$ from $x$ to $y$, i.e.,  $\uptau(x,y)= L_{\uptau}(\gamma)$.
\end{itemize}
In particular, a Lorentzian geodesic space is \emph{(strictly) intrinsic}, i.e.,
\begin{equation*}
    \uptau(x,y) = \sup\{L_\uptau(\gamma): \gamma \text{ future directed causal curve from } x \text{ to } y\}\,,
\end{equation*}
and it is a \LLS if it is additionally locally causally closed, $I^\pm(x)\neq\emptyset$ for all $x\in Y$ and timelike path connected, see  \cite[Def.\ 3.22]{KS:18}. 
\end{defi}

We consider the following version of global hyperbolicity that is consistent with the previous literature \cite[Cor.\ 3.8]{Min:23}. 
A Lorentzian geodesic space $(Y,\met, \ll, \leq,\tau)$ is called
\begin{itemize}
\item \emph{causal}: if $\leq$  is also antisymmetric, i.e., $\leq$ is an order; 
\item \emph{globally hyperbolic}: if it is causal and for every $K_1, K_2\subseteq Y$ compact, the \emph{causal emerald} $J^{+}(K_1)\cap J^{-}(K_2)$ is compact in $Y$.
\end{itemize}

From \cite[Thm.\ 3.7]{Min:23} this definition of global hyperbolicity is equivalent with the one adopted in \cite{KS:18} (i.e., non-total imprisonment and compactness of causal diamonds). 
Global hyperbolicity implies that the relation $\leq$ is a closed subset of $Y\times Y$.
It was proved in \cite[Thm.\ 3.28]{KS:18} that for a globally hyperbolic  Lorentzian length space $(Y,\met, \ll, \leq,\uptau)$, the time-separation function $\uptau$ is finite and continuous: in particular, for maximal causal curve there exists a constant $\uptau$-speed parametrizations, thus any two distinct causally related points are joined by a causal geodesic, hence the space is a Lorentzian geodesic space. Finally, let us emphasize that for the setting of this article (i.e., generalized cones, see Subsection \ref{subsec-con-ms}) there are no differences: Every generalized cone over a locally compact and complete length metric space $(X,\met)$ is a globally hyperbolic \LLS \cite[Cor.\ 4.11]{AGKS:23}, hence a Lorentzian geodesic space.

\subsubsection{Timelike curvature-dimensions conditions for Lorentzian spaces}
Let $(X,\met,\ll,\leq,\uptau)$ be a {globally hyperbolic}  {\it geodesic} Lorentzian space. 

Given $\mu, \nu\in \mathscr{P}(X)$ we define \emph{chronological} and \emph{causal} couplings: the sets $\Pi_\ll(\mu,\nu)$ and $\Pi_\leq(\mu,\nu)$, respectively, are the sets of $\pi\in\Pi(\mu,\nu)$ such that $\pi(X^2_\ll)=1$ and $\pi(X^2_\leq)=1$, respectively.

Similarly to the non-Lorentzian case, one defines a notion of ``Lorentzian distance'' between probability measures: fixed $p\in(0,1)$, the \emph{$p$-Lorentz-Wasserstein distance} \cite{EM:17} $\ell_p$ of $\mu,\nu\in\mathscr{P}(X)$ is
\begin{align}\label{Eq:ellq}
    \ell_p(\mu,\nu) :=  \left[\!\sup_{\pi\in \Pi_{}(\mu,\nu)}\int_{M\times M} \ell(x,y)^p\,\dint \pi(x,y)\right]^\frac{1}{p}
     =\left[\!\sup_{\pi\in \Pi_{\leq}(\mu,\nu)}\int_{M\times M} \uptau(x,y)^p\,\dint \pi(x,y)\right]^\frac{1}{p}
\end{align}
where $\sup\emptyset=-\infty$ and $\ell:X^2\rightarrow[0,\infty]\cup\{-\infty\}$ is defined by
\begin{align*}
    \ell(x,y):=\begin{cases}
        \uptau(x,y)\quad&\mbox{if } x\leq y,\\
        -\infty&\mbox{otherwise}.
        \end{cases}
\end{align*}

The $p$-Lorentz-Wasserstein distance is interpreted as a sort of time separation on $\mathscr{P}(X)$ since it satisfies the reverse triangle inequality (\cite[Thm.\ 13(ii)]{EM:17}, \cite[Prop.\ 2.5]{CM:24a}). We call  a maximizing $\pi\in\Pi_\leq(\mu,\nu)$ \emph{optimal} and write $\pi\in\Pi^{p,\opt}_\leq(\mu,\nu)$.  If $(X, \met, \ll, \leq , \uptau)$ is a globally hyperbolic geodesic Lorentzian space and $\mu,\nu\in\mathscr{P}_\mathrm{c}(X)$ (satisfying an integrability condition) with $\Pi_\leq(\mu,\nu)\neq\emptyset$, then $\smash{\Pi^{p, \opt}_{\leq}(\mu, \nu)\neq \emptyset}$ \cite[Prop.\ 2.3]{CM:24a}.

We call a pair $\mu,\nu\in\mathscr{P}_\mathrm{c}(X)$ \emph{timelike $p$-dualizable} if the class
\begin{align*}
    \left\{\pi\in\Pi_\leq(\mu,\nu):\pi\mbox{ is }\ell_p\mbox{-optimal}\right\}\cap\Pi_\ll(\mu,\nu)
\end{align*} is non-empty, 
and in this case we say that such an element $\pi$ \emph{$p$-dualizes} $(\mu,\nu)$. Notice that if for $\mu,\nu\in\mathscr{P}_\mathrm{c}(X)$ it holds that $\supp\,\mu\times\supp\,\nu\subseteq X^2_\ll$ then the pair $(\mu,\nu)$ is timelike $p$-dualizable also in the following stronger sense \cite[Def.\ 2.27, Cor.\ 2.29]{CM:24a}.  We say that $(\mu,\nu)\in\mathscr{P}(X)$ is \emph{strongly timelike $p$-dualizable by} $\pi\in\Pi_\ll(\mu,\nu)$ if the pair $(\mu,\nu)$ is timelike $p$-dualizable by $\pi$, and there is an $\ell^p$-cyclically monotone Borel set $\Gamma\subseteq X^2_\ll\cap(\supp\mu\times\supp\nu)$ such that every given $\sigma\in\Pi_\leq(\mu,\nu)$ is $p$-optimal if and only if $\sigma(\Gamma)=1$ (in particular, $\sigma$ is chronological). Similarly, in this case we say that such a $\pi$ \emph{strongly $p$-dualizes} $(\mu,\nu)$. {Here, an \emph{$\ell^p$-cyclically monotone set}, is a set $\Lambda\subseteq X^2_\leq$ such that for every finite set of points $(x_i,y_i)_{i=1,\ldots,N}$ in $\Lambda$  it holds that
\begin{equation*}
    \sum_{i=1}^N \ell^p(x_i,y_i) \geq \sum_{i=1}^N\ell^p(x_{i+1},y_i)\,,
\end{equation*}
with the convention that $x_{N+1}:=x_1$.
}

A curve $(\mu_t)_{t\in[0,1]}\subseteq\mathscr{P}(X)$ is called \emph{timelike (proper-time parametrized) $\ell_p$-geodesic} if there exists a $\bdpi\in\mathscr{P}(\TGeo(X))$ with $(\e_0,\e_1)_\sharp \bdpi$ optimal and $(\e_0,\e_1)_\sharp \bdpi(X^2_\ll)=1$ such that
$$\mu_t=(\e_t)_\sharp \bdpi\qquad\forall t\in[0,1].$$
We call such $\bdpi$ a \emph{timelike $p$-optimal geodesic plan} and write $\bdpi\in\OptTGeo_p(\mu,\nu)$.


We call $(Y, \met, \m, \ll, \leq , \uptau)$ a \emph{measured Lorentzian geodesic space} if $(Y, \met, \ll, \leq , \uptau)$ is a Lorentzian geodesic space and $\m$ is a Radon measure on $X$. 

The following definition is the Lorentzian analogue of Definition \ref{De: ess non-branch}.
\begin{defi}[Timelike $p$-essential nonbranching]
   We say that $(X,\met,\m, \ll, \leq , \uptau)$ is \emph{timelike $p$-essentially nonbranching} if for all $\mu,\nu\in\mathscr{P}_p(X, \m)$ and every $\bdpi\in \OptTGeo_p(\mu,\nu)$ is induced by an $\ell_p$-geodesic that is concentrated on a Borel timelike nonbranching set $G\subseteq \TGeo(X)$.
\end{defi}
\begin{rem}[{\cite{CM:24a,Bra:23b}}]\label{Re:reparametrizations}
    The elements of $\TGeo(X)$ are $\uptau$-arclength parametrized, i.e.,  $\gamma\in\TGeo(X)$ satisfies
    \begin{align*}
        \uptau(\gamma_s,\gamma_t)=(t-s)\,\uptau(\gamma_0,\gamma_1)\qquad\forall s,t\in[0,1],\quad s<t.
    \end{align*}
    As a consequence of this and the reverse triangle inequality, every timelike $\ell_p$-geodesic $(\mu_t)_{t\in[0,1]}$ with $\ell_p(\mu_0,\mu_1)<\infty$ similarly satisfies
    \begin{align*}
        \ell_p(\mu_s,\mu_t)=(t-s)\,\ell_p(\mu_0,\mu_1)\qquad\forall s,t\in[0,1],\quad s<t.
    \end{align*}
\end{rem}
Though we only use it in the context of measured Lorentzian geodesic spaces, the following definition makes sense in the context measured Lorentzian pre-length spaces.
\begin{defi}[Timelike curvature-dimension conditions]\label{Def: TCD}
    Fix $p\in(0,1)$ and let $K\in\R$ and $N\geq1$.  A measured Lorentzian pre-length space $(X, \met, \m, \ll, \leq , \uptau)$ satisfies the \emph{timelike curvature-dimension condition} $\tCD_p(K,N)$ if for every timelike $p$-dualizable pair $(\mu_0,\mu_1)=(\rho_0\,\m,\rho_1\,\m)\in\mathscr{P}_\mathrm{c}(X,\m)$ there exists $\bdpi\in\OptTGeo_p(\mu_0,\mu_1)$ such that for all $t\in[0,1]$ and $N'\geq N$ we have
    \begin{equation}
        \begin{aligned}\label{Eq:TCD}
           S_{N'}(\mu|\m)\leq -\int_{X\times X}\Big[\tau_{K,N'}^{(1-t)}(&\met(x_0,x_1))\rho_0(x_0)^{-\frac{1}{N'}}+\tau_{K,N'}^{(t)}(\met(x_0,x_1))\rho_1(x_1)^{-\frac{1}{N'}}\Big]\,\dint\pi(x_0,x_1),
        \end{aligned}
    \end{equation}
    where $\pi=(\e_0,\e_1)_\sharp \bdpi$ and $\mu_i=\rho_i\m$, $i=0,1$. 

    If \eqref{Eq:TCD} holds with the coefficients $\sigma^{(t)}_{K,N'}(\theta)$ in place of \smash{$\tau^{(t)}_{K,N'}(\theta)$}, we say that $X$ satisfies the \emph{reduced timelike curvature-dimension condition} $\tCD^*_p(K,N)$.

    If the previous statements hold for every strongly timelike $p$-dualizable $(\mu_0,\mu_1)\in\mathscr{P}_\mathrm{c}(X, \m)^2$, we say that $X$ obeys the \emph{weak timelike curvature-dimension condition} $\wTCD_p(K,N)$ and the \emph{weak reduced timelike curvature-dimension condition} $\wTCD^*_p(K,N)$ respectively.
\end{defi}

Notice in the definition above the dependence on the transport exponent $p\in(0,1)$. It is  conjectured that the condition $\tCD_p(K,N)$  is independent of $p$, as it is for $\CD(K,N)$ (see \Cref{Not: CDp}).

Next, we introduce the timelike measure contraction properties. The idea behind is the same as in the metric case: one of the two measures in the definition of $\tCD_p(K,N)$ becomes a Dirac measure at a point that in this case is causally related to the support of the other measure. Again, since the only optimal coupling is the product measure, this notion does not depend on the transport exponent $p$.

\begin{defi}[Timelike measure-contraction properties]\label{Def: TMCP}
    Fix $p\in(0,1)$, let $K\in\R$ and $N\geq1$. We say that $(X, \met, \m, \ll, \leq, \uptau)$ satisfies the \emph{future timelike measure contraction property} $\tmcp^+(K,N)$ if for every $\mu_0=\rho_0\,\m\in\mathscr{P}^\ac_c(X)$ and every $x_1\in X$ with $\mu_0(I^-(x_1))=1$ there exists a timelike $\ell_p$-geodesic $(\mu_t)_{t\in[0,1]}$ from $\mu_0$ to $\mu_1:=\delta_{x_1}$ such that for all $t\in[0,1]$ and $N'\geq N$ we have
    \begin{equation}
        \begin{aligned}\label{Eq:TMCP+}
            \int_X\rho_t^{1-\frac{1}{N'}}\,\dint\m\geq\int_{X^2}\tau_{K,N'}^{(1-t)}(\uptau(x,x_1))\rho_0(x^0)^{-\frac{1}{N'}}\,\dint\mu(x),
        \end{aligned}
    \end{equation}
    where $\pi=(\e_0,\e_1)_\sharp \bdpi$ and $\mu_i=\rho_i\m$, $i=0,1$.

    We say that $X$ satisfies the \emph{past} $\tmcp^-(K,N)$ if \eqref{Eq:TMCP+} holds with $\mu_1=\rho_1\,\m$ and $\mu_0=\delta_{x_0}$ for some $x_0\in X$ with $\mu_1(I^+(x_0))=1$, i.e.,
      \begin{equation}
        \begin{aligned}\label{Eq:TMCP-}
            \int_X\rho_t^{1-\frac{1}{N'}}\,\dint\m\geq\int_{X^2}\tau_{K,N'}^{(t)}(\uptau(x_0,x))\rho_1(x)^{-\frac{1}{N'}}\,\dint\mu(x).
        \end{aligned}
    \end{equation}

     Finally, we say that $X$ satisfies $\tmcp(K,N)$ if it satisfies both the conditions $\tmcp^+(K,N)$ and $\tmcp^-(K,N)$.

     If the same statements hold with the coefficients $\smash{\sigma_{K,N}^{(t)}(\theta)}$ in place of $\smash{\tau_{K,N}^{(t)}(\theta)}$, we just put a prefix \emph{reduced} to the respective properties $\smash{\tmcp^{*,\pm}(K,N)}$ and $\tmcp^*(K,N)$.
\end{defi}

\begin{rem}[Relations among the timelike curvature-dimension conditions]\label{Rem: TCD rel}
    As in the case of $\CD(K,N)$, we collect some properties of its timelike counterpart:
    \begin{itemize}
        \item [(i)]\label{Rem: TCD rel 1}\textbf{(Globalization)} Under strong assumptions, the condition $\wTCD^*_{p,\loc}(K,N)$ is equivalent to $\wTCD^*_p(K,N)$, see \cite[Thm.\ 3.45]{Bra:23b} for details. The same statement for $\wTCD_p$ is not known at the moment.
        \item[(ii)] \textbf{($\wTCD_p(K,N)$ and $\wTCD_p(K, \infty)$)}
    Combining \cite[Prop.\ 3.6 (i) and Cor.\ 3.10]{Bra:23b} and \cite[Rem.\ 4.2]{Bra:23a} we have that $\wTCD_p(K,N)$ implies $\wTCD_p(K,\infty)$ in the sense of \cite[Def.\ 4.1]{Bra:23a} which is the Lorentzian version of \Cref{De: CD for inf K}. More precisely, for every pair $\mu_0, \mu_1 \in \mathscr{P}^\ac_c(X)$ with $\Ent_\m(\mu_0), \Ent_\m(\mu_1)<\infty$ that is strongly timelike $p$-dualizable there exists a timelike $p$-dualizing $\pi \in \Pi_{\ll}(\mu_0, \mu_1)$ and a timelike $\ell_p$-geodesic $(\mu_t)_{t\in [0,1]}$ such that for every $t\in [0,1]$
    $$\Ent_\m(\mu_t)\leq (1-t)\Ent_m(\mu_0)+ t\Ent_m(\mu_1) + \frac{K}{2}t(1-t) \left\| \tau\right\|_{L^2(\pi)}^2.$$

        \item[(iii)]\label{Rem: TCD rel 2}\textbf{($\wTCD_p$ and $\tmcp$)} The condition $\wTCD_p(K,N)$ implies $\tmcp(K,N)$ and the same holds true for its reduced version, cf.\ \cite[Prop.\ 4.9]{Bra:23b}.

        \item[(iv)]\label{Rem: TCD rel 3}\textbf{(Equivalent pointwise inequality)} If $(X,\met,\ll,\leq,\uptau,\m)$ is also timelike essentially nonbranching, thanks to \cite[Thm.\ 3.41]{Bra:23b} $\tCD_p(K,N)$ and $\wTCD_p(K,N)$ are equivalent to the following pointwise inequality,  for $\bdpi$-a.e.\ $\gamma$ (retaining the notation of \eqref{Eq:TCD}):
        \begin{align}\label{Eq: TCD pointwise}
            \rho_t(\gamma_t)^{-\frac{1}{N}}\geq\tau_{K,N}^{(1-t)}(\uptau(\gamma_0,\gamma_1))\rho_0(\gamma_0)^{-\frac{1}{N}}+\tau_{K,N}^{(t)}(\uptau(\gamma_0,\gamma_1))\rho_1(\gamma_1)^{-\frac{1}{N}}.
        \end{align}
        Evident adaptations hold for $\wTCD^*(K,N)$ and for $\tmcp(K,N)$ and their variants \cite{Bra:23b}.
    \end{itemize}
\end{rem}

\begin{rem}[$\tmcp$ and $\tmcp^e$]\label{rem:entropicmcp} Under the assumption of $p$-essentially nonbranching, the measure contraction property $\tmcp^+$ also implies the entropic measure contraction property $\tmcp^e$ of \cite{CM:24a}.  In particular, by \cite[Prop.\ 3.19]{CM:24a}, it follows for every pair $(\mu_0, \mu_1)\in \mathscr P_c(X)\times \mathscr P_c(X)$ of timelike $p$-dualizable measures there exists $\pi \in \Pi_{\leq}^{p, \opt}(\mu_0, \mu_1)$  that 
$$U_N(\mu_t)\geq \sigma_{K,N}^{(t)}(\left\|\pi\right\|_{L^2(\pi)})U_N(\mu_0).$$
In particular, if $\mu_0= \m(A_0)^{-1} \m|_{A_0}$ for a set $A_0$ of positive measure, by Jensen's inequality one has 
$$\m(A_t)^{\frac{1}{N}}\geq \sigma_{K,N}^{(t)}(\left\|\pi\right\|_{L^2(\pi)}) \m(A_0)^{\frac{1}{N}}.$$
\end{rem}    

\subsubsection{Weighted Lorentzian manifolds and the Bakry--\'Emery condition}
Let $(M,g)$ be a smooth Lorentzian spacetime of dimension $n\in \N_{\geq 2}$, i.e.,  a smooth, connected, time-oriented Lorentzian manifold. For this subsubsection we choose the signature convention to be $(+, -, \dots, -)$, but later it will be $(-,+,+,\ldots,+)$, see Remark \ref{rem-sign-conv} below. Also, we assume $(M,g)$ is globally hyperbolic. 
\smallskip

For $N>n$ and $\Phi\in C^\infty(M)$ we define the Bakry--\'Emery $N$-Ricci tensor as 
\begin{align}
\Ric^{\Phi, N}_g= \Ric_g-\nabla^2 \Phi - \frac{1}{N-n} \dint\Phi \otimes \dint\Phi = \Ric_g - (N-n)\frac{\nabla^2 e^{\frac{1}{N-n}\Phi}}{e^{\frac{1}{N-n}\Phi}}.
\end{align}
Here $\nabla^2 \Phi$ is the Hessian form w.r.t.\ $g$ of $\Phi$. If $N=n$, we set 
\begin{align}\Ric_g^{N, \Phi}(v,v)= \begin{cases} \Ric_g(v,v)- \nabla^2 \Phi(v,v) & \mbox{ if } \langle \nabla \Phi, v\rangle =0,\\
-\infty & \mbox{ otherwise.}
\end{cases}
\end{align}
\begin{thm}\label{thm:smoothcd} Let $p\in (0,1)$, $K\in \R$ and $N\in [n, \infty)$. The following statements are equivalent. 
\begin{itemize}
\item[(i)] $\Ric_g^{N, \Phi}\geq Kg$, i.e., $\Ric_g^{N, \Phi}(v,v)\geq Kg(v,v)$ for every timelike vector $v\in TM$.
\item[(ii)] The condition $\tCD_{p}(K,N)$ holds {(w.r.t.\ the reference measure $\m= e^\Phi\,\vol_g$).}
\end{itemize}
Moreover, if $\Ric_g\geq K$ on timelike vectors and $h= e^{\Phi}$ is measurable and satisfies
\begin{align*}
h^{\frac{1}{N}} \circ \gamma(t) \geq \sigma_{K'/N}^{(1-t)}(\tau(\gamma(0), \gamma(1))) h^\frac{1}{N}\circ \gamma(0)+  \sigma_{K'/N}^{(t)}(\tau(\gamma(0), \gamma(1))) h^\frac{1}{N}\circ \gamma(1)
\end{align*} 
for each timelike, constant-speed geodesic $\gamma: [0,1]\rightarrow M$, then $(M,\met,\leq,\ll,\uptau, e^\Phi\mathrm{vol}_g)$ satisfies  $\tCD_{p}(K+K', N+n)$. 
\begin{rem}\label{rem-sign-conv} We recall that 
$\Ric_g(v,v)= \sum_{i=1}^n \epsilon_i g(R(e_i, v)v, e_i)$
for a timelike vector $v\in TM$, and orthonormal basis $(e_i)_{i=1, \dots, n}$, and $\epsilon_i = g(e_i, e_i)$. Since the curvature tensor $R$ only depends on the Levi-Civita connection that is the same for $g$ and $-g$, we have $\Ric_{g}= \Ric_{-g}$. It follows that 
a Ricci curvature bound $\Ric_g^{N, \Phi}\geq Kg$ for a metric $g$ with signature $(+, -, \dots, -)$ as in {\it (i)} of \Cref{thm:smoothcd} holds if and only if there is  a  bound $\Ric_{g^-}^{N, \Phi}\geq -Kg^-$ for the metric $g^-=-g$ with signature $(-,+, \dots, +)$. Hence, for a metric $g$ with signature $(-, +, \dots, +)$ the statement of the previous theorem is that $\Ric_g^{N, \Phi}\geq Kg$ holds if and only if $\tCD(-K, N)$ holds. We emphasize this since there is no unified signature convention in the literature and Theorem \ref{thm:smoothcd} will be crucial in the proof of our main results.
\end{rem}
\end{thm}
\begin{proof} For the equivalence between (i) and (ii) we refer to Theorem A.1 in the Appendix A in \cite{Bra:23b}, where the equivalence was established for $\tCD^*_p$-spaces \cite{McC:20}.

For the second statement we refer to \cite[Thm.\ 1.7]{Stu:06b} and its proof.
\end{proof}
