\subsubsection{Disintegration of measures} 
In this subsection we follow the presentation in \cite{fremlin} (see also \cite{CM:21, zhenhao24}).

We consider  a measurable space $(R,\mathcal R)$, a set $Q$ and a map $\mathfrak Q:R\rightarrow Q$. The set $Q$ is equipped with the smallest $\sigma$-algebra $\mathcal Q$ such that $B\in \mathcal Q$  if $\mathfrak Q^{-1}(B)\in \mathcal{R}$. Given a measure $\m$ on $(R,\mathcal R)$, one can define {its quotient} measure $\mathfrak q$ on $Q$ via the pushforward $\mathfrak Q_{\sharp}\, \m=: \mathfrak q$.

A disintegration of $\m$ over  $\mathfrak q$ is a map $\mathcal R \times Q\ni (B,q)\mapsto \m_{q}(B)\in [0,\infty]$ such that the following holds
\begin{itemize}
\item $\m_{q}$ is a measure on $(R,\mathcal R)$ for every $q\in Q$,
\item $q\mapsto \m_{q}(B)$ is $\mathfrak q$-measurable for every $B\in \mathcal R$,
\item $\m(B)= \int_Q\m_q(B)\,\dint\mathfrak q$ for every $B\in \mathcal R$.
\end{itemize}We use the notation $\{\m_{q}\}_{q\in Q}$ for such a disintegration. We call the measures $\m_{q}$ {\it conditional  measures}.
%Let $f: (R, \mathcal R)\rightarrow (Q, \mathcal Q)$ be measurable, for instance $\mathfrak Q$.
A disintegration $\{\m_q\}_{q \in Q}$ over $\mathfrak q$ is called \emph{consistent w.r.t.\ $\mathfrak Q$}  if for all $B\in \mathcal R$ and $C\in \mathcal Q$ the consistency condition
$$
\m(B\cap \mathfrak Q^{-1}(C))=\int_C \m_{q}(B) \,\dint\mathfrak q(q)
$$
holds.  
A 
disintegration $\{\m_{q}\}_{q\in Q}$  
 is called {\it strongly consistent }if it is consistent w.r.t.\ its quotient map and for $\mathfrak q$-a.e.\ $q$ the conditional measure $\m_q$ is concentrated in $\mathfrak Q^{-1}(\{q\})$.

Finally, we say that a consistent disintegration $\{\m_q\}_{q \in Q}$ over $\mathfrak q$ is \emph{$\mathfrak q$-unique} if the following holds. Let $ \{\m'_{q}\}_{q\in Q}$ be another consistent disintegration of $\m$ over $\mathfrak q$. Then $\m_{q}=\m'_{q}$ for $\mathfrak q$-a.e.\ $q \in Q$. If $\mathcal R$ is countably generated and $\m$ is $\sigma$-finite, then a consistent disintegration of $\m$ over $\mathfrak q$ is $\mathfrak q$-unique.
%\begin{thm}Assume that $(R,\mathcal R, \m)$ is a countably generated probability space and $R=\bigcup_{q\in Q}R_{q}$ is a partition of $R$. Let $\mathfrak Q: R\rightarrow Q$ be the quotient map associated to this partition, that is $q =\mathfrak Q(x)$ if and only if $x\in R_{q}$ and assume the corresponding quotient space $(Q,\mathcal Q)$ is a Polish space.
%Then, there exists a strongly consistent disintegration $\{\m_{q}\}_{q\in Q}$ of $\m$ {with respect to} $\mathfrak Q:R\rightarrow Q$ that is $\mathfrak q$-unique.\end{thm}
\subsubsection{$1D$ localisation}  
Let $(X,d,\m)$ be a proper metric measure space that is essentially nonbranching. We  assume that $\supp\m =X$.
Let $u:X\rightarrow \mathbb{R}$ be a $1$-Lipschitz function. Then 
\begin{align*}
\Gamma_u:=\{(x,y)\in X\times X : u(x)-u(y)=d(x,y)\}
\end{align*}
is a  $d$-cyclically monotone set. One also defines $$\Gamma_u^{-1}=\{(x,y)\in X\times X: (y,x)\in \Gamma_u\}.$$
If $\gamma:[a,b]\rightarrow X$ is a geodesic such that $(\gamma(a),\gamma(b))\in \Gamma_u$ then $(\gamma(t),\gamma(s))\in \Gamma_u$ for $a<t\leq s<b$.  It is therefore natural to consider the set $G$ of unit speed geodesics $\gamma:[a,b]\rightarrow \R$ such that $(\gamma(t),\gamma(s))\in \Gamma_u$ for all $a\leq t\leq s\leq b$. 
The union $\Gamma_u\cup \Gamma_u^{-1}$ defines a relation $R_u$ on $X\times X$, and $R_u$ induces a {\it transport set with endpoints} 
$$\mathcal T^b_u:= P_1(R_u\backslash \{(x,y):x=y\})\subseteq X,$$ 
where $P_1(x,y)=x$ is the projection onto the first factor. For $x\in \T^b_u$ we define the sections $\Gamma_u(x):=\{y\in X:(x,y)\in \Gamma_u\}, $
and similarly $\Gamma_u^{-1}(x)$, as well as $R_u(x)=\Gamma_u(x)\cup \Gamma_u^{-1}(x)$. Since $u$ is $1$-Lipschitz, 
 $\Gamma_u, \Gamma_u^{-1}, R_u\subseteq X^2$ and  $\Gamma_u(x), \Gamma_u^{-1}(x), R_u(x)\subseteq X$ are closed.

The {\it transport set without branching} $\mathcal T_u$ associated to $u$ is  defined as 
\begin{align*}
\mathcal T_u=\left\{ x\in \mathcal T^b_u: \forall  y,z\in R_u(x) \Rightarrow  (y,z)\in R_u\right\}.
\end{align*}
%
%
% 
The sets $\T^b_u$ and $\T^b_u\setminus \T_u$ are $\sigma$-compact, and $\T_u$ and $R_u\cap \T_u\times \T_u$ are Borel sets.
Moreover, $\T_u$ is  $\sigma$-compact. 

In \cite{Cav:17} Cavalletti shows that $R_u$ restricted to $\T_u\times \T_u$ is an equivalence relation. 
%
Hence, from $R_u$ one obtains a partition of $\mathcal T_u$ into a disjoint family of equivalence classes $\{X_{q}\}_{q\in Q}$. 

Let $\mathfrak Q: \mathcal T_u\rightarrow Q$ be the induced quotient map. We  equip
 $Q$ with the   measurable structure $\mathcal Q$ such that $\mathfrak Q: \T_u\rightarrow Q$ is a measurable map. 
%
%
We set $\smash{\mathfrak q:= \mathfrak Q_{\sharp}\,[\m|_{\mathcal T_u}]}$. 

Every $X_{q}$ is isometric to an interval  $I_q\subseteq\mathbb{R}$ via a distance preserving map $\gamma_q:I_q \rightarrow X_{q}$. The curve $\gamma_q:I_q\rightarrow X$ extends to an arclength parametrized geodesic  on $\overline I_{q}$  that we also denote $\gamma_q$. We denote the  open interior of $\overline I_q$ with $(a_q,b_q)$ where $a_q, b_q\in \R\cup \{\pm \infty\}.$


A \emph{measurable section} of the equivalence relation $R_u$ on $\T_u$ is a measurable map $s: \T_u\rightarrow \T_u$ such that $R_u(s(x))=R_u(x)$, and $(x,y)\in R_u$ implies $s(x)=s(y)$. In \cite[Prop.\ 5.2]{Cav:17} Cavalletti shows that there exists a measurable section $s$ of $R_u$ on $\T_u$. Therefore, one can identify the measurable space $Q$ with the measurable set $\{x\in \T_u: x=s(x)\}\subseteq X$ equipped with the induced measurable structure. Hence $\mathfrak q$ is a Borel measure on $X$. By inner regularity there exists a $\sigma$-compact set $Q'\subseteq X$ such that $\mathfrak q(Q\setminus Q')=0$. We have that the Borel $\sigma$-algebra induced on $Q'$ is contained in $\mathcal Q$. In the following we will replace $Q$ with $Q'$ without further comments.  The map $\gamma_q$ with {$q\in Q$ is reparametrized such that $\gamma_q(0)=s(x)$.} The functions $Q\ni q \mapsto a_{q}, b_{q}\in \R$ are measurable. 
%We set $Q^l=\{l\geq |a_q|, |b_q|\geq \frac{1}{l}\}$.
%
%Now, we also assume that $(X,d,\m)$ is a $\CD^*(K,N)$ space for $K\in \R$ and $N\geq 1$. 
%The following lemma is .
\begin{lem}[{\cite[Lem.\ 3.4]{CM:20}}]
Let $(X,d,\m)$ be an essentially nonbranching $\CD^*(K,N)$ space for $K\in \R$ and $N\in (1,\infty)$ with $\supp \m=X$ and $\m(X)<\infty$.
Then, for any $1$-Lipschitz function $u:X\rightarrow \R$, it holds that $\m(\T^b_u\setminus \T_u)=0$.
\end{lem}
For $\mathfrak q$-a.e.\ $q\in Q$ it was proved in \cite[Thm.\ 7.10]{CM:21} that 
\begin{align}\label{int}
R_u(x)=\overline{X_q}\supset X_q \supset (R_u(x))^{\circ} \ \ \forall x\in \mathfrak Q^{-1}(q).
\end{align}
where $(R_u(x))^\circ$ denotes the relative interior of the closed set $R_u(x)$. We replace $Q$ with a set, that is also denoted $Q$, such that \eqref{int} holds for every $q\in Q$.
