\begin{thm}[{\cite[Thm.\ 3.3]{CM:20}}]\label{Th:1Dloc}
Let $(X,d,\m)$ be
%
a complete, proper, geodesic metric measure space 
with $\supp\m =X$ and $\m$ $\sigma$-finite. Let $u:X\rightarrow \mathbb{R}$ be a $1$-Lipschitz function,  let $(X_q)_{q\in Q}$ be the induced partition of $\mathcal T_u$ via $R_u$, and let $\mathfrak Q: \T_u\rightarrow Q$ be the induced quotient map as above.
Then, there exists a strongly consistent disintegration $\{\m_q\}_{q\in Q}$ of $\m|_{\T_u}$ w.r.t.\ $\mathfrak Q$. 
\end{thm}
Define the ray map $\mathfrak{G}$ as 
\begin{align*}
\mathfrak G:  \mathcal V\subseteq Q\times \R\rightarrow X\ \mbox{ via }\
\mbox{graph}(\mathfrak G)=\{ (q, t,x) \in Q\times \R\times X: t\in I_q, \gamma_q(t)=x\}.  
\end{align*}
We have the following:
\begin{itemize}
\item 
the map $\mathfrak G$ is Borel measurable,  and 
by definition $\mathcal V= \mathfrak G^{-1}(\T_u)$;
\item $\mathfrak G(q,\cdot)=\gamma_q: I_q\rightarrow X$; 
\item $\mathfrak G:\mathcal V\rightarrow  \T_u$ is bijective and its inverse is given by $\mathfrak G^{-1}(x)=\big( \mathfrak Q(x), \pm d(x,\mathfrak Q(x))\big)$.
\end{itemize}
\begin{thm}\label{Th:CD1}
Let $(X,d,\m)$ be an essentially nonbranching $\CD(K,N)$  space with $\supp\m=X$, $\m$ $\sigma$-finite, $K\in \R$ and $N\in (1,\infty)$.

Then, for any $1$-Lipschitz function $u:X\rightarrow \R$ there exists a disintegration $\{\m_q\}_{q\in Q}$ of $\m$ that is strongly consistent with $R^b_u$. 

Moreover, for $\mathfrak q$-a.e.\ $q\in Q$, $\m_{q}$ is a Radon measure with $\m_q=h_q\mathcal{H}^1|_{X_q}$ and $(X_q, d|_{X_q\times X_q}, \m_q)$ verifies the condition $\CD(K,N)$. 
\end{thm}
\begin{rem}[$\CD(K,N)$-density]\label{rem:thefollowingremark}
More precisely, for $\mathfrak q$-a.e.\ $q\in Q$ it holds that
\begin{align}\label{kuconcave}
h_q(c_t)^{\frac{1}{N-1}}\geq \sigma_{K/N-1}^{(1-t)}(|\dot c_t|)h_q(c_0)^{\frac{1}{N-1}}+\sigma_{K/N-1}^{(t)}(|\dot c_t|)h_q(c_1)^{\frac{1}{N-1}}
\end{align}
for every geodesic $c:[0,1]\rightarrow (a_q,b_q)$.

The property
\eqref{kuconcave} yields that $h_q$ is locally Lipschitz continuous on $(a_q,b_q)$, and  $h_q:\R \rightarrow (0,\infty)$ satisfies
\begin{align}\label{kuode}
\frac{d^2}{dr^2}h_q^{\frac{1}{N-1}}+ \frac{K}{N-1}h_q^{\frac{1}{N-1}}\leq 0 \mbox{ on $(a_q, b_q)$} \mbox{ in distributional sense.}
\end{align}Moreover, $h_q$ is continuous on $\overline{(a_q, b_q)}$ for $\mathfrak q$-a.e.\ $q\in Q$. It follows that \eqref{kuconcave} holds for every geodesic $c:[0,1]\rightarrow \overline{(a_q, b_q)}$ for $\mathfrak q$-a.e.\ $q\in Q$.



Hence, $h_q$ is a $\CD(K,N)$-density on $\overline{(a_q, b_q)}$ in the sense of Cavalletti-Milman \cite{CM:21}. Such functions have been studied also in \cite{EKS:15}.\end{rem}


\begin{rem}[Properties of $\CD(K,N)$-densities]\label{Re:properties of CD(K,N)-densities and logarithmic convolutions}
We  collect  some properties of $\CD(K,N)$-densities from \cite{CM:21} that we will need later.
\begin{enumerate}
    \item $h$ is strictly positive in  $(a,b)$ or it identically vanishes.
    \item $h$ is locally semi-concave in the interior of its definition, i.e., for all $r_0\in(a,b)$ there exists a constant $C_{r_0}\in\R$ such that $h(r)-C_{r_0}r^2$ is concave in a neighbourhood of $r_0$.
    \item $h$ is locally Lipschitz continuous in the interior $(a,b)$.
\item A  metric measure space $(I, \m)$ for an interval $I\subset \R$ and a measure $\m$ on $I$ satisfies the $\CD(K,N)$ condition if and only if $\m= h \dint \mathcal L^1$ and $h$ is a $CD(K,N)$-density. 
\end{enumerate}
\end{rem}
\begin{rem}
If a function $h: \overline{(a,b)}\rightarrow \R$ is upper semi-continuous and satisfies the differential inequality \eqref{kuode} in $(a,b)$, then $h$  satisfies \eqref{kuconcave} for every geodesic $c$ in $\overline{(a,b)}$ \cite[Lem.\ 2.8]{EKS:15}.
\end{rem}

\subsubsection{Characterization of curvature bounds via $1D$ localisation}\label{subsec:CD1}
Given a continuous function $\phi: X\rightarrow \R$ such that $\phi^{-1}(\{0\})=: S\neq \emptyset$, we define the signed distance function w.r.t.\ $\phi$ as 
$$\met_\phi: X\rightarrow \R, \ \met_\phi(x) =\sgn(\phi(x)) \cdot\inf_{y\in S} \met(y,x) .$$
When $(X,\met)$ is a length space $\met_\phi$ is $1$-Lipschitz. 

Let $K\in \R$ and $N\geq 1$.
\begin{defi} 
Let $(X,\met_X,\m_X)$ be an essentially nonbranching metric measure length space with $\supp \m_X= X$, and let $u=\met_\phi$ be a signed distance function with the associated partition $\{X_q\}_{q \in Q}$ of $\mathcal T_u$ where $Q$ is equipped with the measurable structure as before such that the quotient map $\mathfrak Q$ is measurable. We say that $(X,\met_X,\m_X)$ satisfies the condition $\CD_u^1(K,N)$  if 
\begin{itemize}
\item[(i)] There exists a $\mathfrak q$-unique disintegration $\{\m_q\}_{q\in Q}$ of $\m|_{\mathcal T_u}$ over $\mathfrak q$.
\item[(ii)] $Q$ is the image of a measurable section $s: \mathcal T_u\rightarrow \mathcal T_u$, and there exists a Borel set $Q'\subseteq Q$, a subset of $\mathcal T_u$, such that $\mathfrak q(Q\setminus Q')=0$.
\item[(iii)] For $\mathfrak q$-a.e.\ $q\in Q$ the set $R_u(x)=\overline X_q$ for every $x\in \mathfrak Q^{-1}(\{q\})$, and $X_q$ is the image $\mbox{Im}(\gamma_q)$ of a geodesic $\gamma_q:I_q\rightarrow X$ for an interval $I_q\subseteq\R$.
\item[(iv)] For $\mathfrak q$-a.e.\ $q\in Q$ $\m_q$ is supported on $\overline X_q$ and  the metric measure space $(X_q, \met_X|_{X_q\times X_q},\m_q)$ satisfies the condition $\CD(K,N)$.
\item[(v)] For every bounded set $K\subseteq X$ there exists $C_K\in (0, \infty)$ such that $\m_q(K)\leq C_K$ for $\mathfrak q$-a.e.\ $q\in Q$. 
\end{itemize}
\noindent
The metric measure space $(X,d_X,\m_X)$ satisfies the condition $\CD^1(K,N)$ if it satisfies the condition $\CD^1_u(K,N)$ for any $1$-Lipschitz function $u:X\rightarrow \R$.
\end{defi}
\begin{rem}
From the previous sub-subsection it is immediately clear that the condition $\CD(K,N)$ implies the condition $\CD^1(K,N)$. 
\end{rem}
\begin{thm}[{\cite{CM:21, zhenhao24}}]\label{thm:cavmil}
If an essentially nonbranching, locally finite metric measure space $(X,\met_X,\m_X)$, such that $\m_X$ has full support, satisfies the condition $\CD^1(K,N)$ for $K\in \R$ and $N\in [1,\infty)$ then it satisfies the condition $\CD(K,N)$.
\end{thm}
