\section{Generalized cones and warped products}\label{sec-gen-con-wpd-prod}
Here we discuss semi-Riemannian warped products in the smooth and nonsmooth setting with a particular focus on the case of a one-dimensional base, and also with one-dimensional fiber.

\subsection{Warped products over semi-Riemannian manifolds}\label{sec:wpsemiriem}
Let $(B,g_B)$ be an $d$-dimensional semi-Riemannian manifold and let $f: B\rightarrow (0, \infty)$ be a smooth function. Let $(F,g_F)$ be an $n$-dimensional semi-Riemannian manifold. The \emph{semi-Riemannian warped product} of $B$ and $F$  w.r.t.\ $f$ is defined as the product manifold
$C= B\times F$
equipped with the semi-Riemannian metric 
$$g_{_{B\times_f F}} = (P_B)^* g_B + (f\circ P_B)^2 (P_F)^* g_F\,,$$
where $(P_B)^*$ and $(P_F)^*$ are the pullbacks onto $B\times F$ w.r.t.\ the projections maps from $B\times F$ onto $B$ and $F$. The spaces $B$, $F$ and the function $f$ are called the base, the fiber and the warping function, respectively. The semi-Riemannian manifold $(B\times F, g_{B\times_f F})$ has index (i.e., the dimension of the largest negative definite subspace) $\nu_B + \nu_F$, where $\nu_B$ and $\nu_F$ are the index of $g_B$ and $g_F$, respectively. 

We call $\smash{P_F^{-1}(\{x\})}$, for $x\in F$, the leaves and $\smash{P_B^{-1}(\{t\})}$, for $t\in B$, the fibers. Vectors tangent to leaves are called \emph{horizontal}, vectors tangent to fibers are called \emph{vertical}.  We write $(\cdot)^{\perp}$ and $(\cdot)^\top$ for the horizontal and the vertical projections. One can lift vector fields on $B$ or on $F$ to $B\times F$ and the family of all such lifts is denoted with $\mathcal L(B)$ and $\mathcal L(F)$, respectively. We use the same notation for vector fields on $B$ or $F$, and their lifts.  If $h$ is a smooth function then the lift of the gradient $\nabla h$ is the gradient of $h\circ P_B$.

Recall the following formulas for the Levi-Civita connection $\nabla$ of $B\times_fF$ (see \cite[Prop. 7.35]{ONe:83}). Let $X, Y\in \mathcal L(B)$ and $V,W\in \mathcal L(F)$, then 
\begin{enumerate}
\item $\nabla_XY$ is the lift of $\nabla^B_X Y$. 
\item $\nabla_XV= \nabla_VX= (X\log f)V= g_B(X, \nabla \log f) V$. 
\item $(\nabla_VW)^\perp= - g_F (V,W) \nabla \log f$.
\item $(\nabla_VW)^\top$ is the lift of $\nabla^F_VW$. 
\end{enumerate}
\noindent
{\bf Assumption:} 
From now on we assume that both $B$ and $F$ are Riemannian manifolds with Riemannian metrics $g_B$ and $g_F$, but we consider $B$ as a semi-Riemannian manifold $^\pm\! B$ that  is either equipped with the Riemannian metric $g_B$ or with the semi-Riemannian $\smash{-g_B=g_{^{{-}}\!B}}$. The warped product metric is given then by
$$g_{^\pm\! B\times_f F} = (P_B)^* g_{^\pm B} + (f\circ P_B)^2 (P_F)^* g_F= \pm (P_B)^* g_{B} + (f\circ P_B)^2 (P_F)^* g_F\,.$$

\begin{rem}[Hessian and Laplacian]\label{Rem: hessian and laplacian}
Recall that the Hessian of  $h\in C^\infty(B)$ w.r.t.\ $g_B$ is 
$$\nabla^2 h(X,Y) = X(Y h) - \nabla^B_XY h= g_B(\nabla^B_X \nabla h, Y)\,,$$
where $\nabla^B$ is the Levi-Civita connection of $g_B$.

We note also that by Koszul's formula the Levi-Civita connections w.r.t.\ $g_B$ and w.r.t.\ $-g_B$ are the same.  In particular, the Hessians $\nabla^2$ w.r.t.\ $g_B$ and w.r.t.\ $-g_B$ are the same. On the other hand, for the gradient of a function $h$ w.r.t.\ $g_{^- B}$ we have  $\smash{\nabla^{^-\!B} h= - \nabla^{B} h}$ because by definition of the gradient
$$ g_B(\nabla^B h, X)= g_{^-B}(- \nabla^B h, X).$$ 
Moreover $-g_{B}(\nabla^B h, \nabla^B h)= g_{^- B}(\nabla^{^- B} h, \nabla^{^- B} h)$. In the following we drop the superscript in $\nabla^{^\pm B}h$ and write $\nabla h$ if there is no risk of confusion.

For the Laplace operator we have  $\smash{\Delta^{\!^-\!B}= - \Delta^B}$. To see  this we recall that the Laplace operator $\Delta^M$ on a semi-Riemannian manifold $M$ is defined as 
$$\Delta^M f(p)= \sum_{i=1}^n \epsilon_i g_M(\nabla_{e_i} \nabla f|_p, e_i)$$ 
where $p\in M$, $(e_i)_{i=1, \dots, n}$ is an orthonormal basis at $T_pM$ and $\epsilon_i = g_M(e_i, e_i)$. Equivalently, $\Delta^M f$ is the divergence of $\nabla f$.


\end{rem}

Given $\kappa\in \R$ we assume for $h\in C^2(B)$ that 
\begin{align}\label{Eq: f diff ineq}
\nabla^2 h + \kappa h g_{^{\pm}\! B}=\nabla^2 h \pm \kappa h g_{ B}\leq 0.
\end{align}
For instance, if $B=I$ is an interval this differential inequality translates to 
$$ h'' \pm \kappa h\leq 0.$$
Hence, $h$ is either $\kappa$-concave or $(-\kappa)$-concave, depending on whether we consider $I$ or $^-\! I$. 
\smallskip

We will consider measures of the form $f^N\vol_B \otimes \vol_F$ on ${}^\pm B\times_f F$. On the other hand the volume that is induced by $\smash{g_{{}^\pm B\times_f F}}$ is of the form $f^n\vol_B\otimes \vol_F$ where $n$ is the dimension of $F$. This is why we will study now the convexity properties of the function $\smash{\Phi:= \log f^{N-n}}$. For $N\in (n, \infty)$ a straightforward calculation from \eqref{Eq: f diff ineq} for $\Phi= (N-n) \log f$  yields
\begin{align}\label{Eq: Phi}
    \nabla^2 \Phi + \frac{1}{N-n} \dint\Phi \otimes \dint\Phi  +  (N-n)\kappa\, g_{^\pm\! B}\leq 0.
\end{align}
Moreover, given $\eta\in \R$ we consider $H\in C^{2}(F)$ such that 
$$\nabla^2 H^{\frac{1}{N-n}}+ \eta H^\frac{1}{N-n} g_F\leq 0.$$
Then, setting $\Psi:= \log H$ it follows that
\begin{align}\label{Eq: Psi}
    \nabla^2 \Psi + \frac{1}{N-n} \dint\Psi\otimes \dint\Psi +  (N-n) \eta\, g_F\leq 0.
\end{align}
\begin{prop}\label{Pr:G is kappa concave}
Let $\Phi\in C^{\infty}(B)$ and $\Psi\in C^{\infty}(F)$  satisfy \eqref{Eq: Phi} and \eqref{Eq: Psi}.  We set $\Theta= \Phi\circ P_B  + \Psi\circ P_F \in C^{\infty}(B\times F)$ and assume additionally that
\begin{align}\label{ineq:forf} g_{^\pm B}(\nabla f, \nabla f) + \kappa f^2 \leq \eta \mbox{ on } B.\end{align}
Then
\begin{align*}
\nabla^2 \Theta+ \frac{1}{(d+N)-(d+n)} \dint\Theta\otimes \dint\Theta + ((d+N)-(d+n))\kappa \,g_{\pm B\times_f F} \leq 0.
\end{align*}
In particular $G= e^\Theta$ satisfies $\nabla^2 G^\frac{1}{N-n}+ \kappa\, G^\frac{1}{N-n} g_{\pm B\times_f F}\leq 0$.
\end{prop}
We note  that $d+N-(n+d)=N-n$.
\smallskip

If $B=I$, then \Cref{ineq:forf} reads as $\pm (f')^2 + \kappa f^2 \leq 0$.
\begin{proof}  We  write  $\langle \cdot, \cdot \rangle$ for $\smash{g_{_{^\pm B\times_f F}}}$. We pick vector fields $X\in \mathcal L(B)$ and $V\in \mathcal L(F)$ and set $W=X+V\in\mathfrak{X}(B\times F)$. Using the formulas of the Levi-Civita connection of $B\times_fF$ we compute that 
$$\nabla^2 (\Phi\circ P_B)(W,W)= \langle \nabla_W \nabla( \Phi\circ P_B), W\rangle = \nabla^2(\Phi\circ P_B)(X,X)+ \nabla^2 (\Phi\circ P_B)(V,V)$$
and 
$$\nabla^2 (\Psi\circ P_F)(W,W)= \nabla^2(\Psi\circ P_F)(V,V)+2 \nabla^2(\Psi\circ P_F)(X,V).$$
Moreover we compute
\begin{align*}
\nabla^2(\Phi\circ P_B)(X,X)&= X(X(\Phi\circ P_B)) - (\nabla_X X)(\Phi\circ P_B)\\
&= X(X\Phi)\circ P_B- (\nabla^B_XX)\Phi\circ P_B= \nabla^2 \Phi(X,X)\circ P_B\,,\\
\nabla^2(\Phi\circ P_B)(V,V)&= \langle V, V\rangle \langle \nabla \log f, \nabla \Phi\rangle\\
&= (N-n)\langle V, V\rangle \langle \nabla\log f, \nabla \log f \rangle\,,
\end{align*}
as well as 
\begin{align*}
\nabla^2(\Psi\circ P_F)(V,V)= \nabla^2 \Psi(V,V)\circ P_F,\ \
\nabla^2(\Psi\circ P_F)(X,V)= -\langle X, \nabla\log f\rangle \langle V, \nabla \Psi\rangle\,.
\end{align*}
We also compute 
\begin{align*}
\nabla \Theta \otimes \nabla \Theta(W,W)
%&= \nabla \Phi \otimes \nabla \Phi (W,W)+ 2\nabla \Phi \otimes \nabla \Psi (W,W) + \nabla \Psi\otimes \nabla \Psi (W,W)\\
%&= \nabla \Phi\otimes \nabla \Phi(X,X)+ 2 \nabla \Phi \otimes \nabla \Psi (X,V)+ \nabla \Psi\otimes \nabla \Psi (V,V)\\
&=(N-n)^2 \langle \nabla \log f, X\rangle^2 + 2 (N-n)\langle \nabla \log f, X\rangle \langle \nabla \Psi, V\rangle+ \langle \nabla \Psi, V\rangle^2\,.
\end{align*}
Hence,
\begin{align*}
&\nabla^2 \Theta(W,W) + \frac{1}{N-n} \nabla \Theta\otimes \nabla \Theta(W,W)\\
&= \nabla^2 \Phi(X,X)\circ P_B + \nabla^2 \Psi(V,V)\circ P_F\\
&\ \ \ \  \ + (N-n)\langle V,V\rangle \langle \nabla \log f, \nabla \log f \rangle \\
&\ \ \ \ \ -2 (...)+  (N-n) \langle \nabla \log f, X\rangle^2+2(...) + \frac{1}{N-n} \nabla \Psi\otimes \nabla \Psi (V,V)\\
&\leq  \nabla^2 \Phi(X,X)\circ P_B + \nabla^2 \Psi(V,V)\circ P_F\\
&\ \ \ \  +(N-n) \langle V, V\rangle \frac{\eta- \kappa f^2}{f^2}+ \frac{1}{N-n} \langle \nabla \Phi, X\rangle^2+ \frac{1}{N-n} \nabla \Psi\otimes \nabla \Psi (V,V)
\\
&=  \nabla^2 \Phi(X,X)\circ P_B + \nabla^2 \Psi(V,V)\circ P_F\\
&\ \ \ \  + (N-n) \big(\eta g_F(V,V)  - \kappa\langle V, V\rangle \big)+ \frac{1}{N-n} \langle \nabla \Phi, X\rangle^2+ \frac{1}{N-n} \nabla \Psi\otimes \nabla \Psi (V,V)\\
&\leq -(N-n)\kappa \big( g_{^\pm \! B}(X,X) + f^2 g_F(V,V)\big).
%=- (N-n) \kappa g_{^\pm \! B\times_f F} (W,W)\,,
\end{align*}
and this finishes the proof. 
\end{proof}
\subsubsection{$1$-dimensional base and fiber}
We now assume that $B= I$ is an interval. 
The interval $I$ is equipped with either one of the two standard semi-Riemannian metrics, that is $(\dint t)^2$ or $-(\dint t)^2$.  In the former case we  write $^+\!I$ for $I$, in the latter case we write $^-\!I$ for $I$ as before. 

We recall that the inequality \eqref{Eq: f diff ineq} for a smooth function $f: ^{\pm}\!I \rightarrow (0, \infty)$ becomes 
\begin{align}\label{inequ:kappa} f'' \pm \kappa f\leq 0\,,\end{align}
where the sign $\pm$ in front of $\kappa$ depends on whether we consider $^+ I$ or $^- I$. 

%In particular,  the space $(^{\pm}\!I,\vert\cdot\vert,f^{N-1}(t)\,\dint t)$
%}
%satisfies $\Ric^{\Phi, N}_{{}^\pm\!I}\geq \pm(N-1) \kappa$ where $\Phi=(N-1) \log f$. 
%Indeed, similarly as above, we have 
%$$\Phi'' + \frac{1}{N-1} (\Phi')^2 \pm (N-1) \kappa\leq 0.$$


Moreover, we consider $F=(a,b)\subseteq\R$,  equipped with the Riemannian metric $(\dint t)^2$, and let $h\in C^\infty( (a,b),(0,\infty))$ satisfy 
$$\left(h^{\frac{1}{N-1}}\right)'' + \eta h^\frac{1}{N-1}\leq 0.$$
\begin{rem}
Consider the semi-Riemannian warped product $^\pm I\times_f (a,b)$ between $B={}^\pm\! I$ and $F=(a,b)$. If $I$ is equipped with the standard Riemannian structure, i.e., $I= ^+\!\!\!I$, then $^+\! I\times_f (a,b)$ is a Riemannian manifold and the Riemannian metric is $(\dint t)^2 + f^2 (\dint r)^2$. If $I$ is equipped with the semi-Riemannian metric $-(\dint t)^2$, i.e., ${}^-\!I$, then $^-\! I\times_f (a,b)$ is a Lorentzian manifold and the Lorentzian metric is $-(\dint t)^2+ f^2 (\dint r)^2$. 
\end{rem}
\begin{rem}[Signature convention]
We could use a different signature convention, i.e.\ $(\dint t)^2- f^2 (\dint r)^2$ instead of $-(\dint t)^2+f^2 (\dint r)^2$. Then, $\kappa$  has to be replace with $-\kappa$ (i.e. $f''+\kappa f\leq 0$ instead of $f''- \kappa f\leq 0$. In the literature there is no canonical signature convention. Hence, for comparison with other results, the signature convention has to be fixed. For instance, in \cite{AB:08}, \cite{CM:24a} and in \cite{AGKS:23} the signature convention is $(-, +, \dots, +)$, whereas in \cite{McC:20} the signature convention is $(+, -, \dots, -).$
\end{rem}
Applying  \Cref{Pr:G is kappa concave} to $G= f^{N-1} h$ we get the following result:
\begin{cor}\label{cor:fct}
 Let $f,h$ and $G$ be as above. Then $G$ satisfies
\begin{equation}\label{eq:fct} \smash{\nabla^2 G^\frac{1}{N-1}+ \kappa G^\frac{1}{N-1}g_{\pm I\times_f(a,b)}\leq 0\,},
\end{equation} provided $\pm \left(\frac{\dint f}{\dint t}\right)^2 + \kappa f^2 \leq \eta$,  where the sign depends on whether $I$ is equipped with $(\dint t)^2$ or with $-(\dint t)^2$.
\end{cor}
In particular, if $c: [0, 1]\rightarrow{}^-I \times_f (a,b)$ is a timelike, constant speed geodesic, then we compute for $\phi =G \circ c$ that 
$$\left( \phi^\frac{1}{N-1}\right)'' = \nabla^2 G^{\frac{1}{N-1}}(c', c')\leq - \kappa \left(G^{\frac{1}{N-1}}\circ c\right) g_{{}^-I\times_f F}(c', c')= + (L(c))^2\kappa G^{\frac{1}{N-1}}\circ c.$$
Hence, $(\phi^{\frac{1}{N-1}})'' - \kappa L(c)^2 \phi^{\frac{1}{N-1}}\leq 0$, and that is equivalent to 
$$\phi((1-s) t_0 + st_1)^\frac{1}{N-1} \geq \sigma_{-\kappa}^{(1-s)}((t_1-t_0)L(c)) \phi(t_0)^{\frac{1}{N-1}} +  \sigma_{-\kappa}^{(s)}((t_1-t_0)L(c)) \phi(t_1)^{\frac{1}{N-1}} $$
for all $t_0, t_1\in [0,1]$ and $s\in [0,1]$.
\begin{prop}\label{prop:concave} Consider $I$, $f$ and $(a,b)$ as before, as well as the semi-Riemannian warped product $^-\!I\times_f (a,b)$. 
Let  $h$ be a continuous function on $[a,b]$ such that $\smash{(h^\frac{1}{N-1})'' + \eta h^\frac{1}{N-1}\leq 0}$ in the distributional sense. Let $c: [0,1]\rightarrow\,^-\!I\times_f (a,b)$ be a timelike, constant-speed geodesic w.r.t.\ $g_{^-\!I\times_f(a,b)}$, and set $\phi= G\circ c$. Then 
$$\left(\phi^{\frac{1}{N-1}}\right)'' - \kappa L(c)^2 \phi^{\frac{1}{N-1}} \leq 0 \ \ 
\mbox{ in the distributional sense. }$$
\end{prop}
\begin{proof}
We can approximate $h$ uniformly by smooth functions $h_\varepsilon$  such that $(h_\varepsilon^\frac{1}{N-1})''+ \eta  h_\varepsilon^\frac{1}{N-1}\leq 0$. More precisely,  we pick a non-negative mollifier function $\varphi\in C^{\infty}_c((0,1))$ with $\int_0^1 \varphi(t)\,\dint t =1$ and define $\varphi_\varepsilon(t):= \frac{1}{\varepsilon} \varphi\left(\frac{t}{\varepsilon}\right)$.  Then, for $s\in (a+\varepsilon, b-\varepsilon)$, we set
$$g_\varepsilon(s):=h^{\frac{1}{N-1}}*\varphi_\eps(s) = \int_a^b \varphi_\varepsilon(t-s)h^{\frac{1}{N-1}}(t)\,\dint t= \int_{-\varepsilon}^0 \varphi_\varepsilon(-r) h^{\frac{1}{N-1}}(s-r)\,\dint r\,.$$
It follows that $h_\varepsilon =g_\varepsilon^{N-1} \in C^{\infty}((a+\varepsilon, b-\varepsilon))$ and $h_\varepsilon$ satisfies the desired differential inequality. For details we refer to the proof of \cite[Prop.\ 3.6]{Ket:17}.  

Since $h$ is continuous, one can check that $h_\varepsilon$ converges uniformly to $h$ on $(a+\bar \varepsilon, b-\bar \varepsilon)$ as $\varepsilon\downarrow 0$ for all $\bar\varepsilon$ small enough. We can replace $f$ with $f_\alpha=\alpha\cdot f$ such that $-(f_\alpha')^2 + \kappa f_\alpha^2 \leq \eta-\varepsilon$ for a constant $\alpha=\alpha(\varepsilon)$ with $\alpha(\varepsilon)\rightarrow 1$ if $\varepsilon \rightarrow 0$. Then, it follows that $G_{\alpha, \varepsilon}=f^{N-1}_\alpha h_\varepsilon$ satisfies 
\begin{align}\label{ineq:concave}\nabla^2 G_{\alpha, \varepsilon}^\frac{1}{N-1} + \kappa G_{\alpha,\varepsilon}^\frac{1}{N-1} g_{I\times_{f_\alpha} (a,b)} \leq 0 \ \mbox{ on } I\times (a+\bar\varepsilon, b-\bar \varepsilon). \end{align}
The semi-Riemannian metric $-\dint t^2 +f^2_\alpha \dint r^2$ converges smoothly to $-\dint t^2 + f^2 \dint r^2$ on $I\times (a,b)$. Hence, every timelike geodesic $c:[0,1] \rightarrow I\times (a,b)$ w.r.t.\ $-\dint t^2+f^2 \dint r^2$ is the limit of timelike geodesics $c_\alpha$ in $I\times (a+\bar\varepsilon, b-\bar \varepsilon)$ w.r.t.\ $-\dint t^2 + f^2_\alpha \dint r^2$ for $\alpha\rightarrow 1$ and $\bar \varepsilon>0$ sufficiently small.  At the same time we have that $G_{\alpha(\varepsilon), \varepsilon}$ converges uniformly to $\smash{G=f^{\frac{1}{N-1}} h}$ as $\varepsilon\downarrow 0$ on $I\times (a+\bar \varepsilon, b+\bar\varepsilon)$.  

By the previous computations, it follows for $\phi_\varepsilon= G_{\alpha(\varepsilon), \varepsilon}$ and $t_0, t_1\in [0,1]$ that 
$$\phi_\epsilon((1-s) t_0 + st_1)^\frac{1}{N-1} \geq \sigma_{-\kappa}^{(1-s)}((t_1-t_0)L(c_\varepsilon)) \phi_\epsilon(t_0)^{\frac{1}{N-1}} +  \sigma_{-\kappa}^{(s)}((t_1-t_0)L(c_\varepsilon)) \phi_\epsilon(t_1)^{\frac{1}{N-1}} .$$
This inequality is stable under uniform convergence  and hence it is also satisfied for $\phi$. This yields that distributional inequality for $\phi$ by \cite[Prop.\ 3.6]{Ket:17}. 
\end{proof}

\subsection{Generalized cones as metric spaces}\label{subsec-con-ms}
We briefly recall the construction of warped products with one-dimensional base space, a.k.a.\ generalized cones, of metric spaces, c.f.\ \cite{AB:04, AB:98, BBI:01}.

Let $(X, \met)$ be a metric space, let $I\subseteq\R$ be a closed interval and suppose $f:I\rightarrow [0,\infty)$ is continuous. The length of an absolutely continuous  curve $\gamma=(\alpha, \beta): [a,b]\rightarrow I \times X$ is given by 
$$L(\gamma)= \int_a^b \sqrt{ \dot \alpha^2 + (f\circ \alpha)^2 v_\beta^2} \ \dint t$$
where both components $\alpha$ and $\beta$ are absolutely continuous. In particular, the metric speed $v_\beta$ of $\beta$ is well-defined almost everywhere. Equivalently, $L(\gamma)$ is the supremum of the expressions
\begin{equation}\label{eq:varlength}\sum_{i=0}^N\left( |\alpha(t_{i})- \alpha(t_{i-1})|^2 + (f\circ \alpha(t_i))^2 \met(\beta(t_{i-1}), \beta(t_i))^2\right)^{\frac{1}{2}}
\end{equation}
where $a=t_0\leq t_1 \leq \dots \leq t_N=b$.

The warped product distance on $I \times_f X$ between points $(s,x)$ and $(t, y)$ is defined by the infimum of the length of paths connecting  $(s,x)$ and $(t,y)$. First, this is a semi-distance on $I\times X$ that turns into a distance function when we build the quotient space $(I\times X)/\sim$. Here $(s,x)\sim (t,y)$ if and only if the warped distance between $(s,x)$ and $(t,y)$ is $0$. We write $\met_{I\times_f X}=\met_Y$ for the warped product metric on $(I\times X)/\sim$ and write $I\times_f X$ for the corresponding metric space that we also call generalized (metric) cone.

\begin{rem} If $f>0$, the topology induced by $\met_Y$ coincides with the product topology. If we allow that $f$ vanishes at certain points this might not be the case. But in the following we will always impose  conditions that  imply that $f^{-1}(\{0\})\subseteq\partial I$. It follows that the topology in a neighbourhood of $[(s,x)]$ for $s\in f^{-1}(\{0\})$ is the same as in a neighbourhood of the tip of the topological cone $([0, \infty)\times X)/\{(0,x)\sim (0,y)\}$. 
%In conclusion, at points $[(s,x)]\in I\times_f X$ such that $f(s)>0$ the topology w.r.t.\ $\met_Y$ is locally the product topology, at points $[(s,x)]$ such that $f(s)=0$ the topology w.r.t.\ $\met_Y$ is locally the topology at the tip of a cone. 
\end{rem}
\begin{thm}[Properties of minimizers, {\cite[Thm.\ 3.1]{AB:98}}]
    Assume $(X,\met)$ is a geodesic space, and let $\gamma=(\alpha, \beta)$ be a minimizer of $L$ in $I\times_f X$.
    Then 
    \begin{enumerate}
        \item $\beta$ is a length minimizer in $X$.
        \item $\gamma$ is independent of $X$, except for the total height, i.e., the length of $\beta$. Precisely: for another geodesic metric space $\tilde X$ and a minimizer $\tilde \beta$ in $\tilde X$ with the same length and speed as $\beta$, $(\alpha, \tilde \beta)$ is a minimizer in $I\times_f \tilde X$. This property is called \emph{fiber independence}.
        \item $\alpha$ has speed $\frac{c}{f^2}$ for a constant $c>0$. 
        \item For some parametrization of $\gamma$ proportional to arclength, $\alpha$ satisfies $\frac{1}{2} (\dot \alpha)^2 + \frac{1}{2}\frac{1}{f^2}=E$ for a constant $E>0$. 
        \end{enumerate}
\end{thm}

Two standard examples that illustrate this definition are Euclidean metric cones where $I=[0,\infty)$ and $f=\id$, and spherical suspensions, where $I=[0,\pi]$ and $f=\sin$. The Euclidean cone is given as the quotient space $([0,\infty))\times X/ \sim$ with the metric $\met_Y$ that has the explicit form
$$\met_Y([s,x], [t,y])= \begin{cases} \sqrt{s^2 + t^2 - 2st \cos \met_X(x,y)} & \met_X(x,y)<\pi\,,\\
s+t& \met_X(x,y)\geq \pi\,. \end{cases}$$
\subsection{Generalized cones as Lorentzian length spaces}\label{subsec-con-lls}
In this section we review the construction of a generalized cone as Lorentzian pre-length space from \cite{AGKS:23}. We slightly generalize their definition by allowing arbitrary intervals and a warping function that might vanishes at the endpoints of the interval as in the metric case. To be precise, let $(X,\met)$ be a metric space, $I$ be an interval and $f: I\rightarrow [0, \infty)$ be continuous such that $f^{-1}(\{0\})\subseteq \{\inf I, \sup I\}$. If $f$ vanishes at $\inf I$ or $\sup I$, we demand that
$$\int_{\inf I}^t \frac{1}{f}=\infty\,,\quad\quad\int_t^{\sup I}\frac{1}{f}=\infty,\quad\quad\forall t\in(\inf I,\sup I)\,.$$
This generalization has been discussed in \cite[Rem.\ 3.32]{AGKS:23}. 



%For simplicity, we also assume that $(X,d)$ is a complete metric space that is locally compact and intrinsic, hence strictly intrinsic.

To put a Lorentzian structure on ${}^-\!I\times X$ we define causal and timelike curves.
\begin{defi}[Timelike and causal curves]
 Let $Y={}^-\!I\times X$  and let $\gamma\colon J\rightarrow Y$ be an absolutely continuous curve with respect to the product metric on $Y$. Such a curve has components $\gamma=(\alpha,\beta)$, where $\alpha\colon J\rightarrow I$ and $\beta\colon 
J\rightarrow X$ are both absolutely continuous, and the metric derivative of $\beta$, $v_\beta$, exists 
almost everywhere \cite[Thm.\ 2]{AGS:05}. We additionally require that $\alpha$ is strictly monotonous. The curve $\gamma$ is called
\begin{equation}
\begin{cases}
 \text{\emph{timelike}}\\
 \text{\emph{null}}\\
 \text{\emph{causal}}
 \end{cases}
 \text{\quad if \qquad}
 -\dot\alpha^2 + (f\circ \alpha)^2 v_{\beta}^2\quad
 \begin{cases}
  < 0\,,\\
  = 0\,,\\
  \leq 0\,.
 \end{cases}
\end{equation}
almost everywhere. It is called \emph{future/past directed causal} if $\alpha$ is strictly monotonically 
increasing/decreasing, i.e., $\dot\alpha>0$ or $\dot\alpha<0$ almost everywhere.
\end{defi}

Following \cite{AGKS:23} we can define causal relations on $Y$ as follows.
 Let $y, y'\in Y$, then $y$ and $y'$ are \emph{chronologically} (or \emph{timelike}) related, denoted by $y\ll y'$, if there exists a future 
directed timelike curve from $y$ to $y'$. Moreover, $y$ and $y'$ are \emph{causally} related, denoted by $y\leq y'$ 
if there exists a future directed causal curve from $y$ to $y'$ or $y=y'$.

\begin{defi}[Length of a causal curve]
Let $\gamma=(\alpha,\beta)\colon [a,b]\rightarrow Y$ be a causal curve. Its \emph{length} $L(\gamma)$ is defined as 
\begin{equation}
 L(\gamma):= \int_a^b \sqrt{\dot\alpha^2 - (f\circ\alpha)^2 v_\beta^2}\,.
\end{equation}
\end{defi}
In \cite{AGKS:23} the authors prove a variational formula for $L$ that resembles the formula \eqref{eq:varlength} in the case of metric warped products. As consequence they show that $L$ is upper semi-continuous w.r.t.\ pointwise convergence of $\gamma_n$ to $\gamma$. The latter is understood w.r.t.\ the product topology on $I\times X$. As noted before, if $f$ vanishes in $\partial I$, the topology of $Y$ should be the corresponding quotient topology, i.e., the topology induced by $\met_Y$. It is straightforward to see that the upper semi-continuity still holds in this case. 
\begin{prop}[Push-up]
Every generalized cone ${}^-I\times_f X$ such that $X$ is a length space has the property that $p\ll q$ if
and only if there exists a future directed causal curve from $p$ to $q$ of positive
length, i.e., push-up holds. Moreover, $I^{\pm}(p)$ is open for any $p\in Y$.
\end{prop}
\begin{defi}[Time separation function]
The \emph{time separation function} $\uptau\colon Y\times Y \rightarrow [0,\infty]$ on $Y={}^-I \times_f X$ is defined as
\begin{equation}
 \uptau(y,y'):=\sup\{L(\gamma):\gamma \text{ future directed causal curve from } y \text{ to } y'\},
\end{equation}
if this set is non-empty, and $\uptau(y,y')=0$ otherwise.
\end{defi}
\begin{rem}\label{rem-tau-pro} One can deduce that the time separation function $\uptau$ has the following properties:
 \begin{enumerate}
  \item $\uptau(y,y')=0$ if $y'\not\leq y$.
  \item $\uptau(y,y')>0$ if $y\ll y'$.
\item \cite[Lem.\ 3.21]{AGKS:23} $\uptau$ satisfies the \emph{reverse triangle inequality}. More precisely, let $y_1,y_2,y_3\in Y$ with $y_1\leq y_2\leq y_3$. Then
 \begin{equation}\label{lem-rev-tri}
  \uptau(y_1,y_2) + \uptau(y_2,y_3)\leq \uptau(y_1,y_3)\,.
 \end{equation}\item \cite[Lem.\ 3.25]{AGKS:23}
  Let $(X, \met)$ be a  length space. Then $\tau$ is 
lower semi-continuous with respect to the product metric on $I\times X$. 
It is again straightforward to see that, if $f$ vanished in $\partial I$, $\uptau$ is still lower semi-continuous w.r.t.\ to the quotient topology, i.e., the topology induced by $\met_Y$. 
  \end{enumerate}
\end{rem}
\begin{cor} Let $X$ be a length space and let $Y={}^-I \times_f X$ be the generalized cone. Then $(Y, \ll, \leq, \met_Y, \uptau)$ is a Lorentzian pre-length space. 
\end{cor}
\begin{defi}[Energy of a causal curve]
 Let $Y=I\times_fX$ be a generalized cone and let $\gamma=(\alpha,\beta)\colon[a,b]\rightarrow Y$ be a causal curve. Then the \emph{energy} of 
$\gamma$ is defined as
\begin{equation}
 E(\gamma):=\frac{1}{2}\int_a^b\left[ \dot\alpha^2 -(f\circ\alpha)^2 v_\beta^2\right] \,.
\end{equation}
\end{defi}

Next we collect various properties of generalized cones that we will need from \cite{AGKS:23}. Among them an essential feature of them is the so-called fiber independence.
\begin{thm}[Fiber independence {\textnormal{\cite[Thm.\ 3.29]{AGKS:23}}}]\label{th:fiber}
 Let $(X,\met)$ be a geodesic length space and let $\gamma=(\alpha,\beta)\colon[0,b]$ $\rightarrow Y = {}^-\! I\times_f X$ be future directed causal and maximal. 
 \begin{enumerate}
  \item The fiber component $\beta$ is a length minimizer in $X$.
  \item\label{thm-structure-of-geod-fib-ind} Fiber independence holds. The base component $\alpha$ depends only on the length of $\beta$. More precisely, let $(X',\met')$ be another geodesic length space, $\beta'$ minimizing in $X'$ with 
$L^{\met'}(\beta')=L^\met(\beta)$ and the same speed as $\beta$, i.e, $v_\beta=v_{\beta'}$. Then $\gamma':=(\alpha,\beta')$ is a 
future directed maximal causal curve in $Y':=I\times_f X'$, which is timelike if $\gamma$ is timelike in $Y$.
  \item If $\gamma$ is timelike, then it has an (absolutely continuous) parametrization with respect to arclength, i.e., 
$-\dot\alpha^2 + (f\circ\alpha)^2 v_\beta^2 = -1$ almost everywhere. 
 \item If $\gamma$ is timelike and parametrized with respect to arclength, so $b=L^\uptau(\gamma)$, then the energy of $\gamma$, 
$E(\gamma)$, is minimal under all reparametrizations of $\gamma$ on $[0,b]$.
 \item If $\gamma$ is timelike and parametrized with respect to arclength, then $v_\beta$ is proportional to 
$\frac{1}{(f\circ\alpha)^2}$.
\item If $\gamma$ is timelike, it has an (absolutely continuous) parametrization proportional to arclength such that 
$-\dot\alpha^2 + \frac{1}{(f\circ\alpha)^2}$ is constant.
 \end{enumerate}
\end{thm}
\begin{rem}[Consequences of fiber independence]\label{subsec:con_fiber}
The fiber independence has the following consequence. Let $(X,\met)$ be a geodesic length space and let $\gamma=(\alpha,\beta)\colon[0,b]$ $\rightarrow {}^-\! I\times_f X=
Y$ be future directed, causal and maximal.  We can define the generalized cone $Y_\beta$ of $I$, $X_\beta$ and $f$ where $X_\beta=\beta([0,b])$.
The subset $X_\beta$ in $X$ is isometric
to $[0,L(\beta)]$ where $L(\beta)$ is the length of $\beta$. We obtain an isometry by the $\met$-arc-length parametrization $\bar \beta$ of $\beta$.  The fiber independence implies that $Y_\beta=\I\times_f X_\beta\simeq \I\times_f [0, L(\beta)]$ isometrically embeds into $Y$ via the map $$F_\beta: \I\times_f [0,L(\beta)] \rightarrow \I\times_f X, \quad F(r,t)= (r,  \bar\beta(t))\,. $$
\end{rem}
Here we use the following: Consider two Lorentzian pre-length spaces $(M_i, d_i, \tau_i, \ll_i, \leq_i)$. We call a map $\iota: M_0\rightarrow M_1$ a Lorentzian isometric embedding if for all $x,y\in M_0$
\begin{enumerate}
\item $x\leq_0 y$ if and only if $ \iota(x) \leq_1 \iota(y)$, 
\item $\tau_0(x, y)= \tau_1(\iota(x), \iota(y))$. 
\end{enumerate}

%Under the assumptions of the previous theorem generalized cones are causally very well behaved. In particular, they are \emph{regular}, i.e., causal maximizers are either timelike or null.
\begin{thm}[Properties of generalized cones]\label{Pr: various properties}
    Let $Y=\!{}^-\!I\times_fX$ be a generalized cone as described above and $(X,\met)$ a metric space.
    \begin{itemize}
        \item[(i)] If $X$ is a geodesic length space 
        every maximizing causal curve $\gamma = (\al,\beta): [-b,b]\to Y$ has a causal character,
        i.e., $\gamma$ is either timelike or null \textnormal{\cite[Cor.\ 3.30]{AGKS:23}}.
        \item[(ii)] If $X$ is locally compact  the length $L$ coincides with the $\uptau$-length $L^{\uptau}$ on future-directed causal curves  \textnormal{\cite[Prop.\ 4.7]{AGKS:23}}.
        \item[(iii)] If $X$ is a geodesic and locally compact length space then $Y$ is a strongly causal and regular Lorentzian length space \textnormal{\cite[Cor.\ 4.9]{AGKS:23}}.
        \item[(iv)] If $X$ is a locally compact, complete length space then $Y$ is globally hyperbolic \textnormal{\cite[Cor.\ 4.11]{AGKS:23}}.
        \item[(v)] If $X$ is geodesic, then $Y$ is geodesic too. Furthermore, any two timelike related points can be connected by a timelike geodesic \textnormal{\cite[Cor.\ 4.11]{AGKS:23}}.
    \end{itemize}
\end{thm}

\section{Two-dimensional model spaces}\label{sec-2d-mod-spa}
First, we recall the formulas of the Ricci tensor of warped products of semi-Riemannian manifolds. Let $B, F$ and $f$ be as in Section \ref{sec:wpsemiriem}, especially $\dim_B=d$ and $\dim_F=n$, and let $X,Y\in\mathcal{L}(B)$ and $V,W\in\mathcal{L}(F)$.

The following formulas for the Ricci curvature of $^\pm\!B\times_f F$ hold, cf.\ \cite[Prop.\ 7.43]{ONe:83}:
\begin{enumerate}
\item $\Ric_{^\pm\!B\times_f F}(X,Y)= \Ric_B(X,Y)- n \frac{\nabla^2 f(X,Y)}{f}.$
\item $\Ric_{^\pm\! B\times_f F}(X,V)= 0.$
\item $\smash{\Ric_{\pm\! B\times_f F}(V,W)= \Ric_F(V,W) - \left( \frac{\Delta^{^\pm\!B} f}{f} + (n-1) \frac{g_{^\pm B}(\nabla f, \nabla f)}{f^2} \right) \langle V,W\rangle}.$
\end{enumerate}
Hence
\begin{align*}
\begin{rcases}
g_{^\pm B}(\nabla f, \nabla f) + \kappa f^2 \leq \eta\\ 
\nabla^2 f+ \kappa f g_{^\pm \! B}\leq 0\\
\Ric_{B}\geq (d-1) \kappa g_{\pm B}\\ 
\Ric_F\geq (n-1) \eta g_F
\end{rcases}\Longrightarrow\Ric_{^\pm\!B\times_f F}\geq (n+d-1) \kappa g_{\pm B\times_f F}.
\end{align*}
Now, we assume $B=I$, where $I\subseteq\R$ is an interval, and $F=(a,b)$. We have the following corollary. 

\begin{cor}\label{Co: 2-dim smooth warped product} Let $I\subseteq\R$, $[a,b]\subseteq\R$ and $f:I\rightarrow [0,\infty)$ be smooth. Assume that $\partial I= f^{-1}(\{0\})$ if $\partial I\neq \emptyset.$
\begin{enumerate}
    \item[(1)]
The semi-Riemannian warped product $\I\times_f [a,b]$ satisfies 
$$
\tCD_p(-\kappa, 2) \mbox{ if } I \mbox{ is equipped with $-(\dint t)^2$ }
$$
if and only if 
$
f''- \kappa f\leq 0$.
\item[(2)]
The Riemannian warped product $I\times_f [a,b]$ satisfies 
$$
\CD(\kappa , 2) \mbox{ if } I \mbox{ is equipped with $(\dint t)^2$}$$
if and only if $f''+ \kappa f \leq 0$ and, if $\partial I\neq 0$, $(f')^2 + \kappa f^2 \leq \sqrt{\frac{b-a}{\pi}}.$
\end{enumerate}
\end{cor} \begin{proof} (1) Let us first check the {\it if} implication for the case $I=\I$.

By the formulas for the Ricci curvature of $\I\times_f (a,b)$  for a timelike vector $v=a\frac{\partial}{\partial t}+b\frac{\partial}{\partial r}$, i.e., $g_{^- I\times_f [a,b]}(v,v)<0$, we have
\begin{align*}
%\label{est:est}
    \Ric_{^- I\times_f(a,b)}\left(v,v\right)&= -a^2\frac{f''}{f}\left\vert\frac{\partial}{\partial t}\right\vert^2_{^{^+}\! I}{+}\, b^2\frac{f''}{f} f^2\left\vert\frac{\partial}{\partial r}\right\vert^2
    = \frac{f''}{f}\underbrace{\left[-a^2\left\vert\frac{\partial}{\partial t}\right\vert_{^{^+}\!I}^2 + b^2\,f^2 \left\vert\frac{\partial}{\partial r}\right\vert^2\right]}_{<0\,\text{(}v\text{ is timelike)}}\\ &\geq \kappa\left[-a^2\left\vert\frac{\partial}{\partial t}\right\vert^2_{{}^+I} + b^2f^2\left\vert\frac{\partial}{\partial r}\right\vert^2\right]= \kappa\cdot g_{^-I\times_f(a,b)}(v,v)
    \end{align*}
where $\left| \frac{\partial}{\partial t}\right|_{^+ I}^2= g_{^+I}\left( \frac{\partial}{\partial t}, \frac{\partial}{\partial t}\right).$
Hence $\Ric_{^- I\times_f (a,b)}\geq \kappa g_{^-I\times_f(a,b)} $ in timelike directions whenever $f>0$. Then \Cref{thm:smoothcd} yields the condition $\tCD_p(-\kappa,2)$.

Note that $\I\times_f [a,b]$ is not a smooth space if $\partial I=f^{-1}(\{0\})\neq \emptyset$. However it is clear that one can prove the inequality for the $\tCD_p$ condition on $\I\times_f (a,b)$ for any admissible optimal transport, in the same way as for \Cref{thm:smoothcd}, and that the singular points  $\partial I\times [a,b]$, in case $\partial I$ is non-empty, as well as the boundary $I\times( \{a\}\cup \{b\})$ do not affect the validity of the $\tCD_p$ condition on $\I\times_f[a,b]$. 

For the \emph{only if} direction we refer to the proof of \Cref{Le:from Y to X 2 dim and h smooth} below.
\smallskip

(2) For the {\it if} implication in this case we refer to \cite{Ket:13}. 

For the {\it only if } implication, one has to observe that the tangent cone at $[(t,r)]\in I\times_f [a,b]$ with $t\in \partial I$ exists and is isometric to $[0,\infty)\times_{\id} [a,b]$, the Euclidean cone over $[a,b]$. Moreover, by stability of the $\CD$ condition it satisfies $\CD(0,2)$. Then the conclusion follows from \cite[Cor.\ 2.6]{BS:14}.
\end{proof}
%\begin{rem}We notice that a first order condition $|f'|^2 + \kappa f^2 \leq \eta$ was not necessary  due to (iii) above since $d=1$.
%\end{rem}
Let $h\in C^{\infty}((a,b))$ satisfy $\smash{\big( h^\frac{1}{N-1}\big)'' + \eta h^\frac{1}{N-1}\leq 0}$, where $\eta\in\R$ and $N>1$, and  define $\Theta= \log G$, where {$G= f^{N-1} h:I\times(a,b)\rightarrow\R$.  For $f\in C^\infty(I)$ we still assume \begin{align}\label{ass:forf} f'' \pm \kappa f\leq 0 \ \mbox{ and } \ \pm (f')^2 + \kappa f^2 \leq \eta.\end{align} 

Thanks to \Cref{cor:fct}} (the one-dimensional case of \Cref{Pr:G is kappa concave}) it follows that the $(N+1)$-Bakry--\'Emery Ricci tensor of $({}^\pm I\times_f (a,b), e^{\Theta}\vol_{{}^\pm I\times_f (a,b)})$ has a lower bound
\begin{align}\label{Eq: ricbxff h smooth}
\Ric^{\Theta, N+1}_{{}^\pm I\times_f (a,b)}= \Ric_{{}^\pm I\times_f (a,b)} -\nabla^2 \Theta - \frac{1}{(N+1)-2}\,\dint\Theta \otimes \dint\Theta\geq N\kappa g_{^\pm I \times_f (a,b)}
\end{align}
whenever $f>0$, i.e., the generalized cone and the reference measure $G\vol_{{}^\pm I \times_f (a,b)}$ is smooth. 
\smallskip

In fact, under this assumption the space $({}^\pm I\times_f [a,b], e^{\Theta}\vol_{{}^\pm I\times_f (a,b)})$ satisfies a curvature-dimension condition. We will show this in the next proposition, where  we will also lower the regularity of $h$ from smooth to continuous.
\begin{thm}\label{Th:2 dimensional non-smooth case} Let $f$ as before, $p\in (0,1)$, $N>1$ and assume $\partial I= f^{-1}(\{0\})$.
If $h\in C^0([a,b], [0, \infty))$ satisfies $${\left(h^\frac{1}{N-1}\right)'' + \eta h^\frac{1}{N-1}\leq 0\,,}$$ in the distributional sense, then the generalized cone $({}^\pm I\times_f [a,b], {G}\,\vol_{^\pm I\times_f [a,b]})$ satisfies\\$\CD(\kappa N, N+~1)$ or $\tCD_p({{-}}\kappa N,N+1)$, respectively. 
\end{thm}
\begin{proof} We only prove the statement in the case $I=\I$.


If $h$ is smooth, then  $G$ satisfies  \eqref{eq:fct} in Corollary \ref{cor:fct}. 
Then \Cref{Co: 2-dim smooth warped product} and the second part in  Theorem \ref{thm:smoothcd} yield the claim. 

If $h$ is not smooth, the conclusion follows from \Cref{Co: 2-dim smooth warped product}, \Cref{prop:concave}, and  again the second part in Theorem \ref{thm:smoothcd}.
\end{proof}
{In the following we will prove  a converse of \Cref{Th:2 dimensional non-smooth case} above, i.e., the assumptions on $h$ and $f$ are in general not only sufficient for $(^\pm I \times_f [a,b], G\vol_{I\times_f [a,b]})$ to satisfy a curvature-dimension condition but also necessary.  

We start with the case where $h$ is smooth in \Cref{Le:from Y to X 2 dim and h smooth} below and then decrease the regularity of $h$ to $L^\infty_\loc((a,b))$ in \Cref{Pr:from Y to X 2 dim and h semi-concave}.} 


\begin{lem}\label{Le:from Y to X 2 dim and h smooth}
Assume that $h:[a,b]\rightarrow [0, \infty)$  and $f:{}^\pm\! I \rightarrow [0, \infty)$ are smooth, $\partial I= f^{-1}(\{0\})$ (if $\partial I\neq \emptyset$) and $$\left(^\pm \!I\times_f[a,b], f(t)^N h(r)\,\dint t\otimes\dint r\right)$$ satisfies $\CD(N\kappa, N+1)$ or $\tCD_p({{-}}\kappa N, N+1)$ for $0<p<1$.

If we consider $I={^+}\!I$, then we assume additionally $\partial I\neq \emptyset$. 
Then it follows that 
\begin{enumerate}
    \item $f''\pm \kappa f\leq 0$, 
    \item $([a,b], h(r)\,\dint r)$ satisfies $\CD((N-1)\eta, N)$ with $\eta= \sup_I\left\{\pm (f')^2 + \kappa f^2\right\}$.
\end{enumerate}
\end{lem}

\begin{proof}[{Proof of Lemma \ref{Le:from Y to X 2 dim and h smooth}}] {\bf 1.} We first consider the case of $I={^-\!I}$.

Since the generalized cone under consideration is smooth the $(N+1)$-Ricci tensor is well-defined and is given explicitly by
$$\Ric_{^-\!I\times_f [a,b]} - (N-1)\frac{\nabla^2 (f^{N-1} h)^{\frac{1}{N-1}}}{(f^{N-1} h)^{\frac{1}{N-1}}}.$$
In combination with the formulas for $\Ric_{{}^-\!I \times_f [a,b]}$ and the Hessian $\nabla^2 G$ with $G=f^{N-1} h$, this can equivalently be written as follows
\begin{enumerate}
\item $\Ric_{^-\!I\times^N_f [a,b]}(\partial_t,\partial_t)= \Ric_I(\partial_t,\partial_t)- N\frac{\nabla^2 f(\partial_t,\partial_t)}{f}= - N \frac{f''}{f}.$
\item $\Ric_{^-\!I\times^N_f [a,b]}(\partial_t,\partial_r)= 0.$
\item $\Ric_{^-\!I\times^N_f [a,b]}(\partial_r,\partial_r)= \Ric_{[a,b]}(\partial_r,\partial_r) - (N-1)\smash{\frac{\nabla^2 h^{\frac{1}{N-1}}}{h^{\frac{1}{N-1}}}}- \left( \frac{\smash{\Delta^{\!^-\!I}} f}{f} + (N-1) \frac{\pm (f')^2}{f^2} \right) \langle \partial_r,\partial_r\rangle$\\
 $\,\,\hspace*{3cm}= -(N-1)\frac{\left(h^\frac{1}{N-1}\right)''}{h^{\frac{1}{N-1}}}-\left(\frac{- f''}{f}+ (N-1)\frac{\pm(f')^2}{f^2}\right) f^2.$
\end{enumerate}
By {\Cref{thm:smoothcd}} the condition $\textsf{TCD}_p({{-}}\kappa N,N+1)$ on $\smash{{}^-I\times^N_f [a,b]}$ is equivalent to the bound $\smash{\Ric_{^-\!I\times^N_f [a,b]}}\geq \kappa N g_{{}^-I\times_f^{N} [a,b]}$ (keeping in mind our signature convention). Hence, by (i) above it follows that $\smash{-N\frac{f''}{f}\geq   -N\kappa}$, i.e.,  $f''- \kappa f\leq 0$. 

By (iii) and again the curvature assumption we have that
\begin{align}\label{Eq:lower Ricci1}
    -(N-1)\frac{\left(h^\frac{1}{N-1}\right)''}{h^{\frac{1}{N-1}}}&\geq N\kappa f^2 + \left(-\frac{ f''}{f}+ (N-1)\frac{-(f')^2}{f^2}\right) f^2\nonumber\\
    &=(N-1)(-(f')^2+\kappa f^2)
    %+(-\vert f'\vert^2-\kappa f^2)
    +f\underbrace{(- f''+\kappa f)}_{\geq 0 \  (\dagger)}\geq (N-1)(-(f')^2+\kappa f^2).
\end{align} 

With the formula above {and the non-negativity of $f$} it follows that, at every point $(t, r)\in \I\times_f [a,b]$ with $r\in [a,b]$ and $t\in I$ arbitrary, we have that
$$-(N-1)\frac{\left(h^\frac{1}{N-1}\right)''}{h^{\frac{1}{N-1}}}\geq (N-1) \eta.$$
\noindent
{\bf 2.} Now we consider the case $I=  {^+\!I}$ where we assume $\partial I\neq \emptyset.$

The argument is the same, except for the last estimate $(\dagger)$ in \eqref{Eq:lower Ricci1}. Instead of $-f''+\kappa f\geq 0$ we have $f''+\kappa f\leq 0$ in
\begin{align}\label{Eq:lower Ricci1.1}
    -(N-1)\frac{\left(h^\frac{1}{N-1}\right)''}{h^{\frac{1}{N-1}}}\geq (N-1)((f')^2+\kappa f^2)
    +f{( f''+\kappa f)}.
\end{align} 
Evaluating at points $(t,r)$ with $t\in \partial I$ we get  that 
$$
  -(N-1)\frac{\left(h^\frac{1}{N-1}\right)''}{h^{\frac{1}{N-1}}}\geq (N-1) \sup_{\partial I} (f')^2.
$$
Finally, by Lemma 3.1 in \cite{AB:04} the claim follows. 
\end{proof}
\begin{rem}
 Considering the formula \eqref{Eq:lower Ricci1.1} it is clear that we obtain the partial converse, i.e., the sharp lower curvature bound $\eta=\sup_I \{(f')^2+f^2\}$ for $([a,b], h(r)\,\dint r)$ also if we assume that $f''+\kappa f=0$. In this case $\eta=\sup_I \{(f')^2+f^2\}= (f')^2 + f^2$.
\end{rem}
We now want to extend \Cref{Le:from Y to X 2 dim and h smooth} to the case where $h$ is semi-concave.
For this we introduce the following regularisations of $h$ (cf.\ \cite{CM:17b}).
\begin{defi}[Power-like convolutions]\label{Le:power-convolutions}
   Let $h:[a,b]\rightarrow(0,\infty)$ be a continuous function and $\phi$ a standard mollifier as in the proof of Proposition \ref{prop:concave}. Define the following ``power-like" convolutions $h^\eps$ as
   \begin{align}\label{Eq:power-like convolutions}
       h^\eps(r):=\left[h^{\frac{1}{N+1}}*\phi_\eps(r)\right]^{N+1} =\left[\int_\R h(r-y)^{\frac{1}{N+1}}\phi_\eps(y)\,\dint y\right]^{N+1}.
   \end{align}
   \end{defi}
As in \cite[Lem.\ 6.2]{CM:17b} these convolutions have the following properties:
 \begin{itemize}
       \item [(i)] $h^\eps$ is a non-negative smooth function on $[a+\eps, b-\eps]$.
       \item[(ii)] $h^\eps\rightarrow h$ uniformly on compact subsets of $(a,b)$ as $\eps\rightarrow0$.
   \end{itemize}
   \begin{rem}[The case {$h\in L^\infty_\loc((a,b))$}]\label{rem:pwc}
       If $h$ is in $L_{\loc}^\infty((a,b))$, then $h^\eps$ converges to $h$ in $L^p_{\loc}([a+\eps, b-\eps])$ for $p\in [1,\infty)$. So in particular, after picking a subsequence $h^\eps$ converges to $h$ pointwise almost everywhere. We also notice that $h^\eps$ is uniformly bounded. 
   \end{rem}

In the following we denote by $Y^\eps$ the  $N$-generalized cone given by $\smash{{^\pm}\!I\times^N_f[a+\eps,b-\eps]}$ and we endow it with the volume measure $\n^\eps(\dint t,\dint r):=f(t)^{{N-1}}h^\eps(r)\,\dint t\otimes\dint r$. {Recall also  the function $\Phi(t,r):=\log(f(t)^{{N-1}}h(r))$ from \Cref{Co: 2-dim smooth warped product}} and let $\Phi^\eps$ be analogously defined with $h^\eps$ in place of $h$.
\begin{lem}[Curvature-dimension bounds for $Y^\eps$]\label{Le: Yeps}
    Assume that the $N$-generalized cone $Y$ satisfies $\tCD_p(\kappa N,N+1)$ or $\CD(\kappa N,N+1)$, respectively. Then also $Y^\eps$ does.
\end{lem}
\begin{proof} We only present the proof for the Lorentzian case, i.e., $Y^\varepsilon={^-}\!I\times^{N}_f (a+\eps,b-\eps)$, because the Riemannian case works in an analogous manner (in fact, even simpler). 

Considering $Y^\varepsilon$, the underlying Lorentzian manifold ${^-}\!I\times_f (a+\eps,b-\eps)$  is smooth and $Y^{\eps'}\subseteq Y^\eps$ if $\eps\in (0, \eps')$.  The Lorentzian reference measure is $f(t)\,\dint t \otimes\dint r$. Given $(\mu_0,\mu_1)\in\mathscr{P}^\mathrm{ac}_{\textnormal{c}}(Y)$ $p$-dualizable by an optimal geodesic plan $\boldsymbol{\pi}\in\mathrm{OptTGeo}(Y)$, denote the $\ell_p$-geodesic between $\mu_0$ and $\mu_1$ by $(\mu_s)_{s\in[0,1]}$. We assume $\spt \mu_s\subseteq I\times_f (a+\eps, b-\eps)$. Then by \cite{McC:20} for $\mu_s\ll\n$ with $\mu_s= \zeta_s \n$ for $\boldsymbol{\pi}$-a.e.\ $\gamma=(\alpha,\beta)$ it holds that
\begin{align*}
    \zeta_s(\gamma_s)=f(\alpha_s)^{-(N-1)}h(\beta_s)^{-1}\rho_s(\alpha_s,\beta_s)
\end{align*}
where $\rho_s(T_s(x))=\det DT_s(x)^{-1} \rho_0(x)$ ($s\in [0,1]$), is the density of $\mu_s$ w.r.t.\ $f(t)\,\dint t\otimes \dint r$, and $T_s$ is the optimal transport map between $\mu_0$ and $\mu_s$, i.e., $(T_s)_\sharp\mu_0=\mu_s$, which exists due to \cite{McC:20}.

Now the key observation is that the $\ell_p$-geodesic between $\mu_0$ and $\mu_1$  in $Y^\eps$ is  $\mu_s$, independently of $\varepsilon$. Replacing $h$ with $h^\eps$ only changes the density {$\zeta_s$}, since the metric structure of $Y^\eps$ is the same as the one of $Y$. More precisely, the density $\zeta^\eps_s$ of $\mu_s$ w.r.t.\ $\n^\eps$ is
\begin{align}
    \zeta_s^\eps(\gamma_s)=f(\alpha_s)^{-(N-1)}h^\eps(\beta_s)^{-1}\rho_s(\alpha_s,\beta_s).
\end{align}
Then we are left to prove that $Y^\eps$ is $\tCD_p(\kappa N,N+1)$.

Recall that for timelike essentially nonbranching spaces, due to \cite[Thm.\ 3.35, Rem.\ 3.36 and Thm.\ 3.41]{Bra:23b}, for every $\n$-absolutely continuous pair $(\mu_0,\mu_1)=(\zeta_0\n,\zeta_1\n)$ timelike $p$-dualized by $\boldsymbol{\pi}$,
and denoted by $\mu_s=\zeta_s\n$ their optimal $\ell_p$-geodesic, $\tCD_p(\kappa N,N+1)$ is equivalent for $\boldsymbol{\pi}$-a.e.\ $\gamma$ to
$$\zeta_s(\gamma_s)^{-\frac{1}{N+1}}\geq\tau_{\kappa N,N+1}^{(1-s)}(\uptau(\gamma_0,\gamma_1))\zeta_0(\gamma_0)^{-\frac{1}{N+1}}+\tau_{\kappa N,N+1}^{(s)}(\uptau(\gamma_0,\gamma_1))\zeta_1(\gamma_1)^{-\frac{1}{N+1}}.$$
From our assumption
that $Y$ is $\tCD_p(\kappa N,N+1)$ we get for $\boldsymbol{\pi}$-a.e.\ $\gamma_s=(\alpha_s,\beta_s)$
\begin{align*}
    \bigg[h^\eps(\beta_s)^{-1}&f(\alpha_s)^{-(N-1)}\rho_s(\alpha_s,\beta_s)\bigg]^{-\frac{1}{N+1}}\\
    &=\left[\left(\int_\R h(\beta_s-y)^{\frac{1}{N+1}}\phi_\eps(y)\,\dint y\right)^{-(N+1)}f(\alpha_s)^{-(N-1)}\rho_s(\alpha_s,\beta_s)\right]^{-\frac{1}{N+1}}\\
    &=\left[\left(\int_\R\left(h(\beta_s-y)^{-1}f(\alpha_s)^{-(N-1)}\rho_s(\alpha_s,\beta_s)\right)^{-\frac{1}{N+1}}\phi_\eps(y)\,\dint y\right)^{-(N+1)}\right]^{-\frac{1}{N+1}}\\
    &\geq\int_\R\Big[\tau_{\kappa N,N+1}^{(1-s)}(\uptau(\gamma_0,\gamma_1))\left(h(\beta_0-y)^{-1}f(\alpha_0)^{-(N-1)}\rho_0(\alpha_0,\beta_0)\right)^{-\frac{1}{N+1}}\\
    &\hspace{2cm}+\tau_{\kappa N,N+1}^{(s)}(\uptau(\gamma_0,\gamma_1))\left(h(\beta_1-y)^{-1}f(\alpha_1)^{-(N-1)}\rho_1(\alpha_1,\beta_1)\right)^{-\frac{1}{N+1}}\Big]\phi_\eps(y)\,\dint y\\
    &=\tau_{\kappa N,N+1}^{(1-s)}(\uptau(\gamma_0,\gamma_1))f(\alpha_0)^\frac{N-1}{N+1}\rho_0(\alpha_0,\beta_0)^{-\frac{1}{N+1}}\int_\R h(\beta_0-y)^{\frac{1}{N+1}}\phi_\eps(y)\,\dint y\\
    &\hspace{2cm}+\tau_{\kappa N,N+1}^{(s)}(\uptau(\gamma_0,\gamma_1))f(\alpha_1)^\frac{N-1}{N+1}\rho_1(\alpha_1,\beta_1)^{-\frac{1}{N+1}}\int_\R h(\beta_1-y)^{\frac{1}{N+1}}\phi_\eps(y)\,\dint y\\
    &=\tau_{\kappa N,N+1}^{(1-s)}(\uptau(\gamma_0,\gamma_1))\left(h^\eps(\beta_0)^{-1}f(\alpha_0)^{-(N-1)}\rho_0(\alpha_0,\beta_0)\right)^{-\frac{1}{N+1}}\\
    &\hspace{2cm}+\tau_{\kappa N,N+1}^{(s)}(\uptau(\gamma_0,\gamma_1))\left(h^\eps(\beta_1)^{-1}f(\alpha_1)^{-(N-1)}\rho_1(\alpha_1,\beta_1)\right)^{-\frac{1}{N+1}},
\end{align*}
which shows the displacement convexity for  $(\mu^\eps_s)_{s\in[0,1]}$ in $Y^\eps$. Since $\mu_0, \mu_1\in \mathscr{P}^{\mathrm{ac}}_{\textnormal{c}}(Y)$ with $\spt\mu_s$ in $Y^\eps$ are arbitrary, $\tCD_p(\kappa N, N+1)$ for $Y^\eps$ follows. 

If we instead assume that $Y$ satisfies $\CD(\kappa N,N+1)$ in place of its timelike counterpart, up to replacing $\uptau(\gamma_0,\gamma_1)$ with $\met(\gamma_0,\gamma_1)$ and not assuming timelike $p$-dualizability of $(\mu_0,\mu_1)\in\mathscr{P}^\mathrm{ac}_{\textnormal{c}}(X)$ because of the absence of causality, we get that $Y^\eps$ satisfies $\CD(\kappa N,N+1)$ too.
\end{proof}
Now we want to prove that the previous \Cref{Le:from Y to X 2 dim and h smooth} holds just assuming that $h$ is {$L^\infty_\loc((a,b))$}.
\begin{cor}[2-dimensional case, from $Y$ to $(a,b)$ with $h$ in $L^\infty_{\loc}((a,b))$]\label{Pr:from Y to X 2 dim and h semi-concave}
     Assume that $h:~[a,b]\rightarrow [0, \infty)$ is in $L^\infty_{\loc}((a,b))$ and $f:{}^\pm\! I \rightarrow [0, \infty)$ is smooth. Assume 
     $$\left(^\pm \!I\times_f[a,b], f(t)^N h(r)\,\dint t\otimes\dint r\right)$$
     satisfies $\CD(\kappa N, N+1)$ or $\tCD_p(-\kappa N, N+1)$, respectively. If we consider $I={^+}\!I$, then we assume additionally $\partial I\neq \emptyset$. Then it still follows that 
\begin{enumerate}
    \item $f''\pm \kappa f\leq 0$, 
    \item $([a,b], h(r)\,\dint r)$ satisfies $\CD((N-1)\eta, N)$ with $\eta= \sup_I\left\{\pm (f')^2 + \kappa f^2\right\}$.
\end{enumerate}
    In particular $h$ is semi-concave on $[a,b]$ and continuous on $(a,b)$.
\end{cor}
\begin{proof}
    From \Cref{Le: Yeps} we know that $Y^\eps$ satisfies $\CD(\kappa N,N+1)$, respectively $\tCD_p(\kappa N,N+1)$. We can consider the two cases simultaneously. 

    By construction $Y^\eps$ is smooth, so we can apply Lemma \ref{Le:from Y to X 2 dim and h smooth} directly. 
   % write down $\Ric_{Y^\eps}^{\Phi^\eps,N}$ explicitly and use the same formulas (i), (ii) and (iii) used in \Cref{Le:from Y to X 2 dim and h smooth}. 
    More specifically, from  \Cref{Le:from Y to X 2 dim and h smooth}, formula (i) there, we  get
    $$f''\pm\kappa f\leq0$$
    which does not depend on $\varepsilon$. 

    Also by Lemma \ref{Le:from Y to X 2 dim and h smooth}
    the densities $h^\eps$ are $\CD(\eta(N-1),N)$-densities {on $(a+\eps, b-\eps)$}, i.e.,
    \begin{align}\label{aboveabove}
    \left(\left(h^\eps\right)^{\frac{1}{N-1}}\right)''+\eta\left(h^\eps\right)^\frac{1}{N-1}\leq0 \ \mbox{ where } \eta=\sup_I\{ \pm(f')^2 + \kappa f^2\}.
    \end{align}  
    Notice that the sharp estimate with $\eta$ follows from the assumptions on $f$.
In particular, thanks to Remark \ref{Re:properties of CD(K,N)-densities and logarithmic convolutions},(ii), $h^\eps$ is semi-concave.

Moreover $h^\varepsilon$ converges pointwise a.e.\ to $h$ in $(a,b)$ by Remark \ref{rem:pwc}. {We suppress the fact that $h^\eps$ is only defined on $(a+\eps, b-\eps)$, but it is clear that this is not important for the argument.}  The differential inequality for $h^\varepsilon$ above is equivalent to the property that the integrated inequality 
$$h^\varepsilon((1-s)r_0 +s r_1)^{\frac{1}{N-1}}\geq \sigma_{\eta(N-1),N-1}^{(1-s)}(|r_1-r_0|) h^\varepsilon(r_0)^{\frac{1}{N-1}}+\sigma_{\eta(N-1),N-1}^{(s)}(|r_1-r_0|) h^\varepsilon(r_1)^{\frac{1}{N-1}}$$
holds along any geodesic of the form $\varsigma(s):=(1-s)r_0 + s r_1$ in $(a,b)$.

%The latter inequality is stable w.r.t.\ uniform convergence of $h^\varepsilon\rightarrow h$ on compact subsets in $(a,b)$. 
For fixed  points $r_0, r_1\in (a,b)$ and $s\in [0,1]$ the latter inequality is stable when $h_\eps$ converges to $h$ in the points $r_0, r_1$ and $(1-s)r_0+ sr_1=:r_2$. Note that we can write $s= \frac{r_2-r_0}{r_1-r_0}$.

Since we assume  that $h_\eps$ converges to $h$ pointwise a.e.\ in $(a,b)$, there exists a subset $\mathcal D$ in $(a,b)$ such that $(a,b)\setminus \mathcal D$ has Lebesgue measure $0$, and $h^\eps$ converges pointwise everywhere on $\mathcal D$ to $h$. It follows that for all $r_0<r_1\in \mathcal D$ and for all $r_2\in \mathcal D\cap (r_0,r_1)$, we have 
\begin{align}\label{above}
h(r_2)^{\frac{1}{N-1}}\geq \sigma_{\eta(N-1),N-1}^{(1-s)}(|r_1-r_0|) h^\varepsilon(r_0)^{\frac{1}{N-1}}+\sigma_{\eta(N-1),N-1}^{(s)}(|r_1-r_0|) h^\varepsilon(r_1)^{\frac{1}{N-1}}
\end{align}
where $s=\frac{r_2-r_1}{r_1-r_0}$. In particular, $h$ is locally Lipschitz  on $\mathcal D\cap (a,b)$. Since $\mathcal D$ is also a dense subset, $h|_{\mathcal D}$ admits a unique continuous extension on every compact subset in $(a,b)$. Hence, there exists a continuous function $\tilde h$ on $(a,b)$ that coincides almost everywhere with $h$. Hence, we found a continuous representative on $(a,b)$ of $h$ and we identify $h$ with $\tilde h$. 

Since $h$ is continuous on $(a,b)$, it satisfies the inequality \eqref{above} for all $r_0,r_1\in (a,b)$ and $s\in [0,1]$. In particular, it follows that $h$ satisfies the differential inequality \eqref{aboveabove} in the distributional sense on $(a,b)$. Consequently $h$ is a $\CD(\eta (N-1), N)$-density on $(a,b)$. {Moreover, since $h^\eps$ is uniformly bounded, $h$ is bounded by the same constant. Hence, by setting 
$$h(a)= \liminf_{r\downarrow a} h(r)<\infty, \ \ h(b)=\liminf_{r\uparrow b} h(r)<\infty,$$ we can define a lower semi-continuous version of $h$ on $[a,b]$ with values in $[0,\infty)$. } Moreover, $h$ semi-concave on $[a,b]$ thanks again to Remark \ref{Re:properties of CD(K,N)-densities and logarithmic convolutions},(ii).
\end{proof}

We want to further generalize the previous result. First we prove the following lemma. 
\begin{lem}\label{lem:2Dmcp}
     Let  $([a,b], \m)$ be a metric measure space where $\m$ is a Radon measure with $\spt \m=~[a,b]$ and assume $f:{}^\pm\! I \rightarrow [0, \infty)$ is smooth with $\partial I = f^{-1}(\{0\})$. Assume that 
     $$\left(^\pm \!I\times_f[a,b], f(t)^N \dint t\otimes \m\right)$$
     satisfies $\mcp(\kappa N, N+1)$ or $\tmcp(N\kappa, N+1)$, respectively.  Then it  follows that $\m\ll\mathcal{L}^1$ with
  $\m= h(r)\,\dint r$, where  $h\in L^\infty_{\loc}((a,b))$.
\end{lem}

\begin{proof} 
In the positive signature case $I={}^+\!I$ we can apply \cite[Prop.\ 3.1]{Han:20}: the space $I\times_f [a,b]$ is equipped with the measure $f(t)^N \dint t \otimes \m$ and it satisfies a measure contraction property, hence {from the mentioned result} it follows that
$$f(t)^N\dint t \otimes \m= \Phi(t,r) f(t)\,\dint t \otimes \dint r\ \mbox{ with }\Phi\in L^\infty_{\loc}(I\times_f (a,b)). $$
In particular $\m= h(r)\,\dint r$ for $\smash{h\in L^\infty_{\loc}((a,b))}$. 

For the negative signature case $I=\I$ we  do not have an analogue of Han's theorem. Therefore we argue as follows. We pick any point $(t,r)=p\in\I\times_f [a,b]$ and consider {the function} $u=\uptau(p,\cdot)$ on $I^+(p)$, the timelike future of $p$. The spacetime $\I\times_f [a,b]$ can be endowed with the measure $f(t)^N\,\dint t \otimes \m$ or with the measure $f(t)\,\dint t\otimes\dint r$, that is the Lorentzian volume of $^-I\times_f[a,b]$. In both cases  a measure contraction property is satisfied. 

The time separation function is the same in both cases. It gives a measurable decomposition $\{X_q\}_{q\in Q}$ of $I^+(p)$ into timelike geodesics w.r.t.\ $u$. 
This  yields  disintegrations

\begin{align}\label{Eq:emms}
    f(t)^N\,\dint t\otimes \m= \int_Q \m_q \,\dint \mathfrak q(q), \qquad f(t)\,\dint t\otimes \dint r= \int_Q  \tilde \m_q \,\dint \tilde{\mathfrak q}(q),
\end{align}
where $\mathfrak q$ and $\tilde{\mathfrak q}$ are measures on the quotient space $Q$. Moreover, since a measure contraction property holds, $\m_q=h_q(r) \,\dint r$ and $\tilde \m_q= \tilde h_q(r)\,\dint r$ are absolutely continuous w.r.t.\ the Lebesgue measure, with densities in $L^\infty_{\loc}((a_q, b_q))$ that have full support in $[a_q,b_q]$ \cite[Thm.\ 4.18]{CM:24a}. {It is worth noting that $Q$ is a smooth manifold since the underlying space is smooth and $u$ is the distance function to a point, but this fact does not play a role.} 

We consider the Lebesgue decomposition of $\m$ w.r.t.\ the Lebesgue measure, that is\\ $\m=~h\mathcal L^1 +~\m^s$.  There exists a measurable set $S\subseteq[a,b]$ such that $\mathcal L^1(S)=0$ and $\m^s= \m|_S$. We claim that $\m(S)=0$.

Assume by contradiction that $\m(S)>0$ and set $C=I\times S$. Then 
$$\int_C f({t})^N\,\dint {t}\, \dint\m>0 \quad \mbox{ but } \quad \int_Cf({t})\,\dint {t} \,\dint \mathcal L^1=0.$$

Recall that up to $\mathfrak q$-null sets the minimal geodesic segment $X_q$ is isometric to an interval with endpoints $a_q, b_q\in \R\cup\{\pm \infty\}$. We denote the relative interior of $X_q$ with ${X}^\circ_q$, i.e., $X_q^\circ \simeq (a_q, b_b)$. 

 It follows that there exists a set $P\subseteq Q$ with $\mathfrak q(P)>0$ and a set $N\subseteq Q$ with $\mathfrak q(N)=0$ such that $\m_q(C)=\m_q(C\cap X_q)>0$, $\m_q=h_q\,\mathcal L^1$  and $X^\circ_q\simeq (a_q, b_q)$ for for all $q\in P\setminus N$. If we pick such $q\in P\setminus N$, then the set $C_q= C\cap X_q^\circ\subseteq(a_q, b_q)$ satisfies $\mathcal L^1(C_q)>0$. The latter property holds since ${\int_{C_q}h_q \,\dint\mathcal L^1= \m_q(C_q)>0}$. 

Since $\mathfrak q(P\setminus N)>0$, we can pick such a $q\in P\setminus N$. 

Moreover, there can be only at most one $q\in P\setminus N$ such that $X_q\subseteq(I\times\{\tilde r\})$ for some $\tilde r\in [a,b]$ since every segment $X_q$ starts in the point $p$.



Since $\m_q(C_q)>0$, it holds necessarily that $C_q= (I\times S) \cap X^\circ_q\neq \emptyset$.  
We can pick one $s\in S$ such that $(I\times\{s\})\cap X^\circ_q\neq \emptyset$. 
A neighbourhood $U(s)= (s-\eta, s+ \eta)\subseteq(a,b)$ of $s$ has the property, that $I\times\{\tilde s\}\cap X_q^\circ\neq \emptyset$ for every $\tilde s\in U(s)$.  There are two cases: either $(1)$ each $I\times \{\tilde s\}$  intersects with $X_q^\circ$ only once, or $(2)$ $X_q^\circ \subseteq I\times\{s\}$. This is a property of geodesics in smooth spaces. 

Let us assume $(1)$. We can define a map $F_s: \tilde s\in U(s)\mapsto X_q^\circ \cap( I\times\{\tilde s\})$.  Notice that the image $F_s(S\cap (s-\eta, s+\eta))$ of $S$ under $F_s$ is exactly the set $(I\times (S\cap (s-\eta, s+\eta))) \cap X_q^\circ$. This map is clearly smooth on $(s-\eta, s+\eta)$. Hence $F_s(S\cap (s-\eta, s+\eta))$ is a $\mathcal L^1$-null set in $X_q^\circ$. We can cover $X_q\cap C$ with a countable number of such sets. Consequently $C_q$ is a $\mathcal L^1$-null set. But this contradicts $\mathcal L^1(C_q)>0$. 

Hence, only $(2)$ happens, i.e., $X_q^\circ \subseteq I\times \{s\}$. In particular, $p\in I\times \{s\}$. But this is a contradiction if we choose $p\notin C$. 


Hence there exists a measurable function $h: [a,b]\rightarrow [0,\infty)$ such that $\m=h\,\dint \mathcal L^1$. In particular, by \eqref{Eq:emms} we have $\m_q= f^{N-1}h\, \tilde \m_q$ for $\mathfrak q$-a.e.\ $q$ and therefore $h_q= f^{N-1}h \tilde h_q$ for $\mathfrak q$-a.e $q$. This is true for an arbitrary disintegration. Since $h_q$ and $\tilde h_q$ are in $L^\infty_{\loc}([a_q, b_q])$ it follows that  $h\in L^\infty_{\loc}((a,b))$.  
\end{proof}
\begin{thm}\label{th:lasttheorem}
     Let  $([a,b], \m)$ be a metric measure space for a Radon measure $\m$ with $\spt \m=~[a,b]$ and let $f:{}^\pm\! I \rightarrow [0, \infty)$ be smooth with $\partial I= f^{-1}(\{0\})$. Assume 
     $$\left(^\pm \!I\times_f[a,b], f(t)^N \dint t\otimes \m\right)$$
     satisfies $\CD(\kappa N, N+1)$ or $\tCD_p(-\kappa N, N+1)$, respectively, with $\kappa\in \R$ and $N>1$. If we consider $I={^+}\!I$, then we assume additionally $\partial I\neq \emptyset$. Then it  follows that 
\begin{enumerate}
    \item $f''\pm \kappa f\leq 0$, 
    \item $([a,b], \m)$ satisfies $\CD((N-1)\eta, N)$ with $\eta= \sup_I\left\{|f'|^2 + \kappa f^2\right\}$.
\end{enumerate}
    In particular, $\m= h(r)\,\dint r$ where  $h$ is semi-concave on $[a,b]$ and continuous on $(a,b)$.
\end{thm}
\begin{proof}
    Since under the assumption of the theorem a curvature-dimension condition always implies a measure contraction property, the corollary is a consequence of the previous lemma and Corollary \ref{Pr:from Y to X 2 dim and h semi-concave}.
\end{proof}


\section{From the fiber to the generalized cone \texorpdfstring{$Y$}{Y}}\label{sec-fib-Y}
Throughout this section we assume that $f:I\rightarrow[0,\infty)$ is smooth and satisfies
\begin{itemize}
    \item $f''- \kappa f\leq 0$, 
    \item $-(f')^2 + \kappa f^2 \leq \eta$. 
\end{itemize}
\begin{rem}
We note that we could replace $\kappa\in \R$ by $-\kappa\in \R$. Then the assumptions would take the 
 equivalent form\begin{itemize}
    \item $f''+\kappa f\leq 0$, 
    \item $(f')^2 + \kappa f^2 \geq -\eta$. 
\end{itemize}
\end{rem}
The main purpose of this section is to prove the following result.

\begin{thm}[From $X$ to ${}^-\!I\times^N_fX$] \label{th:totmcp}
Assume that $(X,\met,\m)$ is an essentially nonbranching metric measure space satisfying $\CD(\eta (N-1), N)$ for $N>1$, and $f: I \rightarrow [0, \infty)$ is smooth as above. Then ${}^-\!I\times_f^N X$, i.e., the generalized cone ${}^-\!I\times_f X$ equipped with the measure $f(t)^N \,\dint t \otimes\dint\m$, satisfies $\tmcp(-\kappa N, N+1)$. 
\end{thm}
%\begin{rem} Since a $\CD(K,1)$ space is necessarily an interval in $\R$ or just a point, the case $N=1$ is already covered by \Cref{Co: 2-dim smooth warped product}.\end{rem}


We first prove a preliminary lemma.
Recall the following set
$$\Geo(X)= \{\bar \beta:[0,1]\rightarrow X: \bar \beta \mbox{ is a constant speed geodesic}\}.$$
The set $\Geo(X)$ is endowed with the uniform distance $\smash{\met_\infty(\bar \beta_0, \bar \beta_1)= \sup_{ s\in [0,1]}\met_X(\bar \beta_0(s), \bar \beta_1(s))}$.
\begin{lem}[{{Measurable selection}}]\label{Lem:selection}
There exists a  measurable map $$\Psi^+: I^+((\bar t, \bar x))\subseteq \I\times_f X\longrightarrow \TGeo(\I\times_fX)$$ such that $\Psi^+(t,x)$ is the unique future-directed timelike geodesic between $(\bar t, \bar x)$ and $(t, x)$ with speed $\uptau((\bar t, \bar x), (t,x))$. 

Similarly, there exists an $\n$-a.e.\ defined measurable map  $$\Psi^-: I^-((\bar t, \bar x))\subseteq \I\times_f X\longrightarrow \TGeo(\I\times_fX)$$ such that $\Psi^-(t,x)$ is a future-directed timelike geodesic between  $(t, x)$ and $(\bar t, \bar x)$ with speed $\uptau((t, x), (\bar t, \bar x))$.

Moreover, $\Psi^-(t,x)$ is the unique future-directed geodesic between $(t,x)$ and $(\bar t, \bar x)$.

\end{lem}
\begin{proof}[Proof of Lemma \ref{Lem:selection}] We prove the statement for $\Psi^+=:\Psi$. 

Since $X$ satisfies the condition $\CD(\eta (N-1), N)$ {and is essentially nonbranching}, for a fixed $\bar x\in X$ there exists an $\m$-almost everywhere defined, measurable map $$\Phi: X\rightarrow \mbox{Geo}(X)$$
 such that $\Phi(x)=: \bar\beta_x$ satisfies $\bar \beta_x(0)=x$ and $\bar \beta_x(1)=\bar x$, and $\bar \beta_x:[0,1]\rightarrow X$ is the unique constant speed geodesic between $x$ and $\bar x$. 
 \smallskip\\
 {\it Remark:}
 We note that by use of a measurable selection theorem   there always exist a measurable map $\Phi$ that assigns to $x\in X$ a geodesic between $\bar x$ and $x$ {\cite[Lem.\ 2.11]{AG:13}, \cite[Thm.\ 6.9.2]{Bog:07b}.} Moreover, provided $X$ is an essentially nonbranching $\CD$ space it  follows from \cite[Corollary 5.4]{CM:17a} that for $\m_X$-a.e.\ $x$ there is exactly one geodesic between $\bar x$ and $x$. This yields $\Phi$ with the claimed properties.
\smallskip

For  $(t,x)\in I^+((\bar t, \bar x))\subseteq I\times_f X$, such that $\Phi(x)=\bar\beta_x$ is defined, we  consider a future-directed timelike geodesic $\gamma=(\alpha, \beta):[0,1]\rightarrow \I\times_f X$ between $(\bar t, \bar x)$ and $(t, x)$, parametrized proportional to {$\uptau$-}arclength, i.e., $\sqrt{\dot \alpha - (f^2 \circ \alpha) v_\beta}\equiv \uptau((\bar t, \bar x), (t,x))$.  According to Theorem \ref{th:fiber}  $\beta: [0, 1] \rightarrow X$ is a length minimizer and therefore a pre-geodesic between $\bar x$ and $x$, hence a reparametrization of $\bar \beta_x$. Moreover, $\gamma$ is the unique geodesic between $(\bar t, \bar x)$ and $(t,x)$, since $\bar \beta_x$ is the unique geodesic between $\bar x$ and $x$.

By Theorem \ref{th:fiber},(ii) $\alpha$ only depends on $\bar t, t$ and $d_X(\bar x, x)=L(\beta)$. In particular, if  we consider the generalized cone $\I\times_f [0, \infty)$ and the geodesic $\tilde \gamma=(\tilde \alpha, \tilde \beta)$ between $(\bar t, 0)$ and $(t, d)$, $d:=\met(\bar x, x)$, where $\gamma$ is defined on $[0,1]$ and parametrized proportional to {$\uptau$-}arclength, we have that $\tilde \alpha= \alpha$. The curve $\tilde \beta:[0,1] \rightarrow [0,d]$ is a reparametrization of $s\in [0,1]\mapsto s\cdot d$, and it holds that $\smash{\beta= \bar \beta_x\circ \frac{1}{d} \tilde \beta}$. Moreover the map $\tilde \Psi$ that assigns to the tuple $(t, d)$ the geodesic $\tilde \gamma$ connecting $(\bar t, 0)$ and $(t, d)$ in $\I\times_f [0, \infty)$, is measurable.  We also recall that the length functional $\L$ on $\mbox{Geo}(X)$ is a measurable map. 

Now we define $\Psi: I\times X\rightarrow {\mathrm{T}}\mbox{Geo}({Y})$ as $$\Psi(r,x):=  \left( P_1\Big[\tilde \Psi\Big(r,  \mathcal L(\Phi(x))\Big)\Big], \Phi(x)\circ \frac{1}{d}\tilde \beta\right)$$
where $P_1$ is the projection to the first component. By definition $\Psi(t,x)$ is the geodesic that connects $(\bar t, \bar x)$ with $(t, x)$, defined on $[0,1]$ and parametrized by {$\uptau$-}arclength.  Since $\Psi$ is a composition of measurable maps, together with a reparametrization of $\Phi(x)$ that depends measurable on the parameters, it is a measurable map. 
%
%The uniqueness statement follows form the uniqueness of $\Phi$ and the fiber independence.
\end{proof}
\begin{cor}\label{cor:plans} Let $(\bar t, \bar x)\in \I\times_f X$ and $\mu$ be an $\n$-absolutely continuous measure with $\spt \mu\subseteq I^+((\bar t, \bar x))$. Then there exists a unique measure $\Pi \in \mathscr P({\mathrm{T}}\mathrm{Geo}(Y))$ such that $(e_1)_\sharp \Pi= \mu$ and $(e_0)_\sharp\Pi= \delta_{(\bar t, \bar x)}$. 

A similar statement holds if $\mu\in I^-((\bar t, \bar x))$. 
\end{cor}
\begin{proof} Let $\Psi$ be the map constructed in the previous lemma. 
We can define the measure $(\Psi)_\sharp \mu=: \Pi$ which does the job. 
\end{proof}
\begin{prop}\label{prop:prop}
Let $(\bar t, \bar x)= \bar p\in  \I\times_f X=Y$ and let $\mu_0$ be an $\n$-absolutely continuous probability measure {with $\supp\mu_0\subseteq I^-((\bar t,\bar p))$}. Let $(\mu_{{s}})_{{s}\in [0,1]}$ be the $\ell_p$-geodesic between $\mu_0$ and  $\delta_{\bar p}=\mu_1$. Then $\mu_s$ is {$\n$-}absolutely continuous with density $\rho_s$ for each ${s}\in [0,1)$ and $\rho_{(1-\eta) s_0 + \eta s_1}$, with $s_0<s_1\in [0,1)$ and $\eta\in [0,1]$, satisfies 
\begin{equation}
    \begin{aligned}\label{ineq:concave}  
         \rho_{\sigma({\eta})}(\gamma_{\sigma({\eta})})^{-\frac{1}{N}}  \geq \tau_{-\kappa N, N+1}^{({1-\eta})}\big({ (s_1-s_0)L(\gamma)}\big) \rho_{s_0}(\gamma_{s_0})^{-\frac{1}{N}}+\tau_{-\kappa N, N+1}^{({\eta})}\big(((s_1-s_0)L(\gamma)\big) \rho_{s_1}(\gamma_{s_1})^{-\frac{1}{N}}
    \end{aligned}
\end{equation}
for $\Pi$-almost every $\gamma\in{\mathrm T\!}\Geo(Y)$ where $\sigma(\eta)=(1-\eta) s_0 + \eta s_1$. 
\end{prop}

\begin{proof}
{\bf 1.} 
We consider $u= \met_{\bar x}:= \met(\cdot, \bar x)$ and perform a $1D$ localization   w.r.t.\ $u$. It follows from Theorem \ref{Th:1Dloc} that there exists a measurable partition $\{X_q\}_{q\in Q}$ of  $X$ (more precisely of the  set $\mathcal T^b_u$, but we have $\smash{\m(X\setminus\mathcal T^b_u)=0}$ since  $u=\met_{\bar x}$). 

This partition yields a disintegration $\{\m_q\}_{q \in Q}$ of $\m$ with measures $\m_q$ supported on $X_q$, as well as a corresponding quotient measure $\mathfrak q$ on $Q$. 

Since $X$ satisfies $\CD(\eta(N-1), N)$ we have the the following properties. 
\begin{itemize}
    \item
For $\mathfrak q$-a.e.\ $q$ the closure $\overline X_q$ is the image of a distance preserving map $ \beta_q: [a_q, b_q]\rightarrow X$. In other words $\overline X_q$ is a geodesically convex subset of $X$ that is isometric to $[a_q,b_q]$ via the distance preserving map $ \beta_q: [a_q,b_q]\rightarrow \overline X_q$.  

\item
For $\mathfrak q$-a.e.\ $q$ there exists $ h_q: [a_q,b_q]\rightarrow [0,\infty)$ such that 
$$\m_q= (\beta_q)_{\sharp}\left[ h_q \, \mathcal L^1|_{\scriptscriptstyle [a_q, b_q]}\right].$$
\item
 For $\mathfrak q$-a.e.\ $q\in Q$ the density $h_q: [a_q, b_q]\rightarrow [0, \infty)$ is a continuous function satisfying 
$$\frac{\dint^2}{\dint s^2} h_q^{\frac{1}{N-1}} + \eta h_q^{\frac{1}{N-1}}\leq 0 \ \mbox{ in the distributional sense in } (a_q,b_q).$$ 
In other words $(X_q, \met|_{\scriptscriptstyle X_q\times X_q}, \m_q)$ satisfies the condition $\CD(\eta(N-1), N)$. This follows from Theorem \ref{Th:CD1} and Remark \eqref{rem:thefollowingremark}.
\end{itemize}
\smallskip
{\bf 2.}
By fiber independence $Y_q:= \I \times_f X_q$ embeds isometrically into $\I\times_f X$ and $\{ Y_q\}_{q\in Q}$ is a measurable decomposition of $Y:=\I\times_f X$. Moreover there is a disintegration of the measure $\n:=f(t)^N\mathcal\dint t \otimes \m$ w.r.t.\ $\{Y_q\}_{q\in Q}$ into 
$$f(t)^N\dint t\otimes \m_q=: \n_q.$$
The quotient measure is $\mathfrak q$, and  $\mathfrak{n}_q$ is supported on $Y_q$ for $\mathfrak{q}$-almost every $q\in Q$.  Also, $\n_q$ has a continuous density w.r.t.\ $\smash{f(t)\,\dint t\otimes{\mathcal{L}^1|_{[a_q,b_q]}}}$ that is $f(t)^{N-1}h_q({r})= G(t,{\mathfrak{G}(q,r)})$ where $\mathfrak G$ is the ray map that we introduced after Theorem \ref{Th:1Dloc}.

Hence, for $\mathfrak q$-a.e.\ $q$ the subset $Y_q$ equipped with $\n_q$ is the generalized $N$-cone over $([a,b], \m_q)$ w.r.t.\ $\I$ and $f$ and  satisfies the condition $\tCD(\kappa N, N+1)$ by \Cref{Th:2 dimensional non-smooth case}.
\smallskip\\
{\bf 3.}
 Let us consider an $\n$-absolutely continuous measure $\mu:=\mu_0$, i.e., $\mu= \rho \n$ for a measurable function $\rho$.  Let $\Pi$ be the measure given by Corollary \ref{cor:plans}.

The disintegration of $\n$ into $\{\n_q\}_{q\in Q}$ yields for $\mathfrak{q}$-a.e.\ $q\in Q$ absolutely continuous measures $\mu_q:= \rho \,\n_q=$ with respect to $\n_q$ such that 
$$ \int_{{Q}}  \mu_q \,\dint\mathfrak q(q)= \int_{{Q}}  \rho \,\n_q \,\dint\mathfrak q(q)= \rho\, \n = \mu.$$
\smallskip
\textbf{Claim 1:} For $\mathfrak q$-a.e.\ ${q\in Q}$ there exists a measure $\Pi_q$ on $\TGeo(Y)$ such that $q\in Q\mapsto \Pi_q(G)$ is a measurable map for every measurable set $G\subseteq \TGeo(Y)$, and such that 
$$\Pi= \int_{{Q}} \Pi_q \,\dint\mathfrak q(q).$$ 
The measure $\Pi_q$ is supported on $\TGeo(Y_q)$, and  is the unique measure  on $\TGeo(Y_q)$ with $(e_0)_\sharp \Pi_q= \mu_q$ and $(e_1)_\sharp \Pi_q=\delta_{\bar x}$.  The measure $\Pi_q$ is given by $(\Psi|_{Y_q})_\sharp \mu_q= \Pi_q$ for $\mathfrak q$-a.e.\ $q\in Q$.
\medskip\\
\textit{Proof of Claim 1}. The map $\Psi$ from \Cref{Lem:selection} is defined $\n$-a.e.\ on $I^+((\bar t, \bar x))$. Hence,  for $\mathfrak q$-a.e.\ $q\in Q$ the map $\Psi$ is defined $\n_q$-a.e.\ on $Y_q\cap I^+((\bar t, \bar x)).$ 
Moreover, by fiber independence $\Psi|_{Y_q} $ maps $Y_q$ to ${\mathrm{T}}\mbox{Geo}(Y_q)$. 
Hence, we can define $\Pi_q$ as in the claim.


We pick a measurable subset $  G\subseteq {\mathrm{T}}\mbox{Geo}(Y)$. It follows that $\Pi_q(G)=\mu_q(\Psi^{-1}(G)\cap Y_q)=\mu_q(\Psi|_{Y_q})^{-1}( G)=\mu_q(\Psi^{-1}(G))$ depends measurable on $q\in Q$, and
\begin{align*} 
\Pi(  G)= \mu(\Psi^{-1}(  G)) = \int_{{Q}}  \mu_q(\Psi^{-1}(  G)\cap Y_q) \,\dint \mathfrak q(q) = \int_{{Q}}  \Pi_q {(G)} \,\dint \mathfrak q(q).
\end{align*}
This is the claim.
\hfill$\blacksquare$
\smallskip

%\\
%\\
%We consider $(e_t)_\#\Pi_q= \mu_{t, q}$. Since $I\times_f (a_q,b_q)$ is a smooth Riemannian manifold the family $\{\mu_{t,q}\}_{t\in [0,1]}$ is the unique $L^p$-Wasserstein geodesic between $\mu_0=\mu$ and $\delta_{(\bar t, \bar x)}$.  
\noindent
{\bf 4.}
From Proposition \ref{Th:2 dimensional non-smooth case} it follows that the slice $Y_q= I\times_f X_q$ equipped with the measure $f(t)^N\,\dint t \otimes \m_q$ satisfies the condition $\tCD_p(-\kappa N, N+1)$.   

From this and since $Y_q$ is in fact smooth, we infer that $(e_{{s}})_\sharp\Pi_q=\mu_{{s}, q}$ is $\n_q$-absolutely continuous, i.e., $\mu_{{s}, q}= \rho_{{s},q} \,\n_q$, and for $s_0<s_1\in [0,1)$ and $\sigma({\eta})= (1-{\eta})s_0 + {\eta} s_1$ we have
\begin{equation}
\begin{aligned}\label{ineq:tcd2} 
\rho_{\sigma({\eta}), q}(\gamma_{\sigma({\eta})})^{-\frac{1}{N}}\geq \tau_{-\kappa N, N+1}^{(1-{\eta})}(\uptau(\gamma_{s_0},\gamma_{s_1}))\rho_{s_0, q}(\gamma_{s_0})^{-\frac{1}{N}}+\tau_{-\kappa N, N+1}^{({\eta})}(\uptau(\gamma_{s_0},\gamma_{s_1})) \rho_{s_1, q}(\gamma_{s_1})^{-\frac{1}{N}}
\end{aligned}
\end{equation}
for  $\Pi_q$-almost every geodesic $\gamma$. 
\smallskip

We set $(e_s)_\sharp\Pi =: \mu_s$ for $s\in (0,1)$. 
\smallskip\\
\textbf{Claim 2:} It holds that $\int_Q \mu_{{s}, q} \dint \mathfrak q(q)= \mu_{{s}}$.
\smallskip\\
\textit{Proof of Claim 2}. We  compute for any measurable set $A\subseteq   Y$ that 
\begin{align*}
\mu_{{s}}(A)=(e_{{s}})_\sharp\Pi(A)= \Pi(e_{{s}}^{-1}(A))&= \int _{{Q}}\Pi_q(e^{-1}_{{s}}(A)) \,\dint \mathfrak q(q) \\&= \int_{{Q}} \big[(e_{{s}})_\sharp \Pi_q\, {(A)}\big] \,\dint \mathfrak q(q) = \int_{{Q}}\mu_{{s}, q} {(A)} \,\dint \mathfrak q (q).
\end{align*}
Hence
$\int_{{Q}} \mu_{{s}, q}\,\dint \mathfrak q(q)= \mu_{{s}}. $\hfill$\blacksquare$
\smallskip\\
\textbf{Claim 3:} $\mu_s$ is $\n$-absolutely continuous. 
\smallskip\\
\textit{Proof of Claim 3}.  Let us consider a $\n$-null set $N$. Then, $N$ is a $\n_q$-null set for $\mathfrak q$-a.e.\ $q\in Q$. 
It follows that $\mu_{s,q}(N)=0$ for $\mathfrak q$-a.e.\ $q\in Q$, and consequently $\mu_s(N)=0$. 
\hfill $\blacksquare$
\smallskip

Let $\rho_s$ be the density of $\mu_s$ w.r.t.\ $\n$. 
\smallskip\\
\textbf{Claim 4:} $\rho_{{s}, q}= \rho_{{s}}|_{Y_q}$ for $\mathfrak q$-a.e.\ $q\in Q$.
\smallskip\\
%We define $\tilde \rho_{{s}}({y})= \rho_{{s}, q}({y})$ if and only if ${y}\in Y_q$. 
%Since the decomposition $\{Y_q\}_{q\in Q}$ is measurable and since each $\rho_{{s}, q}$ is a measurable function on $Y_q$, also $\tilde \rho_{{s}}$ is measurable.  
%Integration w.r.t.\ $h\in C_b(Y)$ yields
\textit{Proof of Claim 4}.
We pick a measurable function $\phi: Y\rightarrow [0,\infty)$. Then
\begin{align*}
\int_Q\int \phi \rho_s\, \dint \n_q\,\dint \mathfrak q(q)= \int \phi\,\dint\mu_{{s}} = \int_{{Q}}\int \phi \,\dint\mu_{{s}, q}\,\dint \mathfrak q(q) &= \int_{{Q}}\int \phi \rho_{{s}, q}\,\dint \n_q \,\dint \mathfrak q(q)
\end{align*}
This finishes the proof of the claim. \hfill $\blacksquare$
\smallskip\\

We pick a measurable set $G$ in ${\mathrm{T}}\mbox{Geo}(Y)$ and integrate \eqref{ineq:tcd2} w.r.t.\ $\Pi_q|_A$ and then w.r.t.\ $\mathfrak q$. It follows that
\begin{align*}
\int_G \rho_{\sigma({\eta})}(\gamma_{\sigma({\eta})})^{-\frac{1}{N}} \,\dint \Pi (\gamma)\geq \int_G\bigg[ \tau_{\kappa N, N+1}^{(1-{\eta})}&(\uptau(\gamma_{s_0},\gamma_{s_1})) \rho_{s_0}(\gamma_{s_0})^{-\frac{1}{N}}\\&+\tau_{\kappa N, N+1}^{({\eta})}(\uptau(\gamma_{s_0},\gamma_{s_1})) \rho_{s_1}(\gamma_{s_1})^{-\frac{1}{N}}\bigg] \dint \Pi(\gamma).
\end{align*}
Since $G$ was arbitrary, this finishes the proof of the theorem. 
\end{proof}
\begin{proof}[Proof of Theorem \ref{th:totmcp}] We will show the condition $\tmcp^-$. $\tmcp^+$ follows analogously.

Let $(\bar t, \bar p)\in Y$ and let $\mu_0$ be an $\n$-absolutely continuous probability measure such that  $\supp \mu_0\subseteq I^-((\bar t, \bar x))$. From inequality \eqref{ineq:concave} we get
$$
         \rho_{\eta s_1}(\gamma_{\eta s_1)})^{-\frac{1}{N}}  \geq \tau_{-\kappa N, N+1}^{({1-\eta})}\big({ s_1L(\gamma)}\big) \rho_{s_0}(\gamma_{s_0})^{-\frac{1}{N}}
$$
for $\Pi$-a.e.\ $\gamma$ where $\sigma(\eta)= \eta s_1$ and $\eta\in [0,1]$ and $s_1\in (0,1)$.  We integrate this inequality w.r.t.\ $\Pi$ to obtain
$$
\int \rho_{\eta s_1}^{-\frac{1}{N}} \dint \mu_{\eta s_1} \geq \int  \tau_{-\kappa N, N+1}^{({1-\eta})}\big({ s_1L(\gamma)}\big) \rho_{s_0}(\gamma_{s_0})^{-\frac{1}{N}} \dint \Pi(\gamma).
$$
Finally, let $s_1 \uparrow 1$. The negative of the left hand side is the Renyi entropy and therefore lower semi-continuous. Moreover, $s_1\mapsto \tau_{-\kappa N, N+1}^{({1-\eta})}\big({ s_1L(\gamma)}\big)$ is continuous. Hence, the right hand side converges as $s_1$ goes to $1$. 
\end{proof}
\medskip
It is clear that our method also gives the corresponding statement for generalized cones as metric measure spaces which is  new in this generality.
\begin{thm}[From $X$ to ${}^+I\times^N_fX$]\label{th:mmsmcp} Assume $f:I\rightarrow[0,\infty)$ is smooth and satisfies
\begin{itemize}
    \item $f''+ \kappa f\leq 0$, 
    \item $(f')^2 + \kappa f^2 \leq \eta$. 
\end{itemize}
Assume that $(X,\met,\m)$ is an essentially nonbranching metric measure space satisfying\\ $\CD(\eta (N-1), N)$ for $N>1$, and $f: I \rightarrow [0, \infty)$ is smooth as above. 

Then $I\times_f^N X$, i.e., the generalized cone $I\times_f X$ equipped with the measure $f(t)^N \,\dint t \otimes\dint\m$, satisfies $\mcp(\kappa N, N+1)$. 
\end{thm}
\begin{proof}
The proof is a word by word adaption of the proof of \Cref{th:totmcp}. There are analogous statements of  Lemma  \ref{Lem:selection} and Corollary \ref{cor:plans}, and  we apply again \Cref{Th:2 dimensional non-smooth case}. 

It is important to notice that geodesics in $I\times_f X$ may intersect with points where $f$ vanishes. But if $\partial I= f^{-1}(\{0\})\neq \emptyset$, then it was shown \cite[Thm.\ 3.4] {Ket:13} that  any transport plan $\Pi$ such that $(\e_0)_\sharp \Pi$ is absolutely continuous w.r.t.\ the reference measure, is concentrated on a set of geodesics that don't intersect with points where $f$ vanishes. 
\end{proof}

\begin{rem}
Let us compare the previous theorem with the results in \cite{ohta:cones} where Ohta proved the following theorem. 
\medskip\\
{\bf Theorem} (\cite[Thm.\ 4.2]{ohta:cones}){\bf .} {\it 
Let $X$ be a metric measure space that satisfies the measure contraction property $\mcp(N-1,N)$. Then $[0, \infty)\times_r^N X$ satisfies $\mcp(0,N+1)$. }
\medskip\\
In this theorem the assumption on the metric measure space $X$ is weaker.  $X$ is only required to satisfy the measure contraction property $\mcp(N+1,N)$.  The proof is an explicit computation for the volume distortion of optimal transport to a delta distribution.
We observed that this works similarly for the Minkowski cone, i.e., the property $\mcp(-(N-1),N)$ for $X$ implies the property $\tmcp(0, N+1)$ for $\I\times_r^N X$.
However, it is not clear to us how to generalize this approach to  general warped products. 

On the other hand, the proof of our theorem uses a $2D$-localisation technique. This reduces the problem to the case of smooth $2$-dimensional weighted warped products and we can apply the results of Section \ref{sec-2d-mod-spa} that establish the full theorem for the case of  warped products over weighted intervals. But this method seems to break down  if we just assume the measure contraction property, since the  property $\mcp(K,N)$ for a smooth Riemannian (or Lorentzian) space is equivalent to a lower bound $K$ for the Ricci tensor, only if  $N$ is a priori equal to the  Hausdorff dimension of the space. 
\smallskip\\
In conclusion, the following question remains open. 
\begin{que}Can we replace the condition  $\CD(\eta (N-1), N)$ for $X$ in Theorem \ref{th:totmcp} (or in Theorem \ref{th:mmsmcp}) with the weaker property $\mcp(\eta (N-1), N)$? 
\end{que} 
\end{rem}


\section{From the generalized cone \texorpdfstring{$Y$}{Y} to the fiber}\label{sec-Y-fib}
In this subsection we will prove the following result. 
\begin{thm}[From $\I\times^N_fX$ to $X$]\label{Th: Y to X}
Let $N\in (1,\infty)$, $\kappa\in \R$, and let $X$ be a proper, essentially nonbranching, complete, geodesic metric space with a Radon measure $\m$. Assume that $\smash{Y:=\I\times^N_f X}$ satisfies $\tCD_p(-\kappa N, N+1)$ and is {timelike} {$p$-essentially nonbranching} where $f: I\rightarrow [0, \infty)$ is smooth with $\partial I=f^{-1}(\{0\})$. Then \begin{itemize}
    \item $f''- \kappa f\leq 0$, and
    \item $X$ satisfies $\CD(\eta(N-1), N)$ where
\begin{align}
\label{Eq: first order condition, Y to X}\sup_I\{ -(f')^2 + \kappa f^2\} = :\eta.
\end{align}
\end{itemize}
\end{thm}
\begin{rem}  By fiber independence we know that $Y$  is timelike nonbranching  if and only if   $X$ is  nonbranching. 
\end{rem}
\begin{conjecture}
     {Timelike} $p$-essential nonbranchingness for $Y$ follows from  $X$ being essentially nonbranching, and $X$ being essentially nonbranching implies $Y$ to be timelike $p$-essentially nonbranching. 
\end{conjecture}

We obtain the following corollaries. 
\begin{cor}\label{cor:cone}
Let $N\in (1,\infty)$, and let $X$ be a proper,  nonbranching, complete, geodesic metric space with a Radon measure $\m$. Assume that the Minkowski $N$-cone  $\smash{[0, \infty)\times^N_f X}$ satisfies $\tCD_p(0, N+1)$. Then, the metric measure space $(X, \m)$ satisfies the condition $\CD(-(N-1), N)$.
\end{cor}
\begin{cor}\label{cor-Y-TCD-X-RCD}
Let $N\in (1,\infty)$, $\kappa\in \R$ and $X$ be a proper, essentially nonbranching, complete, infinitesimal Hilbertian, geodesic metric space with a Radon measure $\m$. Assume that $\smash{Y:=\I\times^N_f X}$ satisfies $\tCD_p(-\kappa N, N+1)$ and is {timelike} {$p$-essentially nonbranching} where $f: I\rightarrow [0, \infty)$ is smooth with $\partial I=f^{-1}(\{0\})$. Then \begin{itemize}
    \item $f''- \kappa f\leq 0$, and
    \item $X$ satisfies $\RCD(\eta(N-1), N)$ where
$\sup\limits_I\{ -(f')^2 + \kappa f^2\} = :\eta.
$\end{itemize}
\end{cor}

We notice that according to \Cref{Pr: various properties} $\I\times_fX$ is a globally hyperbolic  Lorentzian geodesic space. 

Since $\m$ is a Radon measure, it follows that $\n= f(t)^N\,\dint t \otimes \m$ is a Radon measure. 
\medskip

For the proof of \Cref{Th: Y to X} we will utilize the characterization of the curvature dimension condition $\CD$ for essentially nonbranching spaces in term of the $1D$-localisation, i.e., \Cref{thm:cavmil}. For this  we will fix a  localisation of $X$ given by a signed distance function. 
%Moreover, we will introduce a new map $\mathfrak H$ that we derive from the ray map  $\mathfrak G$  of the localisation. 
\medskip

 More precisely, we consider a partition $\{X_q\}_{q \in Q}$ of $X$  induced by a $1D$ localization of a signed distance function $u=\met_\phi$ as introduced in Subsection \ref{subsec:CD1}. More precisely, $\{X_q\}_{q\in Q}$ is a decomposition of $\mathcal T_u^b$, the transport set associated to $u$, and there exist distance-preserving maps $ \beta_q: [a_q, b_q]\rightarrow X$ such that $ \beta_q([a_q, b_q])= \overline{X}_q$.  This yields a partition $\{Y_q\}_{q\in Q}$ of $Y$ as in step {\bf 2} of the proof of Proposition \ref{prop:prop} and a disintegration  $\{\n_q\}_{q\in Q}$ of the measure $\n$. The slices $Y_q\subseteq Y$ are geodesically convex subsets in $Y$ and $Y_q$ is isometric to the (smooth) generalized cone $\I\times_f [a_q, b_q]$ via the map $F_\beta$ defined in  {\Cref{subsec:con_fiber}}. As before, we have  
$$\n_q=f(t)^N \dint t\otimes \m_q$$
where $\{\m_q\}_{q\in Q}$ is the disintegration of $\m|_{\mathcal T_u^b}$ that arises from $\{X_q\}$. 
Let $\mathfrak q$ be the quotient measure on $Q$ such that $\int_Q \m_q \dint \mathfrak q(q)= \m$. 

Since $\m$ is a Radon measure, we have the following property: if $J\times A$ is a bounded subset in $I\times X$, then $\n(J\times A)<\infty$, and consequently $\n_q(J\times A)<\infty$ for $\mathfrak q$-a.e.\ $q\in Q$.

\begin{rem}
We do not  know at this point whether the conditional measures $\m_q$ are {$\mathcal{H}^1$-}absolutely continuous. In the theory of $1D$-localization this follows usually from a curvature-dimension-type condition like the measure contraction property. However we do not assume this a priori for $X$ in this section.
\end{rem}

It is useful to recall how the {ray map} $\mathfrak G$ {was defined after \Cref{Th:1Dloc}}.
Since the function $u$ is the signed distance function associated to the set $S=\phi^{-1}(\{0\})$, we can modify the ray map accordingly so that each $(q,{r})\in \mathcal{V}$ gets mapped via $\mathfrak{G}$ to the {unique} point $x$ in  $X_q$ at signed distance {$\met$ equal to} ${r}$ from $S$. More precisely:
\begin{align*}
    &\mathfrak G:  \mathcal V\subseteq Q\times \R\rightarrow X,\\
    \mbox{graph}(&\mathfrak G)=\{ (q,{r},x) \in Q\times \R\times X:  \met_S(\beta_q({r}))={r} \mbox{ and } \beta_q({r})=x\}. 
\end{align*}
In particular there exist $a_q,b_q\in\R$ with $(a_q,b_q)\subseteq{\mathrm{Dom}(\mathfrak{G}(q,\cdot))}$.

We then build a natural extension  $\mathfrak H$ of $\mathfrak G$ to $Y$. 
\begin{defi}[{Sheet map}]\label{Def: shit map} The   {\it sheet map} $\mathfrak H$ is defined as
$$\mathfrak H: \mathcal W \subseteq Q\times (I\times_f \R) \rightarrow Y \ \ \mbox{ by } \ \ \mathfrak H(q, {t}, r)=({t}, \mathfrak G(q, r)).$$
\begin{itemize}
\item 
The map $\mathfrak H$ is Borel measurable and  $\mathcal W= \mathfrak H^{-1}(I\times \T^b_u)$. 
\item $\mathfrak H(q,\cdot,\cdot)=F_q: I\times_f [a_q, b_q]\rightarrow {Y_q}\subseteq Y$ is a Lorentzian embedding. 
\item $\mathfrak H:\mathcal W\rightarrow  I\times \T^b_u$ is bijective and its inverse is measurable and given by $$\mathfrak H^{-1}({t},x)=( \mathfrak Q(x), {t}, \met_S(x)).$$
\end{itemize}
\end{defi}
\begin{lem}\label{lem:cycmon}
Let $\mathcal C$ be any $\uptau^p$-cyclically monotone set in  $({\I}\times_f \R)^2$. Then the set 
$$\smash{ \tilde{\mathcal C} = \left\{ \left(({t^0},{x^0}),({t^1},{x^1})\right) \in {\I}\times_f X: \left(({t^0}, \met_\phi({x^0})), ({t^1}, \met_\phi({x^1}))\right)\in \mathcal C\right\}}$$
is $\uptau^p$-cyclically monotone in $({\I}\times_f X)^2.$
\end{lem}
\begin{proof}
For $\smash{\left\{\left(({t^0_i}, {x^0_i}), ({t^1_i}, {x^1_i})\right)\right\}_{i=1, \dots, n}\subseteq \tilde{\mathcal C}}$ and any permutation $\sigma\in \mathcal S_n$ it follows by fiber independence that  
\begin{align*}\sum_{i=1}^n \uptau^p\left( ({t^0_i}, {x^0_i}), ({t^1_{\sigma(i)}}, {x^1_{\sigma(i)}})\right)&=\sum_{i=1}^n \uptau^p\left( ({t^0_i}, \met_\phi({x^0_i})), ({t^1_{\sigma(i)}}, \met_\phi({x^1_{\sigma(i)}}))\right)\\
&\leq \sum_{i=1}^n \uptau^p\left( ({t^0_i}, \met_\phi({x^0_i})), ({t^1_{i}}, \met_\phi( {x^1_{i}}))\right) = \sum_{i=1}^n \uptau^p\left( ({t^0_i},{x^0_i}), ({t^1_{i}}, {x^1_{i}})\right).
\end{align*}
The last inequality follows from the $\uptau^p$-cyclical monotonicity of $\mathcal C$. 
\end{proof}
{}

We fix a finite interval $[L_0, L_1]\subseteq \R$ and define 
\begin{align}\label{Eq:tilde Q}
\tilde Q:= Q_{[L_0, L_1]}:=\{ q \in Q: [L_0, L_1]\subseteq (a_q, b_q)\}\subseteq Q.
\end{align}
Hence $\I\times_f [L_0, L_1]\subseteq Y_q$ for every $q\in \tilde Q$.
\begin{prop}[{{The sheets satisfy $\tmcp$}}]The smooth Lorentzian length space $\I\times_f [L_0,L_1]$ equipped with the measure $\smash{\n_q|_{\I\times_f [L_0, L_1]}}$ satisfies a {timelike} measure contraction property for $\mathfrak q$-a.e.\ $q\in \tilde Q$. 
\end{prop}
\begin{proof} 

We pick a point $({\bar t}, {\bar r})\in\I\times_f [L_0, L_1]$ 
and  a bounded set $A\subseteq I^\pm(({\bar t}, \bar{r}))\subseteq\I\times_f [L_0, L_1]$ with $\n(A)>0$. Let us assume that $A\subseteq I^+(({\bar t}, \bar r))$ for simplicity.


 It is clear that $\{(\bar t, \bar r)\}\times A$ is $\uptau^p$-cyclically monotone for every $p\in (0,1)$.

We consider the set $\smash{\TGeo_{(\bar t, \bar r)}^{A}}$ of future-directed timelike geodesics $\gamma
\in \TGeo(\I\times_f [L_0,L_1])$ such that $\gamma(0)=(\bar t, \bar r)$ and $\gamma(1)\in A$.

We set 
\begin{align*}
\smash{A_{{s}}:= \{({t},{r})\in I^+(({\bar t}, {\bar r})): ({t}, {r})= \gamma({s})\mbox{ for } \gamma\in \TGeo_{(\bar t, \bar r)}^{A}\}}
\end{align*}
where $A_1=A$. 
Moreover, there is a measurable map $\smash{T: A\rightarrow \TGeo_{(\bar t, \bar r)}^{A}}$ such that  $T(t,r)$ is a timelike future-directed geodesic between $(\bar t, \bar r)$ and $(t,r)\in A$. In particular $\e_s(T(t,r))\in A_s$ for all $(t,r)\in A$.  

We choose a measurable and bounded  subset $\Lambda\subseteq \tilde{Q}$ with $0<\mathfrak q(\Lambda)<\infty$. 
Considering $\Lambda\times A\subseteq \mathcal W$, then $\mathfrak H(\Lambda\times A)=\tilde A$ is a measurable subset in $\I\times_f X$ (see also \eqref{Eq:tilde Q}). Recalling the definition of  $\mathfrak H$ we notice that
$$\tilde A= \{(t,x): \beta_q(r)=x, \ q\in \Lambda,\  (t, r)\in A\}.$$
Here $\beta_q(r)=x$ implies $\met_\phi(x)=r$.


We also define $$L:=\{(\bar{t}, \bar{x}): \beta_q(\bar r)=\bar x, q\in \Lambda\}= \mathfrak H(\Lambda\times \{(\bar t, \bar r)\})\subseteq {\I}\times _f X.$$
Since $\Lambda$, $A$ are bounded, $\tilde A$ is bounded. Hence $\n(\tilde A)<\infty$  since $\n$ is a Radon measure. Hence $\n_q( A)<\infty$ for $\mathfrak q$-a.e.\ $q\in \tilde Q$.

We set \begin{align}\label{Eq: nqaq}
\mu_{q,0}:=\frac{1}{\n_q(A)}\n_q|_A.
\end{align}
The measure $T_\sharp \mu_{q,0}=: \bdpi_q$ is an optimal dynamical plan, and $(\e_s)_\sharp \bdpi_q= \mu_{q,s}$ is supported on $A_s$.

The set 
$$
\left\{ \big(({\bar t}, {\bar x}), ({t}, {x})\big):  \big(({\bar t}, \met_\phi({\bar x})), ({t}, \met_\phi({x}))\big)\in \{(\bar t, \bar r)\}\times A\right\}=\tilde{ \mathcal{C}}
$$
is $\uptau^p$-cyclically monotone in $({\I}\times_f X)^2$ by Lemma \ref{lem:cycmon}.

We define $\smash{\mu_0= \n(\tilde A)^{-1} \n|_{\tilde A}}$. 
Moreover, {we define a map $\tilde T: Y\rightarrow\TGeo(Y)$ so that  $\tilde T(t,x)$ is a timelike future-directed geodesic that connects a point $(\bar t, \bar x)\in L$ and  $(t,x)$ such that $\bar x, x\in X_q$ and $\tilde T(t,x)(s)\in Y_q$ for all $s\in [0,1]$}. In particular, $(\e_0, \e_1)(\tilde T(t,x))\subseteq \tilde C$. 
Since $\tilde{\mathcal{C}}$ is $\uptau^p$-cyclically monotone, it follows that 
$$T_\sharp \mu_0= \bdpi$$
is an optimal geodesic plan between $(\e_0)_\sharp \bdpi= \mu_0$ and $(\e_1)_\sharp\bdpi=\mu_1${, cf.\ \cite[Prop.\ 2.8]{CM:24a}}. Moreover $(\e_s)_\sharp \bdpi$ is concentrated in $\tilde A_s = \mathfrak H(\Lambda \times A_s)$. In particular, $\mu_0, \mu_1$ are strongly dualizable and since we assume that $\I\times_f X$ is {timelike} $p$-essentially nonbranching, $\bdpi$ is the unique optimal plan.

The {timelike} curvature-dimension condition on ${\I}\times_f X$ implies (see \Cref{rem:entropicmcp}) 
$$\n(B\cap \tilde A_{{s}})\geq g({s})\, \n\big((\e_s \circ \tilde T(t,x))^{-1}(B)\cap \tilde A\big),$$
where
$g: [0,1] \rightarrow (0, \infty)$  by $$g({s}):=g_{B,K,N}({s}):= \inf_{(t,{r})\in B}\sigma_{K,N}^{({s})}\left(\uptau((\bar t,{\bar r}),(t,{r}))\right)^N.$$
The precise value of $K\in \R$ does not play a role here. 

In terms of the disintegration of $\n$ w.r.t.\ $\mathfrak q$ this is 
$$\int_\Lambda \n_q(B\cap \tilde A_{{s}}) \,\dint \mathfrak q(q)\geq g({s}) \int_\Lambda \,\n_q\big((\e_s\circ T(r,x))^{-1}(B)\cap \tilde A\big)\, \dint \mathfrak q(q).$$
Since the set $\Lambda$ was arbitrary, this implies 
\begin{align*}
   \n_q(B)\geq  \n_q( B\cap A_{{s}})\geq g({s}) \,&\n_q\big( (\e_s \circ T(t,r))^{-1}(B)\cap A\big) \\&= g(s) \,\n_q(A) \mu_{q,s}(B) \qquad\mbox{ for } \mathfrak q\mbox{-a.e.\ } q\in \tilde Q.
\end{align*} For the last equality note that from \eqref{Eq: nqaq} we have
$$\mu_{q,s}(B)= \mu_{q,0} ((t,r)\mapsto T(t,r)^{-1}(\e_s^{-1}(B))\cap A)= \frac{1}{\n_{q}(A)} \n_q ((t,r)\mapsto T(t,r)^{-1}(\e_s^{-1}(B))\cap A).$$

Decomposing $B$ into a union of pairwise disjoint sets $B=\bigcup_i B_i$ where $B_i= B\cap \{ (t,r): \eps (i-1)< \uptau((\bar t, \bar r), (t, r))< \eps i\}$, applying the previous estimate with $B=B_i$ and finally letting $\eps\rightarrow 0$ yields 
$$ \n_q(B) \geq \int_B \sigma_{K,N}^{(s)}\big(\uptau((\bar t, \bar r), \cdot )\big)^{{N}}\,\n_q(A) (\e_s)_\sharp \bdpi_q.$$
If we choose $B=B_n$ where  $\{B_n\}_{n\in \N}$ is  a countable $\cap$-stable generator for of the Borel $\sigma$-field,  we get
\begin{align}\label{ineq:amcp}
    \n_q\geq \e_s\left(\sigma_{K,N}^{(s)}\big(\uptau((\bar t, \bar r), \cdot)\big)^{{N}}\n_q(A) \bdpi_q\right) \quad\mbox{ for } \mathfrak q\mbox{-a.e.\ } q\in \tilde Q. 
\end{align}
We can pick a countable collection of points $({\bar t}, {\bar r})$ such that \eqref{ineq:amcp} holds for $\mathfrak q$-a.e.\ $q\in \tilde Q$. By the stability of inequality \eqref{ineq:amcp} we derive that the inequality holds for all $({\bar t}, {\bar r})$  for $\mathfrak q$-a.e.\ $q\in \tilde Q$. 

Hence 
$$({\I}\times_f [L_0, L_1], \n_q)$$
satisfies a {timelike} measure contraction property for $\mathfrak q$-a.e.\ $q\in\tilde Q$. 
\end{proof}
\begin{rem} 
Note that \Cref{ineq:amcp} is a measure contraction property in the sense as proposed by Ohta in \cite{Oht:07} for metric measure spaces. A difference is that the coefficient $\smash{\tau_{K,N}^{(s)}}$ is replaced with the coefficient $\smash{\sigma_{K,N}^{(s)}}$. By standard techniques, taking into account that  the underlying space is essentially nonbranching and even smooth, one can deduce the measure contraction property in the form of \Cref{Def: TMCP}, still with $\sigma^{(t)}_{K,N}$ instead of $\tau^{(t)}_{K,N}$ (compare with \cite[Prop.\ 9.1]{CM:21}).
\end{rem}


We obtain the following corollary directly from \Cref{lem:2Dmcp}.
\begin{cor}
The measure $\m_q$ is $\mathcal L^1$-absolutely continuous for $\mathfrak q$-a.e.\ $q\in \tilde Q$, i.e., $\m_q= h_q \mathcal L^1$ for $h_q\in L^\infty_{\loc}((L_0, L_1))$. 
\end{cor}
Let $(\mu_{{s}})_{{s}\in [0,1]}$ be a $\ell_p$-Wasserstein geodesic concentrated in $\I\times_f (L_0, L_1)$ and absolutely continuous w.r.t.\ $f(t)\,\dint t \otimes\dint r$, the  Lorentzian volume  of $\I\times_f (L_0, L_1)$ {and such that $\mu_0, \mu_1$ are $p$-dualizable}.

\begin{rem}\label{Rem: smooth lmfd}
Note that $\I\times_f (L_0, L_1)$ is a smooth Lorentzian manifold. Hence, since $(\mu_{{s}})_{{s}\in [0,1]}$ is concentrated on $\I\times_f (L_0, L_1)$, it follows for the density $\varrho_s$ w.r.t.\ $f(t)\,\dint t\otimes\dint r$ that 
$$\varrho_0(p)= \det DT_{{s}}(p)\varrho_{{s}}(T_{{s}}(p)) $$
where $T_{{s}}(x)$ is the unique optimal map between $\mu_0$ and $\mu_{{s}}$ \cite[Sec.\ 5]{McC:20}. The map $$\smash{{s}\in [0,1]\mapsto T_{{s}}(p)=\gamma_p(s)}=\smash{(\alpha_{p}({s}), \beta_{p}({s}))}$$ is a geodesic in ${\I}\times_f(L_0, L_1)$ for $\mu_0$-a.e.\ $p=(t_p,r_p)$. 
There also exists an optimal geodesic plan $\Pi\in\mathscr{P}({\mathrm{T}\!}\Geo({\I}\times_f (L_0, L_1)))$ such that $(\e_{{s}})_\sharp\Pi=\mu_{{s}}$ $\forall {s}\in [0,1]$.
\end{rem}
\begin{lem}
For $\mathfrak q$-a.e.\ $q \in \tilde Q$ there exists a unique $\ell_p$-geodesic $(\mu_{{s}}^q)_{{s}\in [0,1]}$ between $\mu^q_0$ and $\mu^q_1$ where $\mu^q_i:=\mathfrak H(q, \cdot, \cdot)_{\sharp} \mu_i$ for $i=0,1$ in $\I\times_f X_q$ such that $\mu^q_{{s}}$ is $\n_q$-absolutely continuous with density $\rho_{{s}}^q$, $\mu^q_{{s}}= (e_{{s}})_\sharp \Pi^q$ for $\Pi^q\in\mathscr P({\mathrm{T}\!}\Geo({\I}\times_f X_q))$, and 
\begin{align*}
    \rho^q_{{s}}(\gamma({s}))^{-\frac{1}{N+1}} \geq \tau_{-\kappa N, N+1}^{(1-{s})}(L_{{\uptau}}(\gamma))\rho^q_0(\gamma(0))^{-\frac{1}{N+1}} + \tau_{-\kappa N, N+1}^{({s})}(L_{{\uptau}}(\gamma) )\rho^q_1(\gamma(1))^{-\frac{1}{N+1}},
\end{align*}
for $\Pi_q$-a.e.\ $\gamma\in\TGeo(\I\times_fX_q)$.
\end{lem}
\begin{proof}
We define probability measures $\nu_i\in{\mathscr{P}}({\I}\times_f X)$ as follows: {we pick $\tilde Q'\subseteq \tilde Q$ with $0<\mathfrak q(\tilde Q')= \lambda<\infty$. Then we set}
\begin{align*}
    \nu_i= {\frac{1}{\lambda}}\int_{\tilde Q'} \mathfrak H(q, \cdot, \cdot)_{\sharp}\mu_i \,\dint\mathfrak q(q), \ \ i=0,1. 
\end{align*}
\noindent
\textbf{Claim:} 
For $i=0,1$ the measures $\nu_i$ are $\n$-absolutely continuous with a density $\rho_i$ that satisfies 
\begin{align}\label{equ:density} \rho_i(\mathfrak H(q, t, r))={\lambda }\cdot{h_q(r)^{-1}f(t)^{-(N-1)}}\varrho_i(t, r),\end{align}
where $\varrho_i$ are the densities of $\mu_i$ w.r.t.\ $f({t})\,\dint {t} \otimes \dint {r}$.\smallskip\\
\noindent\textit{Proof of the Claim}. First we prove that $\nu_i$, $i=0,1$, is $\n$-absolutely continuous.  Since $\mu_i$ is absolutely continuous w.r.t.\ $f({t})\,\dint{t} \otimes \dint{r}$, $\mu^q_i$ is  absolutely continuous w.r.t.\ $\n_q=f({t})^N\,\dint {t} \otimes \m_q$ for $\mathfrak q$-almost every $q\in \tilde Q$. This is because ${\I}\times_f (L_0, L_1)$ equipped with the measure $\n_q$ satisfies a measure contraction property for $\mathfrak q$-a.e.\ $q\in \tilde Q$, and hence $\m_q$ is $\mathcal L^1$-absolutely continuous such that its density $h_q$ has full support in $X_q$. 

Let $N\subseteq Y$ be a $\n$-null set. We have to prove that $\nu_i(N)=0$. By Fubini's theorem it follows that $Y_q\cap N$ is a $\n_q$-null set for $\mathfrak q$-a.e.\ $q\in \tilde Q$.  Hence $\mu_i^q(N\cap X_q)=0$ for $\mathfrak q$-a.e.\ $q\in \tilde Q$ and therefore $$\nu_i(N)=\frac{1}{\lambda}\int_{\tilde Q'}\mu_i^q(N\cap X_q) \,\dint\mathfrak q(q)=0.$$ So $\nu_i$ is $\n$-absolutely continuous with $\nu_i=\rho_i\,\n$.
\smallskip

Let $\phi: \mathcal W\rightarrow [0, \infty)$ be any measurable function where $\mathcal W$ is the domain of the sheet map.  Then, integrating $\phi$ w.r.t.\ $\nu_i$, we get
\begin{align*}\int_{\tilde Q'}\iint \phi(q,{t},{r}) &\rho_i(\mathfrak H(q,{t},{r})) {f({t})^N\,\dint{t}\,  \dint\m_q({r}) } \,\dint\mathfrak q(q)\\
&=\int_{\tilde Q'}\left(\int  \phi \circ \mathfrak H(q, \cdot, \cdot)^{-1}(y)\rho_i(y) \,\dint\n_q(y)  \right)\dint\mathfrak q(q)\\
&= \int   \phi \circ \mathfrak H(q, \cdot, \cdot)^{-1}(y) \rho_i(y)\,\dint\n(y)\\
&= \int   \phi \circ \mathfrak H(q, \cdot, \cdot)^{-1}(y) \,\dint\nu_i(y)\\
&= \int_{\tilde Q'} \int   \phi \circ \mathfrak H(q, \cdot, \cdot)^{-1}(y)\,\dint \mu_i^q(y)\, \dint \mathfrak q(q)\\
&= \int_{\tilde Q'} \int  \phi \circ \mathfrak H(q, \cdot, \cdot)^{-1}(y) \,\dint(\mathfrak {H}(q, \cdot, \cdot)_\sharp \mu_i)(y)\, \dint \mathfrak q(q)\\
&= \int_{\tilde Q'} \iint \phi(q, {t}, {r}) \,\dint\mu_i({t},{r}) \,\dint \mathfrak q(q)\\
&= \int_{\tilde Q'} \left(\iint \phi(q, {t},{r})\varrho_i({t},{r})  f({t})\,\dint {t}\,  \dint {r}\right)\dint\mathfrak q(q)\\
&= \int_{\tilde Q'}\iint \phi(q, {t}, {r}) \varrho_i({t},{r}) h_q({r})^{-1} f(t)^{-(N-1)}f({t})^N\, \dint {t}\, \dint\m_q({r})\,\dint\mathfrak q(q)
%\\
%&= \int_{\tilde Q} \int \phi (q, r,t)\frac{\varrho_i(r,t)}{ h_q(t)f(r)^{N-1}} \,\dint\m_q \,\dint\mathfrak q(q).
\end{align*}
This proves \eqref{equ:density} and therefore the claim.
\hfill$\blacksquare$
\smallskip

We consider a $\ell_p$-geodesic $(\mu_{{s}})_{{s}\in [0,1]}$ between $\mu_0$ and $\mu_1$. By Lemma \ref{lem:cycmon}, 
$${s}\in [0,1] \mapsto \nu_{{s}}:=\frac{1}{\lambda}\int_{\tilde Q'} \mathfrak H(q, \cdot, \cdot)_{\sharp} \mu_{{s}}\,\dint\mathfrak q(q)$$
is an  $\ell_p$-geodesic in ${\I}\times_f X$ between $\nu_0$ and $\nu_1$.  Moreover, also by \Cref{lem:cycmon},  $\nu_0, \nu_1$ are strongly timelike $p$-dualizable in $Y$. Since $Y$ is also $p$-essentially nonbranching, $\nu_s$ is the unique geodesic between $\nu_0$ and $\nu_1$. Hence, by the curvature-dimension condition $\nu_{{s}}$ is $\n$-absolutely continuous for all ${s}\in [0,1]$, and as before one can check that its  density satisfies $$ 
\rho_{{s}}(\mathfrak H(q, t, r))={h_q(r)^{-1}f^{-(N-1)}(t)}\varrho_{{s}}(t, r) $$
where $\varrho_{{s}}$ is the density of $\mu_{{s}}$ w.r.t.\ $f({t})^N\,\dint{t} \otimes \dint {r}$.

We also note that $\mathfrak H(q, \cdot, \cdot)_\sharp \mu_{{s}}= \mu^q_{{s}}$ is the $\ell_q$-geodesic between $\mu_0^q$ and $\mu_1^q$ since $\mathfrak H(q, \cdot, \cdot)= F_q$ is a Lorentzian isometric embedding. Since $\nu_{{s}}$ has the density $\rho_{{s}}$ w.r.t.\ $\n=f(t)^N\,\dint{t} \otimes \m$, it is then clear that $\mu_{{s}}^q$ has the density $\rho_{{s}}|_{Y_q}=\rho_{{s}}^q$ w.r.t.\ $\n_q= f({t})^N\,\dint{t} \otimes \m_q$. 

We  define a map from $\TGeo({\I}\times_f (L_0,L_1))$ to $\TGeo(Y_q)$ as follows. 
We first notice that the map $F_q: {\I}\times_f [a_q, b_q]\rightarrow Y_q$ is a Lorentzian isometric embedding. 
Hence, if we set $$\hat F_q(\gamma)({s}):= F_q\circ \gamma({s}), \ \gamma\in \TGeo({\I}\times_f(L_0,L_1)),$$ then $\hat F_q(\gamma)=:\hat \gamma$ is a geodesic that satisfies $\hat \gamma({s})\in Y_q$ for ${s}\in [0,1]$. We note that \begin{align}\label{eq:com}\e_{{s}}(\hat F_q(\gamma))=F_q\circ \gamma({s})= F_q(\e_{{s}}(\gamma)).\end{align}
Hence, if we define 
$$\hat \Pi = \int_{\tilde Q} (\hat F_q)_\sharp\Pi \,\dint\mathfrak q(q)$$
then $(\e_{{s}})_\sharp \hat \Pi= \nu_{{s}}$. Indeed
\begin{align*}\nu_{{s}}(A)&=\int_{\tilde Q} \mathfrak H(q, \cdot, \cdot)_{\sharp} \big((\e_{{s}})_\sharp \Pi\big) (A) \,\dint\mathfrak q(q)\\
&= \int_{\tilde Q} \Pi\big((\e_{{s}})^{-1}((F_q)^{-1}(A))\big)\,\dint\mathfrak q(q)=\int_{\tilde Q}\Pi((\hat F_q)^{-1}((\e_{{s}})^{-1}(A))\,\dint \mathfrak q(q)=\hat \Pi((\e_{{s}})^{-1}(A)).\end{align*}
We set $(\hat F_q)_\sharp \Pi=: \Pi^q$. Then it also follows that $\mu_{{s}}^q= (\e_{{s}})_\sharp \Pi^q$. Indeed we compute
$$(\e_{{s}})_\sharp \Pi^q=(\e_{{s}} \circ \hat F_q)_\sharp \Pi\stackrel{\eqref{eq:com}}{=} (F_q\circ \e_{{s}})_\sharp\Pi= \mathfrak H(q, \cdot, \cdot)_\sharp \mu_{{s}}= \mu_{{s}}^q.$$


By the curvature-dimension condition on $Y$ it  holds
\begin{align*}
    \rho_s(\gamma({s}))^{-\frac{1}{N+1}}\geq \tau_{-\kappa N,N+1}^{(1-{s})}(\uptau(\gamma_0,\gamma_1))\rho_0(\gamma(0))^{-\frac{1}{N+1}}+ \tau_{-\kappa N,N+1}^{({s})}(\uptau(\gamma_0,\gamma_1))\rho_1(\gamma(1))^{-\frac{1}{N+1}}
\end{align*}
for $\Pi$-a.e.\ $\gamma\in \TGeo(Y)$. In other words, \begin{align*}
    \rho^q_{{s}}(\gamma({s}))^{-\frac{1}{N+1}}\geq \tau_{-\kappa N,N+1}^{(1-{s})}(\uptau(\gamma_0,\gamma_1))\rho^q_0(\gamma(0))^{-\frac{1}{N+1}}+ \tau_{-\kappa N,N+1}^{({s})}(\uptau(\gamma_0,\gamma_1))\rho^q_1(\gamma(1))^{-\frac{1}{N+1}}
\end{align*}
for $\Pi^q$-a.e.\ $\gamma\in \TGeo(Y_q)$ and $\mathfrak q$-a.e.\ $q\in \tilde Q$. This finishes the proof of the lemma.
\end{proof}
\begin{prop}\label{prop:cdslice}
    For $\mathfrak q$-a.e.\ $q\in \tilde Q$ the sheet $(\I\times_f (L_0, L_1), f({t})^N\,\dint{t} \otimes{h_q(r)}\,\dint{r})$ satisfies  $\tCD_p(-\kappa N, N+1)$. 
\end{prop}
\begin{proof} {\bf 1.} 
Let $\mathcal I$ and $\mathcal J$ be families of compact intervals in the open interior of $I$ and in $(L_0, L_1)$, respectively, with endpoints in $\mathbb Q$. Hence, $\mathcal I$ and $\mathcal J$ are countable families. 
We say that a bounded and measurable function $g: I\times_f (L_0, L_1)\rightarrow [0, \infty)$ is a step function if 
\begin{center}$g= \sum_{i=1}^k \alpha_i 1_{A_i}\mbox{ where }\alpha_i \in [0, \infty)\cap \mathbb Q ,A_i = I_i\times J_i\mbox{ with }I_i\in \mathcal I ,J_i\in \mathcal J.$\end{center}

Given a $f(t)\,\dint t \otimes \dint r$-absolutely continuous measure $\mu$ on $Z$, its density $\varrho$ is $L^1$-integrable w.r.t.\ $f(t)\,\dint t \otimes \dint r$. 
 Assuming $\varrho$ is bounded it  can be approximated in $L^\infty$ by a sequence of step functions $g_i$. We can normalize the function $g_i$ so that $\mu_i:= g_i(t,r)\, \dint t \otimes \dint r$ is a probability measure. Then, $g_i$ still converges in $L^\infty$ to $\varrho$, and $(\mu_i)$ also converges weakly to $\mu$. 

We denote by $
\mathfrak S$ the countable set of all $f(t) \,\dint t\otimes \dint r$-absolutely continuous probability measures whose density function is a step function.\\

\noindent{\bf 2.} For every pair $\mu_0, \mu_1\in \mathfrak S$ such that there exists a $\ell_p$-Wasserstein geodesic supported in $\I\times_f (L_0, L_1)$ we can apply the previous lemma. It follows that for $\mathfrak q$-a.e.\ $q\in \tilde Q$ we have, using the same notation as before, \begin{align}\label{ineq:rhoq}
    \rho^q_t(\gamma(s))^{-\frac{1}{N+1}}\geq \tau_{\kappa N,N+1}^{(1-s)}(\uptau(\gamma_0,\gamma_1))\rho^q_0(\gamma(0))^{-\frac{1}{N+1}}+ \tau_{\kappa N,N+1}^{(s)}(\uptau(\gamma_0,\gamma_1))\rho^q_1(\gamma(1))^{-\frac{1}{N+1}}
\end{align}
for all $s\in (0,1)$ and for $\Pi^q$-a.e.\ $\gamma\in \Geo(Y_q)$ where for $s\in [0,1]$ $\rho^q_s$ are the densities w.r.t.\ $\n_q$.
Since $
\mathfrak S$ is countable, we have that there exists a set $N\subseteq Q$ with $\mathfrak q(N)=0$ such that  the last inequality holds for every pair $\mu_0, \mu_1\in \mathfrak S$ for every $q\in Q\setminus N$, i.e., for $\mathfrak q$-a.e.\ $q\in Q$. 
\\
\\
{\bf 3.}
We pick $f(t)^N \,\dint t \otimes \dint r$-absolutely continuous measures $\mu_0, \mu_1$ that are compactly supported in $I\times_f (L_0, L_1)$, with bounded densities $\rho_i$, $i=0,1$, and, such that the $\ell_p$-Wasserstein geodesic is compactly supported in $I\times_f (L_0, L_1)$. Then, we can approximate $\mu_0$ and $\mu_1$ weakly by measures $\mu^k_0$ and $\mu^k_1$ in $\mathfrak S$ such that the corresponding densities $\varrho^k_i$, $i=0,1$, w.r.t.\ $f(t)\,\dint t\otimes \dint r$ converge in $L^\infty$ to $\varrho_i$. 


We note that  $\rho_i^q$, the density of $\mu_i\in \mathfrak S$ w.r.t.\ $f(t)^N\,\dint t\otimes \m_q= f(t)^N\,\dint t \otimes h_q\dint r$, are not step functions. But if the corresponding densities $(\varrho^k_i)_{k\in \mathbb N}$, the density w.r.t.\ $f(t)\,\dint t\otimes \dint r$, converges uniformly to $\varrho_i= \rho_i^q f^Nh_q$, then also $\smash{(\rho^{k,q}_i)}$ converge uniformly to $\rho^q_i$. Note that $\rho_i^{k,q}= \varrho^k_i f^{-(N-1)}(t)h_q(r)^{-1}$ and $\rho^q_i= \varrho_i f^{-(N-1)}(t)h_q(r)^{-1}.$


This remains true for $\mathfrak q$-a.e.\ $q\in \tilde Q$ if we consider the densities $\smash{\rho^q_i, \rho^{k, q}_i}$ w.r.t.\ $\n_q$.  Moreover, by weak convergence of $\mu^k_i$ to $\mu_i$, $i=0,1$, the $\ell_p$-geodesics between $\mu^{k}_i$ converge to the $\ell_p$-geodesic between $\mu_i$. The latter is independent of $q\in \tilde Q$ since the underlying geometry is the fixed, i.e., the one of $\I\times_f (L_0, L_1)$. Similarly, there are geodesic plans $\Pi^k$ converging to $\Pi$. We fix one admissible $q\in \tilde Q$ in the following. 

By integrating the inequality \eqref{ineq:rhoq} w.r.t.\ $\Pi^k$ we get
\begin{align*} &-\int (\rho^{q,k}_s)^{-\frac{1}{N}}(\gamma(t))\,\dint \Pi^{q,k}(\gamma)= -\int (\rho^{q,k}_s)^{1-\frac{1}{N}}(x)\,\dint \n_q(x)= S_N(\mu^{k}_s|\n_q) \\
&\geq-\!\int\Big[\tau_{-\kappa N,N+1}^{(1-s)}(\uptau(x_0,x_1))\rho^{q,k}_0(x_0)^{-\frac{1}{N}} +\tau_{-\kappa N,N+1}^{(s)}(\uptau(x_0,x_1))\rho^{q,k}_1(x_1)^{-\frac{1}{N}}\Big]\,\dint\left((\e_0, \e_1)_\sharp\Pi\right)(x_0,x_1).\end{align*}
The left hand side of this inequality is  the $N$-Renyi entropy which is lower semi-continuous w.r.t.\ weak convergence. The right hand side, on the other hand, is upper semi-continuous because $\Pi^k$ weakly converges to $\Pi$ (after we eventually take another subsequence) and because the densities $\smash{\rho^{q,k}_i}$, $i=0,1$, converge uniformly to $\smash{\rho^{q,k}}$. 

It follows that 
\begin{align*} S_N(\mu_s|\n_q)\geq-\int\Big[\tau_{-\kappa N,N+1}^{(1-s)}(&\uptau(x_0,x_1))\rho^{q}_0(x_0)^{-\frac{1}{N}} \\&+\tau_{-\kappa N,N+1}^{(s)}(\uptau(x_0,x_1))\rho^{q}_1(x_1)^{-\frac{1}{N}}\Big]\,\dint\left((\e_0, \e_1)_\sharp\Pi^k\right)(x_0,x_1).\end{align*}
Hence, $(\I\times_f (L_0,L_1), \n_q)$ satisfies $\tCD_p(-\kappa N, N+1)$ for $\mathfrak q$-a.e.\ $q\in \tilde Q$.
\end{proof}
\begin{cor}
For $\mathfrak q$-a.e.\ ${q} \in Q$ the needle $(X_{ q}, \m_{ q})$ satisfies the condition $\CD(\eta (N-1), N)$ where $\eta =\sup_I\{-(f')^2 + \kappa f^2\}$, and 
$$f''-\kappa f\leq 0.$$\end{cor}
\begin{proof} By Proposition \ref{prop:cdslice} and by Theorem \ref{th:lasttheorem} it follows that $h_q|_{(L_0, L_1)} $  for $\mathfrak q$-a.e.\  $q \in \tilde Q$ is a $\CD(\eta(N-1), N)$-density and $f$ satisfies $f''-\kappa f\leq 0$.

Let $(L_0^i, L_1^i)$ be a countable collection of open intervals such that $\forall q \in Q$ and $\forall t_0\in (a_q, b_q)$ there exists $i\in \N$ such that $t_0\in (L^i_0, L_1^i)\subseteq (a_q, b_q)$. Given the $\tilde Q^i$ associated to $(L^i_0, L_1^i)$ we have that $h_q$ restricted to $(L^i_0, L^i_1)$ is as above for $\mathfrak q$-a.e.\ $q\in \tilde Q^i$. In other words, there exists $\mathcal N^i$ with $\mathfrak q(\mathcal N^i)=0$ such that $h_q|_{(L^i_0, L^i_1)}$ is such a density $\forall q \in \tilde Q^i\setminus\mathcal N^i$. We set $\mathcal N:= \bigcup_i \mathcal N_i$, which is still a null set. Hence, $\forall q\in Q\setminus \mathcal N$ and $\forall t_0\in (a_q, b_q)$ there exists a neighbourhood of $t_0$ such that $h_{\ q}$ is a $\CD(\eta(N-1), N)$ density. Consequently $\forall q \in Q\setminus\mathcal N$ we have that $h_q$ is a $\CD(\eta(N-1), N)$ density. 
\end{proof}

\begin{proof}[\it Proof of \Cref{Th: Y to X}.]
Since the distance function $\met_\phi$ from which we derived the needle decomposition on $X$ was arbitrary we obtain  \Cref{Th: Y to X} from Theorem \ref{thm:cavmil}.\end{proof}



\section{Applications}\label{sec-app}
{In this final section we give several applications, in particular we provide new examples of \LLSn s which satisfy the timelike measure contraction property. Also, we point out several open questions.}

\subsection{New examples of spaces with synthetic timelike Ricci curvature bounds}\label{subsec-new-ex}
\subsubsection{Generalized cones as Lorentzian length spaces}
\Cref{th:totmcp} provides a new class of examples of measured Lorentzian length spaces $\I\times_f^N X$ that satisfy a timelike measure contraction property $\tmcp$, i.e., a generalized strong energy condition.

Let $f: I\rightarrow [0, \infty)$ be a smooth function such that \begin{enumerate}
    \item $f$ is $(-\kappa)$-concave, and
    \item $ \kappa f^2 - (f')^2\leq \eta$. 
\end{enumerate}
We can now pick any essentially nonbranching $\CD(\eta(N-1), N)$ space $X$ to produce a generalized cone ${}^-I \times_f^N X$ that is a measured Lorentzian geodesic space satisfying the condition $\tmcp(-\kappa N, N+1)$. 

In particular,  we can choose  $X$ as an  $\RCD(\eta(N-1), N)$ space. By now there is wide spectrum of different classes of metric measure spaces that satisfy an $\RCD$ condition:
\begin{itemize}
    \item $N$-dimensional Alexandrov spaces with curvature bounded from below $\eta$ \cite{pet11}.
    \item Ricci limit spaces, i.e., metric measure spaces that arise as pointed measured Gromov--Hausdorff limits of Riemannian manifolds with Ricci curvature bounded from below by $\eta (N-1)$ and dimension bounded from above by $N$ \cite{Stu:06a, Stu:06b, LV:09, gsm15}.
    \item Weighted $N$-dimensional Riemannian manifolds whose Bakry--\'Emery $N$-Ricci tensor is bounded from below by $\eta (N-1)$ \cite{Stu:06a, Stu:06b, LV:09}.
    \item $N$-dimensional smooth manifolds equipped with a $C^0$-Riemannian metric that satisfy a lower Ricci curvature bound $\eta (N-1)$ in the distributional sense \cite{mr24}.
    \item $N$-dimensional stratified spaces that satisfy a generalized lower Ricci curvature bound $\eta (N-1)$ \cite{bkmr21}.
\end{itemize}
{This leads to the following natural question (to which we expect a positive answer).}
\begin{que} Is $I\times^N_f X$ infinitesimal Minkowskian in the sense of \cite[Def.\ 1.4]{BBCGMORS:24} if the metric measure space $X$ is infinitesimal Hilbertian?
\end{que}
The more general class of $\CD$ spaces includes
\begin{itemize}
\item Weighted $N$-dimensional Finsler manifolds such that the generalized Bakry--\'Emery\\ $N$-Ricci curvature is bounded from below by $\eta (N-1)$ \cite{ohta_interpolation}.
\end{itemize}

We can also choose $f$ to be $(-\kappa)$-affine, i.e., $f''- \kappa f=0$. Then $\kappa f^2 - (f')^2 \equiv \eta\in \R$. By rescaling $f$ and $I$ we can assume $\kappa, \eta \in \{-1, 0, +1\}$. 
Since $\partial I= f^{-1}(\{0\})$, it follows that, up to Lorentzian isometries,  we have precisely the following list of examples. Here $X$ is a general metric measure space.
\begin{enumerate}
    \item[(L1)] Anti-de-Sitter $N$-suspension: $^-[0,\pi]\times_{\sin}^N X$,
    \item[(L2)] Minkowski $N$-cone: $^-[0, \infty)\times_{\mathrm{id}}^N X$, 
    \item[(L3)] Minkowski product: $^-[0, \infty)\times X$, 
    \item[(L4)] Lorentzian Elliptic $N$-cone: $^-[0, \infty)\times^N_{\sinh} X$, 
    \item[(L5)] Lorentzian Parabolic $N$-cone: $^-\R\times_{\exp}^N X$, 
    \item[(L6)] De-Sitter $N$-cone: $^-\R\times^N_{\cosh} X$. 
