     \begin{definition}[\ac{pdfa} extended from \cite{rahmani2023probabilistic}]
		\label{def:pdfa}
		A \ac{pdfa} over an alphabet $\Sigma$ is a tuple $\pdfa= \langle Q, \Sigma, \delta, q_0, O, \succeq, \lambda \rangle$ in which 
        $Q$ is a finite set of states, $\Sigma$ is the alphabet, $\delta: Q \times \Sigma \rightarrow Q$ is the deterministic transition function, $q_0$ is the initial state,
        $O$ is a finite set of \emph{ranks}, and $\succeq\subseteq O^2$ is a \emph{partial order}, which is a reflexive, transitive, and anti-symmetric relation, on $O$, and $\lambda: Q \rightarrow O$ is the \emph{ranking} function, which maps each state $q\in Q$ to a unique rank $o \in O$ and is a complete and surjective function.
	\end{definition} 
        %
        Note that this definition replaces the set of accepting (final) states of a DFA with the partial order relation on accepting conditions.
		%
        A \ac{pdfa} is readily visualized as a finite automaton along with a directed acyclic graph showing the partial order.
        %

		The \ac{pdfa} encodes a preference model $\succeq$ for $\Sigma^\ast$ as follows. 
		%
		Consider two words $w, w' \in \Sigma^\ast$, and let $q = \delta(q_0, w)$ and $q' = \delta(q_0, w')$.
		%
        There are four cases:
        (1) if $\lambda(q) = \lambda(q')$, then $w \sim w'$; (2) if $\lambda(q)  \succ  \lambda(q')$, then $w \succ w'$; (3) if $\lambda(q') \succ \lambda(q)$, then $w' \succ w$; and (4) otherwise, $w \nparallel w'$.
  %
        A preference model $\langle \Sigma^\ast, \succeq \rangle$ is called \emph{regular} if and only if it can be represented by a \ac{pdfa}.

        Two \ac{pdfa}s $\pdfa= \langle Q, \Sigma, \delta, q_0, O, \succeq, \lambda \rangle$ and 
        $\pdfa'= \langle Q', \Sigma, \delta', q_0', O', \succeq', \lambda' \rangle$ are \emph{equivalent} if they encode the same preorder over $\Sigma^*$.
        %
        Formally, they are equivalent if for any $w_1, w_2 \in \Sigma^*$, assuming $q_1 = \delta(q_0, w_1)$, $q_2 = \delta(q_0, w_2)$, $q_1' = \delta'(q_0', w_1')$, and $q_2' = \delta'(q_0', w_2')$, (1) $\lambda(q_1) = \lambda(q_2)$ iff $\lambda'(q_1') = '\lambda'(q_2')$, (2) $\lambda(q_1) \succ \lambda(q_2)$ iff $\lambda'(q_1') \succ' \lambda'(q_2')$, and (3) $\lambda(q_2) \succ \lambda(q_1)$ iff $\lambda'(q_2') \succ' \lambda'(q_1')$.

        %
      % \deleted{  A \ac{pdfa} $\pdfa$ specifies a preference model over $\Sigma^\ast$, which is denoted $P(\pdfa)$.}
