          \begin{definition}
        \label{def:sample}
            A finite set $S \subseteq \Sigma^\ast \times \Sigma^\ast \times \{0, 1, \perp \}$  is called a \emph{preference sample}, or simply a \emph{sample}, where for each 
        $(w, w', b) \in S$, 
        %
        \begin{enumerate}
            \item $b  = 0$ means $w$ and $w'$ are indifferent to each other,
            \item $b   = 1$ means $w$ is strictly preferred to $w'$, and
            \item $b  = \perp$ means $w$ and $w'$ are incomparable.
        \end{enumerate}
        \end{definition}
        %\jf{Define $W_S?$}
        %
        A sample is readily visualized as a `multi-edge-sets' graph with three sets of edges, one set of solid undirected edges for representing
        the pairs of indifferent words, one set of solid directed edges for representing the strict preference relation, and 
        one set of undirected and dashed edges for representing the incomparable pairs of words.  The set of words that appear in $S$ is denoted $W_S$, formally defined as $W_S = \{w \in \Sigma^* \mid \exists w' \in \Sigma^\ast, b\in \{0,1,\perp\}: (w, w', b) \in S \text{ or } (w', w, b) \in S \}$.
        %

        \begin{definition}
        \label{def:consistent}
           A \ac{pdfa} $\pdfa= \langle Q, \Sigma, \delta, q_0, O, \succeq, \lambda \rangle$ and a sample $S$ are \emph{consistent} with each other, if for each
           $(w, w', b) \in S$, 
            \begin{itemize}
                \item if $b  =0$, then $w \sim w'$;
                \item if $b = 1$, then $w \succ w'$; and
                \item if $b = \perp$, then  $w \nparallel w'$.
            \end{itemize}
        \end{definition}

