\section{Hardness of learning preference model}
\label{sec:hardness}
%
A regular preference model may be represented by more than one  \ac{pdfa}s.
 %
 Among them, there is a   \ac{pdfa}  that has the smallest number of states, referred to as the \emph{canonical \ac{pdfa}}.
 %
Ideally, for a given sample $S$, we would like to find a canonical \ac{pdfa}  consistent with $S$. 
        %

        To understand the complexity of learning a \ac{pdfa} from a given sample, we first consider the following problem.
        %
       %\deleted{ Given a regular preference model $P=\langle \Sigma^\ast, \succeq \rangle$, the smallest \ac{pdfa} $\pdfa$ such that $P(\pdfa) = P$ is called the \emph{canonical} \ac{pdfa} for $P$, and is denoted $\pdfa(P)$.}
        %
        %
        \decproblembox{Minimum Consistent PDFA (\MCPDFA)}
        %
        {A sample $S=\{ (w_1, w_1', b_1), \cdots, (w_n, w_n', b_n) \}$ and a positive integer $k$.}
        {\Yes  if there exists a \ac{pdfa} with at most $k$ states that is consistent with $S$, otherwise \No.}
        %
        Note if the canonical \ac{pdfa} from which the sample is drawn has at most $k$ states, then the answer to this decision problem is \Yes.
        However, if the answer to this is problem is \Yes, it is still unknown whether the canonical \ac{pdfa} has at most $k$ states or not.
        Yet, understanding the hardness of this problem sheds lights on how difficult is to learn an exact regular preference model from which a sample is drawn.

         Regarding this decision problem, we present the following result.
         \begin{lemma}
		\label{lem:NP}
        \MCPDFA $\in \NP$.
		\end{lemma}
%
		\begin{proof}
            We need to show that given a \ac{pdfa} $\pdfa= \langle Q, \Sigma, \delta, q_0, O, \succeq, \lambda \rangle$ as a certificate, we can verify in polynomial time to size of $S$ both (1) whether $\pdfa$ has at most $k$ states, and that (2) $\pdfa$ is consistent with $S$.
		    Trivially, in constant time we can check (1).
            %
            Assume the transition and the ranking functions are encoded as hash tables.
            %
            If not, one can clearly construct those hash tables in polynomial time.
            %
            In respect with (2), for each $(w_i, w_i', b_i) \in S$, in time $\bigO(|w_i|+|w_i'|)$ we can obtain $\delta(q_0, w_i)$ and $\delta(q_0, w_i')$ and then in constant time we can check whether $(w_i, w_i', b_i)$ is consistent with $\pdfa$, using the rules in Definition~\ref{def:consistent}. 
            %
            Accordingly, checking whether $S$ is consistent with the \ac{pdfa} takes $\bigO(\sum_{1 \leq i \leq n}(|w_i|+|w_i'|))$, which is a polynomial time to the size of $S$.
        \end{proof}
        % 

        To further study the hardness of \MCPDFA, we first consider the classical problem of learning a minimal consistent deterministic finite automaton from positive and negative data.
        %
        \decproblembox{Minimum Consistent DFA \MCDFA}
        {A finite non-empty set $S^+ \in 2^{\Sigma^\ast}$, a finite non-empty set $S^- \in 2^{\Sigma^\ast}$, and an integer $k'$}
        {\Yes if there exists a \ac{dfa} $A=(Q, \Sigma, \delta, q_0, F)$ such that $S^+ \subseteq L(A)$, $S^- \cap L(A) = \emptyset$, and $ |Q| \leq k'$, and \No otherwise.  } 
        %
        %Intuitively, the purpose of the minimization version of this decision problem is to find a minimum DFA that accepts all the words in $S^+$ and rejects all the words in $S^-$.
        % %
        % It is well-known that this problem is computationally hard. 
        %  \jf{missing reference}.
        % %
        \begin{proposition}
    		\label{pro:NP-hard}
            \MCDFA $\in \NP$-hard.
        \end{proposition}
        \begin{proof}
            See the proofs in \cite{gold1978complexity,lingg2024learning}.
        \end{proof}
        %
        We use this result to prove that the preference learning problem \MCPDFA is computationally hard.
        %
        \begin{theorem}
        \label{thr:NP-hard}
            \MCPDFA $\in \NP$-hard.
        \end{theorem}
        %
        \begin{proof}
            By reduction from \MCDFA.
            %
            Given an instance $$x = \langle S^+, S^-, k \rangle$$ we construct an instance $$y = \langle S, k \rangle,$$ where
            \begin{multline}
                S = \{ (w, w', 0) \mid w, w' \in S^+ \} \cup \{ (w, w', 0) \mid w, w' \in S^- \} \\ 
                \cup \{ (w, w', 1) \mid w \in S^+ \text{ and } w' \in S^- \} \notag.
            \end{multline}
            %
            We need to show that (1) the reduction takes a polynomial time, and (2) the reduction is correct.
            %
            It holds that $\abs{S} = \abs{S^+}^2+\abs{S^-}^2+\abs{S^+}\abs{S^-}$, and clearly, the reduction takes a polynomial time.
            %

            For the correctness of the reduction, we show that \MCDFA produces \Yes for instance $x$ if and only if \MCPDFA produces $\Yes$ for instance
            $y$.
            %

            ($\Rightarrow$) Suppose \MCDFA produces \Yes for instance $x$, i.e., there exists a DFA $A = (Q, \Sigma, \delta, q_0, F)$ such that $|Q| \leq k$, $S^+ \subseteq L(A)$, and $S^- \cap L(A) = \emptyset$.
            %
            We construct \ac{pdfa} $\pdfa = (Q, \Sigma, \delta, q_0, O, \succeq, \lambda)$ in which $O= \{1, 2\}$, $\succeq = \{(1, 1), (2, 2), (1, 2)\}$, and
            for each $q \in Q$, let $\lambda(q) = 1$ if $q \in F$, and $\lambda(q) = 2$ otherwise.
            %
            By the construction of $S$, for each $(w, w', b) \in S$, it holds that $b \in \{0, 1 \}$ and
            \begin{itemize}
                \item If $b=0$, then it means  $\lambda(\delta(q_0, w)) = \lambda(\delta(q_0, w'))$, and thus
                 $w \sim w'$;
                 \item If $b=1$, then it means $\lambda(\delta(q_0, w)) = 1$ and $\lambda(\delta(q_0, w'))=2$, and because $1 \succeq 2$, $w \succ w'$.
            \end{itemize}
            %
            Therefore, $\pdfa$ is consistent with $S$, and because $\pdfa$ has $k$ states, \MCPDFA produces \Yes for $y$.

            ($\Leftarrow$) Suppose \MCPDFA produces \Yes for instance $y$, i.e., there exists a \ac{pdfa} $\pdfa = (Q, \Sigma, \delta, q_0, O, \succeq, \lambda)$ consistent with $S$ such that $|Q| \leq k$.
            %
            Because $S^+$ and $S^-$ are non-empty, there exists a tuple $(w, w', 1) \in S$. 
            %
            This means that $O$ contains at least two distinct ranks $o_1$ and $o_2$ such that $\lambda(\delta(q_0, w))=o_1$, $\lambda(\delta(q_0, w'))=o_2$, and  either  $o_1 \succ o_2$ or $o_2 \succ o_1$.
            % \hr{It is OK the either to be there. Because up to this point, we only have considered the fact that $S^+$ and $S^-$ are non-empty. We only need to add the following in blue.}
            %
            Additionally, because $S$ is consistent with $\pdfa$, it must be the case that for all $w \in S^+$, $\lambda(\delta(q_0, w))= o_1$,   for all
            $w' \in S^-$, $\lambda(\delta(q_0, w'))=o_2$, and that $o_1 \succ o_2$. 
            %
            Let $F = \{q \in Q \mid \lambda(q) = o_1 \}$.
            %
            Accordingly, for the DFA $A = (Q, \Sigma, \delta, q_0, F)$, $S^+ \subseteq L(A)$ and that $S^-  \cap  L(A) = \emptyset$.
            %
            Because DFA $A$ is consistent with $S^+$ and $S^-$ and that $|Q| \leq k$, the answer of \MCDFA given $x$ is \Yes if the answer of \MCPDFA to $y$ is
            \Yes.
            %
            This completes the proof.
        \end{proof}
        %

        Accordingly, we the following result holds.
        %
        \begin{theorem}
        \label{thr:NP-Complete}
            \MCPDFA $\in \NP$-Complete.
        \end{theorem}
        %
        \begin{proof}
            It follows from Lemma~\ref{lem:NP} and Theorem~\ref{thr:NP-hard}.
        \end{proof}

        The impact of this result is that assuming $\P \neq \NP$, there exists no algorithm that  can efficiently compute the minimum \ac{pdfa} consistent with an arbitrary sample $S$. 
