We introduce some notations: Let $W \subseteq \Sigma^\ast $ be a set and $\pi =\{B_1,\ldots, B_{\abs{\pi}}\}$ be a partition of the set $W$, that is, $B_i \neq \emptyset$ for all $i$'s, $\cup_{i=1}^{\abs{\pi}} B_i = W$, and $B_i\cap B_j=\emptyset$ if $i\ne j$.

\begin{definition}
  Given a partition $\pi$ over a set $W$,  for each $w\in W$, the \emph{block} in partition $\pi$ that contains $w$ is denoted by $B(w, \pi)$.
\end{definition}

%
%}

        \begin{definition}
        \label{def:eq_graph}
  Given a sample $S \subset \Sigma^* \times \Sigma^* \times \{0, 1, \perp\}$,   the \emph{indifference graph} for   sample  $S$ is an undirected graph $G_{\sim}=(W_S, E_{\sim})$ where for each $w, u \in W_S$, 
        $\{w, u\} \in E_\sim$ iff $\{(w, u, 0), (u, w, 0)\} \cap S \neq \emptyset$.
        \end{definition}
        %
      Note that even though the sample might not directly compare two words $u,w$, we may derive these two words to be indifferent  using the transitive closure of this relation.
        %
        %This can happen when the vertices connecting those two words are connected in this graph.
        %
        %
%       Accordingly, in the next step, the algorithm decomposes this graph into its set of strongly connected components. 
        %
        We let $\pi_S$ to be the set of strongly connected components (SCCs) of $G_\sim$, i.e., $\pi_S=\SCCs(G_\sim)$. 
        Clearly, $\pi_S$ is partition of $W_S$. Also, for each $w\in W_S$,  any $ w' \in B(w, \pi_S )$ is indifferent to $w$ by construction. 
        Using these, we create a partial order in the following.

 Let $\rankS$ be the index set of $\pi_S$, \ie,  $\rankS =\{1,\ldots,|\pi_S| \}$. Let $C_i$ be the $i$-th SCC in $\pi_S$.
        We construct a relation $R_S$ over the set of indices $\rankS$ as follows:
        %
        \begin{equation}
        \label{eq:relation-rank}
            R_S = \{(i, j) \mid \exists w \in C_i, w' \in C_j : (w, w', 1) \in S \}
        \end{equation}

         %\jf{the definition of $R_S$ is incorrect. What is the relation between $w, w'$ and $B, B'$?}
        %\hr{Fixed it.}
The partial order, denoted $\succeq_S$, is constructed as the union of the reflexive closure and the transitive closure of $R_S$.
        %


    \begin{definition}
    \label{def:pt} Given a sample $S$, its indifference graph $G_{\sim}$, the index set $\rankS$ of SCCs and relation $R_S$ constructed from $G_\sim$,  a prefix tree \ac{pdfa} $\PTree_S = (\Pref(W_S)=\{u_0,\ldots, u_r\}, \Sigma, \delta_S, u_0 \coloneqq \epsilon, O\coloneqq \rankS, \succeq_S, \lambda_S)$ 
    in which 
    \begin{itemize}
    \item $\Pref(W_S)$ is a set of states in the prefix tree \ac{pnfa}, which is the set of all prefixes of the words appeared in the sample. In particular, let  $u_0, u_1, \cdots, u_r$ where $r = |\Pref(W_S)|$ be the  states within $  \PTree_S$ indexed with the lexicographical ordering.
    \item $\Sigma$ is the alphabet.
    \item The transition function $\delta_S$ is defined as follows:
      For each $w \in \Pref(W_S)$, $a \in \Sigma$ and $wa \in \Pref(W_S)$, $\delta_S(w, a)=wa$. % ; and 
  %  \end{itemize}
    \item $u_0 = \epsilon$, the empty string, is the initial state.
    \item $\rankS$ is the set of ranks.   
    \item $\succeq_S$ is the partial order relation on $\rankS$.
    \item $\lambda_S: \Pref(W_S) \rightarrow \rankS \cup \{\varnothing\}$ is defined such that 
each prefix $u \in \Pref(W_S)  \cap W_S $ is mapped to the index $i$ of the SCC that contains $u$. That is, if $C_i\in \pi_S$ contains $u$, then $\lambda_S(u)=i$.  For each $u \in \Pref(W_S) \setminus W_S$, $\lambda_S(u)=\varnothing$, meaning   $\lambda_S$ is undefined for $u$. 
     \end{itemize}
     \end{definition}
     By construction of SCCs, the rank of each state in the prefix-tree automaton is unique.

Slightly abusing notation, we use each subset (block) of the partition $\rankS$ to denote a rank. It can be understood as each subset is associated with a unique index and the ranks are the set of indices.

