We lift the lexicographical ordering $<_L$ on to the blocks of a given partition such that given $B_1, B_2 \in \pi$,
$B_1 <_L B_2$ iff $\eta(B_1) <_L \eta(B_2)$.
%}

Algorithm~\ref{alg:euclid} begins with an initial partition $\pi_0$ (line~\ref{line:initial_parition}), and then, in lexicographical ordering, iteratively performs joining of blocks and determinization of the automaton to update the partition for $n$ steps where $n$ is the number of states in the $\PTree_S$. At the end, it returns the partition $\pi_r\coloneqq \pi_n$ and the quotient \ac{pdfa} $\calA_r \coloneqq D(\calA_0/\pi_r)$. 


\begin{algorithm}
\caption{LearnPDFA}\label{alg:euclid}
\begin{algorithmic}[1]
\Procedure{LearnPDFA}{$\PTree_S$} %\Comment{The g.c.d. of a and b}
\State $\pi_0 \gets \{ \{u_0\}, \{u_1\}, \cdots, \{u_n\} \}$ 
\label{line:initial_parition}
\State $\calA_0 \gets \PTree_S$.
\For{$i \gets 1$ \textbf{to} $n$} \label{line:outer_loop_start}
\State $\Merged \gets \False$
\If{$\text{exists } B_i \in \pi_{i-1} \text{ s.t. } u_i = \eta(B_i)$}
\For{$B <_L B_i$ in the ascending order} \label{line:for_loop_start} %\Comment{We have the answer if r is 0}
\If{$\lambda_S(B)=\lambda_S(B_i) \text{ or } \lambda_S(B) = \undefined \text{ or } \lambda_S(B_i) = \undefined$}
\If{$ D(\pnfa_0 / J(\pi_{i-1}, B, B_i)) \neq \undefined$} \label{line:check_determinization}
\State $\pi_i = DJ(\pi_{i-1}, B, B_i)$ 
\label{line:join_deter}
\State $\calA_i \gets D(A_0/\pi_i)$,
 \State  $\Merged \gets \True$
\State $\textbf{break}$
\EndIf
\EndIf
\EndFor\label{line:for_loop_end}
\EndIf
\If{$\Merged == \False$}
\State $\pi_i \gets \pi_{i-1}$
\State $\calA_i \gets \calA_{i-1}$

\EndIf
\EndFor \label{line:outer_loop_end}
\State \textbf{return} $\pi_r\gets \pi_n$, $\calA_r  \gets \calA_n $ %\Comment{The gcd is b}
\EndProcedure
\end{algorithmic}
\end{algorithm}

