\section{Identification in the limit}
%
\label{sec:iden_in_limit}
%
Though Algorithm~\ref{alg:euclid}
learns a \ac{pdfa}, its correctness  in learning a \ac{pdfa} equivalent to the \ac{pdfa} from which the sample is generated,  is only ensured when the sample satisfies a specific condition. 
In this section, we define the condition of sample and prove that if a given sample satisfies this condition, then the proposed algorithm accurately learns the canonical \ac{pdfa} of the   preference model from the sample is drawn from. 
        %

We first introduce two definitions, extending the shortest prefix and nucleus of a \ac{dfa}~\cite{oncina1992identifying} to those of a \ac{pdfa}.
        %\jf{add citation}
\begin{definition}
\label{def:short_nucl}
Let $\pdfa= \langle Q, \Sigma, \delta, q_0, O, \succeq, \lambda  \rangle$ be the minimal \ac{pdfa} the sample $S$ is drawn from.
%
Given a state $q \in Q$, the \emph{shortest prefix} of $q$, denoted $\SPref(q)$, is the shortest word in the lexicographical ordering of $\Sigma^*$ that reaches state $q$, \ie, 
\begin{multline*}
\SPref(q)  \in \Sigma^\ast 
\text{ such that, } \delta (q_0, \SPref(q) )=q \text{ and } \\
\forall w' \in \Sigma^\ast,\delta (q_0, w')=q \implies w' >_L \SPref(q)   .
  \end{multline*}
% \hr{Maybe we want $\SPref(q)$ be a state instead of a set?}
% \jf{changed to a state}
Note that by construction $\SPref(q)$ is a singleton. Thus, we use  $\SPref(q)$ to refer to the shortest prefix for state $q$.
 The \emph{shortest prefixes of $\pdfa$}, denoted $\SPref(\pdfa)$, is the set of all the short prefixes of the states within $\pdfa$, i.e.,
\[
\SPref(\pdfa) =  \{\SPref(q) \mid q \in Q \}.
\]
% \hr{
% If $\SPref(q)$ is a set, then we need to change this definition as $\SPref(\pdfa) = \bigcup_{q \in Q} \{ \SPref(q) \}$.
% }
% ---ADDRESSED. SP is a single word.
\end{definition}
The \emph{nucleus} of $\pdfa$, denoted $\NU(\pdfa)$, is the set of all one-letter extensions of the words within $\SPref(\pdfa)$ and the empty string,
\[
\NU(\pdfa) = \{ ua \mid u \in \SPref(\pdfa) \text{ and } a \in \Sigma \} \cup \{\epsilon\}.
\]
%
While the shortest prefixes set contains the set of minimal words required to reach all the states of $\pdfa$, the nucleus contains a set of words that cover all the transitions in the automaton, including the transition on `empty string'   that reaches the initial state.
%

\begin{example} Consider the \ac{pdfa} in Figure~\ref{fig:pdfa}.
%
For this \ac{pdfa}, $\SPref(00) = \{ \epsilon \}$, $\SPref(10) = \{a\}$, $\SPref(01) = \{b\}$, $\SPref(11) = \{ab\}$.
%
Accordingly,
\[
\SPref(\pdfa) = \{\epsilon, a, b, ab \}
\]
and
\[
\NU(\pdfa) = \{\epsilon, a, b, aa, ab, ba, bb, aba, abb \}.
\]
\end{example}
%

\begin{definition}
        \label{def:closureS}
            Given a sample $S \subset \Sigma^* \times \Sigma^* \times \{0, 1, \perp\}$, the \emph{transitive closure} of $S$, denoted $S^\circ$, is the minimal
            subset  $S' \subset \Sigma^* \times \Sigma^* \times \{0, 1, \perp \}$ 
            such that 
            \begin{enumerate}
                \item $S \subseteq S'$;
                \item \label{cond:eq_reflexive} $\{(w, w, 0) \mid w \in W_S \} \subseteq S'$;
                \item \label{cond:eq_incomp_symmetric} for $b \in \{0, \perp\}$, if $(w, w', b) \in S'$, then $(w', w, b) \in S'$;
            %     \item \label{cond:eq_transitive} if $(w, w', 0) \in S^\circ$ and $(w', w'', 0) \in S^\circ$, then $(w, w'', 0) \in S^\circ$; and
                \item \label{cond:eq_succ_transitive} for $b\in \{0,1\}$, if $(w, w', b) \in S'$ and $(w', w'', b) \in S'$, then $(w, w'', b) \in S'$;
                \item \label{cond:eq_succ_incomp} for $b \in \{1, \perp \}$, if $(w, w', 0) \in S'$ and $(w', w'', b) \in S'$, then $(w, w'', b) \in S'$; and
                \item \label{cond:succ_incomp_eq} for $b \in \{1, \perp\}$, if $(w, w', b) \in S'$ and $(w', w'', 0) \in S'$, then $(w, w'', b) \in S'$.
            \end{enumerate}
        % 
        \end{definition}
        %
        % Intuitively, Condition~\ref{cond:eq_symmetric} and ~\ref{cond:eq_transitive}, ensure that the relation $R = \{(w, w') \in \Sigma^* \times \Sigma^* \mid (w, w', 0) \in S^\circ \}$, is symmetric and transitive, and Condition~\ref{cond:succ_transitive}  guarantees that the relation $R' = \{ (w, w') \in \Sigma^* \times \Sigma^* \mid (w, w', 1) \in S^\circ \}$ is transitive.
        % %

    Notice that the size of $S^\circ$ is polynomial to the size of $S$. 
    %
    More precisely, $|S^\circ| = \bigO(|S|^2)$. 
    %
    This is because between any two words $w, w' \in W_S$, at most one tuple $(w, w', b)$ could exist in $S^\circ$, and that $|W_S| = O(|S|)$.
    %  
    The time required to construct $S^\circ$ is polynomial to the size of $S$.
    %
    To construct $S^\circ$, one can extend common algorithms used for making the transitive closure of a relation.
    %
    For example, we can extend the Floyed-Warshall algorithm~\cite{floyd1962algorithm}, by which, the time complexity will be $\bigO(|W_S|^3)=\bigO(|S|^3)$.

    These above definitions are used to identify a family of samples for which our algorithm can efficiently learn the canonical \ac{pdfa} the sample is drawn from.
    %
 %    We introduce this family of samples in the following definition.
\begin{definition}
\label{def:char_set}
Let $\pdfa= \langle Q, \Sigma, \delta, q_0, O, \succeq, \lambda \rangle$ be the minimal \ac{pdfa} where a sample $S$ is drawn from.  
%
This sample  $S$ is \emph{characteristic} if
\begin{enumerate}
    \item \label{itm:char_nu_subset} $\NU(\pdfa) \subseteq \Pref(W_S)$;
    \item \label{itm:char_sp_and_nu} for each $w \in \SPref(\pdfa)$ and $u \in \NU(\pdfa)$, if $\delta (q_0, w) \neq \delta (q_0, u)$, then there exists $y \in \Sigma^*$ such that
        $wy \in W_S$ and $uy \in W_S$, and $$\{(wy, uy, 1), (uy, wy, 1), (wy, uy, \perp)\} \cap S^\circ \neq \emptyset;$$
    %\item \label{itm:char_pref_graph} For each $o \in O$, $\bigcup_{w \in W_S: \lambda(\delta(q_0, w))=o} \{ w \} \neq \emptyset$;  and
    \item \label{itm:char_pref_graph} For each $q \in Q$, there exists $w \in W_S$ such that $\delta(q_0, w) = q$;  and
    \item \label{itm:char_pref} for each $w, u \in W_S$, 
    \begin{enumerate}
        \item if $w \sim u$, then $(w, u, 0) \in S^\circ$,
        \item if $w \succ u$, then $(w, u, 1) \in S^\circ$,
        \item if $w \nparallel u$, then $\{(w, u, 0), (w, u, 1), (u, w, 1)\} \cap S^\circ = \emptyset$.
    \end{enumerate}
\end{enumerate}
\end{definition}
%
Condition~\ref{itm:char_nu_subset} indicates that any  transition of the canonical \ac{pdfa} can be   triggered by reading at least one prefixes of the sample.
%
Condition~\ref{itm:char_sp_and_nu} guarantees that the states corresponding to those two words $w$ and $u$ in the prefix tree automaton are not merged by the algorithm (see  the proofs next). 
Conditions~\ref{itm:char_pref_graph} ensures that each rank is represented by at least one word within the sample. Condition~\ref{itm:char_pref}    ensures the partial order over the set of ranks can be inferred correctly (see the proofs next). 
%
