\begin{lemma}
\label{lem:not_merged}
Consider a ranking-consistent partition $\pi$ of $W_S$, two blocks $B_1, B_2 \in \pi$ and two words $u_1 \in B_1$ and $u_2 \in B_2$ selected from two blocks. 
If there exists $y \in \Sigma^*$ such that one of the  tuples  $(u_1y,  u_2y, 1)$ or  $(u_2 y, u_1y, 1)$ or $(u_1y, u_2y, \perp)$ is included in $S^o$, then $D(\pdfa_0 / J(\pi, B_1, B_2)) = \undefined$, meaning that
  $B_1$ is not merged with $B_2$ by Algorithm~\ref{alg:euclid}.
\end{lemma}
