\begin{lemma}
\label{lem:state_mapping}
 The following properties hold:
\begin{enumerate}
    \item \label{itm:sp_in_blocks} For any $w \in \SPref(\pdfa)$, there exists $B \in \pi_r$ such that $w \in B$.    
    \item \label{itm:sp_to_block} For each $q \in Q$, there is a block $B \in \pi_r$ such that $\SPref(q) = \eta(B)$.
% \item \textcolor{red}{For each $B\in \pi_r$, there exists $ w \in \NU(\calA)$ that $w \in B$.}
    \item \label{itm:block_to_sp} For each $B \in \pi_r$, there is a state $q\in Q$  such that $q = \delta (q_0, \eta(B))$ and   
    $\eta(B) = \SPref(q)$. %$\eta(B) = \SPref(\delta(q_0, \eta(B)))$ %, meaning that the smallest word within each block of $\pi_r$ is the shortest prefix of the state in the canonical \ac{pdfa}, to which that word reaches. Because those smallest words are distinct, no two blocks within $\pi_r$ are mapped to the same state in the canonical \ac{pdfa}. 
\end{enumerate}
\end{lemma}
