\section{Bendixson inequalities}
\label{app:Bendixson}

\begin{theorem*}[Bendixson inequalities~\cite{bendixson1902}]
Let $M$ be an arbitrary real matrix, $z$ any one of its eigenvalues, and $x_m$ and $x_M$ respectively the smallest and largest eigenvalues of $(M+M^T)/2$, where ${M}^T$ denotes the transpose of $M$. Then,
\begin{equation}
    x_m\leq \Re z \leq x_M.
\end{equation}
\end{theorem*}

\begin{proof}
Let $B=M-x_m \id$ and $v$ be one of its eigenvectors with eigenvalue $y=z-x_m$, $Bv=yv$. We thus have to prove that $\Re y\geq 0$. Since $(B+B^T)/2$ is positive semidefinite by construction, we have
\begin{equation}
    0\leq \langle v, \frac{B+B^T}{2}v\rangle 
    =\frac{1}{2}\langle v, Bv\rangle + \frac{1}{2}\langle Bv, v \rangle
    =\Re y \ \langle v,v \rangle.
\end{equation}
Because $\langle v,v \rangle \geq 0$, we arrive at the desired result. The upper bound on $\Re y$ can be established in the same way by considering the matrix $C=x_M \id - M$.
\end{proof}


