\section{NO-based reinforcement learning framework}
In this section, we present the RL framework that integrates a pre-trained DeepONet with the SAC algorithm. We use a SAC framework with an actor network $ \pi_\phi(a_t|s_t) $, two critic networks $ Q_{\theta_i}(s_t,a_t) $, and their corresponding target networks $ Q_{\bar\theta_i}(s_t,a_t) $ (the dual-critic design mitigates bootstrapping issues). The DeepONet introduced in Section \ref{subsec_DeepONet}, is pre-trained using the backstepping controller,  which serves as a feature extractor and replaces the CNN layers in the standard SAC architecture. The DeepONet  connects directly to the actor/critic fully connected layers. During training, the actor and critic networks, along with their embedded DeepONet feature extractors, are jointly trained via backpropagation. The architecture of the RL is shown in  Fig. \ref{fig:1}. 

\begin{figure}[htbp]
	\centering
	\includegraphics[width=0.8\linewidth]{pictures/NOSAC2}
	\caption{\small The DeepONet pre-trained with the backstepping method is embedded into the SAC framework.}
	\label{fig:1}
\end{figure}

\subsection{Actor network} By introducing the policy entropy $ H_{\pi} $, it measures the randomness of the action distribution given the state $ s_t $. The policy entropy is defined as: $H(\pi(\cdot|s_t)) = -\mathbb{E}_{a_t \sim \pi_{\phi}} [\log \pi_{\phi}(a_t|s_t)]$. The policy network $\pi_{\phi}(a_t|s_t)$ is trained by minimizing the following objective function:
\begin{align} 
	\label{J}
	J_\pi({\phi}) = \mathbb{E}_{s_t \sim \mathcal{G}} \mathbb{E}_{a_t \sim \pi_{\phi}} \left[ -\alpha H(\pi_{\phi}(\cdot|s_t)) - \min_{i=1,2} Q_{\theta_i}(s_t, a_t) \right],
\end{align}
where $\mathcal{G}$ denotes the state distribution. Accordingly, the parameter $\phi$ of the policy network is updated by
\begin{align} 
	\label{pi}
\phi \leftarrow \phi - \eta \nabla_\phi J_\pi(\phi),
\end{align}
where $\eta$ denotes the learning rate.

\subsection{Critic networks} We use a double Q-network structure (two independent FNNs), the action-value function is defined as $ Q_\pi(s_t, a_t) $, which represents the expected cumulative return that the agent obtains by following the policy $ \pi_\phi $ after executing the action $ a_t $ in the state $ s_t $. Using two target networks $Q_{\bar\theta_{1,2}}$ to estimate the target action-value:
\begin{align} 
	\label{yt}
	y_t = r_t + \gamma \left( \min_{i=1,2} Q_{\bar\theta_i}(s_{t+1}, \hat{a}_{t+1}) - \alpha \log \pi_{\phi}(\hat{a}_{t+1}|s_{t+1}) \right),
\end{align}
$\alpha$ is the temperature parameter, which is used to balance the trade-off between reward maximization and policy entropy, and the action $\hat{a}_{t+1} \sim \pi(\cdot|s_{t+1})$ is sampled from the policy network. The weights of the target network $ Q_{\bar\theta_i} $ are updated by
\begin{align} 
\label{-theta}
\bar{\theta}_i \leftarrow \tau\theta_i + (1-\tau)\bar{\theta}_i,
\end{align}
where $ i \in \{1, 2\} $ and $ \tau \in (0, 1] $ denotes the weighted coefficient.



The action-value networks $ Q_{\theta_1}(s_t, a_t) $ and $ Q_{\theta_2}(s_t, a_t) $ are trained by minimizing the
following objective:
\begin{align} 
	\label{JQ}
	J_Q(\theta_i) = \mathbb{E}_{(s_t,a_t) \sim \mathcal{W}} \left[ (Q_{\theta_i}(s_t, a_t) - y_t)^2 \right],
\end{align}
where $ i \in \{1, 2\} $ and $\mathcal{W}$ is the distribution of the states and actions. The parameter $\theta_i$ is updated via stochastic gradient descent:
\begin{align}
\label{Jtheta}
\theta_i \leftarrow \theta_i - \lambda \hat\nabla_{\theta_i} {J}_Q(\theta_i), 
\end{align}
where $\lambda$ denotes the learning rate.

\subsection{Algorithm (Markov Decision Process)}
We have briefly outlined the processing of the Markov Decision Process (MDP), as shown in Algorithm \ref{alg:sac}. 


1) State space $ \mathcal{S} $: we denote $ s_t = \{u(x,t)\} \in \mathcal{S} $ as the augmented state at time $ t $.

2) Action space $ \mathcal{A} \subseteq \mathbb{R} $: it is defined as $ \mathcal{A} = [-\bar{U},\bar{U}] $, where $ \bar{U} = \sup_{t \in \mathbb{R}^+} |U(t)| $, $U(t) = a_t \in \mathcal{A}$.

3) Policy function $\pi(a_t|s_t)$: the policy is a probability density function $\pi(a_t|s_t)$ that maps the current state $s_t \in \mathcal{S}$ to a probability distribution over actions $a_t \in \mathcal{A}$.

4) State transition $ p(s_{t+1} | s_t, a_t) $: this $ p(s_{t+1} | s_t, a_t) $ is the probability distribution of $ s_{t+1} $, which depends on the current state $ s_t $ and the action $ a_t $ chosen by the agent. Given the state $ s_t $ at time $ t $, when the agent executes action $ a_t $, the environment transitions to the next state $ s_{t+1} $ following this probability distribution.  

5) Reward function $r_t$ and additional reward function $q$: it is designed to guide the learning of the optimal control policy. The reward function is defined as follows:
\begin{align}
r_t(s_t, s_{t+1}) &= -1 \cdot \| s_{t+1} - s_t \|_{L_2}, \label{eq:reward} \\
q(s_T, a_0, \ldots, a_T) &= 
\begin{cases} 
0 &  \| s_T \|_{L_2} > \zeta, \\
\begin{aligned}
\sigma - \dfrac{1}{\eta} \cdot \sum_{\tau=0}^T |a_\tau|_{L_1} \\
- \| s_t \|_{L_2} 
\end{aligned} &  \| s_T \|_{L_2} \leq \zeta,
\end{cases} \label{eq:q_function}
\end{align}
here, $\sigma$, $\eta$, and $\zeta$ are hyperparameters. 

The reward function $r_t$ is applied at each step to drive state convergence, while an additional reward $q$ is given at the end of each episode if the $L_2$ norm of the final state is less than or equal to a specified threshold $\zeta$.



\begin{algorithm}
\caption{SAC Procedure}
\label{alg:sac}
\begin{algorithmic}[1]  % 行号从 1 开始
\State Initialization: $\phi, \theta_i, \bar{\theta}_i$ for $i = 1, 2$, $\mathcal{W}$ and $s_0 = \{u_0(x)\}$
\For{$l \gets 0$ to $\text{total steps}$}
    \If{$\lVert s_t \rVert_{L_2} > \mathrm{limit} \lor t \geq T$}
        \State Reset initial state $s_0$
    \EndIf
    \State Observe current state $s_t = \{u_t\}$
    \State Sample action $a_t \sim \pi_\phi(a_t \mid s_t)$
    \State Execute $a_t$, observe $s_{t+1}$ and $r_t$
    \State $\mathcal{W} \gets \mathcal{W} \cup \{(s_t, a_t, r_t, s_{t+1})\}$
    \For{each gradient step}
        \State Sample a mini-batch from $\mathcal{W}$
        \State Compute the target value $y_t$ using (6)
        \State Update parameters of the $Q_{\theta_{1,2}}$ by (8)
        \State Update parameters of the $Q_{\bar{\theta}_{1,2}}$ by (5)
        \State Update parameters of the $\pi_\phi$ by (4)
    \EndFor
\EndFor
\end{algorithmic}
\end{algorithm}

\section{Simulation} 
