The $\lambda$-loop breaking procedure has the following properties.
\begin{lemma}
    $S = \{ v_1, v_3 \}$ is a tight set for $\bm{x} \uparrow^{v_3} (v_1, v_2)$.
\end{lemma}
\begin{proof}
Let $\bm{x}' = \bm{x}  \uparrow^{v_3} (v_1, v_2) $
\[\bm{x}^{\prime}(\delta(S))=\sum_{\substack{b \in \rev{V} \\ b \neq v_3}} x_{v_1 b}+\sum_{\substack{b \in \rev{V} \\ b \neq v_1}} x_{v_3 b} \]
given that
\[
\begin{aligned}
& \sum_{b \in V} x_{v_1 b} =1 \Rightarrow \sum_{\substack{b \in V \\
b \neq v_3}} x_{v_1 b} =1-x_{v_1 v_3}=1-\lambda, \\
& \sum_{b \in V} x_{v_3 b} =1 \Rightarrow \sum_{\substack{b \in V \\
b \neq v_1}} x_{v_3 b}=1-x_{v_3 v_1}=1-(1-\lambda)=\lambda, \\
& \Rightarrow \bm{x}^{\prime}(\delta(S))=1-\lambda+\lambda=1. \\
\end{aligned}\]
\end{proof}

\begin{lemma}\label{lemma:break_loops}
    If $\bm{x}$ is a vertex of $\pasep{n}$ that contains a $\lambda$-loop $\overleftrightarrow{v_1 v_2}$, then $\bm{x}  \uparrow^{v_3} (v_1, v_2)$ is a vertex of $\pasep{n + 1}$.
\end{lemma}
%
\begin{proof}
    Let $\bm{x}' := \bm{x}  \uparrow^{v_3} (v_1, v_2)$. Clearly $\bm{x}'$ is feasible. 
    %
    To show that \rev{$\bm{x}$} is \rev{also} a vertex, assume by contradiction that there exists $\bm{y}', \bm{z}' \in \pasep{n + 1}$ and $\mu \in (0, 1)$ such that
    $\bm{x}' = \mu \bm{y}' + (1 - \mu)\bm{z}'$.
    Let $S = \{v_1, v_3\}$. Note that 
    \begin{equation}\label{eq:convex_comb}
        \bm{x}'(\delta(S)) = 1 = \mu \bm{y}'(\delta(S)) + (1 - \mu)\bm{z}'(\delta(S)).
    \end{equation}
    As $\bm{y}', \bm{z}'$ are feasible, we have $\bm{y}'(\delta(S)) \geq 1$ and $\bm{z}'(\delta(S)) \geq 1$. As the equality should hold, we have then  $\bm{z}'(\delta(S)) = \bm{y}'(\delta(S)) = 1$.
    Thus, we have
    \[ 
        \bm{y} := \downarrow_{v_1} \bm{y}' (S) \quad \text{ and } \quad \bm{z} := \downarrow_{v_1} \bm{z}' (S). 
    \]
    Thanks to Lemma \ref{lemma:prop331}, $\bm{z}, \bm{y} \in \pasep{n}$.
    Clearly, $\bm{x} = \mu \bm{y} + (1-\mu)\bm{z}$.
    This can be verified entry by entry. As an example, consider the case $e = uv_1$:
    \begin{eqnarray*}
        \mu y_{u v_1}+(1-\mu) z_{u v_1}&=&
  \mu\left(y_{u v_1}^{\prime}+y_{u v_3}^{\prime}\right)+(1-\mu)\left(z_{u v_1}^{\prime}+z_{u v_3}^{\prime}\right)  \\ 
        &=& \left[\mu y_{u v_1}^{\prime}+(1-\mu) z_{u v_1}^{\prime}\right]+\left[\mu y_{u v_3}^{\prime}+(1-\mu) z_{u v_3}^{\prime}\right] \\
&=& x_{u v_1}^{\prime}+x_{u v_3}^{\prime}=x_{u v_1}.
    \end{eqnarray*}
    Thus, $\bm{x}$ is not a vertex of $\pasep{n}$, and we get a contradiction. 
\end{proof}


\begin{remark}
Note that the converse unfortunately does not hold, e.g., if you collapse a $\lambda$-loop into a single \rev{node}, you are not guaranteed to obtain a vertex. 
%
This will be particularly relevant in Section \ref{sec:new_lb} where we collapse instead $\lambda$-loops: after doing that, we have to check that what we obtain is again a vertex.
%
\rev{However, it always leads to a feasible point thanks to Lemma \ref{lemma:prop331}.}
\end{remark}

