This gives us a representative for 6 different orbits and, among them, we choose the one with the smallest number of zeros.
%
Figure \ref{fig:x0_6} reports its support graph.
%
Such vertex has entries equal to $\frac{k}{3}$, $k \in \{0, \ldots, 5\}$.
%
We start by pivoting from this vertex and collecting all its neighbors.
%
Then, among its neighbors, we move to the one having \rev{the smallest} number of zeros, and we proceed iteratively.
%
Different from the pivoting pipeline presented in \cite{elliott2008integrality}, we can recover at least one representative for each orbit.

%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{algorithm}
\DontPrintSemicolon
\SetAlgoLined
%\SetAlgoNoLine
\KwInput{$n$, Number of nodes of the ATSP instance under study}
\KwInput{$R := \{\bm{x}_i\}_{i\in I}$, list of vertices available for $n-1$}
\KwInput{$M$, Maximum number of iteration\rev{s} of algorithm}
\KwInput{$T_{tot}$, time limit for the whole iteration\rev{s}}
\KwInput{$T_{it}$, timelimit for the single iteration}
\KwOutput{$R'$, a collection of non isomorphic vertices of $\pasep{n}$}
$R'$ = Extend($R$) \;
$R'$ = SortByNumberOfZeros($R'$) \;
$ i = 0$ \;
$\bm{x}_0 = R'[i]$ \;
$ Ps = [ ] $ \;
\While{$i < M$ and time $< T_{tot}$}{
\If {$\bm{x}_0$ is not isomorphic to any vertex in $Ps$}{
$Ps$.append($\bm{x}_0$) \;
$\mathcal{N}'(\bm{x_0}) =$ Pivoting($\bm{x}_0,T_{it}$) \;
\For{$\bm{y} \in \mathcal{N}(\bm{x_0})$}{
\If {$\bm{y}$ is not isomorphic to any vertex in $R'$}{
$R'$.insert($\bm{y}$)
}
} 
$i \gets i+1$\;
$Ps$.append($R'[i]$) \;
}
}  
\Return $R'$
\caption{Generating vertices of $\pasep{n}$ \rev{via} the explore-exploit algorithm.\label{alg:expl}}
\end{algorithm}
