    \centering
    \includegraphics[width=1\linewidth]{New1.pdf} 
    \caption{
    \textbf{$\pt$-symmetry in spatial and temporal photonic crystals.}
     (a-b) Sinusoidal spatial (a) and temporal (b) modulation of permittivity that obeys $\pt$-symmetry. The spatial and temporal periodicity are noted as \(R\) and \(T\), respectively.
     }
    \label{fig:1}
\end{figure}


%
A time-domain version of the $\mathcal{PT}$-symmetry in a homogeneous but time-varying photonic medium of permittivity $\epsilon(t)$ could be defined as 
%
$
\epsilon(-t) = \epsilon^*(t),
$
where the asterisk denotes complex conjugation.
%
More specifically, for a periodic modulation of $\epsilon(t)$, in each period
there exists a time axis (chosen as $t=0$ in Fig.~\ref{fig:1} without loss of generality) such that the real part of the permittivity is symmetric in time, $\Re{\epsilon(t)} = \Re{\epsilon(-t)}$, and the imaginary part is antisymmetric, $\Im{\epsilon(t)} = -\Im{\epsilon(-t)}$.
%

%
In quantum mechanics, this condition in a homogeneous potential naturally leads to real spectra (see Supplemental Material (SM S1)), whereas the situation becomes complicated for photonic media. 





To discuss the consequences of this temporal $\mathcal{PT}$-symmetry in photonics, we extend the transfer matrix method to handle modulation in both $\Re{\epsilon(t)}$ and $\Im{\epsilon(t)}$ from binary-level modulation to multi-level and continuous modulation schemes.
%
Starting with binary-state modulation, we consider systems where the permittivity alternates between two discrete values periodically in time. This modulation can be characterized using transfer matrices that describe the continuity of electromagnetic fields at temporal boundaries, which leads to the dispersion relation~\cite{lustig2018topological}:
\begin{align}
    \Omega(k_z)T = \cos^{-1}\left[\text{Tr}(M)/2\right],
    \label{eq:TMM_2state}
\end{align}
where $\Omega$ is the quasienergy, $k_z$ is the wavevector along the wave's propagation direction.
%
We generalize this approach to $n$-state modulation schemes, where the permittivity cycles through $n$ discrete values within each period. The total transfer matrix $M$ over one period is constructed as the product of matrices corresponding to each temporal segment:
\begin{widetext}
    \begin{equation}
    \label{eq:multistate}
    \begin{split}
    M &= \frac12
    \begin{pmatrix}
      f_{1} & -f_{1}/p_{1} \\
      1/f_{1} & 1/(p_{1}f_{1})
    \end{pmatrix}
    \underbrace{\left[
    \prod_{k=1}^{n-1}
    \begin{pmatrix}
      1/f_{2k} & f_{2k} \\
      -1/f_{2k} & f_{2k}
    \end{pmatrix}
    \;\frac12\;
    \begin{pmatrix}
      f_{2k+1} & -f_{2k+1}/p_{k+1} \\
      1/f_{2k+1} & 1/(p_{k+1}f_{2k+1})
    \end{pmatrix}
    \right]}_{U}
    \begin{pmatrix}
      1/f_{2n} & f_{2n} \\
      -1/f_{2n} & f_{2n}
    \end{pmatrix}
    \end{split},
    \end{equation}
\end{widetext}
where \(f_k = \exp(\iu\omega_k\tau_k)\), \(\tau_k = \sum_{i=1}^{k}t_{\mathrm{i}}\), \(\omega_k\) is the angular frequency of the \(k\)-th time segment, \(p_k = \omega_k/\omega_{k+1}\) for \(k=1,\ldots,n-1\), and \(p_n = \omega_n/\omega_1\)(SM S2). 



We explicitly prove the realness of the trace of the transfer matrix $M$ under the temporal $\mathcal{PT}$-symmetry (see details in SM S3). In short, the $\pt$-symmetry imposes
\begin{align}
M^{\dagger} = \mathcal{P} M \mathcal{P}^{-1},\qquad 
\label{eq:PT}
\end{align}
where we find $\mathcal{P}=\sigma_z$. Eq.~\eqref{eq:PT} is known as the pseudo-Hermiticity condition under operator $\mathcal{P}$~\cite{10.1063/1.1418246,PhysRevLett.89.270401}. 
%
Eq.~\eqref{eq:PT} ensures $\operatorname{Tr} M = \operatorname{Tr} M^{\dagger} \in \mathbb{R}$ and constrains the eigenvalues of $M$ to either being a degenerate real pair or forming a complex-conjugate pair.








%

If the permittivity $\epsilon(t)$ varies continuously with time, we can further reformulate the discrete matrix product Eq.~\eqref{eq:multistate} into a continuous differential framework. By considering infinitesimal time intervals, we derive a first-order matrix differential equation (SM S2):
\begin{align}
\frac{\mathrm{d}U(t)}{\mathrm{d}t} = U(t) R(t).
\end{align}
Here $U(t)$ is a continuous formulation of the intermediate $2n-2$ matrices in Eq.~\eqref{eq:multistate}, and 
$R(t)=\begin{pmatrix}
0 & \iu\omega(t)\\
\iu\omega(t) & \omega'(t)/\omega(t)
\end{pmatrix}$ 
is the instantaneous generator matrix,
%
where $ \omega(t;k_z)=ck_z/\sqrt{\epsilon(t)}$.
In the following context, we denote the full-cycle \(U(T)\) implicitly as \(U\) for convenience, while \(U(t)\) refers to the general time-dependent evolution matrix.
The dispersion relation can be written as 
\begin{align}
    \Omega(k_z)T =  \cos^{-1}\left[\text{Tr}(U)/2\right],
\label{eq:eigen}
\end{align}
which remains consistent with Eq.~\eqref{eq:TMM_2state} because in the limit \(n \to \infty\), the rightmost and leftmost matrices in Eq.~\eqref{eq:multistate} act as a similarity transformation on the intermediate matrix, and the trace remains invariant under this transformation. The numerical consistency of this convergence is demonstrated in SM S4.


Therefore, to ensure that the Floquet band structure remains Hermitian, it is required that $\text{Tr}(U) = u_{11} + u_{22}$ is real and satisfies $|\text{Tr}(U)| \leq 2$, where $u_{11}$ and $u_{22}$ are the diagonal elements of $U$.
%
We note that this framework can even handle discontinuous modulation where a mathematical renormalization of the $u_{22}$ component can be introduced (see SM S2).


We can further define differential operators to encapsulate the behavior of the system:
\begin{align}
\hat{O} &= \left( \dfrac{\mathrm{d}}{\mathrm{d}t} \right)^2 + \dfrac{(c k_z)^2}{\epsilon(t)} + \dfrac{1}{2} \dfrac{\epsilon'(t)}{\epsilon(t)} \dfrac{\mathrm{d}}{\mathrm{d}t}, \\
\hat{P} &= \dfrac{1}{2} \dfrac{\epsilon'(t)}{\epsilon(t)} \dfrac{\mathrm{d}}{\mathrm{d}t}.
\end{align}
The $U(t)$ matrix should satisfy:
\begin{align}
(\hat{O} + \hat{P}) u_{11}(t) = 0, \\
(\hat{O} - \hat{P}) {u}_{22}(t) = 0.
\end{align}
This mathematical formulation will be helpful for our further analysis on the $\pt$ phase transition.
%
One may equivalently derive the differential operators from Maxwell's equations, where the $u_{11}$ and $u_{22}$ parameters correspond to the normalized magnetic and displacement fields, respectively (see SM S2). 
%
%
Crucially, the operator $\hat{O}$ satisfies:
\begin{align}
\hat{O} \cos\left( \int_{0}^{t} \omega(\tau; k_z) \, \mathrm{d}\tau \right) = 0,
\end{align}
regardless of the specific form of the modulation $\epsilon(t)$; see SM S5. 
%




An example satisfying the requirement of the temporal $\pt$-symmetry is the sinusoidal modulation of $\epsilon(t)$, where the real and imaginary components share the same frequency but are phase-shifted by $\mathrm{\pi}/2$.
%
Specifically, one can express 
\begin{align}
\epsilon(t) = \epsilon_{\mathrm{i}} + \epsilon_A \left[ \cos\left( \omega_\text{m} t \right) + \iu \gamma \sin\left(\omega_\text{m} t \right) \right],
\label{eq:single_freq}
\end{align}
where \( \omega_\text{m} = 2\mathrm{\pi}/T \) is the fundamental angular frequency, $\epsilon_{\mathrm{i}} > \epsilon_A$ to ensure that $\Re\epsilon(t)$ remains positive. The contrast between the modulation depth of $\Im\epsilon(t)$ to that of $\Re\epsilon(t)$ is defined as $\gamma$.
%
\begin{figure}[h!]
    \centering
    \includegraphics[width=1\linewidth]{pt.pdf} 
    \caption{\textbf{Temporal \(\mathcal{PT}\)-symmetric and \(\mathcal{PT}\)-broken behavior under sinusoidal modulation of \(\epsilon(t)\).}
    (a-b) Complex-plane trajectories of \(\epsilon(t)\) under sinusoidal modulation. In the convergent case (a), \(\Re{\epsilon(t)}\) and \(\Im{\epsilon(t)}\) oscillate at the same frequency with a phase difference of \(\mathrm{\pi}/2\), forming \(\mathcal{PT}\)-symmetric Hermitian (blue ellipse) and \(\mathcal{PT}\)-broken non-Hermitian (orange ellipse) regions. This behavior corresponds to convergent bounded oscillations of \(\text{Tr}(U)\). Divergence of \(\text{Tr}(U)\) appears if the modulation phase difference deviates from $\pm\mathrm{\pi}/2$ (b). 
    (c-d) \(\mathcal{PT}\)-symmetric and \(\mathcal{PT}\)-broken phase transitions with varying modulation depth contrast \(\gamma\): the real (c) and imaginary (d) parts of \(\Omega(k_z)T\) at the first extremum of \(\text{Tr}(U)/2-k_z\) are plotted with parameters \(\epsilon_{\mathrm{i}} = 1.8\) and \(\epsilon_A = 1\).
}
    \label{fig:5}
\end{figure}

As illustrated in Fig.~\ref{fig:5}(a), the trajectory of $\epsilon(t)$ in the complex plane can be plotted in polar coordinates over one complete evolution period. With an exact phase difference of $\pm\pi/2$ between $\Re\epsilon$ and $\Im\epsilon$, the trajectory exhibits mirror symmetry about the real axis $\Re\epsilon$, which satisfies temporal $\mathcal{PT}$-symmetry. In this case, $\Tr(U)$ remains purely real for all $k_z$, and the corresponding $\Omega(k_z)$ is convergent.
%
Conversely, if the phase difference between the real and imaginary parts deviates from $\pm\pi/2$ (Fig.~\ref{fig:5}(b)), the trajectory is no longer mirror-symmetric about $\Re\epsilon$, thus breaking temporal $\mathcal{PT}$-symmetry. As a result, $\Tr(U)$ acquires a nonzero imaginary part for generic $k_z$, and $\Omega(k_z)$ becomes divergent. 



The Hermiticity of the band $\Omega(k_z)$ requires both $\Tr(U)\in\mathbb{R}$ and $\abs{\Tr(U)}\leq2$. As we have proved previously that a $\mathcal{PT}$-symmetric system automatically satisfy the first criterion, the Hermiticity reduces to the condition $\abs{\Tr(U)}\le2$, which hinges critically on the modulation depth contrast $\gamma$ for the single-frequency modulation in Eq.~\eqref{eq:single_freq}.

%
As shown in Fig.~\ref{fig:5}(c) and (d), $\gamma$ is the key parameter affecting the $\pt$-symmetry transition, playing a similar role as the spatial gain-loss contrast for the spatial $\pt$-transition~\cite{Feng2017}.
%
For $\gamma < \gamma_0$ (yellow circular region in Fig.~\ref{fig:5}), the system exhibits non-Hermitian energy bands.
%
For $\gamma > \gamma_0$ (blue region in Fig.~\ref{fig:5}), the system becomes Hermitian.
%
$\gamma = \gamma_0$ corresponds to the exceptional point where the temporal $\pt$ phase transition occurs.
%

%

For the single frequency modulation in Eq.~\eqref{eq:single_freq}, the phase transition occurs at $\gamma_0 \approx 1$, which will be explained by our Magnus expansion analysis (see SM S6).
%
Interestingly, in contrast to the spatial case where the $\pt$-symmetric phase appears for a weak loss-gain contrast, in the temporal case, the $\pt$-symmetric phase requires stronger $\Im\epsilon$ modulation than $\Re\epsilon$ modulation.



We provide more analytical insights to explain the $\pt$ phase transition in Fig.~\ref{fig:5}(c,d) using the Magnus expansion~\cite{https://doi.org/10.1002/cpa.3160070404}.
%
We adopt a perturbative analysis by treating \(\hat{P}=\frac{1}{2}\epsilon'(t)/\epsilon(t)\,\partial_t\) as a perturbation to $\hat{O}$. We therefore write
\(u_{11}=u_{11}^{(0)}+u_{11}^{(1)}+u_{11}^{(2)}+\dots\), \(u_{22}=u_{22}^{(0)}+u_{22}^{(1)}+u_{22}^{(2)}+\dots\),
and introduce the summation and difference combinations
\(S(t)=u_{11}(t)+u_{22}(t)\), \(D(t)=u_{11}(t)-u_{22}(t)\).
Adding and subtracting the evolution equations \((\hat{O}\pm\hat{P})u_{11,22}=0\) gives the coupled non-Hermitian system
\(\hat{O}S(t)=-\hat{P}D(t)\) and \(\hat{O}D(t)=-\hat{P}S(t)\).

At zeroth order, the unperturbed solution of \(\hat{O}S_{0}=0\) is \(S_{0}(t)=u_{11}^{(0)}+u_{22}^{(0)}=2\cos\theta(t)\), with accumulated phase \(\theta(t)=\int_{0}^{t}\omega(\tau)\,\mathrm{d}\tau\).  Hence, the extremum value $\lvert\text{Tr}(U)\rvert = 2$, regardless of $\gamma$, shows that the zeroth-order approximation fails to capture any phase transition.
%
At first order, from \(\hat{O}D_{1}=-\hat{P}S_{0}\) we obtain  
\(D_{1}(t)=\int_{0}^{t} \sin\bigl[\theta(t)-\theta(t_{1})\bigr] L(t_{1})\sin\theta(t_{1})\,\mathrm{d}t_{1}\), \(L(t)=\epsilon'(t)/\epsilon(t)\), whereas \(S_{1}(t)=0\).
%
At second order, with \(\hat{O}S_{2}=-\hat{P}D_{1}\) the symmetric component becomes  
\begin{align}
S_{2}(t)  
&=-\frac{1}{2}\int_{0}^{t}\!\mathrm{d}t_{1}\,L(t_{1})  
\sin\bigl[\theta(t)-\theta(t_{1})\bigr]  
\nonumber\\  
&\phantom{={}}\times  
\int_{0}^{t_{1}}\!\mathrm{d}t_{2}\,L(t_{2})  
\sin\theta(t_{2})  
\cos\bigl[\theta(t_{1})-\theta(t_{2})\bigr],  
\label{eq:S2}  
\end{align}
so that \(u_{11}+u_{22}=2\cos\theta+S_{2}+\mathcal{O}(\hat{P}^{3})\). Although the zeroth-order approximation yields the universal trivial extrema $\lvert\text{Tr}(U)\rvert = 2$, the addition of $S_{2}$ lifts this degeneracy, makes the system sensitive to $\gamma$, and thus captures the onset of phase transitions.

For the specific permittivity modulation given in Eq.\,\eqref{eq:single_freq} with $\epsilon_A=1$ without loss of generality and $\epsilon_{\mathrm{i}}>1$, the phase accumulation over one period can be compactly written as the contour integral.
$
 \theta(T) = c\,k_{z}/(\iu\,\omega_\text{m}) \oint_{|z|=1} \mathrm{d}z / [ z^{3/2} \sqrt{ \epsilon_{\mathrm{i}}\,z + (1/2)(1-\gamma) + (1/2)(1+\gamma)z^{2} } ] 
$.  
$\theta(T)$ reduces to \(2\mathrm{\pi}\,c\,k_{z}/(\omega_\text{m}\sqrt{\epsilon_{\mathrm{i}}})\) when \(\gamma=1\). The function \(L(t)\) takes the explicit form:  
$
L(t) = \omega_\text{m} \bigl[ -\sin(\omega_\text{m} t) + \iu\gamma \cos(\omega_\text{m} t) \bigr] 
/ \bigl[ \epsilon_{\mathrm{i}} + \cos(\omega_\text{m} t) + \iu\gamma \sin(\omega_\text{m} t) \bigr].
$
Substituting \(L(t)\) into the second-order expression Eq.~\eqref{eq:S2} yields the trace expansion:  
\begin{widetext}  
\begin{align}  
\Tr(U)  
=2\cos\theta(T) &- \frac{1}{2}\int_{0}^{T}\!\mathrm{d}t_{1}  
\frac{\omega_\text{m}\bigl[-\sin(\omega_\text{m}t_{1})+\iu\gamma\cos(\omega_\text{m}t_{1})\bigr]}{\epsilon_{\mathrm{i}}+\cos(\omega_\text{m}t_{1})+\iu\gamma\sin(\omega_\text{m}t_{1})}  
\sin\bigl[\theta(T)-\theta(t_{1})\bigr] \notag \\  
&\quad \times \int_{0}^{t_{1}}\!\mathrm{d}t_{2}  
\frac{\omega_\text{m}\bigl[-\sin(\omega_\text{m}t_{2})+\iu\gamma\cos(\omega_\text{m}t_{2})\bigr]}{\epsilon_{\mathrm{i}}+\cos(\omega_\text{m}t_{2})+\iu\gamma\sin(\omega_\text{m}t_{2})}  
\sin\theta(t_{2})  
\cos\bigl[\theta(t_{1})-\theta(t_{2})\bigr]  
+\mathcal{O}(L^{3}),  
\end{align}  
\end{widetext}  
with \(\theta(t)=\int_{0}^{t} \left[ ck_{z}\,\mathrm{d}\tau \big/ \sqrt{ \epsilon_{\mathrm{i}}+\cos(\omega_\text{m}\tau)+\iu\gamma\sin(\omega_\text{m}\tau) } \right]
\).
As shown in Fig.~\ref{fig:mg}(a), even at zeroth order, the Magnus expansion already captures the fundamental oscillation frequency observed in direct numerical integration of the ODE; for sufficiently large \(k_z\), the zeroth-order result agrees very well with the full solution for selected values of \(\gamma\). In the special case \(\gamma = 1\), this agreement persists across the entire \(k_z\) domain, reflecting the fact that \(S_2(T)=0\) under this condition (see SM S6), so the zeroth- and second-order expansions are identical. 
When carried out to the second order, the Magnus approximation exhibits excellent agreement with the direct ODE solutions over the full range of \(k_z\) for all choices of~$\gamma$.
%
Their corresponding band structures indeed exhibit the predicted non-Hermitian to Hermitian $\pt$ phase transition as $\gamma$ increases (Fig.~\ref{fig:mg}(b-d)).


