\section{Model and Equivalent Problem} \label{model}
\setcounter{equation}{0}
%
Let $(\Omega,\mathbb{F},\cal{F},\mathbb{P})$ be a filtered probability space, where $\mathbb{P}$ is the probability measure and the filtration  $\mathbb{F}=\{{\cal{F}}_t,t\in[0,T]\}$ satisfies the usual conditions.
The market consists of one riskless asset $S_0$
and one risky asset $S$, satisfying, for $0\leq t\leq T$,  
\begin{eqnarray*}
dS_0(t)&=&r S_0(t)dt,\nonumber \\
dS(t)&=&\mu S(t) dt+\sigma S(t) dW(t), 
\end{eqnarray*}
where $\{W(t),t\in[0,T]\}$ is a standard Brownian motion, adapted to the filtration $\mathbb{F}$, $r$ and $\sigma$ are positive constants, and $\mu$ is a  ${\cal F}_0$ measurable random variable. We assume $\mu$ and $W$ are unobservable and independent of each other.  
Let $\mathbb{F}^S=\{{\cal{F}}_t^S,t\in[0,T]\}$ be the natural filtration generated by the risky asset $S$, augmented with all $\mathbb{P}$-null sets in ${\cal{F}}$. The filtration $\mathbb{F}^S$ is observable and $\mathbb{F}^S\subset \mathbb{F}$. We further assume that random variable $\mu$ takes two values $\mu^h$ and $\mu^l$ with probability $p$ and $1-p$. To avoid triviality, we assume $\mu^l<\mu^h$ and $p\in (0,1)$. There is only one risky asset in the market for simplicity, which can be easily generalized to multiple risky assets with correlated Brownian motions.

Let $\pi(t)$ be  the proportion of wealth invested in the risky asset at time $t$, then the wealth process $X$ satisfies the following stochastic differential equation (SDE): 
\begin{equation}\label{dx}
	dX(t)=X(t)(r+\pi(t)(\mu-r))dt+X(t)\pi(t)\sigma dW(t),\  X(0)=x_0, \quad 0\leq t\leq T,
\end{equation}
where  $\pi$ is ${\cal{F}}^S$-progressively measurable and satisfies  $\mathbb{E}\left[\int_0^T|\pi(t)|^2dt\right]<\infty$, called an {\it admissible control}. The set of all admissible controls  is denoted by ${\cal{A}}$.
%Let $K$ be a closed convex cone, which concludes many kinds of common constraints, more details can be found in \cite{sass}.
We consider a general S-shaped utility function  given by 
$$
	U(x)=\left\{
	\begin{array}{lll}
		-\infty,\ x<0,\\
		-U_2(\theta-x),\ 0\leq x<\theta, \\
	    U_1(x-\theta),\ x\geq \theta,				
	\end{array}
	\right.
$$
where $U_1, U_2$ are  strictly increasing, strictly concave, continuously differentiable  with $U_1(0)=U_2(0)=0$, and $\theta$ is a positive constant.
Additionally, $\lim_{x\rightarrow +\infty}U_1(x)=+\infty$, $\lim_{x\rightarrow +\infty}U'_1(x)=0$, $\lim_{x\rightarrow +\infty}\frac{xU'_1(x)}{U_1(x)}<1$ and  $\lim_{x\rightarrow 0^+}U'_i(x)=+\infty$, for $i=1,2$.
In what follows, $I_i$ denotes the inverse function of $U'_i$ for $i=1,2$.
$U$ is convex for $0\leq x\leq \theta$ and concave for $x\geq \theta$, indicating the behavioral change from risk seeking to risk averse at a reference point $\theta$.  
%\begin{remark}\label{ucon}
%	As shown in (Kong et al.(2022)), the utility function covers several typical setting in literatures, including piecewise linear utility, scaled-TK and modified-TK etc. 
%\end{remark}
Our problem is to maximize the expected utility of  terminal wealth with a quantile constraint: 
\begin{equation}\label{utility}
	\left\{
	\begin{array}{l}
	\sup_{\pi\in {\cal{A}}}\mathbb{E}[U(X^{\pi}(T)))],\\
	{\text{s.t.}}\ X^{\pi}(t)\ {\text{satisfies}}\ (\ref{dx}),\\
	\mathbb{P}(X^{\pi}(T)\geq L)\geq 1-\varepsilon,
	\end{array}
	\right.
	\end{equation}
where $0\leq \varepsilon\leq 1$ is a constant given in advance.
In this paper, we assume $L<\theta$. The case $L\geq \theta$ can be similarly discussed. 


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{ Filtering and equivalent formulation} \label{sec_filter}
We now transform the primal problem (\ref{utility}) into an equivalent completely observable  problem. 
Denote the filter estimate of $\mu$ by 
$$\hat{\mu}(t)=\mathbb{E}[\mu|{\cal{F}}_t^S]$$
 and the innovation process $\hat W$ by
\[
\hat{W}(t)\defeq \sigma^{-1}\int_0^t(\mu-\hat{\mu}(s))ds+W(t),\quad  t\in[0,T].
\]
Then $\hat W$ is a $(\mathbb{P},{\mathbb{F}}^S)$-Brownian motion (see \cite{sas07}).
We can rewrite equivalently the asset price process $S$ as
\begin{equation}\label{sn}
dS(t)=\hat{\mu}(t)S(t)dt+\sigma S(t) d\hat{W}(t),
\end{equation}
and the wealth process $X$ as 
\begin{equation}\label{xn}
dX(t)=X(t)(r+\pi(t)(\hat{\mu}(t)-r))dt+X(t)\pi(t)\sigma d\hat{W}(t).
\end{equation}
The filtered drift process $\hat{\mu}$ satisfies the SDE:
\begin{equation}\label{mu}
	d\hat{\mu}(t)=\psi(\hat\mu(t))d\hat{W}(t),
	\end{equation}
where $\psi(u)=\sigma^{-1}(u-\mu^l)(\mu^h-u)$, and $\hat\mu(0)=\mathbb{E}[\mu] =p\mu^h+(1-p)\mu^l\in (\mu^l,\mu^h)$. 

We now have a fully observed control problem with state processes $X,\hat{\mu}$ and the problem (\ref{utility}) is equivalent to the following problem:
\begin{equation}\label{uo}
\left\{
\begin{array}{l}
\sup_{\pi\in {\cal{A}}}\mathbb{E}[U(X^{\pi}(T))],\\
{\text{s.t.}}\ X^{\pi}(t)\ {\text{satisfies}}\ (\ref{xn}),\\
{\hat \mu}(t) \ {\text{satisfies}}\ (\ref{mu}),\\
\mathbb{P}(X^{\pi}(T)\geq L)\geq 1-\varepsilon,
\end{array}
\right.
\end{equation}
We can solve problem (\ref{uo}) in two steps: First,  solve an unconstrained problem:
\begin{equation}\label{util}
\left\{
\begin{array}{l}
\sup_{\pi\in {\cal{A}}}\mathbb{E}[U_{\lambda}(X^{\pi}(T))],\\
{\text{s.t.}}\ X^{\pi}(t)\ {\text{satisfies}}\ (\ref{xn}),\\
{\hat \mu}(t) \ {\text{satisfies}}\ (\ref{mu}).\\
\end{array}
\right.
\end{equation}
where 
$$U_{\lambda}(x)\defeq U(x)+\lambda {\mathbb{I}}_{\{x\geq L\}}$$
and $\lambda\geq 0$ is a Lagrange multiplier to be determined. Second, 
find $\lambda^*$ such that the quantile constraint and the complementary slackness condition are satisfied:
\begin{equation}\label{lamd}
\left\{
\begin{array}{l}
\mathbb{P}(X^{\pi^*(\lambda),\lambda}(T)\geq L)\geq 1-\varepsilon,\\
\lambda(\mathbb{P}(X^{\pi^*(\lambda),\lambda}(T)\geq L)- 1+\varepsilon)=0.\\
\end{array}
\right.
\end{equation}
The relation of problems (\ref{uo}) and  (\ref{util})  is discussed in 
	\cite[Lemma 2.3]{dong20} that shows  if there exists a nonnegative constant $\lambda^*$ such that $X^{\pi^*,\lambda^*}(T)$ solves problem (\ref{util}) and satisfies condition (\ref{lamd}), then it also solves problem (\ref{uo}).

