\subsection{Concavified utility and dual problem}
The utility function $U_\lambda$ in (\ref{util}) is discontinuous at $x=L$ as well as nonconcave. We can use the concavification technique (see \cite{car00}) to solve the unconstrained problem (\ref{util}) as both state processes $X$ and $\hat \mu$ are driven by the same Brownian motion $\hat W$ and we have a complete market model. 
The concave envelope of $U$ is given by  
\begin{equation}\label{uc}
U^c(x)=\left\{
\begin{array}{ll}
-\infty, &x<0,\\
c_z x-U_2(\theta), & 0\leq x<z,\\
U_1(x-\theta), &x\geq z,
\end{array}
\right.
\end{equation}
where 
$$c_x=U'_1(x-\theta),\ x>\theta$$
 and $z>\theta$ is the unique solution to the equation
\begin{equation}\label{z}
U_1(x-\theta)+U_2(\theta)-xU'_1(x-\theta)=0.
\end{equation}
%\begin{figure}[htbp]
%	\centering
%	 \includegraphics[width=0.4\textwidth]{uc.png}
%\end{figure}
For a fixed $\lambda\geq 0$, denote by $U_{\lambda}^c$ the concave envelope of $U_{\lambda}$ and $V^c_{\lambda}$ the dual function of $U_{\lambda}^c$, defined by
$$V^c_{\lambda}(y)=\sup_{x\geq 0}\{U^c_{\lambda}(x)-xy\},\quad y>0,$$
and $x^{*,\lambda}(y)$ the maximizer of $V^c_{\lambda}(y)$. 
We can characterize $U_{\lambda}^c$ and $x^{*,\lambda}(y)$ as follows:
\begin{proposition}\label{dong}
	(\cite{dong20}) 
	Let 
\begin{equation}\label{kl}
k_{\lambda}\defeq \frac{U_2(\theta)  - U_2(\theta - L) + \lambda}{L},
\end{equation} 	
and 	 $\tilde{z}\in (\theta,z)$ is the unique solution to the equation
	\begin{equation}\label{zt}
	U_1(x-\theta)+U_2(\theta-L)-(x-L)U'_1(x-\theta)=0.
	\end{equation}
	(1) If $k_{\lambda}>c_{\tilde{z}}$, then
	\begin{equation}\label{r3-1-1}
	U_{\lambda}^c(x)=\left\{
	\begin{array}{ll}
	-\infty,& x<0,\\
	k_{\lambda}x-U_2(\theta),&0\leq x<L,\\
	c_{\tilde{z}}(x-L)-U_2(\theta - L)+\lambda,& L\leq x<\tilde{z},\\
	U_1(x-\theta)+\lambda,&x\geq \tilde{z},
	\end{array}\right.
	\end{equation}
	and 
	\begin{equation}\label{r3-1-2}
	x^{*,\lambda}(y)=\left\{
	\begin{array}{ll}
	\theta+I_1(y),&y<c_{\tilde{z}},\\
	L,&c_{\tilde{z}}\leq y<k_{\lambda},\\
	0,&y\geq k_{\lambda}.
	\end{array}
	\right.
	\end{equation}
	\\
	(2) If $k_{\lambda}\leq c_{\tilde{z}}$, then 
		\begin{equation}\label{r2-1-1}
		U_{\lambda}^c(x)=\left\{
		\begin{array}{ll}
		-\infty,& x<0,\\
		c_{z_0}x-U_2(\theta),&0\leq x<\tilde{z}_0,\\
		U_1(x-\theta)+\lambda,&x\geq \tilde{z}_0,
		\end{array}\right.
		\end{equation}
		and
		\begin{equation}\label{r2-2-l}
		x^{*,\lambda}(y)=\left\{
		\begin{array}{ll}
		\theta+I_1(y),&y<c_{\tilde{z}_0},\\
		0,&y\geq c_{\tilde{z}_0},
		\end{array}
		\right.
		\end{equation}
    where $\tilde{z}_0\in [\tilde{z},z]$ is the unique solution to the equation
    \begin{equation}\label{z0}
    U_1(x-\theta)+U_2(\theta)+\lambda-xU'_1(x-\theta)=0.
    \end{equation} 
     If $\lambda=0$, then $\tilde{z}_0=z$, $\tilde{U}_{\lambda}^c(x)$ and $x^{\lambda,0}(y)$ are given by (\ref{uc}) and (\ref{r2-2-l}) respectively.           
	\end{proposition}
