\section{Main Results} \label{sec_main}
\setcounter{equation}{0}
To express  $\mathbb{E}[V_{\lambda}^c(Y(T))]$ explicitly in terms of integral representation, we need to know
the joint distribution of $Y$ and ${\hat \mu}$, which is unknown. To address this,   we employ a measure change technique (\cite{xing25}). We introduce a new process $W^Q$ by 
\[
dW^Q(t)\defeq \frac{\hat{\mu}(t) - \mu^l}{\sigma}dt+d\hat{W}(t),
\] 
and a new probability measure by 
\[
\left.\frac{dQ}{dP}\right|_{{\cal{F}}_T^S}\defeq \exp \left(-\frac{1}{2}\int_0^T\left(\frac{\hat{\mu}(u) - \mu^l}{\sigma}\right)^2du-\int_0^T\frac{\hat{\mu}(u) - \mu^l}{\sigma}d\hat{W}(u)\right).
\]
By Girsanov's theorem, $W^Q$ is a standard Brownian motion under the new probability measure $Q$.
Under this new measure $Q$, the wealth process $X$ satisfies
\[
dX(t)=X(t)(r+\theta_l \sigma\pi(t))dt+X(t)\sigma \pi(t)dW^Q(t),
\]
where $\theta_l = \frac{\mu^l - r}{\sigma}$,
and the corresponding dual process 
\[
d{\cal{Y}}(t)={\cal{Y}}(t)\left(-rdt-\theta_ldW^Q(t)\right).    
\]
Let 
$$\Phi(t)\defeq \frac{\hat{\mu}(t) - \mu^l}{\mu^h - \hat{\mu}(t)}, \quad t \in [0,T].$$
 Note that $\Phi(t)$ is well defined as $\hat{\mu}(t)\in (\mu^l, \mu^h)$ a.s. for all $t\in [0,T]$ due to $\hat\mu(0) \in (\mu^l, \mu^h)$  (see \cite[Lemma 3.1]{Decamps2005}).   Then $\Phi(t)$ satisfies the SDE:
\[
d\Phi(t)=\Theta \Phi(t)dW^Q(t)
\]
with $\Phi(0)=\phi\defeq \frac{ \hat{\mu}(0) - \mu^l}{\mu^h -  \hat{\mu}(0)}$, where $\Theta=\frac{\mu^h-\mu^l}{\sigma}$. In addition, let 
\begin{equation} \label{F(t)}
F(t)\defeq \frac{1+\Phi(t)}{1+\phi},
\end{equation}
 then $F(t)$ satisfies the SDE:
$$dF(t)=\sigma^{-1}(\hat{\mu}(t) - \mu^l) F(t)dW^Q(t)$$
with $F(0)=1$, and
\begin{eqnarray*}
	\left.F(t)=\frac{dP}{dQ}\right|_{{\cal{F}}_t^S}.
\end{eqnarray*}
Applying Ito's lemma, we deduce that
\[
d(F(t)Y(t))=-rF(t)Y(t)dt-F(t)Y(t)\theta_ldW^Q(t)
\]
with $F(0)Y(0)=y_0$, 
which yields that ${\cal{Y}}(t)=F(t)Y(t)$ under measure $Q$.
We also get that 
\begin{equation}\label{phi}
\Phi(t)=\phi \exp\left\{\Theta W^Q(t)-\frac{1}{2}\Theta^2t\right\},
\end{equation}
and
\begin{equation}\label{cy}
{\cal{Y}}(t)=y_0\exp\left\{-\theta_l W^Q(t)-\left(r+\frac{1}{2}\theta_l^2\right)t
\right\}.
\end{equation}
%\begin{equation*}
%{\cal{Y}}(t)=y(0)\exp
%\left\{-\frac{(\mu^l-r)\left(\ln \frac{\Phi_t}{\phi}+\frac{1}{2}\Theta^2t\right)}{\sigma\Theta}
%-\left(r+\frac{(\mu^l-r)^2}{2\sigma^2}\right)t
%\right\}.
%\end{equation*}
Using the above observations, the  dual value function in (\ref{dutils}) becomes
$$ \mathbb{E}[V_{\lambda}^c(Y(T))]
=\mathbb{E}^Q[F(T)V_{\lambda}^c({\cal{Y}}(T)/F(T))]
=\mathbb{E}^Q\left[\frac{1+\Phi(T)}{1+\phi}V_{\lambda}^c\left({\frac{1+\phi}{1+\Phi(T)}\cal{Y}}(T)\right)\right]. 
$$
Since $\Phi$ and $\cal{Y}$ can be expressed in terms of $Q$-Brownian motion $W^Q$, we can write out 
the integral representation of the dual value function (\ref{eq_dual_value})  and the constraint function (\ref{eq_dual_con}) explicitly, that is, 
\begin{align}\label{vlaue1}
v^c_{\lambda}(t,y,\hat{\mu})&=\int_{\mathbb{R}}\Psi\left(t, x, \hat{\mu}\right) V_\lambda^c\left(\frac{y \exp\left\{-\theta_lx-\left(r+\frac{1}{2}\theta_l^2\right)(T-t)\right\}}{\Psi(t, x, \hat{\mu})}\right)p(t, x)dx,\\
g_{\lambda}(t,y,\hat{\mu})&=\int_{\mathbb{R}}\Psi\left(t, x, \hat{\mu}\right) \ind_{x^{*,\lambda}\left(\frac{y \exp\left\{-\theta_lx-\left(r+\frac{1}{2}\theta_l^2\right)(T-t)\right\}}{\Psi(t, x, \hat{\mu})}\right)\geq L}p(t, x)dx, \label{eq_dual_con_exp}
\end{align}
where 
\begin{align*}
\Psi(t, x, \hat{\mu}) & \defeq \frac{1+\phi \exp\left\{\Theta x-\frac{1}{2}\Theta^2 (T-t)\right\}}{1+\phi}, \\
p(t, x) & \defeq \frac{1}{\sqrt{2\pi(T-t)}}\exp\left\{-\frac{x^2}{2(T-t)}\right\}.
\end{align*}
