%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Condition (\ref{lamd}) can be written as
\begin{equation}\label{lamdq}
\left\{
\begin{array}{l}
\mathbb{E}^Q[F(T)\mathbb{I}_{\{X^{\pi^*,\lambda}(T)\geq L\}}]\geq 1-\varepsilon,\\
\lambda(\mathbb{E}^Q[F(T)\mathbb{I}_{\{X^{\pi^*,\lambda}(T)\geq L\}}]- 1+\varepsilon)=0.
\end{array}
\right.
\end{equation}
For a given $\lambda\geq 0$, the optimal terminal wealth is given by 
\begin{equation}\label{ox}
X^{\pi^*,\lambda}(T)=x^{*,\lambda}(Y(T)),
\end{equation}
where $x^{*,\lambda}$ is given by (\ref{r3-1-2})  or (\ref{r2-2-l}),   depending on the value $\lambda$, 
$$Y(T)={{\cal Y}(T)\over F(T)}= y_0(1+\phi)H(T),$$
 and
\begin{equation} \label{H(T)}
H(T)\defeq \frac{\exp\{-\theta_l W^Q(T)-(r+\frac{1}{2}\theta_l^2)T\}}{1+\phi \exp\left\{\Theta W^Q(T)-\frac{1}{2}\Theta^2T\right\} }.
\end{equation}
Additionally, $y_0$ is determined by the binding budget constraint $\mathbb{E}[X^{*,\lambda}(T) Y(T)]=x_0y_0$, that is,
\begin{equation}\label{bc}
\mathbb{E}^Q[F(T)X^{\pi^*,\lambda}(T)(1+\phi)H(T)]=x_0.
\end{equation}
Combining  (\ref{lamdq}) and (\ref{bc}), we can derive solutions $(y_0,\lambda^*)$.
We next state the main theorem on the existence and uniqueness of the Lagrange multiplier and the feasibility condition. 
\begin{theorem} \label{thm_feasible}
Let $x_0>0$ and $H^*_\varepsilon$ be the solution of the equation \begin{align}\label{eq_defH*}
\mathbb{E}^Q[F(T)\mathbb{I}_{\{H(T)\leq H^*_\varepsilon\}}]
=1-\varepsilon,
\end{align} where $F(T)$ and $H(T)$ are given in (\ref{F(t)}) and (\ref{H(T)}). Denote by 
\begin{equation} \label{x_epsilon}
\hat x_\varepsilon:=\mathbb{E}^Q[F(T)L\mathbb{I}_{\{H(T)<H^*_\varepsilon\}}(1+\phi)H(T)].
\end{equation}
   Then the following results hold.
\begin{enumerate}
\item If 	$x_0>\hat x_\varepsilon$, then there exists a unique $\lambda^*\geq 0$ such that $X^{\pi^*,\lambda^*}(T)$ in (\ref{ox})  is the optimal solution to problem (\ref{uo}).
\item If $x_0 = \hat x_\varepsilon$, then there is only one solution
$X^{\pi^*,\lambda^*}(T)=L\mathbb{I}_{H(T)<H^*_\varepsilon}$ a.s..
\item If $x_0< \hat x_\varepsilon$, then  
 problem (\ref{uo}) is infeasible, that is, condition  (\ref{lamd}) is not satisfied.
 \end{enumerate}
\end{theorem}

\begin{proof} We first discuss the case  $x_0>\hat x_\varepsilon$. 
		For a fixed $\lambda\geq 0$, the optimal terminal wealth $X^{\pi^*,\lambda}(T)$ is given by (\ref{ox}).
			If we can find a solution $(y_0,\lambda^*)$ to equations  (\ref{lamdq}) and (\ref{bc}), then $X^{\pi^*,\lambda^*}(T)$ is the optimal solution to problem (\ref{uo}). 

			 Case I: $H_{\varepsilon}^*\leq \frac{c_z}{y_0(1+\phi)}$. If we choose $\lambda=0$, then  	
			 $X^{\pi^*,\lambda}(T)$ is given by 
			 \begin{equation}\label{0x}
				X^{\pi^*, \lambda}(T)=(\theta+I_1(y_0(1+\phi)H(T)))\mathbb{I}_{\{H(T)\leq\frac{c_z}{y_0(1+\phi)}\}}.
			\end{equation}
			 We have 
\begin{eqnarray*}\mathbb{E}^Q[F(T)\mathbb{I}_{\{X^{\pi^*,\lambda}(T)\geq L\}}]
&=&\mathbb{E}^Q[F(T)\mathbb{I}_{\{H(T)\leq \frac{c_z}{y_0(1+\phi)}\}}]
\geq\mathbb{E}^Q[F(T)\mathbb{I}_{\{H(T)\leq H_{\varepsilon}^*\}}]
=1-\varepsilon.
\end{eqnarray*}
			The quantile constraint  (\ref{lamdq}) is  satisfied with  $\lambda^*=0$.
			We next show that there is a unique solution  $y_0$ to equation  (\ref{bc}).
			Denote by $f(y_0)\defeq \mathbb{E}^Q[F(T)X^{\pi^*,\lambda}(T)(1+\phi)H(T)]$. We can check that $f$ is  continuous, strictly decreasing,    and  $\lim_{y_0\rightarrow 0^+}f(y_0)=\infty, \lim_{y_0\rightarrow \infty}f(y_0)=0<x_0$, then  there exists a unique $y_0$ satisfying (\ref{bc}).

						 Case II: $\frac{c_{z}}{y_0(1+\phi)}<H_{\varepsilon}^*\leq \frac{c_{\tilde{z}}}{y_0(1+\phi)}$. 			In this case, if $\lambda^*=0$, then 
						 $$\mathbb{E}^Q[F(T)\mathbb{I}_{\{X^{\pi^*,\lambda}(T)\geq L\}}]=\mathbb{E}^Q[F(T)\mathbb{I}_{\{H(T)\leq \frac{c_z}{y_0(1+\phi)}\}}]
			<\mathbb{E}^Q[F(T)\mathbb{I}_{\{H(T)\leq H_{\varepsilon}^*\}}]=1-\varepsilon,$$
			which implies $\lambda^*=0$ is impossible as (\ref{lamdq}) is not satisfied. We must have  
			 $\lambda^*>0$ and the quantile constraint is binding, that is,  
			\begin{equation}\label{x-0-A}
			\mathbb{E}^Q[F(T)\mathbb{I}_{\{X^{\pi^*,\lambda}(T)\geq L\}}]=1-\varepsilon.
			\end{equation}
			Since
			$X^{\pi^*,\lambda}(T)=x^{*,\lambda}(Y(T))$ and $x^{*,\lambda}$ is given by (\ref{r3-1-2})  or (\ref{r2-2-l}), we next discuss its form.
			If $k_{\lambda}>c_{\tilde{z}}$, then
			\begin{equation}\label{x-4}X^{\pi^*,\lambda}(T)=(\theta+I_1(y_0(1+\phi)H(T)))\mathbb{I}_{\{H(T)<\frac{c_{\tilde{z}}}{y_0(1+\phi)}\}}+L\mathbb{I}_{\{\frac{c_{\tilde{z}}}{y_0(1+\phi)}\leq H(T)<\frac{k_{\lambda}}{y_0(1+\phi)}\}},
			\end{equation} and
		$$
			\mathbb{E}^Q[F(T)\mathbb{I}_{\{X^{\pi^*,\lambda}(T)\geq L\}}]=\mathbb{E}^Q[F(T)\mathbb{I}_{\{H(T)<\frac{k_{\lambda}}{y_0(1+\phi)}\}}]			>\mathbb{E}^Q[F(T)\mathbb{I}_{\{H(T)<H_\varepsilon^*\}}]
			=1-\varepsilon
			$$
				 as $k_\lambda>c_{\tilde{z}}\geq y_0(1+\phi)H_\varepsilon^*$, which is a contradiction to  (\ref{x-0-A}).
				 We must have $k_{\lambda}\leq c_{\tilde{z}}$, then 
						\begin{equation}\label{x-3}
				X^{\pi^*,\lambda}(T)=(\theta+I_1(y_0(1+\phi)H(T)))\mathbb{I}_{\{H(T)<\frac{c_{\tilde{z}_0}}{y_0(1+\phi)}\}}.
			\end{equation}
			To ensure (\ref{x-0-A}) holds, we have $c_{\tilde{z}_0}=y_0(1+\phi)H_{\varepsilon}^*$ and from (\ref{z0}) we define	 
			\begin{equation}\label{l-1-A}
			\lambda_1^*(y_0)\defeq  \tilde{z}_0U'_1(\tilde{z}_0-\theta)-U_1(\tilde{z}_0-\theta)-U_2(\theta).
			\end{equation}
To show $\lambda_1^*(y_0)>0$, define  $g(x):=xU'_1(x-\theta)-U_1(x-\theta)-U_2(\theta)$. Since $g$ is strictly decreasing and  $\tilde z_0<z$, we have  $\lambda_1^*(y_0)=g(\tilde{z}_0)>g(z)=0$. 
			The proof of existence and uniqueness of $y_0$ is similar to that in case I. 

		 Case III: $H_{\varepsilon}^*>\frac{c_{\tilde{z}}}{y_0(1+\phi)}$.
			In this case, similar to Case II, we have $\lambda^*>0$ and $X^{\pi^*,\lambda}(T)$ is given by (\ref{x-4}) or (\ref{x-3}). 
			If $X^{\pi^*,\lambda}(T)$ were given by (\ref{x-3}), we would have 
			$$\mathbb{E}^Q[F(T)\mathbb{I}_{\{X^{\pi^*,\lambda}(T)\geq L\}}]=\mathbb{E}^Q[F(T)\mathbb{I}_{\{H(T)<\frac{c_{\tilde{z}_0}}{y_0(1+\phi)}\}}]<\mathbb{E}^Q[F(T)\mathbb{I}_{\{H(T)<H_\varepsilon^*}]=1-\varepsilon$$ as $c_{\tilde{z}_0}\leq c_{\tilde{z}}<H_\varepsilon^*y_0(1+\phi)$, which is a contradiction to (\ref{x-0-A}).
			We must have $k_{\lambda}>c_{\tilde{z}}$ and $X^{\pi^*,\lambda}(T)$ is given by (\ref{x-4}).
						To ensure (\ref{x-0-A}) holds, we have $k_{\lambda}=y_0(1+\phi)H_{\varepsilon}^*$ and by the expression of $k_\lambda$ we define
			\begin{equation}\label{l-2-A}
			\lambda_2^*(y_0)=k_{\lambda}L+U_2(\theta-L)-U_2(\theta).
			\end{equation}
			Then 
			$$\lambda_2^*(y_0)>LU'_1(\tilde{z}-\theta)+U_2(\theta-L)-U_2(\theta)=\tilde{z}U'_1(\tilde{z}-\theta)-U_1(\tilde{z}-\theta)-U_2(\theta)=g(\tilde{z})>g(z)=0.$$
			The second equation holds as $U_1(\tilde{z}-\theta)+U_2(\theta-L)-(\tilde{z}-L)U'_1(\tilde{z}-\theta)=0$.

			To show the existance and uniqueness of $y_0$, define $f(y_0)\defeq \mathbb{E}^Q[F(T)X^{\pi^*,\lambda^*}(T)(1+\phi)H(T)]$. We can check that $f$  is continuous,  strictly decreasing, $\lim_{y_0\rightarrow 0^+}f(y_0)=\infty$ and $\lim_{y_0\rightarrow \infty}f(y_0)=\mathbb{E}^Q[F(T)L\mathbb{I}_{\{H(T)<H_{\varepsilon}^*\}}(1+\phi)H(T)]
			=\hat x_\varepsilon<x_0$, which shows there exists a unique $y_0$ to equation (\ref{bc}). 


	We next discuss the case  $x_0=\hat x_\varepsilon$.  Combining (\ref{bc}), we have  
			\begin{equation}\label{eqL}
			\mathbb{E}^Q[F(T)L\mathbb{I}_{\{H(T)<H_{\varepsilon}^*\}}H(T)]=\mathbb{E}^Q[F(T)X^{\pi^*,\lambda^*}(T)H(T)].
			\end{equation}
				If $H_{\varepsilon}^*\leq \frac{c_z}{y_0(1+\phi)}$, then $\lambda^*=0$ and $X^{\pi^*}(T)$ is given by (\ref{0x}).  					We have 
	$$
			\mathbb{E}^Q[F(T)X^{\pi^*,\lambda^*}(T)H(T)]\geq \mathbb{E}^Q[F(T)z\mathbb{I}_{H(T)<\frac{c_z}{y_0(1+\phi)}}H(T)]			>\mathbb{E}^Q[F(T)L\mathbb{I}_{\{H(T)<H_{\varepsilon}^*\}}H(T)],
			$$
			 which is a contradiction to (\ref{eqL}). 
			Similarly, 	if $\frac{c_{z}}{y_0(1+\phi)}<H_{\varepsilon}^*\leq \frac{c_{\tilde{z}}}{y_0(1+\phi)}$, then 
			$X^{\pi^*,\lambda}(T)$ is given by (\ref{x-3}) with $c_{\tilde{z}_0}=y_0(1+\phi)H_{\varepsilon}^*$, 
			 this gives that 
			$$\mathbb{E}^Q[F(T)X^{\pi^*,\lambda^*}(T)H(T)]\geq \mathbb{E}^Q[F(T)\tilde{z}_0\mathbb{I}_{\{H(T)<H_\varepsilon^*\}}H(T)]
			>\mathbb{E}^Q[F(T)L\mathbb{I}_{\{H(T)<H_{\varepsilon}^*\}}H(T)],
			$$
						 which is again a contradiction to  (\ref{eqL}). 
			If $H_{\varepsilon}^*>\frac{c_{\tilde{z}}}{y_0(1+\phi)}$, then $X^{\pi^*,\lambda}(T)$ is given by (\ref{x-4}) with $k_{\lambda}=y_0(1+\phi)H_{\varepsilon}^*$, 
						this gives  that 
			$$\mathbb{E}^Q[F(T)X^{\pi^*,\lambda^*}(T)H(T)]\geq \mathbb{E}^Q[F(T)L\mathbb{I}_{\{H(T)<H_{\varepsilon}^*\}}H(T)].$$ 
			To ensure (\ref{eqL}) holds, we must have  $y_0=\infty$, then $k_\lambda=\infty$,  $\lambda=\infty$, and   $X^{\pi^*,\lambda^*}(T)=L\mathbb{I}_{H(T)<H_{\varepsilon}^*}$.

		We finally discuss the case  $x_0<\hat x_\varepsilon$. Suppose solutions exist. 
			If $H_{\varepsilon}^*\leq \frac{c_z}{y_0(1+\phi)}$, then $\lambda^*=0$ and $X^{\pi^*}(T)$ is given by (\ref{0x}).  					We have 
	$$		 \mathbb{E}^Q[X^{\pi^*,\lambda}(T){\cal Y}(T)]\geq \mathbb{E}^Q[L\mathbb{I}_{\{H(T)<H_{\varepsilon}^*\}}y_0(1+\phi)H(T)F(T)]=\hat x_\varepsilon y_0>x_0y_0,
		$$
			which is a contradiction. Similarly, 
			if $\frac{c_{z}}{y_0(1+\phi)}<H_{\varepsilon}^*\leq \frac{c_{\tilde{z}}}{y_0(1+\phi)}$ or $H_{\varepsilon}^*>\frac{c_{\tilde{z}}}{y_0(1+\phi)}$, then 
			$X^{\pi^*,\lambda}(T)$ is given by (\ref{x-3}) with $c_{\tilde{z}_0}=y_0(1+\phi)H_{\varepsilon}^*$
			or (\ref{x-4}) with $k_{\lambda}=y_0(1+\phi)H_{\varepsilon}^*$, respectively, we would again have
			$\mathbb{E}^Q[X^{\pi^*,\lambda}(T){\cal Y}(T)]>x_0y_0$, which is a contradiction. We conclude that there is no feasible solution if $x_0<\hat x_\varepsilon$. 
				\end{proof}


				\begin{remark}
										If $\varepsilon=0$, which requires $X^\pi(T)\geq L$ a.s., then $H^*_\varepsilon=+\infty$, $\hat x_\varepsilon=(1+\phi)\mathbb{E}^Q[LF(T)H(T)]$ and 
										$$X^{\pi^*,\lambda^*}(T)=(\theta+I_1(Y(T)))\mathbb{I}_{\{Y(T)<c_{\tilde{z}}\}}+L\mathbb{I}_{\{Y(T)\geq c_{\tilde{z}}\}}.$$ 
					If $\varepsilon=1$, which removes the quantile constraint, then $H^*_\varepsilon=0$, $\hat x_\varepsilon=0$ and 
					$$X^{\pi^*,\lambda^*}(T)=(\theta+I_1(Y(T)))\mathbb{I}_{\{Y(T)\leq c_z\}}.$$ 
				\end{remark}




