% Subsection: Finite element approximations
\subsection{Finite element approximations}
Various finite element approximations have been proposed in the literature for approximating the Darcy--Forchheimer model~\cite{GW:2008,LMS:2009,PR:2012,Park:2005,SLM:2013}; see also~\cite{HCR:2018} and the references therein.  
Among these, we adopt the approach introduced in~\cite{PR:2012}, which employs Raviart--Thomas-type finite element discretizations~\cite{BBF:2013}.  

We define the function spaces  
\begin{align*}
X &= \left\{ \bv \in L^3(\Omega)^d : \div \bv \in L^2(\Omega) \right\}, \\
M &= L^2(\Omega).
\end{align*}
% Neumann case: where $L_0^2(\Omega)$ denotes the subspace of $L^2(\Omega)$ consisting of functions satisfying the zero-mean condition~\eqref{zero_mean}:
% \begin{equation*}
% L_0^2(\Omega) = \left\{ q \in L^2(\Omega) : \int_{\Omega} q \, dx = 0 \right\}.
% \end{equation*}
Observe that $X$ is the intersection of two Banach spaces, $H (\div; \Omega)$ and $L^3(\Omega)^d$:
\begin{equation*}
X = H (\div; \Omega) \cap L^3(\Omega)^d.
\end{equation*}
Equipped with the norm
\begin{equation*}
\| \bv \|_X = \left( \| \div \bv \|_{L^2(\Omega)}^2 + \| \bv \|_{L^2(\Omega)}^2 + \| \bv \|_{L^3(\Omega)}^2 \right)^{1/2},
\end{equation*}
the space $X$ becomes a uniformly smooth and uniformly convex Banach space (cf.~\cite{Megginson:1998}).  
% We also note that $X$ inherently incorporates the homogeneous Neumann boundary condition~\eqref{Forchheimer_BC}.


The weak formulation of~\eqref{Forchheimer} defined on $(X, M)$ is as follows: find $ ( \bu, p) \in X \times M $ such that  
\begin{equation}
\label{weak}
\begin{split}
\frac{\mu}{\rho} \int_{\Omega} \bK^{-1} \bu \cdot \bv \,dx + \frac{\beta}{\rho} \int_{\Omega} | \bu | \bu \cdot \bv \,dx - \int_{\Omega} p \div \bv \,dx = \int_{\Omega} \bf \cdot \bv \,dx
&\quad \forall \bv \in X, \\
\int_{\Omega} q \div \bu \,dx = \int_{\Omega} gq \,dx 
&\quad \forall q \in M.
\end{split}
\end{equation}

% % Figure: Lowest-order Raviart--Thomas
% \begin{figure}
%     \centering
%     \includegraphics[width=\textwidth]{RT.png}
%     \caption{Reference elements for the lowest-order Raviart--Thomas finite element in two and three dimensions.
%     Arrows indicate the degrees of freedom associated with the normal components on the element edges/faces.}
%     \label{Fig:RT}
% \end{figure}

Let $\cT_h$ be a quasi-uniform partition of $\Omega$ into finite elements, where $h$ denotes the characteristic mesh size.
Let $X_h \times M_h \subset X \times M$ be a Raviart--Thomas-type conforming mixed finite element space~\cite{BBF:2013} defined on $\cT_h$.
For example, in two dimensions ($d = 2$), if each element $T \in \cT_h$ is a rectangle, the local spaces $X_h$ and $M_h$ on $T$ are defined as
\begin{equation*}
X_h (T) := Q_{k+1, k} (T) \oplus Q_{k, k+1} (T),
\quad
M_h (T) := Q_{k, k} (T),
\end{equation*}
for $k \geq 0$, where $Q_{k,\ell}(T)$ denotes the set of polynomials on $T$ of degree at most $k$ and $\ell$ in each coordinate direction, respectively.
% Then the corresponding global spaces $X_h$ and $M_h$ are given by
% \begin{align*}
% X_h &= \left\{ \bv \in X : \bv|_T \in X_h (T) \text{ for all } T \in \mathcal{T}_h \right\}, \\
% M_h &= \left\{ q \in M : q|_T \in M_h (T) \text{ for all } T \in \mathcal{T}_h \right\}.
% \end{align*}
Additional examples of Raviart--Thomas-type conforming mixed finite element spaces can be found in~\cite[Table~1]{PR:2012}.
% The reference elements for the lowest-order Raviart--Thomas finite element in two and three dimensions are illustrated in \cref{Fig:RT}. 

The finite element formulation of~\eqref{weak} using the discrete space $X_h \times M_h$ is given as follows: find $(\bu_h, p_h) \in X_h \times M_h$ such that
\begin{equation}
\label{mixed_FEM}
\begin{split}
\frac{\mu}{\rho} \int_{\Omega} \bK^{-1} \bu_h \cdot \bv \,dx 
+ \frac{\beta}{\rho} \int_{\Omega} | \bu_h | \bu_h \cdot \bv \,dx 
- \int_{\Omega} p_h \div \bv \,dx 
= \int_{\Omega} \bf \cdot \bv \,dx \quad &\forall \bv \in X_h, \\
\int_{\Omega} q \div \bu_h \,dx 
= \int_{\Omega} g q \,dx \quad &\forall q \in M_h.
\end{split}
\end{equation}
Existence and uniqueness results for~\eqref{mixed_FEM} can be found in~\cite[Theorem~3.5]{PR:2012}.  
% In what follows, we refer to $\bu_h$ as the \emph{primal solution} and $p_h$ as the \emph{dual solution}.

We define the functional $F \colon X \rightarrow \mathbb{R}$ by
\begin{equation}
\label{F}
F(\bv) = \frac{\mu}{2 \rho} \int_{\Omega} \bK^{-1} | \bv |^2 \,dx + \frac{\beta}{3\rho} \int_{\Omega} | \bv |^3 \,dx - \int_{\Omega} \bf \cdot \bv \,dx,
\quad \bv \in X.
\end{equation}
One readily observes that~\eqref{mixed_FEM} corresponds to the optimality condition of the following saddle-point problem:
\begin{equation}
\label{mixed_FEM_saddle}
\min_{\bv \in X_h} \max_{q \in M_h}
\left\{ F(\bv) - \int_{\Omega} q (\div \bv - g ) \,dx \right\}.
\end{equation}
By invoking Fenchel--Rockafellar duality~\cite{JPX:2025,Rockafellar:1970}, the saddle-point problem~\eqref{mixed_FEM_saddle} is equivalent to a constrained convex optimization problem.  
Namely,~\eqref{mixed_FEM} can be reformulated as a constrained minimization problem, as summarized in \cref{Prop:equiv_opt}.

% Proposition: Equivalence to convex
\begin{proposition}
\label{Prop:equiv_opt}
The function $\bu_h \in X_h$ is a primal solution of~\eqref{mixed_FEM} if and only if it solves the following convex optimization problem with a linear constraint:
\begin{equation}
\label{mixed_FEM_opt}
\min_{\bv \in X_h} F(\bv) \quad
\text{ subject to } \quad
\div \bv = g_h,
\end{equation}
where the functional $F$ is defined in~\eqref{F}, and $g_h$ is the $L^2 (\Omega)$-orthogonal projection of $g$ onto $M_h$.
\end{proposition}


% Section: Reduction to a nearly semicoercive convex optimization problem
\section{Reduction to a nearly semicoercive convex optimization problem}
\label{Sec:Reduction}
In this section, we show that the finite element discretization~\eqref{mixed_FEM} can be reduced to a nearly semicoercive convex optimization problem if we proceed similarly as in~\cite[Section~2.2]{LWXZ:2007}.
More precisely, we show that an iteration of the augmented Lagrangian method~\cite{Hestenes:1969,Powell:1969} for solving the constrained optimization problem~\eqref{mixed_FEM_opt} is equivalent to a nearly semicoercive convex optimization problem~\cite{LP:2024b}, where the convergence rate of the augmented Lagrangian method can be arbitrarily fast.

The augmented Lagrangian method~\cite{Hestenes:1969,Powell:1969} for solving~\eqref{mixed_FEM_opt} is summarized in \cref{Alg:aug}.

% Algorithm: Augmented Lagrangian method
\begin{algorithm}
\caption{Augmented Lagrangian method for solving~\eqref{mixed_FEM_opt}}
\begin{algorithmic}[]
\label{Alg:aug}
\STATE Given $\epsilon > 0$:
\STATE Choose $p_h^{(0)} \in M_h$.
\FOR{$n=0,1,2,\dots$}
    \STATE $\displaystyle
    \bu_h^{(n+1)} = \operatornamewithlimits{\arg\min}_{\bv \in X_h} \left\{ F (\bv) - \int_{\Omega} p_h^{(n)} \div \bv \,dx + \frac{1}{2\epsilon} \int_{\Omega} ( \div \bv - g_h )^2 \,dx \right\}
    $
    \STATE $\displaystyle
    p_h^{(n+1)} = p_h^{(n)} - \epsilon^{-1} ( \div \bu_h^{(n+1)} - g_h)
    $
\ENDFOR
\end{algorithmic}
\end{algorithm}

In the linear case, for instance when $\beta = 0$ in~\eqref{mixed_FEM}, it was shown in~\cite[Lemma~2.1]{LWXZ:2007} that the augmented Lagrangian method can achieve arbitrarily fast convergence by choosing $\epsilon$ sufficiently small; similar results are also found in~\cite{LP:2009,LP:2017}.  
In \cref{Thm:aug}, we show that this property remains valid for a nonlinear case.
We note that the augmented Lagrangian method in a general abstract setting is analyzed in \cref{App:Aug}.

% Theorem: Augmented Lagrangian method
\begin{theorem}
\label{Thm:aug}
Let $\{ ( \bu_h^{(n)}, p_h^{(n)} ) \}$ be the sequence generated by the augmented Lagrangian method presented in \cref{Alg:aug}.
Then, there exists a constant $\mu > 0$, independent of $\epsilon$, such that
\begin{equation*}
D_F^{\mathrm{sym}} (\bu_h^{(n+1)}, \bu_h) 
\leq \frac{\epsilon}{4} \| p_h^{(n)} - p_h \|^2
\leq \frac{\epsilon}{4} \left( \frac{\epsilon}{\mu + \epsilon} \right)^{2n} \| p_h^{(0)} - p_h \|^2,
\quad n \geq 0,
\end{equation*}
where the symmetrized Bregman divergence $D_F^{\mathrm{sym}}$ is defined in~\eqref{symmetrized_Bregman}.
\end{theorem}
\begin{proof}
Thanks to~\eqref{aug_general_reduction}, \cref{Rem:local_strong_convexity}, and \cref{Thm:aug_general}, it suffices to verify that $F^* \circ \div^*$ is locally strongly convex on $M_h$, where $F^* \colon X_h \rightarrow \overline{\mathbb{R}}$ is the Legendre--Fenchel conjugate of $F$ defined in~\eqref{Legendre_Fenchel}, and $\div^* \colon M_h \rightarrow X_h$ denotes the $L^2(\Omega)$-adjoint of $\div \colon X_h \rightarrow M_h$.
Since $F$ is locally smooth on $X_h$~(see \cref{Sec:Multilevel}.2), it follows from~\cite{GR:2008} that $F^*$ is locally strongly convex.
Moreover, because $\div^*$ is injective, the composition $F^* \circ \div^*$ inherits local strong convexity.
This completes the proof.
\end{proof}

\cref{Thm:aug} implies that the convergence rate of the augmented Lagrangian method for solving~\eqref{mixed_FEM_opt} can be made arbitrarily fast by choosing $\epsilon$ sufficiently small.  
In other words, the number of iterations required to achieve a prescribed level of accuracy becomes very small as $\epsilon$ decreases.
Relevant numerical results illustrating this behavior will be provided in \cref{Sec:Numerical}.

In this sense, the mixed formulation~\eqref{mixed_FEM} can be viewed as being reduced to a convex optimization problem of the form
\begin{equation}
\label{mixed_FEM_nearly}
\min_{\bv \in X_h} \left\{ F^{\epsilon} (\bv ; q_h) := \frac{1}{2} \int_{\Omega} ( \div \bv - g_h )^2 \,dx + \epsilon \left[ F (\bv) -  \int_{\Omega} q_h \div \bv \,dx \right] \right\}
\end{equation}
for some $q_h \in M_h$.
When there is no ambiguity, we simply write $F^{\epsilon} (\bv) = F^{\epsilon} (\bv; q_h)$.
In what follows, it suffices to focus on solving~\eqref{mixed_FEM_nearly}.
We denote the solution of~\eqref{mixed_FEM_nearly} by $\bu_h^{\epsilon} \in X_h$.

A major difficulty in solving~\eqref{mixed_FEM_nearly} numerically is that the problem is nearly semicoercive~\cite{LP:2024b}~(cf.\ nearly singular in the linear case~\cite{LWXZ:2007}) due to the nontrivial kernel of $\div$.  
As a result,~\eqref{mixed_FEM_nearly} becomes increasingly ill-conditioned as $\epsilon$ becomes small, causing conventional iterative solvers to converge very slowly.

In the following section, we present the construction of an efficient iterative solver for~\eqref{mixed_FEM_nearly} that remains robust with respect to both small $\epsilon$ and the mesh size $h$.

% Section: Multilevel method
\section{Multilevel methods}
\label{Sec:Multilevel}
In this section, we propose a multilevel method for solving the nearly semicoercive convex optimization problem~\eqref{mixed_FEM_nearly} that is robust with respect to both the augmented Lagrangian parameter~$\epsilon$ and the mesh size~$h$.
Building upon the abstract theory of subspace correction methods for solving nearly semicoercive convex optimization problems developed in~\cite{LP:2024b}, we construct a patch-based multilevel method with Schwarz smoothers, similarly as in~\cite{AFW:2000,LWC:2009}.
We also present a backtracking strategy for line search in the multilevel method~\cite{Park:2022a}, which makes the algorithm more practical in the sense that it is even faster and does not require a predetermined step size.

% Subsection: Multilevel subspace correction
\subsection{Multilevel subspace correction}
% Figure: Multilevel grids
\begin{figure}
    \centering
    \includegraphics[width=\textwidth]{multilevel_grids.png}
    \caption{Multilevel mesh hierarchy $\{ \mathcal{T}_k \}_{k=1}^J$ for a rectangular grid $\mathcal{T}_h$~($J = 4$).}
    \label{Fig:grids}
\end{figure}

We assume that the partition $\cT_h$ is part of a nested sequence of quasi-uniform partitions $\{ \cT_k \}_{k=1}^J$, where $\cT_h = \cT_J$ and each $\cT_k$, $1 \leq k \leq J$, has a characteristic element size $h_k$.
The quasi-uniformity constants are independent of $k$, and the mesh sizes satisfy $h_k \eqsim \gamma^k$ for some $\gamma \in (0,1)$.
See \cref{Fig:grids} for an example of a rectangular grid $\cT_h$ when $J = 4$.

For each $\cT_k$, we define the finite element space $V_k$, of the same type as $V$.
It follows that
\begin{equation*}
V_1 \subset V_2 \subset \dots \subset V_J = V.
\end{equation*}
Let $\cV_k$ be the set of all internal vertices of $\cT_k$, and let $n_k = | \cV_k |$.
For each $x_k^i \in \cV_k$, $1 \leq i \leq n_k$, we define
\begin{equation*}
\cT_k^i = \{ \tau \in \cT_k : x_k^i \in \partial \tau \}, \quad
\Omega_k^i = \left( \bigcup_{\tau \in \cT_k^i} \tau \right)^{\circ}.
\end{equation*}
We define the subspace $V_k^i$ as
\begin{equation*}
V_k^i = \{ v \in V_k : \operatorname{supp} v \subset \overline{\Omega}_k^i \}.
\end{equation*}
Then we have the following vertex-based multilevel space decomposition of $V$:
\begin{equation}
\label{space_decomposition}
V = \sum_{k=1}^J \sum_{i=1}^{n_k} V_k^i.
\end{equation}
Such vertex-based space decomposition for vector field problems was previously considered in, e.g.,~\cite{AFW:2000,LWC:2009}.

Now, we are ready to present our proposed multilevel method.
The proposed method is a parallel subspace correction method~\cite{LP:2024b,Park:2020,TX:2002} for solving~\eqref{mixed_FEM_nearly} based on the multilevel space decomposition~\eqref{space_decomposition}, as summarized in \cref{Alg:multilevel}.


% Algorithm: Multilevel method
\begin{algorithm}
\caption{Parallel multilevel method for solving~\eqref{mixed_FEM_nearly}}
\begin{algorithmic}[]
\label{Alg:multilevel}
\STATE Given $\tau > 0$:
\STATE Choose $\bu^{(0)} \in V$.
\FOR{$n=0,1,2,\dots$}
    \FOR{$k = 1, 2, \dots, J$}
        \FOR{$i = 1, 2, \dots, n_k$}
            \STATE $\displaystyle \bw_{k,i}^{(n+1)} = \operatornamewithlimits{\arg\min}_{\bw_{k,i} \in V_k^i} F^{\epsilon} ( \bu^{(n)} + \bw_{k,i} )
            $
        \ENDFOR
    \ENDFOR
    \STATE $\displaystyle
    \bu^{(n+1)} = \bu^{(n)} + \tau \sum_{k=1}^J \sum_{i=1}^{n_k} \bw_{k,i}^{(n+1)}
    $
\ENDFOR
\end{algorithmic}
\end{algorithm}

Note that each $\bw_{k,i}^{(n+1)}$-local problem in \cref{Alg:multilevel} is a convex optimization problem of small dimension, which can be solved robustly and efficiently using second-order optimization algorithms, such as the damped Newton method~\cite{BV:2004}.
Moreover, the for-loops with respect to $k$ and $i$ in \cref{Alg:multilevel} can be fully parallelized, making the algorithm well-suited for implementation on parallel computing architectures.
The step size~$\tau$ in \cref{Alg:multilevel} must satisfy a certain condition (to be specified later) to ensure convergence of the algorithm.
Nevertheless, as we will show later, the backtracking line search proposed in~\cite{Park:2022a} can be employed to efficiently determine a suitable step size~$\tau$ with only marginal additional computational cost at each iteration of \cref{Alg:multilevel}.

% Remark: Linear case
\begin{remark}
\label{Rem:BPX}
In the linear case, i.e., when $\beta = 0$ in~\eqref{mixed_FEM_nearly}, \cref{Alg:multilevel} can serve as a preconditioner.
In fact, it coincides with the Bramble--Pasciak--Xu preconditioner~\cite{BPX:1990} or the multilevel additive Schwarz preconditioner~\cite{Zhang:1992,Zhang:1994}.
Convergence analysis of multilevel methods for linear problems posed in $H(\div)$ spaces can be found in, e.g.,~\cite{AFW:2000,HT:2000}.
\end{remark}

