% Subsection: Convergence analysis
\subsection{Convergence analysis}
We present a convergence analysis of the proposed multilevel method in \cref{Alg:multilevel}, based on the abstract theory developed in~\cite{LP:2024b}. For completeness, a summary of the abstract framework is provided in \cref{App:Nearly}.

Throughout this section, we use the notations
$A \lesssim B$ and $B \gtrsim A$ to indicate that there exists a positive constant $C$, independent of the geometric parameters such as $h$ and $J$, such that $A \leq C B$.
We write $A \eqsim B$ when both $A \lesssim B$ and $A \gtrsim B$ hold.

First, we observe that the multilevel space decomposition~\eqref{space_decomposition} satisfies the strengthened convexity condition~\eqref{strengthened_convexity} with
\begin{equation}
\label{tau_0}
\tau_0 \gtrsim J^{-1} \eqsim | \log h |^{-1},
\end{equation}
as a consequence of a coloring argument~\cite[Section~5.1]{Park:2020} applied at each level.

Let $F_0$ and $F_1$ be the semicoercive and coercive parts of the energy functional $F$, respectively, namely,
\begin{equation}
\label{F0}
F_0 (\bv) = \frac{1}{2} \int_{\Omega} (\div \bv - g_h )^2 \,dx, \quad
F_1(\bv) = F(\bv) - \int_{\Omega} q_h \div \bv \,dx,
\quad \bv \in V,
\end{equation}
so that $F^{\epsilon} = F_0 + \epsilon F_1$.
We define the Bregman divergences associated with $ F_0 $ and $F_1$ by
\begin{equation}
\label{d1}
\begin{aligned}
d_0(\bw; \bv) &= F_0(\bv + \bw) - F_0(\bv) - \langle F_0'(\bv), \bw \rangle, \\
d_1(\bw; \bv) &= F_1(\bv + \bw) - F_1(\bv) - \langle F_1'(\bv), \bw \rangle,
\end{aligned}
\quad \bv, \bw \in V,
\end{equation}
where $\langle \cdot, \cdot \rangle$ denotes the duality pairing on $V$.
By a direct computation, we observe that
\begin{equation}
\label{d0}
d_0(\bw; \bv) = \frac{1}{2} \| \div \bw \|_{L^2(\Omega)}^2,
\quad \bv, \bw \in V.
\end{equation}
Moreover, we have the following lemma concerning $d_1$, whose proof is elementary; see, for instance,~\cite{Ciarlet:2002}.

% Lemma: Bounds for d_1
\begin{lemma}
\label{Lem:d1}
The Bregman divergence $d_1$ given in~\eqref{d1} satisfies the following:
\begin{enumerate}[(a)]
\item $d_1(\bw; \bv) \lesssim \| \bw \|_{L^2(\Omega)}^2 + ( \| \bv \|_{L^3 (\Omega)} + \| \bw \|_{L^3 (\Omega)} )\| \bw \|_{L^3(\Omega)}^2$.
\item $d_1(\bw; \bv) \gtrsim \| \bw \|_{L^2(\Omega)}^2 + \| \bw \|_{L^3(\Omega)}^3$.
\end{enumerate}
\end{lemma}

In the abstract convergence theory presented in \cref{App:Nearly}, several assumptions are required to ensure the convergence of subspace correction methods; see \cref{Thm:nearly} for the convergence result and \cref{Ass:smooth,Ass:uniform,Ass:kernel,Ass:triangle} for the corresponding assumptions. In the following, we verify that \cref{Alg:multilevel} satisfies all these assumptions.

The local smoothness condition (\cref{Ass:smooth}) follows directly from~\eqref{d0} and \cref{Lem:d1}(a).
The local uniform convexity condition (\cref{Ass:uniform}) with $p = 3$ is similarly implied by~\eqref{d0} and \cref{Lem:d1}(b).
Namely, for any bounded and convex subset $K \subset V$, we have
\begin{equation}
\label{mu}
\mu_{0, K} := \inf_{\bv,\, \bv + \bw \in K} \frac{d_0 ( \bw; \bv )}{\| \div \bw \|_{L^2 (\Omega)}^3} \gtrsim 1,
\quad
\mu_{1, K} := \inf_{\bv,\, \bv + \bw \in K} \frac{(d_0 + d_1) (\bw; \bv)}{\| \bw \|_X^3} \gtrsim 1.
\end{equation}

The kernel decomposition condition (\cref{Ass:kernel}) is satisfied by the patch-based multilevel decomposition~\eqref{space_decomposition}, as discussed in~\cite[Section~5.1]{LWXZ:2007}. Finally, the triangle inequality-like property (\cref{Ass:triangle}) is a direct consequence of~\cite[Lemma~5.4]{LY:2001}; see also~\cite[Example~C.3]{LP:2024b}.

Given an initial guess $\bu^{(0)} \in V$, we define
\begin{equation}
\label{K_0}
K_0 := \{ \bv \in V : F( \bv ) \leq F( \bu^{(0)} ) \}.
\end{equation}
Since all assumptions in \cref{Thm:nearly} have been verified, we obtain the following convergence result for \cref{Alg:aug} by invoking that theorem.

% Theorem: Convergence theorem
\begin{theorem}
\label{Thm:convergence}
In \cref{Alg:multilevel}, assume that $\tau \in (0, \tau_0]$, where $\tau_0$ was given in~\eqref{tau_0}.
Then there exists $\zeta^* > 0$ such that, if $F^{\epsilon} (\bu^{(0)}) - F^{\epsilon} (\bu_h^{\epsilon}) > \zeta^*$, then
\begin{equation*}
F^{\epsilon} (\bu^{(1)}) - F^{\epsilon} (\bu_h^{\epsilon}) \leq \left(1 - \frac{\tau}{2} \right) ( F^{\epsilon} (\bu^{(0)}) - F^{\epsilon} (\bu_h^{\epsilon}) ),
\end{equation*}
and otherwise,
\begin{equation*}
F^{\epsilon} (\bu^{(n)}) - F^{\epsilon} (\bu_h^{\epsilon})
\leq \frac{ C_1^{3} }{ \tau^{3} C_2^{2} n^{3} },
\quad n \geq 1,
\end{equation*}
where $C_1$ is a positive constant independent of $\epsilon$, except for its implicit dependence on $K_0$, and $C_2 = \min \{\mu_{0, K_0}, \mu_{1, K_0} \}$~(see~\eqref{mu}).
\end{theorem}

We note that the convergence theorem above explains how the convergence rate of \cref{Alg:multilevel} depends on the augmented Lagrangian parameter $\epsilon$, but not explicitly on the mesh size $h$.
In fact, the constant $C_1$ in \cref{Thm:convergence}, which is defined in terms of stable decompositions of the multilevel subspaces~\eqref{space_decomposition} (see~\cite[Theorem~5.8]{LP:2024b}), may implicitly depend on $h$.

While $h$-independence of multilevel space decompositions for linear problems in $H(\div; \Omega)$ has been established in the literature~\cite{AFW:2000,HT:2000} using the Helmholtz decomposition, extending these arguments to our setting is highly nontrivial.
The main difficulty stems from the fact that our problem is posed on the space $X = H(\div; \Omega) \cap L^3(\Omega)^d$, which requires controlling the $L^3 (\Omega)^d$-norm in addition to the $H(\div; \Omega)$-norm.

In \cref{Sec:Numerical}, we provide numerical evidence indicating that the convergence of \cref{Alg:multilevel} is robust with respect to $h$, similarly to the case of linear problems, across a range of problem settings.

% Remark: Linear convergence
\begin{remark}
\label{Rem:linear_convergence}
Combining \cref{Lem:d1}(b) with the inverse inequality $\| \bw \|_{L^3(\Omega)} \lesssim h^{-\frac{d}{6}} \| \bw \|_{L^2(\Omega)}$~\cite[Theorem~4.5.11]{BS:2008}, we can verify that the local uniform convexity condition~(\cref{Ass:uniform}) holds with $p = 2$, although the constant $\mu_{1,K}$ depends on the mesh size $h$.
Consequently, by invoking \cref{Thm:nearly}(a), we obtain the linear convergence of \cref{Alg:multilevel}.
However, the resulting convergence rate is suboptimal due to its dependence on $h$, which originates from the inverse inequality.
\end{remark}

% Remark: Park:2024a
\begin{remark}
\label{Rem:Park:2024a}
In~\cite{Park:2024a}, an alternative approach was proposed for analyzing the $\epsilon$-independence of the convergence rate of subspace correction methods for solving problems of the form~\eqref{mixed_FEM_nearly}.
However, to apply the strategy developed in~\cite{Park:2024a}, one must construct a stable decomposition for the multilevel spaces~\eqref{space_decomposition} that satisfies certain specific conditions~\cite[Assumption~3.1]{Park:2024a}, which is not straightforward.
\end{remark}

% Subsection: Backtracking line search
\subsection{Backtracking line search}
As stated in \cref{Thm:convergence}, the step size $\tau$ must be chosen smaller than $\tau_0$ given in~\eqref{tau_0} to guarantee the convergence of \cref{Alg:multilevel}.
However, in this case, computing an explicit lower bound for $\tau_0$ is needed, and any such estimate may be overly conservative, potentially resulting in slow convergence of \cref{Alg:multilevel}.
To address this issue, we incorporate a backtracking line search strategy for selecting the step size, as introduced in~\cite{Park:2022a}, into the proposed multilevel method.
The resulting algorithm is summarized in \cref{Alg:multilevel_backt}.

% Algorithm: Multilevel method with backtracking
\begin{algorithm}
\caption{Parallel multilevel method for solving~\eqref{mixed_FEM_nearly} with backtracking}
\begin{algorithmic}[]
\label{Alg:multilevel_backt}
\STATE Choose $\bu^{(0)} \in V$ and $\tau^{(0)} > 0$.
\FOR{$n=0,1,2,\dots$}
    \FOR{$k = 1, 2, \dots, J$}
        \FOR{$i = 1, 2, \dots, n_k$}
            \STATE $\displaystyle \bw_{k,i}^{(n+1)} = \operatornamewithlimits{\arg\min}_{\bw_{k,i} \in V_k^i} F^{\epsilon} ( \bu^{(n)} + \bw_{k,i} )
            $
        \ENDFOR
    \ENDFOR
    \STATE $\displaystyle \tau \leftarrow 2 \tau^{(n)}$
    \REPEAT
        \STATE $\displaystyle
        \bu^{(n+1)} = \bu^{(n)} + \tau \sum_{k=1}^J \sum_{i=1}^{n_k} \bw_{k,i}^{(n+1)}
        $
        \IF{$\displaystyle F^{\epsilon} (\bu^{(n)}) - F^{\epsilon} (\bu^{(n+1)}) < \tau \sum_{k=1}^J \sum_{i=1}^{n_k} \left( F^{\epsilon} (\bu^{(n)}) - F^{\epsilon} (\bu^{(n)} + \bw_{k,i}^{(n+1)}) \right)$}
            \STATE $\displaystyle \tau \leftarrow \frac{\tau}{2}$
        \ENDIF
    \UNTIL{$\displaystyle F^{\epsilon} (\bu^{(n)}) - F^{\epsilon} (\bu^{(n+1)}) \geq \tau \sum_{k=1}^J \sum_{i=1}^{n_k} \left( F^{\epsilon} (\bu^{(n)}) - F^{\epsilon} (\bu^{(n)} + \bw_{k,i}^{(n+1)}) \right)$}
    \STATE $\displaystyle \tau^{(n+1)} = \tau$
\ENDFOR
\end{algorithmic}
\end{algorithm}

The key idea behind the backtracking strategy is to adaptively select a step size $\tau$ such that the global energy decay exceeds the sum of the local energy decays, weighted appropriately.
It was shown in~\cite[Lemma~3.1]{Park:2022a} that the backtracking procedure always terminates, and a lower bound for $\tau^{(n)}$ can be established in terms of $\tau_0$ defined in~\eqref{tau_0}.
Therefore, \cref{Alg:multilevel_backt} does not require a priori knowledge of $\tau_0$.

Moreover, both theoretical and numerical results in~\cite{Park:2022a} demonstrate that the backtracking strategy not only eliminates the need to tune the step size $\tau$ but can also improve the convergence rate.
The convergence analysis for the backtracking-enhanced method follows similar lines to the case without backtracking; we refer to~\cite{Park:2022a} for details and omit it here.

% Section: Numerical results
\section{Numerical results}
\label{Sec:Numerical}
In this section, we present numerical results for the proposed multilevel methods~(\cref{Alg:multilevel,Alg:multilevel_backt}) for solving the Darcy--Forchheimer model.
We also include results for the augmented Lagrangian method~(\cref{Alg:aug}) to support our theoretical findings.
All numerical experiments were conducted using MATLAB R2022b on a desktop equipped with an AMD Ryzen~5 5600X CPU (3.7~GHz, 6 cores), 40~GB RAM, and the Windows~10 Pro operating system.

For the Darcy--Forchheimer model~\eqref{Forchheimer}, we set $\Omega = (0,1)^2 \subset \mathbb{R}^2$ and assume that $\bK = K \bI$ for some positive scalar $K$.
Following the settings commonly used in the literature on numerical methods for the Darcy--Forchheimer model, we take $\mu = 1$, $\rho = 1$, and $K = 1$ as in~\cite{LMS:2009,HCR:2018,PR:2012}, and vary the Forchheimer coefficient $\beta = 0, 10, 20, 30$, as in~\cite{HCR:2018,LMS:2009}.
Note that the case $\beta = 0$ corresponds to the linear Darcy model.

% Discretization detail?

We consider the following two benchmark examples taken from~\cite{PR:2012}.

% Example : Example 1
\begin{example}
\label{Ex:Ex1}
The functions $\bf$ and $g$, and the corresponding exact solutions $\bu$ and $p$ of~\eqref{Forchheimer} are given by
\begin{align*}
\bf (x,y) &= \left(\frac{\mu}{\rho K} + \frac{\beta}{\rho} e^x \right)(e^x \sin y, e^x \cos y)^T + (y(1-2x)(1-y), x(1-x)(1 - 2y))^T, \\
g (x,y) &= 0, \quad
\bu (x,y) = ( e^x \sin y, e^x \cos y)^T, \quad
p (x,y) = xy(1-x)(1-y).
\end{align*}
\end{example}

% Example : Example 2
\begin{example}
\label{Ex:Ex2}
The functions $\bf$ and $g$, and the corresponding exact solutions $\bu$ and $p$ of~\eqref{Forchheimer} are given by
\begin{align*}
\bf (x,y) &= \left(\frac{\mu}{\rho K} + \frac{\beta}{\rho} \sqrt{x^2 e^{2y} + y^2 e^{2x}}\right)(x e^y, y e^x)^T + \pi ( \cos \pi x \sin \pi y, \sin \pi x \cos \pi y)^T, \\
g (x,y) &= e^x + e^y, \quad
\bu (x,y) = (x e^y, y e^x )^T, \quad
p (x,y) = \sin \pi x \sin \pi y.
\end{align*}
\end{example}

In all experiments and for all algorithms, we use zero initial guesses.
For the nearly semicoercive problem~\eqref{mixed_FEM_nearly}, we set $q_h = 0$ throughout.
In the linear case~($\beta = 0$), we employ \cref{Alg:multilevel} as a preconditioner for the conjugate gradient method~\cite{BPX:1990}.

