\section{Convergence analysis of the augmented Lagrangian method}
\label{App:Aug}
In this appendix, we present a proof of \cref{Thm:aug} in an abstract setting.
That is, we provide a convergence rate analysis of the augmented Lagrangian method~\cite{Hestenes:1969,Powell:1969} for solving convex optimization problems with linear constraints.

Let $V$ and $W$ be finite-dimensional real vector spaces equipped with inner products $(\cdot, \cdot)$ and associated norms $\| \cdot \|$.
We consider the following general convex optimization problem with a linear constraint:
\begin{equation}
\label{general}
\min_{v \in V} F(v) 
\quad \text{subject to} \quad Bv = g,
\end{equation}
where $B \colon V \rightarrow W$ is a linear operator, $F \colon V \rightarrow \overline{\mathbb{R}}$ is a convex functional, and $g \in W$.
Let $u \in V$ denote a solution to~\eqref{general}. The augmented Lagrangian method for solving~\eqref{general} is summarized in \cref{Alg:aug_general}.

% Algorithm: Augmented Lagrangian method
\begin{algorithm}
\caption{Augmented Lagrangian method for solving~\eqref{general}}
\begin{algorithmic}[]
\label{Alg:aug_general}
\STATE Given $\epsilon > 0$:
\STATE Choose $p^{(0)} \in W$.
\FOR{$n=0,1,2,\dots$}
    \STATE $\displaystyle
    u^{(n+1)} = \operatornamewithlimits{\arg\min}_{v \in V} \left\{ F (v) + ( p^{(n)}, Bv - g ) + \frac{1}{2\epsilon} \| Bv - g \|^2 \right\}
    $
    \STATE $\displaystyle
    p^{(n+1)} = p^{(n)} + \epsilon^{-1} ( B u^{(n+1)} - g)
    $
\ENDFOR
\end{algorithmic}
\end{algorithm}

We observe that \cref{Alg:aug_general} reduces to \cref{Alg:aug} if we set
\begin{equation}
\label{aug_general_reduction}
V \leftarrow X_h, \quad
W \leftarrow M_h, \quad
\| \cdot \| \leftarrow \| \cdot \|_{L^2 (\Omega)}, \quad
F(v) \leftarrow F (\bv), \quad
B \leftarrow - \div, \quad
g \leftarrow - g_h.
\end{equation}

To carry out the convergence analysis, we leverage the equivalence between the augmented Lagrangian method and the proximal point algorithm~\cite{Martinet:1970,Rockafellar:1976} for solving a dual problem, as established in~\cite{JPX:2025,Setzer:2011}.
By invoking Fenchel--Rockafellar duality~\cite{Rockafellar:1970}, the dual problem associated with~\eqref{general} is given by
\begin{equation}
\label{general_dual}
\min_{q \in W} \left\{ F^*(-B^* q) + (g, q) \right\},
\end{equation}
where $B^* \colon W \rightarrow V$ denotes the adjoint of $B$, and $F^* \colon V \rightarrow \overline{\mathbb{R}}$ is the Legendre--Fenchel conjugate of $F$, defined by
\begin{equation}
\label{Legendre_Fenchel}
F^*(w) = \sup_{v \in V} \left\{ (w, v) - F(v) \right\}, \quad w \in V.
\end{equation}

The proximal point algorithm for solving~\eqref{general_dual} is summarized in \cref{Alg:proximal_point}.

% Algorithm: Proximal point algorithm
\begin{algorithm}
\caption{Proximal point algorithm for solving~\eqref{general}}
\begin{algorithmic}[]
\label{Alg:proximal_point}
\STATE Given $\epsilon > 0$:
\STATE Choose $q^{(0)} \in W$.
\FOR{$n=0,1,2,\dots$}
    \STATE $\displaystyle
    q^{(n+1)} = \operatornamewithlimits{\arg\min}_{q \in W} \left\{ F^* (- B^* q) + (g, q) + \frac{\epsilon}{2} \| q - q^{(n)} \|^2 \right\}
    $
\ENDFOR
\end{algorithmic}
\end{algorithm}

In \cref{Lem:proximal_point_equiv}, we summarize the equivalence between \cref{Alg:aug_general,Alg:proximal_point}; see~\cite[Remark~6.2]{JPX:2025} for details. 

% Lemma: Proximal point algorithm
\begin{lemma}
\label{Lem:proximal_point_equiv}
The augmented Lagrangian method presented in \cref{Alg:aug_general} is equivalent to the proximal point algorithm presented in \cref{Alg:proximal_point} in the following sense: if $p^{(0)} = q^{(0)}$, then we have $p^{(n)} = q^{(n)}$ for all $n \geq 0$.
\end{lemma}

Thanks to \cref{Lem:proximal_point_equiv}, it suffices to analyze \cref{Alg:proximal_point} in order to establish the convergence rate of \cref{Alg:aug_general}.
In \cref{Lem:proximal_point_conv}, we present the convergence result for the proximal point algorithm, as established in~\cite[Example~23.40]{BC:2011}; see also~\cite{Kim:2021,Rockafellar:1976}.

% Lemma: Convergence of the proximal point algorithm
\begin{lemma}
\label{Lem:proximal_point_conv}
In~\eqref{general_dual}, suppose that $F^* \circ (- B^*)$ is $\mu$-strongly convex for some $\mu > 0$, ensuring that~\eqref{general_dual} admits a unique solution $p \in W$.
Then, in the proximal point algorithm presented in \cref{Alg:proximal_point}, we have
\begin{equation*}
\| q^{(n+1)} - p \| \leq \frac{\epsilon}{\mu + \epsilon} \| q^{(n)} - p \|,
\quad n \geq 0.
\end{equation*}
\end{lemma}

% Remark: Local strong convexity
\begin{remark}
\label{Rem:local_strong_convexity}
For certain convex optimization problems of the form~\eqref{general_dual} arising in partial differential equations~(see, e.g.,~\cite{LP:2024a}), particularly the dual problem associated with~\eqref{mixed_FEM_opt}, the composition $F^* \circ (- B^*)$ is only \emph{locally} strongly convex.
Nevertheless, since \cref{Alg:proximal_point} is a contraction, the sequence $\{ q^{(n)} \}$ remains bounded.
This boundedness allows the assumption of global strong convexity in \cref{Lem:proximal_point_conv} to be relaxed to a local one.
For simplicity and clarity of the analysis, however, we continue to assume global strong convexity throughout.
A related discussion appears in~\cite[Remark~2.1]{TX:2002}.
\end{remark}

Using \cref{Lem:proximal_point_equiv,Lem:proximal_point_conv}, we establish the convergence rate of \cref{Alg:aug_general}, as stated in \cref{Thm:aug_general}.
We remark that \cref{Thm:aug_general} generalizes~\cite[Lemma~2.1]{LWXZ:2007}, which addresses the special case where $F$ is quadratic, i.e., when~\eqref{general} reduces to a linear saddle-point problem.
In \cref{Thm:aug_general}, $D_F^{\mathrm{sym}}$ denotes the \textit{symmetrized Bregman divergence} associated with $F$~\cite{ABB:2013,NN:2009}, defined by
\begin{equation}
\label{symmetrized_Bregman}
D_F^{\mathrm{sym}} (v, w) = (\nabla F(v) - \nabla F(w), v - w), \quad v, w \in V.
\end{equation}

% Theorem: Augmented Lagrangian method
\begin{theorem}
\label{Thm:aug_general}
In~\eqref{general_dual}, suppose that $F^* \circ (- B^*)$ is $\mu$-strongly convex.
Then, in the augmented Lagrangian method presented in \cref{Alg:aug_general}, we have
\begin{equation}
\label{Thm1:aug_general}
\| p^{(n + 1)} - p \| \leq \frac{\epsilon}{\mu + \epsilon} \| p^{(n)} - p \|,
\quad n \geq 0.
\end{equation}
Moreover, if we further assume that $F$ is differentiable, then we have
\begin{equation}
\label{Thm2:aug_general}
D_F^{\mathrm{sym}} (u^{(n+1)}, u) \leq
\begin{cases}
\displaystyle
\frac{\mu \epsilon^2}{( \mu + \epsilon)^2} \| p^{(n)} - p \|^2, & \text{ if } \epsilon \leq \mu, \\
\displaystyle
\frac{\epsilon}{4} \| p^{(n)} - p \|^2, & \text{ if } \epsilon > \mu,
\end{cases}
\quad n \geq 0.
\end{equation}
\end{theorem}
\begin{proof}
The first estimate~\eqref{Thm1:aug_general} follows obviously from \cref{Lem:proximal_point_equiv,Lem:proximal_point_conv}.
To prove~\eqref{Thm2:aug_general}, we first see that the optimality condition for~\eqref{general} reads as
\begin{subequations}
\begin{align}
\label{Thm3:aug_general}
\nabla F(u) + B^* p = 0, \\
\label{Thm4:aug_general}
Bu = g.
\end{align}
\end{subequations}
Moreover, \cref{Alg:aug_general} reads as
\begin{subequations}
\begin{align}
\label{Thm5:aug_general}
\nabla F(u^{(n+1)}) + B^* p^{(n)} + \epsilon^{-1} B^* (B u^{(n+1)} - g) = 0, \\
\label{Thm6:aug_general}
p^{(n+1)} = p^{(n)} + \epsilon^{-1} (B u^{(n+1)} - g).
\end{align}
\end{subequations}
Combining~\eqref{Thm3:aug_general},~\eqref{Thm4:aug_general}, and~\eqref{Thm5:aug_general} yields
\begin{equation}
\label{Thm7:aug_general}
\nabla F(u^{(n+1)}) - \nabla F(u) + B^* (p^{(n)} - p) + \epsilon^{-1} B^* B (u^{(n+1)} - u) = 0.
\end{equation}
In addition, combining~\eqref{Thm4:aug_general} and~\eqref{Thm6:aug_general} yields
\begin{equation}
\label{Thm8:aug_general}
p^{(n+1)} - p^{(n)} = \epsilon^{-1} B (u^{(n+1)} - u).
\end{equation}
It follows that
\begin{equation}
\label{Thm9:aug_general}
\begin{split}
D_F^{\mathrm{sym}} &(u^{(n+1)}, u)
\stackrel{\eqref{symmetrized_Bregman}}{=} (\nabla F(u^{(n+1)}) - \nabla F(u), u^{(n+1)} - u) \\
&\stackrel{\eqref{Thm7:aug_general}}{=} - (B^* (p^{(n)} - p), u^{(n+1)} - u) - \epsilon^{-1} (B^* B (u^{(n+1)} - u), u^{(n+1)} - u) \\
&\stackrel{\eqref{Thm8:aug_general}}{=} - \epsilon \| p^{(n+1)} - p \|^2 + \epsilon (p^{(n+1)} - p, p^{(n)} - p) \\
&\leq   \epsilon\left( \frac{1}{2 \theta} - 1 \right) \| p^{(n+1)} - p \|^2 + \frac{\epsilon \theta}{2} \| p^{(n)} - p \|^2,
\end{split}
\end{equation}
where $\theta$ is any positive real number.
On one hand, if $\epsilon \leq \mu$, setting $\theta = \frac{\epsilon}{\mu + \epsilon} \leq \frac{1}{2}$ in~\eqref{Thm9:aug_general} yields
\begin{equation*}
D_F^{\mathrm{sym}} (u^{(n+1)}, u)
\leq \frac{\mu - \epsilon}{2} \| p^{(n+1)} - p \|^2 + \frac{\epsilon^2}{2 (\mu + \epsilon)} \| p^{(n)} - p \|^2
\stackrel{\eqref{Thm1:aug_general}}{\leq} \frac{\mu \epsilon^2}{( \mu + \epsilon )^2} \| p^{(n)} - p \|^2.
\end{equation*}
On the other hand, if $\epsilon > \mu$, setting $\theta = \frac{1}{2}$ in~\eqref{Thm9:aug_general} yields
\begin{equation*}
D_F^{\mathrm{sym}} (u^{(n+1)}, u) \leq \frac{\epsilon}{4} \| p^{(n)} - p \|^2.
\end{equation*}
This completes the proof.
\end{proof}

