% Appendix: Abstract convergence theory
\section{Abstract theory of subspace correction methods for nearly semicoercive problems}
\label{App:Nearly}
In this appendix, we provide a brief summary of the abstract convergence theory of subspace correction methods for nearly semicoercive convex optimization problems, as developed in~\cite{LP:2024b}.
Although the theory in~\cite{LP:2024b} is formulated in a broader setting, we confine our discussion here to a specific case suitable for our purpose, for the sake of simplicity and clarity.

Let $V$ be a uniformly smooth and uniformly convex Banach space (cf.~\cite{Megginson:1998}) equipped with a norm $\| \cdot \|$ and a continuous seminorm $| \cdot |$.
We consider the following nearly semicoercive model problem:
\begin{equation}
\label{model_abstract}
\min_{v \in V} \left\{ F(v) := F_0(v) + \epsilon F_1(v) \right\},
\end{equation}
where $F_0 \colon V \rightarrow \mathbb{R}$ and $F_1 \colon V \rightarrow \mathbb{R}$ are G\^{a}teaux differentiable and convex functionals, and $\epsilon$ is a small positive parameter, say $\epsilon \in (0, 1/2]$.
We further assume that $F_0$ is semicoercive with respect to $| \cdot |$~\cite[Proposition~2.3]{LP:2024b}, and that $F_1$ is coercive.

Suppose that the space $V$ admits the following space decomposition:
\begin{equation}
\label{space_decomposition_abstract}
V = \sum_{k=1}^J V_k,
\end{equation}
where each $V_k$, $1 \leq k \leq J$, is a closed subspace of $V$.
The strengthened convexity condition~\cite[Equation~(3.4)]{LP:2024b} asserts that there exists a constant $\tau_0 > 0$ such that
\begin{equation}
\label{strengthened_convexity}
(1 - \tau_0) F(v) + \tau_0 \sum_{k=1}^J F(v + w_k) \geq F \left( v + \tau_0 \sum_{k=1}^J w_k \right),
\quad v \in V \text{ } w_k \in V_k.
\end{equation}

% % Remark: Strengthened convexity
% \begin{remark}
% \label{Rem:strengthened_convexity}
% The condition given in~\cite{LP:2024b,Park:2020,Park:2022a} is stated in a global sense.
% However, by carefully following the convergence analysis in~\cite{LP:2024b}~(see~\cite[Equation~(4.7)]{LP:2024b}), we deduce that we may replace the global condition with the local condition given above.
% \end{remark}

The parallel subspace correction method for solving the problem~\eqref{model_abstract} based on the space decomposition~\eqref{space_decomposition_abstract} is presented in \ref{Alg:PSC}.

% Algorithm: PSC
\begin{algorithm}
\caption{Parallel subspace correction method for solving~\eqref{model_abstract}}
\begin{algorithmic}[]
\label{Alg:PSC}
\STATE Given $\tau > 0$:
\STATE Choose $u^{(0)} \in V$.
\FOR{$n=0,1,2,\dots$}
    \FOR{$k = 1, 2, \dots, N$}
        \STATE $\displaystyle w_k^{(n+1)} = \operatornamewithlimits{\arg\min}_{w_k \in V_k} F(u^{(n)} + w_k)$
    \ENDFOR
    \STATE $\displaystyle
    u^{(n+1)} = u^{(n)} + \tau \sum_{k=1}^J w_k^{(n+1)}
    $
\ENDFOR
\end{algorithmic}
\end{algorithm}

In the following, we present conditions that should be verified to show convergence of \cref{Alg:PSC}.
We define the Bregman divergences $d_0$ and $d_1$ corresponding to $F_0$ and $F_1$, respectively, as in~\eqref{d1}.
Combination of~\cite[Proposition~4.9 and Assumption~5.4]{LP:2024b} yields the following local smoothness condition.

% Assumption: Smoothness - Nearly coercive problem
\begin{assumption}[local smoothness]
\label{Ass:smooth}
For any $\| \cdot \|$-bounded and convex subset $K$ of $V$, we have
\begin{equation*}
    \sup_{v, v + w \in K} \frac{d_{0} (w; v)}{\| w \|^2} < \infty
    \quad \text{and} \quad
    \sup_{v, v + w \in K} \frac{d_{1} (w; v)}{\| w \|^2} < \infty.
\end{equation*}
\end{assumption}

The local uniform convexity condition~\cite[Assumption~5.9]{LP:2024b} is presented as follows.

% Assumption: Local uniform convexity
\begin{assumption}[local uniform convexity]
\label{Ass:uniform}
For some $p \geq 2$, we have the following:
\begin{enumerate}[(a)]
\item For any $| \cdot |$-bounded and convex subset $K$ of $V$, we have
\begin{equation*}
    \mu_{0,K} := \inf_{v, v+w \in K} \frac{d_0 (w; v)}{| w |^p} > 0.
\end{equation*}
\item For any $\| \cdot \|$-bounded and convex subset $K$ of $V$, we have
\begin{equation*}
    \mu_{1,K} := \inf_{v, v+w \in K} \frac{(d_0 + d_1) (w; v)}{\| w \|^p} > 0.
\end{equation*}
\end{enumerate} 
\end{assumption}

Under \cref{Ass:smooth,Ass:uniform}, we can ensure convergence of \cref{Alg:PSC}~\cite[Theorem~4.13]{LP:2024b}~(see also~\cite[Theorem~4.8]{Park:2020}).
However, in order to ensure $\epsilon$-dependent convergence rate, we need more conditions.

The following kernel decomposition assumption~\cite[Assumption~5.6]{LP:2024b}, originally introduced in~\cite{LWXZ:2007} for the analysis of linear problems, plays a critical role in the convergence theory.

% Assumption: Kernel decomposition
\begin{assumption}[kernel decomposition]
\label{Ass:kernel}
The kernel $\cN = \ker F_0$ of the semicoercive functional $F_0$ in~\eqref{model_abstract} admits the decomposition
\begin{equation*}
\cN = \sum_{k=1}^J (V_k \cap \cN).
\end{equation*}
\end{assumption}

The next condition, \cref{Ass:triangle}, describes a triangle-inequality-like property stated in~\cite[Assumption~5.7]{LP:2024b}.

% Assumption: Triangle-inequality-like property
\begin{assumption}[triangle inequality-like property]
\label{Ass:triangle}
For any bounded and convex subset $K \subset V$, there exists a constant $C_{K} > 0$ such that
\begin{equation}
\label{C_tri}
d_1(w + w'; v) \leq C_{K} \left( d_1(w; v) + d_1(w'; v) \right),
\quad v \in K, \quad w, w' \in V.
\end{equation}
\end{assumption}

Similar to~\eqref{K_0}, given an initial guess $u^{(0)} \in V$ for \cref{Alg:PSC}, we define the set $K_0$ by
\begin{equation}
\label{K_0_abstract}
K_0 := \{ v \in V : F(v) \leq F(u^{(0)}) \}.
\end{equation}
Note that $K_0$ depends implicitly on $\epsilon$ due to the $\epsilon$-dependence of the energy functional $F$; see~\cite[Remark~5.5]{LP:2024b}.
Under all the assumptions stated above, we obtain the following convergence theorem, which is a direct consequence of~\cite[Theorems~4.13, 5.8, and 5.10]{LP:2024b}.

% Theorem: Convergence theorem for nearly semicoercive
\begin{theorem}
\label{Thm:nearly}
Suppose that \cref{Ass:smooth,Ass:uniform,Ass:kernel,Ass:triangle} hold.
In \cref{Alg:PSC}, assume that $\tau \in (0, \tau_{0}]$, where $\tau_0$ was given in~\eqref{strengthened_convexity}.
Then we have the following:
\begin{enumerate}[(a)]
\item In the case $p = 2$, we have
\begin{equation*}
F(u^{(n)}) - F(u)
\leq \left( 1 - \frac{\tau}{2} \min \left\{ 1, \frac{C_2}{C_1} \right\} \right)^n ( F(u^{(0)}) - F(u) ),
\quad n \geq 0,
\end{equation*}
where $C_1$ is a positive constant independent of $\epsilon$, except for its implicit dependence on $K_0$ (see~\eqref{K_0_abstract}), and $C_2 = \min \{ \mu_{0, K_0}, \mu_{1, K_0} \}$.

\item In the case $p > 2$, there exists $\zeta^* > 0$ such that, if $F(u^{(0)}) - F(u) > \zeta^*$, then
\begin{equation*}
F(u^{(1)}) - F(u) \leq \left( 1 - \frac{\tau}{2} \right) ( F(u^{(0)}) - F(u) ),
\end{equation*}
and otherwise,
\begin{equation*}
F(u^{(n)}) - F(u) \leq \frac{ C_1^{\frac{p}{p-2}} }{ \tau^{\frac{p}{p-2}} C_2^{\frac{2}{p-2}} n^{\frac{p}{p-2}} },
\quad n \geq 1,
\end{equation*}
where $C_1$ and $C_2$ are as defined in~(a).
\end{enumerate}
\end{theorem}

