\begin{document}
\title{Group Gradings on Classical Lie Superalgebras}

\author{Caio De Naday Hornhardt}
\address{Department of Mathematics and Statistics, Memorial University of Newfoundland, St. John's, NL, A1C5S7, Canada}
\email{cdnh22@mun.ca}
\thanks{This paper is based on the first author's Ph.D. thesis, written under the supervision of the second author. The first author acknowledges the support of Memorial University and of the Natural Sciences and Engineering Research Council (NSERC) of Canada.}

\author{Mikhail Kochetov}
\address{Department of Mathematics and Statistics, Memorial University of Newfoundland, St. John's, NL, A1C5S7, Canada}
\email{mikhail@mun.ca}
\thanks{The second author is supported by Discovery Grant 2018-04883 of NSERC}

\begin{abstract}
    We classify, up to isomorphism, the group gradings on the non-exceptional classical simple Lie superalgebras, except for type~$A(1,1)$, over an algebraically closed field of characteristic zero.
    To this end, we study graded-simple and graded-superinvolution-simple associative superalgebras satisfying the descending chain condition on graded left superideals, which allows us to classify abelian group gradings on finite-dimensional simple and superinvolution-simple associative superalgebras over an algebraically closed field of characteristic different from $2$.
\end{abstract}

\keywords{Group grading, Lie superalgebra, classical Lie superalgebra, associative superalgebra, superinvolution}

