% Tipo di documento. L'uso di twoside implica che i capitoli inizino sempre con la prima pagina a sinistra, eventualmente lasciando una pagina vuota nel capitolo precedente. Se questa cosa è fastidiosa, è possibile rimuoverlo. 
\documentclass[a4paper, twoside,openright]{report}

% Dimensione dei margini
\usepackage[a4paper,top=3cm,bottom=3cm,left=3cm,right=3cm]{geometry} 
% Dimensione del font
\usepackage[fontsize=11pt]{scrextend}
% Lingua del testo
\usepackage[english]{babel}
% Lingua per la bibliografia
\usepackage[fixlanguage]{babelbib}
% Codifica del testo
\usepackage[utf8]{inputenc} 
% Encoding del testo
\usepackage[T1]{fontenc}
% Per ruotare le immagini
\usepackage{rotating}
% Per modificare l'header delle pagine 
\usepackage{fancyhdr}               

% Librerie matematiche
\usepackage{amssymb}
\usepackage{amsmath, stmaryrd}
\usepackage{amsthm}         
\usepackage{proof}
% Uso delle immagini
\usepackage{graphicx}
% Uso dei pdf
\usepackage{pdfpages}
% Uso dei colori        
% Uso dei listing per il codice
\definecolor{Black}{rgb}{0.0, 0.0, 0.0}
\definecolor{Green}{rgb}{0.0, 0.6, 0.3}
\definecolor{Blue}{rgb}{0.0, 0.0, 1.0}
\usepackage{listings}          
% Per inserire gli hyperlinks tra i vari elementi del testo 
\usepackage{hyperref}     
\hypersetup{colorlinks,allcolors=Blue}
% Diversi tipi di sottolineature
\usepackage[normalem]{ulem}
% Per creare degli schemi
\usepackage{tikz}
\usetikzlibrary{shapes, positioning}
\usetikzlibrary{patterns}
%Per gli uguali lunghi su cui scrivere regola
\usepackage{extarrows}
%Per font matematici extra
\usepackage{mathrsfs} 
%Per personalizzare gli elenchi puntati
\usepackage{enumitem} 
\usepackage{mathtools}
%Lasciare solo i necessari
\usepackage{booktabs}
\usepackage{bussproofs}
\usepackage[all,2cell,cmtip]{xy} 
\UseAllTwocells 
\usepackage{relsize}
\usepackage{stmaryrd}
\usepackage{longtable}
\usepackage{fancyvrb}
\VerbatimFootnotes

\usepackage{multirow}
\usepackage{microtype}
\usepackage{multicol}
\usepackage{needspace}


% -----------------------------------------------------------------

% Modifica lo stile dell'header
\pagestyle{fancy}
\fancyhf{}
\lhead{\rightmark}
\rhead{\textbf{\thepage}}
\fancyfoot{}
\setlength{\headheight}{12.5pt}

% Rimuove il numero di pagina all'inizio dei capitoli
\fancypagestyle{plain}{
  \fancyfoot{}
  \fancyhead{}
  \renewcommand{\headrulewidth}{0pt}
}

% Stile del codice
\lstset{breaklines=true,
  language=[objective]caml,     
  basicstyle=\ttfamily,
  columns=fullflexible,
  keepspaces=true,
  keywordstyle=[2]\color{green},
  keywordstyle=[1]\color{purple}, 
  keywordstyle=[3]\color{blue}\bfseries,
  showstringspaces=false,
  morekeywords=[1]{new_definition, 
                   new_recursive_definition,
                   new_inductive_definition,
                   define_type,
                   loadt,
                   prove,
                   function},
   morekeywords=[2]{REPEAT,THEN},
   morekeywords=[3]{let, in, val, rec, fun, match, with, type, and, open, module, struct, sig, end, if, then, else, begin, end},
   commentstyle=\color{gray},
   literate={'"'}{\textquotesingle "\textquotesingle}3,
  alsodigit={_}
}

\lstset{
  escapeinside={(*@}{@*)},  % enables LaTeX escapes within the listing
  basicstyle=\ttfamily
}

% Togliendo il commento al comando che segue, si inseriscono nella bibliografia anche le fonti presenti in Bibliography.bib ma non citati direttamente con il comando \cite
\nocite{*}

% Margini prima e dopo blocchi di codice, per avere più distanza
\lstset{aboveskip=20pt,belowskip=20pt}

% Modifica dello stile dei riferimenti, con il testo in cyano
\hypersetup{
    colorlinks,
    linkcolor=Blue,
    citecolor=Blue
}

% Aggiunti definizioni, teoremi, linea e listing
\newtheorem{definition}{Definition}[section]
\newtheorem{convention}{Convention}[section]
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}{Lemma}[section]
\newtheorem{fact}{Fact}[section]
\providecommand*\definitionautorefname{Definition}
\providecommand*\theoremautorefname{Theorem}
\providecommand*{\listingautorefname}{Listing}
\providecommand*\lstnumberautorefname{Linea}



\usepackage{chngcntr} % Per resettare contatori

% Definizione dei contatori
\newcounter{claimcounter}

\numberwithin{claimcounter}{theorem} % Resetta il contatore per ogni theorem
\numberwithin{claimcounter}{lemma}   % Resetta il contatore per ogni lemma
