\section{Data Poisoning attack Machine Learning } 

Let $\mathcal{D}=\left\{\left(\boldsymbol{x}_i, y_i\right)\right\}_{i=1}^N$ be a clean training set, and $C: \mathcal{X} \rightarrow$ $\mathcal{Y}$ denotes the functionality of the target neural network. For each sound $\boldsymbol{x}_i$ in $\mathcal{D}$, we have $\boldsymbol{x}_i \in \mathcal{X}=[0,1]^{C \times W \times H}$, and $y_i \in \mathcal{Y}=\{1, \ldots, J\}$ is the corresponding label, where $J$ is the number of label classes. To launch an attack, backdoor adversaries first need to poison the selected clean samples $\mathcal{D}_p$ with covert transformation $T(\cdot)$. Then the poisoned samples are mixed with clean ones before training a backdoored model, the process of which can be formalized as: $\mathcal{D}_t=\mathcal{D} \cup \mathcal{D}_p$, where $\mathcal{D}_p=\left(x_i^{\prime}, y_t\right) \mid x^{\prime}=T(x),\left(x_i, y_i\right) \in \mathcal{D}_p$. The deep neural network (DNNs) is then optimized as follows:

$$
\min _{\boldsymbol{\Theta}} \sum_{i=1}^{N_b} \mathcal{L}\left(f\left(\boldsymbol{x}_i ; \boldsymbol{\Theta}\right), y_i\right)+\sum_{j=1}^{N_p} \mathcal{L}\left(f\left(\boldsymbol{x}_r^{\prime} ; \boldsymbol{\Theta}\right), y_t\right) .
$$ where $N_b=|\mathcal{D}|$ , $N_p=\left|\mathcal{D}_p\right|$.


\begin{figure}[H]
\centering
\includegraphics[width=0.45\textwidth]{imgs/Fig4.png}
\caption{Data Poisoning.}
\label{fig:attacker's_view}
\end{figure}


In this study \cite{feng2023review},\cite{rigaki2023survey},\cite{hou2023large},\cite{sosnin2024certified},\cite{yu2024generalization}, a scenario in which a model owner aims to train a deep learning model based on the training dataset provided by a third party (Figure \ref{fig:attacker's_view}) is considered. However, the third party can poison the training dataset to hijack the model in the future. We assume that the model owner and the trusted third party play the roles of defender and attacker, respectively, in the threat model. The threat model is shown in Figure \ref{fig:attacker's_knowledge}.

The knowledge that an attacker can access can generally be classified \cite{yang2024comprehensive} into two categories. Figure \ref{fig:attacker's_knowledge}: White and black box settings. In a white-box environment, the adversary understands and controls the target dataset and model, including the ability to access and modify the dataset, as well as parameters and the structure of the model. However, in the stricter framework of the black-box, the attacker is only able to manipulate part of the training data but has no knowledge of the structure and parameters of the target model, such as weights, hyperparameters, configurations, etc.


\begin{figure}[H]
\centering
\includegraphics[width=0.45\textwidth]{imgs/Fig6.png}
\caption{knowledge.}
\label{fig:attacker's_knowledge}
\end{figure}


By deliberately misclassifying the inputs with the trigger (Figure \ref{fig:backdoorexp}) as the adversary's intended labels, the adversary uses a backdoor approach to keep the victim model operating at a high level of accuracy on normal samples. The adversary seeks to have the target model behave as expected on benign data while operating in a way described by the adversary on samples that have been poisoned, as seen in Figure \ref{fig:attacker's_knowledge}. 
A formulation of the enemy's objective is: 


$$
\begin{aligned}
\min _{\mathcal{M}^*} \mathcal{L}\left(\mathcal{D}^b, \mathcal{D}^p, \mathcal{M}^*\right)= & \sum_{x_i \in \mathcal{D}^b} l\left(\mathcal{M}^*\left(x_i\right), y_i\right) \\
& +\sum_{x_j \in \mathcal{D}^p} l\left(\mathcal{M}^*\left(x_r \circ  \varepsilon \right), y_t\right),
\end{aligned}
$$


where $\mathcal{D}^b$ and $\mathcal{D}^p$ represent the benign and poisoned training datasets, respectively. The function $l(\cdot, \cdot)$ denotes the loss function which depends on the specific task. The symbol $\circ $ denotes the operation of integrating the backdoor trigger $(\varepsilon)$ into the training data.


\section{Adversarial Machine Learning in Finance via Bayesian Approach}

\begin{algorithm}[ht]
\caption{Diffusion Bayesian Optimization}
\label{alg:Diffusion_bayesian_optimization}
\KwData{T, $\theta$, $\alpha$, $\beta$, $\sigma$}
\KwResult{Model parameters and trace.}
Initialize $x_T$\;
\For{$t \leftarrow T - 1$ \textbf{downto} $0$}{
    \If{$t > 1$}{
        $z \gets$ Noise\_dist$(0)$\;
    }
    Else{
        $z \gets 0$\;
    }
    $transport\_component \gets$ Optimal\_transport$(x_T, t, \theta, \beta, \sigma)$\;
    $x_{t-1} \gets$ Normal$(f'x_t', \mu = drift\_function(x_T, t, \theta, \beta, \sigma) + transport\_component + \sigma[t] \cdot z, \sigma = 1)$\;
    $x_T \gets x_{t-1}$\;
}
\end{algorithm}



\begin{algorithm}[ht]
\SetAlgoLined
\KwData{$\theta$, $\alpha$, $\beta$, $\sigma$}
\KwResult{Priors for $\theta$, $\alpha$, $\beta$, $\sigma$}

Define hierarchical priors for each parameter group\;
\BlankLine
\For{each parameter group}{
  \If{parameter group is $\theta$}{
    $\theta \sim \mathcal{N}(0,1)$\;
  }
  \ElseIf{parameter group is $\alpha$}{
    $\alpha \sim \mathcal{N}(0,1)$\;
  }
  \ElseIf{parameter group is $\beta$}{
    $\beta \sim \mathcal{N}(0,1)$\;
  }
  \ElseIf{parameter group is $\sigma$}{
    $\sigma \sim \mathcal{N}(0,1)$\;
  }
}
\caption{Setting up hierarchical priors}
\label{alg:hierarchical_priors}
\end{algorithm}



