\section*{Concepts of LIBOR Market.}

\begin{definition}[LIBOR Market]

The $\delta_i$-forward-LIBOR rate $L_i(t)$ is the simple yield for the time interval $\left[t_{i-1}, t_i\right]$, i.e. with $\delta_i=t_i-t_{i-1}$ we define:


 \begin{align*}
\begin{aligned}
L_i(t)=L\left(t ; t_{i-1}, t_i\right)=\frac{1}{\delta_i} \frac{P\left(t, t_{i-1}\right)-P\left(t, t_i\right)}{P\left(t, t_i\right)} .
\end{aligned}
\end{align*}

By the definition of the $t_i$-forward measure $\mathbb{Q}_i:=\mathbb{Q}_{t_i}$,  $L_i(t)$ is a $\mathbb{Q}_i$-martingale. Thus, it is an immediate consequence that if we want to model log-normal forward-LIBOR rates in a diffusion setting, we have to choose the following dynamics under $\mathbb{Q}_i$ :

$$
d L_i(t)=L_i(t) \sigma_i(t) d W_i(t),
$$

Here, $W_i($.$)$ is a (for the moment one-dimensional) $\mathbb{Q}_i$-Brownian motion, $\sigma_i(t)$ a bounded and deterministic function.

\end{definition}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{remark}
 The risk-free deposit rates $D_s^i$ for deposits between $t_i$ and $t_{i+1}$ are defined by,

$$
1+\delta_i D_s^i=\frac{P^D\left(s, t_i\right)}{P^D\left(s, t_{i+1}\right)} .
$$

The factors $\delta_i$ are the accrual factors or day count fractions and represent the fraction of the year spanned by the interval $\left[t_i, t_{i+1}\right]$ .


$$
d D_t^j=\gamma_j\left(D_t^j, t\right) \cdot d W_t^{j+1}
$$
 $\gamma_j(0 \leq j \leq n-1)$ are $m$-dimensional functions.
The Brownian motion change between the $N_t$ and the $P^D\left(t, t_{j+1}\right)$  is given by,

$$
d W_t^{j+1}=d W_t+\nu\left(t, t_{j+1}\right) d t  .
$$

 $\nu\left(t, t_{j+1}\right)-\nu\left(t, t_j\right)$ can be written \cite{rebonato2002theory} as:
$$
\nu\left(t, t_{j+1}\right)-\nu\left(t, t_j\right)=\frac{1}{D_t^j+\frac{1}{\delta_j}} \gamma_j\left(D_t^j, t\right)
$$


$$
d W_t^{j+1}=-\sum_{i=j+1}^{n-1} \frac{1}{D_t^i+\frac{1}{\delta_i}} \gamma_i\left(D_t^i, t\right) d t+d W_t^n .
$$


 \begin{align*}
\begin{aligned}
d L_t^j=-\left(\sum_{i=j+1}^{n-1} \frac{1}{D_t^i+\frac{1}{\delta_i}} \gamma_i\left(D_t^i, t\right) \cdot \gamma_j\left(D_t^j, t\right)\right) d t+ \\ \gamma_j\left(D_t^j, t\right) \cdot d W_t^n .
\end{aligned}
\end{align*}

by incorporating a diffusion approximation with  $a_i \leq 1 / \delta_i$ we have, 

$$
\gamma_j(D, t)=\alpha(t)\left(D+a_j\right) \gamma_j
$$



 \begin{align*}
\begin{aligned}  
d D_t^j=-\alpha^2(t)\left(\sum_{i=j+1}^{n-1} \frac{D_t^i+a_i}{D_t^i+\frac{1}{\delta_i}} \gamma_i \cdot \gamma_j\right)\left(D_t^j+a_j\right) d t+ \\ \alpha(t)\left(D_t^j+a_j\right) 
\gamma_j \cdot d W_t^n .
\end{aligned}
\end{align*}

with $\alpha$ a deterministic scalar function, $a$ a constant vector of dimension $n$ and $\left(\gamma_j\right)_{j=1, \ldots, n}$ vectors of dimension $m$. 

\end{remark}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


\begin{theorem} Cap pricing and the Black formula, 
 for $i=1, \ldots, N$ the $\delta_i$ forward-LIBOR rates satisfy,

$$
d L_i(t)=L_i(t) \sigma_i(t) d W_i(t), t<t_i .
$$
(a) Then today's price $C_i\left(t, \sigma_i(t)\right)$ of a caplet maturing at time $t_i$ with a payment of $\delta_i \cdot\left(L_i\left(t_i\right)-L\right)^{+}$is given by,


 \begin{align*}
\begin{aligned}
C_i\left(t, \sigma_i(t)\right)=\delta_i P\left(t, t_i\right)\left[L_i(t) \Phi\left(d_1(t)\right)-L \Phi\left(d_2(t)\right)\right], \\
d_1(t)=\frac{\ln \left(\frac{L_i(t)}{L}\right)+\frac{1}{2} \bar{\sigma}_i^2(t)}{\bar{\sigma}_i(t)}, d_2(t)=d_1(t)-\bar{\sigma}_i(t), \\
\bar{\sigma}_i^2(t)=\int_t^{t_{i-1}} \sigma^2(s) d s .
\end{aligned}
\end{align*}

(b) Today's price of a cap in the forward-LIBOR model $\operatorname{Cap}_{F L}(t ; V, L)$ with payment times $t_1<\ldots<t_N$ and level $L$ is given by,

$$
\operatorname{Cap}_{F L}(t ; V, L)=V \cdot \sum_{i=1}^N C_i\left(t, \sigma_i(t)\right) .
$$

In particular, if all volatility processes satisfy $\sigma_i(t)=\sigma$ for some positive constant $\sigma$ then we have

$$
\operatorname{Cap}_{F L}(t ; V, L)=\operatorname{Cap}_{\text {Black }}(t, V, L, \sigma),
$$
i.e. the price of the cap equals the one obtained with the Black formula.
\end{theorem}



\section*{Concepts of hedging.}


For hedging \footnote{\href{https://www.math.columbia.edu/~smirnov/over99.pdf}{Hedging concepts}} and risk management, the delta \cite{fliess2010delta},\cite{fliess2012preliminary} $\Delta=\frac{\partial V}{\partial S}$, i.e., the first partial derivative of the option's value with respect to the index level: For the Greeks of a European call option.


$$
\Delta=\frac{\partial C}{\partial S}=N\left(d_1\right)
$$

The gamma is the second partial derivative with respect to the index level,

$$
\gamma=\frac{\partial^2 C}{\partial S^2}=\frac{N^{\prime}\left(d_1\right)}{S \sigma \sqrt{T-t}}
$$

The theta of an option is, by convention, the negative first partial derivative with respect to time-to-maturity $t^*=T-t$

$$
\theta=-\frac{\partial C}{\partial t^*}=-\frac{S N^{\prime}\left(d_1\right) \sigma}{2 \sqrt{T-t}}-r e^{-r(T-t)} K N \left(d_2\right)
$$

The rho of an option is the first partial derivative with respect to the short rate $r$

$$
\rho=\frac{\partial C}{\partial r}=K(T-t) e^{-r(T-t)} N\left(d_2\right)
$$

The vega-which is obviously not a Greek letter-is the first partial derivative with respect to the volatility $\sigma$,

$$
\mathbf{vega}=\frac{\partial C}{\partial \sigma}=S N^{\prime}\left(d_1\right) \sqrt{T-t}
$$


Hedging dynamics can be defined as: 

$$
\Delta_t^P \equiv \frac{\partial P_t}{\partial S_t}
$$


$$
d P_t-\Delta_t^P d S_t=0
$$


Investment banks are also often interested in replicating the payoff of such a put (or another option). 

This is accomplished by setting up a replication portfolio consisting of $\Delta_t^P$ units of the underlying and $\gamma_t \equiv P_t-\Delta_t^P S_t$ units of the risk-less bond $B_t$ such that the resulting portfolio value equals the option value at any time $t$,

$$
P_t=\Delta_t^P S_t+\gamma_t B_t
$$
or
$$
d P_t=\Delta_t^P d S_t+\gamma_t d B_t
$$

For a plain vanilla put option this generally implies being short the underlying $\left(\Delta_t^P<0\right)$ and long the bond. For a call option $\left(\Delta_t^C>0\right)$ this implies the opposite.

A replication strategy $\left(\Delta_t^P, \gamma_t\right), t \in\{0, \ldots, \tau-\Delta t\}$, is called self-financing if for $t>0$ and $\tau$ being the exercise date (i.e, $\tau=T$ for a European option)
$$
\Delta_t^P S_t+\gamma_t B_t=\Delta_{t-\Delta t}^P S_t+\gamma_{t-\Delta t} B_t.
$$


Self-financing: The value $V_t$ of a portfolio containing $\psi_t$ units of bonds and $\phi_t=\left(\phi_{t, 1}, \ldots, \phi_{t, m}\right)^{\top}$ units of various stocks at a given time $t$ is given by
$$
V_t=B_t \psi_t+\sum_{i=1}^m \phi_{t, i} S_{t, i}=B_t \psi_t+\phi_t^{\top} \mathbf{S}_t .
$$


The particular value of the portfolio at time $t$ typically depends on the units of assets $\left(\psi_t, \phi_t\right)$ held just before time $t$. The stochastic process $\left\{\left(\psi_t, \phi_t\right), t \geqslant 0\right\}$ can thus be interpreted as a trading strategy. 


 $\left\{\mathcal{F}_t, t \geqslant 0\right\}$. 
$$
\mathrm{d} V_t=\left(B_t \mathrm{~d} \psi_t+\mathbf{S}_t^{\top} \mathrm{d} \phi_t\right)+\psi_t \mathrm{~d} B_t+\phi_t^{\top} \mathrm{d} \mathbf{S}_t
$$


The portfolio is called self-financing if
$$
B_t \mathrm{~d} \psi_t+\mathbf{S}_t^{\top} \mathrm{d} \phi_t=0
$$
in which case
$$
V_T=V_0+\int_0^T \psi_t \mathrm{~d} B_{\ell}+\int_0^T \phi_t^{\top} \mathrm{d} \mathbf{S}_t .
$$


Arbitrage-free market: A market model is called arbitrage-free on $[0, T]$ if, in essence, for every self-financing trading strategy $\left\{\left(\psi_t, \phi_t\right), 0 \leqslant t \leqslant T\right\}$,
$$
V_0=0 \Rightarrow \mathbb{P}\left(V_T>0\right)=0 \text {. }
$$

 $\left\{\widetilde{\mathbf{S}}_t, 0 \leqslant t \leqslant T\right\}$, with $\widetilde{\mathbf{S}}_t=B_t^{-1} \mathbf{S}_t$, is an $\left(\mathcal{F}_t, \mathbb{Q}\right)$-martingale. 

$$
\sigma_t \mathbf{u}_t=\mu_t-r_t \mathbf{S}_t
$$
has a solution $\mathbf{u}_t, t \in[0, T]$ for which $\mathbb{E} \exp \left(\frac{1}{2} \int_0^T \mathbf{u}_t^{\top} \mathbf{u}_t \mathrm{~d} t\right)<\infty$ 


$$
\begin{aligned}
\mathrm{d} \widetilde{\mathbf{S}}_t & =B_t^{-1}\left(\boldsymbol{\mu}_t-r_t \mathbf{S}_t\right) \mathrm{d} t+B_t^{-1} \sigma_t \mathrm{~d} \mathbf{W}_t \\
& =B_t^{-1} \sigma_t\left(\mathbf{u}_t \mathrm{~d} t+\mathrm{d} \mathbf{W}_t\right) \\
& =B_t^{-1} \sigma_t \mathrm{~d} \mathbf{Z}_t
\end{aligned}
$$

where $\mathrm{d} \mathbf{Z}_t=\mathbf{u}_t \mathrm{~d} t+\mathrm{d} \mathbf{W}_t$ , defines an Itô process. Let

$$
M_t=\exp \left(\int_0^t \mathbf{u}_s^{\top} \mathrm{d} \mathbf{W}_s-\frac{1}{2} \int_0^t \mathbf{u}_s^{\top} \mathbf{u}_s \mathrm{~d} s\right) .
$$


Then, by Girsanov's theorem \cite{choe2016girsanov}, $\left\{M_t, t \geqslant 0\right\}$ is an $\left(\mathcal{F}_t, \mathbb{P}\right)$-martingale, and under the new measure $\mathbb{Q}(A) \stackrel{\text { def }}{=} \mathbb{E}\left[M_T \mathrm{I}_A\right]$ for all $A \in \mathcal{F}_T$, the process $\left\{\mathbf{Z}_t, 0 \leqslant\right.$ $t \leqslant T\}$ is a Wiener process. 


It follows that under $\mathbb{Q}$ the process $\left\{\widetilde{\mathbf{S}}_t, 0 \leqslant t \leqslant T\right\}$ is a martingale with respect to $\left\{\mathcal{F}_t, 0 \leqslant t \leqslant T\right\}$, which had to be shown. $\mathbb{Q}$ is called the risk-neutral measure.


Let $\widetilde{V}_t=B_t^{-1} V_t=\psi_t+\boldsymbol{\phi}_t^{\top} B_t^{-1} \mathbf{S}_t=\psi_t+\boldsymbol{\phi}_t^{\top} \widetilde{\mathbf{S}}_t$ be the discounted value of the portfolio of stocks and bonds.



\begin{align*}
\begin{aligned}
\mathrm{d} \widetilde{V}_t=\boldsymbol{\phi}_t^{\top} \mathrm{d} \widetilde{\mathbf{S}}_t=B_t^{-1} \boldsymbol{\phi}_t^{\top} \boldsymbol{\sigma}_t \mathrm{~d} \mathbf{Z}_t
\end{aligned}
\end{align*}


$\mathbb{Q}$ the process $\left\{\tilde{V}_t, 0 \leqslant t \leqslant T\right\}$ is a martingale with respect to $\left\{\mathcal{F}_t, 0 \leqslant t \leqslant T\right\}$. As a consequence,
$$
V_t=B_t \mathbb{E}_{\mathbb{Q}}\left[B_T^{-1} V_T \mid \mathcal{F}_t\right], \quad t \leqslant T .
$$


The payoff at maturity for a call option is $\left(S_T-K\right)^{+}=\max \left\{S_T-K, 0\right\}$ and for a put option is $\left(K-S_T\right)^{+}$. 


Suppose for concreteness that we are dealing with a call option and denote its value at time $t \leqslant T$ by $C_t=C\left(S_t, K, r_t, T-t\right)$, where $T-t$ is the time until maturity. 

 \begin{align*}
\begin{aligned}
C_t=V_t=B_t \mathbb{E}_{\mathbb{Q}}\left[B_T^{-1} C_T \mid \mathcal{F}_t\right], \quad t \leqslant T,
\end{aligned}
\end{align*}

where

\begin{align*}
\begin{aligned}
C_T=V_T=V_0+\int_0^T \psi_t \mathrm{~d} B_t+\int_0^T \boldsymbol{\phi}_t^{\top} \mathrm{d} \mathbf{S}_t .
\end{aligned}
\end{align*}


Consider a call and a put options written on the same non-dividend-paying stock, with the same strike price $K$ and time to maturity $T$. Then their prices $C_0$ and $P_0$ at time $t=0$ are related as follows:


$$
C_0+K e^{-r T}=P_0+S_0
$$

where $S_0$ is the current stock price and $r$ is the continuously compounded riskfree interest rate.


Consider a portfolio consisting of a call option and an amount of cash given by $K e^{-r T}$. At maturity, the value of this portfolio is,

$$
\max \left\{S_T-K, 0\right\}+K=\max \left\{S_T, K\right\}
$$

$$
\max \left\{K-S_T, 0\right\}+S_T=\max \left\{K, S_T\right\}
$$



Option prices provide information about state variables and parameters via the pricing equation. An option price is given by,

$$
C\left(S_t, V_t, \theta\right)=e^{-r(T-t)} \mathbb{E}_t^{\mathbb{Q}}\left[\max \left(S_t-K, 0\right) \mid S_t, X_t, \theta\right]
$$

where the expectation is taken under $\mathbb{Q}$ the risk-neutral probability measure. here we assume that the risk-free rate $r$ is constant. This simplifies by letting $A=\left\{S_T \geq K\right\}$ denote the event that the stock ends in the money. Then the option price is given by:



 \begin{align*}
\begin{aligned}
e^{-r t} \mathbb{E}_t^{\mathbb{Q}}\left(\max \left(S_T-K, 0\right)\right) & =e^{-r t} \mathbb{E}_t^{\mathbb{Q}}\left(S_T \mathbb{I}_A\right)-e^{-r t} K \mathbb{E}\left(\mathbb{I}_A\right) \\
& =e^{-r t} \mathbb{E}_t^{\mathbb{Q}}\left(S_T \mathbb{I}_A\right)-e^{-r t} K \mathbb{P}(A) .
\end{aligned}
\end{align*}

The logarithmic asset price and volatility follow an affine process with $Y_t=\left(\log S_t, V_t\right) \in \mathfrak{R} \times \mathfrak{R}^{+}$satisfying


\begin{align*}
\begin{aligned}
& d Y_t=\left(r-\frac{1}{2} V_t\right) d t+\sqrt{V_t} d B_{1, t} \\
& d V_t=\kappa\left(\theta-V_t\right) d t+\sigma_v \sqrt{V_t} d Z_t
\end{aligned}
\end{align*}

where $Z_t=\rho B_{1, t}+\sqrt{1-\rho^2} B_{2, t}$. The correlation, $\rho$, or so-called leverage effect is important to explain the empirical fact that volatility increases faster as equity prices drop. The parameters $(\kappa, \theta)$ govern the speed of mean reversion and the long-run mean of volatility and $\sigma_v$ measures the volatility of volatility. Under the risk-neutral measure they become $\left(\kappa / \kappa+\lambda_v\right) \theta$ and $\kappa+\lambda_v$ where $\lambda_v$ is the market price of volatility risk.


From affine process theory, the discounted transform,

$$
\psi(u)=e^{-r t} \mathbb{E}\left(e^{u Y_T} \mid Y_t\right)=e^{\alpha(t, u)+u Y_t+\beta(t, u) V_t}
$$
where $\alpha, \beta$ satisfy Riccati equations. 



