f_X(x) & =\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{\ln M_X(t)} e^{-t x} d t \\
& =\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{K_X(t)-t x} dt  ({\text  {Equation }  a})
\end{aligned}
\end{align*}


\section*{The Tail Probability}

$$
\mathbb{P}(X>x)=\int_x^{\infty} f_X(u) d u
$$


\begin{align*}
\begin{aligned}
\mathbb{P}(X>x) & =\int_x^{\infty} \underbrace{\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{K_X(t)-t u} d t}_{\text {Equation } a} d u \\
& =\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} \int_x^{\infty} e^{K_X(t)-t u} d u d t \\
& =\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{K_X(t)}\left(\int_x^{\infty} e^{-t u} d u\right) d t \\
& =\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{K_X(t)}\left[-\frac{e^{-t u}}{t}\right]_x^{\infty} d t \\
& =\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{K_X(t)}\left[0-\left(-\frac{e^{-t x}}{t}\right)\right] d t \\
& =\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} \frac{e^{K_X(t)-t x}}{t} d t
\end{aligned}
\end{align*}


The VaR\footnote{\href{https://en.wikipedia.org/wiki/Expected_shortfall}{VaR}} is an upper-tail probability, which allows us to deduce:


\section*{shortfall integral}

\begin{align*}
\begin{aligned}
& \mathbb{E}(X \mid X>x)=\frac{1}{\mathbb{P}(X>x)} \int_x^{\infty} u f_X(u) d u, \\
& =\frac{1}{\mathbb{P}(X>x)} \int_x^{\infty} u \underbrace{\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{K_X(t)-t u} d t}_{\text {Equation } a} d u, \\
& =\frac{1}{\mathbb{P}(X>x)} \frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{K_X(t)}\left(\int_x^{\infty} u e^{-t u} d u\right) d t, \\
& =\frac{1}{\mathbb{P}(X>x)} \frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{K_X(t)}\left[\left(-\frac{u}{t}-\frac{1}{t^2}\right) e^{-t u}\right]_x^{\infty} d t, \\
& =\frac{1}{\mathbb{P}(X>x)} \frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{K_X(t)}\left[-\left(-\frac{x}{t}-\frac{1}{t^2}\right) e^{-t x}\right] d t \text {, } \\
& =\frac{1}{\mathbb{P}(X>x)} \frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} e^{K_X(t)}\left[\frac{x e^{-t x}}{t}+\frac{e^{-t x}}{t^2}\right] d t \text {, } \\
& =\frac{1}{\mathbb{P}(X>x)}(\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} \frac{e^{K_X(t)-t x}}{t^2} d t+x \underbrace{\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} \frac{e^{K_X(t)-t x}}{t} d t}_{\mathbb{P}(X>x)}) \text {, } \\
& =\frac{1}{\mathbb{P}(X>x)}\left(\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} \frac{e^{K_X(t)-t x}}{t^2} d t+x \mathbb{P}(X>x)\right) \text {, } \\
& =x+\frac{1}{\mathbb{P}(X>x)}\left(\frac{1}{2 \pi i} \int_{-i \infty,(0+)}^{+i \infty} \frac{e^{K_X(t)-t x}}{t^2} d t\right) \text {. }
\end{aligned}
\end{align*}


