\section*{Understanding Diffusion concepts at a more advanced level }


\section*{Concepts of Diffusion Riemannian.}


Consider a solution $u: \mathcal{M} \times[0, T] \rightarrow[0, \infty)$ ,

$$
\frac{\partial u}{\partial t}=\Delta u
$$

with $\int_{\mathcal{M}} u(\cdot, 0) d \mu_g=1$, where $\mu_g$ is the Riemannian \footnote{\href{https://bjlkeng.io/posts/hyperbolic-geometry-and-poincare-embeddings/}{Ricci-Riemann}} volume measure.

$$
\frac{d}{d t} \int_{\mathcal{M}} u(\cdot, t) d \mu_g=\int_{\mathcal{M}} \Delta u d \mu_g=0,
$$

The integral of $u$ over $\mathcal{M}$ remains one for each $t \in[0, T]$, and in particular, $u$ can be viewed as a probability density of a measure $\nu(t)$ defined by $d \nu(t):=u(\cdot, t) d \mu_g$. 


$\nu(t)$ represents the probability distribution of a particle moving on the manifold under Brownian motion, with initial probability distribution $\nu(0)$,


Suppose $g(\tau)$ is a family of Riemannian metrics on $\mathcal{M}$, for $\tau \in$ $[0, T]$. We call a flow of measures $v(\tau)$ a diffusion \cite{chen2023geometric} (representing the probability distribution of a Brownian particle as above) if $d \nu(\tau)=u(\cdot, \tau) d \mu_{g(\tau)}$ with , 

$$
\frac{\partial u}{\partial \tau}=\Delta_{g(\tau)} u-\left(\frac{1}{2} \operatorname{tr} \frac{\partial g}{\partial \tau}\right) u
$$


$\frac{\partial g}{\partial \tau}=2 \operatorname{Ric}(g(\tau))$, $g(\cdot)$ a Ricci flow with respect to a 'reverse' time coordinate $\tau$ (that is, $\tau=C-t$ for some constant $C$ ),

$$
\frac{\partial u}{\partial \tau}=\Delta_{g(\tau)} u-R u
$$


$$
\begin{aligned} 
\frac{d}{d \tau} \int_{\mathcal{M}} d \nu(\tau) \\ = \frac{d}{d \tau} \int_{\mathcal{M}} u(\cdot, \tau) d \mu_{g(\tau)} & =\\\int_{\mathcal{M}}\left(\frac{\partial u}{\partial \tau} d \mu_{g(\tau)}+u \frac{\partial}{\partial \tau} d \mu_{g(\tau)}\right) \\
& =\int_{\mathcal{M}} \Delta_{g(\tau)} u d \mu_{g(\tau)}=0
\end{aligned}
$$


 If $g(\tau)$ is a flow of Riemannian metrics for $\tau \in[a, b]$, and $\nu(\tau)$ is a diffusion (as defined above) then given any $f: \mathcal{M} \times[a, b] \rightarrow \mathbb{R}$ solving $-\frac{\partial f}{\partial \tau}=\Delta_{g(\tau)} f$, 

$$
\frac{d}{d \tau} \int_{\mathcal{M}} f(\cdot, \tau) d \nu(\tau)=0 .
$$


