	Following the study in \cite{AJ}, we further suppose throughout the paper that $K$ in the SVIE \eqref{mu0} satisfies the following assumption.
	\begin{assumption}\label{assume_K}
	$K\in L_{loc}^2(\mathbb{R}_+, \mathbb{R}^{2 \times 2})$ admits a resolvent of the first kind and the components of $K$ satisfy the condition:
	\begin{align}\label{condition_K}
	 \begin{split}
	&  K \in L_{loc}^2(\mathbb{R}_+, \mathbb{R}), \text{ there exists } h \in (0, 2] \text{ such that } \int_0^\epsilon K(t)^2 dt = O(\epsilon^h) \text{ and }\\
	 & \int_0^T (K(t + \epsilon) - K(t))^2dt = O(\epsilon^h) \text{ for every } T < \infty. 
	\end{split}
	\end{align}
	\end{assumption}
 \end{comment}

 \subsection{Useful mathematical property of the model}
	By Theorem 3.4 in \cite{AJ}, the SVIE \eqref{mu0} admits a continuous weak solution for any initial value $\mu(0) \in \mathbb{R}^2$. The following lemma\footnote{For two functions $F$ and $K$, the convolution $F*K$ is defined by
  $F*K(t)=\int_0^t F(s)K(t-s)ds.$ For a kernel $K$, the resolvent, or resolvent of the second kind of $K$, is the kernel $R$ such that $K*R = R*K = K-R$. For a fractional kernel $K(t) = c \frac{t^{\alpha-1}}{\Gamma(\alpha)}$ where $c$ and $\alpha \in (\frac{1}{2}, \frac{3}{2})$ are constants, its resolvent is given by $R(t) = ct^{\alpha -1}E_{\alpha, \alpha}(-ct^\alpha)$. Here, $E_{\alpha, \beta}(z) =  \sum_{n = 0}^\infty \frac{z^n}{\Gamma(\alpha n + \beta )}$ denotes the Mittag–Leffler function.} provides the Laplace--Fourier transform of $\mu$, which ensures the analytical tractability of the proposed mortality model \eqref{mu0}. 
	\begin{lemma}\label{lemma:expmu}
		\citep{AJ} Suppose that $\mu$ follows the SVIE \eqref{mu0} and a constant row vector $f \in (\mathbb{R}^2)^*$. For any $0\leq t \leq T$, assume that $\psi\in L^2([0, T],(\mathbb{R}^2)^*)$ is a solution to the Volterra--Riccati equation $\psi = (f - \psi\Theta + \frac{1}{2}A(\psi))*K$. Then:
		\begin{equation}\label{expmu}
		\mathbb{E}\left[\left.e^{\int_{0}^{T}f \mu(s)ds}\right|\mathcal{F}_t\right] = \exp(Y_t(T)), 
		\end{equation}
		where 
		\begin{align}\label{Y}
		\begin{split}
		Y_t(T) &= Y_0(T) + \int_{0}^{t}\psi(T-s)\sigma(\mu(s))dW(s) - \frac{1}{2}\int_{0}^{t}\psi(T-s)a(\mu(s))\psi(T-s)^\top ds,\\
		Y_0(T) &= \int_{0}^{T}\left[f\mu(0) + \psi(s)(b(s) - \Theta\mu(0)) + \frac{1}{2}\psi(s)a(\mu(0))\psi(s)^\top\right]ds.
		\end{split}
		\end{align}
		In addition, $Y$ has an alternative expression: 
		\begin{equation}\label{Y2}
		Y_t(T) = \int_{0}^{T}f \mathbb{E}\left[\mu(s)|\mathcal{F}_t\right]ds + \frac{1}{2}\int_{t}^{T}\psi(T-s)a(\mathbb{E}[\mu_s|\mathcal{F}_t])\psi(T- s)^\top ds, 
		\end{equation}
		where 
		\begin{equation}\label{expectation:mu}
		\mathbb{E}[\mu(T)|\mathcal{F}_t] = \left(I - \int_{0}^{T}R_\Theta(s)ds\right)\mu_0 + \int_{0}^{T}E_\Theta(T-s)b(s)ds + \int_{0}^{t}E_\Theta(T- s)\sigma(\mu)dW(s),
		\end{equation}
		where $R_\Theta$ is the resolvent of $K\Theta$ and $E_\Theta = K- R_\Theta*K$.
	\end{lemma}

	\subsection{Longevity bond price}

     To mitigate the longevity risk associated with the experienced mortality portfolio, the insurance company  purchases the longevity bonds as the  hedging instrument, which is referenced to the national mortality $\mu_1$. And also, investment in a risk-free bond is allowed.  In this part, we present the setting of the financial market and provide the closed-form expressions for zero-coupon risk-free bond and longevity bond. 


      {We assume  that  financial	 market	 and	 mortality rates	 are	 independent.}  Although empirical studies in literature \citep{CT2007} also document the LRD property of  the interest rate, we assume that the  interest rate $r(\cdot)$ a Markov affine process to focus on the effect of longevity risk. Specifically, $r(\cdot)$ follows the dynamic:
	\begin{equation}\label{interest}
	dr(t)=(b_r -  \theta_r r(t))dt +\sigma_r(r(t))dW_r(t),
	\end{equation}
	where $b_r$ and $\theta_r$ are two positive constants, and $W_r$ is a standard Brownian motion independent of $W$. Furthermore, the variance of the interest rate $\left(\sigma_r(r(t))\right)^2$ linearly depends on $r(t)$ with constant coefficients. Note that LRD of interest rate can be easily incorporated in our framework by modelling $r$ with an affine Volterra process.  


	Let $\mathbb{Q}$ be the pricing measure equivalent to $\mathbb{P}$. The zero-coupon risk-free bond price is given by
    \begin{equation}\label{Bond-expectation}
    \mathcal{B}(t,T) = \mathbb{E}^{\mathbb{Q}}\left[\left.e^{-\int_{t}^{T}r(s)ds}\right|\mathcal{F}_t\right].
    \end{equation}
     The longevity bond is based on the national index.   {Suppose that $l(t)$ is  the  number of survivors from the national population at time $t$. Zero-coupon longevity bond $\mathcal{B}_L(t,T)$ pays $l(T)/l(t)$ at time $T$. As $\hat{\mu}_1$ is the force of mortality for the national population, we have $\frac{l(T)}{l(t)} = \exp\left( -\int_t^T\hat{\mu}_1(s)ds\right)$}.  As the financial market is independent of the   {force of mortality},  the zero-coupon longevity bond admits the following representation:
    \begin{equation}\label{Long-B-expectation}
     \mathcal{B}_L(t,T) =\mathbb{E}^{\mathbb{Q}}\left[\left.e^{-\int_{t}^{T}r(s)+   {\hat{\mu}_1(s)} ds}\right|\mathcal{F}_t\right] 
    =\mathcal{B}(t,T)\mathbb{E}^{\mathbb{Q}}\left[\left.e^{-\int_{t}^{T}  {\hat{\mu}_1(s)} 
 ds}\right|\mathcal{F}_t\right], 
     \end{equation}

	To derive the stochastic dynamics of both $\mathcal{B}(t,T)$ and $\mathcal{B}_L(t,T)$, we specify the pricing measure $\mathbb{Q}$ by using the measure change that is modeled by the Girsanov theorem. Let $\boldsymbol{W} \triangleq (W^\top, W_r)^\top$. The pricing measure $\mathbb{Q}$ is given by
	\begin{equation}
	\frac{d\mathbb{Q}}{d\mathbb{P}}= e^{\int_{0}^{t}\zeta(s)^\top d\boldsymbol{W}(s)-\frac{1}{2}|\zeta(s)|^2ds},\nonumber
	\end{equation} 
	where $\zeta(s) = (\varphi(s)^\top, \vartheta(s))^\top$ with $\varphi:[0, T] \rightarrow \mathbb{R}^2$, and $\vartheta: [0, T] \rightarrow \mathbb{R}$ satisfies Novikov's condition:
	\begin{equation}\label{Novikov}
	\mathbb{E}\left[e^{\frac{1}{2}\int_{0}^{T}\zeta(s)^\top \zeta(s)ds}\right] < \infty. 
	\end{equation}
    Under the pricing measure $\mathbb{Q}$, we have $$dW^{\mathbb{Q}}(t) = dW(t) - \varphi(t)dt, ~ dW_r^{\mathbb{Q}}(t) = dW_r(t) -\vartheta(t)dt.$$  
    Inspired by \cite{WaCW}, we apply an affine retaining transform so that the mortality and interest rates maintain an affine structure under the measure $\mathbb{Q}$, as in \eqref{mu0} and \eqref{interest}. Then, the zero-coupon bond price in \eqref{Bond-expectation} admits a closed-form expression by classical results from transforms of affine diffusion (see Appendix \ref{appendix:affine}). By It\^o's formula, the $\mathbb{P}$-dynamic of the bond price is given by
	\[d\mathcal{B}(t,T) = \mathcal{B}(t,T)(r(t)+\nu_{\mathcal{B}}(t))dt + \mathcal{B}(t,T)\sigma_b(t)dW_r(t),\]
	where  $\nu_{\mathcal{B}}(t) = \vartheta(t)\sigma_b(t)$ for some $\mathcal{F}_t$-adapted volatility rate $\sigma_b(t)$. Examples of $\sigma_b$ under specific settings are presented in Propositions \ref{pro:Vas} and \ref{Pro:CIR} later in this paper. With the affine structure maintained under measure $\mathbb{Q}$, Lemma \ref{lemma:expmu} shows that the zero-coupon longevity bond price in \eqref{Long-B-expectation} also admits a closed-form expression. By using Lemma \ref{lemma:expmu} and It\^o's formula, the longevity bond price $\mathcal{B}_L(t, T)$ satisfies the stochastic differential equation (SDE):
	\[d\mathcal{B}_L(t,T) = \mathcal{B}_L(t,T)(r(t) +   {\hat{\mu}_1(t)} 
+ \nu_{\mathcal{L}}(t))dt + \mathcal{B}_L(t,T)\sigma_l(t)^\top dW(t) +\mathcal{B}_L(t,T)\sigma_bdW_r(t),\]
	where $\nu_{\mathcal{L}}(t) = \nu_{\mathcal{B}}(t) + \varphi(t)^\top\sigma_l(t)$ for a certain $\mathcal{F}_t$-adapted process $\sigma_l(t)$ in $\mathbb{R}^2$.  Under concrete settings, the forms of $\sigma_l$ are derived in Proposition \ref{pro:Vas} and \ref{Pro:CIR} later in this paper. As an amount $\mathcal{B}_L(t,T)$ invested in the longevity bond at time $t$ becomes $e^{-\int_{t}^{\tau}\hat{\mu}_1(s)ds}\mathcal{B}_L(\tau,T)$ at $\tau >t$, the value of holding one unit of the zero-coupon longevity bond $\mathcal{B}_L(t)$ satisfies
	\begin{equation}\label{longevity}
	d\mathcal{B}_L(t,T) = \mathcal{B}_L(t,T)(r(t) + \nu_{\mathcal{L}}(t))dt + \mathcal{B}_L(t,T)\sigma_l(t)^\top dW(t) +\mathcal{B}_L(t,T)\sigma_bdW_r(t).
	\end{equation}
	The vector $\varphi(t)$ is the market price of mortality risk and $\vartheta(t)$ is the market price of the interest rate risk.  In fact, because the longevity bond pricing only involves the national   {force of mortality}  and is not related to the insurer's experienced mortality portfolio, we have $\sigma_l \triangleq (\sigma_{l1}, \sigma_{l2})^\top = (\sigma_{l1}, 0)^\top$.

\begin{remark}
   { The assumption that the financial market and mortality rate  are independent is often used in the literature (see, e.g., \cite{Biffis}) to simplify the modeling framework.  Actually, it is possible to relax this assumption in this paper.  If we consider that the interest rate and force of mortality are correlated, for instance, by considering that $W_r$ is  correlated with $W$, the valuation for the longevity bond would be complicated. In \eqref{Long-B-expectation}, we cannot separate the expectations; however, it is also possible to derive the  closed-form solution by forming the vector $(r, \mu_1)^\top$ as an affine Volterra process and applying  Lemma \ref{lemma:expmu}. }
\end{remark}


    \section{The longevity hedging problem}\label{state-section}
    Consider an insurance company that provides annuities/pension scheme and life insurances to the insurance market. While the insurance company aims to manage the risk generated from $  {\hat{\mu}_2} $, the available hedging vehicle (i.e. the longevity bond) is based on $  {\hat{\mu}_1}$. This further complicates the mathematical treatment of the hedging problem. We use a Poisson process $N_2(t)$ with a stochastic intensity $c_1  {\hat{\mu}_1(s)}$ where $c_1 \in \mathbb{R}_+$  to denote the frequency of life insurance claims experienced by the company. 
    Suppose that $c_2\in \mathbb{R}_+$ is the amount of the pension/annuity   {payment} that the insurer must pay at the initial time. At time $t$, the survival proportion of the population becomes $c_2e^{-\int_{0}^{t}  {\hat{\mu}_2(s)} ds}$. Therefore, the pension annuity net cash outflow is represented by $\pi(t) =  c_2e^{-\int_{0}^{t}  {\hat{\mu}_2(s)} ds}$ in this paper. The insurer's hedging horizon is $T_0$, and the company uses the longevity bond with a maturity time $T> T_0$ as the hedging instrument.

	Let $u_0(t)$, $u_1(t)$, and $u_2(t)$ denote the amounts of investment in a bank account, zero-coupon longevity bond, and zero-coupon risk-free bond, respectively. The wealth process of the insurer is
	\begin{equation}
	\bar{X}(t)=u_0(t)+ u_1(t)+ u_2(t)- \sum_{i=1}^{N_2(t)}z_i-\Pi(t),~ t\in[0,T_0],
	\end{equation}
	where $\Pi(t) = \int_{0}^{t}\pi(s)ds$,  and $\{z_i\}_{i=1}^{\infty}$ denotes the positive independent and identically distributed (iid) insurance claims. Note that the insurer's pension annuity net cash outflow and insurance claims depend on $  {\hat{\mu}_2}$, the insurer's experienced   {force of mortality}.   {In this paper, we consider that the insurer is only looking at one specific cohort  of individuals. In other words,  the individuals are all the same age at time $t$.} 

	We further postulate that the insurance claims $z$ have the  probability density function $g(z)$ on $\mathbb{R}_+$ with finite moments $\mathbb{E}[z], \mathbb{E}[z^2]$ (i.e., $\mathbb{E}[z^2] = \int_{\mathbb{R}_+}z^2g(z)dz< \infty$). For convenience, we use a Poisson random measure to denote the compound Poisson process. Specifically,  $\sum_{i=1}^{N_2(t)}z_i = \int_{0}^{t}\int_{\mathbb{R}_+}zN_2(ds,dz)$, where $N_2(dt , dz)$ is a Poisson random measure on $\Omega\times[0,T_0]\times\mathbb{R}_+$ with the compensator $c_1  {\hat{\mu}_2(t)} g(z)dzdt \triangleq \delta(dz)dt$. We use $F^2(t, T; \mathbb{R})$ to denote the set of all $\{\mathcal{F}_s\}_{s \in[t, T]}$-predictable processes $X(\cdot, \cdot): \Omega\times[t, T]\times\mathbb{R}_+\rightarrow \mathbb{R}$ such that $\mathbb{E}\left[\int_{[t, T]\times\mathbb{R}_+}\|X(s, \cdot)\|^2_{L^2}ds\right] < \infty$, where $\|X(s, z)\|^2_{L^2}$ := $\int_{\mathbb{R}_+}|X(s, z)|^2\delta(dz)$. 
	By setting $\widetilde{N}(dt,dz) = N_2(dt,dz)-\delta(dz)dt$, the insurer's wealth $\bar{X}(t)$ satisfies
	\begin{equation}\label{wealth}
	d\bar{X}(t)= (\bar{X}(t)r(t)+\nu(t)^\top u(t)-\pi(t) - \mathbb{E}[z]c_1  {\hat{\mu}_2(t)})dt + u(t)^\top\sigma_S(t)^\top d\boldsymbol{W}(t)-\int_{\mathbb{R}_+} z\widetilde{N}(dt, dz),
	\end{equation}
	where   {$u(t) = (u_1(t), u_2(t))^\top$}, $\nu(t)=(\nu_{\mathcal{L}}, \nu_{\mathcal{B}})^\top$, and
\begin{equation*}
    \sigma_S(t)^\top = \left(\begin{array}{ccc}
 \sigma_{l1}(t)  & 0 &  \sigma_b(t) \\
    0 & 0 & \sigma_b(t)
\end{array}  \right).
\end{equation*}

	In this paper, we study the problem with respect to the discounted wealth process $X \triangleq e^{-\int_{0}^{t}r(s)ds}\bar{X}(t)$. The objective of an insurer is to minimize
	\begin{align}\label{objective}
	\begin{split}
	J(t, X; u(\cdot)) & = \frac{1}{2}{\rm Var}_t(X(T_0)) - \lambda\mathbb{E}_t[X(T_0)] \\
	& = \frac{1}{2}\mathbb{E}_t[X(T_0)^2] - \frac{1}{2}\mathbb{E}_t^2[X(T_0)] - \lambda\mathbb{E}_t[X(T_0)]
	\end{split}
	\end{align}
	by an admissible control $u$ for $X(t)$ at time $t$, where $\mathbb{E}_t[\cdot] = \mathbb{E}[\cdot|\mathcal{F}_t]$ and the parameter $\lambda$ reflects the insurer's risk aversion level. By \eqref{wealth}, 
	\begin{align}
	\begin{split}\label{Xtilde}
	dX(t) = e^{-\int_{0}^{t}r(s)ds}\left(\nu(t)^\top u(t)-\pi(t) - \mathbb{E}[z]c_1  {\hat{\mu}_2(t)} \right)dt
       + e^{-\int_{0}^{t}r(s)ds}u(t)^\top\sigma_S(t)^\top d\boldsymbol{W}(t)\\ -\int_{\mathbb{R}_+}ze^{-\int_{0}^{t}r(s)ds}\widetilde{N}(dt, dz). 
	\end{split}
	\end{align}

\begin{definition}\label{def1}
$u(\cdot) $ is called an admissible control if $u(\cdot) \in H_\mathcal{F}^2(0,T_0;\mathbb{R}^2, \mathbb{P})$, and if Equation \eqref{Xtilde} admits a unique strong solution $X \in S_\mathcal{F}^2(0,T_0;\mathbb{R}, \mathbb{P})$. 
\end{definition}
\begin{lemma}\label{lemma:E_mu}
Let $\mu$ be the continuous solution to \eqref{mu0}. For any constant $p \geq 2$, there exists a constant $C$ such that
\[\sup_{t\leq T}\mathbb{E}[|\mu_t|^p] \leq C.  \]
\end{lemma}
\begin{proof}
This is a direct consequence of Lemma 3.1 in \cite{AJ} and \eqref{mu0}.
\end{proof}
Under the interest rate model setting in \eqref{interest}, we prove the following Lemma \ref{Lemma:interest} concerning the boundedness property of $r(\cdot)$ in Appendix \ref{appendix:affine}. The general result for the admissibility of the equilibrium control is presented in Theorem \ref{Thm:admissible}.
\begin{lemma}\label{Lemma:interest}
$\sup_{0\leq s \leq T_0}\mathbb{E}\left[e^{-\int_0^s 4r(v)dv}\right] < \infty$ and $\sup_{0\leq s \leq T_0}\mathbb{E}\left[e^{\int_0^s qr(v)dv}\right] < \infty$ for any $q\geq 0$. 
\end{lemma}
\begin{theorem}\label{Thm:admissible}
Suppose that $\pi \in L_\mathcal{F}^4(0, T_0; \mathbb{R}, \mathbb{P})$. 
If $u \in H^2_\mathcal{F}(0, T_0; \mathbb{R}^2, \mathbb{P})$ such that $\nu^\top u\in L_\mathcal{F}^4(0, T_0;  \mathbb{R}, \mathbb{P})$, and $\sigma_S u \in L_\mathcal{F}^4(0, T_0;  \mathbb{R}^3, \mathbb{P})$, then $u$ is an admissible control.
\end{theorem} 
\begin{proof}
    See Appendix \ref{Appendix:Thm1}.
\end{proof}
The variance term of the objective in \eqref{objective} causes a time-inconsistency issue, which means that the optimal hedging strategy derived at the initial time  is dependent  on the initial wealth level and would be sub-optimal at a later time point,  as widely documented in the literature. To overcome the time-inconsistency issue, we adopt the well-received open-loop framework \cite{HJZ2012, HJZ2017} to investigate equilibrium controls. 
\begin{definition}\label{def2}
Let $u^*(\cdot) \in H_\mathcal{F}^2(0,T_0;\mathbb{R}^2, \mathbb{P})$ be a given control and $X^*(\cdot)$ be the corresponding state process. Then, the control $u^*$ is called an equilibrium strategy if for any $t\in [0,T_0]$ and $\epsilon>0$, $\eta \in H_{\mathcal{F}_t}^2(\Omega;\mathbb{R}^2)$, 
\begin{equation}\label{eq:def}
\mathop{ \liminf}\limits_{\epsilon \downarrow 0} \frac{J(t, X^*(t), u^{t,\epsilon, \eta}(\cdot)) - J(t, X^*(t), u^*(\cdot))}{\epsilon} \geq 0,
\end{equation}
where $ u^{t,\epsilon, \eta}(\cdot) = u^*(\cdot) + \eta\boldsymbol{1}_{[t, t+\epsilon)}(\cdot)$.
\end{definition}

The control defined in Definition \ref{def2} is known as an open-loop control form because the control $u^{t,\epsilon, \eta}(\cdot)$ is not presumed to depend on the state process $X$. Instead, it depends on any adapted process $\eta\in H_{\mathcal{F}_t}^2(\Omega;\mathbb{R}^2)$ in the sense of spike variation, embracing the possibility of feedback and closed-loop control forms. This open-loop control definition is necessary for our problem because the state process has LRD (non-Markovian) coefficients. The equilibrium control may depend on the entire historical paths of the coefficients and the state process.

\subsection{Preliminary results}
To derive the equilibrium strategy under Definition \ref{def2}, we adopt the BSDEs approach in \cite{HJZ2012}. 
For any $ t \in [0,T_0]$, we define the adjoint process $ (p^*(s; t), k^*_1(s; t), k^*_2(s, z; t)) \in S_\mathcal{F}^2(t,T_0;\mathbb{R}, \mathbb{P}) \times L_\mathcal{F}^2(t,T_0;\mathbb{R}^3, \mathbb{P}) \times F^2(t,T_0;\mathbb{R})$ in the interval $[t, T_0]$ to be the solution of the following BSDE, with the discount wealth process $X^* \in S_\mathcal{F}^2(0,T_0;\mathbb{R}, \mathbb{P})$ under $u^*$: 
\begin{align}\label{BSDE:p}
\left\{
\begin{array}{lr}
dp^*(s; t) = k_1^*(s;t)^\top d\boldsymbol{W}(s) + \int_{\mathbb{R}_+} k_2^*(s,z;t)\widetilde{N}(ds,dz),\\
p^*(T_0; t) = X^*(T_0) - \mathbb{E}_t[X^*(T_0)] - \lambda. 	\end{array}
\right.
\end{align}
With the adjoint process $ (p^*(s; t), k^*_1(s; t), k^*_2(s, z; t))$ defined above, we have the following theorem to estimation the term $J(t, X^*(t), u^{t, \epsilon,\eta}) -  J(t, X^*(t), u^*)$ in \eqref{eq:def} in Definition \ref{def2}. 
\begin{theorem}\label{Thm:spike}
	For any $t \in [0,T_0]$, $\epsilon>0$ and $\eta \in H_\mathcal{F}^2(\Omega;\mathbb{R}^2)$, let $u^*(\cdot) \in H_\mathcal{F}^2(0,T_0;\mathbb{R}^2, \mathbb{P})$ be a given control and $u^{t,\epsilon, \eta}(\cdot)$ be as defined in Definition \ref{def2}. If $\nu(\cdot) \in H_\mathcal{F}^2(0,T_0;\mathbb{R}^2, \mathbb{P})$ and each component of $\sigma_S^\top\sigma_S$ belongs to $H_\mathcal{F}^2(0, T_0; \mathbb{R}, \mathbb{P})$, then
	\[J(t, X^*(t), u^{t, \epsilon,\eta}) -  J(t, X^*(t), u^*) = \mathbb{E}_t\int_{t}^{t + \epsilon} \left[\langle \Lambda(s; t), \eta_s \rangle +\frac{1}{2} \langle \Phi(s) \eta_s, \eta_s \rangle\right] ds + o(\epsilon),\]
	where
	\begin{equation}\label{Lamtilde}
     \Lambda(s; t) = e^{-\int_{0}^{s}r(v)dv}\nu(s)p^*(s;t) + e^{-\int_{0}^{s}r(v)dv}\sigma_S(s)^\top k_1^*(s; t),
	\end{equation}
	and $\Phi(s) =  e^{-\int_{0}^{s}2r(v)dv}$.
\end{theorem}
\begin{proof}
    See Appendix \ref{Appendix:Thm2}. 
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The following Proposition \ref{Pro:Lam} presents a special form for the process $\Lambda$. By Proposition \ref{Pro:Lam} and Theorem \ref{Thm:spike}, the sufficient and necessary condition for an equilibrium hedging strategy is provided in Proposition \ref{Pro:Lam0}. The proofs mimic those of Propositions 5 and 6 in \cite{WW2021} and hence we omit them here. Although Propositions \ref{Pro:Lam} and \ref{Pro:Lam0} are not the key results of this paper, they are useful in the proofs for our main contributions in the next section.
\begin{pro}\label{Pro:Lam}
	For a given control $u^*$ and the corresponding state process $X^*$, the solution to the BSDE \eqref{BSDE:p} satisfies $k_1^*(s; t_1) = k_1^*(s; t_2)$ and $k_2^*(s,z; t_1) = k_2^*(s,z; t_2)$ for $a.e.~s \geq \max(t_1, t_2)$. Moreover, there exist processes $\Lambda_0$ in $\mathbb{R}^2$ and $\omega \in S^2_\mathcal{F}(t, T_0; \mathbb{R}, \mathbb{P})$  such that
	\[ \Lambda(s; t) =  \Lambda_0(s) + e^{-\int_{0}^{s}r(v)dv}\nu(s)\omega_t. \]
\end{pro}
\begin{pro}\label{Pro:Lam0}
	Let $ (p^*(s; t), k^*_1(s; t), k^*_2(s, z; t)) \in S_\mathcal{F}^2(t,T_0;\mathbb{R}, \mathbb{P}) \times L_\mathcal{F}^2(t,T_0;\mathbb{R}^3, \mathbb{P}) \times F^2(t,T_0;\mathbb{R})$ be the unique solution to the BSDE \eqref{BSDE:p}. Then, $u^*$ is an equilibrium control if and only if
	\begin{equation}\label{Lam}
	\Lambda(t; t) =  e^{-\int_{0}^{t}r(v)dv}\nu(t) p^*(t;t) + e^{-\int_{0}^{t}r(v)dv}\sigma_S(t)^\top k_1^*(t; t) = 0, ~ a.s., ~a.e.,~ t \in [0, T_0].
	\end{equation}
\end{pro}
\subsection{Explicit equilibrium hedging strategies}
\label{Sec:explicit}
We first derive the general solution to the time-consistent hedging problem \eqref{objective}, which involves the solution of a BSDE. Under certain conditions, the general uniqueness result for the equilibrium investment and hedging strategies is provided in Theorem \ref{Thm:unique}.  Under the settings of a deterministic and volatility-driven market price of risks, the BSDE is solved explicitly and the closed-form investment and hedging strategies are derived together with rigorous proofs about their admissibility and uniqueness.

By condition \eqref{Lam}, we derive the general form of the equilibrium strategy in the following. Consider the solution form for $p^*(s; t)$ as
\[p^*(s; t) = X^*(s) + \Gamma_s^{(1)} - \lambda -\mathbb{E}_t[X^*(s) + \Gamma_s^{(1)}], \] 
where $\left(\Gamma^{(1)}, \gamma^{(1)}\right)$ is the solution of the BSDE: 
\begin{equation*}
d\Gamma_s^{(1)} = -F(s)ds + \gamma^{(1)}(s)^\top d\boldsymbol{W}(s), ~ \Gamma^{(1)}(T_0) = 0
\end{equation*}
with $\gamma^{(1)} = (\gamma^{(1)}_1, \gamma^{(1)}_2, \gamma^{(1)}_3)^\top$. 
We suppress the dependence of $s$ when no confusion occurs. Mimicking the procedure in \cite{HJZ2012}, we deduce that
\begin{equation}\label{u*}
u^*(t) = e^{\int_{0}^{t}r(v)dv}\left(\sigma_S(t)^\top\sigma_S(t)\right)^{-1}\left(\lambda\nu(t) - \sigma_S(t)^\top\gamma^{(1)}(t)\right)
\end{equation}
and 
\[F(t) = \nu(t)^\top\left(\sigma_S(t)^\top\sigma_S(t)\right)^{-1}\left(\lambda \nu(t)  -\sigma_S(t)^\top\gamma^{(1)}(t)\right) + e^{-\int_{0}^{t}r(v)dv}\left( - \pi(t) -\mathbb{E}[z]c_1  {\hat{\mu}_2(t)}  \right). \] 
Then, $\Gamma^{(1)}$ satisfies the following BSDE:
\begin{align}\label{BSDE:gamma1}
\left\{
\begin{array}{ll}
d\Gamma^{(1)}_t & = -\Big\{\nu(t)^\top\left(\sigma_S(t)^\top\sigma_S(t)\right)^{-1}\left(\lambda \nu(t)  -\sigma_S(t)^\top\gamma^{(1)}(t)\right) + e^{-\int_{0}^{t}r(v)dv}\big(-\pi(t)\\
 & -\mathbb{E}[z]c_1  {\hat{\mu}_2(t)} \big)\Big\}dt + \gamma^{(1)}(t)^\top d\boldsymbol{W}(t), \\
\Gamma^{(1)}_{T_0} & = 0. 
\end{array}
\right.
\end{align}
We provide a uniqueness result for the general equilibrium control \eqref{u*} as follows. 
\begin{theorem}\label{Thm:unique}
Suppose that the following conditions are satisfied:
\begin{enumerate}[label=(\roman*)]
\item\label{condition1} $\sigma_S(t)\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1}\nu(t) \in H_\mathcal{F}^q(0, T_0; \mathbb{R}, \mathbb{P})$ for any $q > 1$, and
\begin{equation}
    \mathbb{E}\left[\exp\left(C\int_0^{T_0}\left|\sigma_S(s)\left(\sigma_S(s)^\top \sigma_S(s)\right)^{-1}\nu(s)\right|^2ds\right)\right] < \infty
\end{equation}
for a sufficiently large constant $C$.
\item The BSDE \eqref{BSDE:gamma1} admits a unique solution $(\Gamma^{(1)}_t, \gamma^{(1)}(t)) \in S_\mathcal{F}^q(0, T_0; \mathbb{R}, \mathbb{P})\times H_\mathcal{F}^q(0, T_0; \mathbb{R}^3, \mathbb{P})$ for a constant $q \geq 4$, and the $u^*$ in \eqref{u*} satisfies the condition in Theorem \ref{Thm:admissible} such that it is admissible. 
\end{enumerate}
Then, the equilibrium control $u^*$ given in \eqref{u*} is unique. 
\end{theorem}
The proof of Theorem \ref{Thm:unique} is shown in Appendix \ref{Appendix:unique}, where we clarify that $C > 6$ is considered to be sufficiently large in Condition \ref{condition1}.
To derive the closed-form solution for the equilibrium investment and hedging strategies, we want to solve for the BSDE \eqref{BSDE:gamma1} explicitly.


