\subsection{ Deterministic market price of risk}
In this part, we assume that the market prices of risks are deterministic functions of time, which is a common assumption in financial modeling. 
\begin{assumption}\label{assume1}
The magnitudes of the market prices of the interest rate and mortality risk are both continuous deterministic functions. Specifically, $\varphi(s)= (\varphi_1(s), 0)^\top \in \mathbb{R}^2$ and $\vartheta(s)\in \mathbb{R}$, where $\varphi_1$ and $\vartheta$ are bounded deterministic functions.
\end{assumption}
It directly follows from Assumption \ref{assume1} that Novikov's condition \eqref{Novikov} is satisfied.
\subsubsection{Vasicek setting}
In the following, we adopt constant volatilities. Under Assumption \ref{assume_Vasicek}, the interest rate follows the classic Vasicek model and  $\mu_1$ in \eqref{mu1} becomes a Volterra type of Vasicek model.
\begin{assumption}\label{assume_Vasicek}
The volatility matrix of the   {force of mortality} 
$$\sigma(\mu(s)) \equiv \left(\begin{array}{cc}
\sigma_1 & 0\\
0  & \sigma_2
\end{array} \right) \triangleq \sigma_\mu,$$ 
where $\sigma_1, \text{and } \sigma_2$ are two positive constants. The volatility of the interest rate $\sigma(r(s))\equiv \sigma_r$ where $\sigma_r$ is a positive constant.
\end{assumption}
\begin{pro}\label{pro:Vas}
Under Assumption \ref{assume1} and \ref{assume_Vasicek}, $\sigma_l(s)$ in \eqref{longevity} is given by
 $$\sigma_l(s) = (\psi_1(T-s)\sigma_1, 0)^\top$$ 
 where $\psi_1$ solves $\psi_1 = (-1-\psi_1\theta_1)*K_1$; and $\sigma_b(s) = d_1(s)\sigma_r$ where $d_1(s) = \frac{1}{\theta_r}\left(e^{-\theta_r(T-s)} -1\right)$. 
In addition, $\pi(t) \in L_\mathcal{F}^q(0, T_0; \mathbb{R}, \mathbb{P})$ for any $q > 1$.
\end{pro}




To solve the BSDE \eqref{BSDE:gamma1} explicitly, we introduce the pricing measure $\bar{\mathbb{P}}$:
\begin{equation}\label{P_bar}
\frac{d\bar{\mathbb{P}}}{d\mathbb{P}} =  \exp{\left( \int_0^t -(\varphi_1(s), 0, \vartheta(s))d\boldsymbol{W}(s)- \frac{1}{2}(\varphi_1(s)^2 + \vartheta(s)^2)ds \right)}.
\end{equation}
Under the measure $\bar{\mathbb{P}}$, $\bar{\boldsymbol{W}}(t) \triangleq \boldsymbol{W}(t) + \int_0^t (\varphi_1(s), 0, \vartheta(s))^\top ds$ is a standard Brownian motion. We use $\bar{\mathbb{E}}[\cdot]$ to denote the expectation under the measure $\bar{\mathbb{P}}$. 
\begin{theorem}\label{thm:gam_Vas}
Under Assumptions \ref{assume1} and \ref{assume_Vasicek}, the BSDE \eqref{BSDE:gamma1} admits a unique solution $(\Gamma^{(1)}_t, \gamma^{(1)}(t)) \in S_\mathcal{F}^q(0, T_0; \mathbb{R}, \mathbb{P})\times H_\mathcal{F}^q(0, T_0; \mathbb{R}^3, \mathbb{P})$ for any $q > 1$, which is given by
\begin{align*}
\Gamma^{(1)}_t = \int_t^{T_0} \lambda\left( \varphi_1(s)^2 + \vartheta(s)^2 \right) - e^{-\int_{0}^{t}r(v)dv}e^{\bar{d}_0(s, t) + \bar{d}_1(s, t)r(t)}\Bigg( c_2\exp\left(  {\int_0^s - m_2(v) dv + }  Y^1_t(s)\right) \\
+ \mathbb{E}[z]c_1\bar{\mathbb{E}}_t[  {\hat{\mu}_2(s)} ]\Bigg)ds,
\end{align*}
and 
\begin{align*}
  \left(\begin{array}{c}
    \gamma^{(1)}_1(t) \\
    \gamma^{(1)}_2(t)
  \end{array} \right)  = -\int_t^{T_0} e^{-\int_{0}^{t}r(v)dv}e^{\bar{d}_0(s, t) + \bar{d}_1(s, t)r(t)}\Bigg( c_2\exp\left(   {\int_0^s - m_2(v) dv + }  Y^1_t(s)\right)\sigma_\mu\psi(s-t)^\top\\
  + \mathbb{E}[z]c_1\sigma_\mu \left(\begin{array}{c}
     E_\Theta^{21}(s-t) \\
     E_\Theta^{22}(s-t)
  \end{array} \right)\Bigg)ds,
\end{align*}
\begin{align*}
\gamma_3^{(1)} = -\int_t^{T_0}e^{-\int_{0}^{t}r(v)dv}e^{\bar{d}_0(s, t) + \bar{d}_1(s, t)r(t)}\bar{d}_1(s, t)\sigma_r \left( c_2\exp\left(  {\int_0^s- m_2(v) dv + } 
 Y^1_t(s)\right) + \mathbb{E}[z]c_1\bar{\mathbb{E}}_t[  {\hat{\mu}_2(s)} ]\right)ds,
\end{align*}
where $\bar{d}_1(s, t) = \frac{1}{\theta_r}\left(e^{-\theta_r(s -t)}-1 \right)$; $\bar{d}_0(s, t) = \int_t^s(b_r -\sigma_r\vartheta(v)) + \frac{1}{2}\sigma_r^2\bar{d}_1(v, t)^2dv$; $Y^1 _t(s)$ is equivalent to $Y_t(s)$, as defined in \eqref{Y} with $\sigma(\mu(s)) = \sigma_\mu$, $f = (0, -1)$, $W(s)$ replaced by $\bar{W}(s)$, and $\psi$ solving the Volterra--Riccati equation $\psi = ((0, -1) - \psi \Theta)*K$;   {$\bar{\mathbb{E}}_t[\hat{\mu}(s)] = (m_1(s), m_2(s))^\top + \bar{\mathbb{E}}_t[\mu(s)] $ where} $\bar{\mathbb{E}}_t[\mu(s)]$ is given in \eqref{expectation:mu} with $b(s) = (b_1 - \sigma_1\varphi_1(s), b_2)$, $\sigma(\mu(s)) = \sigma_\mu$ and $W(s)$ replaced by $\bar{W}(s)$; and $E_\Theta = \left(\begin{array}{cc}
    E_\Theta^{11} & E_\Theta^{12}  \\
    E_\Theta^{21} & E_\Theta^{22}
\end{array}\right)$ in \eqref{expectation:mu}.
\end{theorem}
\begin{proof}
By calculation,
\begin{align*}
& \nu(t)^\top\left(\sigma_S(t)^\top\sigma_S(t)\right)^{-1}\nu(t) \\
& = (\varphi_1(t)\sigma_{l1}(t)+ \vartheta(t)\sigma_b(t), \vartheta(t)\sigma_b(t))\left(\begin{array}{cc}
   \sigma_b^2 +\sigma_{l1}^2  & \sigma_b^2 \\
   \sigma_b^2  & \sigma_b^2
\end{array} \right)^{-1}\left(\begin{array}{c}
     \varphi_1(t)\sigma_{l1}(t)+ \vartheta(t)\sigma_b(t) \\
      \vartheta(t)\sigma_b(t)
\end{array}\right)\\
& = \varphi_1(t)^2 + \vartheta(t)^2,
\end{align*}
and 
\begin{align*}
\nu(t)^\top\left(\sigma_S(t)^\top\sigma_S(t)\right)^{-1}\sigma_S(t)^\top =  (\varphi_1(t), 0 , \vartheta(t)) \triangleq \xi(t). 
\end{align*} 
Under the measure $\bar{\mathbb{P}}$, the BSDE \eqref{BSDE:gamma1} becomes
\begin{align*}
\left\{
\begin{array}{ll}
d\Gamma^{(1)}_t & = -\left\{\lambda\left( \varphi_1(t)^2 + \vartheta(t)^2 \right) + e^{-\int_{0}^{t}r(s)ds}\left( - \pi(t) -\mathbb{E}[z]c_1  {\hat{\mu}_2(t)} \right)\right\}dt + \gamma^{(1)}(t)^\top d\bar{\boldsymbol{W}}(t), \\
\Gamma^{(1)}_{T_0} & = 0.
\end{array}
\right.
\end{align*}
By Lemmas \ref{lemma:expmu} and \ref{lemma:E_mu}, and Proposition \ref{pro:Vas}, we have
\[e^{-\int_{0}^{t}r(s)ds}\left( - \pi(t) -\mathbb{E}[z]c_1  {\hat{\mu}_2(t)} \right) \in H_\mathcal{F}^{q}(0,T_0;\mathbb{R}, \bar{\mathbb{P}}). \]
for any $q > 1$. By Theorem 5.1 in \cite{EPQ}, there exists a unique solution $ (\Gamma^{(1)}, \gamma^{(1)}) \in S_\mathcal{F}^{q}(0,T_0;\mathbb{R}, \bar{\mathbb{P}}) \times H_\mathcal{F}^{q}(0,T_0;\mathbb{R}^3, \bar{\mathbb{P}})$ for any $q > 1$. 
We denote the $\frac{d\bar{\mathbb{P}}}{d\mathbb{P}}$ in \eqref{P_bar} by $\mathcal{E}_t(-\xi)$. For any constant $q > 1$, there exists a constant $C_1$ such that
\begin{align*}
\mathbb{E}\left[\sup_{0\leq t\leq T_0}|\Gamma_t^{(1)}|^q \right] & = \bar{\mathbb{E}}\left[ \sup_{0\leq t\leq T_0}|\Gamma_t^{(1)}|^q \mathcal{E}_{T_0}^{-1}(\xi)\right]\leq \left\{\bar{\mathbb{E}}\left[\sup_{0\leq t\leq T_0}|\Gamma_t^{(1)}|^{2q} \right]\mathbb{E}[\mathcal{E}_{T_0}^{-1}(\xi)] \right\}^{\frac{1}{2}}\\
& \leq C_1 \left\{\mathbb{E}\left[\mathcal{E}_{T_0}(2\xi) \right]\mathbb{E}\left[\exp\left(3 \int_0^{T_0}|\xi(s)|^2ds\right) \right] \right\}^{\frac{1}{4}} < \infty. 
\end{align*}
Therefore, $\Gamma^{(1)} \in S_\mathcal{F}^{q}(0,T_0;\mathbb{R}, \mathbb{P})$ for any $q > 1$. Similarly, we have $\gamma^{(1)} \in H_\mathcal{F}^{q}(0,T_0;\mathbb{R}^3, \mathbb{P})$ for any $q > 1$. 
Furthermore, 
\begin{align*}
\Gamma^{(1)}_t & = \int_t^{T_0} \bar{\mathbb{E}}_t\left[\lambda\left( \varphi_1(s)^2 + \vartheta(s)^2 \right) -  e^{-\int_{0}^{s}r(v)dv}\left( \pi(s)  + \mathbb{E}[z]c_1  {\hat{\mu}_2(s)}\right) \right]ds \\
& = \int_t^{T_0} \lambda\left( \varphi_1(s)^2 + \vartheta(s)^2 \right) - \bar{\mathbb{E}}_t\left[e^{-\int_{0}^{s}r(v)dv} \right]\left( c_2\bar{\mathbb{E}}_t\left[e^{-\int_{0}^{s}  {\hat{\mu}_2(v)}dv} \right] + \mathbb{E}[z]c_1\bar{\mathbb{E}}_t[  {\hat{\mu}_2(s)}]\right)ds.
\end{align*}
Under the measure $\bar{\mathbb{P}}$,   $\mu$ follows
\begin{align*}
\mu(t)= \mu(0) + \int_0^t K(t-s)(b(s) -\Theta\mu(s))ds + \int_0^t K(t-s)\sigma_\mu d\bar{W}(s),
\end{align*}
where $b(s) = (b_1 - \sigma_1\varphi_1(s), b_2)$, $K = \left( \begin{array}{cc}
K_1 & 0\\
\beta_1 K_1 & K_2
\end{array} \right)$, and $\Theta = \left(\begin{array}{cc}
\theta_1 & 0\\
\beta_2 & \theta_2
\end{array}\right)$, which maintains the affine structure. By Lemma \ref{lemma:expmu}, we have
\[\bar{\mathbb{E}}_t\left[e^{-\int_{0}^{s}\mu_2(v)dv}\right] = \exp(  {\int_0^s - m_2(v) dv + } Y^1_t(s)).\]
The interest rate under the measure $\bar{\mathbb{P}}$ follows the dynamic:
\[ dr(t) = (b_r - \sigma_r\vartheta(t) - \theta_r r(t))dt + \sigma_rd\bar{W}_r(t).\]
By Appendix \ref{appendix:affine}, $ \bar{\mathbb{E}}_t\left[e^{-\int_{0}^{s}r(v)dv} \right] = e^{-\int_{0}^{t}r(v)dv}e^{\bar{d}_0(s, t) + \bar{d}_1(s, t)r(t)}$. The expression for $(\Gamma^{(1)}, \gamma^{(1)})$ follows.
\end{proof}


\begin{cor}\label{cor:Vas}
  Under Assumption \ref{assume1} and \ref{assume_Vasicek},  the unique admissible equilibrium investment and hedging strategies $u^* = (u^*_1, u^*_2)^\top$ is given by 
  \begin{align*}
   u^*_1(t) & =   e^{\int_0^tr(s)ds}\left(  \frac{\lambda\varphi_1(t)}{\psi_1(T-t)\sigma_1} - \frac{\gamma^{(1)}_1(t)}{\psi_1(T-t)\sigma_1}\right) \label{u1*Vas} \\
   u^*_2(t) & = e^{\int_0^tr(s)ds}\left( - \frac{\lambda\varphi_1(t)}{\psi_1(T-t)\sigma_1} + \frac{\lambda\vartheta(t)}{d_1(t)\sigma_r}+\frac{1}{\psi_1(T-t)\sigma_1}\gamma^{(1)}_1(t) - \frac{1}{d_1(t)\sigma_r}\gamma^{(1)}_3(t)\right)
  \end{align*}
\begin{comment}
\begin{align*}
u^*(t) = e^{\int_0^tr(s)ds}\left(\lambda\left(\begin{array}{c}
   \frac{\varphi_1(t)}{\psi_1(T-t)\sigma_1}\\
     - \frac{\varphi_1(t)}{\psi_1(T-t)\sigma_1} + \frac{\vartheta(t)}{d_1(t)\sigma_r}
\end{array}\right) -  \left(\begin{array}{c}
    \frac{1}{\psi_1(T-s)\sigma_1}\gamma^{(1)}_1(t) \\
     -\frac{1}{\psi_1(T-s)\sigma_1}\gamma^{(1)}_1(t) + \frac{1}{d_1(t)\sigma_r}\gamma^{(1)}_3(t)
\end{array} \right) \right),
\end{align*}
\end{comment}
where $\psi_1$ solves $\psi_1 = (-1-\psi_1\theta_1)*K_1$, $d_1(t) = \frac{1}{\theta_r}\left(e^{-\theta_r(T-t)} -1\right)$, and  $\gamma^{(1)}_1$ and $\gamma^{(1)}_3$ are given in Theorem \ref{thm:gam_Vas}.
\end{cor}
\begin{proof}
    As $\sigma_S(t)\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1}\nu(t)= (\varphi_1(t), 0 , \vartheta(t))^\top$ is 
a bounded deterministic function in this case, condition \ref{condition1} in Theorem \ref{Thm:unique} is satisfied. By calculation, the expression for $u^*$ folows. 
By Lemma \ref{Lemma:interest} and H\"older's inequality, it holds that $u^* \in H_\mathcal{F}^2(0, T_0; \mathbb{R}^2, \mathbb{P})$. Similarly, we have $\nu^\top u^*\in L_\mathcal{F}^4(0, T_0; \mathbb{R}, \mathbb{P})$ and $\sigma_S u^* \in L_\mathcal{F}^4(0, T_0; \mathbb{R}^3, \mathbb{P})$, then $u^*$ is a unique admissible control. 
\end{proof}

 As our problem has LRD property, the equilibrium hedging strategy $u^*$ in Corollary \ref{cor:Vas} naturally depends on the entire historical life tables of the nation. Most of the functions there are time deterministic functions and depened on the model parameters, except for $\gamma_1^{(1)}$ and $\gamma_3^{(1)}$. The $\gamma_1^{(1)}$ and $\gamma_3^{(1)}$ defined in Theorem \ref{thm:gam_Vas} appear as functionals of $Y^1_t(\cdot)$, which is a collection of the historical paths of $\mu_1$ and depends on the state process $X_t$. In other words, the equilibrium hedging strategy is not a function on the state process $X$ alone but the historical path of the national death data. As the open-loop control framework embraces feedback and closed-loop controls as special cases, this funding justifies the suboptimality of them for our application.

In Corollary \ref{cor:Vas},  the closed-form solution of the unique admissible strategy is provided. We further investigate the effects of incorporation LRD property and cointegration.  The effect of cointegration is mainly reflected in the term $c_2\exp\left(  {\int_0^s m_2(v) dv + } Y^1_t(s)\right)\sigma_\mu\psi(s-t)^\top
  + \mathbb{E}[z]c_1\sigma_\mu \left(\begin{array}{c}
     E_\Theta^{21}(s-t) \\
     E_\Theta^{22}(s-t)
  \end{array} \right)$ in the expression of $\left(\begin{array}{c}
    \gamma^{(1)}_1(t) \\
    \gamma^{(1)}_2(t)
  \end{array} \right)$. Indeed, the function $\psi$ admits an explicit solution
  $\psi = (0 , -1)*E_\Theta$. In the following, we provide the explicit form for $E_\Theta$.

\begin{pro}\label{pro:RB}
$E_\theta$ admits the form
\begin{align}
    E_\Theta = \left(\begin{array}{cc} 
    \frac{1}{\theta_1}R_{1\theta_1} & 0 \\
    \frac{\beta_1}{\theta_1}R_{1\theta_1} -(\frac{\beta_1}{\theta_1} + \frac{\beta_2}{\theta_1\theta_2})R_{2\theta_2}*R_{1\theta_1} & \frac{1}{\theta_2}R_{2\theta_2}
\end{array} \right),
\end{align}
where $R_{1\theta_1}$ and $R_{2\theta_2}$ are the resolvents for $\theta_1 K_1$ and $\theta_2 K_2$, respectively.
\end{pro} 

By Proposition \ref{pro:RB}, we can alternatively express $\gamma_1^{(1)}$ as follows. 
\begin{align*}
  \gamma_1^{(1)}(t) =  \sigma_1 e^{-\int_{0}^{t}r(v)dv} \int_t^{T_0} e^{\bar{d}_0(s, t) + \bar{d}_1(s, t)r(t)}\Bigg(c_2\exp\left(  {\int_0^s m_2(v) dv + }  Y^1_t(s)\right)\int_0^{s-t}E_\Theta^{21}(u)du \\
  -\mathbb{E}[z]c_1E_\Theta^{21}(s-t)\Bigg)ds,
\end{align*}
where $E_\Theta^{21} =  \frac{\beta_1}{\theta_1}R_{1\theta_1} -(\frac{\beta_1}{\theta_1} + \frac{\beta_2}{\theta_1\theta_2})R_{2\theta_2}*R_{1\theta_1}$. It is then clear that the cointegration and correlation affect the equilibrium hedging  strategy through the values of $\beta_1$ and $\beta_2$ in $E_\Theta^{21}$. In our model setting, the coefficient $\beta_1$ is associated with both cointegration and correlation between $\mu_1$ and $\mu_2$, and $\beta_2$ only contributes to the cointegration. When $\mu_1$ and $\mu_2$ are independent, we have $\beta_1 =\beta_2 = 0$ and $E_\Theta^{21} = 0$ so that $\gamma_1^{(1)} = 0$. The equilibrium hedging strategy $u_1^*$ in 
\eqref{u1*Vas}  reduces to  
\[ u^*_1(t) =   e^{\int_0^tr(s)ds} \frac{\lambda\varphi_1(t)}{\psi_1(T-t)\sigma_1},\]
where $\psi_1$ is defined in Corollary \ref{cor:Vas}.

By setting $H_1 = H_2 = \frac{1}{2}$, we have $K_1 = K_2 \equiv 1$ and recover the equilibrium hedging strategy under the Markovian model. Hence, the effect of LRD property on the equilibrium strategy is reflected by the terms $\psi_1$ and $\gamma_1^{(1)}$ in \eqref{u1*Vas}. Note that $\psi_1 = \frac{1}{\theta_1}(e^{-\theta_1 t} -1)$ under the Markovian case. Therefore, the LRD property primarily adjusts $E_\Theta$. In fact, the term $\exp(Y_t^1)$ is influenced by the related $\psi$ through $E_\Theta$. Under the Markovain model,
 \[E_\Theta^{21}(t) = \beta_1 e^{-\theta_1 t} - \frac{\beta_1 \theta_2 + \beta_2}{\theta_2 -\theta_1}\left(e^{-\theta_1 t} - e^{-\theta_2 t}\right). \]
The direct comparison shows that the LRD adjustment on $E_\Theta^{21}$ reads
\begin{align*}
   \frac{\beta_1}{\theta_1}R_{1\theta_1} -(\frac{\beta_1}{\theta_1} + \frac{\beta_2}{\theta_1\theta_2})R_{2\theta_2}*R_{1\theta_1} - \beta_1 e^{-\theta_1 t} + \frac{\beta_1 \theta_2 + \beta_2}{\theta_2 -\theta_1}\left(e^{-\theta_1 t} - e^{-\theta_2 t}\right). 
\end{align*}


\subsection{Volatility-driven market price of risk}
Another consideration is that the market prices of risks are related to their volatility. In this part of the paper, we investigate the hedging strategy under the following assumption.
\begin{assumption}\label{assume2}
The market prices of mortality and interest risks are related to their volatility. Specifically, $\varphi(s) = \sigma(\mu(s))(\widetilde{\varphi}_1, 0)^\top$ and $\vartheta(s) = \widetilde{\vartheta} \sigma_r(r(s))$, where $\widetilde{\varphi}_1$ and $\widetilde{\vartheta}$ are constant values.
\end{assumption} 
\subsubsection{CIR setting}
\begin{assumption}\label{assume_CIR}
The volatility matrix of the   {force of mortality}  $$\sigma(\mu(s)) = \left(\begin{array}{cc}
\widetilde{\sigma}_1\sqrt{\mu_1(s)} & 0\\
0  & \widetilde{\sigma}_2\sqrt{\mu_2(s)}
\end{array} \right)$$ with constant values $\widetilde{\sigma}_1$ and $\widetilde{\sigma}_2$. The volatility of the interest rate $\sigma_r(r(s)) = \widetilde{\sigma}_r\sqrt{r(s)}$ for a positive constant $\widetilde{\sigma}_r$. 
\end{assumption}
Further, under the CIR setting, we make the following assumption.
\begin{assumption}\label{assume:expmu}
\begin{equation}\label{condition:expmu1}
\mathbb{E}\left[\exp\left(C\int_0^{T_0}\mu_1(s)ds\right)\right] < \infty    
\end{equation}
for a sufficiently large constant $C$, and $\sup_{0\leq t \leq T_0}\mathbb{E}\left[e^{-16\int_0^t\mu_2(s)ds}\right] < \infty$.
\end{assumption}
Under Assumption \ref{assume:expmu}, Novikov's condition in \eqref{Novikov} is satisfied and $\pi \in L_\mathcal{F}^{16}(0, T_0; \mathbb{R}, \mathbb{P})$.
Under the CIR setting in Assumption \ref{assume_CIR},     {$\mu$}  in \eqref{mu0} becomes
\begin{align}
\mu_1(t) & = \mu_1(0) + \int_{0}^{t}K_1(t-s)(b_1 - \theta_1 \mu_1(s))ds + \int_{0}^{t}K_1(t-s)\widetilde{\sigma}_1\sqrt{\mu_1(s)}dW_1(s),\label{mu1CIR}\\
\mu_2(t) & = \mu_2(0) + \int_{0}^{t}\beta_1 K_1(t-s)(b_1 - \theta_1 \mu_1(s))ds  + \int_0^tK_2(t-s)(b_2 - \beta_2 \mu_1(s) - \theta_2 \mu_2(s))ds \nonumber \\
& + \int_{0}^{t}\beta_1 K_1(t-s)\widetilde{\sigma}_1\sqrt{\mu_1(s)}dW_1(s) + \int_0^t K_2(t-s)\widetilde{\sigma}_2\sqrt{\mu_2(s)} dW_2(s); \label{mu2CIR}
\end{align}
The interest rate follows 
\[	dr(t)=(b_r -  \theta_r r(t))dt +\widetilde{\sigma}_r \sqrt{r(s)} dW_r(t).\]
\begin{pro}\label{Pro:CIR}
Under Assumptions \ref{assume2}, \ref{assume_CIR}, and \ref{assume:expmu}, we have
$$\sigma_l(s)  =  \left(\psi'_1(T-s)\widetilde{\sigma}_1\sqrt{\mu_1(s)},~ 0 \right)^\top. $$
where $\psi'_1$ solves the Volterra--Riccati equation $\psi'_1 = (-1 - (\theta_1 - \widetilde{\varphi}_1\widetilde{\sigma}_1^2)\psi'_1+ \frac{1}{2}\widetilde{\sigma}_1^2(\psi'_1)^2)*K_1$.
In addition, $\sigma_b(s) = d'_1(s)\widetilde{\sigma}_r \sqrt{r(s)}$ with $d'_1( s) = \frac{1}{\theta_r-\widetilde{\vartheta}\widetilde{\sigma}_r^2}\left(e^{-(\theta_r-\widetilde{\vartheta}\widetilde{\sigma}_r^2)(T-s)} -1\right)$.
\end{pro}

To present the closed-form solution to BSDE \eqref{BSDE:gamma1} explicitly, we introduce the pricing measure $\widetilde{\mathbb{P}}$ as follows.
 $$\frac{d\widetilde{\mathbb{P}}}{d\mathbb{P}} =  \exp{\left( \int_0^t -(\widetilde{\varphi}_1\widetilde{\sigma}_1\sqrt{\mu_1(s)}, 0, \widetilde{\vartheta}\widetilde{\sigma}_r\sqrt{r(s)})d\boldsymbol{W}(s)- \frac{1}{2}(\widetilde{\varphi}_1^2\widetilde{\sigma}_1^2\mu_1(s) + {\widetilde{\vartheta}}^2\widetilde{\sigma}_r^2 r(s))ds \right)}.$$
 $\widetilde{\boldsymbol{W}}(t) \triangleq \boldsymbol{W}(t) + \int_0^t (\widetilde{\varphi}_1\widetilde{\sigma}_1\sqrt{\mu_1(s)}, 0, \widetilde{\vartheta}\widetilde{\sigma}_r\sqrt{r(s)})^\top ds$ is a standard Brownian motion under measure $\widetilde{\mathbb{P}}$. Let $\widetilde{\mathbb{E}}[\cdot]$ denote the expectation under the measure $\widetilde{\mathbb{P}}$. 
\begin{theorem}\label{solutionCIR}
Under Assumptions \ref{assume2}, \ref{assume_CIR}, and \ref{assume:expmu},  the BSDE \eqref{BSDE:gamma1} admits a unique solution $(\Gamma^{(1)}_t, \gamma^{(1)}(t)) \in S_\mathcal{F}^4(0, T_0; \mathbb{R}, \mathbb{P})\times H_\mathcal{F}^4(0, T_0; \mathbb{R}^3, \mathbb{P})$ given by
\begin{align*}
\Gamma^{(1)}_t = \int_t^{T_0} \lambda \left(\widetilde{\varphi}_1^2\widetilde{\sigma}_1^2\widetilde{\mathbb{E}}_t[  {\hat{\mu}_1(s)}] + \widetilde{\vartheta}^2\widetilde{\sigma}_r^2 \widetilde{\mathbb{E}}_t[r(s)]\right) - e^{-\int_{0}^{t}r(v)dv}e^{\widetilde{d}_0(s, t) + \widetilde{d}_1(s, t)r(t)}\\
\bigg( c_2\exp\left(  {\int_0^s - m_2(v) dv + }  Y^2_t(s)\right)  + \mathbb{E}[z]c_1\widetilde{\mathbb{E}}_t[  {\hat{\mu}_2(s)}]\bigg)ds,
\end{align*}
and 
\begin{align*}
  \left(\begin{array}{c}
    \gamma^{(1)}_1(t) \\
    \gamma^{(1)}_2(t)
  \end{array} \right) = \int_t^{T_0}\lambda\widetilde{\varphi}_1^2\widetilde{\sigma}_1^2\left(\begin{array}{c}
      E_{B_1}(s-t)\widetilde{\sigma}_1\sqrt{\mu_1(t)}   \\
      0 
  \end{array}\right) -e^{-\int_{0}^{t}r(v)dv}e^{\widetilde{d}_0(s, t) + \widetilde{d}_1(s, t)r(t)}\\
  \Bigg( c_2\exp\left(Y^2_t(s)\right)\sigma(\mu(t))\widetilde{\psi}(s-t)^\top
  + \mathbb{E}[z]c_1\left(\begin{array}{c}
      \widetilde{\sigma}_1\sqrt{\mu_1(s)}E_{\widetilde{\Theta}}^{21}(s-t) \\
      \widetilde{\sigma}_2\sqrt{\mu_2(s)}E_{\widetilde{\Theta}}^{22}(s-t)
  \end{array} \right)\Bigg)ds,
\end{align*}
\begin{align*}
\gamma_3^{(1)}(t) = \int_t^{T_0}\lambda \widetilde{\vartheta}^2\widetilde{\sigma}_r^2 e^{-\theta_r(s-t)}\widetilde{\sigma}_r\sqrt{r(t)} -e^{-\int_{0}^{t}r(v)dv}e^{\widetilde{d}_0(s, t) + \widetilde{d}_1(s, t)r(t)}\widetilde{d}_1(s, t)\widetilde{\sigma}_r\sqrt{r(t)}\\
\Bigg(c_2\exp\left(  {\int_0^s - m_2(v) dv + } 
 Y^2_t(s)\right)
+ \mathbb{E}[z]c_1\widetilde{\mathbb{E}}_t[  {\hat{\mu}_2(s)}]\Bigg)ds,
\end{align*}
where $B_1 = -\theta_1$;  $Y^2_t(s)$ is equivalent to $Y_t(s)$ in \eqref{Y} and  $\widetilde{\mathbb{E}}_t[\hat{\mu}_2(s)] = m_2(s) + \widetilde{\mathbb{E}}_t[\mu_2(s)]$ where    $\widetilde{\mathbb{E}}_t[\mu_2(s)]$ is as defined in \eqref{expectation:mu}, with $f = (0, -1)$, $b(s) = (b_1, b_2)$, $\Theta$ replaced by $\widetilde{\Theta} \triangleq \left(\begin{array}{cc}
\theta_1 + \widetilde{\varphi}_1\widetilde{\sigma}_1^2 & 0\\
\beta_2 & \theta_2
\end{array}\right)$, $W(s)$ replaced by $\widetilde{W}(s)$, and $\psi$ replaced by $\widetilde{\psi}$, which solves the Volterra--Riccati equation $\widetilde{\psi} = ((0, -1) - \widetilde{\psi}\widetilde{\Theta} + \frac{1}{2}(\widetilde{\sigma}_1^2\widetilde{\psi}_1^2, \widetilde{\sigma}_2^2\widetilde{\psi}_2^2))*K$; $E_\Theta$ replaced by $E_{\widetilde{\Theta}} \triangleq \left(\begin{array}{cc}
    E_{\widetilde{\Theta}}^{11} & E_{\widetilde{\Theta}}^{12}  \\
    E_{\widetilde{\Theta}}^{21} & E_{\widetilde{\Theta}}^{22}
\end{array}\right)$ in \eqref{expectation:mu}.
\end{theorem}
\begin{proof}
The proof is similar to the proof of Theorem \ref{thm:gam_Vas} and is thus omitted.
\end{proof}

\begin{cor}
    Under Assumption \ref{assume2}, \ref{assume_CIR}, and \ref{assume:expmu},  the unique admissible equilibrium investment and hedging strategies $u^*$ is given by
    \begin{align}
       u^*_1(t) & =  e^{\int_0^tr(s)ds}\left(\frac{\lambda\widetilde{\varphi}_1}{\psi'_1(T-t)} - \frac{\gamma^{(1)}_1(t)}{\psi'_1(T-t)\widetilde{\sigma}_1\sqrt{\mu_1(t)}} \right), \\
       u^*_2(t) & =  e^{\int_0^tr(s)ds}\left(  - \frac{\lambda \widetilde{\varphi}_1}{\psi'_1(T-t)} + \frac{\lambda\widetilde{\vartheta}}{d'_1( t)} + \frac{\gamma^{(1)}_1(t)}{\psi'_1(T-t)\widetilde{\sigma}_1\sqrt{\mu_1(t)}} - \frac{\gamma^{(1)}_3(t)}{d'_1(t)\widetilde{\sigma}_r \sqrt{r(t )}}\right),
    \end{align}
    where  $\psi'_1$ solves $\psi'_1 = (-1 - (\theta_1 - \widetilde{\varphi}_1\widetilde{\sigma}_1^2)\psi'_1+ \frac{1}{2}\widetilde{\sigma}_1^2(\psi'_1)^2)*K_1$, $d'_1( s) = \frac{1}{\theta_r-\widetilde{\vartheta}\widetilde{\sigma}_r^2}\left(e^{-(\theta_r-\widetilde{\vartheta}\widetilde{\sigma}_r^2)(T-s)} -1\right)$,  and $\gamma^{(1)}_1$ and $\gamma^{(1)}_3$ are given in Theorem \ref{solutionCIR}.
\end{cor}
Under the volatility-driven market price of risk and the CIR setting, Theorem \ref{solutionCIR} provides the unique equilibrium hedging strategy under the condition in Assumption \ref{assume:expmu}. From the proof, $C > \max\{\frac{1}{2}\widetilde{\varphi}_1\widetilde{\sigma}_1^2, 8\}$ in Assumption \ref{assume:expmu} is sufficient for Novikov's condition \eqref{Novikov}, the admissibility and uniqueness of the control. 
\section{Numerical study}
\label{Sec:numerical}
In this section, we numerically examine the effects of cointegration and the LRD property of the   {force of mortality}  on longevity hedging strategies. The deterministic market price of risk and the Vasicek setting in Assumptions \ref{assume1} and \ref{assume_Vasicek} are considered.  Then,   {the dynamic of $\mu$  is given by} 
\begin{align}\label{Vas_num}
\begin{split}
\mu_1(t) & = \mu_1(0) + \int_{0}^{t}\frac{(t-s)^{H_1 -\frac{1}{2}}}{\Gamma(H_1+\frac{1}{2})}(b_1 - \theta_1 \mu_1(s))ds + \int_{0}^{t}\frac{(t-s)^{H_1 -\frac{1}{2}}}{\Gamma(H_1+\frac{1}{2})}\sigma_1dW_1(s) \\ 
\mu_2(t) & = \mu_2(0) + \beta_1\int_{0}^{t} \frac{(t-s)^{H_1 -\frac{1}{2}}}{\Gamma(H_1+\frac{1}{2})}(b_1 - \theta_1 \mu_1(s))ds  + \int_0^t \frac{(t-s)^{H_2 -\frac{1}{2}}}{\Gamma(H_2+\frac{1}{2})}(b_2-\beta_2\mu_1(s) -\theta_2 \mu_2(s))ds \\
    & + \beta_1 \int_{0}^{t} \frac{(t-s)^{H_1 -\frac{1}{2}}}{\Gamma(H_1+\frac{1}{2})}\sigma_1dW_1(s) + \int_0^t \frac{(t-s)^{H_2 -\frac{1}{2}}}{\Gamma(H_2 +\frac{1}{2})}\sigma_2 dW_2(s).
\end{split}
\end{align}
The interest rate follows the dynamic:
\begin{equation}\label{interest_num}
dr(t) = (b_r - \theta_r r(t))dt + \sigma_rdW_r(t).
\end{equation}


