\begin{appendices} 
	\section{Transformation of affine Markovian processes}
	\label{appendix:affine}
	Suppose that a $\mathcal{F}_t$-adapted Markovian process $r(\cdot)\in \mathbb{R}$ is the strong solution to the SDE:
	$$dr(t)=(b_r(t) - \theta_r r(t))dt +\sigma_r(r(t))dW_r(t), $$
	where $b_r(t)\in \mathbb{R}$ is a bounded deterministic function,  $\theta_r$ is a constant, and $W_r$ is a standard Brownian motion. Suppose that $\sigma_r(r(t))^2 = a_r^0 + a_r^1r(t)$ for some constants $a_r^0$ and $a_r^1$. 
    From the study in \cite{DPS}, we have
	\[\mathbb{E}\left[\left.e^{\int_{t}^{T}-r(s)ds}\right|\mathcal{F}_t\right]= e^{d_0(t)+ d_1(t)r(t)},\]
	where the functions $ d_0(\cdot)\doteq d_0(\cdot, T)$ and $d_1(\cdot)\doteq d_1(\cdot, T)$ solve the following ordinary differential equations:
	\[\dot{d_1}(t)= 1 + \theta_rd_1(t) - \frac{1}{2}a^1_rd_1(t)^2,\]
	\[\dot{d_0}(t)= -b_r(t) d_1(t)-\frac{1}{2}a_r^0d_1(t)^2,\]
	with boundary conditions $d_1(T)=0$ and $d_0(T)= 0$.



\section{Proofs}
\subsection{Proof of Proposition \ref{pro:Hurst}}
\label{appendix:Hurst}
\begin{proof}
    Define  a sequence of stopping time as $\tau_n := \inf\{t > 0; \mu_1(t)>n, \mu_2(t)>n\}$ for $n = 1, 2, \cdots$.  For each $n$, we introduce the following dynamic:
    \begin{align*}
        \mu_2^n(t) & = \mu_2(0) + \int_{0}^{t}\beta_1 K_1(t-s)(b_1 - \theta_1 \mu_1(s))\mathbbm{1}_{\{s< \tau_n\}}ds  \\
       & + \int_0^tK_2(t-s)(b_2 - \beta_2 \mu_1(s) - \theta_2 \mu_2(s))\mathbbm{1}_{\{s< \tau_n\}}ds \nonumber \\
& + \int_{0}^{t}\beta_1 K_1(t-s)\sigma_1(\mu_1(s))\mathbbm{1}_{\{s< \tau_n\}}dW_1(s) + \int_0^t K_2(t-s)\sigma_2(\mu_2(s)) \mathbbm{1}_{\{s< \tau_n\}}dW_2(s). 
    \end{align*}
For any $p > 2$ and $0 \leq s < t \leq  T$, 
\begin{align*}
    |\mu_2^n(t)-\mu_2^n(s)|^p &\leq C\Bigg[\left| \int_{s}^{t}K_1(t-u)(b_1 - \theta_1 \mu_1(u))\mathbbm{1}_{\{u< \tau_n\}}du \right|^p \\
    & + \left|\int_0^s(K_1(t-u) - K_1(s-u))(b_1 - \theta_1 \mu_1(u))\mathbbm{1}_{\{u< \tau_n\}}du\right|^P \\
    & + \left| \int_s^tK_2(t-u)(b_2 - \beta_2 \mu_1(u) - \theta_2 \mu_2(u))\mathbbm{1}_{\{u < \tau_n\}}du \right|^p\\
    & + \left|\int_0^s(K_2(t-u) - K_2(s-u))(b_2 - \beta_2 \mu_1(u) - \theta_2 \mu_2(u))\mathbbm{1}_{\{u < \tau_n\}}du \right|^p \\
    & + \left|\int_s^t K_1(t-u)\sigma_1(\mu_1(u))\mathbbm{1}_{\{u< \tau_n\}}dW_1(u) \right|^p \\
    & + \left|\int_0^s(K_1(t-u)-K_1(s-u))\sigma_1(\mu_1(u))\mathbbm{1}_{\{u< \tau_n\}}dW_1(u)\right|^p\\
    & + \left|\int_s^t  K_2(t-u)\sigma_2(\mu_2(u)) \mathbbm{1}_{\{u< \tau_n\}}dW_2(u)\right|^p \\
    & + \left|\int_0^s(K_2(t-u) -K_2(s-u))\sigma_2(\mu_2(u)) \mathbbm{1}_{\{u< \tau_n\}}dW_2(u)\right|^p
    \Bigg]\\
    & := \bold{1} + \bold{2} + \bold{3} + \bold{4} + \bold{5} + \bold{6} + \bold{7} + \bold{8}.
\end{align*}

By applying the H\"older inequality twice, we obtain
\begin{align*}
    \bold{1} & \leq (t-s)^{p/2}\left| \int_s^t K_1^2(t-u)(b_1 - \theta_1 \mu_1(u))^2\mathbbm{1}_{\{u< \tau_n\}}du\right|^{p/2} \\
    & \leq (t-s)^{p/2}\left(\int_s^t K_1^2(t-u)du\right)^{p/2-1}\left(\int_s^t K_1^2(t-u) \left|(b_1 - \theta_1 \mu_1(u))\mathbbm{1}_{\{u< \tau_n\}}\right|^p du  \right).
\end{align*}
 By taking expectation, we have
 \begin{align*}
     \mathbb{E}[\bold{1}] & \leq \sup_{0\leq u \leq T}\mathbb{E}\left[\left|(b_1 - \theta_1 \mu_1(u))\mathbbm{1}_{\{u< \tau_n\}}\right|^p  \right] (t-s)^{p/2}\left(\int_s^t K_1^2(t-u)du\right)^{p/2-1}\\
    & \leq \sup_{0\leq u \leq T}\mathbb{E}\left[\left|(b_1 - \theta_1 \mu_1(u))\mathbbm{1}_{\{u< \tau_n\}}\right|^p  \right] (t-s)^{(H_1 + 1/2)p}. 
 \end{align*}
Similarly, we have
\begin{align*}
\mathbb{E}[\bold{2}] \leq \sup_{0\leq u \leq T}\mathbb{E}\left[\left|(b_1 - \theta_1 \mu_1(u))\mathbbm{1}_{\{u< \tau_n\}}\right|^p  \right] (t-s)^{p/2}\left(\int_0^s(K_1(t-u)-K_1(s-u))^2 du\right)^{p/2}. 
\end{align*}
For $H_1 \in (0,  1/2)$, 
\begin{align*}
    & \left(\int_0^s(K_1(t-u)-K_1(s-u))^2 du\right)^{p/2} \leq(t-s)^{H_1 p} \int_0^{\infty}\left[(u+1)^{H_1 -1/2}-u^{H_1 -1/2}\right]^2 d u \\
& \leq(t-s)^{H_1 p}\left\{\int_0^1\left[(u+1)^{H_1 -1/2}-u^{H_1 - 1 / 2}\right]^2 d u+\int_1^{\infty} u^{2 H_1 - 3} d u\right\} \\
& \leq C(t-s)^{H_1 p} .
\end{align*}
For $H_1 \in [1/2, 1)$, it is clear that $\left(\int_0^s(K_1(t-u)-K_1(s-u))^2 du\right)^{p/2} \leq C(t-s)^{H_1 p}$. 
Applying the Burkholder-Davis-Gundy inequalities and using similar calculations, we have 
\begin{align*}
    \mathbb{E}[\bold{1} + \bold{2} + \bold{5} + \bold{6}] \leq C \sup_{0 \leq t \leq T} \mathbb{E}\left[\left| (b_1 - \theta_1 \mu_1(u))\mathbbm{1}_{\{u< \tau_n\}}\right|^p + |\sigma_1(\mu_1(u))^2\mathbbm{1}_{\{u\leq \tau_n\}}|^{p/2}\right](t-s)^{H_1 p},
\end{align*}
and 
\begin{align*}
    & \mathbb{E}[\bold{3} + \bold{4} + \bold{7} + \bold{8}] \\
    & \leq C \sup_{0 \leq t \leq T} \mathbb{E}\left[\left| (b_2 - \beta_2 \mu_1(u) - \theta_2 \mu_2(u))\mathbbm{1}_{\{u< \tau_n\}}\right|^p + |\sigma_2(\mu_2(u))^2\mathbbm{1}_{\{u\leq \tau_n\}}|^{p/2}\right](t-s)^{H_2 p}. 
\end{align*}
As $\sigma_1(\mu_1)^2$ and $\sigma_2(\mu_2)^2$ are linear in $\mu_1$ and $\mu_2$ respectively, there exist a constant $C$ such that
\begin{align*}
    \mathbb{E}\left[|\mu_2^n(t) - \mu_2^n(s)|^p\right] \leq C(t-s)^{\min\{H_1, H_2\}p}. 
\end{align*}
The H\"older continuity follows from the Kolmogorov continuity theorem (see Theorem I.2.1 in \cite{RY1999}). As $\mu_2(t) = \mu_2^n(t)$ almost surely on $\{t \leq \tau_n\}$ for each $t$, the result follows from letting $\tau_n \rightarrow \infty$. 
\end{proof}



\subsection{Proof of Theorem \ref{Thm:admissible}}
\label{Appendix:Thm1}
\begin{proof}
From \eqref{Xtilde}, we have
\begin{align*}
X(t) & = \int_0^t e^{-\int_{0}^{s}r(v)dv}\left(\nu(s)^\top u(s)-\pi(s) - \mathbb{E}[z]c_1  {\hat{\mu}_2(s)} \right)ds  + \int_0^t e^{-\int_{0}^{s}r(v)dv}u(s)^\top\sigma_S(s)^\top d\boldsymbol{W}(s)\\ & -\int_0^t\int_{\mathbb{R}_+}ze^{-\int_{0}^{t}r(s)ds}\widetilde{N}(ds, dz). 
\end{align*}
By H\"older's inequality,
\begin{align*}
& \mathbb{E}\left[\int_0^{T_0}e^{-\int_0^s 2 r(v) dv}|\nu(s)^\top u(s)|^2 ds \right]\leq \left(\mathbb{E}\left[\int_0^{T_0}e^{-\int_0^s 4r(v)dv } ds\right]\right)^{\frac{1}{2}} \left(\mathbb{E}\left[\int_0^{T_0}|\nu(s)^\top u(s)|^4 ds \right] \right)^{\frac{1}{2}}   \\
& \leq \left(T_0\sup_{0\leq s \leq T_0}\mathbb{E}\left[e^{-\int_0^s 4r(v)dv}\right]\right)^{\frac{1}{2}} \left(\mathbb{E}\left[\int_0^{T_0}|\nu(s)^\top u(s)|^4 ds \right] \right)^{\frac{1}{2}} < \infty. 
\end{align*}
  {As $m_1$ and $m_2$ are bounded deterministic functions, it follows Lemma  \ref{lemma:E_mu} that for any constant $p \geq 2$, there exists a  constant $C$ such that $\sup_{t\leq T}\mathbb{E}[|\hat{\mu}|^p] \leq C$. } By applying H\"older's inequality, it follows that  $\mathbb{E}\left[\int_0^{T_0}e^{-\int_0^s 2 r(v) dv}|\pi(s)|^2 ds \right] <\infty$ and $\mathbb{E}\left[\int_0^{T_0}e^{-\int_0^s 2 r(v) dv}|\mathbb{E}[z]c_1  {\hat{\mu}_2(s)}|^2 ds \right] <\infty$. 
As we have $\mathbb{E}\left[\int_0^{T_0}\int_\mathbb{R}z^2e^{-2\int_0^tr(s)ds}\delta(dz)dt\right]\leq c_1\mathbb{E}[z^2]\int_0^{T_0}\mathbb{E}\left[e^{-2\int_0^t r(s)ds}\right]\mathbb{E}[  {\hat{\mu}_2(t)} 
]dt < \infty$, 
by the Burkholder--Davis--Gundy (BDG) inequality, 
\begin{align*}
\mathbb{E}\left[\sup_{0\leq t \leq T_0}\left(\int_0^t\int_{\mathbb{R}_+}ze^{-\int_{0}^{t}r(s)ds}\widetilde{N}(ds, dz)\right)^2\right] \leq C_1 \int_0^{T_0} \mathbb{E}\left[e^{-\int_0^s2r(v)dv}\right]\mathbb{E}\left[|  {\hat{\mu}_2(s)} |\right]ds < \infty
\end{align*}
for a constant $C_1$.
Then, by the BDG and H\"older's inequalities, we have
\begin{align*}
& \mathbb{E}\left[\sup_{0\leq t \leq T_0}|X(t)|^2\right] < C_2 + C_2\mathbb{E}\left[\int_0^{T_0}e^{-\int_0^s 2 r(v) dv}(|\nu(s)^\top u(s)|^2+ |\pi(s)|^2 + |\mathbb{E}[z]c_1  {\hat{\mu}_2(s)} |^2)ds \right] \\
& + C_2 \mathbb{E}\left[\int_0^{T_0} e^{-\int_0^s2r(v)dv}|\sigma_S(s)u(s)|^2ds\right]   + C_2 \int_0^{T_0} \mathbb{E}\left[e^{-\int_0^s2r(v)dv}\right]\mathbb{E}\left[|  {\hat{\mu}_2(s)}|\right]ds < \infty
\end{align*}
for a positive constant $C_2$. 
\end{proof}
\subsection{Proof of Theorem \ref{Thm:spike}}
\label{Appendix:Thm2}
\begin{proof}
Let $X^\epsilon(\cdot)$ denote the state process corresponding to $u^{t,\epsilon, \eta}(\cdot)$. Using the standard perturbation approach, 
	\[X^\epsilon(s) = X^*(s) + Y^\epsilon(s) + Z^\epsilon(s), s\in[t, T_0], \]
	where $Y^\epsilon(s)$ and $Z^\epsilon(s)$ are the solutions to the following SDEs respectively, 
	\[dY^\epsilon(s) = e^{-\int_0^s r(v)dv}\eta^\top\sigma_S^\top\boldsymbol{1}_{[t, t+\epsilon]}(s) d\boldsymbol{W}(s), ~ Y^\epsilon(t) =0, ~ s\in [t, T_0],  \]
	\[dZ^\epsilon(s) = e^{-\int_0^s r(v)dv} \nu^\top\eta\boldsymbol{1}_{[t, t+\epsilon]}(s)ds, ~ Z^\epsilon(t) =0, ~ s\in [t, T_0]. \]
	By the BDG inequality, there exists a positive constant $C_1$ such that
	\begin{align*}
	&\mathbb{E}_t\left[\sup_{s \in [t, T_0]}(Y_s^\epsilon)^2\right] \leq \mathbb{E}_t\left[\sup_{s\in[t, T_0]}\left(\int_{t}^{s}e^{-\int_{0}^{v}r(u)du} \eta^\top\sigma_S^\top\boldsymbol{1}_{[t, t+\epsilon]} d\boldsymbol{W}(v)\right)^2\right]\notag\\
	&\leq C_1\mathbb{E}_t\left[\int_{t}^{T_0}e^{-\int_{0}^{v}r(u)du} \eta^\top\sigma_S^\top\sigma_S\eta\boldsymbol{1}_{[t, t+\epsilon]}dv\right]
	\end{align*}
	 Let $\sigma_S^\top\sigma_S = (\Sigma_S^{ij}), ~i, j = 1, 2$. By Lemma \ref{Lemma:interest} and H\"older's inequality, there exists a positive constant $C_2$ such that
	\begin{align*}
	  & \mathbb{E}_t\left[\int_{t}^{T_0}e^{-\int_{0}^{v}r(u)du} \eta^\top\sigma_S^\top\sigma_S\eta dv\right]\\
	  & \leq C_2 \left(\int_t^{T_0}  \mathbb{E}[e^{-\int_{0}^{v}2r(u)du}]dv\right)^{\frac{1}{2}}\left(\int_t^{T_0}\sum_{ij}\mathbb{E}\left[(\Sigma_S^{ij})^2\right]dv\right)^{\frac{1}{2}}\mathbb{E}\left[|\eta|^2\right] < \infty.
	\end{align*}
	Therefore, $\mathbb{E}_t\left[\sup_{s \in [t, T_0]}(Y_s^\epsilon)^2\right] = O(\epsilon)$.
	Moreover, 
	\begin{align}
	&\mathbb{E}_t\left[\sup_{s \in [t, T_0]}(Z_s^\epsilon)^2\right] \leq \mathbb{E}_t\left[\sup_{s\in[t, T_0]}\left(\int_{t}^{s}e^{-\int_{0}^{v}r(u)du}\nu^\top\eta\boldsymbol{1}_{[t, t+\epsilon]}dv\right)^2\right]\notag\\
	&= \mathbb{E}_t\left[\left(\int_{t}^{t+\epsilon}e^{-\int_{0}^{v}r(u)du}\nu^\top\eta dv\right)^2\right] = O(\epsilon^2). 
	\end{align}
	Applying the same method as in \cite{HJZ2012}, the result follows. 
\end{proof}



\subsection{Proof of Theorem \ref{Thm:unique}}
\label{Appendix:unique}
\begin{proof}
Suppose that there is another admissible equilibrium control $u$ that is different from $u^*$ in \eqref{u*} and has a corresponding wealth process $X$. The equation \eqref{BSDE:p} admits a unique solution, with $X^*$ replaced by $X$. Let $(p(s; t), k_1(s; t), k_2(s, z; t))$ denote the solution. By Proposition \ref{Pro:Lam}, 
we have
 \begin{equation}\label{p*}
  e^{-\int_{0}^{t}r(v)dv}\nu(t) p(t;t) + e^{-\int_{0}^{t}r(v)dv}\sigma_S(t)^\top k_1(t; t) = 0, ~ a.s.,~a.e.,~ t \in [0, T_0].
 \end{equation}
 We define that
 $$\bar{p}(s; t) = p(s; t) - \left(X(s) + \Gamma_s^{(1)} - \lambda -\mathbb{E}_t[X(s) + \Gamma_s^{(1)}]\right), $$
 $\bar{k}_1(s; t) = k_1(s; t) - e^{-\int_{0}^{s}r(v)dv}\sigma_S(s)u(s) - \gamma^{(1)}(s)$, and $ \bar{k}_2(s, z; t) =  k_2(s, z; t) +  ze^{-\int_{0}^{s}r(v)dv}$. Then, we have $\bar{p}(s; t)\in S_\mathcal{F}^2(t,T_0;\mathbb{R}, \mathbb{P})$,  $\bar{k}_1(s; t)\in H_\mathcal{F}^2(t,T_0;\mathbb{R}^3, \mathbb{P})$, and $\bar{k}_2(s; t)\in F^2(t,T_0;\mathbb{R})$.

 Substituting the above into \eqref{p*} yields
 \begin{equation*}
 	\left[ \bar{p}(t; t) - \lambda\right]\nu(t) + \sigma_S(t)^\top\left( \bar{k}_1(t; t) + e^{-\int_{0}^{t}r(v)dv}\sigma_S(t)u(t) + \gamma^{(1)}(t)\right)= 0.
 \end{equation*}
 Thus,
 $u = -e^{\int_{0}^{t}r(v)dv}\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1}\left( \left[ \bar{p}(t; t) - \lambda\right]\nu(t) + \sigma_S(t)^\top\bar{k}_1(t; t) + \sigma_S(t)^\top\gamma^{(1)}(t)  \right) \triangleq  e^{\int_{0}^{t}r(v)dv}\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1}\left( \lambda \nu(t) - \sigma_S(t)^\top\gamma^{(1)}(t)  + D(t)\right)$ with $D(t) = -\bar{p}(t; t)\nu(t) - \sigma_S(t)^\top\bar{k}_1(t; t)$. We aim to prove the uniqueness by showing that $D \equiv 0$. We have
 \begin{align*}
 	d\bar{p}(s; t) & = dp(s; t) - d\left(X(s) + \Gamma_s^{(1)} - \lambda -\mathbb{E}_t[X(s) + \Gamma_s^{(1)}]\right)\\
 	&= -\left\{\nu(s)^\top\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1} D_s - \mathbb{E}_t\left[\nu(s)^\top\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1}D_s \right] \right\}ds \\
 	&+ \bar{k}_1(s; t)^\top d\boldsymbol{W}(s) +  \int_{\mathbb{R}_+} \bar{k}_2(s,z;t)\widetilde{N}(ds,dz), 
 \end{align*}
 and $\bar{p}(T_0; t) = 0$. By taking the conditional expectation on both sides of the above equation, it follows that $\mathbb{E}_t[\bar{p}(s; t)] = 0$ for $s > t$. Specifically, we have $\bar{p}(t; t) = 0$. Thus, $D_t = -\sigma_S(t)^\top \bar{k}_1(t; t).$ In addition, we have $k_1(s; t_1) = k_1(s; t_2)$ for a.e. $s \geq \max(t_1, t_2)$ similar to that in Proposition \ref{Pro:Lam}. We define that $\hat{p}(s; t) = \bar{p}(s; t) + \int_{s}^{T_0} \mathbb{E}_t\left[\nu(v)^\top \left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1} D_v\right]dv$. Then,
 \begin{align*}
 	d\hat{p}(s; t) = \nu(s)^\top\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1}\sigma_S(s)^\top\bar{k}_1(s; s)ds + \bar{k}_1(s; s)^\top d\boldsymbol{W}(s) +  \int_{\mathbb{R}_+} \bar{k}_2(s,z;t)\widetilde{N}(ds,dz). 
 \end{align*}
It is easy to check $\mathbb{E}\left[\sup_{t\leq s\leq T_0}\left|\int_{s}^{T_0}\mathbb{E}_t\left[\nu(v)^\top\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1}\sigma_S(v)^\top\bar{k}_1(v; v)\right]dv\right|^{q}\right] < \infty$ for any $q\in (1, 2)$. As $\bar{p}(s; t)\in S_\mathcal{F}^2(t,T_0;\mathbb{R}, \mathbb{P})$, we have $\mathbb{E}\left[\sup_{t\leq s\leq T_0}\left|\hat{p}(s; t)\right|^{q}\right] < \infty$ for any $q \in (1, 2)$. Let 
  \begin{align*}
    & \mathcal{E}_t\left(\sigma_S\left(\sigma_S^\top \sigma_S\right)^{-1}\nu\right) \\
    & = \exp\left(\int_{0}^{t}-\nu(s)^\top\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1}\sigma_S(s)^\top d{\boldsymbol{W}}(s)-\frac{1}{2}|\sigma_S(s)\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1}\nu(s)|^2ds \right).
   \end{align*}
  We introduce the measure $\hat{\mathbb{P}}$ by $\frac{d\hat{\mathbb{P}}}{d\mathbb{P}}|_{\mathcal{F}_t} =  \mathcal{E}_t\left(\sigma_S\left(\sigma_S^\top \sigma_S\right)^{-1}\nu\right)$. Under measure $\hat{\mathbb{P}}$,  $\hat{\boldsymbol{W}}(t) \triangleq \boldsymbol{W}(t) + \int_0^t \sigma_S(s)\left(\sigma_S(s)^\top \sigma_S(s)\right)^{-1}\nu(s)ds$ is a standard Brownian motion. 
  Under $\hat{\mathbb{P}}$, we have
 \[d\hat{p}(s; t) =  \bar{k}_1(s; s)^\top d\hat{\boldsymbol{W}}(s) + \int_{\mathbb{R}_+} \bar{k}_2(s,z;t)\widetilde{N}(ds,dz).\]
 For any $m >1$, 
 \begin{align*}
  & \mathbb{E}\left[\mathcal{E}\left(\sigma_S\left(\sigma_S^\top \sigma_S\right)^{-1}\nu\right)^m\right] \leq \\
  & \left(\mathbb{E}\left[\exp\left((2m^2 - m)\int_{0}^{T_0}|\sigma_S(s)\left(\sigma_S(t)^\top \sigma_S(t)\right)^{-1}\nu(s)|^2ds \right) \right] \mathbb{E}\left[\mathcal{E}_{T_0}\left(2m\sigma_S\left(\sigma_S^\top \sigma_S\right)^{-1}\nu\right)\right]\right)^{\frac{1}{2}}\\
  & < \infty. 
 \end{align*}
 Therefore, if $m > \frac{q(q +1)}{(q-1)^2}$ in the above equation, there exists a value of $\bar{q}_0\in (1, q)$ for any $q \in (1, 2)$ such that 
 \[\hat{\mathbb{E}}\left[\sup_{t\leq s \leq T_0}|\hat{p}(s; t)|\right] \leq \left(\mathbb{E}\left[\sup_{t\leq s \leq T_0}|\hat{p}(s; t)|^{\bar{q}_0} \right] \right)^{\frac{1}{q_0}}\left(\mathbb{E}\left[\mathcal{E}\left(\sigma_S\left(\sigma_S^\top \sigma_S\right)^{-1}\nu\right)^{\frac{\bar{q}_0}{\bar{q}_0-1}}\right] \right)^{\frac{\bar{q}_0}{\bar{q}_0-1}} < \infty,\]
 so that $\hat{p}(s; t)$ is a $\hat{\mathbb{P}}$-martingale. Hence, $\hat{p} \equiv 0$ and $D \equiv 0$.
\end{proof}

\subsection{Proof of Proposition \ref{pro:Vas}}
\begin{proof}
Under the pricing measure $\mathbb{Q}$, we have
\begin{align*}
\mu_1(t) & = \mu_1(0) + \int_{0}^{t}K_1(t-s)(b_1 + \varphi_1(s)\sigma_1 - \theta_1 \mu_1(s))ds + \int_{0}^{t}K_1(t-s)\sigma_1 dW_1^\mathbb{Q}(s),\\
\mu_2(t) & = \mu_2(0) + \int_{0}^{t}\beta_1 K_1(t-s)(b_1 + \varphi_1(s)\sigma_1  - \theta_1 \mu_1(s))ds  + \int_0^tK_2(t-s)(b_2 - \beta_2 \mu_1(s)  \nonumber \\ 
& - \theta_2 \mu_2(s))ds + \int_{0}^{t}\beta_1 K_1(t-s)\sigma_1dW_1^\mathbb{Q}(s) + \int_0^t K_2(t-s)\sigma_2 dW_2^\mathbb{Q}(s).
\end{align*}
Hence, the {force of mortality} maintains the affine structure and satisfies \eqref{mu0}, with $b(s) = (b_1 + \varphi_1(s)\sigma_1, b_2)^\top$ and $W(s)$ replaced by $W^\mathbb{Q}(s)$. 
The interest rate follows the SDE:
\[ dr(t)=(b_r +\vartheta(s)\sigma_r -  \theta_r r(t))dt +\sigma_rdW^\mathbb{Q}_r(t). \]
By Appendix \ref{appendix:affine}, we have 
\[\mathcal{B}(t,T) = \mathbb{E}^{\mathbb{Q}}\left[\left.e^{-\int_{t}^{T}r(s)ds}\right|\mathcal{F}_t\right] = e^{d_0(t) + d_1(t)r(t)}, \]
where $d_1(s) = \frac{1}{\theta_r}\left(e^{-\theta_r(T-s)} -1\right)$. Hence, $\sigma_b(s) = d_1(s)\sigma_r$.
By Lemma \ref{lemma:expmu}, the price of the zero-coupon longevity bond is given by
\[ \mathcal{B}_L(t,T) =\mathbb{E}^{\mathbb{Q}}\left[\left.e^{-\int_{t}^{T}r(s)+ \mu_1(s)ds}\right|\mathcal{F}_t\right] =\mathcal{B}(t,T)e^{\int_0^t\mu_1(s)ds}\exp(Y_t(T)),\]
where $Y_t(T)$ is as defined in \eqref{Y} in Lemma \ref{lemma:expmu} with $f = (-1, 0)$, $b(s) = (b_1 + \varphi_1(s)\sigma_1, b_2)^\top$, $\sigma(\mu(s)) \equiv \sigma_\mu$, and $W$ replaced by $W^\mathbb{Q}$. Therefore, by It\^o's formula, $\sigma_l = \psi(T-s)\sigma_\mu$, where $\psi = (\psi_1, \psi_2)$ solves the Volterra--Riccati equation $\psi = (f- \psi\Theta )*K$ with $f =(-1, 0)$. Thus, the result for $\sigma_l$ follows.
By Lemma \ref{lemma:expmu}, for any constant $q > 1$, we have $$\mathbb{E}\left[e^{-q\int_0^{t}\mu_2(s)ds}\right] = \exp\left\{{\int_0^t\left(-q\mu_2(0)+\bar{\psi}(s)(b - \Theta \mu(0)) +\frac{1}{2}\bar{\psi}(s)\sigma_\mu\sigma_\mu^\top\bar{\psi}(s)^\top \right)ds}\right\}$$
where $\bar{\psi}$ solves the Volterra--Riccati equation $\bar{\psi} = (f -\bar{\psi}\Theta)*K$ with $f = (0, -q)$. By Lemma 4.4 in \cite{AJ}, $\bar{\psi}$ admits the closed-form solution $\bar{\psi} = f*E_\Theta $, where $E_\Theta$ is as defined in Lemma \ref{lemma:expmu}. Therefore, $\pi(t) \in L_\mathcal{F}^q(0, T_0; \mathbb{R}, \mathbb{P})$.
\end{proof}

\subsection{Proof of Proposition \ref{pro:RB}}
\begin{proof}
By calculation, we have
$K\Theta = \left(\begin{array}{cc}
    \theta_1K_1 &  0 \\
    \beta_1\theta_1K_1 + \beta_2K_2 & \theta_2K_2
\end{array} \right)$. As $K_1, K_2 \in L_{loc}^2(\mathbb{R}_+, \mathbb{R})$, we have $R_{1\theta_1}, R_{2\theta_2} \in L_{loc}^2(\mathbb{R}_+, \mathbb{R})$ and thus $(R_{2\theta_2}*R_{1\theta_1})*\theta_1K_1 = R_{2\theta_2}*(R_{1\theta_1}*\theta_1K_1)$ \citep{GLS1990}. Then,
\begin{align*}
   & \left[\beta_1R_{1\theta_1} + \frac{\beta_2}{\theta_2} R_{2\theta_2}-(\beta_1 + \frac{\beta_2}{\theta_2})R_{2\theta_2}*R_{1\theta_1}\right]* \theta_1K_1 + R_{2\theta_2}*(\beta_1\theta_1K_1 + \beta_2K_2)\\
   & = \beta_1(\theta_1K_1 - R_{1\theta_1}) + \frac{\beta_2}{\theta_2} R_{2\theta_2}*\theta_1K_1 -(\beta_1 + \frac{\beta_2}{\theta_2})R_{2\theta_2}*(\theta_1K_1 - R_{1\theta_1}) + R_{2\theta_2}*\beta_1\theta_1K_1\\
   & + \frac{\beta_2}{\theta_2}(\theta_2K_2 - R_{2\theta_2})\\
   & = (\beta_1 + \frac{\beta_2}{\theta_2})(R_{2\theta_2}*R_{1\theta_1}) = \beta_1\theta_1K_1 + \beta_2K_2 - \left[\beta_1R_{1\theta_1} + \frac{\beta_2}{\theta_2} R_{2\theta_2}-(\beta_1 + \frac{\beta_2}{\theta_2})R_{2\theta_2}*R_{1\theta_1}\right].
\end{align*}
Thus, we have %The resolvent of $K\Theta$ denoted by $R_\Theta$ is given by
\begin{align}\label{RB}
R_\Theta = \left(\begin{array}{cc} 
    R_{1\theta_1} & 0 \\
    \beta_1R_{1\theta_1} + \frac{\beta_2}{\theta_2} R_{2\theta_2}-(\beta_1 + \frac{\beta_2}{\theta_2})R_{2\theta_2}*R_{1\theta_1} & R_{2\theta_2}
\end{array} \right),
\end{align}
as it satisfies $R_\Theta*K\Theta = K\Theta - R_\Theta$ and  $K\Theta*R_\Theta = K\Theta - R_\Theta$.  

 As shown in Lemma \ref{lemma:expmu}, $E_\Theta$ is defined as $E_\Theta = K- R_\Theta*K$, where $R_\Theta$ is the resolvent of $K\Theta$. Then,
$$E_\Theta \Theta = K \Theta  - R_\Theta*K \Theta  = K \Theta  - (K \Theta - R_\Theta) = R_\Theta.$$
Therefore, $E_\Theta = R_\Theta  \Theta ^{-1}$. The result in Proposition \ref{pro:RB} follows.
\end{proof}


\subsection{Proof of Proposition \ref{Pro:CIR}}
\begin{proof}
Similar to the proof of Proposition \ref{pro:Vas},  $\mu$ maintains the affine structure under the pricing measure. Specifically, under $\mathbb{Q}$, $\mu$ satisfies \eqref{mu0} with $b(s) = (b_1, b_2)^\top$, where $\Theta$ is replaced by
\[\left(\begin{array}{cc}
    \theta_1- \widetilde{\varphi}_1\widetilde{\sigma}_1^2 & 0 \\
    \beta_2 &  \theta_2
\end{array}\right) \triangleq \Theta_q,\]
and $W$ is replaced by $W^\mathbb{Q}$. By Lemma \ref{expmu} and It\^o's formula, we have $\sigma_l(s) = \psi'(T-s)\sigma(\mu(s))$, where $\psi' = (\psi'_1, \psi'_2)$ solves the Volterra--Riccati equation $\psi' = (f - \psi'\Theta_q+ \frac{1}{2} (\widetilde{\sigma}_1^2 (\psi'_1)^2, \widetilde{\sigma}_2^2 (\psi'_2)^2))*K$ with $f = (-1, 0)$. Thus, $\psi'_2 = 0$ and $\psi'_1$ solves $\psi'_1 = (-1 - (\theta_1 - \widetilde{\varphi}_1 \widetilde{\sigma}_1^2)\psi'_1+ \frac{1}{2}\widetilde{\sigma}_1^2 (\psi'_1)^2)*K_1$.
Under the pricing measure $\mathbb{Q}$, the interest rate follows
\[	dr(t)=(b_r -  (\theta_r - \vartheta\sigma_r^2 )r(t))dt +\sigma_r \sqrt{r(s)} dW^\mathbb{Q}_r(t).\]
The result follows from Appendix \ref{appendix:affine} and It\^o's formula.
\end{proof}

