\title[Direct approach to extended KEDF]{A direct approach to computing non-interacting kinetic energy functional}
\author{Dharamveer Kumar, Amuthan A. Ramabathiran}
\address[Dharamveer Kumar]{Department of Aerospace Engineering, Indian Institute of Technology Bombay, Mumbai 400042, India.}
\email{dharamveer\_kumar@iitb.ac.in}
