\section{Supplementary Propositions} \label{app:math_props}
\begin{proposition}
\label{prop: lag_multiplier_on_banach} 
\textit{\textup{[}Section $4.14$ in \cite{Zeilder95}\textup{]}}
    Let \( X \) and \( Y \) be real Banach spaces and $U$ be an open subset of \( X \). Let \( f: U \to \mathbb{R} \) and \( g: U \to Y \) be continuously Frechet differentiable functions. Suppose \( u^* \in U \) is a local extremum of \( f \) subject to the constraint \( g (x)= 0 \). If the Frechet derivative \( Dg(u^*): X \to Y \) is a surjective linear map, then there exists a continuous linear functional \( \lambda^* \in Y^* \), dual to the space \( Y \), such that
\[
Df(u^*) = \lambda \circ Dg(u^*),
\]
where \( Df(u^*): X \to \mathbb{R} \) is Frechet derivative of $f$ at $u^*$. 
\end{proposition}

\begin{proposition}
    \label{prop: Lieb_Schrodinger_GS}\textit{\textup{[}Theorem $11.8$ in \cite{Lieb01}\textup{]}}
    Let $V \in L^1_{loc}(\mathbb{R}^d)$, $\psi_0 \in H^1(\mathbb{R}^d)$ be a minimizer of $\mathcal{E}(f) = \int_{\mathbb{R}^d} \| \nabla f\|^2 + \int_{\mathbb{R}^d}Vf^2$ over $H^1(\mathbb{R}^d)$ with constraint $\|f\|_{L^2(\mathbb{R}^d)} =1$, and $V|\psi_0|^2$ be summable. If $V_+ \in L^\infty(\mathbb{R}^d)$, then $\psi_0$ is unique up to sign change and can be chosen to be strictly positive.
\end{proposition}

\begin{proposition}
\label{prop:H1_level_set}\textit{\textup{[}Theorem $6.9$ in \cite{Lieb01}\textup{]}}
Let $f \in H^1(\mathbb{R}^d)$ and let $B = f^{-1}(\{0\})$. Then $\nabla f = 0$ for almost every $x \in B$. 
\end{proposition}


\section{Gradients for the RBF approximation} \label{app:FCgrad}
The derivatives required for a gradient-based optimization algorithm are provided below for quick reference:
\[
\begin{split}
    \frac{\partial F}{\partial t_{ij}} &= \int_0^1 h \sigma_j - (\rho \cos^2{\theta_1}\cos{\theta_2}^2 \dots \cos{\theta_{i-1}^2} \theta_i^{'})\sigma_j^{'}, \\
    h &= \rho \cos^2{\theta_1} \dots \cos{\theta_{i-1}^2} \cos{\theta_i} \sin{\theta_i}\\
    &\Big((\theta_{i+1}^{'})^2 + \cos^2{\theta_{i+1}} (\theta_{i+2}^{'})^2 + \ldots + \cos^2{\theta_{i+1}} \dots \cos^2{\theta_{N-2}} (\theta_{N-1}^{'})^2 \Big), \\
    \frac{\partial C_{kl}}{\partial t_{ij}} &= \frac{\partial D_{kl}}{\partial t_{ij}} + \frac{\partial D_{lk}}{\partial t_{ij}}, \\
    \frac{\partial D_{kl}}{\partial t_{ij}} &= \int_0^1 g_{ik}(\Theta)\sigma_j \varphi^\Theta_l.
\end{split}
\]
In the final equation shown above, it is important to note that:
\[
\frac{\partial \varphi^\Theta_k }{\partial t_{ij}} = g_{ik}(\Theta)\sigma_j,
\]
where the following conditions hold, for \(1 \leq k \leq N-1\):
\begin{itemize}
    \item When \(k < i\), \(g_{ik}(\Theta) = 0\), 
    \item When \(k = i\), we have
\[
g_{ik}(\Theta) = \sqrt{\frac{\rho}{2}} 
\prod_{m=1}^{k} \cos(\theta_m),
\]
\item When \(k > i\), we have
\[
g_{ik}(\Theta) = -\sqrt{\frac{\rho}{2}}\sin(\theta_i) \sin(\theta_k)\prod_{m=1}^{i-1}\cos(\theta_m)\prod_{p=i+1}^{k-1}\cos(\theta_p).
\] 
\end{itemize}
Finally, when \(k = N\), we have
\[
g_{iN}(\Theta) = -\sqrt{\frac{\rho}{2}} \sin(\theta_i) \prod_{m=1}^{i-1}\cos(\theta_{m}) \prod_{p=i+1}^{N-1}\cos(\theta_{p}).
\]

