	\subsection{Computing $\delta$}\label{SectionComputingDelta}
	Let $F$ and $x$ be as in Section \ref{Genus2SubSection}. Let $J_8$ be the eighth Igusa invariant of $F$ as defined by Igusa in \cite{Igusa1960}. 
	Define $\delta':=\frac{v(J_8)}{8}+2$.
	\begin{Thm}\label{DeltaPrimeTheorem}
		%	The genus $2$ classification in Subsection \ref{Genus2SubSection} remains unchanged when replacing $\delta$ with $\delta'$. 
		The \emph{same} half-open polyhedral regions from Theorem \ref{Genus2SummaryTheorem} describe the type of $C_0$ in terms of $(\alpha, \beta, \gamma, \delta', \epsilon)$ and the thicknesses of $C_0$ are given by the same formulas, where $\delta$ is replaced by $\delta'$.
	\end{Thm}
	\begin{Proof}
		We have  
\begin{align}
2^{16}	J_8 &= 3 (c-2\sqrt{bd})^{8}+48 \sqrt{b}\, \sqrt{d}\, (c-2\sqrt{bd})^{7} \nonumber\\
	&\quad +\left(-208 a e+304 d b\right) (c-2\sqrt{bd})^{6} \nonumber\\
	&\quad +\left(960 b^{\frac{3}{2}} d^{\frac{3}{2}}-2496 \sqrt{b}\, \sqrt{d}\, a e+96 a \,d^{2}+96 b^{2} e\right) (c-2\sqrt{bd})^{5} \nonumber\\
	&\quad +\left(1536 d^{2} b^{2}-10464 d b a e+960 d^{\frac{5}{2}} \sqrt{b}\, a+960 b^{\frac{5}{2}} \sqrt{d}\, e-1632 a^{2} e^{2}\right) (c-2\sqrt{bd})^{4} \nonumber\\
	&\quad +\left(1024 b^{\frac{5}{2}} d^{\frac{5}{2}}-17152 b^{\frac{3}{2}} d^{\frac{3}{2}} a e+3072 d^{3} b a+3072 d \,b^{3} e\right.\nonumber\\
	&\qquad \left.-13056 \sqrt{bd}\, a^{2} e^{2}-1152 d^{2} a^{2} e-1152 b^{2} a \,e^{2}\right) (c-2\sqrt{bd})^{3} \nonumber\\
	&\quad +\left(-6144 d^{2} b^{2} a e+3072 d^{\frac{7}{2}} b^{\frac{3}{2}} a+3072 b^{\frac{7}{2}} d^{\frac{3}{2}} e-29184 d b \,a^{2} e^{2}\right.\nonumber\\
	&\qquad \left.-6912 d^{\frac{5}{2}} \sqrt{b}\, a^{2} e-6912 b^{\frac{5}{2}} \sqrt{d}\, a \,e^{2}+14080 a^{3} e^{3}+512 d^{4} a^{2}+512 b^{4} e^{2}\right) (c-2\sqrt{bd})^{2} \nonumber\\
	&\quad +\left(6144 b^{\frac{5}{2}} d^{\frac{5}{2}} a e-12288 b^{\frac{3}{2}} d^{\frac{3}{2}} a^{2} e^{2}-8192 d^{3} b \,a^{2} e-8192 d \,b^{3} a \,e^{2}\right.\nonumber\\
	&\qquad \left.+56320 \sqrt{b}\, \sqrt{d}\, a^{3} e^{3}+2048 d^{\frac{9}{2}} \sqrt{b}\, a^{2}+2048 b^{\frac{9}{2}} \sqrt{d}\, e^{2}\right.\nonumber\\
	&\qquad -25600 d^{2} a^{3} e^{2}-25600 b^{2} a^{2} e^{3}\Big) (c-2\sqrt{bd}) \nonumber\\
	&\quad -83200 a^{4} e^{4}+5120 b^{4} a \,e^{3}+5120 d^{4} a^{3} e+1792 d^{2} b^{2} a^{2} e^{2} \nonumber\\
	&\quad +125440 d b \,a^{3} e^{3}+2048 d^{\frac{7}{2}} b^{\frac{3}{2}} a^{2} e+2048 b^{\frac{7}{2}} d^{\frac{3}{2}} a \,e^{2} \nonumber\\ \nonumber
	&\quad -51200 d^{\frac{5}{2}} \sqrt{b}\, a^{3} e^{2}-51200 b^{\frac{5}{2}} \sqrt{d}\, a^{2} e^{3}.
