\begin{abstract}
We establish a quantitative version of the isoperimetric inequality for the torsion of multiply connected domains, among sets with
given area and with given joint area of the holes.

Since the optimal shape is the annulus, we investigate how a given domain approaches an annular configuration when its torsion is close to the optimal value. Our result shows that when the torsional rigidity is nearly optimal, the domain $\Omega$ must be close to an annulus.
\newline
\newline
\textsc{Keywords:}  Laplace operator, stability, comparison results.\\
\textsc{MSC 2020:}  35J05, 35B35, 35B45.
\end{abstract}

\section{Introduction}
Let us consider a homogeneous beam with cross-section a multiply connected domain $\Omega$.



\begin{definizione}
    \label{multiplyconnected}
    A set $\Omega$ is a multiply connected domain if  $\Omega=G\setminus S$ where
\begin{itemize}
    \item[\emph{(i)}] there exists $G,\Omega_1,\dots,\Omega_m$ are bounded Lipschitz domain of $\R^n$; 
    \item[\emph{(ii)}] $\overline{\Omega}_i\subset G$ for $i=1,\dots,m$;
    \item[\emph{(iii)}]$\overline{\Omega}_i\cap\overline{\Omega}_j=\emptyset$ if $i\neq j$;
    \item[\emph{(iv)}]$S=\bigcup\limits_{i=1}^m\overline{\Omega}_i$.    
\end{itemize}
\end{definizione}


It is well known that the torsional rigidity of $\Omega$, i.e. the one of the beam with cross-section $\Omega$, can be written as the maximum of a Rayleigh quotient (see for instance \cite{B,PW}), that is
\begin{equation}\label{torsione}
    T(\Omega)= \max\left\{ \frac{\displaystyle \left(\int_G \varphi\, dx\right)^2}{\displaystyle \int_G\abs{\nabla\varphi}^2\,dx} : \, \varphi \in H^1_0(G), \varphi\equiv \text{ constant on }  \Omega_i \, \forall i=1, \dots m  \right\}.
\end{equation}

In the case of simply connected domains ($m=0$), in 1856 de Saint-Venant conjectured that among all beams with cross-section of prescribed area, the one with circular cross-section has the highest torsional rigidity. The complete proof of such conjecture is due to P\'olya in 1948, see  \cite{P}.

The de Saint-Venant inequality was latter generalized to different settings, for instance in \cite{DW}, Diaz and Weinstein gave some upper and lower bounds for the torsional rigidity of a beam also in the case of multiply connected domains, in terms of its second order momentum.

In 1950, P\'olya and Weinstein proved in \cite{PW} that among all beams with multiply connected cross-section with
given area and with given joint area of the holes, the one with annular cross-section has the highest torsional rigidity. Namely, using definition \eqref{torsione} we have the following inequality
\begin{equation}\label{polyaweinstein}
    T(\Omega)\leq T(\Omega^\OO),
\end{equation}
where $\Omega^\OO=G^\sharp\setminus S^\sharp$ and  $G^\sharp$ and $S^\sharp$ stands for the centered ball having same measure as $G$ and $S$ respectively. Lastly, this result have been extended in any dimension also for degenerate elliptic operator in \cite{B}.

By the way, this can also be seen as a limiting case of a double-phase problem, studied by several authors, such as in \cite{CLM,CMS,MNP}.

Once an isoperimetric inequality is established, a natural question that arises is its rigidity, specifically, under what conditions equality holds. For instance, in the case of simply connected domains, this was proved by Polya in \cite{P} and later by \cite{BM}. For multiply connected domains, P\'olya and Weinstein provided a partial answer. They established that if equality holds in the isoperimetric inequality \eqref{polyaweinstein}, then the domain must necessarily have exactly one hole. 
Up to our knowledge, no additional information has been provided in the case of multiply connected domains ($m\geq 1$), so we give the following result.
\begin{prop}\label{propmerc}
    Let $\Omega\subset\R^2$ satisfy definition \ref{multiplyconnected}. If equality holds in \eqref{polyaweinstein}, that is
    \[T(\Omega)=T(\Omega^\OO),\]

     then, up to translation, $\Omega=\Omega^\OO$ and therefore there exists $x_0 \in \R^2$ such that $G=G^\sharp+ x_0$ and $S=S^\sharp+ x_0$.
\end{prop}

We will prove, in section \ref{section3}, Proposition \ref{propmerc} as a particular case of a more general theorem given in any dimension and for a more general class of linear elliptic operator.


The fact that annuli are the only sets for which the equality holds in \eqref{polyaweinstein} naturally raises the question of the stability of this inequality. More precisely, one can try to improve \eqref{polyaweinstein} by adding a remainder term in the left-hand side that quantifies the deviation of a set from the corresponding annulus, that is, the annulus with the same measure and the same hole measure.

Firstly, we need to introduce a way of measuring the deviation from the corresponding annulus. 
More precisely, we firstly aim to measure the distance both between the outer boundary and the sphere, and between the holes and the ball. One way to measure them is through the Fraenkel Asymmetry index, see for instance \cite{F} for its properties. This index is defined by the following equation
\begin{equation*}
	\alpha(\Omega):=\min_{x \in \R^{n}}\bigg \{  \dfrac{|\Omega\triangle B_r(x)|}{|B_r(x)|} \;,\; |B_r(x)|=|\Omega|\bigg \},
\end{equation*} where the symbol $\triangle$ denotes the symmetric difference (see definition in subsection \ref{subsection2.3}).

Hence, we state our main theorem as follow.
\begin{theorem}\label{thm:dueasimmetrie}
    Let $\Omega\subset\R^2$ satisfy definition \ref{multiplyconnected} such that $\displaystyle{\abs{S}\leq\frac{3}{4}\abs{G}}$. Then %there exists some constants $C_1=C_1(\abs{G})$, $C_2$ such that
 \begin{equation*}
        T(\Omega^\OO)-T(\Omega)\geq \frac{1}{3^22^9 \pi \gamma_2}\left[\abs{G}^2  \alpha^3(G)+\abs{S}^2\alpha^3(S)\right].
     \end{equation*}

    %\begin{equation*}
    %    T(\Omega^\OO)-T(\Omega)\geq
    %    C_1 \alpha^3(G)+ C_2 \left(\abs{S}\alpha(S)\right)^3.
     %\end{equation*}
\end{theorem}

The proof of this theorem relies on the propagation of asymmetry discussed in \cite{HN}, which has been used, explained, and further explored in various works \cite{AB,ABMP,BD,CLI,MS}.

We would also like to point out that quantitative inequalities where annuli are optimal have already appeared in the literature. In \cite{CPP}, the authors studied a mixed eigenvalue problem on a domain with holes, providing an interpretation of the distance between $\Omega$ and the corresponding annulus. Also in this case, the authors had to divide the proof into two parts: one for the outer boundary and one for the inner boundary.


Motivated by the classical Fraenkel Asymmetry index, we define an "Annular Asymmetry index" as follows:
$$
\beta(\Omega) =\inf \{\abs{\Omega \triangle A} \, : \, A=B_1 \setminus B_2, \, \abs{B_1}= \abs{G} , \, \abs{B_2} = \abs{S}\},$$
that vanishes if and only if the set $\Omega$ is an annulus. 

With this definition, we can state  our main Theorem.
\begin{theorem}\label{thm:anellia}
 Let $\Omega\subset\R^2$ satisfy definition \ref{multiplyconnected}. Then, there exists $C>0$ and $\overline{\theta}>0$, depending on $\abs{G}$ and $\abs{S}$, such that 
	\begin{equation}
		\label{teoremabeta}
		T(\Omega^\OO)-T(\Omega) \geq C \beta^{\overline{\theta}}(\Omega).
	\end{equation}
\end{theorem}

The proof of this theorem relies on the closeness of the torsion function to that of the annulus. Since the holes can be seen as the regions where the gradient of the torsion function vanishes, this closeness implies that not only the outer domain and the holes are almost a balls, as shown in Theorem \ref{thm:dueasimmetrie}, but also that these two balls must be almost centered.



The paper is organized as follows: in Section \ref{section2} we introduce the notation and the preliminary results that we will need throughout the paper;  Section \ref{section3} is devoted to the proof of rigidity;  in Section \ref{section4}  we prove that the external domain is almost a ball; in Section \ref{section5} we prove that the asymmetry of the holes is small, and in Section \ref{section6} we discuss the almost radiality of the torsion function. Finally, in Section \ref{section7} we collect a list of open problems.


\section{Notation and preliminary}
\label{section2}
In the following, we will denote by $\abs{\Omega}$ the Lebesgue measure of an open and bounded set of $\R^n$, with $n\geq2$. Also, the $ L^p-$ norm will be denoted as $\norma{\cdot}_p$ if the space is clear by the context; otherwise, the space will be explicitly written as $\norma{\cdot}_{L^p(\Omega)}$.
\begin{definizione}
    Let be $\Omega$ a bounded open set and let be $E\subset\Omega$, then $P(E,\Omega)$ denotes the \textbf{perimeter} of $E$ inside $\Omega$ defined as
    $$
    P(E,\Omega)= \inf \left\{\liminf_n \int_E \abs{\nabla u_n}\, dx : \, u \in \text{Lip}_{\text{loc}}(E)  , \, u_n \to \chi_E \in L^1_{\text{loc}}(E)\right\}.
    $$
    If $\Omega = \R^n$, we denote $\text{Per}(E):=\text{Per}(E,\R^n)$.
\end{definizione}
Moreover, if $\Omega$ is an open set, the following coarea formula applies. Some references for results relative to the sets of finite perimeter and the coarea formula are, for instance, \cite{AFP,Fleming_Rishel,maggi2012sets}.
\begin{theorem}[Coarea formula]
	Let $\Omega \subset \mathbb{R}^n$ be an open set. Let $f\in W^{1,1}_{\text{loc}}(\Omega)$ and let $u:\Omega\to\R$ be a measurable function. Then,
	\begin{equation}
        	\label{coarea}
		{\displaystyle \int _{\Omega}u(x)|\nabla f(x)|dx=\int _{\mathbb {R} }dt\int_{\Omega\cap f^{-1}(t)}u(y)\, d\mathcal {H}^{n-1}(y)}.
	\end{equation}

Moreover, if  $f \in \text{BV}(\Omega)$, then it holds the Fleming-Rishel formula, i.e.
\begin{equation*}
	% \label{flemingrishel}
	\abs{Df}(\Omega) = \int_{-\infty}^{+\infty} \text{Per}(\Set{ u>t},\Omega ) \, dt.
\end{equation*}
\end{theorem}

The rest of this section is devoted to the introduction of the rearrangement of functions and both some qualitative and quantitative properties. 
\subsection{Rearrangement of functions}
Some general results and applications of the theory of rearrangements can be found in \cite{K}.

 \begin{definizione}\label{distribution:function}
	Let $u: \Omega \to \R$ be a measurable function, the \emph{distribution function} of $u$ is the function $\mu_u : [0,+\infty[\, \to [0, +\infty[$ defined as the measure of the superlevel sets of $u$, i.e.
	$$
	\mu_u(t)= \abs{\Set{x \in \Omega \, :\,  \abs{u(x)} > t}}.
	$$
\end{definizione}
Also using the Coarea formula \eqref{coarea}, is possible to deduce an explicit expression for $\mu$ in terms of integrals of $u$

\begin{equation*}
    %\label{mugr0}
    \mu_u(t)=\abs{\{u>t\}\cap \{|\nabla u |=0\}}+ \int_t^{+\infty} \left(\int_{u=s}\frac{1}{\abs{\nabla u}}\, d\, \mathcal{H}^{n-1}\right)\, ds,
\end{equation*}

as a consequence, for almost all $t\in (0,+\infty)$,
    \begin{equation}\label{brothers1}
        \infty>-\mu_u'(t)\geq\displaystyle \int_{u=t}\dfrac{1}{|\nabla u|}d\mathcal{H}^{n-1}
    \end{equation}
moreover if $\mu$ is absolutely continuous, equality holds in \eqref{brothers1}.


\begin{definizione} \label{decreasing:rear}
	Let $u: \Omega \to \R$ be a measurable function, the \emph{decreasing rearrangement} of $u$, denoted by $u^\ast(\cdot)$, is defined as
$$u^*(s)=\inf\{t\geq 0:\mu_u(t)<s\}.$$
	\end{definizione}
 \begin{oss}
	Let us notice that the function $\mu_u(\cdot)$ is decreasing and right continuous and thus the function $u^\ast(\cdot)$ can be seen as its generalized inverse.
 \end{oss}
 Also by this remark, one can prove using Definitions \ref{distribution:function} and \ref{decreasing:rear} that
	 $$u^\ast (\mu_u(t)) \leq t, \quad \forall t\ge 0,$$ 
  $$\mu_u (u^\ast(s)) \leq s \quad \forall s \ge 0.$$ 
	\begin{definizione}
	 The \emph{Schwartz rearrangement} of $u$ is the function $u^\sharp $ whose superlevel sets are balls with the same measure as the superlevel sets of $u$. 
	\end{definizione}
		We emphasize the relation between $u^\sharp$ and $u^*$:
	$$u^\sharp (x)= u^*(\omega_n\abs{x}^n),$$
 where $\omega_n$ stands for the measure of the unit ball in $\R^n$.
  By their construction, the functions $u$, $u^*$ e $u^\sharp$ have the same distribution function, or equi-distributed, and it holds
$$ \displaystyle{\norma{u}_{p}=\norma{u^*}_{p}=\lVert{u^\sharp}\rVert_{p}}, \quad \text{for all } p\ge1.$$


The absolute continuity of $\mu_u$ is ensured by the following lemma (we refer, for instance, to \cite{BZ,CF2}).

\begin{lemma}

Let $u\in W^{1,p}(\R^n)$, with $p\in(1,+\infty)$. The distribution function $\mu_u$ of $u$ is absolutely continuous if and only if 
\begin{equation*}
    \abs{\{0<u<  ||u^\sharp||_\infty\}\cap \{|\nabla u^\sharp| =0\}}=0.
\end{equation*}

\end{lemma}

The decreasing rearrangement has a lot of useful inequality such as the Hardy-Littlewood inequality, see \cite{HLP}. 

\begin{theorem}[Hardy-Littlewood inequaliy]
Let us consider $h\in L^p(\Omega)$ and $g\in L^{p'}(\Omega)$. Then 
    \begin{equation*}
 \int_{\Omega} \abs{h(x)g(x)} \, dx \le \int_{0}^{\abs{\Omega}} h^*(s) g^*(s) \, ds.
\end{equation*}
\end{theorem}
Furthermore, if we assume that the function $u$ is a \emph{Sobolev function}, i.e. $u\in W^{1,p}_0(\Omega)$, then also $u^\sharp$ is a Sobolev function and its gradient does not increase under symmetrization, as a consequence of the  P\'olya-Szegő inequality (see \cite{PS}).
\begin{theorem}[P\'olya-Szegő inequality]

    Let $u \in W^{1,p}_0(\Omega)$, then $u^{\sharp} \in W^{1,p}_0(\Omega^\sharp)$ and
	\begin{equation}\label{poliaszego}
		\lVert \nabla u^{\sharp} \rVert_{p} \leq \norma{\nabla u}_{p}.
	\end{equation}
\end{theorem}
Also, we recall the notion of pseudo-rearrangement of a function, introduced in \cite{AT}. Given $u$ measurable function in $\Omega$, $\forall s  \in [0, |\Omega|]$ we can find a subset $D(s)$ such that:
    \begin{enumerate}
        \item $|D(s)|=s$;
        \item  $s_1 \leq s_2
        \implies D(s_1)\subset D(s_2)$;
        \item $D(s)= \{x \in \Omega : \, |u(x)| >t\}$ if $s = \mu_u(t)$.
    \end{enumerate}
    Moreover, if $f\in L^p(\Omega)$ then \[\int_{D(s)}f(x)\,dx\] is an absolutely continuous function of $s$, so it exists a function $F$ such that \[\int_0^sF(t)\,dt=\int_{D(s)}f(x)\,dx.\] In particular, the following lemma \cite[Lemma 2.2]{AT} holds
    \begin{lemma}\label{pseudorearr}
        Let $f\in L^p(\Omega),p>1$. There is a sequence $\{F_k(s)\}$ of functions which have the same rearrangement $f^*$ of $f$, such that \[F_k(s)\rightharpoonup F(s)\quad\text{in }L^p(0,|\Omega|)\]
        If $f\in L^1(\Omega)$, it follows that: \[\lim_k\int_0^{|\Omega|}F_k(s)g(s)\,ds=\int_0^{|\Omega|}F(s)g(s)\,ds\] for each function $g$ belonging to the space $BV(0,|\Omega|)$.
    \end{lemma}
\subsection{Inequalities for the Torsional Rigidity}
Let  us recall Buonocore's result in \cite{B}, that is a generalization for general degenerate elliptic operator in any dimension of \eqref{polyaweinstein}. To state it, we need the following definition.
\begin{definizione}
\label{torsion-buonocore}
    Let $\Omega$ satisfy definition \ref{multiplyconnected} and let $\{a_{ij}(x)\}_{i,j=1,\dots,n}$ be a symmetric matrix, such that \begin{equation*}
    a_{ij}(x)\xi_i\xi_j\geq\nu(x)\abs{\xi}^2,\quad x\in\Omega
    \end{equation*}
    with $\nu(x)\geq0,\nu\in L^1(\Omega),\nu^{-1}\in L^p(\Omega)$ for some $p>1$.

We define the quantity
\begin{equation*}
    T(\Omega,a_{ij})= \max\left\{ \frac{\displaystyle \left(\int_G \varphi\, dx\right)^2}{\displaystyle \int_Ga_{ij} \varphi_{x_i}\varphi_{x_j} \,dx} : \, \varphi \in H^1_0(G), \varphi\equiv \text{ constant on }  \Omega_i \, \forall i=1, \dots m  \right\}.
\end{equation*}
We will denote by $T(\Omega)=T(\Omega,\delta_{ij})$.

\end{definizione}
Hence we get the following theorem.
\begin{theorem}\label{buonocore}

Let $\Omega$ satisfy definition \ref{multiplyconnected}, let $\{a_{ij}(x)\}_{i,j=1,\dots,n}$ be a symmetric matrix, such that \begin{equation*}
    a_{ij}(x)\xi_i\xi_j\geq\nu(x)\abs{\xi}^2,\quad x\in\Omega
    \end{equation*}
    with $\nu(x)\geq0,\nu\in L^1(\Omega),\nu^{-1}\in L^p(\Omega)$ for some $p>1$ and $T(\Omega,a_{ij})$ as in Definition \ref{torsion-buonocore}.

If $\Omega^\OO 
=G^\sharp \setminus S^\sharp $, then
$$T(\Omega,a_{ij})\leq T(\Omega^\OO,\delta_{ij}).$$
\end{theorem}


\begin{oss}
The Euler-Lagrange equation of the functional $T(\Omega,a_{ij})$, as shown in \cite{B,PW}, see also \cite{BS,K}, is given by \begin{equation}\label{torsionprob}
        \begin{cases}
            -\left(a_{ij}z_{x_i}\right)_{x_j}=1 & \text{ in } \Omega \\
            z = 0 & \text{on } \partial \Omega \\
            z=c_i & \text{on } \partial \Omega_i
        \\ \displaystyle{\int_{\partial \Omega_i} \frac{\partial z}{\partial  \nu } \, d\sigma =\abs{\Omega_i} }& \forall i=1,\dots m.\end{cases}
    \end{equation}  

    Hence, if $\tilde u$ is the maximum of $T(\Omega,a_{ij})$, then its restriction to $\Omega$ is solution to \eqref{torsionprob}.

    The constants $(c_1,\dots,c_m)\in\R^m$ for which problem \eqref{torsionprob} admits a unique solution are unknown and are determined a posteriori.

\end{oss}

\begin{oss}
    For the sake of readability, we point out that the function $V$  defined as follows
    \begin{equation}\label{defV}
      V(x)=n^{-2}\omega_n^{-\frac{2}{n}}\int_{\omega_n\abs{x}^n}^\abs{G}r^{-1+\frac{2}{n}}\left(\nu^*\left(r-\abs{S}\right)\right)^{-1}\,dr
    \end{equation}
it turns out to be the only minimum of the symmetrized problem given by 
    \begin{equation}
    	\label{probsimm}
        \begin{cases}
            \displaystyle{-\left(\nu^*\left(\omega_n\abs{x}^n-\abs{S}\right)V_{x_i}\right)_{x_i}=1} & \text{ in } \Omega^\OO \\
            \displaystyle{V = 0} & \text{on } \partial G^\sharp \\
            \displaystyle{V=n^{-2}\omega_n^{-\frac{2}{n}}\int_{\abs{S}}^\abs{G}r^{-1+\frac{2}{n}}\left(\nu^*\left(r-\abs{S}\right)\right)^{-1}\,dr} & \text{on } \partial S^\sharp
        \end{cases}
    \end{equation}
\end{oss}


Using the notion of pseudorearrangement \ref{pseudorearr} for $\nu^{-1}$ holds the following approximation result
\begin{lemma}\label{approx}
    There is a sequence $\{v_k(s)\}$ of functions such that $v_k^*(s)=\nu^*(s)$ and $\{v^{-1}_k(s)\}$ is weakly convergent in $L^p(0,\abs{\Omega})$ to $v^{-1}$.
\end{lemma}
Also, is useful to recall the definition of the function $\zeta^{-1}$ given in \cite{B} which allows to explicitly write a solution to \eqref{torsionprob}. Setting \[I_h=\left(\mu(c_h)+\sum_{k=h+1}^m\abs{\Omega_k},\mu(c_{h})+\sum_{k=h}^m\abs{\Omega_k}\right),\quad h=1,\dots,m-1\]
\[J_h=\left(\mu(c_h)+\sum_{k=h}^m\abs{\Omega_k},\mu(c_{h-1})+\sum_{k=h}^m\abs{\Omega_k}\right),\quad h=1,\dots,m\]
using notation of lemma \ref{approx} we define
\begin{equation*}\zeta^{-1}_k(r)=\begin{cases}
    \displaystyle{v_k^{-1}(r)} & \text{ if } r\in\left(0,\mu(c_m)\right)\\
    \displaystyle{0} & \text{ if } r\in\left(\mu(c_m),\mu(c_m)+|\Omega_m|\right) \quad \text{or }r\in I_h\\
    \displaystyle{v_k^{-1}\left(r-\sum_{k=h}^m\abs{\Omega_k}\right)} & \text{ if } r\in J_h
\end{cases} \end{equation*}
which, again by lemma \ref{approx}, weakly converges in $L^p$ to
\begin{equation} \label{zeta}
    \zeta^{-1}(r)=\begin{cases}
    \displaystyle{v^{-1}(r)} & \text{ if } r\in\left(0,\mu(c_m)\right)\\
    \displaystyle{0} & \text{ if } r\in\left(\mu(c_m),\mu(c_m)+|\Omega_m|\right)\quad \text{or }r\in I_h\\
    \displaystyle{v^{-1}\left(r-\sum_{k=h}^m\abs{\Omega_k}\right)} & \text{ if } r\in J_h
\end{cases}
\end{equation}
Moreover, by isoperimetric inequality the following point-wise inequality holds \cite{B}
  \begin{equation}\label{puntuale}
      \Tilde{u}^*(s)\leq w(s)=n^{-2}\omega_n^{-\frac{2}{n}}\int_s^\abs{G}r^{-1+\frac{2}{n}}\zeta^{-1}(r)\,dr,\quad s\in(0,\abs{G}).
  \end{equation}
Also, using the $\zeta^{-1}$ and \eqref{puntuale} the inequality \eqref{polyaweinstein} can be rewritten as
\begin{equation}\label{saintven}
    T(\Omega,a_{ij})\leq\frac{1}{2n^2\omega_n^{-\frac{2}{n}}}\int_0^{\abs{G}}s^\frac{2}{n}\zeta^{-1}(s)\,ds\leq\frac{1}{2n^2\omega_n^{-\frac{2}{n}}}\int_{\abs{S}}^{\abs{G}}s^\frac{2}{n}(\nu^*(s-\abs{S}))^{-1}\,ds=T(\Omega^\OO,\delta_{ij}).
\end{equation}


\begin{corollario}\label{puntualedim2}
    If $n=2$, and $\tilde u$  is the maximum of $T(\Omega,a_{ij})$, we have
    \[\tilde u^\sharp(x)\leq V(x),\quad x\in\Omega^\sharp.\]
\end{corollario}

