\subsection{Quantitative inequalities}
\label{subsection2.3}
The technique to prove our main theorem is to apply some quantitative inequalities and then estimate how the distance from the optimum propagates. Denoting by $\alpha(\Omega)$ the Fraenkel's asymmetry index \begin{equation*}
	\alpha(\Omega):=\min_{x \in \R^{n}}\bigg \{  \dfrac{|\Omega\triangle B_r(x)|}{|B_r(x)|} \;,\; |B_r(x)|=|\Omega|\bigg \} \text{ where } |\Omega\triangle B_r(x)|= |(\Omega\setminus B_r(x)) \cup ( B_r(x)\setminus\Omega)|,
\end{equation*}
 we have the following quantitative isoperimetric inequality, proved in \cite{FMP2} (see also \cite{FMP,H,CL,Fuglede}).


\begin{theorem}
    There exists a constant $\gamma_n$ such that,  for any measurable set $\Omega$ of finite measure
    \begin{equation}\label{quant_isop}
        P(\Omega)\geq n\omega_n^{\frac{1}{n}}\abs{\Omega}^{\frac{n-1}{n}}\left(1+\dfrac{\alpha^2(\Omega)}{\gamma_n}\right),
    \end{equation}
where
$$\gamma_n= \frac{181\, n^7}{(2-2^{(n-1)/n})^{\frac{3}{2}}}.$$
\end{theorem}

The asymmetry propagation from the whole domain to the superlevel sets is not trivial, nevertheless we can use the following result (see for instance \cite[Lemma 2.8]{BD}) which does an estimate on the propagation outside. 

\begin{lemma}\label{propasi}
    Let $\Omega\subset\R^n$ be an open set with finite measure and $U\subset\Omega$ a subset of positive measure such that \[\frac{|\Omega\backslash U|}{|\Omega|}\leq\frac{1}{4}\alpha(\Omega)\]
    then holds that \[\alpha(U)\geq\frac{1}{2}\alpha(\Omega)\]
\end{lemma}
Another key ingredient is the quantitative version of P\'olya-Szeg\H o
inequality \eqref{poliaszego}, proved in \cite{CFET}.
\begin{theorem}[Quantitative P\'olya-Szeg\H o
inequality]
\label{polya_quant}
    Let $u\in W^{1,2}(\R^n)$, $n\geq 2$. Then, there exist  positive constants $r$, $s$ and $C$, depending only on $n$,  such that, for every $u\in W^{1,2}(\R^n)$, it holds
\begin{equation*}
   \inf_{x_0 \in \R^n} \dfrac{\displaystyle{\int_{\R^n} \abs{u(x)\pm u^\sharp(x+x_0)} \, dx }}{\abs{\{u>0\}}^{\frac{1}{n}+\frac{1}{2}}\norma{\nabla u^\sharp}_2}\leq C(n) \left[M_{u^\sharp}(E(u)^r)+E(u)\right]^s,
\end{equation*}
where 
\begin{equation}\label{eumu}
E(u)= \frac{\displaystyle{\int_{\R^n} \abs{\nabla u}^2}}{\displaystyle{\int_{\R^n} |\nabla u^{\sharp}|^2}}-1 \qquad \text{ and } \qquad M_{u^\sharp}(\delta)=\dfrac{\abs{\left\{|\nabla u^{\sharp}|<\delta\right\}\cap \left\{0<u^\sharp<||u||_\infty\right\}}}{\abs{\{\abs{u}>0\}}}.
\end{equation}
\end{theorem}
Lastly we recall, also, the sharp quantitative inequality for the torsional rigidity (see \cite{BDV}) in the case of homogeneous Dirichlet boundary condition
\begin{theorem}
    There exists a constant $C$ depending only on the dimension $n$, such that for every open set $\Omega\subset\R^n$ with finite measure we have
    \[\abs{B}^{-\frac{n+2}{n}}T(B)-\abs{\Omega}^{-\frac{n+2}{n}}T(\Omega)\geq C\mathcal{A}^2(\Omega).\]
\end{theorem}
\section{ Rigidity of the problem}\label{section3}
As already mentioned in the introduction, we prove Proposition \ref{propmerc} in a more general setting. Let u and v be solutions to \ref{torsionprob} and \ref{probsimm} respectively. Then we have

\begin{theorem}\label{teorig}
Let $\Omega$ satisfy definition \ref{multiplyconnected}. Let $n\geq 2$,  $\nu\in L^1(\Omega),\nu^{-1}\in L^p(\Omega)$ for some $p>1$, and u and v  be  solutions to \ref{torsionprob} and \ref{probsimm} respectively. Then if 
 $$T(\Omega,a_{ij})=T(\Omega^\OO,\delta_{ij}),$$
 necessarily $\Omega= \Omega^\OO+ x_0$, $u=u^\sharp(\cdot +x_0)$, $\nu=\nu^\sharp(\cdot +x_0)$  and $a_{ij}(x+x_0)x_j=\nu(x)x_i$ for some $x_0 \in \R^n$.
\end{theorem}

It is clear that the Proposition \ref{propmerc} is a particular case when $n=2$ and $a_{ij}= \delta_{ij}$.

Before proving the rigidity, we recall the following adapted version of the Brothers and Ziemer theorem contained in \cite{BM}.

\begin{theorem}\label{brotherziemer}
    Let $u$ be a non negative function in $W_0^{1,p}(\Omega)$ with $1<p<\infty$ and
    \[\abs{\{x:\nabla u^\sharp(x)=0\}\cap u^{\sharp^{-1}}(0,\norma{u}_\infty)}=0.\]
    Let $\psi$ be a non negative measurable function such that the level sets of $\psi$ are the level sets of $u$ and $\int_\Omega\psi(x)\abs{\nabla u}^p(x)\,dx<+\infty$. If the following equality holds:
    \[\int_\Omega\psi(x)\abs{\nabla u}^p(x)\,dx=\int_{\Omega^\sharp}\psi^\sharp(x)\abs{\nabla u^\sharp}^p(x)\,dx,\]
    then there is a translate of $u^\sharp$ which is almost everywhere equal to $u$.
\end{theorem}
Now we are able to prove the rigidity result.

\begin{proof}[Proof of Theorem  \ref{teorig}]
        In the equality case, the inequality \eqref{saintven} gives:
    \begin{equation*}
        \int_0^\abs{G}s^\frac{2}{n}\zeta^{-1}(s)\,ds=\int_\abs{S}^\abs{G}s^\frac{2}{n}\left(\nu^*\left(s-\abs{S}\right)\right)^{-1}\,ds=\int_0^\abs{G}s^\frac{2}{n}\overline{\nu}(s)\,ds
    \end{equation*}
    where $\overline{\nu}$ is defined as the extension at zero of $\nu^*$ that is:
    \begin{equation*}
        \overline{\nu}(s)=\begin{cases}
            0 & \text{ if } s\in(0,\abs{S})\\
            \left(\nu^*\left(s-\abs{S}\right)\right)^{-1} &\text{ if }s\in(\abs{S},\abs{G})
        \end{cases}.
    \end{equation*}
    Now, given that $s^\frac{2}{n}$ is non negative, strictly monotone and absolutely continuous, follows
    \begin{equation*}
        \zeta^{-1}(s)=\overline{\nu}(s)\qquad \text{a.e. in }[0,\abs{G}],
    \end{equation*}
   which gives $\tilde u^\sharp\leq \tilde V$ (by \eqref{defV} and \eqref{puntuale}) and the assumption ensures the equality $\tilde u^\sharp=\tilde V$. \\ On the other hand, equality in the (isoperimetric) inequality \eqref{puntuale} gives:
    \begin{equation*}
        -\frac{d}{dt}\int_{\abs{u}>t}\nu\abs{\nabla u}^2\,dx=-\frac{d}{dt}\int_{\abs{u}>t}a_{ij}u_{x_i}u_{x_j}\,dx,
    \end{equation*}
    and together with $\displaystyle{\int_{u >\norma{u}_\infty}\nu\abs{\nabla u}^2\,dx=\int_{\abs{u}>\norma{u}_\infty}a_{ij}u_{x_i}u_{x_j}\,dx}=0$, it  yields to
    \begin{equation}\label{equalitytorsioni}
        \int_\Omega\nu\abs{\nabla u}^2\,dx=\int_\Omega a_{ij}u_{x_i}u_{x_j}\,dx=T(\Omega).
    \end{equation}
     But equality holds, so \eqref{equalitytorsioni} and $u^\sharp=V$ (hence the vanishes only on the top level) give:
    \begin{equation}\label{equalityint}
        \int_{\Omega^\OO}\nu^*\left(\omega_n\abs{x}^n-\abs{S}\right)\abs{\nabla u^\sharp}^2\,dx=\int_\Omega\nu\abs{\nabla u}^2\,dx.
    \end{equation}
    By theorem \ref{brotherziemer}, up to translations, we have 
    \[\Omega= \Omega^\OO \quad \text{ and } \quad
    u = \pm u^\sharp.
    \]
    Hence, \eqref{equalityint} becomes 
    \begin{equation*}
        \int_{\Omega^\OO}\nu^*\left(\omega_n\abs{x}^n-\abs{S}\right)\abs{\nabla u}^2\,dx=\int_{\Omega^\OO}\nu\abs{\nabla u}^2\,dx,
    \end{equation*}
    which gives $\nu=\nu^\ast$. From \eqref{equalitytorsioni}, we finally get
    $$a_{i,j}(x+x_0)x_i=\nu(x)x_j,$$
    for some $x_0$.

\end{proof}
\section{Asymmetry of the exterior domain}\label{section4}

This section is devoted to proving that the Fraenkel asymmetry index for the exterior domain $G$ can be controlled by the deficit in the P\'olya-Weinstein inequality. 

 To this aim we recall the definition of $s_G$, given in \cite{BD}
    \begin{equation*}
        s_{G}=\sup\left\{ t\geq 0: \mu_{\tilde u}(t)\geq \abs{G}\left(1-\dfrac{\alpha(G)}{4}\right)\right\} \in \R,
    \end{equation*}
then, it holds the following lemma.
\begin{lemma}
Let $\Omega\subset\R^n$ satisfy definition \ref{multiplyconnected} then, it holds
    \begin{equation}
        \label{essamitorsion}
         T(\Omega^\OO)- T(\Omega)\geq s_G\abs{G}\frac{\alpha(G)^2}{8\gamma_n},
    \end{equation}

    where $\gamma_n$ is the constant appearing in the quantitative isoperimetric inequality \eqref{quant_isop}.
\end{lemma}
\begin{proof} We  assume that $\alpha(G)>0$, otherwise the result is trivial. 
    Let us apply the quantitative isoperimetric inequality \eqref{quant_isop} to the level set $\{\Tilde{u}>t\}$ and, then, argue as in the proof of Theorem \ref{buonocore},

    \begin{equation*}
        \begin{aligned}
       n^2\omega_n^{\frac{2}{n}}\mu_{\tilde u}^{2-\frac{2}{n}}(t)\left(1+\dfrac{2}{\gamma_n}\alpha^2(\tilde u>t)\right)&\le n^2\omega_n^{\frac{2}{n}}\mu_{\tilde u}^{2-\frac{2}{n}}(t)\left(1+\dfrac{1}{\gamma_n}\alpha^2(\tilde u>t)\right)^2\leq P^2(\tilde u>t) \\
       &\leq -\mu_{\tilde u}'(t) \nu[\mu_{\tilde u}(t)] \left(- \frac{d}{dt} \int_{\tilde u>t}\abs{\nabla u}^2\, dx\right).
        \end{aligned}
    \end{equation*}
    If we divide by $n^2\omega_n^{\frac{2}{n} }\mu_{\tilde u}^{2-\frac{2}{n}}(t)$ and we integrate between $0$ and $\tau$, we get
    \begin{equation*}
            \tau+\dfrac{2}{\gamma_n}\int_0^{\tau}\alpha^2(\tilde u>t)\;dt\leq n^{-2}\omega_n^{-\frac{2}{n}}\int_{\mu_{\tilde u}(\tau)}^{\abs{G}}r^{-1+\frac{2}{n}}\zeta^{-1}(r)\,dr,
    \end{equation*}
    Also, using the Hardy-Littlewood inequality and the lemma \eqref{approx} we obtain
    \begin{equation*}
        \tau+\dfrac{2}{\gamma_n}\int_0^{\tau}\alpha^2(\tilde u>t)\;dt\leq n^{-2}\omega_n^{-\frac{2}{n}}\int_{\mu_{\tilde u}(\tau)}^{\abs{G}}r^{-1+\frac{2}{n}} \nu^\ast (r-\abs{S})^{-1} \, dr.
    \end{equation*}    

    The last, due to the definition of decreasing rearrangement, can be written as
    \begin{equation}\label{fine}
        \dfrac{2}{\gamma_n}\int_0^{\tilde u^*(r)}\alpha^2(\tilde u>t)\;dt \leq n^{-2}\omega_n^{-\frac{2}{n}}\int_{r}^{\abs{G}}t^{-1+\frac{2}{n}} \nu^\ast (t-\abs{S})^{-1} \, dt-\tilde u^*(r)=\tilde V(r)-\tilde u^\ast(r).
    \end{equation}
   \begin{comment}
        Indeed, the last implies
$$
 \tau \leq  v^\ast (\mu(\tau)) - \dfrac{2}{\gamma_n}\int_0^{u^\ast(\mu (\tau))}\alpha^2(U_t)\;dt,
$$
and since $u^\ast(r) =\inf\{\tau |\, \mu(\tau )<r\}$
\begin{align*}
    u^\ast(r)& =\inf\{\tau |\, \mu(\tau )<r\} \\ &\leq \inf  \left\{ v^\ast (\mu(\tau)) - \dfrac{2}{\gamma_n}\int_0^{u^\ast(\mu (\tau))}\alpha^2(U_t)\;dt|\, \mu(\tau )<r\right\} \\
    & \leq \inf  \left\{ v^\ast (\mu(\tau))|\, \mu(\tau )<r\right\} - \dfrac{2}{\gamma_n}\int_0^{u^\ast(r)}\alpha^2(U_t)\;dt\\
    & \leq v^\ast(r) - \dfrac{2}{\gamma_n}\int_0^{u^\ast(r)}\alpha^2(U_t)\;dt.
\end{align*}
  \end{comment}
We define the set
     \begin{equation*}
    A:= \left\{   
 t\geq 0: \mu_{\tilde u}(t)\geq \abs{G}\left(1-\dfrac{\alpha(G)}{4}\right)  \right\},\end{equation*}
then $0 \in A$  whenever $\alpha(G)>0$, and it is an interval since $\mu_{\tilde u}$ is a decreasing function.  Moreover, for all $t\in A$, it holds

 \begin{equation*}
     \frac{\abs{G \setminus \{\tilde u>t\}}}{\abs{G}}=1-\frac{\mu_{\tilde u}(t)}{\abs{G}}\le \frac{1}{4} \alpha(G).
 \end{equation*}
 Therefore, we can apply Lemma \ref{propasi} and we get \begin{equation*}
     \alpha(\tilde u>t)\geq \frac{\alpha(G)}{2}\qquad \forall t \in A.
 \end{equation*}
 On the other hand, from \eqref{fine}, integrating from $[0, \abs{G}]$, it follows
 \begin{equation*}
   s_G\abs{G}\left(1-\frac{\alpha({G})}{4}\right)\frac{\alpha({G})^2}{4\gamma_n}\leq \int_0^{\abs{G}} \left(\tilde V(r)-\tilde u^*(r)\right) = T(\Omega^\OO)- T(\Omega).
 \end{equation*}


\end{proof}
It remains to bound from below the quantity $s_G$ in terms of asymmetry using the approach contained in \cite{Kim}. 

Let us spend a few more words on the additional assumption $\abs{S} \leq \frac{3}{4} \abs{G}$: it might seem weird, but if $S$ is allowed to be closer and closer to $G$, then the torsion of $G\setminus S$ is getting closer and closer to 0.
	This remark suggests us that an assumption about the ratio between the measure of $G$ and that of $S$ is necessary.

\begin{prop}\label{lemma4.2}
   Let $\Omega\subset\R^2$ satisfy definition \ref{multiplyconnected}. If $$\abs{S} \leq \frac{3}{4}\abs{G}$$ then
    \[
    T(\Omega^\OO)- T(\Omega)\geq \frac{\abs{G}^2 }{2^9 \pi \gamma_2} {\alpha(G)^3}.\]
\end{prop}

\begin{proof}
     We have to set $t_1$ such that 
    $$
   \mu_{\tilde V}(2t_1) = \abs{G}\left(1- \frac{1}{8} \alpha(G)\right).
    $$
    By $\abs{S} \leq \frac{3}{4}\abs{G}$, we have $\mu_{\tilde V}(2t_1) \geq \abs{S}$.

    Therefore, it holds the following bound
    \begin{equation*}
        \begin{aligned}
        \frac{\abs{G}}{8} \alpha(G) &=\abs{G}-\abs{G}\left(1- \frac{1}{8} \alpha(G)\right)= \mu_{\tilde V}(0)- \mu_{\tilde V}(2t_1)=- \int_{0}^{2t_1} \mu_{\tilde V}'(s)\,ds\\&= \int_{0}^{2t_1} {4\pi}= 8\pi t_1.
    \end{aligned}
    \end{equation*}
    Now let us distinguish 2 cases:
    \begin{itemize}
        \item $s_G \geq t_1 \geq C \alpha(G)$ then from \eqref{essamitorsion}, we obtain
        \begin{equation}\label{caso1}
         T(\Omega^\OO)- T(\Omega)\geq  \dfrac{\abs{G}^2}{2^9\pi\gamma_2} \alpha^3(G);
        \end{equation}
        \item $s_G <t_1$, then by \ref{puntualedim2}, we have
        \begin{equation}
        \label{93}
        T(\Omega^\OO)-T(\Omega) = 
              {\lVert\tilde V\rVert_1}-{\norma{\tilde u}_1}  = \int_0^{\norma{\tilde V}_\infty} \left(\mu_{\tilde V}(t)-\mu_{\tilde u}(t)\right)\, dt \geq \int_{t_1}^{2t_1} \left(\mu_{\tilde V}(t)-\mu_{\tilde u}(t)\right)\, dt.
        \end{equation}
        Since $s_{G} < t_1 \leq t \leq 2t_1$, we have both
        \begin{equation}
        \label{nufinale}
        \mu_{\tilde V}(t) \geq \mu_{\tilde V}(2t_1)= \abs{G}\left(1- \frac{1}{8} \alpha(G)\right),
        \end{equation}
        and
        \begin{equation}\label{mufinale}
            \mu_{\tilde u}(t) \leq \abs{G}\left(1- \frac{1}{4} \alpha(G)\right).
        \end{equation}

        Consequently, combining \eqref{nufinale}, \eqref{mufinale} and \eqref{93} we have
        \begin{equation}\label{caso2}
        \begin{aligned}
            {\lVert\tilde V\rVert_1}-{\norma{\tilde u}_1}&\geq \int_{t_1}^{2t_1} \left(\mu_{\tilde V}(t)-\mu_{\tilde u}(t)\right)\, dt\geq \frac{\abs{G}}{2^3} \alpha(G)\int_{t_1}^{2t_1} \, dt\\&\geq 
            \frac{\abs{G}}{2^3} \alpha(G)t_1 = 
            \frac{\abs{G}^2}{2^9\pi} \alpha^2(G) 
            \geq
            \frac{\abs{G}^2}{2^{10}\pi} \alpha^3(G),
        \end{aligned}
        \end{equation}   
    \end{itemize}
    hence, the thesis follows by choosing as a constant the minimum between \eqref{caso1} and \eqref{caso2}.
\end{proof}

\section{Asymmetry of the holes}\label{section5}

This section is devoted to proving that the Fraenkel asymmetry index for the  holes $S$ can be controlled by the deficit in the P\'olya-Weinstein inequality.  

We are going to prove this property by substituting the role of $S$ with $\tilde S= D(\abs{S})$, using the definition of $D(s)$ given in Section 2, and proving the following two Lemmas, for the asymmetry of $\tilde S$ and the difference of $S \setminus \tilde S$.


\begin{lemma}\label{lemma5.1}
	Let $\Omega\subset\R^2$ satisfy definition \ref{multiplyconnected}. Let $\tilde{S}=D(\abs{S})$ then 
\begin{equation*}
		T(\Omega^\OO)-T(\Omega) \geq \frac{\abs{S}}{4\pi}\abs{S\setminus\tilde{S}}
\end{equation*}

\end{lemma}

\begin{lemma}\label{lemma5.2}
	Let $\Omega\subset\R^2$ satisfy definition \ref{multiplyconnected}. Let $\tilde{S}=D(\abs{S})$ then 
\begin{equation*}
T(\Omega^\OO)-T(\Omega) \geq \frac{\abs{S}^2\alpha(\tilde{S})^3}{3^22^4\pi \gamma_ 2}.
\end{equation*}
\end{lemma}

Let us start with Lemma \ref{lemma5.1}. 


\begin{proof}[Proof of Lemma \ref{lemma5.1}]
	By definition, \begin{equation*}      T(\Omega^\OO)=\int_0^\abs{G}\tilde V^\ast(s)\,ds=\int_\abs{S}^\abs{G}V^\ast(s)\,ds+V^\ast(0)\abs{S}
	\end{equation*}
	and by remark \ref{puntualedim2}
	\begin{equation*}
		T(\Omega)=\int_0^\abs{G}\tilde u^\ast(s)\,ds\leq \int_\abs{S}^\abs{G}\tilde u^\ast(s)\,ds+V^\ast(0)\abs{S}.
	\end{equation*}
	Hence, using the definition above and \eqref{puntuale} the term $T(\Omega^\OO)-T(\Omega)$ can be bounded from below as
	\begin{equation*}
		T(\Omega^\OO)-T(\Omega)\geq\int_\abs{S}^\abs{G}V^\ast(s)-\tilde u^\ast(s)\,ds\geq \frac{1}{4\pi}\int_\abs{S}^\abs{G}\int_s^\abs{G} \nu^\ast(r)^{-1}-\zeta^{-1}(r)\,dr\,ds
	\end{equation*}
	and exchanging the order of integration gives
	\begin{equation*}
		T(\Omega^\OO)-T(\Omega)\geq\frac{1}{4\pi}\int_\abs{S}^\abs{G}\int_0^r
		\nu^\ast(r)^{-1}-\zeta^{-1}(r)\,dr\,ds\geq\frac{\abs{S}}{4\pi}\int_\abs{S}^\abs{G}1-\zeta^{-1}(r)\,dr,
	\end{equation*}
	the last equality is due to $\nu^\ast(r)^{-1}=1$ whenever $r\geq\abs{S}$. But the definition \eqref{zeta} of $\zeta^{-1}$ characterizes the integrand term as
	\begin{equation}\label{1-zeta}
		1-\zeta^{-1}(r)=\begin{cases}
			\displaystyle{0} & \text{ if } r\in\left(0,\mu(c_m)\right)\\
			\displaystyle{1} & \text{ if } r\in\left(\mu(c_m),\mu(c_m)+|\Omega_m|\right) \text{or }r\in I_h\\
			\displaystyle{0} & \text{ if } r\in J_h
		\end{cases}.
	\end{equation}
	Thus, the integral of \eqref{1-zeta} is
	\begin{equation*}
		T(\Omega^\OO)-T(\Omega)\geq\frac{\abs{\tilde{S}}}{4\pi}\left(\sum_{h:\mu(c_h)>\abs{\tilde{S}}}\abs{\Omega_h}+\mu(c_k)+\abs{\Omega_k}-\abs{\tilde{S}}\right)=\frac{\abs{S}}{4\pi}\abs{\bigcup_{i=1}^m\Omega_i\setminus\tilde{S}}
	\end{equation*}
	whereas the term out of the summation appears in the case where exists some $1\leq k\leq m$ such that $\mu(c_k)<\abs{\overline{S}}<\mu(c_k)+\abs{\Omega_k}$ and moreover $\abs{\tilde S}=\abs{S}$ by definition. 
 %    Now let us distinguish two cases, \begin{itemize}
	% 	\item If $\abs{S}<\varepsilon^\alpha$ for some $\alpha\in\R$ then \[\abs{\bigcup_{i=1}^m\Omega_i\setminus\tilde{S}}\leq\abs{S}\varepsilon^\alpha\].
	% 	\item If $\abs{S}>\varepsilon^\alpha$ for some $\alpha\in\R$ then \[\abs{\bigcup_{i=1}^m\Omega_i\setminus\tilde{S}}\leq4\pi\frac{\varepsilon}{\abs{S}}=4\pi\varepsilon^{1-\alpha}.\]
	% \end{itemize}
	% Therefore the theorem holds with the choice $\alpha=\frac{1}{2}$.
\end{proof}

 Now the idea is to obtain an estimate on the asymmetry of $\tilde S=D(\abs{S})$ by "propagating" the asymmetry between level set as in \cite{BD}. However, now propagation must be done outward and is possible by exploiting the following adaptation of the Lemma \ref{propasi}.
\begin{lemma}\label{propasiback}
    Let $\Omega\subset U$ such that \[\frac{\abs{U\setminus\Omega}}{\abs{\Omega}}\leq\frac{1}{4}\alpha(\Omega)\] then it holds: \[\alpha(U)\geq\frac{1}{3}\alpha(\Omega).\]
\end{lemma}
\begin{proof}
    Let $B$ the ball that achieves the minimum in the definition of $\alpha(U)$, by the triangle inequality we get
    \begin{equation*}
        \begin{aligned}
            \alpha(U)=\frac{\abs{U\triangle B}}{\abs{U}}\geq\frac{\abs{\Omega}}{\abs{U}}\left(\frac{\abs{\Omega\triangle B}}{\abs{\Omega}}-\frac{\abs{U\triangle \Omega}}{\abs{\Omega}}\right)\geq \frac{2}{3}\left(\frac{\abs{\Omega\triangle B'}}{\abs{\Omega}}-\frac{\abs{B\triangle B'}}{\abs{\Omega}}-\frac{\abs{U\triangle \Omega}}{\abs{\Omega}}\right)\geq\\ \geq \frac{2}{3}\left(\alpha(\Omega)-2\frac{\abs{U\setminus\Omega}}{\abs{\Omega}}\right)\geq \frac{1}{3}\alpha(\Omega),
        \end{aligned}
    \end{equation*}
    where $B'$ is a ball concentric to $B$ that has the same measure of $\Omega$. By using that 
    \[\abs{U\triangle\Omega}=\abs{U\setminus\Omega}=\abs{U}-\abs{\Omega}=\abs{B\triangle B'},\] and noticing that the assumption on the measure is equivalent to \[\frac{\abs{\Omega}}{\abs{U}}\geq\frac{1}{1+\frac{1}{4}\alpha(\Omega)}.\] Lastly, the conclusion follows by the property that $\alpha(\Omega)\geq 2$.
\end{proof}
Let us define again the threshold as
\begin{equation*}
\begin{aligned}
        s_{\tilde{ S}}&=\inf\left\{ \tau \leq u^\ast\left(\abs{S}\right): \mu_{\tilde u}(\tau)\leq \abs{ S }\left(1+\dfrac{\alpha(\tilde S )}{4}\right)\right\}\\
    &=\sup\left\{ \tau \leq u^\ast\left(\abs{S}\right): \mu_{\tilde u}(\tau)> \abs{ S }\left(1+\dfrac{\alpha(\tilde S )}{4}\right)\right\} \in \R
    \end{aligned}
\end{equation*}
then, it holds the following lemma.
\begin{lemma}
Let $\Omega\subset\R^2$ satisfy definition \ref{multiplyconnected} then, it holds
    \begin{equation}
        \label{essastorsion}
         T(\Omega^\OO)- T(\Omega)\geq  (u^\ast\left(\abs{S}\right) -s_{\tilde{S}})2\abs{S}\frac{\alpha(\tilde{ S})^2}{9\gamma_n},
    \end{equation}

    where $\gamma_n$ is the constant appearing in the quantitative isoperimetric inequality \eqref{quant_isop}.
\end{lemma}
\begin{proof} We  assume that $\alpha(\tilde{ S})>0$, otherwise the result is trivial. 
    Let us apply the quantitative isoperimetric inequality \eqref{quant_isop} to the level set $\{\Tilde{u}>t\}$ and, then, argue as in the proof of Theorem \ref{buonocore},

    \begin{equation*}
        \begin{aligned}
       n^2\omega_n^{\frac{2}{n}}\mu_{\tilde u}^{2-\frac{2}{n}}(t)\left(1+\dfrac{2}{\gamma_n}\alpha^2(\tilde u>t)\right)&\le n^2\omega_n^{\frac{2}{n}}\mu_{\tilde u}^{2-\frac{2}{n}}(t)\left(1+\dfrac{1}{\gamma_n}\alpha^2(\tilde u>t)\right)^2\leq P^2(\tilde u>t) \\
       &\leq -\mu_{\tilde u}'(t) \nu[\mu_{\tilde u}(t)] \left(- \frac{d}{dt} \int_{\tilde u>t}\abs{\nabla u}^2 \, dx\right).
        \end{aligned}
    \end{equation*}
    If we divide by $n^2\omega_n^{\frac{2}{n} }\mu_{\tilde u}^{2-\frac{2}{n}}(t)$ and we integrate between $0$ and $\norma{u}_\infty$, we get
    \begin{equation*}
            \tau+\dfrac{2}{\gamma_n}\int_0^{\tau}\alpha^2(\tilde u>t)\;dt\leq n^{-2}\omega_n^{-\frac{2}{n}}\int_{\mu_{\tilde u}(\tau)}^{\abs{G}}r^{-1+\frac{2}{n}}\zeta^{-1}(r)\,dr,
    \end{equation*}
    Also, using the Hardy-Littlewood inequality and the lemma \eqref{approx} we obtain
    \begin{equation*}
        \tau+\dfrac{2}{\gamma_n}\int_0^{\tau}\alpha^2(\tilde u>t)\;dt\leq n^{-2}\omega_n^{-\frac{2}{n}}\int_{\mu_{\tilde u}(\tau)}^{\abs{G}}r^{-1+\frac{2}{n}} \nu^\ast (r-\abs{S})^{-1} \, dr.
    \end{equation*}    

    The last, due to the definition of decreasing rearrangement, can be written as
    \begin{equation}\label{finebuchi}
        \dfrac{2}{\gamma_n}\int_0^{\tilde u^*(r)}\alpha^2(\tilde u>t)\;dt \leq n^{-2}\omega_n^{-\frac{2}{n}}\int_{r}^{\abs{G}}t^{-1+\frac{2}{n}} \nu^\ast (t-\abs{S})^{-1} \, dt-\tilde u^*(r)=\tilde V(r)-\tilde u^\ast(r).
    \end{equation}
We define the set
     \begin{equation*}
    A_{\tilde{S}}:= \left\{ \tau \leq u^\ast\left(\abs{S}\right): \mu_{\tilde u}(\tau)\leq \abs{ S }\left(1+\dfrac{\alpha(\tilde S )}{4}\right)\right\} ,\end{equation*}
then $u^\ast\left(\abs{S}\right) \in A$, and it is an interval since $\mu_{\tilde u}$ is a decreasing function.  Moreover, for all $\tau\in A$, it holds

 \begin{equation*}
     \frac{\abs{\tilde{S} \setminus \{\tilde u>\tau\}}}{\abs{S}}=\frac{\mu_{\tilde u}(\tau)}{\abs{S}}-1\le \frac{1}{4} \alpha(\tilde{S}).
 \end{equation*}
 Therefore, we can apply Lemma \ref{propasiback} and we get \begin{equation*}
     \alpha(\tilde u>\tau)\geq \frac{\alpha(\tilde{S})}{3}\qquad \forall \tau \in A.
 \end{equation*}
 On the other hand, from \eqref{finebuchi}, integrating from $[0, \abs{G}]$, it follows 
 \begin{equation*}
     \begin{aligned}
         \int_0^\abs{G} \tilde V(r)-\tilde u^\ast(r)\,dr\geq\dfrac{2}{\gamma_n}\int_0^\abs{G}\int_0^{\tilde u^\ast(r)}\alpha^2(\tilde u>t)\;dt\,dr\geq\dfrac{2}{\gamma_n}\int_0^{\abs{ S }\left(1+\frac{\alpha(\tilde S )}{4}\right)}\int_{s_{\overline{S}}}^{\tilde u^\ast(r)}\alpha^2(\tilde u>t)\;dt\,dr \\  \geq \dfrac{2}{9\gamma_n}\alpha^2(\tilde{S})\int_0^{\abs{ S }\left(1+\frac{\alpha(\tilde S )}{4}\right)} \tilde u^\ast(r)-s_{\tilde{S}}\,dr \\ \geq \dfrac{2}{9\gamma_n}\alpha^2(\tilde{S})\int_0^{\abs{S}} \tilde u^\ast(r)-s_{\tilde{S}}\,dr.
     \end{aligned}
 \end{equation*}
Lastly, using the definition of $\tilde{S}$ yields to:
 \begin{equation*}
 T(\Omega^\OO)- T(\Omega)= \int_0^{\abs{G}} \left(\tilde V(r)-\tilde u^*(r)\right)  \geq  (u^\ast\left(\abs{S}\right) -s_{\tilde{S}})2\abs{S}\frac{\alpha({\tilde{S}})^2}{9\gamma_n}.
 \end{equation*}
\end{proof}
Again using the techniques contained in \cite{Kim} we are able to saturate the threshold $s_{\tilde S}$ in term of the asymmetry, proving Lemma \ref{lemma5.2}
\begin{proof}[Proof of Lemma \ref{lemma5.2}]
    We have to set $t_1$ such that
    \begin{equation*}
        \mu_{\tilde V}(\tilde V(\abs{S})-2t_1)=\abs{S}\left(1+\frac{1}{4}\alpha(\tilde{S})\right).
    \end{equation*}
    Therefore, it holds the following bound
    \begin{equation*}
        \begin{aligned}
            \frac{\abs{S}\alpha(\tilde{S})}{4}=\abs{S}\left(1+\frac{1}{4}\alpha(\tilde{S})\right)-\abs{S}=\mu_{\tilde V}(\tilde V(\abs{S})-2t_1)-\mu_{\tilde V}(\tilde V(\abs{S}))=\\-\int_{V(\abs{S})-2t_1}^{V(\abs{S})}\mu_{\tilde V}'(s)\,ds=4\pi\int_{V(\abs{S})-2t_1}^{V(\abs{S})}\,ds=8\pi t_1,
        \end{aligned}
    \end{equation*}
    also the pointwise comparison gave us a bound on $s_{\tilde{S}}$ as
    \begin{equation}\label{boundss}
        \tilde V(\abs{S})-2t_1=\tilde V\left(\abs{S}\left(1+\frac{1}{4}\alpha(\tilde{S})\right)\right)\geq\tilde u^\ast\left(\abs{S}\left(1+\frac{1}{4}\alpha(\tilde{S})\right)\right)=s_{\tilde{S}}.
    \end{equation}
    Now let us distinguish two cases:
    \begin{itemize}
        \item if $\tilde V(\abs{S})-\tilde u^\ast(\abs{S})<t_1$ then from \eqref{boundss} and \eqref{essastorsion}, we obtain
        \begin{equation*}
            {\tilde u}^\ast(\abs{S})-s_{\overline{S}}\geq\tilde u^\ast(\abs{S})-\tilde V(\abs{S})+2t_1\geq -t_1+2t_1=\frac{\abs{S}\alpha(\tilde{S})}{2^5\pi},
         \end{equation*}
        hence 

         \begin{equation*}
              T(\Omega^\OO)-T(\Omega)\geq   (u^\ast\left(\abs{S}\right) -s_{\tilde{S}})2\abs{S}\frac{\alpha({\tilde{S}})^2}{9\gamma_n} \geq \frac{\abs{S}^2\alpha(\tilde{S})^3}{3^22^4\pi \gamma_ 2}.
         \end{equation*}
         \item if $\tilde V(\abs{S})-\tilde u^\ast(\abs{S})\geq t_1$, we claim that \begin{equation}
             \label{claimbho}T(\Omega^\OO)-T(\Omega)\geq 2 \pi \left(\tilde V(\abs{S})-\tilde u^\ast(\abs{S})\right)^2
             ,\end{equation} from which we obtain
         \begin{equation*}
             T(\Omega^\OO)-T(\Omega)\geq 2 \pi \left(\tilde V(\abs{S})-\tilde u^\ast(\abs{S})\right)^2\geq 2 \pi t_1^2\geq \frac{2 \pi}{2^{10} \pi^2}\abs{S}^2\alpha(\tilde{S})^2\geq \frac{\abs{S}^2\alpha(\tilde{S})^3}{2^{10} \pi}.
         \end{equation*}

