By combining Lemmas \ref{lemma5.1} and \ref{lemma5.2}, we obtain the desired asymmetry control for holes.

\begin{prop}\label{prop5.5}
	Let $\Omega\subset\R^2$ satisfy definition \ref{multiplyconnected}. Then 
	\begin{equation*}
	T(\Omega^\OO)-T(\Omega) \geq \frac{\abs{S}^2\alpha^3(S)}{3^22^9\pi \gamma_ 2}.
	\end{equation*}
\end{prop}

\begin{proof}
	Let $B$ be the ball which realizes $\alpha(\tilde{ S})$, then it is sufficient to observe that 
	$$
	\abs{S}  \alpha(S)\leq \abs{S\triangle B}\leq \abs{\tilde{ S}\triangle B} + \abs{S\triangle \tilde{ S}}	= \abs{\tilde{ S}\triangle B} + 2 \abs{S\setminus \tilde{ S}} \leq 2\left(\abs{\tilde{ S}} \alpha(\tilde{ S})+ \abs{S\setminus \tilde{ S}}\right).$$

    Indeed, by Lemmas \ref{lemma5.1} and \ref{lemma5.2}, and the last property, we have
    \begin{equation*}
        \begin{aligned}
           	T(\Omega^\OO)-T(\Omega) &\geq \frac{\abs{S}}{4\pi}\abs{S\setminus\tilde{S}} +\frac{\abs{S}^2\alpha(\tilde{S})^3}{3^22^4\pi \gamma_ 2} \\
        &\geq \frac{1}{3^22^4\pi \gamma_ 2 \abs{S}}  \left[\abs{S\setminus\tilde{S}}^3 +\abs{S}^3\alpha(\tilde{S})^3\right]\\
         &\geq \frac{1}{3^22^6\pi \gamma_ 2 \abs{S}}  \left[\abs{S\setminus\tilde{S}}+\abs{S}\alpha(\tilde{S})\right]^3\\
         &\geq \frac{1}{3^22^9\pi \gamma_ 2 \abs{S}}  \left[\abs{S}\alpha(S)\right]^3.
        \end{aligned}
    \end{equation*}
	\end{proof}

Theorem \ref{thm:dueasimmetrie} follows by combining Propositions \ref{lemma4.2} and \ref{prop5.5}.
\section{Almost radiality of the solution and conclusion}\label{section6}

This section will focus on the almost radiality of the solution.
The idea is similar to the one exploited in \cite{ABMP}, with some appropriate adaptations.

As a first step, we need to prove that the function 
\begin{equation}
\label{doppiav}
    w(x):= \min\{u(x), \, \tilde u^\ast(\abs{S})\}
\end{equation}
has the Polya-Szego deficit controlled via the torsion deficit $T(\Omega^\OO) -T(\Omega)$.

We observe that for $w(x)$ the following properties holds
\begin{enumerate}
    \item $\Big\lvert \{w\geq \tilde u^\ast(\abs{S})\}\Big\rvert\geq \abs{S}$;
    \item $\displaystyle{\int_G \abs{\nabla w}^2 \, dx \leq  \int_G \abs{\nabla u}^2 \, dx }$;
    \item $\displaystyle{w(x)\leq u(x) \leq w(x) + \chi_{D(\abs{S})}\left(\tilde V(\abs{S})-\tilde u^\ast(\abs{S})\right)}$.
\end{enumerate}
Hence we have
\begin{lemma}
\label{lem_grad}
     Let $\Omega\subset\R^2$ satisfy definition \ref{multiplyconnected}. Let $u$ and $v$ be the torsion function of $\Omega$ and $\Omega^\OO$ respectively. 

     Then 
\begin{equation}
\label{tops}
\int_{\Omega}\abs{\nabla w}^2-\int_{\Omega^\sharp}|\nabla w^\sharp|^2\leq \frac{6\abs{G}}{\sqrt{2\pi}}\left(T(\Omega^\OO) - T(\Omega)\right)^\frac{1}{2}.
\end{equation}
\end{lemma}
\begin{proof}
We observe that the torsion function of $\Omega^\OO$ is the unique minimizer of
\begin{equation*}
    -T(\Omega^\OO)= \min\left\{\int_{G^\sharp}\abs{\nabla\varphi}^2\,dx - 2\int_{G^\sharp} \varphi\, dx  : \, \varphi \in H^1_0(G^\sharp), \varphi\equiv  \, \text{constant on }  S^\sharp \right\}.
\end{equation*}
Hence we have 
\begin{equation*}
\int_G\,|\nabla w|^2-\int_{G} w \geq \int_{G^{\sharp}}\,|\nabla w^\sharp|^2-\int_{G^\sharp} w^\sharp\geq \int_{G^{\sharp}}\abs{\nabla \tilde V}^2-\int_{G^\sharp}v.
\end{equation*}
By the Buonocore's inequality,

$$  T(\Omega)=\int_{G}\abs{\nabla u}^2\le \int_{G^\sharp}\abs{\nabla \tilde V}^2=T(\Omega^\OO),$$ 
and the H\"older inequality, we obtain
\begin{equation*}
    \begin{aligned}
\int_{G}\abs{\nabla w}^2-\int_{G^\sharp}|\nabla w^\sharp|^2 &\leq \int_{G^\sharp}\abs{\nabla u}^2-\int_{G^\sharp}|\nabla u^\sharp|^2 \\ &\leq \int_{G^\sharp}\abs{\nabla \tilde V}^2-\int_{G^\sharp}|\nabla u^\sharp|^2\\
&\leq 2\int_{G^\sharp}(v-w^\sharp) \, dx\\
&\leq 2\int_{G^\sharp}\left(v-u^\sharp + \chi_{D(\abs{S})}\left(\tilde V(\abs{S})-\tilde u^\ast(\abs{S})\right)\right) \, dx \\
&\leq 2 \left( T(\Omega^\OO) - T(\Omega)\right) + 2 \abs{S} \left( T(\Omega^\OO) - T(\Omega)\right)^\frac{1}{2}
\end{aligned}
\end{equation*}
where the last inequality follows from \eqref{claimbho}.  
The thesis follows by direct calculations, reminding that $T(\Omega^\OO) = \frac{1}{2\pi}\left( \abs{G}^2- \abs{S}^2 \right)$.
\end{proof}

In particular, \eqref{tops} suggests that the P\'olya-Szeg\H o inequality holds true almost as an equality when $T(\Omega^\OO) - T(\Omega)$ is small enough. So it is natural to consider the P\'olya-Szeg\H o quantitative inequality, recalled in Theorem \ref{polya_quant}.


Now, to prove the show that $w$ to $w^\sharp$ are close it is enough to prove that, for every positive $\delta$, the quantity $M_{w^{\sharp}}(\delta)$, defined in \eqref{eumu}, can be estimated from above by some power of $\delta$. This is not true in general for every Sobolev function, but it holds for $w$ because it is a truncation of the torsion function of $\Omega$.

The main idea to bound from above the quantity $M_{w^{\sharp}}(\delta)$ is to write the set $A:=\{\nabla w^\sharp < \delta\} \cap \{0 <w^\sharp < {\tilde u}^\ast(\abs{S})\}$ as the union of suitable subsets, and to bound from above the measure of each of them. In order to do that, in Lemma \ref{lemmaI}
 we define a set $I\subseteq [0,{\tilde u}^\ast(\abs{S})]$ and, in \eqref{t_epsilon}, we define a positive number $t_{\varepsilon,\beta}\in{[0, {\tilde u}^\ast(\abs{S})]}$, so that we have

\begin{align*}
   A=&\Big( A\cap w^{\sharp-1}(I^c\cap (0,t_{\varepsilon,\beta})\Big)\\
    &\cup\Big(A\cap w^{\sharp-1}(I\cap (0,t_{\varepsilon,\beta})\Big)\\
    &\cup\Big(A\cap w^{\sharp-1}(t_{\varepsilon,\beta}, +\infty)\Big).
\end{align*}


We will prove next Lemmas and Propositions under the additional assumptions
$$ \abs{G}=1, \quad T(\Omega^\OO) - T(\Omega)=:\varepsilon \le \varepsilon_0, $$ where $\varepsilon_0$ will be suitably chosen later.


\begin{lemma} \label{lemmaI}
Let us fix $0<\alpha<\frac{1}{2}$, let $\varepsilon:=T(\Omega^\OO) - T(\Omega)$ and let us define 
the set $I$ as follows
   \begin{equation}
\label{I}
I=\left\{t \in [0, \tilde u (\abs{S})] :\,\int_{\tilde V = t}\abs{\nabla \tilde V}-\int_{w^\sharp=t}\abs{\nabla w^\sharp}>\varepsilon^\alpha\right\}.
\end{equation}
    Then,    
    \begin{equation}\label{I_bound}
        \abs{I}\le \frac{6\abs{G}}{\sqrt{2\pi}}  \varepsilon^{\frac{1}{2}-\alpha},
    \end{equation}
and, for every  $t\in I^c$,  it holds
\begin{equation}
\label{gradient}
\int_{\tilde V = t}\abs{\nabla \tilde V}\;-\int_{w^\sharp=t}|\nabla w^\sharp|\leq \varepsilon^{\alpha}.
\end{equation}

\end{lemma}
\begin{proof}
Claim \eqref{gradient}  is a direct consequence of the definition of the set $I$ in \eqref{I}. Moreover, using  the Coarea formula \eqref{coarea}, we have
\begin{align*}
    \varepsilon^{\alpha}\abs{I}\leq \int_{I}\biggl(\int_{\tilde V = t}\abs{\nabla \tilde V}-\int_{\{w^\sharp=t\}}|\nabla w^\sharp|\biggr)&\leq \int_0^{+\infty}\biggl(\int_{\tilde V = t}\abs{\nabla \tilde V}-\int_{w^\sharp=t}|\nabla w^\sharp|\biggr)\\&=\int_{\Omega^\sharp}\abs{\nabla \tilde V}^2-\int_{\Omega^\sharp}|\nabla w^\sharp|^2<\frac{6\abs{G}}{\sqrt{2\pi}} \varepsilon^\frac{1}{2}, 
    \end{align*}
and claim \eqref{I_bound} follows.
\end{proof}
\begin{lemma}
   Let $\delta>0$ and let  $\tilde V$ be the extension of the solution to \eqref{probsimm}. Then, there exists a positive constant $K$ such that
    \begin{equation*}
        \abs{\{\abs{\nabla \tilde V}\leq\delta\}\cap (G^\sharp\setminus S^\sharp)}\leq K \delta^2.
    \end{equation*}
\end{lemma}
\begin{proof}
    By direct computation, from \eqref{probsimm}, we have that $\abs{\nabla \tilde V}(x)= \abs{x}$ if $\omega_2\abs{x}^2 \geq \abs{S}$, otherwise it is zero. 

    Hence,
    \begin{itemize}
        \item if $\omega_2\delta^2 < \abs{S}$ we have 
          \begin{equation*}
        \{\abs{\nabla \tilde V}\leq\delta\}=S^\sharp;
    \end{equation*}
      \item if $\omega_2\delta^2 \geq \abs{S}$ we have 
      \begin{equation*}
        \{\abs{\nabla \tilde V}\leq\delta\} = \{\abs{x}\leq\delta\}.
    \end{equation*}


    \end{itemize}
    In any case, 
      $$\abs{\{\abs{\nabla \tilde V}\leq\delta\}\cap G^\sharp\setminus S^\sharp}\leq K \delta^2 - \abs{S}\leq K \delta^2 .$$
\end{proof}
\begin{lemma} Let $w$ be the function defined in \eqref{doppiav}.
 If we define the following quantity
\begin{equation}
    \label{t_epsilon}
    t_{\varepsilon,\beta}=\sup\left\{t>0\;:\;\;\mu_w(t)>\varepsilon^{2\beta}\right\},
\end{equation}
then, for every $\delta>0$, it holds     \begin{equation*}
        \abs{\{ A \cap w^{\sharp-1}(I^c\cap (0,t_{\varepsilon,\beta}) }\leq\pi\left(\delta+\frac{\varepsilon^{\alpha-\beta}}{2\sqrt{\pi}}\right)^2.
    \end{equation*}
\end{lemma}
\begin{proof}
    By direct computation, property \eqref{gradient} in \ref{lemmaI} is equivalent to
    \begin{equation}\label{Icomplementare}
        P(\tilde V = t)\abs{\nabla \tilde V}(y)-P(w^\sharp=t)\abs{\nabla w^\sharp}(x)\leq\varepsilon^\alpha,
    \end{equation}
    for every $y\in\{\tilde V = t\}$ and $x\in\{w^\sharp=t\}$. If we fix $x\in\{w^\sharp=t\}$ and we consider $y=\ell(t)x,$ where $\displaystyle{\ell(t)=\left(\frac{\mu_{\tilde V}(t)}{\mu_{\tilde u}(t)}\right)^\frac{1}{2}}$, we have that $y\in\{\tilde V=t\}$. Thus by pointwise comparison, the monotonicity of the distribution function and the properties of $w$ we have that
    \begin{equation*}
        P(\tilde V = t)\geq P(w^\sharp=t)=2(\pi\mu_w(t))^{\frac 1 2}\geq2\sqrt{\pi}\varepsilon^{\beta },
    \end{equation*}
    which implies in \eqref{Icomplementare} that
    \begin{equation}\label{diffgrad}
        \abs{\nabla \tilde V}(\ell(t)x)-\abs{\nabla w^\sharp}(x)\leq\frac{\varepsilon^\alpha}{2\sqrt{\pi}\varepsilon^{\beta}}=\frac{\varepsilon^{\alpha-\beta}}{2\sqrt{\pi}} .
    \end{equation}
    Moreover, combining \eqref{diffgrad}, the definition \eqref{defV} and the fact that $\ell(t)\geq1$ we have
    \begin{equation*}
        \abs{x}-\abs{\nabla w^\sharp}(x)\leq\abs{\nabla \tilde V}(\ell(t)x)-\abs{\nabla w^\sharp}(x)\leq\frac{\varepsilon^{\alpha-\beta}}{2\sqrt{\pi}}, \quad\forall x\in w^{\sharp-1}(I^c \cap (0, t_{\varepsilon,\beta})).
    \end{equation*}
    Which implies that 
    \begin{equation*}
        A\cap w^{\sharp-1}(I^c\cap (0, t_{\varepsilon,\beta}))\subseteq\left\{\abs{x}\leq\delta+\frac{\varepsilon^{\alpha-\beta}}{2\sqrt{\pi}}\right\}.
    \end{equation*}
\end{proof}

\begin{oss}
We observe that 
\begin{equation*}
\abs{w^{\sharp-1}(t_{\varepsilon,\beta}, +\infty)}\le\varepsilon^{2\beta},
\end{equation*}
indeed
    $$\mu_w(t_{\varepsilon,\beta})=\lim_{t\rightarrow t_{\varepsilon,\beta}^+}\mu_w(t)\leq \varepsilon^{2\beta},$$
    since $\mu_w$ is right continuous.
\end{oss}


\begin{lemma}
    Let $w$ be the function defined in \eqref{doppiav}. Then for every $0<q<\frac12-\alpha $, we have 

\begin{equation*}
     \abs{w^{\sharp-1}(I) \cap \{0 <w^\sharp < {\tilde u}^\ast(\abs{S})\}} \leq  K \varepsilon^{2q}+2\sqrt{\pi}\varepsilon^{\frac 1 2 - \alpha -q}. 
\end{equation*}
\end{lemma}
\begin{proof}
    Arguing as in the proof of \ref{buonocore}, by the isoperimetric inequality and Fleming-Rishel formula we get
    \begin{equation*}
        \frac{1}{4\pi}(-\mu_{\tilde V}'(t)) =\frac{1}{4\pi}(-\mu_{\tilde V}'(t))\nu^{\ast-1}(\mu_{\tilde V}(t))\leq\frac{1}{4\pi}(-\mu_{\tilde u}'(t))\zeta^{-1}(\mu_{\tilde u}(t)) \leq \frac{1}{4\pi}(-\mu_{\tilde u}'(t)), \qquad \forall t>0.
    \end{equation*}
    Therefore, we obtain
    \begin{equation*}
        -\mu_{\tilde u}'(t)\geq-\mu_{\tilde V}'(t)\quad\forall t\in I^c,
    \end{equation*}
    which gives us
    \begin{equation}\label{immagineic}
    \begin{aligned}
        \abs{w^{\sharp-1}(I^c) \cap \{0 <w^\sharp < {\tilde u}^\ast(\abs{S})\}}&=\abs{w^{\sharp-1}(I^c) \cap \left\{ \abs{ \nabla w^\sharp}=0 \right\}} + \int_{I^c}-\mu_{\tilde u}'(t)\,dt \\ &\geq \int_{I^c}-\mu_{\tilde u}'(t)\,dt\\&\geq\int_{I^c}-\mu_{\tilde V}'(t)\,dt=\abs{\tilde V^{-1}(I^c) \cap (G^\sharp\setminus S^\sharp)}.
    \end{aligned}
    \end{equation}
    So, using \eqref{immagineic} we have that
    \begin{equation*}
    \begin{aligned}
         \abs{w^{\sharp-1}(I) \cap \{0 <w^\sharp < {\tilde u}^\ast(\abs{S})\}}&=\abs{G^\sharp \setminus  \{0 <w^\sharp < {\tilde u}^\ast(\abs{S})\}}-\abs{w^{\sharp-1}(I^c) \cap \{0 <w^\sharp < {\tilde u}^\ast(\abs{S})\}}\\ &\leq \abs{G^\sharp \setminus  S^\sharp)}-\abs{\tilde V^{-1}(I^c)\cap G^\sharp\setminus S^\sharp}=\abs{\tilde V^{-1}(I)\cap G^\sharp\setminus S^\sharp},
    \end{aligned}
    \end{equation*}
    but the last term can be bounded as follows
    \begin{equation*}
        \begin{aligned}
           \abs{\tilde V^{-1}(I)\cap G^\sharp\setminus S^\sharp}&=\int_I\int_{\tilde V = t}\frac{1}{\abs{\nabla \tilde V}}\,d\mathcal{H}^{n-1}\,dt\\&=\int_I\int_{\{\tilde V = t\}\cap\{\abs{\nabla \tilde V}\leq\delta\}}\frac{1}{\abs{\nabla \tilde V}}\,d\mathcal{H}^{n-1}\,dt+\int_I\int_{\{\tilde V = t\}\cap\{\abs{\nabla \tilde V}>\delta\}}\frac{1}{\abs{\nabla \tilde V}}\,d\mathcal{H}^{n-1}\,dt\\&\leq\abs{\{\abs{\nabla \tilde V}\leq\delta\} \cap (G^\sharp \setminus S^\sharp)}+\frac{1}{\delta}\int_I2\pi\left(\frac{\mu_{\tilde V}(t)}{\pi}\right)^\frac{1}{2}\,dt\\&\leq\abs{\{\abs{\nabla \tilde V}\leq\delta\}\cap (G^\sharp \setminus S^\sharp)}+\frac{2\sqrt{\pi}}{\delta}\abs{I}\\&\leq K \delta^2+\frac{2\sqrt{\pi}}{\delta}\varepsilon^{\frac 1 2 - \alpha}.
        \end{aligned}
    \end{equation*}

    The thesis follows by choosing $\delta=\varepsilon^q$ with $0<q<\frac 1 2- \alpha$.
\end{proof}


\begin{prop}\label{Musharp}
 Let $w$ be the function defined in \eqref{doppiav} and let $M_{w^\sharp}$ be the quantity defined in \eqref{eumu}. Then, for every $0<q \leq \frac{1}{2}- \alpha$, there exist $\theta=\theta(r)>0$ and $K$ such that

   $$ M_{w^\sharp}(\varepsilon^r)\leq K\varepsilon^{\theta}.$$
\end{prop}
\begin{proof}
We have 
\begin{align*}
   M_{w^\sharp}(\delta) =& \abs{\{\nabla w^\sharp < \delta\} \cap \{0 <w^\sharp < {\tilde u}^\ast(\abs{S})\}} = \abs{A} \\=&\abs{A\cap w^{\sharp-1}(I^c\cap (0,t_{\varepsilon,\beta})}\\
    &+\abs{A\cap w^{\sharp-1}(I\cap (0,t_{\varepsilon,\beta})}\\
    &+\abs{A\cap w^{\sharp-1}(t_{\varepsilon,\beta}, +\infty)}\\
    \leq &\abs{A\cap w^{\sharp-1}(I^c\cap (0,t_{\varepsilon,\beta})}
\\
&+\abs{w^{\sharp-1}(I) \cap \{0 <w^\sharp < {\tilde u}^\ast(\abs{S})\}}  
 +\mu_w(t_{\varepsilon,\beta}) 
\\ \leq &\pi\left(\delta+\frac{\varepsilon^{\alpha-\beta}}{2\sqrt{\pi}}\right)^2 + K \varepsilon^{2q}+2\sqrt{\pi}\varepsilon^{\frac 1 2 - \alpha -q}+ \varepsilon^{2\beta}.
\end{align*}
  So, evaluating $M_{u^\sharp}(\delta)$ in $\varepsilon^r$ with $r < \frac{1}{2}-\alpha$, we obtain
  $$M_{w^\sharp}(\varepsilon^r)\leq \pi\left(\varepsilon^r+\frac{\varepsilon^{\alpha-\beta}}{2\sqrt{\pi}}\right)^2 + K \varepsilon^{2q}+{2\sqrt{\pi}}\varepsilon^{\frac 1 2 - \alpha-q} + \varepsilon^{2\beta},$$
 so we can conclude, by setting

 $$\theta=\min\left\{ 2r, 2(\alpha-\beta),2q,\frac 1 2 - \alpha-q, 2\beta  \right\},$$
obtaining the desired claim for a positive constant $K$.
\end{proof}
Hence, combining the previous results we have
\begin{theorem}
\label{anellia}
    Let $u$ be the maximizer of \eqref{torsione} and $\tilde u$ its constant extension. Then, there exists two positive constants $\tilde \theta$ and $\tilde C$ such that
    \[
    \inf_{x_0\in\R^n}\norma{\tilde u-\tilde u^\sharp(\cdot+x_0)}_{L^1(\R^n)}\leq\tilde C\varepsilon^{\tilde \theta}.
    \]
\end{theorem}
\begin{proof}
  By the definition of  $w$ in \eqref{doppiav}, we have that 
    \begin{equation*}
        w(x)\leq u(x)\leq w(x)+\chi_{\tilde S}(\tilde V(\abs{S})-\tilde u^*(\abs{S})),
    \end{equation*}
    but also
    \begin{equation*}
        w^\sharp(x)\leq u^\sharp(x)\leq w^\sharp(x)+\chi_{ S^\sharp}(\tilde V(\abs{S})-\tilde u^*(\abs{S})),
    \end{equation*}
    where $\tilde S=D(\abs{S})$ and $\tilde V$ is the extension of the solution to \eqref{probsimm}. 

    Hence
    \begin{equation*}
       w(x)- w^\sharp(x)-\chi_{ S^\sharp}(\tilde V(\abs{S})-\tilde u^*(\abs{S}))\leq u(x)-u^\sharp(x)\leq     w(x)- w^\sharp(x)+\chi_{ \tilde S}(\tilde V(\abs{S})-\tilde u^*(\abs{S})),
    \end{equation*}
    then, by integrating we have
    \begin{equation}\label{umenousharp}
        \int_{\R^n}\abs{\tilde u-\tilde u^\sharp}\,dx\leq \int_{\R^n}\abs{w-w^\sharp}\,dx+\abs{S}(\tilde V(\abs{S})-\tilde u^*(\abs{S})).
    \end{equation}
    On the other hand, by the theorem \ref{polya_quant} we have that exists two positive constants $r,s$ such that
    \begin{equation}\label{wmenowsharp}
        \inf_{x_0\in\R^n}\norma{w-w^\sharp(\cdot+x_0)}_{L^1(\R^n)}\leq C\left[M_{w^\sharp}(E(w)^r)+E(w)\right]^s,
    \end{equation}
    but now we are in position to apply estimates of lemmas \ref{lem_grad} and \ref{Musharp}. Therefore, by combining \eqref{umenousharp} and \eqref{wmenowsharp}
    \begin{equation*}
        \inf_{x_0\in\R^n}\norma{\tilde u-\tilde u^\sharp(\cdot+x_0)}_{L^1(\R^n)}\leq\overline C\varepsilon^{s\theta}+\frac{1}{2\pi}\varepsilon^\frac{1}{2},
    \end{equation*}
    where the bound of the last term follows from \eqref{claimbho} and we can conclude, by setting
    \begin{equation*}
        \tilde \theta=\min\left\{s\theta,\frac{1}{2}\right\},\qquad \tilde C=\max\left\{\overline C,\frac{1}{2\pi}\right\}.
    \end{equation*}
    Finally, we remove the additional assumption $\abs{G}=1$ using the rescaling properties of the torsional rigidity.
\end{proof}

Thanks to previous theorem we have that the torsion function $u$ (and also its truncated $w$) is almost symmetric, therefore each superlevel set is almost a ball. Then we can finally prove the  Theorem \ref{thm:anellia}


\begin{proof}[Proof of Theorem \ref{thm:anellia}]
As a by-product of P\'olya-Szeg\H o's quantitative inequality in \cite[Theorem 4.1]{CFET}, if $t \in G \cap(t_0,t_1)$ with $G$ defined in \cite{CFET}, such that $\abs{G^c} < \varepsilon^\theta$, and $$
\mu(t_1) < \eta^{2\overline \theta}, $$ we have that there exists two constants $C$ and $\gamma$ such that 
\begin{equation}\label{livelliu}
    \abs{\{w>t\}\triangle\{w^\sharp>t\}}\leq C\eta^\gamma,
\end{equation}
where
\begin{equation*}
    \eta=2M_{w}(0)+M_{w^\sharp}(\varepsilon^r)+6\sqrt{\pi}\frac{\varepsilon^\frac{1}{2}+\varepsilon^\frac{1}{4}}{\varepsilon^r}+\varepsilon^{2\alpha}.
\end{equation*}
Using lemma \ref{lemma5.1}, therefore we can bound \eqref{livelliu} as
\begin{equation*}
    \abs{\{w>t\}\triangle\{w^\sharp>t\}}\leq C\varepsilon^\vartheta \qquad \forall t \in G \cap(t_0,t_1).
\end{equation*}


 Hence, two cases can occur:
 \begin{itemize}
     \item if $\abs{S} < \eta^{2\overline{\theta}} = \varepsilon^{\theta_1}$, then \eqref{teoremabeta} follows;

     \item   if $\abs{S} >\eta^{2\overline{\theta}} = \varepsilon^{\theta_1}$ then we take $\overline{t}$ such that 
     $$
     \abs{\{w >\overline{t}\} \setminus S} \leq C\varepsilon^{\theta_2}.
     $$
     Hence, we set $B'$  such that $\abs{B'}=\abs{S}$ and $B''= \{w^\sharp >\overline{t}\}$, then we have
    \begin{equation*}
        \begin{aligned}
        \abs{S\setminus B'} &\leq \abs{(S\cap \{w>\overline{t}\}) \setminus B' } + \abs{S\setminus\tilde S} \\
        &\leq \abs{\{w>\overline{t}\} \setminus B' } + \abs{S\setminus\tilde S} \\
        &\leq \abs{\{w>\overline{t}\} \setminus B'' } + \abs{B''\setminus B'}+ \abs{S\setminus\tilde S} \leq  C\varepsilon^{\overline{\theta}}.
        \end{aligned}
    \end{equation*}
 \end{itemize}

Since, if we denote by $B'''$ the ball which realize $\alpha(G)$, then we have 
$$\beta(\Omega) \leq \abs{G \triangle B'''} + \abs{S \triangle B'},  $$
hence the thesis.  
    \end{proof}



