\section{A brief introduction to Hironaka's characteristic polyhedron}
\label{Sec:Hiro}


First, we give a short overview on Hironaka's characteristic polyhedron \cite{HiroCharPoly} in the special case of particular principal ideals which is the situation that we are interested in. 
Detailed introductions to the topic can be found in \cite[Chapter~8 and appendix]{CJS} as well as in \cite{CS-Compl}, for instance.




Let $ ( \cO, \mm, K ) $ be a regular local ring
with maximal ideal $ \mm $ and residue field $ K \simeq \cO/\mm $.
Let $f \in \mm $ be a non-zero element.
Recall that the order of $ f $ at $ \mm $ is defined as 
\[
	\nu := \nu_\mm(f) := \sup \{ \alpha \in \IZ_+ \mid f \in \mm^\alpha  \} .
\]


We make the assumption on $ f $ that there exists a regular system of parameters $ (x,y) = (x_1, \ldots, x_e,y) $ of $\cO $ such that
\begin{equation}
	\label{eq:Dir=1}
		f \equiv Y^\nu \mod \mm^{\nu+1}
\end{equation}
where $ Y := y \mod \mm^2 $ denotes the image of $ y $ in the graded ring $ \operatorname{gr}_\mm(\cO) = \bigoplus_{a \geq 0} \mm^a/\mm^{a+1} $.
In Remark~\ref{Rk:dir_dim_zero} we address how we reduce to this situation for $ 1 $-dimensional schemes essentially of finite type over a field. 
%
Since $ \cO $ is Noetherian, we have a {\em finite} expansion 
\[
	f = y^\nu + \sum_{(A,b)} c_{A,b} x^A y^b 
\] 
with $ c_{A,b} \in \cO^\times \cup \{ 0 \} $ and multi-index notation $ x^A = x_1^{A_1} \cdots x_e^{A_e} $,
see \cite[Proposition~2.1]{Cossart-Pitant}.




\begin{Def}
	\begin{enumerate}
		\item 
		The {\em projected polyhedron} of $ f $ with respect to $ (x;y) $ is defined as
		\[
		\Delta(f;x;y) \ := \
		\conv \left( \left\{ \frac{A}{\nu - b} + \IR_\gqz^e  \ \Big| \  c_{A,b} \neq 0 \right\} \right) , 
		\]
		where $ \conv (*) $ denotes the convex hull.

		\item 
		For a vertex $ v \in \Delta(f;x;y) $
		the {\em initial form of $ f $ at $ v $}
		is given by
		\[
		\ini_v (f) \ := \  Y^\nu + \sum_{(A,b) : \frac{A}{\nu- b} = v} \overline{c_{A,b}} X^A Y^b \ \in \  K[X,Y],
		\]
		where 
		$ \overline{c_{A,b}} $ are the images of the coefficients in the residue field $ K \simeq \cO/\mm $.


		\item 
		A vertex $ v \in \Delta (f;x;y) $ is called {\em solvable} if $ v \in \IZ_{\geq 0}^ e $ and there exists a (unique) $ \lambda \in K \smallsetminus \{ 0 \} $ such that
		$ \ini_v (f) = (Y-\lambda X^v)^\nu$. 
	\end{enumerate}
\end{Def}

Illustrative pictures of the projected polyhedron and the initial form at a vertex can be found in \cite[Examples 18.18, 18.23, and 18.31]{CJS}.

Suppose $ v $ is a solvable vertex. 
Let $ \epsilon \in \cO^\times $ be any lift of $ \lambda $ in $ \cO $, i.e., $ \epsilon \equiv \lambda \mod \mm $.  
If we set $ y' := y - \epsilon x^v $, then $ v \notin \Delta(f;x;y') $ and $  \Delta(f;x;y) \supsetneq  \Delta(f;x;y') $
by \cite[Lemma~(3.10)]{HiroCharPoly}.




\begin{Ex}
	Let $ \cO = K [[x,y]] $ be of dimension two for a field $ K $ of characteristic 2 and consider the polynomial $ f = y^2 + \lambda x^4  + x^5$
	with $ \lambda \in K $.
	The vertex of the projected polyhedron $ \Delta(f;x;y) $ is $ v = 2 $.

	If $ \lambda \in K^2 $ is a square, then $ v $ is solvable via the change $ y' := y + \mu x^2 $ with $ \mu \in K $ such that $ \mu^2 = \lambda $.
	The resulting polyhedron $ \Delta(f;x;y') $ has vertex $ v' = 5/2 $ which is not solvable.

	On the other hand, if $ K $ is imperfect and if $ [K^2 (\lambda):K^2] = 2 $, i.e., $ \lambda $ is not a square, then $ v = 2 $ is not solvable. 
\end{Ex}




For a non-empty convex subset $ \Delta \subseteq \IR_\gqz^e $, we define the number 
\[  
	\delta(\Delta) := \inf\{  v_1 + \cdots + v_e \mid (v_1, \ldots, v_e ) \in \Delta\} . 
\]
Furthermore we set $ \delta(\emptyset) := \infty $ 
and abbreviate $ \delta(f;x;y) :=  \delta(\Delta(f;x;y)) $.

Let us point out that $ \delta(f;x;y) = \infty $ if and only if $ f =\epsilon  y^\nu  $ for some unit $ \epsilon\in \cO $.
In this case the reduction of $ \{ f = 0 \} $ is regular.


\begin{Thm}
	\label{Thm:poly}
	Let $ f \in \mm $ be an element such that \eqref{eq:Dir=1} holds.
	\begin{enumerate}
	\item \label{It:char_poly}
	There is an element $ z \in \cO $ such that $ (x,z) $ is a regular system of parameters for $ \cO $ 
	and $ \Delta(f;x;z) $ is minimal with respect to inclusion among all possible $ \Delta(f;x;y) $ with $ (x,y) $ a regular system of parameters for $ \cO $.

	\item \label{It:delta_inv}
	The number $ \delta(f;x;z) $ 
	is an invariant of the singularity $ \cO/(f) $.
	\end{enumerate}
\end{Thm}

The minimal polyhedron $ \Delta(f;x) := \Delta(f;x;z) $ 
appearing in Theorem~\ref{Thm:poly}\eqref{It:char_poly}
is called {\em the characteristic polyhedron of $ f $}.
We emphasize that this is an ad-hoc definition. 
Originally, $ \Delta(f;x) $ is defined as the intersection over all possible projected polyhedra $ \Delta(f;x;y) $ with varying $ y $.


\begin{proof}[Proof of Theorem~\ref{Thm:poly}] 
	This follows from a combination of results from \cite{HiroCharPoly,Cossart-Pitant-compl,CJSch}:
Hironaka proved that in the $ \mm $-adic completion $ \widehat{\cO} $ there is an element $ \widehat{z} $ with $ \Delta(f;x;\widehat{z}) = \Delta(f;x) $ in \cite[Theorems~(3.17) and (4.8)]{HiroCharPoly}.
In \cite{Cossart-Pitant-compl} the existence of $ z \in \cO $, not necessitating completion, was shown for the given setting.
Generalizations followed in \cite{CS-Compl}.  
The second part on the invariant is proven in \cite[Corollary~B(3)]{CJSch}.
\end{proof} 




\begin{Def}
	\label{Def:Fdelta}
	Let $ f \in \cO $ be as above and let $ z $ be as in Theorem~\ref{Thm:poly}. 
	Set $ \delta := \delta(f;x;z)  $.
	The {\em $ \delta $-initial form} of $ f  = \sum_{(A,b)}  c_{A,b} x^A z^b $ is defined as 
	the initial form of $ f $ at the vertex $ \delta $, which can be rewritten as
	\[
	\ini_\delta(f)
	\ = \  
	\sum_{(A,b) \, : \, \frac{|A|}{\delta\nu} + \frac{b}{\nu} = 1} \overline{c_{A,b}} X^A Z^b.
	\]



	We introduce the following lift to $ \cO $ of the $ \delta $-initial form of $ f $:
	\[
		F_\delta \ :=  \  \sum_{(A,b) \, : \, \frac{|A|}{\delta\nu} + \frac{b}{\nu} = 1} c_{A,b} x^A z^b \in \cO.
	\]
\end{Def}






Observe that the definition of the lift depends on the choice of lifts for the coefficients of the initial forms from $ K = \cO/\mm $ to $ \cO $.
Since they  originate from certain elements $ c_{A,b} \in \cO^\times \cup \{ 0\} $, we choose them as the lifts.




\begin{Ex}
	\phantomsection
	\label{Ex:1_2_3}
	\begin{enumerate}
		\item \label{Ex:1_imperfect}
		Let $ \K $ be an imperfect field of characteristic $ p $ 
		and $ a \in  \K \smallsetminus \K^p $.
		Consider 
		\[  
			f \, = \, y^p- x_1^m (x_1^p + a)^{pm+1} - a x_2^{pm}
		 \ \in \ k[x_1,x_2,y] 
		\]
		with $ m > p  $ coprime to $ p $.

		At the closed point $ q $ given by the maximal ideal $ (x_1, x_2, y) $ 
		the residue field is equal to $ k $.
		The vertices of $ \Delta(f;x;y) $ are 
		$ v_1 := (\frac{m}{p}, 0) $ and $ v_2 := (0, m) $.
		Observe that $ \ini_{v_2} (f) = Y^p - a X_2^{pm} $ and since $ a \notin \K^p $, the vertex $ v_2 $ is not solvable. 
		Thus, none of the vertices is solvable and $  \Delta(f;x;y) =  \Delta(f;x) $ is the characteristic polyhedron (at $ q $).

		Let us look at the point $ \widetilde{q} $ corresponding to the maximal ideal $ (x_1^p + a , x_2, y) $.
		The residue field at this point is $ K := k [x_1]_{(x_1^p+a)}/(x_1^p +a)  $. 
		Possible local parameters at $ \widetilde{q} $ 
		are $ ( u_1 := x_1^p + a , x_2, y ) $.
		By substituting $ a = u_1 - x_1^p $,
		$ f $ can be rewritten as 
		\[
			f \,  = \, y^p- x_1^m u_1^{pm+1} - u_1 x_2^{pm} + x_1^p x_2^{pm} .
		\]
		Taking into account that $ x_1 $ is invertible at $ \widetilde q $,
		the vertices of the corresponding projected polyhedron $ \Delta(f;u_1, x_2;y) $ are 
		$ \widetilde{v_1} := (m+\frac{1}{p},0) $ and $ \widetilde{v_2} := (0, m)$.
		This time $ \widetilde{v_2} $ is solvable since $ \ini_{\widetilde{v_2}} (f) = Y^p + \overline{x_1}^p X_2^{pm} = (Y + \overline{x_1} X_2^m )^p $
		where  $ \overline{x_1} $  
		denotes the image of $ x_1 $ in the residue field $ K $.
		Introducing  $ z := y + x_1 x_2^{m} $
		the vertices of $ \Delta(f;u_1, x_2;  z) $
		are $ \widetilde{v_1} $ and $ \widetilde{v_3} := (\frac{1}{p},m) $.  
		Both vertices are not solvable and hence $ \Delta(f;u_1, x_2; z) = \Delta(f;u_1, x_2) $ is the characteristic polyhedron (at $ \widetilde q $).


		\item \label{Ex:2_localize}
		Let $ \K $ be a perfect field of positive characteristic $ p $
		and let $ \cO $ be the localization of $ \K[x,y,z] $ at the ideal $ (x,y) $. 
		Let $ m \in \IZ_+ $ with $ m > p $
		and 
		 \[ 
		 	f \, = \, y^{2p} + x^m y^p z^{m+p} + x^{2m} z^{p+1} + x^{2m-1} y  \ \in \ \cO .
		 \]
		Notice that $ (x,y) $ is a regular system of parameters for $ \cO $ and $ z $ is invertible in $ \cO $.
		The projected polyhedron $ \Delta(f;x;y) = \Delta (f;x)$ coincides with the characteristic polyhedron since the vertex is $ \delta = \frac{m}{p} $ which is not solvable. 

		We have $ \ini_\delta(f) = Y^{2p} + X^m Y^p \overline{z}^{m+p} + X^{2m} \overline{z}^{p+1} $,
		where $ \overline{z} $ denotes the image of $ z $ in the residue field $ \cO/ (x,y) $. 

	\end{enumerate}
\end{Ex}




























\section{Invariant, parameters, and center}\label{Sec:inv}






	In the next step, we define the invariant in the setting of Theorem~\ref{Thm:Main1} and deduce from this the designated center for the weighted blow-up.

	Let $ C \subset S $ be a hypersurface in a regular $ 2 $-dimensional scheme $ S $ which is essentially of finite type over a field $ k $
		and let $ q \in C $ be a singular closed point such that $ C_{\rm red} $ is singular at $ q $. 
	Let $ (\cO,\mm,K) $ be the local ring of $ C $ at $ q $
	and let $ f \in \mm $ be an element locally at $ q $ defining $ C $.
	Sometimes, we will abuse notation by writing $ C = \{ f = 0 \} $.








\begin{Rk}
	\label{Rk:dir_dim_zero}
	Let us address the situation if \eqref{eq:Dir=1} does not hold. 
	Then $ \ini_\mm(f) := f \mod \mm^{\nu+1} \in \operatorname{gr}_\mm(\cO) $ cannot be expressed as polynomial in a single variable.
	For readers familiar with Hironaka's notion of the directrix (for example, see~\cite[Definitions~2.8 and 2.26]{CJS}), the latter means that the dimension of the directrix is zero.
	Due to a result of Hironaka \cite[Theorem~2]{HiroAdditive} which was generalized by Mizutani \cite{Mizutani} (see also \cite[Theorem~3.14]{CJS})
	blowing up the closed point $ q $ will lead in this situation to a strict decrease of the order at points lying above $ q $.


	In the remainder of the article 
	we include the discussed case by setting $ \delta := 1 $ and $ \ini_\delta (f) := \ini_\mm (f) $ if  
	\eqref{eq:Dir=1} does not hold.
\end{Rk}












\begin{Def}
	Let $ q \in C \subset S $ be as before, locally given as $ q \in \{ f = 0 \} \subset \Spec(\cO) $. 
		The {\em invariant of $ C $ at $ q $} is defined as
		\[ 
			\inv_{C} ( q ) \, := \,  \inv_{f} (q) \, := \,  (a_1,a_2) \, := \,  (\nu, \delta\nu) \ \, \in \ \,  \Gamma \, := \,  \IZ_{\geq 0} \times \frac{1}{a_1!} \IZ_{\geq 0} ,
		\] 
		where $ \nu $ is the order of $ C $ at $ q $, $ \delta \in \IQ_+ $ is the number introduced in Theorem~\ref{Thm:poly}\eqref{It:delta_inv} (resp.~Remark~\ref{Rk:dir_dim_zero}),
			and $ \Gamma $ is equipped with the lexicographical ordering.
\end{Def} 

Recall that our assumption, $ C_{\rm red} $ is singular at $ q $, implies that $ \delta := \delta(f;x;z) < \infty $, see the paragraph just before Theorem~\ref{Thm:poly}.




Using parameters $ (z,x) $ with the property $ \Delta(f;x;z) = \Delta(f;x) $ we determine the center of the weighted blow-up in terms of monomial valuations. 
While this definition depends on choices, we show in Theorem~\ref{Thm:J_unique} that the center is unique.
Despite working in a more general setup, the proof follows the same lines as \cite[Theorem~4.2]{AQS-plane}.








\begin{Def} 
	Let $ ( \cO, \mm, K ) $ be a regular local ring of dimension $ 2 $ which is essentially of finite type over a field $ k $.
		\begin{enumerate}
			\item 
			For {\em any}
 parameters $ (x_1, x_2) $ of $ \cO $
 and {\em any} positive rational numbers $ a_1, a_2 \in \IQ_+ $, 
 			we define $J = (x_1^{a_1},x_2^{a_2})$ to be the monomial valuation 
 			$v_J\colon \cO \smallsetminus \{0\} \to \IQ$
 			given by 
 			\[
 				v_J(x_1) = \frac{1}{a_1},
 				\quad 
 				v_J(x_2) = \frac{1}{a_2}.
 			\]

 		\item 
 		For a non-zero element $ f \in \cO  \smallsetminus \{0\}$,
 		we say $J = (x_1^{a_1},x_2^{a_2})$ is {\em admissible} for $ f $
 		if we have $ v_J(f) \geq 1 $. 
		\end{enumerate}
\end{Def}




\begin{Rk}
	\phantomsection
	\label{Rk:v_J}
	\begin{enumerate}
		\item 
		Since $ v_J $ is a monomial valuation, we have:
		For any $ g \in \cO\smallsetminus \{0\} $
		with expansion $ g (x_1,x_2) = \sum\limits_{(i_1,i_2)} d_{i_1, i_2} x_1^{i_1} x_2^{i_2} $ for $ d_{i_1,i_2}\in \cO^\times \cup \{ 0 \} $,
		the following holds: 
		\[ 
		v_J(g) = \min\left\{ \frac{i_1}{a_1} +  \frac{i_2}{a_2} \ \Big| \  d_{i_1,i_2} \neq 0\right\}.
		\]
		In particular, we have $ v_J(x_1^{a_1}) = v_J(x_2^{a_2}) = 1 $. 

		\item 
		Observe that $ J =  (x_1^{a_1},x_2^{a_2}) $ is admissible for a given $ f $ if and only if $f\in (x_1^{a_1},x_2^{a_2})^{\Int}$.

		\item \label{It:local} 
		For resolution of $ 1 $-dimensional schemes the local perspective via valuations is enough. 
		In general, for instance in Theorem~\ref{Thm:Main2}, one has to describe centers globally, 
		as for example in \cite[Section~2.2]{ATW_weighted} via \emph{valuative $\IQ$-ideals}.
	\end{enumerate}
\end{Rk}





\begin{Thm}
	\label{Thm:J_unique}
	Let $ q \in C = \{ f = 0 \} \subset \Spec(\cO) $ be as described at the beginning of this section.
	Let $ (a_1, a_2 ) := (\nu, \nu \delta ) $ 
and let $ (x_1, x_2) $ be a regular system of parameters for $ \cO $ such that $ \Delta (f;x_2;x_1) = \Delta(f;x_2) = [\delta ; \infty [  $.
Then $ J = (x_1^{a_1}, x_2^{a_2} ) $ is the unique admissible center for $ f $ for which $ (a_1,a_2) $ with $ a_1 \leq a_2 $ attains its maximum with respect to the lexicographical order.
Moreover, $J$ is stable under base change to separable field extensions of $ k $.
\end{Thm}


We note that this theorem implies Theorem~\ref{Thm:Main1}\eqref{It:well-defined}.

\begin{proof}
	Since the proof is analogous to the one for \cite[Theorem~4.2]{AQS-plane},
	we outline the steps and refer for further details to \cite{AQS-plane}.
	Our goal is to show
	\begin{equation}
	\label{eq:lexmax} 
	\max_{\geq_{\rm lex}} \{ (b_1, b_2) \in \IQ_+^2 \mid \exists \, (y_1,y_2) :  (y_1^{b_1},y_2^{b_2}) \mbox{ admissible center for } f  \}
	= (a_1, a_2) .
	\end{equation}


	First, the left hand side of Equation~\eqref{eq:lexmax} is $ \geq (a_1, a_2) $
	since $ J $ is admissible by the definition of to the characteristic polyhedron.  


Secondly, $ a_1 $ is unique:
If $ (y_1^{b_1},y_2^{b_2})$ is another admissible center with $b_1 \leq b_2$, 
we must have $ b_1 \leq a_1 $ since $ a_1 = \nu_\mm(f) $ which implies the existence of a monomial $ y_1^a y_2^{\nu-a} $ with coefficient a unit in the expansion of $ f $.




		Thirdly, $ a_2 $ is unique:
		Let $ (y_1^{\nu},y_2^{b_2})$ be an admissible center. 
		Using the definition of the characteristic polyhedron and $ \delta(f;y_2;y_1) \leq \delta $, 
		it follows that we have to have $ b_2 \leq \nu \delta = a_2 $ which implies Equation~\eqref{eq:lexmax}.




	Finally, we show that the center is unique: 
	Let $ J_x = ( x_1^{a_1} , x_2^{a_2} ) $
	and $ J_y = ( y_1^{a_1} , y_2^{a_2} ) $ be two admissible centers for $ f $. 
	If $ a_1 = a_2 $ then $ v_{J_x} = v_{J_y} = a_1 \nu_m $ 
	and the desired equality $ J_x = J_y $ holds. 
	Hence, suppose $ a_1 < a_2 $. 

	\begin{enumerate}
		\item [(a)]
		\underline{$ x_2 = y_2 $\,:} 
		By construction, we may vary $ x_2 $ for the given $ x_1 $ as long as we have $ \mm = (x_1, \widetilde{x_2}) $ for the different choice. 
		The analogous statement is true for $ y_2 $. 
		Since $\IP(\mm/\mm^2)$ has at least 3 points,
		we may assume without loss of generality that $ x_2 = y_2 $. 
		Further, this provides $ v_{J_y} (x_2) =v_{J_x} (x_2) = \frac{1}{a_2} $. 

		\item[(b)]
		 \underline{$ v_{J_y} (x_1) = v_{J_x} (y_1) = \frac{1}{a_1} $\,:}
		 If $ x_1 $ and $ y_1 $ differ by a unit factor, the assertion clearly holds. 
		 Therefore, consider an expansion of $ x_1 $ in the regular system of parameter $ (y_1, x_2) $,
		 say $
		 	x_1 = \epsilon y_1 + \mu x_2^A 
		 	$
		 	for  
		 	$ A \in \IZ_+, \epsilon, \mu \in \cO^\times $.
		 Since $ v_{J_y} $ is a monomial valuation, this provides $ v_{J_y} (x_1) \leq v_{J_y} (y_1) = \frac{1}{a_1} $.

		 Assume the inequality is strict, $ v_{J_y} (x_1) < \frac{1}{a_1} $.   
		 Expand $ f = \sum_{ ( i_1, i_2 )} d_{i_1,i_2} x_1^{i_1} x_2^{i_2} $.
		 Since $ J_x $ is admissible for $ f $,
		 we have $ \frac{i_2}{a_2} \geq \frac{a_1-i_1}{a_1} $ for every $ (i_2, i_2) $ such that $  d_{i_1,i_2} \in \cO^\times $ is a unit. 
		 Moreover, we have an equality if and only if $ i_1 = a_1, i_2 = 0 $. 
		 Using the non-Archimedean property, it follows that $ v_{J_y} (f) = a_1 v_{J_y} (x_1) < 1 $.
		 This contradicts the assumption that $ J_y $ is an admissible center for $ f $
		 and therefore we obtain $ v_{J_y} (x_1) = \frac{1}{a_1} $.
		Applying the analogous arguments leads to  $ v_{J_x} (y_1) = \frac{1}{a_1} $.

		\item[(c)]
		\underline{$ J_x = J_y $\,:}
		This follows since $(x_1^{ m a_1},x_2^{m a_2})^\Int =  (y_1^{m a_1},y_2^{m a_2})^\Int$
		for every $ m \in \IZ_{\geq 0} $. 
	\end{enumerate}

	It remains to prove that $J$ is stable under base change to separable field extensions of $ k $.
	Let $ k' / k $ be a separable extension. 
	Using \cite[Prop.~2.15]{Cossart-Pitant}
	(applied for $ h := \ini_\delta (f) $ considered as element in $ S[X_1] $ for $ S := K[X_2]_{ (X_2) } $ and $ \widetilde S := S \otimes_{k} k' $)
	it can be deduced that the characteristic polyhedron does not change under the base change $ k'/k $ and thus $ J $ remains stable. 

	Since our given situation is simpler, we provide a direct argument:
	We have to study the behavior of $ \phi := \ini_\delta (f) \in K[X_1,X_2] $ under separable extensions. 
	Let $ \phi_s $ be the element $ \phi $ considered as element in $ (K \otimes_{k} k') [X_1,X_2] $. 
	We have to show that $ \phi_s $ is not a $ \nu $-th power, $ \phi_s \neq (X_1 + \alpha X_2^\delta )^\nu $ for $ \alpha \in (K \otimes_{k} k' ) \smallsetminus \{0\} $.
	If $ \delta \notin \IZ_+$, this is certainly not possible.
	Hence let $ \delta \in \IZ_+ $ and assume $ \phi_s = (X_1 + \alpha X_2^\delta )^\nu $.
	Write $ \nu = p^m \nu' $ for $ \nu' $ prime to $ p $ if $ \car(k) = p > 0 $ and $ \nu= \nu' , p^m = 1 $ else.
	Since the extension is separable, we have to have $ \phi = \psi^{p^m} $ for some $ \psi \in K [X_1,X_2] $.   
	Clearly, $ \nu' \geq 2 $ in this case and $ \psi_s = (X_1 +\alpha X_2^\delta )^{\nu'} $.
	We have $ \psi = X_1^{\nu'} + \sum_{i=1}^{\nu'} c_i X_1^{\nu'-i} X_2^{\delta i} $ for $ c_i \in K $.
	Let $ Y_1 := X_1 + \frac{c_1}{\nu'} X_2^\delta $.  
	Substituting $ X_1 = Y_1 - \frac{c_1}{\nu'} X_2^\delta $ provides  
	$ \psi = Y_1^{\nu'} + \sum_{i=2}^{\nu'} c_i' Y_1^{\nu'-i} X_2^{\delta i} \neq Y_1^{\nu'}  $ for certain $ c_i' \in K $.
	Observe that $ J $ remains stable under this substitution and that $ c_1' = 0 $.
	The last condition is stable by the base change with $ k' $, but this contradicts $ \psi_s = (X_1 +\alpha X_2^\delta )^{\nu'} $. 
\end{proof} 


In order to draw a connection to the weighted normal cone, we need to compare $ f $ and $ F_\delta $ (Definition~\ref{Def:Fdelta}).
	Note that $ F_\delta $ is the sum over all monomials of valuation $ 1 $ in an expansion of $ f $.
To emphasize the relation to the valuation $ v_J $, we introduce the notation $ f_{J,1} := F_\delta .$
Hence, we have
\begin{equation}
	\label{eq:expansion} 
	f  =  f_{J,1} + \widetilde h,
	\quad
	\mbox{ where } \widetilde h \in \cO 
	\mbox{ with } v_{J} (\widetilde h) > 1 .
\end{equation} 



\begin{Cor}\label{Cor:leading-term} 
	The reduction of $ \{ f_{J,1} = 0 \} $ is singular at $ q $ and $\inv_{f_{J,1}}(q) = (a_1,a_2)$ with the same center  $(x_1^{a_1},x_2^{a_2})$ as for $ f $.
\end{Cor}
\begin{proof}
		First, we have  $ \ini_\delta (f_{J,1})  = \ini_\delta (f) $.
		This implies that the vertex
		$ \delta \in \Delta (f_{J,1};x_2;x_1) $ 
		is not solvable. 
		In particular, $ f_{J,1} $ is not equal to the power of a regular parameter
		which implies the claim on the reduction of $ \{ f_{J,1} = 0 \} $. 

		Furthermore, the characteristic polyhedra of $ f_{J,1} $ and $ f  $ coincide,
		$ \Delta (f_{J,1};x_2;x_1) =  \Delta (f_{J,1};x_2) = [\delta ; \infty [ = 
		\Delta (f;x_2) $.
		So, the designated center for $ f_{J,1} $ is $(x_1^{a_1},x_2^{a_2})$ as well. 	
 \end{proof}








\section{Weighted blow-ups and proper transform}\label{Sec:weighted}\label{Sec:transform}


Now that we have a candidate for the center, let us recall the concept of a stack-theoretic weighted blow-up.
A general reference for them is \cite{Quek-Rydh}.
Weighted blow-ups are very closely connected to W{\l}odarczyk's notion of cobordant blow-ups \cite{Wlodarczyk-Rees}, 
where a torus action is taken into account instead of taking the stack-theoretic quotient.




\begin{Def}[{\cite[Section~2.4]{ATW_weighted}}] 
		\label{Def:reduced_center}
		For $J = (x_1^{a_1},x_2^{a_2})$,
		the associated \emph{reduced center} is 
		$\bar J := (x_1^{1/w_1}, x_2^{1/w_2})$, 
		with 
		$w_1,w_2 \in \IZ_+ $ 
		relatively prime integers 
		such that 
		\[ 
		\ell \cdot \left(\frac1{w_1},\frac1{w_2}\right) \, = \,  (a_1,a_2)
		\] 
		for  $\ell := a_1w_1 = a_2w_2$ 
	the least 
	multiple of $a_1,a_2$
	in $ \IZ_+ $.
\end{Def}


We introduce the weighted blow-up in terms of extended Rees algebras \cite{Rees}.
For $J = (x_1^{a_1},x_2^{a_2})$ with reduced center $\bar J = (x_1^{1/w_1}, x_2^{1/w_2})$
and $ n \in \IZ $
set
$ 
\cI_n := \{g \in \cO \mid  v_{\bar J}(g) \geq n\}. 
$
Notice that that $\cI_n = \cO$ for $n\leq 0$. 
The \emph{extended Rees algebra associated to $\bar J$} is the $ \cO $-algebra
\[ 
	\tilde R \, =  \, \bigoplus_{n\in \IZ} \cI_n. 
\]


This local construction becomes global via $ \cI_n = \cO_S $ away from $ q $.




By \cite[Proposition~5.2.2]{Quek-Rydh}, $ \tilde R $ has the following local presentation:
%
\begin{equation}
	\label{eq:presentation}
	\tilde R \, = \, \cO[ s, x_1', x_2' ] / (x_1 - s^{w_1} x_1',x_2 -s^{w_2} x_2'),
\end{equation}
%
for 
$ s \in \cI_{-1} $ 
the element $ 1 \in \cO $, and 
$ x_i' \in \cI_{w_i} $
corresponding to
$ x_i $ in degree $ w_i $, $ i \in \{1, 2\} $.
Here,
$s$ is the exceptional variable,
defining the exceptional divisor once 
the blow-up
is defined.
Moreover,
$x_i'$ is called the transformed variable corresponding to $x_i$, for $ i \in \{ 1, 2 \} $.








\begin{Constr}[{Degenerating to the weighted normal cone, see \cite{Wlodarczyk-Rees, Quek-Rydh}}]
	\label{Constr:Degen}
	Let 
	$B = \Spec_S(\tilde R)$ 
	be 
	the spectrum relative to the scheme $ S  $ of the quasi-coherent sheaf of $ \cO_S $-algebras $ \tilde R $.
	Besides from its 
	structure morphism  $B \to S$, $ B $ is also equipped with
	a morphism  
	$\varphi \colon B \to \IA_k^1 = \Spec k[s]$.
	Using the latter $ B $ becomes
	the degeneration of $S$ to the weighted normal cone of
	$\bar J  $. Using Equation~\eqref{eq:presentation}, we have: 
\begin{itemize}
	\item 
	The fiber of $ \varphi $ over $s=1$ is isomorphic to $S$ 
	since
	$x_1=x_1', x_2=x_2'$. 

	\item 
	The fiber of $ \varphi $ over $s=0$ lies over the point $(x_1,x_2) = (0,0)$
and it is isomorphic to $\Spec k[x_1',x_2']$ 
	with the natural action of $\IG_m$ with weights $w_i$ on $x_i'$, making it the weighted normal cone 
	at $ (0,0) \in S $.
\end{itemize}


Observe that we have the following action of $\IG_m = \Spec k[t,t^{-1}]$
on $B$
\begin{equation}
	\label{eq:action}
	t \cdot (s,x_1',x_2') \quad = \quad (t^{-1} s, t^{w_1} x_1', t^{w_2} x_2') 
\end{equation} 
stabilizing
$V(\oplus_{n>0} \cI_n) = V(x_1', x_2')$.
\end{Constr}








\begin{Def}[Weighted blow-up]\label{Def:weighted}
	Let $ B = \Spec_S(\tilde R)$ 
	 be as in Construction~\ref{Constr:Degen}.
	The {\em weighted blow-up of $S$ along $\bar J$} is defined as the Artin stack
	\[ 
		\pi \colon \operatorname{Bl}_{\bar J} (S) := [B_+/\IG_m] \to S,
	\]
	where 
	$ B_+ := B \smallsetminus V(x_1', x_2') $, 
		with natural $\IG_m$-action determined by \eqref{eq:action} and
	the morphism $ \pi $ is induced by the structure morphism $ B \to S $.
\end{Def}


Observe that $ \operatorname{Bl}_{\bar J} (S)  $ is covered by two charts, namely where $ x_1' $ (resp.~$ x_2' $) is invertible in which case we also write $ x_1' \neq 0 $ (resp.~$ x_2' \neq 0 $).


\medskip 


By \cite[Lemma~1.1.2 and Remark~3.2.10]{Quek-Rydh} the weighted blow-up fulfills the following properties.
Note that this proves Theorem~\ref{Thm:Main1}\eqref{It:birational}.


\begin{Lem}\label{Lem:weighted}
	Let 
	$ \pi \colon \operatorname{Bl}_{\bar J} (S) = [B_+/\IG_m] \to S $	be the weighted blow-up of $S$ along the reduced center $\bar J = (x_1^{1/w_1}, x_2^{1/w_2})$
	coming from $ J = (x_1^{a_1},x_2^{a_2}) $.
	Then:
	\begin{enumerate}
		\item 
		All stabilizers of the Artin stack  
		$ \operatorname{Bl}_{\bar J} (S) $ are 
		naturally subgroups of $\IG_m$.
		In particular, 
		$ \operatorname{Bl}_{\bar J} (S) $ is a {\em tame} Artin stack.

		\item 
		The dimension of the quotient 
		$ \operatorname{Bl}_{\bar J} (S) $ is two
		and 
		the morphism
		$ \pi $ is an isomorphism outside the exceptional divisor, which is defined on the smooth covering of $ B_+ $ by $ s = 0 $.
	\end{enumerate}	


	In particular, the weighted blow-up $ \pi $ is birational.  

	\begin{enumerate}
		\item[(3)]
		At the point $s = x_1'=0$ the stabilizer group is $\Gmu_{w_2}$; 
		while at the point $s= x_2'=0$ the stabilizer group is $\Gmu_{w_1}$.
		Here, $ \Gmu_m $ denotes the group of $ m $-th roots of unity for $ m \in \IZ_+ $.
	\end{enumerate}
\end{Lem}



Let us next have a look at how an element $ f\in \cO $ transforms along a weighted blow-up.
Recall that we have given a singular point $ q $ on a
hypersurface $ C = \{ f = 0 \} $ in a regular $ 2 $-dimensional scheme which is essentially of finite type over a field $ k $.


Consider an expansion of $ f $ as in Equation~\eqref{eq:expansion}, 
$ f = f_{J,1}(x_1,x_2) + \widetilde h(x_1,x_2) $.
Recall that $ v_{\bar J} (f) = v_{\bar J} (f_{J,1}) = \ell < v_{\bar J} (\widetilde h) $ where $ \ell \in \IZ_+ $ is the integer introduced in Definition~\ref{Def:reduced_center}.
Using the presentation of $ \tilde R $ given in Equation~\eqref{eq:presentation},
the pullback of $ f $ to $ B$ is
%
\[
	f(x_1,x_2) 
	\ = \  f(s^{w_1} x_1',  s^{w_2} x_2') 
	\ = \  s^\ell f_{J,1}(x_1',x_2') + s^{\ell+1} \widetilde h' (s, x_1',x_2') 
\]
where $ \widetilde h' (s, x_1',x_2') $ is defined through
	$  \widetilde h(s^{w_1} x_1',  s^{w_2} x_2') :=
	s^{v_{\bar J} (\widetilde h)-(\ell+1)}\widetilde h' (s, x_1',x_2') $.










\begin{Def}\label{Def:proper}
	The \emph{proper transform of $ f $ 
	on $B$} is defined as 
	the element $ f' $ that we obtain after factoring $ s^\ell $ from the pullback of $ f $ to $ B $,
	\[ 
		f'(s, x_1',x_2') 
		\ := \ 
		s^{-\ell} f(s^{w_1} x_1',  s^{w_2} x_2')  
		\ = \ 
		f_{J,1}(x_1',x_2') + s \, \widetilde h' (s, x_1',x_2').
	\]
\end{Def}




\begin{Ex}\label{Ex:one} 
	Consider again  Example~\ref{Ex:1_2_3}\eqref{Ex:2_localize},
	and assume for simplicity that $p\nmid m$. We have determined $\nu = 2p$ and $\delta = m/p$, giving $(a_1,a_2) = (2p,2m)$ and, keeping $(x_1,x_2) = (y,x)$ we have $J = \left(y^{2p}, x^{2m}\right)$. We now write $ f = f_{J,1}(y,x) + \widetilde h(y,x) $ with
	 \[ 
		 	f_{J,1}(y,x) \ = \ y^{2p} + x^m y^p z^{m+p} + x^{2m} z^{p+1} \qquad\text{and}\qquad \widetilde h(y,x) \ = \ x^{2m-1} y.
		 \]
		  Since $p\nmid m$ we have $\ell = 2mp$. We rescale to obtain $\bar J = \left(y^{1/m}, x^{1/p}\right)$, so that $x = s^px', y=s^my',$ giving
	 \[ 
		 	f'(y',x') \quad = \quad y'^{2p} + x'^m y'^p z^{m+p} + x'^{2m} z^{p+1} \quad + \quad  s^{m-p}x'^{2m-1} y'.
		 \]
		 The argument in the Section \ref{Sec:Proofs} below  guarantees  that its order along the exceptional locus $s=0$ is $<2p$. This follows from the fact that the  term $y'^{2p} + x'^m y'^p z^{m+p} + x'^{2m} z^{p+1}$ is not of the form $g^{2p}$
		and that $ x' $ or $ y' $ is invertible 
		 	(and also remember that $ z $ is invertible). 
\end{Ex}












\section{Proofs}
\label{Sec:Proofs}


Our final section is devoted to proving Theorem~\ref{Thm:Main1}\eqref{It:order-drops}  and Theorem~\ref{Thm:Main2}. Applying the same arguments as explained in \cite[after Defintion~6.1]{AQS-plane}, 
	Corollary~\ref{Cor:leading-term} can be used to deduce that the invariant on any fiber of $ \varphi|_{B_+} \colon B_+ \to \IA_\K^1$ (see Construction~\ref{Constr:Degen})	
	drops strictly.
As in \cite{AQS-plane}, we show the strong statement that the order decreases strictly after the designated weighted blow-up.












\begin{proof}[The order drops: Proof of Theorem \ref{Thm:Main1}\eqref{It:order-drops}]
Since the order  
is functorial for smooth morphisms, showing that the order drops on $B_+$ implies that it drops on the quotient $\Bl_{\bar J}(S) = [B_+/\IG_m]$. 
Note that $\nu_{\mm}(f) \leq \nu^{\log}_{\mm}(f)$, where the logarithmic order $\nu^{\log}_\mm (f)$ 
is defined with respect to the exceptional divisor $\{s=0\}$: it is the order where $s\neq 0$ and otherwise it is the order of the restriction to $\{s=0\}$, namely the order of $f_{J,1}(x_1',x_2')$.




When $s\neq 0$ we simply are computing the order of $f$ away from $ q = \{x_1=x_2=0\}$. 
We note that near $ q $ this order is $<\nu=a_1$ since $f$ is not a pure $\nu$-th power.





When $s=0$ we are computing the order of $f_{J,1}(x_1',x_2')$ away from $\{x_1'=x_2'=0\}$. But once again, $f_{J,1}(x_1',x_2') = x_1'^{\nu} + \cdots$ is not a pure $\nu$-th power, see Corollary \ref{Cor:leading-term}. 
Thus its order of vanishing at any point on this locus is $<\nu=a_1$, as needed.
\end{proof}



\medskip



Using this result, we can now prove its equivariant generalization.

\begin{proof}[Proof of Theorem~\ref{Thm:Main2}]
Consider the localizations of $\cZ \subset \cW$ at the generic point $q:=\eta_\cQ$ of $\cQ$, namely $C := \Spec(\cO_{\cZ,q})$ and $S := \Spec(\cO_{\cW,q})$. Then $S$ is a 2-dimensional regular scheme that is essentially of finite type over $k$, and $C$ is cut out by a local equation $\{f=0\}$ in $S$. Note that the residue field of the closed point $q \in S$ is the function field $K(\cQ)$ 
and hence it is not necessarily perfect even if $ k $ was assumed to be perfect.

We apply part (1) of Theorem~\ref{Thm:Main1} to $C \subset S$ at $q$. There is a unique center $J=(x_1^{a_{1}}, x_2^{a_{2}})$ of maximal invariant $(a_{1},a_{2})$ that is admissible for $C \subset S$ at $q$, where $a_{2} = a_{1}\delta$, with $\delta$ the vertex of the characteristic polyhedron of $f$. Let $q \in U \subset \cQ$ be the largest open subset on which $J = (x_1^{a_{1}}, x_2^{a_{2}})$ extends. In what follows, we show $U = \cQ$: 
\begin{enumerate}
    \item[(i)] Firstly, letting $k^\sep$ denote the separable closure of $k$, we claim $U$ is stable under $T(k^\sep)$. Indeed, $J$ remains the unique center of maximal invariant $(a_1,a_2)$ that is admissible for $C \times_{\Spec(k)} \Spec(k^{\sep})  \subset S \times_{\Spec(k)} \Spec(k^{\sep}) $ 
    at $q$. On the other hand, for every $t \in T(k^\sep)$, $t \cdot J$ is also a center on $S \times_{\Spec(k)} \Spec(k^{\sep}) $ that satisfies the same properties, so by the uniqueness of $J$, $t \cdot J = J$. Thus, $J = t \cdot J$ extends to $t \cdot U \subset \cQ$, so $t \cdot U \subset U$.

    \item[(ii)] Secondly, we claim that in fact $U$ is stable under $T$. To do so, we instead show that $F = \cQ \smallsetminus U$ is stable under $T$, or equivalently, that the preimage of $F$ under the $T$-action $\alpha \colon T \times \cQ \to \cQ$ contains $T \times F$. By (i), $\alpha^{-1}(F) \supset \{t\} \times F$ for every $t \in T(k^\sep)$. Since $T$ is integral and geometrically reduced, the points in $T(k^\sep)$ are dense in $T$. Thus, after taking closures, we deduce $\alpha^{-1}(F) \supset T \times F$ as desired.

\end{enumerate}
Thus, $U \subset \cQ$ are both non-empty $T$-orbits, so $U = \cQ$. Hence, $J$ extends to $\cQ$, and moreover by (i), that extension to $\cQ$ is $T$-invariant.

Next, we claim that $J=(x_1^{a_{1}}, x_2^{a_{2}})$ is the unique $T$-invariant center of maximal invariant that is admissible for $\cZ \subset \cW$ along $\cQ$.
Note that a $ T $-invariant center is necessarily defined by at most 2 local parameters at all points.
To see the claim, any other such center $J'$ necessarily of invariant $(a_1,a_2)$ would localize to a center of maximal invariant that is admissible for $C \subset S$ at $q$. By the uniqueness of $J$ in Theorem~\ref{Thm:Main1}, $J$ agrees with $J'$ at $q$, and hence on a non-empty open subset of $\cQ$. Since $\cQ$ is an orbit under the $T$-action on $\cW$, and both $J$ and $J'$ are $T$-invariant, we deduce that $J = J'$. This completes the proof of part (1) of Theorem~\ref{Thm:Main2}.

We now prove the remaining parts of Theorem~\ref{Thm:Main2}. Following the notation introduced in Section~\ref{Sec:weighted}, consider the weighted blow-up of $[B_+/\Gm] \to \cW$ along $\bar J = (x_1^{1/w_1},x_2^{1/w_2})$. Since $B_+ \subset B = \Spec(\tilde{R})$ with $\cO_\cW \subset \tilde{R} \subset \cO_\cW[t,t^{-1}]$, the co-action $\cO_\cW \to \cO_\cW \otimes \cO_T$ naturally lifts to a co-action $\tilde{R} \to \tilde{R} \otimes \cO_T$ by sending $t \mapsto t \otimes 1$. In this way, the $T$-action on $\cW$ lifts to an action of $T' = T \times \Gm$ on $B_+$, inducing a morphism $[B_+/T'] \to [\cW/T]$ fitting in a cartesian diagram: \[
    \begin{tikzcd}
        {[B_+/\Gm]} \arrow[to=1-2] \arrow[to=2-1] & {[B_+/T']} \arrow[to=2-2] \\
        \cW \arrow[to=2-2]& {[\cW/T]}
    \end{tikzcd}
\]
Since $\cW \to [\cW/T]$ is a smooth cover, and $[B_+/\Gm] \to \cW$ is proper and birational by Lemma~\ref{Lem:weighted}, $[B_+/T'] \to [\cW/T]$ is also proper and birational. In order to show $[B_+/T']$ has finite stabilizers, it suffices to show its relative inertia over $[\cW/T]$ is finite, since by hypothesis $[\cW/T]$ has finite stabilizers. Indeed, that is the case, as the relative inertia of $[B_+/T']$ over $[\cW/T]$ is finite after base change to the smooth cover $\cW \to [\cW/T]$.

Finally, by part (3) of Theorem~\ref{Thm:Main1}, the order of $\cZ' \subset \cW' := B_+$ at every point lying over $q$ is strictly smaller than $a_1$. Since every point lying over $\cQ$ is in the same $T'$-orbit as points lying over $q$, we deduce the same conclusion for points in $\cZ'$ lying over $\cQ$.
\end{proof}






















































