\caption{Results: scenarios I and II}
\label{table:results_scenarios_1_and_2}
\centering
\renewcommand{\arraystretch}{1.3} % Adjust row height
\resizebox{\columnwidth}{!}{%
\begin{tabular}{|l||c|c||c|c|}
\hline
\textbf{Metric} & \multicolumn{2}{c||}{\textbf{scenario I}} & \multicolumn{2}{c|}{\textbf{scenario II}} \\
\cline{2-5}
 & \textbf{String A} & \textbf{String B} & \textbf{String A} & \textbf{String B} \\
\hline\hline
