\section{Continuum limit}\label{appx:continuum-limit}
To derive the continuum evolution equation~\eqref{evo-spring-density-continuous} from the discrete evolution equation~\eqref{evo-density-midpoint} as $m\to\infty$, we introduce a time-dependent parametrisation $\overline{\b r}(u,t)$ of the interface $\b r(s)$ that tracks the evolving midpoint spring positions for constant parameter values $u$, i.e.,
\begin{align}\label{bar-u}
  \overline{\b r}(u_i, t) = \b r\big(\overline{s}_i(t)\big),
\end{align}
where $u_i = i\Deltaup u$, $i=0,\ldots, M$ are time-independent, evenly spaced coordinates in a finite parameter space $u\in[0,U)$, and $\overline{s}_i(t)$ are the arc length coordinates of the spring midpoints~(Figure~\ref{fig-continuum-limit-reparametrisation}). As $m\to\infty$, $\Deltaup u=U/M\to 0$ and $\overline{s}_{i-1}(t)\sim\overline{s}_i(t)\sim\overline{s}_{i+1}(t)$. This parametrisation of the interface is such that
\begin{align}\label{midpoint-arclength-2}
	\overline{s}_i(t) = \int_0^{u_i}\d u\ g(u,t), \qquad g(u,t) = \norm{\pd{\overline{\b r}}{u}(u,t)}.
\end{align}
Spring density at arc length position $\overline{s}_i(t)$, which corresponds to the coordinate $u_i$, is represented by
\begin{align}
	\rho\big(\overline{s}_i(t),t\big) = \frac{1}{g(u_i,t)\Deltaup u}.\label{rho-g}
\end{align}
Using Eq.~\eqref{midpoint-arclength-2} to express $\overline{s}_{i\pm 1}(t)$ in terms of $u_{i\pm1}=u_i\pm\Deltaup u$ and expanding about $u_i$ as $\Deltaup u\to 0$, we obtain (omitting the time dependence of $\overline{s_i}$ to simplify notation),
\begin{align}\label{midpoint-offsets}
	\overline{s}_{i\pm1} = \overline{s}_i  \pm g(u_i,t)\Deltaup u + \pd{g}{u}(u_i,t)\frac{\Deltaup u^2}{2} \pm \pd{^2g}{u^2}(u_i,t)\frac{\Deltaup u^3}{6} + \Order\big(\Deltaup u^4\big).
\end{align}
\begin{figure}
	\centering\includegraphics[scale=0.85]{fig13-continuum-limit-reparametrisation}
	\caption{Time-dependent reparametrisation of the interface. The time-dependent parametrisation $\overline{\b r}(u,t)$ of the interface $\b r(s)$ maps constant, evenly spaced coordinates $u_i$ to the time-dependent spring midpoint positions $\b r\big(\overline{s}_i(t)\big)$ (open circles).}
	\label{fig-continuum-limit-reparametrisation}
\end{figure}
With the expressions~\eqref{midpoint-offsets} and $\ell_i^2=1/\rho^2(\overline{s}_i,t) \sim g^2(u_i,t)\Deltaup u^2$, expanding the right hand side of Eq.~\eqref{evo-density-midpoint} about $u_i$ as $\Deltaup u\to 0$ gives
\begin{align}\label{evo-continuum-rhs}
	\td{}{t}\rho\big(\overline{s}_i,t\big) = - \frac{1}{\eta} \pd{^2}{s^2}\widetilde{f}\big(\rho(\overline{s}_i,t)\big) - \frac{1}{\eta} \frac{1}{g^2(u_i,t)}\pd{g}{u}(u_i,t)\pd{}{s}\widetilde{f}\big(\rho(\overline{s}_i,t)\big) + \Order\left(\Deltaup u^2\right), \qquad m\to\infty.
\end{align}
In the left hand side of Eq.~\eqref{evo-continuum-rhs}, we have, using the chain rule,
\begin{align}
  \td{}{t}\rho(\overline{s}_i,t) &= \pd{\rho}{t}(\overline{s}_i,t) + \pd{\rho}{s}(\overline{s}_i,t) \td{\overline{s}_i}{t},
\end{align}
where from Eqs~\eqref{discrete-evo},~\eqref{rho-cont}--\eqref{f-tilde}, and~\eqref{midpoint-offsets},
\begin{align}\label{evo-midpoint}
  \td{\overline{s}_i}{t} = \frac{1}{2\eta}\left[\widetilde{f}\big(\rho(\overline{s}_{i+1},t)\big) - \widetilde{f}\big(\rho(\overline{s}_{i-1},t)\big)\right] = \frac{1}{\eta} \pd{\widetilde{f}}{s}\big(\rho(\overline{s}_i,t)\big) g(u_i,t)\Deltaup u + \Order\left(\Deltaup u^3\right).
\end{align}
Since from Eqs~\eqref{midpoint-arclength-2}--\eqref{rho-g} $g(u_i,t)\Deltaup u = 1/\rho(\overline{s}_i,t)$ and $(\p\rho/\p s)/\rho = -(\p g/\p s)/g = -(\p g/\p u)/g^2$, the left hand side of Eq.~\eqref{evo-continuum-rhs} asymptotically becomes:
\begin{align}\label{evo-continuum-lhs}
  \td{}{t}\rho(\overline{s}_i,t) &= \pd{\rho}{t}(\overline{s}_i,t) - \frac{1}{\eta} \frac{1}{g^2(u_i,t)} \pd{g}{u}(u_i,t)\pd{\widetilde{f}}{s}\big(\rho(\overline{s}_i,t)\big) + \Order\left(\Deltaup u^3\right)
\end{align}
Equating Eqs~\eqref{evo-continuum-lhs} and~\eqref{evo-continuum-rhs} shows that the second term in the right hand sides of both equations cancel, so that
\begin{align}
  \pd{\rho}{t}(\overline{s}_i,t) &= -\frac{1}{\eta}\pd{^2}{s^2}\widetilde{f}\big(\rho(\overline{s}_i,t)\big) \left(1+ \Order\left(\Deltaup u^2\right)\right),\label{evo-spring-density-continuous-appx}
\end{align}
which is the same as Eq.~\eqref{evo-spring-density-continuous}. This development shows that this partial differential equation is a second-order accurate representation of the discrete model equation~\eqref{evo-density-midpoint} as $m\to\infty$, i.e., corrections are $\Order(\Deltaup u^2) = \Order(1/m^2)$.

If $\overline{s}_i(t)$ is not defined as the midpoint between $s_i(t)$ and $s_{i-1}(t)$, corrections of order $\Order(1/m)$ are obtained for the evolution of cell density. Indeed, defining
\begin{align}
	\overline{s}_i(t) = \frac{1+\epsilon}{2} s_i(t) + \frac{1-\epsilon}{2} s_{i-1}(t)  
\end{align}
for $-1\leq \epsilon \leq 1$, such that the midpoint is obtained when $\epsilon=0$, the expansion in Eq.~\eqref{evo-continuum-rhs} remains the same. However, the evolution of $\overline{s}_i(t)$ in Eq.~\eqref{evo-midpoint} now has $\epsilon \Order(\Deltaup u^2)$ corrections. These corrections modify Equation~\eqref{evo-continuum-lhs} into
\begin{align}\label{evo-continuum-lhs2}
  \td{}{t}\rho(\overline{s}_i,t) &= \pd{\rho}{t}(\overline{s}_i,t) - \frac{1}{\eta} \frac{1}{g^2(u_i,t)} \pd{g}{u}(u_i,t)\pd{\widetilde{f}}{s}\big(\rho(\overline{s}_i,t)\big)\notag
  \\&+\frac{\epsilon}{2\eta}\left(\frac{1}{\rho^2(\overline{s}_i,t)}\pd{\rho}{s}(\overline{s}_i,t)\pd{^2}{s^2}\widetilde{f}\big(\rho(\overline{s}_i,t)\big) - \frac{1}{\rho^3(\overline{s}_i,t)}\left(\pd{\rho}{s}(\overline{s}_i,t)\right)^2\pd{}{s}\widetilde{f}\big(\rho(\overline{s}_i,t)\big) \right)\notag
  \\&+ \Order\left(\Deltaup u^3\right)
\end{align}
Equating Eqs~\eqref{evo-continuum-lhs2} and \eqref{evo-continuum-rhs}, substituting $\rho = m q$, and using the definition of $F(q)$ in Eq.~\eqref{restoring-force-contlim}, one obtains
\begin{align}
  \pd{q}{t}(s,t) = &-\frac{1}{\eta}\pd{^2}{s^2}F\big(q(s,t)\big) \notag
  \\&- \frac{\epsilon}{2\eta}\left(\frac{1}{q^2(s,t)}\pd{}{s}q(s,t)\pd{^2}{s^2}F\big(q(s,t)\big) - \frac{1}{q^3(s,t)}\left(\pd{q}{s}(s,t)\right)^2\pd{}{s}F\big(q(s,t)\big)\right)\frac{1}{m}\notag
  \\&+ \Order\left(\frac{1}{m^2}\right).
\end{align}

