\begin{algorithm}[htb]
\caption{%
    Outline of proposed method using INT8 tensor cores. %
    The functions $\mathrm{trunc}(\cdot)$ and $\mathrm{round}(\cdot)$ round inputs into integers in round-towards-zero and round-to-nearest-even mode, and $E$ is all-ones matrix of appropriate size.
    $\mathbb{F}_{64}$ is a set of floating-point numbers in FP64.%
    \label{alg:Oz2-int8}%
}
\begin{algorithmic}[1]
\REQUIRE $A \in \mathbb{F}_{64}^{p \times q}$, $B \in \mathbb{F}_{64}^{q \times r}$, $m \in \mathbb{N}^s$, $s \in \mathbb{N}$

\item[\textbf{Convert FP64 to INT8:}]{\small
    \STATE\label{alg:Oz2-int8-1} Determine shift values $D \in \mathbb{F}_{64}^{p \times q}$ and $E \in \mathbb{F}_{64}^{q \times r}$
    \STATE\label{alg:Oz2-int8-2} $A' := \mathrm{trunc}(DA)$
    \hfill\COMMENT{$A' \in \mathbb{F}_{64}^{p \times q} \cap \mathbb{Z}^{p \times q}$}
    \STATE\label{alg:Oz2-int8-3} $B' := \mathrm{trunc}(BE)$
    \hfill\COMMENT{$B' \in \mathbb{F}_{64}^{q \times r} \cap \mathbb{Z}^{q \times r}$}
    \STATE $(a'_t)_{ij} := a'_{ij} \bmod m_t$ $(1 \le t \le s)$
    \STATE $(b'_t)_{ij} := b'_{ij} \bmod m_t$ $(1 \le t \le s)$

\item[\textbf{Matrix multiplication using INT8 TCs:}]
    \STATE $C'_t := A'_tB'_t$ $(1 \le t \le s)$

\item[\textbf{Convert matrix products into UINT8:}]
    \STATE $(c''_t)_{ij} := (c'_t)_{ij} - \lfloor (c'_t)_{ij} / m_t \rfloor m_t$ $(1 \le t \le s)$

\item[\textbf{Accumulate matrix products and inversely scale:}]
    \STATE\label{alg:Oz2-int8-8} $C''' := \sum_{t=1}^s C''_t\cdot My_t/m_t$
    \STATE\label{alg:Oz2-int8-9} $C''' := C''' \bmod M$
    \STATE $C := D^{-1}C'''E^{-1}$

\ENSURE $C \in \mathbb{F}_{64}^{p \times r}$ 
}\end{algorithmic}
\end{algorithm}

\subsection{Using FP64 for matrix multiplication}

We set prime numbers $m_1, m_2, \dots, m_s$ as
\begin{equation}
q m_i^2 \le 4 u^{-1}, \quad 1 \le i \le s.
\label{eq:double_bound}
\end{equation}
For $A'_t \in \mathbb{Z}^{p \times q}$ and $B'_t \in \mathbb{Z}^{q \times r}$ in \eqref{eq:modAB}, using~\eqref{eq:double_bound}, we have
\begin{equation}
(|A'_t| |B'_t|)_{ij} \le q \cdot \frac{1}{2}m_t \cdot \frac{1}{2}m_t \le u^{-1}, \quad u = 2^{-53}
\label{eq:FP64up}
\end{equation}
for all $(i,j)$ pairs and $1 \le t \le s$.
Hence, no rounding error occurs in $A'_i B'_i$ for $1 \le i \le s$ using GEMM in BLAS.
Similarly, considering~\eqref{eq:upper_bound}, $k_A + k_B$ is obtained as in~\eqref{eq:easy_k}.

Note that $m_i$ for $1\le i \le s$ does not need to be a prime number as long as they are pairwise coprime. 
However, unlike the case of INT8 TCs, when using FP64, they are simply chosen to be prime numbers to ensure that sufficiently large primes can be easily found.
For example, for $s=16$ and $n = 2^{10}$, we set $m_i$ from~\eqref{eq:double_bound} as
\begin{equation}\label{eq:fp64_law8}
    \begin{split}
        m &:= (4194301, 4194287, 4194277, 4194271, \\
        &\qquad 4194247, 4194217, 4194199, 4194191, \\
        &\qquad 4194187, 4194181, 4194173, 4194167, \\ 
        &\qquad 4194143, 4194137, 4194131, 4194107)^T \in \mathbb{N}^{16}.
    \end{split}
\end{equation}
The reason is that from~\eqref{eq:double_bound}, 
\[
m_i^2 \le \frac{2^{55}}{2^{10}}, 
\]
so that
\[
m_1 \approx 2^{22} \le \sqrt{2^{45}}.
\]
Note that $m$ in \eqref{eq:fp64_law8} satisfies
\[
\frac{m_{16}}{m_1} = \frac{4194107}{4194301} = 0.99995\dots\ .
\]
It is expected that
\[
M \approx s m_s.
\]
Because $ M $ is proportional to $s$, $k_A + k_B$ is also proportional to $s$.
In contrast, $m$ in \eqref{eq:int8_law8} satisfies
\[
\frac{m_{16}}{m_1} = \frac{191}{256} = 0.74\dots \ .
\]
The growth rate of $ M $ decreases as $ s $ increases.

Here, we deal with the application of FP64 to multi-word arithmetic.
Ozaki scheme II can be applied to any multi-word format; we assume that matrices are represented as an unevaluated sum of $v$ floating-point matrices such as
\begin{align}
A := \sum_{i=1}^v A^{(i)}, \quad B := \sum_{i=1}^v B^{(i)}, 
\label{eq:multi-word}
\end{align}
where for $1 \le i \le v-1$, 
\begin{align}
u |A^{(i)}| \ge |A^{(i+1)}|, \quad u |B^{(i)}| \ge |B^{(i+1)}|.
\label{eq:diff}
\end{align}
Again, we set diagonal matrices $D$ and $E$ such that
\[
C \approx D^{-1} A' B' E^{-1}, \quad A' \approx DA, \quad B' \approx BE.
\]
In Part 2-a, we compute
\begin{align*}
A_i' & \approx \left( D \sum_{i=1}^v A^{(i)} \right) \bmod {m_i}, \\
B_i' & \approx \left( \left( \sum_{i=1}^v B^{(i)} \right) E \right) \bmod {m_i},
\end{align*}
where $A'_i \in \mathbb{Z}^{p \times q}$ and $B'_i \in \mathbb{Z}^{q \times r}$ for all $i$.
The rest of the parts are the same as in the original.

Figure~\ref{fig:estimate} illustrates the behavior of the constant~$k := k_A = k_B$ as a function of the number of moduli~$s$.  
When $s$ is in the range of 16 to 20, the value of $k$ is approximately 160, which corresponds to a precision level equivalent to that obtained by triple-word arithmetic.  
As $s$ increases to the range of 21 to 25, $k$ increases to approximately 210, indicating a precision level comparable to that of quadruple-word arithmetic.

\begin{figure}[htb]\centering
\includegraphics[width=\hsize,page=5]{all_figures.pdf}
\caption{$k:=k_A = k_B$ from number of moduli~\eqref{eq:easy_k2} using FP64 for matrix multiplication}
\label{fig:estimate}
\end{figure}

Thus far, we have considered the product of two matrices; however, the same approach can be extended to the product of three or more matrices.
As an example, when dealing with the product of three matrices $A$, $B$, and $C$, we convert them to
\begin{align*}
DA & \approx A' \in \mathbb{Z}^{p \times q}_{k_A}, \quad 
BE \approx B' \in \mathbb{Z}^{q \times r}_{k_B}, \\
E^{-1}CF & \approx C' \in \mathbb{Z}^{r \times w}_{k_C}, 
% \label{eq:def_k}
\end{align*}
where the matrices $D$, $E$, and $F$ are diagonal, with diagonal entries that are powers of two, and $k_A$, $k_B$, and $k_C$ are determined to satisfy 
\[
qr 2^{k_A + k_B + k_C} < \frac{M}{2}.
\]
Then a similar procedure to that in \eqref{eq:upper_bound} and \eqref{eq:easy_k} can be applied.
If $k_A = k_B = k_C$, we set
\[
k_A = k_B = k_C := \left\lfloor \frac{1}{3}\log_2 \frac{M/2 - 1}{qr} \right\rfloor.
\]


\section{Numerical Experiment}\label{sec:Numerical Experiment}

In this section, we present considerations on both accuracy and computational performance based on the results of numerical experiments. 
We report experimental results on FP64 emulation using INT8 TCs, as well as on quad-word format emulation using FP64 on a CPU.
In both scenarios, we assume that the precision levels are equal, that is, $k_A = k_B$.

\subsection{Using INT8 TCs for FP64 emulation}
%==============================
% introduction
%==============================
All numerical experiments here were conducted on NVIDIA GH200 Grace Hopper Superchip and NVIDIA GeForce RTX 4090 GPU with NVIDIA CUDA Toolkit 12.8.61.
The tested methods will be denoted as follows:
\begin{itemize}
    \item DGEMM: cublasGemmEx with CUDA\_R\_64F
    \item OS II-fast-$s$:  Algorithm~\ref{alg:Oz2-int8} with $s$ moduli, employing the Cauchy--Schwarz inequality for the line~\ref{alg:Oz2-int8-1} to satisfy the condition~\eqref{eq:unique_condition} for outputs the unique result
    \item OS II-accu-$s$:  Algorithm~\ref{alg:Oz2-int8} with $s$ moduli, employing cublasGemmEx with CUDA\_R\_8I for the line~\ref{alg:Oz2-int8-1} to satisfy the condition~\eqref{eq:unique_condition} for outputs the unique result
    \item ozIMMU\_EF-$S$:  Ozaki scheme I (implemented by \cite{ozIMMU-uchino}) with $S$ slices
\end{itemize}
The test matrices $A \in \mathbb{F}^{p \times q}$ and $B \in \mathbb{F}^{q \times r}$ were generated as
\[
    a_{ij},b_{ij} \approx  (\mathrm{rand}-0.5)\cdot \exp(\phi\cdot \mathrm{randn}),
\]
where $\phi \in \mathbb{R}$ controls the exponent distribution, 
$\mathrm{rand} \in (0,1] \subset \mathbb{R}$ is a uniformly distributed random number and
$\mathrm{randn} \in \mathbb{R}$ is drawn from the standard normal distribution.
The non-negative constant $\phi$ specifies the tendency to difficulty in terms of the accuracy of matrix multiplication.
Empirically, the exponent distribution for matrix multiplication in HPL is comparable to $\phi = 0.5$.

%==============================
% accuracy
%==============================
Figure~\ref{fig:int8-accuracy} shows the accuracy of DGEMM, OS II-fast-$s$, and OS II-accu-$s$ for $s \in \{8,9,\dots,20\}$ on GH200.
We obtained similar results on RTX 4090.
For reference, ozIMMU\_EF-$S$ requires $S \ge 8$ to obtain comparable or slightly more accurate results than DGEMM (cf. numerical results by~\cite{ootomo2024dgemm} or \cite{Uchino2025}).
The initial estimation at the line~\ref{alg:Oz2-int8-1} of Algorithm~\ref{alg:Oz2-int8} strongly affects the truncation error at the lines~\ref{alg:Oz2-int8-2} and \ref{alg:Oz2-int8-3}.
Thus, OS II-accu returns more accurate results than OS II-fast due to less overestimation of the upper bound of $|A'||B'|$ in~\eqref{eq:unique_condition} by direct matrix multiplication using INT8 TCs.
For $\phi = 0.5$, both proposed methods require $14$ or $15$ moduli to achieve the accuracy of the DGEMM level.
OS II-accu can deal with larger $\phi$ to produce sufficiently accurate results.

